        @{ Offset = 8; Type = 'UDINT'; Value = 'restoredGroupToken' },
        @{ Offset = 12; Type = 'UDINT'; Value = 'restoredGroupGeneration' },
        @{ Offset = 16; Type = 'UDINT'; Value = 'restoredGroupSession' },
        @{ Offset = 20; Type = 'UDINT'; Value = 'restoredGroupSequence' },
        @{ Offset = 24; Type = 'UDINT'; Value = 'restoredGroupIdentitySize' },
        @{ Offset = 28; Type = 'DINT'; Value = 'restoredGroupCommand' },
        @{ Offset = 32; Type = 'DINT'; Value = 'restoredGroupReference' },
        @{ Offset = 36; Type = 'DINT'; Value = 'restoredGroupAdmissionMode' })
    if ($pointerWrites.Count -ne $expectedContextWrites.Count) {
        throw "$blocker helper context write count drifted."
    }
    for ($index = 0; $index -lt $expectedContextWrites.Count; $index++) {
        $expectedWrite = $expectedContextWrites[$index]
        if (([int]$pointerWrites[$index].Groups['Offset'].Value -ne
                $expectedWrite.Offset) -or
            ($pointerWrites[$index].Groups['Type'].Value -cne
                $expectedWrite.Type) -or
            ($pointerWrites[$index].Groups['Value'].Value -cne
                $expectedWrite.Value)) {
            throw "$blocker helper context offset/type/value order drifted."
        }
    }
    $validationGateIndex = $helperScan.LastIndexOf(
        'if preemptBankValid = FALSE then')
    $contextAliasIndex = $helperScan.IndexOf(
        'pContext := pRestoreContext$^USINT;',
        [StringComparison]::Ordinal)
    $firstContextWriteIndex = $pointerWrites[0].Index
    if (($validationGateIndex -lt 0) -or ($contextAliasIndex -lt 0) -or
        ($validationGateIndex -ge $contextAliasIndex) -or
        ($contextAliasIndex -ge $firstContextWriteIndex) -or
        ([regex]::Matches($helperScan, '\^').Count -ne 13)) {
        throw "$blocker helper success-only context publication order drifted."
    }
    $helperResultSequence = [string]::Join(
        '|',
        @([regex]::Matches(
                $helperScan,
                '(?is)\bResult\s*:=\s*(?<Value>[^;]+)\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Groups['Value'].Value,
                    '\s+',
                    '').ToLowerInvariant()
            }))
    if (($helperResultSequence -cne '-1|-3|0') -or
        ([regex]::Matches($helperScan, '(?i)\bRETURN\s*;').Count -ne 2)) {
        throw "$blocker helper Result/RETURN inventory drifted."
    }

    foreach ($methodContract in @(
            @{ Name = 'adapter'; Fragment = $adapter; LF = 29124; CRLF = 29922; Sha = '8855AEEAE9B617CEAC1D10C7CC4ADB7F4D0536D108592560CE0D39ACF344AFAC' },
            @{ Name = 'helper'; Fragment = $helper; LF = 21451; CRLF = 22046; Sha = 'AE6AD76007725544FBC57D8D60DF5C483CD3381149A1D14C424C96BCBEE0AF09' })) {
        if (-not $methodContract.Fragment.EndsWith(
                "`n",
                [StringComparison]::Ordinal)) {
            throw "$blocker $($methodContract.Name) canonical LF terminator drifted."
        }
        $dimensions =
            Get-LasalRollbackSplitByteDimensions -Text $methodContract.Fragment
        if (($dimensions.LF -ne $methodContract.LF) -or
            ($dimensions.CRLF -ne $methodContract.CRLF) -or
            ($dimensions.LF -ge 32768) -or
            ($dimensions.CRLF -ge 32768) -or
            ((Get-LasalRollbackSplitTextSha256 `
                    -Text $methodContract.Fragment) -cne
                $methodContract.Sha)) {
            throw "$blocker $($methodContract.Name) byte/hash ratchet drifted."
        }
    }
    $declarationDimensions =
        Get-LasalRollbackSplitByteDimensions -Text $declaration
    if (($declarationDimensions.LF -ne 207) -or
        ($declarationDimensions.CRLF -ne 216) -or
        ((Get-LasalRollbackSplitTextSha256 -Text $declaration) -cne
            '4BC23CE3F6FAC1F2E18CBC5D2AF7E2C27111834B8064E322AB5C6E66D0FD44E4')) {
        throw "$blocker generated private declaration byte/hash ratchet drifted."
    }
}

function Invoke-LasalAxisOwnershipRollbackSplitVerifierSelfTest {
    param(
        [Parameter(Mandatory = $true)]
        [string]$ControlServiceText,
        [Parameter(Mandatory = $true)]
        [string]$Owner
    )

    $lfControlServiceText =
        ConvertTo-LasalRollbackSplitLf -Text $ControlServiceText
    $crlfControlServiceText = $lfControlServiceText.Replace("`n", "`r`n")
    Assert-LasalAxisOwnershipRollbackSplitMutationFences `
        -ControlServiceText $ControlServiceText `
        -Owner "$Owner positive current"
    Assert-LasalAxisOwnershipRollbackSplitMutationFences `
        -ControlServiceText $lfControlServiceText `
        -Owner "$Owner positive LF checkout"
    Assert-LasalAxisOwnershipRollbackSplitMutationFences `
        -ControlServiceText $crlfControlServiceText `
        -Owner "$Owner positive CRLF IDE"
    $ControlServiceText = $lfControlServiceText
    $fragments = Get-LasalAxisOwnershipRollbackSplitFragments `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
    $fixtures = @(
        @{ Name = 'DeclarationMadeGlobal'; Target = 'Declaration'; Old = "`tFUNCTION ValidateAxisOwnershipRollbackPreemptBank"; New = "`tFUNCTION GLOBAL ValidateAxisOwnershipRollbackPreemptBank"; Expected = 'helper must retain one exact private declaration and implementation ABI' },
        @{ Name = 'HelperMadeGlobal'; Target = 'Helper'; Old = 'FUNCTION LMCControlCommandService::ValidateAxisOwnershipRollbackPreemptBank'; New = 'FUNCTION GLOBAL LMCControlCommandService::ValidateAxisOwnershipRollbackPreemptBank'; Expected = 'helper must retain one exact private declaration and implementation ABI' },
        @{ Name = 'HelperPointerAbiChanged'; Target = 'Helper'; Old = "`t`tpRestoreContext `t: ^void;"; New = "`t`tpRestoreContext `t: ^UDINT;"; Expected = 'helper must retain one exact private declaration and implementation ABI' },
        @{ Name = 'GuardNilInverted'; Target = 'Helper'; Old = 'pRestoreContext = NIL'; New = 'pRestoreContext <> NIL'; Expected = 'helper guard drifted' },
        @{ Name = 'GuardSizeChanged'; Target = 'Helper'; Old = 'RestoreContextSize <> 40'; New = 'RestoreContextSize <> 44'; Expected = 'helper guard drifted' },
        @{ Name = 'GuardMaskWeakened'; Target = 'Helper'; Old = 'ExpectedAxisMask > LMC_OWNER_ROBOT_AXIS_MASK'; New = 'ExpectedAxisMask > 0xFFFFFFFF'; Expected = 'helper guard drifted' },
        @{ Name = 'HelperValidationBypassed'; Target = 'Helper'; Old = "`tif preemptBankValid = FALSE then`r`n`t`tResult := -3;"; New = "`tif preemptBankValid = TRUE then`r`n`t`tResult := -3;"; Expected = 'mixed Group/non-safety rejection or fail fence drifted' },
        @{ Name = 'HelperMixedGroupAccepted'; Target = 'Helper'; Old = 'if restoredGroupFound & restoredNonSafetyFound then'; New = 'if restoredGroupFound & FALSE then'; Expected = 'mixed Group/non-safety rejection or fail fence drifted' },
        @{ Name = 'HelperGroupAggregationSuppressed'; Target = 'Helper'; Old = "`t`t`t`trestoredGroupActive := TRUE;"; New = "`t`t`t`trestoredGroupActive := FALSE;"; Expected = 'restored Group aggregation drifted' },
        @{ Name = 'HelperPersistentWriteAdded'; Target = 'Helper'; Old = "`tcontextActive := 0;"; New = "`tOwnershipState[0] := 1;`r`n`tcontextActive := 0;"; Expected = 'persistent mutation inventory drifted' },
        @{ Name = 'ContextWriteDropped'; Target = 'Helper'; Old = "`t(pContext + 36)^`$DINT := restoredGroupAdmissionMode;`r`n"; New = ''; Expected = 'helper context write count drifted' },
        @{ Name = 'ContextWriteReordered'; Target = 'Helper'; Old = "`t(pContext + 28)^`$DINT := restoredGroupCommand;`r`n`t(pContext + 32)^`$DINT := restoredGroupReference;`r`n"; New = "`t(pContext + 32)^`$DINT := restoredGroupReference;`r`n`t(pContext + 28)^`$DINT := restoredGroupCommand;`r`n"; Expected = 'helper context offset/type/value order drifted' },
        @{ Name = 'HelperForeignClientCall'; Target = 'Helper'; Old = "`tcontextActive := 0;"; New = "`tInputLatch.Probe();`r`n`tcontextActive := 0;"; Expected = 'helper read-only memory/client/clock contract drifted' },
        @{ Name = 'HelperFinalResultChanged'; Target = 'Helper'; Old = "`tResult := 0;`r`n`r`nEND_FUNCTION`r`n"; New = "`tResult := 1;`r`n`r`nEND_FUNCTION`r`n"; Expected = 'helper Result/RETURN inventory drifted' },
        @{ Name = 'AdapterHelperCallRenamed'; Target = 'Adapter'; Old = 'rollbackPreemptResult := ValidateAxisOwnershipRollbackPreemptBank('; New = 'rollbackPreemptResult := ValidateAxisOwnershipRollbackPreemptBankShadow('; Expected = 'exact adapter call, fail fence, or context slot map drifted' },
        @{ Name = 'AdapterContextSizeChanged'; Target = 'Adapter'; Old = 'RestoreContextSize:=40);'; New = 'RestoreContextSize:=36);'; Expected = 'exact adapter call, fail fence, or context slot map drifted' },
        @{ Name = 'AdapterFailureFenceBypassed'; Target = 'Adapter'; Old = "`t`t`tif rollbackPreemptResult <> 0 then`r`n`t`t`t`tResult := -3;"; New = "`t`t`tif rollbackPreemptResult <> 0 then`r`n`t`t`t`tResult := rollbackPreemptResult;"; Expected = 'exact adapter call, fail fence, or context slot map drifted' },
        @{ Name = 'AdapterSlotMapChanged'; Target = 'Adapter'; Old = 'restoredGroupAdmissionMode := restoreContext[9]$DINT;'; New = 'restoredGroupAdmissionMode := restoreContext[8]$DINT;'; Expected = 'exact adapter call, fail fence, or context slot map drifted' },
        @{ Name = 'AdapterLocalTypeChanged'; Target = 'Adapter'; Old = 'restoreContext : ARRAY [0..9] OF UDINT;'; New = 'restoreContext : ARRAY [0..9] OF DINT;'; Expected = 'adapter local name/type/order inventory drifted' },
        @{ Name = 'HelperLocalTypeChanged'; Target = 'Helper'; Old = 'pContext : ^USINT;'; New = 'pContext : ^DINT;'; Expected = 'helper local name/type/order inventory drifted' })
    if (($fixtures.Count -ne 20) -or
        (@($fixtures.Name | Select-Object -Unique).Count -ne 20)) {
        throw "$Owner rollback split self-test fixture inventory drifted."
    }

    $rejected = 0
    foreach ($fixture in $fixtures) {
        $targetText = $fragments.($fixture.Target)
        $fixtureOld = ConvertTo-LasalRollbackSplitLf -Text $fixture.Old
        $fixtureNew = ConvertTo-LasalRollbackSplitLf -Text $fixture.New
        $mutatedTarget = Replace-LasalRollbackSplitExactOne `
            -Text $targetText `
            -Old $fixtureOld `
            -New $fixtureNew `
            -Owner "$Owner fixture $($fixture.Name)"
        $mutatedControl = Replace-LasalRollbackSplitExactOne `
            -Text $ControlServiceText `
            -Old $targetText `
            -New $mutatedTarget `
            -Owner "$Owner fixture source $($fixture.Name)"
        $negativeOwner = "$Owner negative $($fixture.Name)"
        $didReject = $false
        try {
            Assert-LasalAxisOwnershipRollbackSplitMutationFences `
                -ControlServiceText $mutatedControl `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    "$negativeOwner axis ownership rollback split blocker:",
                    [StringComparison]::Ordinal) -or
                ($_.Exception.Message.IndexOf(
                    $fixture.Expected,
                    [StringComparison]::Ordinal) -lt 0) -or
                ($_.Exception.Message -match 'byte/hash ratchet drifted')) {
                throw
            }
            $didReject = $true
        }
        if (-not $didReject) {
            throw "$Owner rollback split negative fixture '$($fixture.Name)' was accepted."
        }
        $rejected++
    }
    return $rejected
}

function Assert-LasalAxisOwnershipPublishMutationFences {
    param(
        [string]$PublishBlock,
        [string]$ControlServiceText,
        [string]$Owner
    )

    $blocker = "$Owner axis ownership publish mutation blocker:"
    $controlScan = Get-LasalLexicalScanText $ControlServiceText
    $lexicalPublishMatches = [regex]::Matches(
        $controlScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if ($lexicalPublishMatches.Count -ne 1) {
        throw "$blocker lexical publish implementation scope drifted."
    }
    $scan = $lexicalPublishMatches[0].Value
    $rawPublishBlock = $ControlServiceText.Substring(
        $lexicalPublishMatches[0].Index,
        $lexicalPublishMatches[0].Length)
    if ([regex]::Matches(
            $rawPublishBlock,
            '"(?:[^"]|"")*"').Count -ne 0) {
        throw "$blocker raw publish implementation may not contain strings."
    }
    if ((Get-LasalLexicalScanText $PublishBlock).Trim() -cne
        $scan.Trim()) {
        throw "$blocker caller-supplied publish block does not match raw source."
    }
    Assert-Match $scan (
        '(?is)^\s*FUNCTION\s+GLOBAL\s+' +
        'LMCControlCommandService::PublishAxisOwnership\b.*?' +
        'END_FUNCTION\s*$') (
        "$blocker public publish implementation scope drifted.")

    $abiBodyPattern = (
        'VAR_INPUT\s*' +
        'AxisMask\s*:\s*UDINT\s*;\s*' +
        'AdmissionToken\s*:\s*UDINT\s*;\s*' +
        'OwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'ReportKind\s*:\s*UINT\s*;\s*' +
        'ReportValue0\s*:\s*UDINT\s*;\s*' +
        'ReportValue1\s*:\s*UDINT\s*;\s*' +
        'ObservationCycle\s*:\s*UDINT\s*;\s*' +
        'END_VAR\s*;?\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
    $classAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+PublishAxisOwnership\s*' +
         $abiBodyPattern + '\s*(?=FUNCTION\b)'))
    $implementationAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*' +
         $abiBodyPattern + '\s*(?=VAR\b)'))
    $classHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION\b[^\r\n:]*\b' +
         'PublishAxisOwnership\s*;?\s*$')).Count
    $implementationHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION\b[^\r\n]*\b' +
         'LMCControlCommandService::PublishAxisOwnership\s*;?\s*$')).Count
    $anyHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?is)(?<![A-Za-z0-9_])FUNCTION\b' +
         '(?:(?!\b(?:FUNCTION|VAR_INPUT|VAR_OUTPUT|VAR|' +
         'END_VAR|END_FUNCTION)\b|;).)*?' +
         '(?<![A-Za-z0-9_])PublishAxisOwnership' +
         '(?=[^A-Za-z0-9_])')).Count
    if (($anyHeaderCount -ne 2) -or
        ($classHeaderCount -ne 1) -or
        ($implementationHeaderCount -ne 1) -or
        ($classAbiMatches.Count -ne 1) -or
        ($implementationAbiMatches.Count -ne 1)) {
        throw (
            "$blocker public declaration and implementation must expose " +
            'the exact closed seven-input/one-output ABI.')
    }

    $classBlockMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bLMCControlCommandService\s*:\s*CLASS\b.*?' +
         '\bEND_CLASS\s*;'))
    if ($classBlockMatches.Count -ne 1) {
        throw "$blocker exact class declaration block is missing."
    }
    $classBlockEnd = $classBlockMatches[0].Index +
        $classBlockMatches[0].Length
    $classAbiEnd = $classAbiMatches[0].Index + $classAbiMatches[0].Length
    if (($classAbiMatches[0].Index -lt $classBlockMatches[0].Index) -or
        ($classAbiEnd -gt $classBlockEnd)) {
        throw "$blocker public declaration escaped the class block."
    }

    $classVariableRegionMatch = [regex]::Match(
        $controlScan,
        ('(?is)LMCControlCommandService\s*:\s*CLASS\b' +
         '(?<Body>.*?)\bFUNCTION\s+GLOBAL\s+HandleRequest\b'))
    if (-not $classVariableRegionMatch.Success) {
        throw "$blocker class variable region is missing."
    }
    foreach ($stateContract in @(
            @{ Name = 'ZeroHomeState'; Upper = 63 },
            @{ Name = 'OwnershipState'; Upper = 351 },
            @{ Name = 'OwnershipObserverState'; Upper = 107 },
            @{ Name = 'OwnershipLeaseState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedState'; Upper = 323 },
            @{ Name = 'OwnershipIdentityState'; Upper = 431 },
            @{ Name = 'OwnershipLeaseIdentityState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedIdentityState'; Upper = 431 })) {
        $statePattern = (
            '(?im)^\s*' + [regex]::Escape($stateContract.Name) +
            '\s*:\s*ARRAY\s*\[\s*0\s*\.\.\s*' +
            $stateContract.Upper + '\s*\]\s*OF\s*DINT\s*;\s*$')
        $wholeCount = [regex]::Matches(
            $controlScan,
            $statePattern).Count
        $memberCount = [regex]::Matches(
            $classVariableRegionMatch.Groups['Body'].Value,
            $statePattern).Count
        if (($wholeCount -ne 1) -or ($memberCount -ne 1)) {
            throw (
                "$blocker state member $($stateContract.Name) exact " +
                'type/bound/location drifted.')
        }
    }

    if ($scan -match '\^') {
        throw "$blocker publish may not expose or create a pointer alias."
    }
    if ($scan -match
            ('(?is)\b[A-Za-z_][A-Za-z0-9_]*\s*\.\s*' +
             '[A-Za-z_][A-Za-z0-9_]*|\b_gettime\s*\(')) {
        throw "$blocker publish may not resample a client or clock."
    }
    if ($controlScan -match '\r(?!\n)') {
        throw "$blocker bare carriage-return line endings are forbidden."
    }
    if ($controlScan -match '\\[^\S\r\n]*\r?\n') {
        throw "$blocker preprocessor-style line splicing is forbidden."
    }
    $expectedPragmas = @(
        'usingLtd _LMCAxis',
        'usingLtd _LMCRobotBase',
        'usingLtd LMCEcatInputLatch')
    $observedPragmas = @()
    $observedPragmaPositions = @()
    foreach ($hashLineMatch in [regex]::Matches(
            $controlScan,
            '(?im)^[^\S\r\n]*#[^\r\n]*\r?$')) {
        $hashLine = $hashLineMatch.Value
        $defineMatch = [regex]::Match(
            $hashLine,
            ('(?i)^[^\S\r\n]*#[^\S\r\n]*define[^\S\r\n]+' +
             '[A-Za-z_][A-Za-z0-9_]*(?:[^\r\n]*)\r?$'))
        if ($defineMatch.Success) {
            continue
        }
        $pragmaMatch = [regex]::Match(
            $hashLine,
            ('(?i)^[^\S\r\n]*#[^\S\r\n]*pragma[^\S\r\n]+' +
             '(?<Body>[^\r\n]*?)[^\S\r\n]*\r?$'))
        if ($pragmaMatch.Success -and
            ($expectedPragmas -ccontains
                $pragmaMatch.Groups['Body'].Value)) {
            $observedPragmas += $pragmaMatch.Groups['Body'].Value
            $observedPragmaPositions += $hashLineMatch.Index
            continue
        }
        throw (
            "$blocker unsupported or malformed preprocessor line " +
            "'$($hashLine.Trim())'.")
    }
    if (($observedPragmas.Count -ne 3) -or
        ([string]::Join('|', $observedPragmas) -cne
            [string]::Join('|', $expectedPragmas))) {
        throw "$blocker exact usingLtd pragma closure drifted."
    }

    $generatedTableHeaderMatch = [regex]::Match(
        $controlScan,
        ('(?im)^\s*FUNCTION\s+GLOBAL\s+TAB\s+' +
         'LMCControlCommandService::@CT_\s*$'))
    $firstCustomImplementationMatch = [regex]::Match(
        $controlScan,
        ('(?im)^\s*FUNCTION\s+' +
         'LMCControlCommandService::ReadAxisRebaseRequiredMask\s*$'))
    if ((-not $generatedTableHeaderMatch.Success) -or
        (-not $firstCustomImplementationMatch.Success) -or
        ($classAbiMatches[0].Index -ge $observedPragmaPositions[0]) -or
        ($observedPragmaPositions[-1] -ge
            $generatedTableHeaderMatch.Index)) {
        throw "$blocker declaration/usingLtd/generated-table order drifted."
    }

    $constantContracts = [ordered]@{}
    foreach ($constantContract in @(
            'LMC_AXIS_REBASE_BARRIER_ENABLED=TRUE',
            'LMC_HOME_ENGINE_FINALIZE=3',
            'LMC_HOME_ENGINE_TERMINAL=4',
            'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED=0x00000010',
            'LMC_HOME_FLAG_OWNER_FINALIZE_INTENT=0x00000008',
            'LMC_HOME_FLAG_PREEMPTION_CLEANUP=0x00000080',
            'LMC_HOME_FLAG_TERMINAL_PUBLISHED=0x00000020',
            'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY=2',
            'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER=3',
            'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD=5',
            'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON=4',
            'LMC_HOME_OWNER_RECEIPT_COMPLETE=6',
            'LMC_HOME_OWNER_RECEIPT_MAGIC=0x484F4D50',
            'LMC_HOME_OWNER_RECEIPT_PREPARED=1',
            'LMC_HOME_RECORD_ABORTED=4',
            'LMC_HOME_RECORD_FAILED=3',
            'LMC_HOME_RECORD_MAGIC=0x4C4D4348',
            'LMC_HOME_RECORD_SUCCEEDED=2',
            'LMC_OWNER_ADMISSION_LIFECYCLE=4',
            'LMC_OWNER_ADMISSION_ORDINARY=1',
            'LMC_OWNER_ADMISSION_SAFETY=2',
            'LMC_OWNER_AXIS_COUNT=9',
            'LMC_OWNER_AXIS_RECORD_MAGIC=0x4F574E00',
            'LMC_OWNER_AXIS_STRIDE=36',
            'LMC_OWNER_GLOBAL_SLOTS=28',
            'LMC_OWNER_IDENTITY_AXIS_HEADER_BASE=314',
            'LMC_OWNER_IDENTITY_AXIS_HEADER_STRIDE=12',
            'LMC_OWNER_IDENTITY_AXIS_MAGIC=0x49444100',
            'LMC_OWNER_IDENTITY_GROUP_HEADER_BASE=422',
            'LMC_OWNER_IDENTITY_GROUP_MAGIC=0x49444752',
            'LMC_OWNER_IDENTITY_PREFIX_BYTES=0x00000040',
            'LMC_OWNER_IDENTITY_SUFFIX_BYTES=1256',
            'LMC_OWNER_IDENTITY_SUFFIX_DINTS=314',
            'LMC_OWNER_IDENTITY_VERSION=1',
            'LMC_OWNER_KIND_DIRECT=1',
            'LMC_OWNER_KIND_DS402_HOME=4',
            'LMC_OWNER_KIND_ENCODER=5',
            'LMC_OWNER_KIND_GROUP=2',
            'LMC_OWNER_KIND_LMC_HOME=3',
            'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE=314',
            'LMC_OWNER_LEASE_IDENTITY_MAGIC=0x49444C53',
            'LMC_OWNER_OBSERVER_EVIDENCE_CLEAR_MASK=0xFFFFFFFC',
            'LMC_OWNER_OBSERVER_FORCE_QUARANTINE=0x00000020',
            'LMC_OWNER_OBSERVER_MAGIC=0x4F425300',
            'LMC_OWNER_OBSERVER_STRIDE=12',
            'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE=0x00010000',
            'LMC_OWNER_PREEMPT_HEADER_BASE=422',
            'LMC_OWNER_PREEMPT_IDENTITY_MAGIC=0x49445052',
            'LMC_OWNER_PROFILE_AXIS_MASK=0x0000000F',
            'LMC_OWNER_REPORT_DISPATCH=1',
            'LMC_OWNER_REPORT_QUARANTINE=4',
            'LMC_OWNER_REPORT_SAFETY_PREEMPT=5',
            'LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE=3',
            'LMC_OWNER_REPORT_TERMINAL_SUCCESS=2',
            'LMC_OWNER_RESOURCE_AXIS=1',
            'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE=4',
            'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE=3',
            'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE=2',
            'LMC_OWNER_ROBOT_AXIS_MASK=0x000001FF',
            'LMC_OWNER_STATE_DS402_HOME_ACTIVE=6',
            'LMC_OWNER_STATE_GROUP_LEASE=3',
            'LMC_OWNER_STATE_LMC_HOME_ACTIVE=5',
            'LMC_OWNER_STATE_QUARANTINED=11',
            'LMC_OWNER_STATE_RESERVED=1',
            'LMC_OWNER_STATE_SAFETY_PREEMPTING=10',
            'LMC_OWNER_STATE_TW20_DRAINING=9',
            'LMC_OWNER_STATE_TW20_QUEUED=7',
            'LMC_OWNER_STATE_TW20_RUNNING=8')) {
        $constantParts = $constantContract.Split('=', 2)
        $constantContracts[$constantParts[0]] = $constantParts[1]
    }

    $publishIdentifiers = [Collections.Generic.HashSet[string]]::new(
        [StringComparer]::OrdinalIgnoreCase)
    foreach ($identifierMatch in [regex]::Matches(
            $scan,
            '\b[A-Za-z_][A-Za-z0-9_]*\b')) {
        [void]$publishIdentifiers.Add($identifierMatch.Value)
    }
    $allowedConstantNames = [Collections.Generic.HashSet[string]]::new(
        [StringComparer]::OrdinalIgnoreCase)
    foreach ($constantName in $constantContracts.Keys) {
        [void]$allowedConstantNames.Add($constantName)
    }
    $macroDefinitionCount = @{}
    $macroDefinitionValues = @{}
    $macroMatches = [regex]::Matches(
            $controlScan,
            ('(?im)^[^\S\r\n]*#[^\S\r\n]*define[^\S\r\n]+' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)' +
             '(?<Value>[^\r\n]*)\r?$'))
    $allMacroInventory = @()
    foreach ($macroMatch in $macroMatches) {
        $macroName = $macroMatch.Groups['Name'].Value
        $macroValue = $macroMatch.Groups['Value'].Value.Trim()
        $allMacroInventory += (
            $macroName.ToLowerInvariant() + '=' +
            [regex]::Replace(
                $macroValue,
                '\s+',
                ' ').ToLowerInvariant())
        if (-not $macroDefinitionCount.ContainsKey($macroName)) {
            $macroDefinitionCount[$macroName] = 0
            $macroDefinitionValues[$macroName] = @()
        }
        $macroDefinitionCount[$macroName]++
        $macroDefinitionValues[$macroName] += $macroValue
        if ($publishIdentifiers.Contains($macroName) -and
            (-not $allowedConstantNames.Contains($macroName))) {
            throw (
                "$blocker executable identifier '$macroName' may not be " +
                'macro-defined outside the frozen constant closure.')
        }
    }
    $joinedMacroInventory = [string]::Join('|', $allMacroInventory)
    $macroInventorySha = [Security.Cryptography.SHA256]::Create()
    try {
        $macroInventoryBytes = [Text.Encoding]::UTF8.GetBytes(
            $joinedMacroInventory)
        $macroInventorySha256 = (
            [BitConverter]::ToString(
                $macroInventorySha.ComputeHash($macroInventoryBytes))
        ).Replace('-', '')
    }
    finally {
        $macroInventorySha.Dispose()
    }
    if (($allMacroInventory.Count -ne 165) -or
        ($joinedMacroInventory.Length -ne 6175) -or
        ($macroInventorySha256 -cne
            '67348A046E35A28C733ACB27B811B4C88EB6402BEC697CE22ADAF726EC6A2928')) {
        throw (
            "$blocker whole-control macro inventory drifted " +
            "($($allMacroInventory.Count)/165, " +
            "$($joinedMacroInventory.Length)/6175, $macroInventorySha256).")
    }
    if (($macroMatches.Count -eq 0) -or
        ($macroMatches[-1].Index -ge
            $firstCustomImplementationMatch.Index)) {
        throw "$blocker macro definitions escaped the pre-implementation region."
    }
    if (($lexicalPublishMatches[0].Index -le
            $firstCustomImplementationMatch.Index) -or
        ($lexicalPublishMatches[0].Index -le $macroMatches[-1].Index)) {
        throw "$blocker qualified publish implementation moved before its prerequisites."
    }
    foreach ($constant in $constantContracts.GetEnumerator()) {
        $definitionCount = if (
            $macroDefinitionCount.ContainsKey($constant.Key)) {
            $macroDefinitionCount[$constant.Key]
        }
        else {
            0
        }
        $definitionValue = if ($definitionCount -eq 1) {
            $macroDefinitionValues[$constant.Key][0]
        }
        else {
            ''
        }
        if (($definitionCount -ne 1) -or
            ($definitionValue -cne $constant.Value)) {
            throw "$blocker constant $($constant.Key) drifted or was redefined."
        }
    }

    $localVarMatch = [regex]::Match(
        $scan,
        ('(?is)VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*' +
         'VAR\s*(?<Body>.*?)\s*END_VAR'))
    if (-not $localVarMatch.Success) {
        throw "$blocker local variable block is missing."
    }
    $localInventory = @(
        [regex]::Matches(
            $localVarMatch.Groups['Body'].Value,
            ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
             '(?<Type>[^;]+)\s*;')) |
            ForEach-Object {
                ($_.Groups['Name'].Value + ':' +
                 [regex]::Replace($_.Groups['Type'].Value, '\s+', '')
                ).ToLowerInvariant()
            })
    $joinedLocals = [string]::Join('|', $localInventory)
    $localSha = [Security.Cryptography.SHA256]::Create()
    try {
        $localBytes = [Text.Encoding]::UTF8.GetBytes($joinedLocals)
        $localSha256 = (
            [BitConverter]::ToString($localSha.ComputeHash($localBytes))
        ).Replace('-', '')
    }
    finally {
        $localSha.Dispose()
    }
    if (($localInventory.Count -ne 93) -or
        ($joinedLocals.Length -ne 2162) -or
        ($localSha256 -cne
            'FF2AD6EE2FADB9C3C42C74D1BA671D477BAF7409907E99BBF1F7A021D24A19E5')) {
        throw (
            "$blocker local variable inventory drifted " +
            "($($localInventory.Count)/93, " +
            "$($joinedLocals.Length)/2162, $localSha256).")
    }

    Assert-Match $scan (
        '(?is)END_VAR\s*' +
        'Result\s*:=\s*-1\s*;\s*' +
        'if\s*\(AxisMask\s*=\s*0\)\s*\|\s*' +
        '\(AxisMask\s*>\s*LMC_OWNER_ROBOT_AXIS_MASK\)\s*\|\s*' +
        '\(AdmissionToken\s*=\s*0\)\s*\|\s*' +
        '\(OwnerGeneration\s*=\s*0\)\s*\|\s*' +
        '\(ReportKind\s*<\s*LMC_OWNER_REPORT_DISPATCH\)\s*\|\s*' +
        '\(ReportKind\s*>\s*LMC_OWNER_REPORT_SAFETY_PREEMPT\)\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'if\s+ZeroHomeState\[60\]\$UDINT\s*=\s*' +
        'LMC_HOME_OWNER_RECEIPT_MAGIC\s+then') (
        "$blocker input guard or durable Home receipt entry drifted.")

    $ignoredCallNames = @(
        'and', 'else', 'elsif', 'if', 'not', 'or', 'then')
    $expectedCallHistogram = [ordered]@{
        '_memcmp' = 3
        '_memcpy' = 2
        '_memset' = 18
        'sizeof' = 4
        'to_dint' = 8
        'to_udint' = 48
        'updateaxisrebaserequiredstate' = 1
    }
    $actualCallHistogram = [ordered]@{}
    foreach ($callMatch in [regex]::Matches(
            $scan,
            ('(?i)(?<![A-Za-z0-9_])' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*\('))) {
        $callName = $callMatch.Groups['Name'].Value.ToLowerInvariant()
        if ($ignoredCallNames -contains $callName) {
            continue
        }
        if (-not $expectedCallHistogram.Contains($callName)) {
            throw "$blocker unsupported call '$callName'."
        }
        if (-not $actualCallHistogram.Contains($callName)) {
            $actualCallHistogram[$callName] = 0
        }
        $actualCallHistogram[$callName]++
    }
    foreach ($callName in $expectedCallHistogram.Keys) {
        $actualCount = if ($actualCallHistogram.Contains($callName)) {
            $actualCallHistogram[$callName]
        }
        else {
            0
        }
        if ($actualCount -ne $expectedCallHistogram[$callName]) {
            throw (
                "$blocker call '$callName' count is $actualCount, expected " +
                "$($expectedCallHistogram[$callName]).")
        }
    }

    $persistentMutationPattern = (
        '(?is)(?:' +
        '\b(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*' +
        '\[[^\]]+\]\s*(?:\$[A-Za-z_][A-Za-z0-9_]*\s*)?' +
        '(?::|\+|-|\*|/|and|or|xor)\s*=\s*[^;]+;' +
        '|' +
        '\b_memset\s*\(\s*dest\s*:=\s*' +
        '#(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*\[.*?\)\s*;' +
        '|' +
        '\b_memcpy\s*\(\s*ptr1\s*:=\s*' +
        '#(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*\[.*?\)\s*;' +
        ')')
    $persistentMutations = [regex]::Matches(
        $scan,
        $persistentMutationPattern)
    $normalizedMutations = @(
        foreach ($mutation in $persistentMutations) {
            [regex]::Replace(
                $mutation.Value,
                '\s+',
                '').ToLowerInvariant()
        })
    $joinedMutations = [string]::Join('|', $normalizedMutations)
    $mutationSha = [Security.Cryptography.SHA256]::Create()
    try {
        $mutationBytes = [Text.Encoding]::UTF8.GetBytes($joinedMutations)
        $mutationSha256 = (
            [BitConverter]::ToString(
                $mutationSha.ComputeHash($mutationBytes))
        ).Replace('-', '')
    }
    finally {
        $mutationSha.Dispose()
    }
    if (($persistentMutations.Count -ne 83) -or
        ($joinedMutations.Length -ne 4848) -or
        ($mutationSha256 -cne
            '86AC17C8D876F87826F98F9EE160F4711E02A6BC82327E07CE1D75C064F53B99')) {
        throw (
            "$blocker persistent mutation inventory/order drifted " +
            "($($persistentMutations.Count)/83, " +
            "$($joinedMutations.Length)/4848, $mutationSha256).")
    }
    if (($normalizedMutations[0] -cne 'ownershipstate[24]:=1;') -or
        ($normalizedMutations[-1] -cne 'ownershipstate[15]:=0;')) {
        throw "$blocker first corruption latch or final singleton write drifted."
    }

    $resultSequence = [string]::Join(
        '|',
        @([regex]::Matches(
                $scan,
                '(?is)\bResult\s*:=\s*(?<Value>[^;]+)\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Groups['Value'].Value,
                    '\s+',
                    '').ToLowerInvariant()
            }))
    $expectedResultSequence = (
        '-1|-3|-3|-3|0|-3|rebaseupdateresult|1|-3|-2|-3|-2|-2|' +
        '-3|-2|-3|-3|-3|-3|-3|-3|-3|0|0')
    if ($resultSequence -cne $expectedResultSequence) {
        throw "$blocker Result value/count/order inventory drifted."
    }
    $controlFlowTokens = @(
        [regex]::Matches(
            $scan,
            '(?is)\bResult\s*:=\s*[^;]+\s*;|\bRETURN\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $controlFlowInventory = [string]::Join('|', $controlFlowTokens)
    $controlFlowSha = [Security.Cryptography.SHA256]::Create()
    try {
        $controlFlowBytes = [Text.Encoding]::UTF8.GetBytes(
            $controlFlowInventory)
        $controlFlowSha256 = (
            [BitConverter]::ToString(
                $controlFlowSha.ComputeHash($controlFlowBytes))
        ).Replace('-', '')
    }
    finally {
        $controlFlowSha.Dispose()
    }
    if (($controlFlowTokens.Count -ne 47) -or
        ($controlFlowInventory.Length -ne 483) -or
        ($controlFlowSha256 -cne
            '92C5659611A0A4F3B7086490BD2623B2370230D477DEBC76F267D5F9428F6CBD')) {
        throw (
            "$blocker Result/RETURN control-flow inventory drifted " +
            "($($controlFlowTokens.Count)/47, " +
            "$($controlFlowInventory.Length)/483, $controlFlowSha256).")
    }

    Assert-Match $scan (
        '(?is)if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY\s*;\s*' +
        'OwnershipIdentityState\[identityHeaderBase\]\s*:=\s*0\s*;.*?' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER\s*;.*?' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s*;.*?' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s*;.*?' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_COMPLETE\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*35\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)') (
        "$blocker durable Home cleanup phase order drifted.")
    Assert-Match $scan (
        '(?is)ZeroHomeState\[60\]\s*:=\s*0\s*;\s*' +
        'ZeroHomeState\[61\]\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_PREPARED\s*;\s*' +
        'ZeroHomeState\[62\]\s*:=\s*0\s*;\s*' +
        'ZeroHomeState\[63\]\$UDINT\s*:=\s*' +
        'ZeroHomeState\[33\]\$UDINT\s*;\s*' +
        'ZeroHomeState\[60\]\$UDINT\s*:=\s*' +
        'LMC_HOME_OWNER_RECEIPT_MAGIC\s*;\s*' +
        'Result\s*:=\s*0\s*;\s*RETURN\s*;') (
        "$blocker first durable Home receipt is not magic-last.")
    Assert-Match $scan (
        '(?is)if\s+LMC_AXIS_REBASE_BARRIER_ENABLED\s*&\s*' +
        '\(ReportKind\s*=\s*LMC_OWNER_REPORT_TERMINAL_SUCCESS\).*?' +
        'rebaseUpdateResult\s*:=\s*UpdateAxisRebaseRequiredState\(\s*' +
        'SetAxisMask:=0\s*,\s*ClearAxisMask:=AxisMask\s*\)\s*;\s*' +
        'if\s+rebaseUpdateResult\s*<>\s*0\s+then\s*' +
        'Result\s*:=\s*rebaseUpdateResult\s*;\s*RETURN\s*;') (
        "$blocker post-cleanup rebase-barrier clear call drifted.")

    $lastPreemptGate = $scan.LastIndexOf(
        'if preemptBankValid = FALSE then')
    $lastLeaseGate = $scan.LastIndexOf('if leaseValid = FALSE then')
    $lastRetainGate = $scan.LastIndexOf('if retainLeaseValid = FALSE then')
    $firstReceiptPublish = $scan.LastIndexOf('ZeroHomeState[60] := 0;')
    $firstGeneralMutation = $scan.IndexOf(
        'OwnershipState[recordBase + 9]$UDINT := ObservationCycle;')
    if (($lastPreemptGate -lt 0) -or ($lastLeaseGate -lt 0) -or
        ($lastRetainGate -lt 0) -or ($firstReceiptPublish -lt 0) -or
        ($firstGeneralMutation -lt 0) -or
        ($lastPreemptGate -ge $firstReceiptPublish) -or
        ($lastLeaseGate -ge $firstReceiptPublish) -or
        ($lastRetainGate -ge $firstReceiptPublish) -or
        ($firstReceiptPublish -ge $firstGeneralMutation)) {
        throw "$blocker terminal validation is not complete before publication."
    }

    Assert-Match $scan (
        '(?is)if\s+\(ReportKind\s*=\s*' +
        'LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*&\s*' +
        '\(forceQuarantine\s*=\s*FALSE\)\s+then\s*' +
        'if\s+preemptRootValid\s+then\s*' +
        'OwnershipPreemptedIdentityState\[\s*' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\]\s*:=\s*0\s*;.*?' +
        'if\s+restoreLease\s*\|\s*destroyBanks\s+then\s*' +
        'OwnershipLeaseIdentityState\[\s*' +
        'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\]\s*:=\s*0\s*;') (
        "$blocker bank destruction escaped exact terminal success.")
    Assert-Match $scan (
        '(?is)if\s+\(ReportKind\s*=\s*' +
        'LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*\|\s*' +
        '\(ReportKind\s*=\s*LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE\)\s+then.*?' +
        'if\s+\(OwnershipState\[7\]\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(OwnershipState\[8\]\$UDINT\s*=\s*OwnerGeneration\)\s+then\s*' +
        'OwnershipState\[7\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[8\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[9\]\s*:=\s*0\s*;\s*end_if\s*;\s*' +
        'if\s+\(OwnershipState\[10\]\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(OwnershipState\[11\]\$UDINT\s*=\s*OwnerGeneration\)\s+then\s*' +
        'OwnershipState\[10\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[11\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[12\]\s*:=\s*0\s*;\s*end_if\s*;\s*' +
        'if\s+\(OwnershipState\[13\]\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(OwnershipState\[14\]\$UDINT\s*=\s*OwnerGeneration\)\s+then\s*' +
        'OwnershipState\[13\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[14\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[15\]\s*:=\s*0\s*;\s*end_if\s*;\s*end_if\s*;\s*' +
        'Result\s*:=\s*0\s*;\s*END_FUNCTION\s*$') (
        "$blocker singleton clear gates or final Result drifted.")

    # Keep this final so targeted assertions explain known drift first.
    $semanticTokens = [regex]::Replace(
        $scan,
        '\s+',
        '').ToLowerInvariant()
    $semanticSha = [Security.Cryptography.SHA256]::Create()
    try {
        $semanticBytes = [Text.Encoding]::UTF8.GetBytes($semanticTokens)
        $semanticSha256 = (
            [BitConverter]::ToString(
                $semanticSha.ComputeHash($semanticBytes))
        ).Replace('-', '')
    }
    finally {
        $semanticSha.Dispose()
    }
    if (($semanticTokens.Length -ne 50046) -or
        ($semanticSha256 -cne
            'FB6B7BE724A2AA4091004890B40B2A11E9AF35471C23CCE9738CDABA9CDDDE16')) {
        throw (
            "$blocker normalized semantic token inventory drifted " +
            "($($semanticTokens.Length)/50046, $semanticSha256).")
    }

    # Hash lexical tokens with explicit boundaries. The whitespace-free hash
    # above is useful for compact drift diagnostics but cannot distinguish an
    # identifier from two identifiers separated by whitespace or a comment.
    $lexicalTokens = @(
        [regex]::Matches(
            $scan,
            ('(?i)0x[0-9a-f]+|[A-Za-z_][A-Za-z0-9_]*|\d+|' +
             ':=|<>|<=|>=|\+=|-=|\*=|/=|[^\s]')) |
            ForEach-Object { $_.Value.ToLowerInvariant() })
    $lexicalInventory = [string]::Join('|', $lexicalTokens)
    $lexicalSha = [Security.Cryptography.SHA256]::Create()
    try {
        $lexicalBytes = [Text.Encoding]::UTF8.GetBytes($lexicalInventory)
        $lexicalSha256 = (
            [BitConverter]::ToString(
                $lexicalSha.ComputeHash($lexicalBytes))
        ).Replace('-', '')
    }
    finally {
        $lexicalSha.Dispose()
    }
    if (($lexicalTokens.Count -ne 9672) -or
        ($lexicalInventory.Length -ne 59717) -or
        ($lexicalSha256 -cne
            '59B54CCFBA25322103DA85FDF0C92C9BC8EEAA28026A2935B35C989CABEF785A')) {
        throw (
            "$blocker lexical token boundary inventory drifted " +
            "($($lexicalTokens.Count)/9672, " +
            "$($lexicalInventory.Length)/59717, $lexicalSha256).")
    }
}

function Invoke-LasalAxisOwnershipPublishVerifierSelfTest {
    param(
        [string]$ControlServiceText,
        [string]$Owner
    )

    $fixtureSpecs = @(
        @{
            Name = 'BareCarriageReturnPragmaAdded'
            Pattern = '\A'
            Replacement = "`r#pragma pack(1)`r`n"
        },
        @{
            Name = 'ImplementationRenamed'
            Pattern = (
                '(?im)^(\s*FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::)PublishAxisOwnership\s*$')
            Replacement = '${1}PublishAxisOwnershipShadow'
        },
        @{
            Name = 'DuplicatePrivateImplementationAdded'
            Pattern = (
                '(?ims)^(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\s*$.*?' +
                '^END_FUNCTION\s*$)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                'FUNCTION LMCControlCommandService::PublishAxisOwnership' +
                [Environment]::NewLine + "`tVAR_OUTPUT" +
                [Environment]::NewLine + "`t`tResult : DINT;" +
                [Environment]::NewLine + "`tEND_VAR" +
                [Environment]::NewLine + "`tResult := 0;" +
                [Environment]::NewLine + 'END_FUNCTION')
        },
        @{
            Name = 'ClassAbiOwnerGenerationTypeChanged'
            Pattern = (
