                'VAR_INPUT.*?\bReportKind\s*:\s*)UINT')
            Replacement = '${1}UDINT'
        },
        @{
            Name = 'ClassAbiTrailingInputAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+PublishAxisOwnership\s*' +
                'VAR_INPUT.*?\bObservationCycle\s*:\s*UDINT\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`t`tUnexpectedInput : UDINT;")
        },
        @{
            Name = 'ImplementationAbiTrailingInputAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\s*' +
                'VAR_INPUT.*?\bObservationCycle\s*:\s*UDINT\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`t`tUnexpectedInput : UDINT;")
        },
        @{
