            Pattern = (
                '(?im)^(\s*FUNCTION\s+GLOBAL\s+' +
                'PublishAxisOwnership\s*)$')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tFUNCTION GLOBAL PublishAxisOwnership" +
                [Environment]::NewLine +
                "`t`tVAR_INPUT" + [Environment]::NewLine +
                "`t`t`tAxisMask : DINT;" + [Environment]::NewLine +
                "`t`tEND_VAR")
        },
        @{
            Name = 'DuplicatePrivateClassDeclarationAdded'
            Pattern = (
                '(?im)^(\s*FUNCTION\s+GLOBAL\s+' +
                'PublishAxisOwnership\s*)$')
            Replacement = (
                'FUNCTION PublishAxisOwnership;' +
                [Environment]::NewLine + '${1}')
        },
        @{
            Name = 'InlineDuplicateClassHeaderAdded'
            Pattern = (
                '(?im)^(\s*FUNCTION\s+GLOBAL\s+' +
                'RollbackAxisOwnership\s*)$')
            Replacement = '${1} FUNCTION PublishAxisOwnership;'
        },
        @{
            Name = 'PointerAliasLocalAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bVAR\s*)(axisIndex\s*:\s*DINT\s*;)')
            Replacement = (
                '${1}' + 'pAlias : ^DINT;' + [Environment]::NewLine +
                "`t`t${2}")
        },
        @{
            Name = 'ClientResampleCallAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tInputLatch.Read();")
        },
        @{
            Name = 'ClockResampleCallAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`thomeReceiptIndex := TO_DINT(_gettime());")
        },
        @{
            Name = 'DuplicateRebaseCallAdded'
