        },
        @{
            Name = 'EarlyReturnAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = '${1}' + [Environment]::NewLine + "`tRETURN;"
        },
        @{
            Name = 'BareStringTokenAdded'
            Pattern = (
