                '.*?^#define\s+' +
                'LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\s+3\s*$)' +
                '(?<Middle>.*?^FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\s*$.*?' +
                '^END_FUNCTION\s*$)')
            Replacement = (
                '${Middle}' + [Environment]::NewLine + '${Suffix}')
        },
        @{
            Name = 'SpacedConstantRedefined'
            Pattern = (
                '(?im)^(\s*#define\s+LMC_OWNER_AXIS_STRIDE\s+36\s*)$')
            Replacement = (
