            Replacement = '${1}35'
        },
        @{
            Name = 'ReceiptCompletePhaseChanged'
            Pattern = (
                '(?im)^(\s*#define\s+' +
                'LMC_HOME_OWNER_RECEIPT_COMPLETE\s+)6\s*$')
            Replacement = '${1}7'
        },
        @{
            Name = 'ReportDomainUpperBoundChanged'
            Pattern = (
                '(?im)^(\s*#define\s+' +
                'LMC_OWNER_REPORT_SAFETY_PREEMPT\s+)5\s*$')
            Replacement = '${1}6'
        },
        @{
            Name = 'LocalTypeChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bhomeReceiptPhase\s*:\s*)DINT')
            Replacement = '${1}UDINT'
        },
        @{
            Name = 'IdentifierSplitByBlockComment'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bpreemptLmc)(Found\s*:=\s*FALSE\s*;)')
            Replacement = '${1}(* split token *)${2}'
        },
        @{
            Name = 'IdentifierSplitByLineComment'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bpreemptDs402)(Found\s*:=\s*FALSE\s*;)')
            Replacement = (
                '${1}// split token' + [Environment]::NewLine + '${2}')
        },
        @{
            Name = 'IdentifierSplitByWhitespace'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bpreemptEncoder)(Found\s*:=\s*FALSE\s*;)')
            Replacement = '${1} ${2}'
        },
        @{
            Name = 'EarlyOwnershipWriteAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tOwnershipState[24] := 1;")
        },
        @{
            Name = 'EarlyZeroHomeWriteAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tZeroHomeState[61] := 0;")
        },
        @{
            Name = 'ReceiptCallGenerationMappedToToken'
            Pattern = (
                '(?is)(homeReceiptCallMatches\s*:=.*?' +
                'ZeroHomeState\[35\]\$UDINT\s*=\s*)OwnerGeneration')
            Replacement = '${1}AdmissionToken'
        },
        @{
            Name = 'ReceiptExactGenerationMappedToToken'
            Pattern = (
                '(?is)(homeReceiptExact\s*:=.*?' +
                'ZeroHomeState\[35\]\$UDINT\s*=\s*)OwnerGeneration')
            Replacement = '${1}AdmissionToken'
        },
        @{
            Name = 'ReceiptSurfaceValidationBypass'
            Pattern = (
                '(?is)(if\s+homeReceiptSurfaceValid\s*=\s*)FALSE' +
                '(\s+then\s*OwnershipState\[24\])')
            Replacement = '${1}TRUE${2}'
        },
        @{
            Name = 'IdentityPhaseAdvancedEarly'
            Pattern = (
                '(?is)(if\s+homeReceiptPhase\s*<=\s*' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY\s+then\s*' +
                'ZeroHomeState\[61\]\s*:=\s*)' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY')
            Replacement = '${1}LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER'
        },
        @{
            Name = 'ObserverPhaseAdvancedEarly'
            Pattern = (
                '(?is)(if\s+homeReceiptPhase\s*<=\s*' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER\s+then\s*' +
                'ZeroHomeState\[61\]\s*:=\s*)' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER')
            Replacement = '${1}LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON'
        },
        @{
            Name = 'SingletonPhaseAdvancedEarly'
            Pattern = (
                '(?is)(if\s+homeReceiptPhase\s*<=\s*' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s+then\s*' +
                'ZeroHomeState\[61\]\s*:=\s*)' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON')
            Replacement = '${1}LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD'
        },
        @{
            Name = 'RecordPhaseMarkedCompleteEarly'
            Pattern = (
                '(?is)(if\s+homeReceiptPhase\s*<=\s*' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s+then\s*' +
                'ZeroHomeState\[61\]\s*:=\s*)' +
                'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD')
            Replacement = '${1}LMC_HOME_OWNER_RECEIPT_COMPLETE'
        },
        @{
            Name = 'RecordMagicPublishedBeforeComplete'
            Pattern = (
                '(?is)(OwnershipState\[recordBase\]\s*:=\s*axisIndex\s*;)\s*' +
                '(ZeroHomeState\[61\]\s*:=\s*' +
                'LMC_HOME_OWNER_RECEIPT_COMPLETE\s*;)\s*' +
                '(OwnershipState\[recordBase\s*\+\s*35\]\$UDINT\s*:=\s*' +
                'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\s*;)')
            Replacement = '${1}' + [Environment]::NewLine + '${3}' +
                [Environment]::NewLine + '${2}'
        },
        @{
            Name = 'RebaseSetMaskBroadened'
            Pattern = (
                '(?is)(UpdateAxisRebaseRequiredState\(\s*SetAxisMask:=)0' +
                '(\s*,\s*ClearAxisMask:=AxisMask\))')
            Replacement = '${1}AxisMask${2}'
        },
        @{
            Name = 'RebaseClearMaskSuppressed'
            Pattern = (
                '(?is)(UpdateAxisRebaseRequiredState\(\s*' +
                'SetAxisMask:=0\s*,\s*ClearAxisMask:=)AxisMask(\))')
            Replacement = '${1}0${2}'
        },
        @{
            Name = 'RebaseCallRemoved'
            Pattern = (
                '(?is)rebaseUpdateResult\s*:=\s*' +
                'UpdateAxisRebaseRequiredState\(\s*' +
                'SetAxisMask:=0\s*,\s*ClearAxisMask:=AxisMask\)\s*;')
            Replacement = 'rebaseUpdateResult := -1;'
        },
        @{
            Name = 'PreemptRootSequenceMappedToSession'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership.*?' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*6\]\$UDINT\s*=\s*)' +
                'expectedSequence')
            Replacement = '${1}expectedSession'
        },
        @{
            Name = 'AbsentPreemptIdentityBankShortened'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership.*?' +
                'preemptRootValid\s*=\s*FALSE.*?' +
                'while\s+identityIndex\s*<=\s*)431(\s+do)')
            Replacement = '${1}430${2}'
        },
        @{
            Name = 'SpecialReplacementOldTokenAccepted'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership.*?' +
                'singletonToken\s*)<>(\s*preemptToken)')
            Replacement = '${1}=${2}'
        },
        @{
            Name = 'PreemptBankGateBypassed'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::PublishAxisOwnership\b.*?' +
                'if\s+preemptBankValid\s*=\s*)FALSE' +
                '(\s+then\s*OwnershipState\[24\].*?Result\s*:=\s*-3\s*;' +
                '\s*RETURN\s*;\s*end_if\s*;\s*end_if\s*;' +
                '\s*cleanupReady\s*:=)')
            Replacement = '${1}TRUE${2}'
        },
        @{
            Name = 'RestoreLeaseGateBypassed'
            Pattern = (
                '(?is)(if\s+leaseValid\s*=\s*)FALSE' +
                '(\s+then\s*OwnershipState\[24\]\s*:=\s*1\s*;' +
                '\s*Result\s*:=\s*-3\s*;\s*RETURN\s*;)')
            Replacement = '${1}TRUE${2}'
        },
        @{
            Name = 'RetainLeaseGateBypassed'
            Pattern = (
                '(?is)(if\s+retainLeaseValid\s*=\s*)FALSE' +
                '(\s+then\s*OwnershipState\[24\]\s*:=\s*1\s*;' +
                '\s*Result\s*:=\s*-3\s*;\s*RETURN\s*;)')
            Replacement = '${1}TRUE${2}'
        },
        @{
            Name = 'ReceiptMagicPublishedBeforeGeneration'
            Pattern = (
                '(?is)(ZeroHomeState\[62\]\s*:=\s*0\s*;)\s*' +
                '(ZeroHomeState\[63\]\$UDINT\s*:=\s*' +
                'ZeroHomeState\[33\]\$UDINT\s*;)\s*' +
                '(ZeroHomeState\[60\]\$UDINT\s*:=\s*' +
                'LMC_HOME_OWNER_RECEIPT_MAGIC\s*;)')
            Replacement = '${1}' + [Environment]::NewLine + '${3}' +
                [Environment]::NewLine + '${2}'
        },
        @{
            Name = 'GeneralMutationInsertedBeforeValidation'
            Pattern = (
                '(?is)(if\s+retainLeaseValid\s*=\s*FALSE\s+then)')
            Replacement = (
                "OwnershipState[recordBase + 9]`$UDINT := ObservationCycle;" +
                [Environment]::NewLine + '${1}')
        },
        @{
            Name = 'BankDestructionAllowsQuarantine'
            Pattern = (
                '(?is)(if\s+\(ReportKind\s*=\s*' +
                'LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*&\s*' +
                '\(forceQuarantine\s*=\s*)FALSE(\)\s+then\s*' +
                'if\s+preemptRootValid)')
            Replacement = '${1}TRUE${2}'
        },
        @{
            Name = 'SingletonTokenGateRemoved'
            Pattern = (
                '(?is)(if\s+\(OwnershipState\[7\]\$UDINT\s*=\s*)' +
                'AdmissionToken(\)\s*&\s*' +
                '\(OwnershipState\[8\]\$UDINT\s*=\s*OwnerGeneration\))')
            Replacement = '${1}OwnershipState[7]$UDINT${2}'
        },
        @{
            Name = 'FinalResultPositive'
            Pattern = (
                '(?is)(OwnershipState\[15\]\s*:=\s*0\s*;\s*' +
                'end_if\s*;\s*end_if\s*;\s*Result\s*:=\s*)0' +
                '(\s*;\s*END_FUNCTION\s*$)')
            Replacement = '${1}1${2}'
        }
    )

    $negativeFixtures = [ordered]@{}
    foreach ($fixture in $fixtureSpecs) {
        $fixtureRegex = [regex]::new(
            $fixture.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline -bor
            [Text.RegularExpressions.RegexOptions]::Multiline)
        $fixtureMatches = $fixtureRegex.Matches($ControlServiceText)
        if ($fixtureMatches.Count -ne 1) {
            throw (
                "$Owner publish negative fixture '$($fixture.Name)' found " +
                "$($fixtureMatches.Count) targets, expected one.")
        }
        $negativeFixtures[$fixture.Name] = $fixtureRegex.Replace(
            $ControlServiceText,
            $fixture.Replacement,
            1)
    }

    $negativeCount = 0
    foreach ($negativeFixture in $negativeFixtures.GetEnumerator()) {
        if ($negativeFixture.Value -ceq $ControlServiceText) {
            throw (
                "$Owner publish negative fixture did not mutate " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeOwner = $Owner + ' negative ' + $negativeFixture.Key
        $negativeRejected = $false
        try {
            $negativeScan = Get-LasalScanText $negativeFixture.Value
            $publishMatches = [regex]::Matches(
                $negativeScan,
                ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
                 'LMCControlCommandService::PublishAxisOwnership\s*$' +
                 '.*?^\s*END_FUNCTION\s*$'))
            if ($publishMatches.Count -ne 1) {
                throw (
                    "$negativeOwner publish implementation count is " +
                    "$($publishMatches.Count), expected one.")
            }
            Assert-LasalAxisOwnershipPublishMutationFences `
                -PublishBlock $publishMatches[0].Value `
                -ControlServiceText $negativeFixture.Value `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    $negativeOwner,
                    [StringComparison]::Ordinal)) {
                throw (
                    "$Owner publish negative fixture " +
                    "'$($negativeFixture.Key)' failed outside its contract " +
                    "assertion: $($_.Exception.Message)")
            }
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner publish verifier accepted negative fixture " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeCount += 1
    }

    $positiveRegex = [regex]::new(
        ('(?is)(FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\b.*?' +
         '\bResult\s*:=\s*-1\s*;)'),
        [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
        [Text.RegularExpressions.RegexOptions]::Singleline)
    if ($positiveRegex.Matches($ControlServiceText).Count -ne 1) {
        throw "$Owner publish positive comment fixture target drifted."
    }
    $positiveFixture = $positiveRegex.Replace(
        $ControlServiceText,
        '${1} // verifier comment-only fixture',
        1)
    $positiveScan = Get-LasalScanText $positiveFixture
    $positivePublishMatches = [regex]::Matches(
        $positiveScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if ($positivePublishMatches.Count -ne 1) {
        throw "$Owner publish positive comment fixture lost its method."
    }
    Assert-LasalAxisOwnershipPublishMutationFences `
        -PublishBlock $positivePublishMatches[0].Value `
        -ControlServiceText $positiveFixture `
        -Owner "$Owner positive comment-only fixture"

    if ($negativeCount -ne 69) {
        throw "$Owner publish negative count is $negativeCount, expected 69."
    }
    return $negativeCount
}

function ConvertTo-LasalPublishSplitLf {
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Text
    )

    return $Text.Replace("`r`n", "`n").Replace("`r", "`n")
}

function Get-LasalPublishSplitTextSha256 {
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Text
    )

    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($Text)
        return ([BitConverter]::ToString(
                $sha.ComputeHash($bytes))).Replace('-', '')
    }
    finally {
        $sha.Dispose()
    }
}

function Replace-LasalPublishSplitExactOne {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string]$Old,
        [AllowEmptyString()][string]$New,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $first = $Text.IndexOf($Old, [StringComparison]::Ordinal)
    $last = $Text.LastIndexOf($Old, [StringComparison]::Ordinal)
    if (($first -lt 0) -or ($first -ne $last)) {
        throw "$Owner exact replacement count is not one."
    }
    return $Text.Substring(0, $first) + $New +
        $Text.Substring($first + $Old.Length)
}

function Replace-LasalPublishSplitRegexExactOne {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string]$Pattern,
        [Parameter(Mandatory = $true)][string]$Replacement,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $regex = [regex]::new(
        $Pattern,
        [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
        [Text.RegularExpressions.RegexOptions]::Singleline -bor
        [Text.RegularExpressions.RegexOptions]::Multiline)
    if ($regex.Matches($Text).Count -ne 1) {
        throw "$Owner regex replacement count is not one."
    }
    return $regex.Replace($Text, $Replacement, 1)
}

function Get-LasalAxisOwnershipPublishMode {
    param(
        [Parameter(Mandatory = $true)][string]$ControlServiceText
    )

    $scan = Get-LasalLexicalScanText $ControlServiceText
    $helperSurfaceCount = [regex]::Matches(
        $scan,
        ('(?i)(?<![A-Za-z0-9_])(?:' +
         'HandleAxisOwnershipPublishHomeReceipt|' +
         'PrepareAxisOwnershipPublishDecision)' +
         '(?![A-Za-z0-9_])')).Count
    if ($helperSurfaceCount -eq 0) {
        return 'Monolith'
    }
    return 'SplitCandidate'
}

function Get-LasalAxisOwnershipPublishSplitFragments {
    param(
        [Parameter(Mandatory = $true)][string]$ControlServiceText,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $blocker = "$Owner axis ownership publish split blocker:"
    $canonicalText = ConvertTo-LasalPublishSplitLf -Text $ControlServiceText
    $scan = Get-LasalLexicalScanText $canonicalText
    $classMatches = [regex]::Matches(
        $scan,
        ('(?is)\bLMCControlCommandService\s*:\s*CLASS\b.*?' +
         '\bEND_CLASS\s*;'))
    if ($classMatches.Count -ne 1) {
        throw "$blocker exact class declaration block is missing."
    }
    $classMatch = $classMatches[0]
    $classText = $canonicalText.Substring(
        $classMatch.Index,
        $classMatch.Length)
    $classScan = $scan.Substring($classMatch.Index, $classMatch.Length)

    $adapterMatches = [regex]::Matches(
        $scan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+GLOBAL[ \t]+' +
         'LMCControlCommandService::PublishAxisOwnership[ \t]*$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*(?:\n|$)'))
    if ($adapterMatches.Count -ne 1) {
        throw "$blocker public adapter implementation count is not one."
    }
    $adapterMatch = $adapterMatches[0]

    $result = [ordered]@{
        CanonicalText = $canonicalText
        Scan = $scan
        ClassText = $classText
        ClassScan = $classScan
        Adapter = $canonicalText.Substring(
            $adapterMatch.Index,
            $adapterMatch.Length)
        AdapterIndex = $adapterMatch.Index
    }
    foreach ($helper in @(
            @{
                Key = 'Home'
                Name = 'HandleAxisOwnershipPublishHomeReceipt'
            },
            @{
                Key = 'Decision'
                Name = 'PrepareAxisOwnershipPublishDecision'
            })) {
        $name = $helper.Name
        $implementationMatches = [regex]::Matches(
            $scan,
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCControlCommandService::' + [regex]::Escape($name) +
             '[ \t]*$.*?^[ \t]*END_FUNCTION[ \t]*(?:\n|$)'))
        if ($implementationMatches.Count -ne 1) {
            throw (
                "$blocker $name private implementation count is " +
                "$($implementationMatches.Count), expected one.")
        }
        $implementationMatch = $implementationMatches[0]
        $declarationMatches = [regex]::Matches(
            $classScan,
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             [regex]::Escape($name) + '[ \t]*$' +
             '.*?^[ \t]*END_VAR;?[ \t]*$' +
             '.*?^[ \t]*END_VAR;?[ \t]*(?:\n|$)'))
        if ($declarationMatches.Count -ne 1) {
            throw (
                "$blocker $name private declaration count is " +
                "$($declarationMatches.Count), expected one.")
        }
        $declarationMatch = $declarationMatches[0]
        $result[$helper.Key] = $canonicalText.Substring(
            $implementationMatch.Index,
            $implementationMatch.Length)
        $result[$helper.Key + 'Index'] = $implementationMatch.Index
        $result[$helper.Key + 'Declaration'] = $classText.Substring(
            $declarationMatch.Index,
            $declarationMatch.Length)
        $result[$helper.Key + 'DeclarationIndex'] =
            $declarationMatch.Index
    }
    return [pscustomobject]$result
}

function Get-LasalAxisOwnershipPublishSplitFragmentMetrics {
    param(
        [Parameter(Mandatory = $true)][string]$Fragment
    )

    $scan = Get-LasalLexicalScanText $Fragment
    $lexicalTokens = @(
        [regex]::Matches(
            $scan,
            ('(?i)0x[0-9a-f]+|[A-Za-z_][A-Za-z0-9_]*|\d+|' +
             ':=|<>|<=|>=|\+=|-=|\*=|/=|[^\s]')) |
            ForEach-Object { $_.Value.ToLowerInvariant() })
    $lexicalInventory = [string]::Join('|', $lexicalTokens)

    $localBlocks = [regex]::Matches(
        $scan,
        ('(?is)(?<![A-Za-z0-9_])VAR(?=[ \t\r\n])\s*' +
         '(?<Body>.*?)\bEND_VAR\s*;?'))
    $localInventory = ''
    $localCount = 0
    if ($localBlocks.Count -eq 1) {
        $locals = @(
            [regex]::Matches(
                $localBlocks[0].Groups['Body'].Value,
                ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
                 '(?<Type>[^;\r\n]+)\s*;')) |
                ForEach-Object {
                    ($_.Groups['Name'].Value + ':' +
                     [regex]::Replace(
                         $_.Groups['Type'].Value,
                         '\s+',
                         '')).ToLowerInvariant()
                })
        $localCount = $locals.Count
        $localInventory = [string]::Join('|', $locals)
    }

    $ignoredCalls = @(
        'and', 'case', 'else', 'elsif', 'for', 'if', 'not', 'or',
        'then', 'while')
    $calls = @{}
    foreach ($call in [regex]::Matches(
            $scan,
            ('(?i)(?<![A-Za-z0-9_])' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*\('))) {
        $callName = $call.Groups['Name'].Value.ToLowerInvariant()
        if ($ignoredCalls -contains $callName) {
            continue
        }
        if (-not $calls.ContainsKey($callName)) {
            $calls[$callName] = 0
        }
        $calls[$callName]++
    }
    $callInventory = [string]::Join(
        '|',
        @($calls.Keys | Sort-Object | ForEach-Object {
                "$_=$($calls[$_])"
            }))

    $mutationPattern = (
        '(?is)(?:' +
        '\b(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*' +
        '\[[^\]]+\]\s*(?:\$[A-Za-z_][A-Za-z0-9_]*\s*)?' +
        '(?::|\+|-|\*|/|and|or|xor)\s*=\s*[^;]+;' +
        '|' +
        '\b_memset\s*\(\s*dest\s*:=\s*#' +
        '(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*\[.*?\)\s*;' +
        '|' +
        '\b_memcpy\s*\(\s*ptr1\s*:=\s*#' +
        '(?:Ownership[A-Za-z0-9_]*State|ZeroHomeState)\s*\[.*?\)\s*;' +
        ')')
    $mutations = @(
        [regex]::Matches($scan, $mutationPattern) |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $mutationInventory = [string]::Join('|', $mutations)

    $controlFlow = @(
        [regex]::Matches(
            $scan,
            '(?is)\bResult\s*:=\s*[^;]+\s*;|\bRETURN\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $controlFlowInventory = [string]::Join('|', $controlFlow)

    return [pscustomobject]@{
        LexicalCount = $lexicalTokens.Count
        LexicalLength = $lexicalInventory.Length
        LexicalSha256 = Get-LasalPublishSplitTextSha256 `
            -Text $lexicalInventory
        LocalBlockCount = $localBlocks.Count
        LocalCount = $localCount
        LocalLength = $localInventory.Length
        LocalSha256 = Get-LasalPublishSplitTextSha256 -Text $localInventory
        CallInventory = $callInventory
        MutationCount = $mutations.Count
        MutationLength = $mutationInventory.Length
        MutationSha256 = Get-LasalPublishSplitTextSha256 `
            -Text $mutationInventory
        ControlFlowCount = $controlFlow.Count
        ControlFlowLength = $controlFlowInventory.Length
        ControlFlowSha256 = Get-LasalPublishSplitTextSha256 `
            -Text $controlFlowInventory
    }
}

function Assert-LasalAxisOwnershipPublishSplitMutationFences {
    param(
        [Parameter(Mandatory = $true)][string]$ControlServiceText,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $blocker = "$Owner axis ownership publish split blocker:"
    $fragments = Get-LasalAxisOwnershipPublishSplitFragments `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
    $scan = $fragments.Scan
    $classScan = $fragments.ClassScan
    $adapterScan = Get-LasalLexicalScanText $fragments.Adapter
    $homeScan = Get-LasalLexicalScanText $fragments.Home
    $decisionScan = Get-LasalLexicalScanText $fragments.Decision

    if ($scan -match '\r(?!\n)') {
        throw "$blocker bare carriage-return line endings are forbidden."
    }
    if ($scan -match '\\[^\S\r\n]*\r?\n') {
        throw "$blocker preprocessor-style line splicing is forbidden."
    }
    if ($scan -match
            ('(?im)^[ \t]*#[ \t]*' +
             '(?:if|ifdef|ifndef|elif|else|endif|undef|include)\b')) {
        throw "$blocker conditional compilation and includes are forbidden."
    }

    $publicAbi = (
        'VAR_INPUT\s*' +
        'AxisMask\s*:\s*UDINT\s*;\s*' +
        'AdmissionToken\s*:\s*UDINT\s*;\s*' +
        'OwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'ReportKind\s*:\s*UINT\s*;\s*' +
        'ReportValue0\s*:\s*UDINT\s*;\s*' +
        'ReportValue1\s*:\s*UDINT\s*;\s*' +
        'ObservationCycle\s*:\s*UDINT\s*;\s*' +
        'END_VAR\s*;?\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
    $publicDeclarationCount = [regex]::Matches(
        $classScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+PublishAxisOwnership\s*' +
         $publicAbi + '\s*(?=FUNCTION\b)')).Count
    $publicImplementationCount = [regex]::Matches(
        $adapterScan,
        ('(?is)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*' +
         $publicAbi + '\s*(?=VAR\b)')).Count
    if (($publicDeclarationCount -ne 1) -or
        ($publicImplementationCount -ne 1)) {
        throw "$blocker public adapter ABI drifted."
    }

    $helperContracts = @(
        @{
            Name = 'HandleAxisOwnershipPublishHomeReceipt'
            Scan = $homeScan
            Declaration = $fragments.HomeDeclaration
            Inputs = (
                'AxisMask\s*:\s*UDINT\s*;\s*' +
                'AdmissionToken\s*:\s*UDINT\s*;\s*' +
                'OwnerGeneration\s*:\s*UDINT\s*;\s*' +
                'ReportKind\s*:\s*UINT\s*;\s*' +
                'ReportValue0\s*:\s*UDINT\s*;\s*' +
                'ReportValue1\s*:\s*UDINT\s*;\s*' +
                'ObservationCycle\s*:\s*UDINT\s*;\s*')
        },
        @{
            Name = 'PrepareAxisOwnershipPublishDecision'
            Scan = $decisionScan
            Declaration = $fragments.DecisionDeclaration
            Inputs = (
                'AxisMask\s*:\s*UDINT\s*;\s*' +
                'AdmissionToken\s*:\s*UDINT\s*;\s*' +
                'OwnerGeneration\s*:\s*UDINT\s*;\s*' +
                'ReportKind\s*:\s*UINT\s*;\s*' +
                'ExpectedSession\s*:\s*UDINT\s*;\s*' +
                'ExpectedSequence\s*:\s*UDINT\s*;\s*' +
                'ExpectedCommandId\s*:\s*DINT\s*;\s*' +
                'ExpectedReference\s*:\s*DINT\s*;\s*' +
                'ExpectedAdmissionMode\s*:\s*DINT\s*;\s*' +
                'ExpectedOwnerKind\s*:\s*DINT\s*;\s*')
        })
    foreach ($helper in $helperContracts) {
        $name = $helper.Name
        $abi = (
            'VAR_INPUT\s*' + $helper.Inputs + 'END_VAR\s*;?\s*' +
            'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
        $declarationAbiCount = [regex]::Matches(
            (Get-LasalLexicalScanText $helper.Declaration),
            ('(?is)^\s*FUNCTION\s+' + [regex]::Escape($name) +
             '\s*' + $abi + '\s*$')).Count
        $implementationAbiCount = [regex]::Matches(
            $helper.Scan,
            ('(?is)^\s*FUNCTION\s+LMCControlCommandService::' +
             [regex]::Escape($name) + '\s*' + $abi +
             '\s*(?=VAR\b)')).Count
        $allHeaders = [regex]::Matches(
            $scan,
            ('(?im)^[ \t]*FUNCTION[^\r\n]*\b' +
             [regex]::Escape($name) + '[ \t]*$'))
        $globalHeaders = [regex]::Matches(
            $scan,
            ('(?im)^[ \t]*FUNCTION[ \t]+(?:VIRTUAL[ \t]+)?GLOBAL\b' +
             '[^\r\n]*\b' + [regex]::Escape($name) + '[ \t]*$'))
        if (($declarationAbiCount -ne 1) -or
            ($implementationAbiCount -ne 1) -or
            ($allHeaders.Count -ne 2) -or
            ($globalHeaders.Count -ne 0)) {
            throw (
                "$blocker $name must retain one exact private " +
                'declaration and nonempty implementation ABI.')
        }
    }

    $tablesIndex = $fragments.ClassText.IndexOf(
        '//Tables:',
        [StringComparison]::Ordinal)
    if (($tablesIndex -lt 0) -or
        ($fragments.HomeDeclarationIndex -ge
            $fragments.DecisionDeclarationIndex) -or
        ($fragments.DecisionDeclarationIndex -ge $tablesIndex) -or
        ($fragments.AdapterIndex -ge $fragments.HomeIndex) -or
        ($fragments.HomeIndex -ge $fragments.DecisionIndex)) {
        throw "$blocker declaration or implementation append order drifted."
    }

    $classVariableRegion = [regex]::Match(
        $scan,
        ('(?is)LMCControlCommandService\s*:\s*CLASS\b' +
         '(?<Body>.*?)\bFUNCTION\s+GLOBAL\s+HandleRequest\b'))
    if (-not $classVariableRegion.Success) {
        throw "$blocker class variable region is missing."
    }
    foreach ($stateContract in @(
            @{ Name = 'ZeroHomeState'; Upper = 63 },
            @{ Name = 'OwnershipState'; Upper = 351 },
            @{ Name = 'OwnershipObserverState'; Upper = 107 },
            @{ Name = 'OwnershipLeaseState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedState'; Upper = 323 },
            @{ Name = 'OwnershipIdentityState'; Upper = 431 },
            @{ Name = 'OwnershipLeaseIdentityState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedIdentityState'; Upper = 431 })) {
        $statePattern = (
            '(?im)^\s*' + [regex]::Escape($stateContract.Name) +
            '\s*:\s*ARRAY\s*\[\s*0\s*\.\.\s*' +
            $stateContract.Upper + '\s*\]\s*OF\s*DINT\s*;\s*$')
        if (([regex]::Matches($scan, $statePattern).Count -ne 1) -or
            ([regex]::Matches(
                $classVariableRegion.Groups['Body'].Value,
                $statePattern).Count -ne 1)) {
            throw (
                "$blocker state member $($stateContract.Name) exact " +
                'type/bound/location drifted.')
        }
    }

    $expectedPragmas = @(
        'usingLtd _LMCAxis',
        'usingLtd _LMCRobotBase',
        'usingLtd LMCEcatInputLatch')
    $observedPragmas = @(
        [regex]::Matches(
            $scan,
            ('(?im)^[^\S\r\n]*#[^\S\r\n]*pragma[^\S\r\n]+' +
             '(?<Body>[^\r\n]*?)[^\S\r\n]*\r?$')) |
            ForEach-Object { $_.Groups['Body'].Value })
    if ([string]::Join('|', $observedPragmas) -cne
        [string]::Join('|', $expectedPragmas)) {
        throw "$blocker exact usingLtd pragma closure drifted."
    }

    $macroInventory = @(
        [regex]::Matches(
            $scan,
            ('(?im)^[^\S\r\n]*#[^\S\r\n]*define[^\S\r\n]+' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)' +
             '(?<Value>[^\r\n]*)\r?$')) |
            ForEach-Object {
                ($_.Groups['Name'].Value.ToLowerInvariant() + '=' +
                 [regex]::Replace(
                     $_.Groups['Value'].Value.Trim(),
                     '\s+',
                     ' ').ToLowerInvariant())
            })
    $joinedMacros = [string]::Join('|', $macroInventory)
    if (($macroInventory.Count -ne 165) -or
        ($joinedMacros.Length -ne 6175) -or
        ((Get-LasalPublishSplitTextSha256 -Text $joinedMacros) -cne
            '67348A046E35A28C733ACB27B811B4C88EB6402BEC697CE22ADAF726EC6A2928')) {
        throw "$blocker whole-control macro inventory drifted."
    }

    $fragmentContracts = @(
        @{
            Name = 'adapter'
            Fragment = $fragments.Adapter
            Lexical = @(4170, 25319,
                '3C1049ED8E8B05BA66B4E356865B6580DAE5FA69FE413A11E60322F62FC17000')
            Locals = @(38, 829,
                '3732E95DEC618170651A42C7A956ECA78CC53C8F5D6D8CD80FB3159F8362CA62')
            Calls = (
                '_memcmp=2|_memcpy=2|_memset=15|' +
                'handleaxisownershippublishhomereceipt=1|' +
                'prepareaxisownershippublishdecision=1|sizeof=4|' +
                'to_dint=6|to_udint=18')
            Mutations = @(56, 3638,
                'E685A4E71455615571B824AD4464434E5158B9A3C67FEA43FF24FE1F13BB258E')
            ControlFlow = @(27, 303,
                '3A83F0E059E5A9A57815948D3EB397FAAEF20B7289228FAB2ACFB62AB04CCEAC')
        },
        @{
            Name = 'Home helper'
            Fragment = $fragments.Home
            Lexical = @(2491, 14812,
                'E0A83B3502A850E0DA66DDDDFE10BBCE0F158D851292369B92A7096F3DF597E8')
            Locals = @(26, 660,
                'CE0C97DDC04924C7DA1391BC4A18F7254EF15FE2D6A273FF9D784F1D2D493F50')
            Calls = '_memset=3|to_dint=2|to_udint=13|updateaxisrebaserequiredstate=1'
            Mutations = @(22, 1094,
                '8CE9A7539C508733BE6A2DEF03CF791271642E474DAE8EA40010BD22F8AF5A86')
            ControlFlow = @(17, 184,
                '089F69C095181311F7B4E606035BFA5E56E40455A465AAC1829CE0DA3DBFCB78')
        },
        @{
            Name = 'decision helper'
            Fragment = $fragments.Decision
            Lexical = @(3372, 22104,
                'C1035138B3C7020306E8243C8F613D817680A06F83A8A578AA85CF487543FA10')
            Locals = @(49, 1100,
                '5F8DB2CE8C6D09E32D0F5919D816E61843B3FDDD4920BC5A702E05A936DD67A4')
            Calls = '_memcmp=1|to_udint=17'
            Mutations = @(5, 114,
                'BAD222CADD90EF1C7221EAED84E0DD31D651A031201648E08C567B643FBCECF3')
            ControlFlow = @(11, 110,
                '39824D0FA2E2DC29621CE1CEE70A0046D938B6753A6806D66CF880484CB9571B')
        })
    foreach ($fragmentContract in $fragmentContracts) {
        $metrics = Get-LasalAxisOwnershipPublishSplitFragmentMetrics `
            -Fragment $fragmentContract.Fragment
        if (($metrics.LexicalCount -ne $fragmentContract.Lexical[0]) -or
            ($metrics.LexicalLength -ne $fragmentContract.Lexical[1]) -or
            ($metrics.LexicalSha256 -cne $fragmentContract.Lexical[2])) {
            throw "$blocker $($fragmentContract.Name) lexical token inventory drifted."
        }
        if (($metrics.LocalBlockCount -ne 1) -or
            ($metrics.LocalCount -ne $fragmentContract.Locals[0]) -or
            ($metrics.LocalLength -ne $fragmentContract.Locals[1]) -or
            ($metrics.LocalSha256 -cne $fragmentContract.Locals[2])) {
            throw "$blocker $($fragmentContract.Name) local inventory drifted or is empty."
        }
        if ($metrics.CallInventory -cne $fragmentContract.Calls) {
            throw "$blocker $($fragmentContract.Name) call inventory drifted."
        }
        if (($metrics.MutationCount -ne $fragmentContract.Mutations[0]) -or
            ($metrics.MutationLength -ne $fragmentContract.Mutations[1]) -or
            ($metrics.MutationSha256 -cne $fragmentContract.Mutations[2])) {
            throw "$blocker $($fragmentContract.Name) persistent mutation inventory drifted."
        }
        if (($metrics.ControlFlowCount -ne
                $fragmentContract.ControlFlow[0]) -or
            ($metrics.ControlFlowLength -ne
                $fragmentContract.ControlFlow[1]) -or
            ($metrics.ControlFlowSha256 -cne
                $fragmentContract.ControlFlow[2])) {
            throw "$blocker $($fragmentContract.Name) Result/RETURN inventory drifted."
        }
        $lfFragment = ConvertTo-LasalPublishSplitLf `
            -Text $fragmentContract.Fragment
        $lfBytes = [Text.Encoding]::UTF8.GetByteCount($lfFragment)
        $crlfBytes = [Text.Encoding]::UTF8.GetByteCount(
            $lfFragment.Replace("`n", "`r`n"))
        if (($lfBytes -ge 32768) -or ($crlfBytes -ge 32768)) {
            throw "$blocker $($fragmentContract.Name) violates the method-size hard limit."
        }
    }

    Assert-Match $adapterScan (
        '(?is)homeReceiptResult\s*:=\s*' +
        'HandleAxisOwnershipPublishHomeReceipt\s*\(.*?' +
        'ObservationCycle\s*:=\s*ObservationCycle\s*\)\s*;\s*' +
        'if\s+homeReceiptResult\s*<>\s*2\s+then\s*' +
        'Result\s*:=\s*homeReceiptResult\s*;\s*RETURN\s*;\s*end_if\s*;') (
        "$blocker Home helper call or Result=2 continuation fence drifted.")
    Assert-Match $adapterScan (
        '(?is)publishDecisionResult\s*:=\s*' +
        'PrepareAxisOwnershipPublishDecision\s*\(.*?' +
        'ExpectedOwnerKind\s*:=\s*expectedOwnerKind\s*\)\s*;\s*' +
        'if\s+publishDecisionResult\s*<\s*0\s+then\s*' +
        'Result\s*:=\s*publishDecisionResult\s*;\s*RETURN\s*;\s*' +
        'elsif\s+publishDecisionResult\s*>\s*7\s+then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;\s*end_if\s*;\s*' +
        'preemptRootValid\s*:=\s*' +
        '\(publishDecisionResult\s+and\s+1\)\s*<>\s*0\s*;\s*' +
        'forceQuarantine\s*:=\s*' +
        '\(publishDecisionResult\s+and\s+2\)\s*<>\s*0\s*;\s*' +
        'restoreLease\s*:=\s*' +
        '\(publishDecisionResult\s+and\s+4\)\s*<>\s*0\s*;') (
        "$blocker decision helper call, failure fence, or bit map drifted.")
    Assert-Match $homeScan (
        '(?is)END_VAR\s*Result\s*:=\s*2\s*;.*?' +
        'END_FUNCTION\s*$') (
        "$blocker Home Result=2 containment drifted.")
    Assert-Match $decisionScan (
        '(?is)Result\s*:=\s*0\s*;\s*' +
        'if\s+preemptRootValid\s+then\s*Result\s*\+=\s*1\s*;.*?' +
        'if\s+forceQuarantine\s+then\s*Result\s*\+=\s*2\s*;.*?' +
        'if\s+restoreLease\s+then\s*Result\s*\+=\s*4\s*;.*?' +
        'END_FUNCTION\s*$') (
        "$blocker decision Result bit domain drifted.")

    return [pscustomobject]@{
        Mode = 'Split'
        Adapter = $fragments.Adapter
        Home = $fragments.Home
        Decision = $fragments.Decision
    }
}

function Assert-LasalAxisOwnershipPublishStateContract {
    param(
        [Parameter(Mandatory = $true)][string]$ControlServiceText,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $mode = Get-LasalAxisOwnershipPublishMode `
        -ControlServiceText $ControlServiceText
    if ($mode -ceq 'Monolith') {
        $scan = Get-LasalLexicalScanText $ControlServiceText
        $publishMatches = [regex]::Matches(
            $scan,
            ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
             'LMCControlCommandService::PublishAxisOwnership\s*$' +
             '.*?^\s*END_FUNCTION\s*$'))
        if ($publishMatches.Count -ne 1) {
            throw (
                "$Owner axis ownership publish state blocker: monolith " +
                "implementation count is $($publishMatches.Count), expected one.")
        }
        Assert-LasalAxisOwnershipPublishMutationFences `
            -PublishBlock $publishMatches[0].Value `
            -ControlServiceText $ControlServiceText `
            -Owner $Owner
        return [pscustomobject]@{
            Mode = 'Monolith'
            Adapter = $publishMatches[0].Value
            Home = ''
            Decision = ''
        }
    }

    return Assert-LasalAxisOwnershipPublishSplitMutationFences `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
}

function Get-LasalAxisOwnershipPublishPlannedSplitFixture {
    param(
        [Parameter(Mandatory = $true)][string]$RepositoryRoot,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $plannerPath = Join-Path $RepositoryRoot (
        'test\Reports_Lasal\C78_20260807_publish_split_rebaseline\' +
        'Plan-PublishSplit.ps1')
    if (-not (Test-Path -LiteralPath $plannerPath -PathType Leaf)) {
        throw "$Owner publish split planner is missing."
    }
    # Dot-source only inside a disposable child scope. The production verifier
    # accepts split source from its own contracts; planner internals are used
    # only to synthesize a pre-transition self-test fixture.
    $plannerResult = & {
        param($ChildPlannerPath, $ChildRepositoryRoot)

        $childOutput = @(
            . $ChildPlannerPath -RepositoryRoot $ChildRepositoryRoot)
        return [pscustomobject]@{
            Output = $childOutput
            Candidate = [string]$plannedSource
        }
    } $plannerPath $RepositoryRoot
    if (($plannerResult.Output.Count -ne 1) -or
        [string]::IsNullOrWhiteSpace(
            [string]$plannerResult.Output[0]) -or
        [string]::IsNullOrWhiteSpace($plannerResult.Candidate)) {
        throw "$Owner publish split planner did not produce one candidate."
    }
    return ConvertTo-LasalPublishSplitLf `
        -Text ([string]$plannerResult.Candidate)
}

function Invoke-LasalAxisOwnershipPublishSplitVerifierSelfTest {
    param(
        [Parameter(Mandatory = $true)][string]$ControlServiceText,
        [Parameter(Mandatory = $true)][string]$RepositoryRoot,
        [Parameter(Mandatory = $true)][string]$Owner
    )

    $currentState = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $ControlServiceText `
        -Owner "$Owner current state"
    $splitFixture = if ($currentState.Mode -ceq 'Split') {
        ConvertTo-LasalPublishSplitLf -Text $ControlServiceText
    }
    else {
        Get-LasalAxisOwnershipPublishPlannedSplitFixture `
            -RepositoryRoot $RepositoryRoot `
            -Owner $Owner
    }
    $splitState = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $splitFixture `
        -Owner "$Owner positive split LF"
    if ($splitState.Mode -cne 'Split') {
        throw "$Owner planned positive fixture did not resolve to Split."
    }
    $crlfFixture = $splitFixture.Replace("`n", "`r`n")
    $crlfState = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $crlfFixture `
        -Owner "$Owner positive split CRLF"
    if ($crlfState.Mode -cne 'Split') {
        throw "$Owner CRLF positive fixture did not resolve to Split."
    }
    $fragments = Get-LasalAxisOwnershipPublishSplitFragments `
        -ControlServiceText $splitFixture `
        -Owner $Owner

    $emptyHome = [string]::Join("`n", @(
            'FUNCTION LMCControlCommandService::HandleAxisOwnershipPublishHomeReceipt',
            "`tVAR_INPUT",
            "`t`tAxisMask : UDINT;",
            "`t`tAdmissionToken : UDINT;",
            "`t`tOwnerGeneration : UDINT;",
            "`t`tReportKind : UINT;",
            "`t`tReportValue0 : UDINT;",
            "`t`tReportValue1 : UDINT;",
            "`t`tObservationCycle : UDINT;",
            "`tEND_VAR",
            "`tVAR_OUTPUT",
            "`t`tResult : DINT;",
            "`tEND_VAR",
            '',
            'END_FUNCTION',
            ''))
    $emptyDecision = [string]::Join("`n", @(
            'FUNCTION LMCControlCommandService::PrepareAxisOwnershipPublishDecision',
            "`tVAR_INPUT",
            "`t`tAxisMask : UDINT;",
            "`t`tAdmissionToken : UDINT;",
            "`t`tOwnerGeneration : UDINT;",
            "`t`tReportKind : UINT;",
            "`t`tExpectedSession : UDINT;",
            "`t`tExpectedSequence : UDINT;",
            "`t`tExpectedCommandId : DINT;",
            "`t`tExpectedReference : DINT;",
            "`t`tExpectedAdmissionMode : DINT;",
            "`t`tExpectedOwnerKind : DINT;",
            "`tEND_VAR",
            "`tVAR_OUTPUT",
            "`t`tResult : DINT;",
            "`tEND_VAR",
            '',
            'END_FUNCTION',
            ''))

    $homeGlobal = Replace-LasalPublishSplitRegexExactOne `
        -Text $fragments.Home `
        -Pattern ('^FUNCTION\s+(?=LMCControlCommandService::' +
            'HandleAxisOwnershipPublishHomeReceipt)') `
        -Replacement 'FUNCTION GLOBAL ' `
        -Owner "$Owner Home global fixture"
    $adapterCallRemoved = Replace-LasalPublishSplitExactOne `
        -Text $fragments.Adapter `
        -Old 'HandleAxisOwnershipPublishHomeReceipt(' `
        -New 'HandleAxisOwnershipPublishHomeReceiptMissing(' `
        -Owner "$Owner adapter call fixture"

    $fixtures = @(
        @{
            Name = 'PartialHomeDeclaration'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.HomeDeclaration `
                -New '' `
                -Owner "$Owner partial Home declaration fixture"
        },
        @{
            Name = 'PartialDecisionImplementation'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.Decision `
                -New '' `
                -Owner "$Owner partial decision implementation fixture"
        },
        @{
            Name = 'DuplicateHomeDeclaration'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.HomeDeclaration `
                -New ($fragments.HomeDeclaration +
                    $fragments.HomeDeclaration) `
                -Owner "$Owner duplicate Home declaration fixture"
        },
        @{
            Name = 'DuplicateDecisionImplementation'
            Value = $splitFixture + "`n" + $fragments.Decision
        },
        @{
            Name = 'EmptyHomeStub'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.Home `
                -New $emptyHome `
                -Owner "$Owner empty Home stub fixture"
        },
        @{
            Name = 'EmptyDecisionStub'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.Decision `
                -New $emptyDecision `
                -Owner "$Owner empty decision stub fixture"
        },
        @{
            Name = 'HomeImplementationMadeGlobal'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.Home `
                -New $homeGlobal `
                -Owner "$Owner Home global source fixture"
        },
        @{
            Name = 'AdapterHomeCallRemoved'
            Value = Replace-LasalPublishSplitExactOne `
                -Text $splitFixture `
                -Old $fragments.Adapter `
                -New $adapterCallRemoved `
                -Owner "$Owner adapter call source fixture"
        })
    if (($fixtures.Count -ne 8) -or
        (@($fixtures.Name | Select-Object -Unique).Count -ne 8)) {
        throw "$Owner split fixture inventory drifted."
    }

    $rejected = 0
    foreach ($fixture in $fixtures) {
        if ($fixture.Value -ceq $splitFixture) {
            throw "$Owner split fixture '$($fixture.Name)' did not mutate."
        }
        $negativeOwner = "$Owner negative $($fixture.Name)"
        $didReject = $false
        try {
            $null = Assert-LasalAxisOwnershipPublishStateContract `
                -ControlServiceText $fixture.Value `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    "$negativeOwner axis ownership publish split blocker:",
                    [StringComparison]::Ordinal)) {
                throw
            }
            $didReject = $true
        }
        if (-not $didReject) {
            throw (
                "$Owner split verifier accepted negative fixture " +
                "'$($fixture.Name)'.")
        }
        $rejected++
    }

    $commentAdapter = Replace-LasalPublishSplitExactOne `
        -Text $fragments.Adapter `
        -Old "`tResult := -1;" `
        -New "`tResult := -1; // split verifier comment-only fixture" `
        -Owner "$Owner split positive comment fixture"
    $commentFixture = Replace-LasalPublishSplitExactOne `
        -Text $splitFixture `
        -Old $fragments.Adapter `
        -New $commentAdapter `
        -Owner "$Owner split positive comment source fixture"
    $commentState = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $commentFixture `
        -Owner "$Owner positive split comment-only"
    if ($commentState.Mode -cne 'Split') {
        throw "$Owner split comment-only fixture did not resolve to Split."
    }
    return $rejected
}

function Get-LasalAxisOwnershipPublishCallerMethodBlock {
    param(
        [string]$SourceText,
        [string]$ClassName,
        [string]$MethodName,
        [string]$Owner
    )

    $scan = Get-LasalLexicalScanText $SourceText
    $matches = [regex]::Matches(
        $scan,
        ('(?ims)^[ \t]*FUNCTION(?:\s+(?:VIRTUAL\s+GLOBAL|GLOBAL))?\s+' +
         [regex]::Escape($ClassName + '::' + $MethodName) + '\s*$' +
         '.*?^[ \t]*END_FUNCTION\s*$'))
    if ($matches.Count -ne 1) {
        throw (
            "$Owner $ClassName.$MethodName implementation count is " +
            "$($matches.Count), expected exactly one.")
    }
    return $matches[0].Value
}

function Get-LasalAxisOwnershipPublishCallerGroupRecords {
    param(
        [string]$MethodBlock,
        [string]$ResultName,
        [string]$Qualifier,
        [string]$Owner,
        [string]$PublishMethod = 'PublishAxisOwnership'
    )

    $qualifiedCall = if ([string]::IsNullOrWhiteSpace($Qualifier)) {
        [regex]::Escape($PublishMethod)
    }
    else {
        [regex]::Escape($Qualifier) + '\s*\.\s*' +
            [regex]::Escape($PublishMethod)
    }
    $callStartPattern = (
        '(?im)(?<![A-Za-z0-9_])' + [regex]::Escape($ResultName) +
        '\s*:=\s*' + $qualifiedCall + '\s*\(')
    $callStarts = [regex]::Matches($MethodBlock, $callStartPattern)
    $records = [System.Collections.Generic.List[object]]::new()

    foreach ($callStart in $callStarts) {
        $openIndex = $callStart.Index + $callStart.Length - 1
        $depth = 0
        $closeIndex = -1
        for ($index = $openIndex; $index -lt $MethodBlock.Length; $index++) {
            if ($MethodBlock[$index] -eq '(') {
                $depth += 1
            }
            elseif ($MethodBlock[$index] -eq ')') {
                $depth -= 1
                if ($depth -eq 0) {
                    $closeIndex = $index
                    break
                }
            }
        }
        if ($closeIndex -lt 0) {
            throw "$Owner $ResultName call has no balanced closing parenthesis."
        }

        $statementEnd = $closeIndex + 1
        while (($statementEnd -lt $MethodBlock.Length) -and
            [char]::IsWhiteSpace($MethodBlock[$statementEnd])) {
            $statementEnd += 1
        }
        if (($statementEnd -ge $MethodBlock.Length) -or
            ($MethodBlock[$statementEnd] -ne ';')) {
            throw "$Owner $ResultName call is not terminated by a semicolon."
        }
        $statementEnd += 1

        $nextAssignment = [regex]::Match(
            $MethodBlock.Substring($statementEnd),
            ('(?im)(?<![A-Za-z0-9_])' +
             [regex]::Escape($ResultName) + '\s*:='))
        $windowEnd = $MethodBlock.Length
        if ($nextAssignment.Success) {
            $windowEnd = $statementEnd + $nextAssignment.Index
        }
        $consumerWindow = $MethodBlock.Substring(
            $statementEnd,
            $windowEnd - $statementEnd)
        $resultUseCount = [regex]::Matches(
            $consumerWindow,
            ('(?i)(?<![A-Za-z0-9_])' +
             [regex]::Escape($ResultName) +
             '(?![A-Za-z0-9_])')).Count
        $records.Add([pscustomobject]@{
                Statement = $MethodBlock.Substring(
                    $callStart.Index,
                    $statementEnd - $callStart.Index)
                ConsumerWindow = $consumerWindow
                CallStartIndex = $callStart.Index
                StatementEndIndex = $statementEnd
                ResultUseCount = $resultUseCount
                Consumed = $resultUseCount -gt 0
            })
    }
    return $records.ToArray()
}

function Assert-LasalAxisOwnershipPublishCallerInventory {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $blocker = "$Owner axis ownership publish caller inventory blocker:"
    $sources = [ordered]@{
        Tcp = @{
            Text = $TcpText
            ClassName = 'TCPMotionInterface'
        }
        Control = @{
            Text = $ControlServiceText
            ClassName = 'LMCControlCommandService'
        }
        Diagnostics = @{
            Text = $DiagnosticsText
            ClassName = 'LMCDiagnosticsService'
        }
    }
    $groups = @(
        @{ Source = 'Tcp'; Method = 'CyWork'; Result = 'cleanupPublishResult'; Qualifier = 'ControlCommands'; Count = 1; Open = @(1); OpenReportKind = '4' },
        @{ Source = 'Tcp'; Method = 'HandleControlSafetyDrainPending'; Result = 'pendingPublishResult'; Qualifier = 'ControlCommands'; Count = 3; Open = @(1, 2, 3); OpenReportKind = '4' },
        @{ Source = 'Tcp'; Method = 'MsgPaser'; Result = 'diagnosticsPublishResult'; Qualifier = 'ControlCommands'; Count = 1; Open = @(1); OpenReportKind = '4' },
        @{ Source = 'Tcp'; Method = 'MsgPaser'; Result = 'controlPublishResult'; Qualifier = 'ControlCommands'; Count = 2; Open = @(1, 2); OpenReportKind = '4' },
        @{ Source = 'Control'; Method = 'HandleRequest'; Result = 'ownershipPublishResult'; Qualifier = ''; Count = 3; Open = @(1); OpenReportKind = 'LMC_OWNER_REPORT_QUARANTINE' },
        @{ Source = 'Control'; Method = 'ProcessAxisOwnership'; Result = 'publishResult'; Qualifier = ''; Count = 2; Open = @(); OpenReportKind = '' },
        @{ Source = 'Control'; Method = 'ProcessAxisZeroHome'; Result = 'homePublishResult'; Qualifier = ''; Count = 2; Open = @(); OpenReportKind = '' },
        @{ Source = 'Diagnostics'; Method = 'ProcessEncoderMaintenance'; Result = 'ownerResult'; Qualifier = 'AxisOwnership'; Count = 4; Open = @(4); OpenReportKind = 'LMC_DIAG_OWNER_REPORT_QUARANTINE' },
        @{ Source = 'Diagnostics'; Method = 'ProcessAxisDs402Home'; Result = 'ownerResult'; Qualifier = 'AxisOwnership'; Count = 1; Open = @(); OpenReportKind = '' },
        @{ Source = 'Diagnostics'; Method = 'HandleAxisDs402HomeCleanupStages'; Result = 'ownerResult'; Qualifier = 'AxisOwnership'; Count = 2; Open = @(1, 2); OpenReportKind = 'LMC_DIAG_OWNER_REPORT_QUARANTINE' }
    )

    $broadCallCount = 0
    $assignedCallCount = 0
    foreach ($source in $sources.GetEnumerator()) {
        $scan = Get-LasalLexicalScanText $source.Value.Text
        $broadCallCount += [regex]::Matches(
            $scan,
            '(?i)(?<![A-Za-z0-9_])PublishAxisOwnership\s*\(').Count
        $assignedCallCount += [regex]::Matches(
            $scan,
            ('(?i)(?<![A-Za-z0-9_])[A-Za-z_][A-Za-z0-9_]*\s*:=\s*' +
             '(?:[A-Za-z_][A-Za-z0-9_]*\s*\.\s*)?' +
             'PublishAxisOwnership\s*\(')).Count
    }
    if (($broadCallCount -ne 21) -or ($assignedCallCount -ne 21)) {
        throw (
            "$blocker production broad/assigned call counts are " +
            "$broadCallCount/$assignedCallCount, expected 21/21.")
    }

    $total = 0
    $consumed = 0
    $open = 0
    foreach ($group in $groups) {
        $source = $sources[$group.Source]
        $groupOwner = (
            "$blocker $($source.ClassName).$($group.Method)." +
            $group.Result)
        $methodBlock = Get-LasalAxisOwnershipPublishCallerMethodBlock `
            -SourceText $source.Text `
            -ClassName $source.ClassName `
            -MethodName $group.Method `
            -Owner $groupOwner
        Assert-LasalExactDeclaredType `
            -Text $methodBlock `
            -Name $group.Result `
            -ExpectedType 'DINT' `
            -Owner "$groupOwner result receiver"
        $records = @(
            Get-LasalAxisOwnershipPublishCallerGroupRecords `
                -MethodBlock $methodBlock `
                -ResultName $group.Result `
                -Qualifier $group.Qualifier `
                -Owner $groupOwner)
        if ($records.Count -ne $group.Count) {
            throw (
                "$groupOwner call count is $($records.Count), expected " +
                "$($group.Count).")
        }

        for ($recordIndex = 0; $recordIndex -lt $records.Count; $recordIndex++) {
            $ordinal = $recordIndex + 1
            $record = $records[$recordIndex]
            $expectedOpen = $group.Open -contains $ordinal
            if ($record.Consumed -eq $expectedOpen) {
                $expectedState = if ($expectedOpen) { 'unconsumed OPEN' } else { 'consumed' }
                throw (
                    "$groupOwner call $ordinal is consumed=$($record.Consumed), " +
                    "expected $expectedState.")
            }
            if ($expectedOpen) {
                $reportKindPattern = (
                    '(?is)(?<![A-Za-z0-9_])ReportKind\s*:=\s*' +
                    [regex]::Escape($group.OpenReportKind) + '\s*,')
                if ([regex]::Matches(
                        $record.Statement,
                        $reportKindPattern).Count -ne 1) {
                    throw (
                        "$groupOwner OPEN call $ordinal ReportKind is not exact " +
                        "$($group.OpenReportKind).")
                }
                $open += 1
            }
            else {
                $consumed += 1
            }
            $total += 1
        }
    }
    if (($total -ne 21) -or ($consumed -ne 10) -or ($open -ne 11)) {
        throw (
            "$blocker grouped total/consumed/OPEN counts are " +
            "$total/$consumed/$open, expected 21/10/11.")
    }
    return [pscustomobject]@{
        Total = $total
        Consumed = $consumed
        Open = $open
    }
}

function Invoke-LasalAxisOwnershipPublishCallerInventoryVerifierSelfTest {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $cleanupCallPattern = (
        '(?is)(cleanupPublishResult\s*:=\s*' +
        'ControlCommands\.PublishAxisOwnership\(.*?\)\s*;)')
    $fixtureSpecs = @(
        @{ Name = 'CallerDuplicated'; Source = 'Tcp'; Pattern = $cleanupCallPattern; Replacement = '${1}' + [Environment]::NewLine + '${1}' },
        @{ Name = 'CallerRemoved'; Source = 'Tcp'; Pattern = '(?is)(cleanupPublishResult\s*:=\s*ControlCommands\.)PublishAxisOwnership(?=\s*\()'; Replacement = '${1}PublishAxisOwnershipShadow' },
        @{ Name = 'ResultAssignmentRemoved'; Source = 'Tcp'; Pattern = '(?is)cleanupPublishResult\s*:=\s*(?=ControlCommands\.PublishAxisOwnership\s*\()'; Replacement = '' },
        @{ Name = 'ResultLocalChanged'; Source = 'Tcp'; Pattern = '(?is)cleanupPublishResult(?=\s*:=\s*ControlCommands\.PublishAxisOwnership\s*\()'; Replacement = 'cleanupRollbackResult' },
        @{ Name = 'OpenResultConsumed'; Source = 'Tcp'; Pattern = $cleanupCallPattern; Replacement = '${1}' + [Environment]::NewLine + 'cleanupRollbackResult := cleanupPublishResult;' },
        @{ Name = 'ConsumedResultCheckRemoved'; Source = 'Control'; Pattern = '(?is)(ownershipPublishResult\s*:=\s*PublishAxisOwnership\(\s*.*?ReportKind:=LMC_OWNER_REPORT_TERMINAL_SUCCESS\s*,.*?\)\s*;\s*if\s+)ownershipPublishResult(\s*<>\s*0\s+then)'; Replacement = '${1}ownershipRollbackResult${2}' },
        @{ Name = 'OpenReportKindChanged'; Source = 'Tcp'; Pattern = '(?is)(cleanupPublishResult\s*:=\s*ControlCommands\.PublishAxisOwnership\(.*?ReportKind\s*:=\s*)4(\s*,)'; Replacement = '${1}3${2}' },
        @{ Name = 'ResultReceiverTypeChanged'; Source = 'Tcp'; Pattern = '(?im)^([ \t]*)cleanupPublishResult\s*:\s*DINT\s*;'; Replacement = '${1}cleanupPublishResult : UDINT;' }
    )
    $negativeCount = 0
    foreach ($fixtureSpec in $fixtureSpecs) {
        $sourceText = switch ($fixtureSpec.Source) {
            'Tcp' { $TcpText }
            'Control' { $ControlServiceText }
            'Diagnostics' { $DiagnosticsText }
        }
        $fixtureRegex = [regex]::new(
            $fixtureSpec.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline -bor
            [Text.RegularExpressions.RegexOptions]::Multiline)
        $fixtureMatches = $fixtureRegex.Matches($sourceText)
        if ($fixtureMatches.Count -ne 1) {
            throw (
                "$Owner caller negative fixture '$($fixtureSpec.Name)' found " +
                "$($fixtureMatches.Count) targets, expected one.")
        }
        $mutatedSource = $fixtureRegex.Replace(
            $sourceText,
            $fixtureSpec.Replacement,
            1)
        if ($mutatedSource -ceq $sourceText) {
            throw (
                "$Owner caller negative fixture '$($fixtureSpec.Name)' " +
                'did not mutate its source.')
        }
        $fixtureTcp = if ($fixtureSpec.Source -eq 'Tcp') {
            $mutatedSource
        }
        else {
            $TcpText
        }
        $fixtureControl = if ($fixtureSpec.Source -eq 'Control') {
            $mutatedSource
        }
        else {
            $ControlServiceText
        }
        $fixtureDiagnostics = if ($fixtureSpec.Source -eq 'Diagnostics') {
            $mutatedSource
        }
        else {
            $DiagnosticsText
        }
        $negativeOwner = "$Owner caller negative $($fixtureSpec.Name)"
        $negativeRejected = $false
        try {
            $null = Assert-LasalAxisOwnershipPublishCallerInventory `
                -TcpText $fixtureTcp `
                -ControlServiceText $fixtureControl `
                -DiagnosticsText $fixtureDiagnostics `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    $negativeOwner,
                    [StringComparison]::Ordinal)) {
                throw (
                    "$Owner caller negative fixture '$($fixtureSpec.Name)' " +
                    "failed outside its contract assertion: $($_.Exception.Message)")
            }
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner caller inventory verifier accepted negative fixture " +
                "'$($fixtureSpec.Name)'.")
        }
        $negativeCount += 1
    }

    $positivePattern = '(?im)^([ \t]*cleanupPublishResult\s*:\s*DINT\s*;)'
    $positiveRegex = [regex]::new($positivePattern)
    if ($positiveRegex.Matches($TcpText).Count -ne 1) {
        throw "$Owner caller positive comment fixture target drifted."
    }
    $positiveTcp = $positiveRegex.Replace(
        $TcpText,
        ('${1} // fakeResult := ' +
         'ControlCommands.PublishAxisOwnership(ReportKind:=3);'),
        1)
    $null = Assert-LasalAxisOwnershipPublishCallerInventory `
        -TcpText $positiveTcp `
        -ControlServiceText $ControlServiceText `
        -DiagnosticsText $DiagnosticsText `
        -Owner "$Owner caller positive comment-only fixture"

    if ($negativeCount -ne 8) {
        throw "$Owner caller negative count is $negativeCount, expected 8."
    }
    return $negativeCount
}

function Invoke-LasalAxisOwnershipPublishCallerLegacySyntheticSelfTest {
    param(
        [string]$Owner
    )

    $newLegacyCall = {
        param(
            [string]$ResultName,
            [string]$Qualifier,
            [string]$ReportKind,
            [bool]$Consumed
        )
        $callName = if ([string]::IsNullOrWhiteSpace($Qualifier)) {
            'PublishAxisOwnership'
        }
        else {
            $Qualifier + '.PublishAxisOwnership'
        }
        $consumer = if ($Consumed) {
@"
if $ResultName <> 0 then
    sink := 1;
end_if;
"@
        }
        else {
            ''
        }
        return @"
$ResultName := $callName(
    AxisMask:=axisMask,
    AdmissionToken:=admissionToken,
    OwnerGeneration:=ownerGeneration,
    ReportKind:=$ReportKind,
    ReportValue0:=0,
    ReportValue1:=0,
    ObservationCycle:=currentCycle);
$consumer
"@
    }

