        @{ Name = 'EncoderPreemptionMarkerRemoved'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?EncoderMaintenanceState\s*\[\s*191\s*\]\s*:=\s*)1(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'EncoderPreemptionStageOrderInverted'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?)(EncoderMaintenanceState\s*\[\s*191\s*\]\s*:=\s*1\s*;)\s*(EncoderMaintenanceState\s*\[\s*152\s*\]\s*:=\s*LMC_DIAG_ENCODER_STAGE_QUARANTINED\s*;)'; Replacement = '${1}${3}' + [Environment]::NewLine + '${2}' },
        @{ Name = 'Ds402RecoveryWriteRemoved'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?ownerResult\s*:=\s*AxisOwnership\.PublishAxisOwnership\(.*?ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_QUARANTINE.*?if\s+ownerResult\s*<>\s*0\s+then\s*Ds402HomeState\s*\[\s*119\s*\]\s*:=\s*)ownerResult(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'Ds402TagRemoved'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?if\s+ownerResult\s*<>\s*0\s+then.*?Ds402HomeState\s*\[\s*118\s*\](?:\s*\$UDINT)?\s*:=\s*)LMC_DIAG_DS402_PUBLISH_FAILURE_MAGIC(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'Ds402StageCommittedEarly'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?Ds402HomeState\s*\[\s*118\s*\](?:\s*\$UDINT)?\s*:=\s*LMC_DIAG_DS402_PUBLISH_FAILURE_MAGIC\s*;)\s*(Ds402HomeState\s*\[\s*92\s*\]\s*:=\s*101\s*;)'; Replacement = '${2}' + [Environment]::NewLine + '${1}' },
        @{ Name = 'Ds402TupleErased'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?ownerResult\s*:=\s*AxisOwnership\.PublishAxisOwnership\(.*?ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_QUARANTINE.*?if\s+ownerResult\s*<>\s*0\s+then\s*Ds402HomeState\s*\[\s*119\s*\]\s*:=\s*ownerResult\s*;)'; Replacement = '${1}' + [Environment]::NewLine + 'Ds402HomeState[120] := 0;' },
        @{ Name = 'PreemptionReplayOneRejected'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?PublishAxisOwnershipPreemptionCleanup\(.*?if\s+\(ownerResult\s*<>\s*0\)\s*&\s*\(ownerResult\s*)<>(\s*1\s*\)\s+then)'; Replacement = '${1}=${2}' },
        @{ Name = 'PreemptionSuccessReplayRejected'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?if\s+\(ownerResult\s*=\s*0\)\s*\|\s*\(ownerResult\s*)=(\s*1\s*\)\s+then)'; Replacement = '${1}<>${2}' },
        @{ Name = 'TcpRollbackBetweenHandleAndPending'; Source = 'Tcp'; Pattern = '(?is)(OwnerGeneration\s*:=\s*ownerGeneration\s*\)\s*;)(\s*if\s+controlResponseSize\s*=\s*LMC_OWNER_SAFETY_DRAIN_PENDING)'; Replacement = '${1}' + [Environment]::NewLine + 'controlPendingResult := ControlCommands.RollbackAxisOwnership(AdmissionToken:=1, OwnerGeneration:=1, CallerSessionEpoch:=1, RequestSequence:=1, Reason:=0);${2}' },
        @{ Name = 'PendingRetainReturnRemoved'; Source = 'Tcp'; Pattern = '(?is)(HandleControlSafetyDrainPending\s*\(\s*Phase\s*:=\s*LMC_OWNER_SAFETY_PHASE_RETAIN.*?\)\s*;)\s*RETURN\s*;'; Replacement = '${1}' + [Environment]::NewLine + 'controlPendingResult := 0;' },
        @{ Name = 'DisconnectPayloadMutation'; Source = 'Tcp'; Pattern = '(?is)(TCP_SVR_SOCK_INFO_DISCONNECT\s*:\s*ConnectedClients\s*-=\s*1\s*;)'; Replacement = '${1}' + [Environment]::NewLine + 'ActiveRequest.PayloadData[0] := 0;' },
        @{ Name = 'DisconnectQueueDequeue'; Source = 'Tcp'; Pattern = '(?is)(TCP_SVR_SOCK_INFO_DISCONNECT\s*:\s*ConnectedClients\s*-=\s*1\s*;)'; Replacement = '${1}' + [Environment]::NewLine + 'QueueReadIndex += 1;' },
        @{ Name = 'DisconnectIngressMutation'; Source = 'Tcp'; Pattern = '(?is)(TCP_SVR_SOCK_INFO_DISCONNECT\s*:\s*ConnectedClients\s*-=\s*1\s*;)'; Replacement = '${1}' + [Environment]::NewLine + 'IngressDiscardRemaining := 0;' },
        @{ Name = 'EncoderProviderDefaultChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::ProcessEncoderMaintenance.*?ownerResult\s*:=\s*)-1(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'EncoderProviderElseEvidenceChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::ProcessEncoderMaintenance.*?else\s*EncoderMaintenanceState\s*\[\s*190\s*\]\s*:=\s*)ownerResult(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'Ds402ProviderDefaultChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?ownerResult\s*:=\s*)-1(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'Ds402PostDispatchDefaultChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?Ds402HomeState\s*\[\s*92\s*\]\s*:=\s*101\s*;\s*RETURN\s*;.*?ownerResult\s*:=\s*)-1(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'Ds402ProviderElseEvidenceChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages.*?else\s*Ds402HomeState\s*\[\s*119\s*\]\s*:=\s*)ownerResult(\s*;)'; Replacement = '${1}0${2}' },
        @{ Name = 'PreemptionAllowedArmResultReused'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?if\s+\(ownerResult\s*=\s*0\)\s*\|\s*\(ownerResult\s*=\s*1\)\s+then\s*sink\s*:=\s*)0(\s*;)'; Replacement = '${1}ownerResult${2}' },
        @{ Name = 'EncoderPreemptionNativeRhsChanged'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?EncoderMaintenanceState\s*\[\s*180\s*\]\s*:=\s*)TO_DINT\s*\(\s*0\s*-\s*ownerResult\s*\)(\s*;)'; Replacement = '${1}ownerResult${2}' },
        @{ Name = 'EncoderPreemptionEvidenceDuplicated'; Source = 'Diagnostics'; Pattern = '(?is)(FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenancePreemption.*?EncoderMaintenanceState\s*\[\s*191\s*\]\s*:=\s*1\s*;)'; Replacement = '${1}' + [Environment]::NewLine + 'EncoderMaintenanceState[191] := 1;' }
    )
    $negativeCount = 0
    foreach ($fixtureSpec in $fixtureSpecs) {
        $sourceText = switch ($fixtureSpec.Source) {
            'Tcp' { $tcpFixture }
            'Control' { $controlFixture }
            'Diagnostics' { $diagnosticsFixture }
        }
        $fixtureRegex = [regex]::new(
            $fixtureSpec.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline -bor
            [Text.RegularExpressions.RegexOptions]::Multiline)
        $fixtureMatches = $fixtureRegex.Matches($sourceText)
        if ($fixtureMatches.Count -ne 1) {
            throw (
                "$Owner target caller negative fixture '$($fixtureSpec.Name)' " +
                "found $($fixtureMatches.Count) targets, expected one.")
        }
        $mutatedSource = $fixtureRegex.Replace(
            $sourceText,
            $fixtureSpec.Replacement,
            1)
        if ($mutatedSource -ceq $sourceText) {
            throw (
                "$Owner target caller negative fixture '$($fixtureSpec.Name)' " +
                'did not mutate its source.')
        }
        $fixtureTcp = if ($fixtureSpec.Source -eq 'Tcp') {
            $mutatedSource
        }
        else {
            $tcpFixture
        }
        $fixtureControl = if ($fixtureSpec.Source -eq 'Control') {
            $mutatedSource
        }
        else {
            $controlFixture
        }
        $fixtureDiagnostics = if ($fixtureSpec.Source -eq 'Diagnostics') {
            $mutatedSource
        }
        else {
            $diagnosticsFixture
        }
        $negativeOwner = "$Owner target caller negative $($fixtureSpec.Name)"
        $negativeRejected = $false
        try {
            $null = Assert-LasalAxisOwnershipPublishCallerContract `
                -TcpText $fixtureTcp `
                -ControlServiceText $fixtureControl `
                -DiagnosticsText $fixtureDiagnostics `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    $negativeOwner,
                    [StringComparison]::Ordinal)) {
                throw (
                    "$Owner target caller negative fixture " +
                    "'$($fixtureSpec.Name)' failed outside its contract " +
                    "assertion: $($_.Exception.Message)")
            }
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner target caller contract accepted negative fixture " +
                "'$($fixtureSpec.Name)'.")
        }
        $negativeCount += 1
    }
    if ($negativeCount -ne 47) {
        throw "$Owner target caller negative count is not 47."
    }
    return [pscustomobject]@{
        NegativeCount = $negativeCount
        Target = $positiveResult
    }
}

function Assert-LasalAxisOwnershipReserveMutationFences {
    param(
        [string]$ReserveBlock,
        [string]$ControlServiceText,
        [string]$Owner,
        [switch]$SharedControlClosureAlreadyChecked
    )

    $blocker = "$Owner axis ownership reserve mutation blocker:"
    $controlScan = Get-LasalLexicalScanText $ControlServiceText
    if (-not $SharedControlClosureAlreadyChecked) {
        $null = Assert-LasalAxisOwnershipPublishStateContract `
            -ControlServiceText $ControlServiceText `
            -Owner $Owner
    }

    $lexicalReserveMatches = [regex]::Matches(
        $controlScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if ($lexicalReserveMatches.Count -ne 1) {
        throw "$blocker lexical reserve implementation scope drifted."
    }
    $scan = $lexicalReserveMatches[0].Value
    $rawReserveBlock = $ControlServiceText.Substring(
        $lexicalReserveMatches[0].Index,
        $lexicalReserveMatches[0].Length)
    if ([regex]::Matches(
            $rawReserveBlock,
            '"(?:[^"]|"")*"').Count -ne 0) {
        throw "$blocker raw reserve implementation may not contain strings."
    }
    if ((Get-LasalLexicalScanText $ReserveBlock).Trim() -cne
        $scan.Trim()) {
        throw "$blocker caller-supplied reserve block does not match raw source."
    }
    Assert-Match $scan (
        '(?is)^\s*FUNCTION\s+GLOBAL\s+' +
        'LMCControlCommandService::ReserveAxisOwnership\b.*?' +
        'END_FUNCTION\s*$') (
        "$blocker public reserve implementation scope drifted.")

    $abiBodyPattern = (
        'VAR_INPUT\s*' +
        'CommandId\s*:\s*UINT\s*;\s*' +
        'Reference\s*:\s*UINT\s*;\s*' +
        'RequestedAxisMask\s*:\s*UDINT\s*;\s*' +
        'OwnerKind\s*:\s*UINT\s*;\s*' +
        'ResourceKind\s*:\s*UINT\s*;\s*' +
        'AdmissionMode\s*:\s*UINT\s*;\s*' +
        'CallerSessionEpoch\s*:\s*UDINT\s*;\s*' +
        'RequestSequence\s*:\s*UDINT\s*;\s*' +
        'pIdentity\s*:\s*\^void\s*;\s*' +
        'IdentitySize\s*:\s*UDINT\s*;\s*' +
        'pEffectiveAxisMask\s*:\s*\^UDINT\s*;\s*' +
        'pAdmissionToken\s*:\s*\^UDINT\s*;\s*' +
        'pOwnerGeneration\s*:\s*\^UDINT\s*;\s*' +
        'END_VAR\s*;?\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
    $classAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+ReserveAxisOwnership\s*' +
         $abiBodyPattern + '\s*(?=FUNCTION\b)'))
    $implementationAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership\s*' +
         $abiBodyPattern + '\s*(?=VAR\b)'))
    $classHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION\b[^\r\n:]*\b' +
         'ReserveAxisOwnership\s*;?\s*$')).Count
    $implementationHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION\b[^\r\n]*\b' +
         'LMCControlCommandService::ReserveAxisOwnership\s*;?\s*$')).Count
    $anyHeaderCount = [regex]::Matches(
        $controlScan,
        ('(?is)(?<![A-Za-z0-9_])FUNCTION\b' +
         '(?:(?!\b(?:FUNCTION|VAR_INPUT|VAR_OUTPUT|VAR|' +
         'END_VAR|END_FUNCTION)\b|;).)*?' +
         '(?<![A-Za-z0-9_])ReserveAxisOwnership' +
         '(?=[^A-Za-z0-9_])')).Count
    if (($anyHeaderCount -ne 2) -or
        ($classHeaderCount -ne 1) -or
        ($implementationHeaderCount -ne 1) -or
        ($classAbiMatches.Count -ne 1) -or
        ($implementationAbiMatches.Count -ne 1)) {
        throw (
            "$blocker public declaration and implementation must expose " +
            'the exact closed thirteen-input/one-output ABI.')
    }
    $classBlockMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bLMCControlCommandService\s*:\s*CLASS\b.*?' +
         '\bEND_CLASS\s*;'))
    if ($classBlockMatches.Count -ne 1) {
        throw "$blocker exact class declaration block is missing."
    }
    $classAbiEnd = $classAbiMatches[0].Index + $classAbiMatches[0].Length
    $classBlockEnd = $classBlockMatches[0].Index + $classBlockMatches[0].Length
    if (($classAbiMatches[0].Index -lt $classBlockMatches[0].Index) -or
        ($classAbiEnd -gt $classBlockEnd)) {
        throw "$blocker public declaration escaped the class block."
    }
    $macroMatches = [regex]::Matches(
        $controlScan,
        ('(?im)^[^\S\r\n]*#[^\S\r\n]*define[^\S\r\n]+' +
         '[A-Za-z_][A-Za-z0-9_]*(?:[^\r\n]*)\r?$'))
    $firstCustomImplementationMatch = [regex]::Match(
        $controlScan,
        ('(?im)^\s*FUNCTION\s+' +
         'LMCControlCommandService::ReadAxisRebaseRequiredMask\s*$'))
    $implementationHeaders = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION(?:\s+GLOBAL)?(?:\s+TAB)?\s+' +
         'LMCControlCommandService::' +
         '(?<Name>@?[A-Za-z_][A-Za-z0-9_]*)\s*$'))
    $implementationHeaderInventory = @(
        foreach ($implementationHeader in $implementationHeaders) {
            $implementationHeader.Groups['Name'].Value.ToLowerInvariant()
        })
    $expectedImplementationHeaderInventory = @(
        '@ct_',
        '@std',
        'readaxisrebaserequiredmask',
        'updateaxisrebaserequiredstate',
        'handleaxisownershipsafetyrepeat',
        'handlerequest',
        'reserveaxisownership',
        'validateaxisownership',
        'commitaxisownership',
        'rollbackaxisownership',
        'publishaxisownership',
        'reconcileaxisownershipstartup',
        'notifyaxisownershipsessionclosed',
        'processaxisownership',
        'handleregistrycommands',
        'handleaxiscommands',
        'handlegroupcommands',
        'handleadmincommands',
        'movelinearabsex',
        'groupreadstatus',
        'processaxiszerohome',
        'handleaxiszerohomecommands',
        'validateaxisownershipidentity',
        'copyaxisownershippreemption',
        'publishaxisownershippreemptioncleanup',
        'publishaxisownershipds402receipt',
        'validateaxisownershippreemptionreplacement',
        'handleaxisownershipds402receiptstage87recovery',
        'validateaxisownershiprollbackpreemptbank')
    if ((Get-LasalAxisOwnershipPublishMode `
            -ControlServiceText $ControlServiceText) -ceq
        'SplitCandidate') {
        $expectedImplementationHeaderInventory += @(
            'handleaxisownershippublishhomereceipt',
            'prepareaxisownershippublishdecision')
    }
    if ([string]::Join('|', $implementationHeaderInventory) -cne
        [string]::Join('|', $expectedImplementationHeaderInventory)) {
        throw "$blocker whole implementation header inventory/order drifted."
    }
    $implementationStructureMatches = [regex]::Matches(
        $controlScan,
        ('(?i)(?:' +
         '\bFUNCTION(?:\s+GLOBAL)?(?:\s+TAB)?\s+' +
         'LMCControlCommandService::' +
         '(?<Name>@?[A-Za-z_][A-Za-z0-9_]*)\b' +
         '|(?<End>\bEND_FUNCTION\b))'))
    $implementationStructureEvents = @(
        foreach ($structureEvent in $implementationStructureMatches) {
            if ($structureEvent.Groups['End'].Success) {
                '<end>'
            }
            else {
                $structureEvent.Groups['Name'].Value.ToLowerInvariant()
            }
        })
    $expectedImplementationStructureEvents = @(
        foreach ($implementationName in
            $expectedImplementationHeaderInventory) {
            $implementationName
            '<end>'
        })
    if ([string]::Join('|', $implementationStructureEvents) -cne
        [string]::Join('|', $expectedImplementationStructureEvents)) {
        throw "$blocker implementation header/end structural order drifted."
    }
    $reserveHeaderIndex = -1
    for ($headerIndex = 0;
         $headerIndex -lt $implementationHeaders.Count;
         $headerIndex++) {
        if ($implementationHeaders[$headerIndex].Groups['Name'].Value -ceq
            'ReserveAxisOwnership') {
            $reserveHeaderIndex = $headerIndex
        }
    }
    if (($macroMatches.Count -eq 0) -or
        (-not $firstCustomImplementationMatch.Success) -or
        ($reserveHeaderIndex -le 0) -or
        ($reserveHeaderIndex -ge ($implementationHeaders.Count - 1)) -or
        ($implementationHeaders[$reserveHeaderIndex].Index -le
            $macroMatches[-1].Index) -or
        ($implementationHeaders[$reserveHeaderIndex].Index -le
            $firstCustomImplementationMatch.Index) -or
        ($implementationHeaders[$reserveHeaderIndex - 1].Groups['Name'].Value -cne
            'HandleRequest') -or
        ($implementationHeaders[$reserveHeaderIndex + 1].Groups['Name'].Value -cne
            'ValidateAxisOwnership')) {
        throw "$blocker implementation prerequisite/location/order drifted."
    }
    $firstCustomHeaderIndex = -1
    for ($headerIndex = 0;
         $headerIndex -lt $implementationHeaders.Count;
         $headerIndex++) {
        if ($implementationHeaders[$headerIndex].Groups['Name'].Value -ceq
            'ReadAxisRebaseRequiredMask') {
            $firstCustomHeaderIndex = $headerIndex
        }
    }
    if ($firstCustomHeaderIndex -lt 0) {
        throw "$blocker first custom implementation header drifted."
    }
    $firstCustomHeaderEvent =
        $implementationStructureMatches[$firstCustomHeaderIndex * 2]
    $lastMacroEnd = $macroMatches[-1].Index + $macroMatches[-1].Length
    if (($lastMacroEnd -gt $firstCustomHeaderEvent.Index) -or
        ($controlScan.Substring(
            $lastMacroEnd,
            $firstCustomHeaderEvent.Index - $lastMacroEnd) -notmatch
            '\A[ \t\r\n]*\z')) {
        throw "$blocker macro-to-custom boundary closure drifted."
    }
    for ($customHeaderIndex = $firstCustomHeaderIndex;
         $customHeaderIndex -lt $implementationHeaders.Count;
         $customHeaderIndex++) {
        $customHeaderEventIndex = $customHeaderIndex * 2
        $customHeaderEvent =
            $implementationStructureMatches[$customHeaderEventIndex]
        $customEndEvent =
            $implementationStructureMatches[$customHeaderEventIndex + 1]
        $customFunctionName =
            $implementationHeaders[$customHeaderIndex].Groups['Name'].Value
        $customFunctionText = $controlScan.Substring(
            $customHeaderEvent.Index,
            ($customEndEvent.Index + $customEndEvent.Length) -
                $customHeaderEvent.Index)
        $blockStack =
            [Collections.Generic.List[string]]::new()
        $blockClosers = @{
            'END_IF' = 'IF'
            'END_CASE' = 'CASE'
            'END_FOR' = 'FOR'
            'END_WHILE' = 'WHILE'
            'END_REPEAT' = 'REPEAT'
        }
        foreach ($blockTokenMatch in [regex]::Matches(
                $customFunctionText,
                ('(?i)\b(?:END_IF|END_CASE|END_FOR|END_WHILE|' +
                 'END_REPEAT|IF|CASE|FOR|WHILE|REPEAT)\b'))) {
            $blockToken = $blockTokenMatch.Value.ToUpperInvariant()
            if ($blockClosers.ContainsKey($blockToken)) {
                if (($blockStack.Count -eq 0) -or
                    ($blockStack[$blockStack.Count - 1] -cne
                        $blockClosers[$blockToken])) {
                    throw (
                        "$blocker custom function block order drifted for " +
                        "$customFunctionName at $blockToken.")
                }
                $blockStack.RemoveAt($blockStack.Count - 1)
            }
            else {
                $blockStack.Add($blockToken)
            }
        }
        if ($blockStack.Count -ne 0) {
            throw (
                "$blocker custom function block closure drifted for " +
                "$customFunctionName at " +
                $blockStack[$blockStack.Count - 1] + '.')
        }
        if ($customHeaderIndex -lt
            ($implementationHeaders.Count - 1)) {
            $nextCustomHeaderEvent =
                $implementationStructureMatches[$customHeaderEventIndex + 2]
            $customGapStart =
                $customEndEvent.Index + $customEndEvent.Length
            if ($controlScan.Substring(
                    $customGapStart,
                    $nextCustomHeaderEvent.Index - $customGapStart) -notmatch
                '\A[ \t\r\n]*\z') {
                throw "$blocker custom implementation gap closure drifted."
            }
        }
        else {
            $finalCustomEnd =
                $customEndEvent.Index + $customEndEvent.Length
            if ($controlScan.Substring($finalCustomEnd) -notmatch
                '\A[ \t\r\n]*\z') {
                throw "$blocker final custom boundary closure drifted."
            }
        }
    }
    $reserveStructureEventIndex = $reserveHeaderIndex * 2
    $handleRequestEndEvent =
        $implementationStructureMatches[$reserveStructureEventIndex - 1]
    $reserveHeaderEvent =
        $implementationStructureMatches[$reserveStructureEventIndex]
    $reserveEndEvent =
        $implementationStructureMatches[$reserveStructureEventIndex + 1]
    $validateHeaderEvent =
        $implementationStructureMatches[$reserveStructureEventIndex + 2]
    $beforeReserveGapStart =
        $handleRequestEndEvent.Index + $handleRequestEndEvent.Length
    $afterReserveGapStart =
        $reserveEndEvent.Index + $reserveEndEvent.Length
    $beforeReserveGap = $controlScan.Substring(
        $beforeReserveGapStart,
        $reserveHeaderEvent.Index - $beforeReserveGapStart)
    $afterReserveGap = $controlScan.Substring(
        $afterReserveGapStart,
        $validateHeaderEvent.Index - $afterReserveGapStart)
    if (($beforeReserveGap -notmatch '\A[ \t\r\n]*\z') -or
        ($afterReserveGap -notmatch '\A[ \t\r\n]*\z')) {
        throw "$blocker implementation neighbor gap closure drifted."
    }

    $pointerDeclarations = @(
        [regex]::Matches(
            $scan,
            ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
             '(?<Type>\^[A-Za-z_][A-Za-z0-9_]*)\s*;')) |
            ForEach-Object {
                ($_.Groups['Name'].Value + ':' +
                 $_.Groups['Type'].Value).ToLowerInvariant()
            })
    $expectedPointerDeclarations = @(
        'pidentity:^void',
        'peffectiveaxismask:^udint',
        'padmissiontoken:^udint',
        'pownergeneration:^udint',
        'pidentitybytes:^usint')
    if ([string]::Join('|', $pointerDeclarations) -cne
        [string]::Join('|', $expectedPointerDeclarations)) {
        throw "$blocker pointer declaration inventory/order drifted."
    }
    $pointerAliasAssignments = @(
        [regex]::Matches(
            $scan,
            '(?is)\bpIdentityBytes\s*:=\s*[^;]+;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    if (($pointerAliasAssignments.Count -ne 1) -or
        ($pointerAliasAssignments[0] -cne
            'pidentitybytes:=pidentity$^usint;')) {
        throw "$blocker identity pointer alias assignment drifted."
    }
    $outputPointerWrites = @(
        [regex]::Matches(
            $scan,
            ('(?is)\bp(?:EffectiveAxisMask|AdmissionToken|' +
             'OwnerGeneration)\s*\^\s*:=\s*[^;]+;')) |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $expectedOutputPointerWrites = @(
        'peffectiveaxismask^:=0;',
        'padmissiontoken^:=0;',
        'pownergeneration^:=0;',
        'peffectiveaxismask^:=repeataxismask;',
        'padmissiontoken^:=repeatadmissiontoken;',
        'pownergeneration^:=repeatownergeneration;',
        'peffectiveaxismask^:=effectiveaxismask;',
        'padmissiontoken^:=nexttoken;',
        'pownergeneration^:=nextgeneration;')
    if ([string]::Join('|', $outputPointerWrites) -cne
        [string]::Join('|', $expectedOutputPointerWrites)) {
        throw "$blocker output pointer write inventory/order drifted."
    }
    if ($scan -match
            ('(?is)\b[A-Za-z_][A-Za-z0-9_]*\s*\.\s*' +
             '[A-Za-z_][A-Za-z0-9_]*\s*\(|\b_gettime\s*\(')) {
        throw "$blocker reserve may not call a client method or clock."
    }
    $ambientFieldReads = @(
        [regex]::Matches(
            $scan,
            '(?i)\b[A-Za-z_][A-Za-z0-9_]*\s*\.\s*[A-Za-z_][A-Za-z0-9_]*') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    if ([string]::Join('|', $ambientFieldReads) -cne
        'ops.tabsolute|ops.tabsolute') {
        throw "$blocker ambient field read inventory drifted."
    }

    $localVarMatch = [regex]::Match(
        $scan,
        ('(?ims)^\s*VAR\s*$\s*(?<Body>.*?)^\s*END_VAR\s*$' +
         '(?=\s*Result\s*:=)'))
    if (-not $localVarMatch.Success) {
        throw "$blocker local variable block is missing."
    }
    $localInventory = @(
        [regex]::Matches(
            $localVarMatch.Groups['Body'].Value,
            ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
             '(?<Type>[^;]+)\s*;')) |
            ForEach-Object {
                ($_.Groups['Name'].Value + ':' +
                 [regex]::Replace($_.Groups['Type'].Value, '\s+', '')
                ).ToLowerInvariant()
            })
    $joinedLocals = [string]::Join('|', $localInventory)
    $localSha = [Security.Cryptography.SHA256]::Create()
    try {
        $localSha256 = (
            [BitConverter]::ToString(
                $localSha.ComputeHash(
                    [Text.Encoding]::UTF8.GetBytes($joinedLocals)))
        ).Replace('-', '')
    }
    finally {
        $localSha.Dispose()
    }
    if (($localInventory.Count -ne 81) -or
        ($joinedLocals.Length -ne 1817) -or
        ($localSha256 -cne
            '55ACBC2438AE68FAE362C479F4B9EB2ADD3F416180DBE863AD78729BE9F4DFF1')) {
        throw (
            "$blocker local variable inventory drifted " +
            "($($localInventory.Count)/81, " +
            "$($joinedLocals.Length)/1817, $localSha256).")
    }

    $ignoredCallNames = @(
        'and', 'else', 'elsif', 'if', 'not', 'or', 'then')
    $expectedCallHistogram = [ordered]@{
        '_memcmp' = 4
        '_memcpy' = 7
        '_memset' = 8
        'copyaxisownershippreemption' = 2
        'readaxisrebaserequiredmask' = 1
        'sizeof' = 7
        'to_dint' = 14
        'to_udint' = 45
        'validateaxisownershipidentity' = 2
    }
    $actualCallHistogram = [ordered]@{}
    foreach ($callMatch in [regex]::Matches(
            $scan,
            ('(?i)(?<![A-Za-z0-9_])' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*\('))) {
        $callName = $callMatch.Groups['Name'].Value.ToLowerInvariant()
        if ($ignoredCallNames -contains $callName) {
            continue
        }
        if (-not $expectedCallHistogram.Contains($callName)) {
            throw "$blocker unsupported call '$callName'."
        }
        if (-not $actualCallHistogram.Contains($callName)) {
            $actualCallHistogram[$callName] = 0
        }
        $actualCallHistogram[$callName]++
    }
    foreach ($callName in $expectedCallHistogram.Keys) {
        $actualCount = if ($actualCallHistogram.Contains($callName)) {
            $actualCallHistogram[$callName]
        }
        else {
            0
        }
        if ($actualCount -ne $expectedCallHistogram[$callName]) {
            throw (
                "$blocker call '$callName' count is $actualCount, expected " +
                "$($expectedCallHistogram[$callName]).")
        }
    }

    Assert-Match $scan (
        '(?is)END_VAR\s*Result\s*:=\s*-1\s*;\s*' +
        'if\s*\(pEffectiveAxisMask\s*=\s*NIL\)\s*\|\s*' +
        '\(pAdmissionToken\s*=\s*NIL\)\s*\|\s*' +
        '\(pOwnerGeneration\s*=\s*NIL\)\s+then\s*RETURN\s*;\s*' +
        'end_if\s*;\s*pEffectiveAxisMask\^\s*:=\s*0\s*;\s*' +
        'pAdmissionToken\^\s*:=\s*0\s*;\s*' +
        'pOwnerGeneration\^\s*:=\s*0\s*;') (
        "$blocker fail-closed pointer guard or zero publication drifted.")
    Assert-Match $scan (
        '(?is)if\s*\(ZeroHomeState\[60\]\s*=\s*0\).*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_INTENT.*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED.*?' +
        'Result\s*:=\s*-2\s*;\s*else\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
        'Result\s*:=\s*-3\s*;\s*end_if\s*;\s*RETURN\s*;') (
        "$blocker incomplete durable Home receipt handling drifted.")
    Assert-Match $scan (
        '(?is)if\s+ZeroHomeState\[60\]\s*<>\s*0\s+then\s*' +
        'if\s*\(ZeroHomeState\[60\]\$UDINT\s*<>\s*' +
        'LMC_HOME_OWNER_RECEIPT_MAGIC\).*?' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'if\s*\(ZeroHomeState\[61\]\s*<>\s*' +
        'LMC_HOME_OWNER_RECEIPT_COMPLETE\).*?' +
        'Result\s*:=\s*-2\s*;\s*RETURN\s*;\s*end_if\s*;\s*' +
        'end_if\s*;\s*effectiveAxisMask\s*:=\s*RequestedAxisMask\s*;') (
        "$blocker completed durable Home receipt validation order drifted.")
    Assert-Match $scan (
        '(?is)if\s*\(RequestedAxisMask\s*=\s*0\)\s*\|\s*' +
        '\(RequestedAxisMask\s*>\s*LMC_OWNER_ROBOT_AXIS_MASK\).*?' +
        '\(IdentitySize\s*>\s*1320\)\s*\|\s*' +
        '\(pIdentity\s*=\s*NIL\)\s+then\s*RETURN\s*;\s*end_if\s*;\s*' +
        'pIdentityBytes\s*:=\s*pIdentity\$\^USINT\s*;') (
        "$blocker request domain or identity pointer gate drifted.")
    Assert-Match $scan (
        '(?is)if\s+LMC_AXIS_REBASE_BARRIER_ENABLED\s+then\s*' +
        'rebaseReadResult\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;\s*' +
        'rebaseAxisMask\s*:=\s*TO_UDINT\(rebaseReadResult\)\s*;.*?' +
        'if\s*\(\(effectiveAxisMask\s+and\s+rebaseAxisMask\)\s*<>\s*0\)' +
        '\s*&\s*\(rebaseAdmissionAllowed\s*=\s*FALSE\)\s+then\s*' +
        'Result\s*:=\s*-2\s*;\s*RETURN\s*;\s*end_if\s*;\s*end_if\s*;') (
        "$blocker retained rebase admission barrier drifted.")
    Assert-Match $scan (
        '(?is)if\s+repeatMode\s*>\s*0\s+then.*?' +
        'if\s+repeatPreemptCopyResult\s*<>\s*-4\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;\s*end_if\s*;.*?' +
        'pEffectiveAxisMask\^\s*:=\s*repeatAxisMask\s*;\s*' +
        'pAdmissionToken\^\s*:=\s*repeatAdmissionToken\s*;\s*' +
        'pOwnerGeneration\^\s*:=\s*repeatOwnerGeneration\s*;\s*' +
        'Result\s*:=\s*repeatMode\s*;\s*RETURN\s*;\s*end_if\s*;') (
        "$blocker repeat proof or mutation-free output publication drifted.")

    $persistentMutationPattern = (
        '(?is)(?:' +
        '\bOwnership[A-Za-z0-9_]*State\s*\[[^\]]+\]\s*' +
        '(?:\$[A-Za-z_][A-Za-z0-9_]*\s*)?' +
        '(?::|\+|-|\*|/|and|or|xor)\s*=\s*[^;]+;' +
        '|' +
        '\b_memset\s*\(\s*dest\s*:=\s*' +
        '#Ownership[A-Za-z0-9_]*State\s*\[.*?\)\s*;' +
        '|' +
        '\b_memcpy\s*\(\s*ptr1\s*:=\s*' +
        '#Ownership[A-Za-z0-9_]*State\s*\[.*?\)\s*;' +
        '|' +
        '\bp(?:EffectiveAxisMask|AdmissionToken|OwnerGeneration)\s*' +
        '\^\s*:=\s*[^;]+;' +
        ')')
    $persistentMutations = [regex]::Matches(
        $scan,
        $persistentMutationPattern)
    $normalizedMutations = @(
        foreach ($mutation in $persistentMutations) {
            [regex]::Replace(
                $mutation.Value,
                '\s+',
                '').ToLowerInvariant()
        })
    $joinedMutations = [string]::Join('|', $normalizedMutations)
    $mutationSha = [Security.Cryptography.SHA256]::Create()
    try {
        $mutationSha256 = (
            [BitConverter]::ToString(
                $mutationSha.ComputeHash(
                    [Text.Encoding]::UTF8.GetBytes($joinedMutations)))
        ).Replace('-', '')
    }
    finally {
        $mutationSha.Dispose()
    }
    if (($persistentMutations.Count -ne 110) -or
        ($joinedMutations.Length -ne 7306) -or
        ($mutationSha256 -cne
            'BBBDA2CFB2BD1763D08D26EC7AF10E0CC18D0A57DEF34A91461B1ABA56869361')) {
        throw (
            "$blocker persistent/output mutation inventory/order drifted " +
            "($($persistentMutations.Count)/110, " +
            "$($joinedMutations.Length)/7306, $mutationSha256).")
    }
    $mutationMarkers = [ordered]@{
        0 = 'peffectiveaxismask^:=0;'
        1 = 'padmissiontoken^:=0;'
        2 = 'pownergeneration^:=0;'
        12 = 'peffectiveaxismask^:=repeataxismask;'
        14 = 'pownergeneration^:=repeatownergeneration;'
        15 = 'ownershipleaseidentitystate[lmc_owner_lease_identity_header_base]:=0;'
        21 = ('ownershipleaseidentitystate[' +
              'lmc_owner_lease_identity_header_base]$udint:=' +
              'lmc_owner_lease_identity_magic;')
        22 = ('ownershippreemptedidentitystate[' +
              'lmc_owner_preempt_header_base]:=0;')
        38 = ('ownershippreemptedidentitystate[' +
              'lmc_owner_preempt_header_base]$udint:=' +
              'lmc_owner_preempt_identity_magic;')
        39 = 'ownershipstate[1]$udint:=nexttoken;'
        40 = 'ownershipstate[2]$udint:=nextgeneration;'
        41 = 'ownershipidentitystate[identityheaderbase]:=0;'
        42 = ('ownershipidentitystate[' +
              'lmc_owner_identity_group_header_base]:=0;')
        74 = ('ownershipstate[recordbase+35]$udint:=' +
              'lmc_owner_axis_record_magic+to_udint(axisindex);')
        87 = ('ownershipidentitystate[identityheaderbase]$udint:=' +
              'lmc_owner_identity_axis_magic+to_udint(axisindex);')
        97 = ('ownershipidentitystate[identityheaderbase]$udint:=' +
              'lmc_owner_identity_group_magic;')
        98 = 'ownershipstate[7]$udint:=nexttoken;'
        106 = 'ownershipstate[15]$udint:=effectiveaxismask;'
        107 = 'peffectiveaxismask^:=effectiveaxismask;'
        109 = 'pownergeneration^:=nextgeneration;'
    }
    foreach ($marker in $mutationMarkers.GetEnumerator()) {
        if ($normalizedMutations[$marker.Key] -cne $marker.Value) {
            throw "$blocker mutation marker $($marker.Key + 1) drifted."
        }
    }
    for ($mutationIndex = 3; $mutationIndex -le 11; $mutationIndex++) {
        if ($normalizedMutations[$mutationIndex] -cne
            'ownershipstate[24]:=1;') {
            throw "$blocker corrupt-bank latch inventory drifted."
        }
    }
    $firstCapturePosition = $persistentMutations[15].Index
    $repeatExitPosition = $scan.IndexOf(
        'pOwnerGeneration^ := repeatOwnerGeneration;')
    if (($repeatExitPosition -lt 0) -or
        ($repeatExitPosition -ge $firstCapturePosition)) {
        throw "$blocker repeat exit is not complete before bank publication."
    }

    $resultSequence = [string]::Join(
        '|',
        @([regex]::Matches(
                $scan,
                '(?is)\bResult\s*:=\s*(?<Value>[^;]+)\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Groups['Value'].Value,
                    '\s+',
                    '').ToLowerInvariant()
            }))
    $expectedResultSequence = (
        '-1|-2|-3|-3|-2|-3|-3|-2|-3|-3|-3|-3|-3|-3|-3|-2|-2|' +
        '-2|-3|-3|-3|-3|-3|-3|-3|-3|-2|-3|-3|-2|-3|-3|-2|-3|' +
        '-3|-2|-3|-3|-3|-3|-3|-3|-3|-3|-2|-3|-2|-3|-2|-3|-3|' +
        '-3|-3|-3|repeatmode|0')
    if ($resultSequence -cne $expectedResultSequence) {
        throw "$blocker Result value/count/order inventory drifted."
    }
    $controlFlowTokens = @(
        [regex]::Matches(
            $scan,
            '(?is)\bResult\s*:=\s*[^;]+\s*;|\bRETURN\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $controlFlowInventory = [string]::Join('|', $controlFlowTokens)
    $controlFlowSha = [Security.Cryptography.SHA256]::Create()
    try {
        $controlFlowSha256 = (
            [BitConverter]::ToString(
                $controlFlowSha.ComputeHash(
                    [Text.Encoding]::UTF8.GetBytes($controlFlowInventory)))
        ).Replace('-', '')
    }
    finally {
        $controlFlowSha.Dispose()
    }
    if (($controlFlowTokens.Count -ne 127) -or
        ($controlFlowInventory.Length -ne 1246) -or
        ($controlFlowSha256 -cne
            '5F438EDB025A88529A2C14326DCC1FEDE9D19ED44A56FAC3645E4B7AF8AF1154')) {
        throw (
            "$blocker Result/RETURN control-flow inventory drifted " +
            "($($controlFlowTokens.Count)/127, " +
            "$($controlFlowInventory.Length)/1246, $controlFlowSha256).")
    }
    Assert-Match $scan (
        '(?is)case\s+ResourceKind\s+of\s*' +
        'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\s*:.*?' +
        'OwnershipState\[7\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE\s*:.*?' +
        'OwnershipState\[10\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE\s*:.*?' +
        'OwnershipState\[13\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        'end_case\s*;\s*pEffectiveAxisMask\^\s*:=\s*effectiveAxisMask\s*;\s*' +
        'pAdmissionToken\^\s*:=\s*nextToken\s*;\s*' +
        'pOwnerGeneration\^\s*:=\s*nextGeneration\s*;\s*' +
        'Result\s*:=\s*0\s*;\s*END_FUNCTION\s*$') (
        "$blocker singleton and final output publication order drifted.")

    # Keep the two token ratchets final so targeted assertions explain known
    # safety drift first. Comments, case, whitespace, and newline style remain
    # outside the executable contract.
    $semanticTokens = [regex]::Replace(
        $scan,
        '\s+',
        '').ToLowerInvariant()
    $semanticSha = [Security.Cryptography.SHA256]::Create()
    try {
        $semanticSha256 = (
            [BitConverter]::ToString(
                $semanticSha.ComputeHash(
                    [Text.Encoding]::UTF8.GetBytes($semanticTokens)))
        ).Replace('-', '')
    }
    finally {
        $semanticSha.Dispose()
    }
    if (($semanticTokens.Length -ne 60886) -or
        ($semanticSha256 -cne
            '9E0A14511F49B47D174CECC978749BAE5C8B4D42D5E934A020BEC2158322C85E')) {
        throw (
            "$blocker normalized semantic token inventory drifted " +
            "($($semanticTokens.Length)/60886, $semanticSha256).")
    }
    $lexicalTokens = @(
        [regex]::Matches(
            $scan,
            ('(?i)0x[0-9a-f]+|[A-Za-z_][A-Za-z0-9_]*|\d+|' +
             ':=|<>|<=|>=|\+=|-=|\*=|/=|[^\s]')) |
            ForEach-Object { $_.Value.ToLowerInvariant() })
    $lexicalInventory = [string]::Join('|', $lexicalTokens)
    $lexicalSha = [Security.Cryptography.SHA256]::Create()
    try {
        $lexicalSha256 = (
            [BitConverter]::ToString(
                $lexicalSha.ComputeHash(
                    [Text.Encoding]::UTF8.GetBytes($lexicalInventory)))
        ).Replace('-', '')
    }
    finally {
        $lexicalSha.Dispose()
    }
    if (($lexicalTokens.Count -ne 11839) -or
        ($lexicalInventory.Length -ne 72724) -or
        ($lexicalSha256 -cne
            'F13EDA75E7EFF379D407E88EC5CE2C37BA3445A3FED0C7D59B3DB9C53517246F')) {
        throw (
            "$blocker lexical token boundary inventory drifted " +
            "($($lexicalTokens.Count)/11839, " +
            "$($lexicalInventory.Length)/72724, $lexicalSha256).")
    }
}

function Invoke-LasalAxisOwnershipReserveVerifierSelfTest {
    param(
        [string]$ControlServiceText,
        [string]$Owner
    )

    $fixtureSpecs = @(
        @{
            Name = 'ImplementationRenamed'
            Pattern = (
                '(?im)^(\s*FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::)ReserveAxisOwnership\s*$')
            Replacement = '${1}ReserveAxisOwnershipShadow'
        },
        @{
            Name = 'DuplicateImplementationHeaderAdded'
            Pattern = (
                '(?im)^([^\S\r\n]*FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership)' +
                '([^\S\r\n]*)(?<Eol>\r?\n)')
            Replacement = (
                '${1}${2}${Eol}' +
                'FUNCTION LMCControlCommandService::ReserveAxisOwnership' +
                '${Eol}')
        },
        @{
            Name = 'ClassAbiCommandIdTypeChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+ReserveAxisOwnership\s*' +
                'VAR_INPUT\s*CommandId\s*:\s*)UINT')
            Replacement = '${1}UDINT'
        },
        @{
            Name = 'ImplementationAbiIdentityPointerChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership\s*' +
                'VAR_INPUT.*?\bpIdentity\s*:\s*)\^void')
            Replacement = '${1}^UDINT'
        },
        @{
            Name = 'ClassAbiTrailingInputAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+ReserveAxisOwnership\s*' +
                'VAR_INPUT.*?\bpOwnerGeneration\s*:\s*\^UDINT\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`t`tUnexpectedInput : UDINT;")
        },
        @{
            Name = 'ImplementationAbiResultTypeChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership\s*' +
                'VAR_INPUT.*?VAR_OUTPUT\s*Result\s*:\s*)DINT')
            Replacement = '${1}UDINT'
        },
        @{
            Name = 'LocalRepeatArrayBoundChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'repeatPreemptProbe\s*:\s*ARRAY\s*\[\s*0\.\.)35')
            Replacement = '${1}34'
        },
        @{
            Name = 'LocalIdentityPointerTypeChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                '\bpIdentityBytes\s*:\s*)\^USINT')
            Replacement = '${1}^UDINT'
        },
        @{
            Name = 'IdentityPointerAliasCastChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'pIdentityBytes\s*:=\s*pIdentity\$)\^USINT')
            Replacement = '${1}^UDINT'
        },
        @{
            Name = 'InitialAdmissionTokenOutputNonzero'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'pAdmissionToken\^\s*:=\s*)0(\s*;)')
            Replacement = '${1}1${2}'
        },
        @{
            Name = 'RepeatGenerationOutputChanged'
            Pattern = (
                '(?is)(if\s+repeatMode\s*>\s*0\s+then.*?' +
                'pOwnerGeneration\^\s*:=\s*)repeatOwnerGeneration')
            Replacement = '${1}nextGeneration'
        },
        @{
            Name = 'FinalAdmissionTokenOutputChanged'
            Pattern = (
                '(?is)(case\s+ResourceKind\s+of.*?end_case\s*;\s*' +
                'pEffectiveAxisMask\^\s*:=\s*effectiveAxisMask\s*;\s*' +
                'pAdmissionToken\^\s*:=\s*)nextToken')
            Replacement = '${1}nextGeneration'
        },
        @{
            Name = 'RawStringAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine + "`t`"reserve`";")
        },
        @{
            Name = 'UnexpectedClientCallAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tAxisClient.ReadStatus();")
        },
        @{
            Name = 'UnexpectedClockCallAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine + "`t_gettime();")
        },
        @{
            Name = 'UnexpectedHelperCallAdded'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                '\bResult\s*:=\s*-1\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`trebaseReadResult := UnknownReserveHelper();")
        },
        @{
            Name = 'AmbientCycleFieldChanged'
            Pattern = (
                '(?is)(OwnershipState\[recordBase\s*\+\s*8\]\$UDINT\s*' +
                ':=\s*ops\.tAbsolute\s*;\s*' +
                'OwnershipState\[recordBase\s*\+\s*9\]\$UDINT\s*:=\s*)' +
                'ops\.tAbsolute')
            Replacement = '${1}ops.tCurrent'
        },
        @{
            Name = 'RebaseHelperRenamed'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'rebaseReadResult\s*:=\s*)ReadAxisRebaseRequiredMask')
            Replacement = '${1}ReadAxisRebaseRequiredMaskShadow'
        },
        @{
            Name = 'ReservedIdentityValidationHelperRenamed'
            Pattern = (
                '(?is)(repeatState\s*=\s*LMC_OWNER_STATE_RESERVED\s+then\s*' +
                'repeatValidationResult\s*:=\s*)' +
                'ValidateAxisOwnershipIdentity')
            Replacement = '${1}ValidateAxisOwnershipIdentityShadow'
        },
        @{
            Name = 'FirstPreemptionCopyHelperRenamed'
            Pattern = (
                '(?is)(if\s+repeatRootPresent\s+then\s*' +
                'axisIndex\s*:=\s*1\s*;.*?' +
                'repeatPreemptCopyResult\s*:=\s*)' +
                'CopyAxisOwnershipPreemption')
            Replacement = '${1}CopyAxisOwnershipPreemptionShadow'
