            Pattern = (
                '(?is)(\(\(liveNonGroupMask\s+and\s+' +
                'RequestedAxisMask\)\s*<>\s*)liveNonGroupMask(\))')
            Replacement = '${1}RequestedAxisMask${2}'
        },
        @{
