                '\(liveNonGroupFound\s*=\s*FALSE\)\s+then\s*)' +
                'if\s+leaseAvailable\s+then')
            Replacement = '${1}if FALSE then'
        },
        @{
            Name = 'DirtyObserverAccepted'
            Pattern = (
                '(?is)(if\s+\(OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\).*?' +
                'OwnershipObserverState\[' +
                'observerBase\s*\+\s*observerIndex\]\s*)<>(\s*0)')
            Replacement = '${1}=${2}'
        },
        @{
            Name = 'RepeatIdentityValidationInverted'
            Pattern = (
                '(?is)(repeatValid\s*:=\s*repeatValidationResult\s*)=(\s*0)')
            Replacement = '${1}<>${2}'
        },
        @{
            Name = 'FinalRepeatPreemptCopyProofChanged'
            Pattern = (
                '(?is)(if\s+repeatMode\s*>\s*0\s+then.*?' +
                'if\s+repeatPreemptCopyResult\s*<>)\s*-4')
            Replacement = '${1} 0'
        },
        @{
            Name = 'LeaseMagicLastChanged'
            Pattern = (
                '(?is)(if\s+leaseCapture\s+then.*?' +
                'OwnershipLeaseIdentityState\[\s*' +
                'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\]\$UDINT\s*:=\s*)' +
                'LMC_OWNER_LEASE_IDENTITY_MAGIC')
            Replacement = '${1}LMC_OWNER_PREEMPT_IDENTITY_MAGIC'
        },
        @{
            Name = 'PreemptMagicLastChanged'
            Pattern = (
                '(?is)(if\s+preemptCapture\s+then.*?' +
                'OwnershipPreemptedIdentityState\[\s*' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*:=\s*)' +
                'LMC_OWNER_PREEMPT_IDENTITY_MAGIC')
            Replacement = '${1}LMC_OWNER_LEASE_IDENTITY_MAGIC'
        },
        @{
            Name = 'LiveRecordMagicChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'OwnershipState\[recordBase\s*\+\s*35\]' +
                '\$UDINT\s*:=\s*)LMC_OWNER_AXIS_RECORD_MAGIC')
            Replacement = '${1}LMC_OWNER_TABLE_MAGIC'
        },
        @{
            Name = 'AxisIdentityMagicChanged'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::ReserveAxisOwnership.*?' +
                'OwnershipIdentityState\[identityHeaderBase\]' +
                '\$UDINT\s*:=\s*)LMC_OWNER_IDENTITY_AXIS_MAGIC' +
                '(\s*\+\s*TO_UDINT\(axisIndex\))')
            Replacement = '${1}LMC_OWNER_IDENTITY_GROUP_MAGIC${2}'
        },
        @{
            Name = 'GroupIdentityMagicChanged'
            Pattern = (
                '(?is)(if\s+OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP.*?' +
                'OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*:=\s*)' +
                'LMC_OWNER_IDENTITY_GROUP_MAGIC')
            Replacement = '${1}LMC_OWNER_IDENTITY_AXIS_MAGIC'
        },
        @{
            Name = 'HomeSingletonTokenChanged'
            Pattern = (
                '(?is)(LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\s*:\s*' +
                'OwnershipState\[7\]\$UDINT\s*:=\s*)nextToken')
            Replacement = '${1}nextGeneration'
        },
        @{
            Name = 'RepeatResultChanged'
            Pattern = (
                '(?is)(pOwnerGeneration\^\s*:=\s*' +
                'repeatOwnerGeneration\s*;\s*Result\s*:=\s*)repeatMode')
            Replacement = '${1}0'
        },
        @{
            Name = 'FinalResultChanged'
            Pattern = (
                '(?is)(pOwnerGeneration\^\s*:=\s*nextGeneration\s*;\s*' +
                'Result\s*:=\s*)0(\s*;\s*END_FUNCTION)')
            Replacement = '${1}1${2}'
        }
    )

    $negativeFixtures = [ordered]@{}
    foreach ($fixture in $fixtureSpecs) {
        $fixtureRegex = [regex]::new(
            $fixture.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline -bor
            [Text.RegularExpressions.RegexOptions]::Multiline)
        $fixtureMatches = $fixtureRegex.Matches($ControlServiceText)
        if ($fixtureMatches.Count -ne 1) {
            throw (
                "$Owner reserve negative fixture '$($fixture.Name)' found " +
                "$($fixtureMatches.Count) targets, expected one.")
        }
        $mutatedFixture = $fixtureRegex.Replace(
            $ControlServiceText,
            $fixture.Replacement,
            1)
        if ($mutatedFixture -match '\r(?!\n)') {
            throw (
                "$Owner reserve negative fixture '$($fixture.Name)' " +
                'introduced a bare carriage return.')
        }
        $negativeFixtures[$fixture.Name] = $mutatedFixture
    }
    $relocationScan = Get-LasalLexicalScanText $ControlServiceText
    $relocationReserveMatches = [regex]::Matches(
        $relocationScan,
        ('(?ims)^FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership[^\r\n]*\r?\n' +
         '.*?^END_FUNCTION[^\S\r\n]*(?<Eol>\r?\n)'))
    if ($relocationReserveMatches.Count -ne 1) {
        throw "$Owner reserve relocation fixture lost its source block."
    }
    $relocationBlock = $ControlServiceText.Substring(
        $relocationReserveMatches[0].Index,
        $relocationReserveMatches[0].Length)
    $withoutReserve = $ControlServiceText.Remove(
        $relocationReserveMatches[0].Index,
        $relocationReserveMatches[0].Length)
    $withoutReserveScan = Get-LasalLexicalScanText $withoutReserve
    $firstDefineMatch = [regex]::Match(
        $withoutReserveScan,
        ('(?im)^[^\S\r\n]*#[^\S\r\n]*define[^\S\r\n]+' +
         '[A-Za-z_][A-Za-z0-9_]*'))
    if (-not $firstDefineMatch.Success) {
        throw "$Owner reserve relocation fixture lost the macro region."
    }
    $relocatedFixture = $withoutReserve.Insert(
        $firstDefineMatch.Index,
        $relocationBlock)
    if ($relocatedFixture -match '\r(?!\n)') {
        throw "$Owner reserve relocation fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationMovedBeforeMacroRegion'] =
        $relocatedFixture
    $updateImplementationMatches = [regex]::Matches(
        $withoutReserveScan,
        ('(?im)^FUNCTION\s+' +
         'LMCControlCommandService::UpdateAxisRebaseRequiredState' +
         '[^\r\n]*\r?$'))
    if ($updateImplementationMatches.Count -ne 1) {
        throw (
            "$Owner reserve neighbor-spoof fixture found " +
            "$($updateImplementationMatches.Count) targets, expected one.")
    }
    $relocationEol =
        $relocationReserveMatches[0].Groups['Eol'].Value
    $neighborSpoofBlock = (
        'FUNCTION GLOBAL LMCControlCommandService::HandleRequest' +
        $relocationEol + $relocationBlock +
        'FUNCTION GLOBAL LMCControlCommandService::ValidateAxisOwnership' +
        $relocationEol)
    $neighborSpoofFixture = $withoutReserve.Insert(
        $updateImplementationMatches[0].Index,
        $neighborSpoofBlock)
    if ($neighborSpoofFixture -match '\r(?!\n)') {
        throw "$Owner reserve neighbor-spoof fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationRelocationNeighborSpoof'] =
        $neighborSpoofFixture
    $handleRequestScopeMatches = [regex]::Matches(
        $withoutReserveScan,
        ('(?ims)^FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::HandleRequest[^\r\n]*\r?\n' +
         '.*?(?<End>^END_FUNCTION[^\S\r\n]*' +
         '(?<Eol>\r?\n))'))
    if ($handleRequestScopeMatches.Count -ne 1) {
        throw (
            "$Owner reserve nested-relocation fixture found " +
            "$($handleRequestScopeMatches.Count) HandleRequest targets, " +
            'expected one.')
    }
    $nestedRelocationFixture = $withoutReserve.Insert(
        $handleRequestScopeMatches[0].Groups['End'].Index,
        $relocationBlock)
    if ($nestedRelocationFixture -match '\r(?!\n)') {
        throw "$Owner reserve nested-relocation fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationNestedInsideHandleRequest'] =
        $nestedRelocationFixture
    $handleRequestEnd = $handleRequestScopeMatches[0].Groups['End']
    $handleRequestEndEol =
        $handleRequestScopeMatches[0].Groups['Eol'].Value
    $orphanEndRelocationBlock =
        $handleRequestEnd.Value + $relocationBlock +
        'END_FUNCTION;' + $handleRequestEndEol
    $orphanEndRelocationFixture = $withoutReserve.Remove(
        $handleRequestEnd.Index,
        $handleRequestEnd.Length).Insert(
            $handleRequestEnd.Index,
            $orphanEndRelocationBlock)
    if ($orphanEndRelocationFixture -match '\r(?!\n)') {
        throw "$Owner reserve orphan-end fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationRelocationOrphanEndToken'] =
        $orphanEndRelocationFixture
    $wrappedRelocationBlock =
        'IF FALSE THEN' + $relocationEol + $relocationBlock +
        'END_IF;' + $relocationEol
    $wrappedRelocationFixture = $ControlServiceText.Remove(
        $relocationReserveMatches[0].Index,
        $relocationReserveMatches[0].Length).Insert(
            $relocationReserveMatches[0].Index,
            $wrappedRelocationBlock)
    if ($wrappedRelocationFixture -match '\r(?!\n)') {
        throw "$Owner reserve wrapper fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationTopLevelFalseWrapper'] =
        $wrappedRelocationFixture
    $triadHandleMatches = [regex]::Matches(
        $relocationScan,
        ('(?ims)^FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::HandleRequest' +
         '[^\S\r\n]*\r?\n' +
         '.*?(?<End>^END_FUNCTION[^\S\r\n]*(?<Eol>\r?\n))'))
    $triadValidateMatches = [regex]::Matches(
        $relocationScan,
        ('(?ims)^FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ValidateAxisOwnership' +
         '[^\S\r\n]*\r?\n' +
         '.*?(?<End>^END_FUNCTION[^\S\r\n]*(?<Eol>\r?\n))'))
    if (($triadHandleMatches.Count -ne 1) -or
        ($triadValidateMatches.Count -ne 1)) {
        throw "$Owner reserve triad-wrapper fixture target drifted."
    }
    $triadEndIndex =
        $triadValidateMatches[0].Groups['End'].Index +
        $triadValidateMatches[0].Groups['End'].Length
    $triadWrapperFixture = $ControlServiceText.Insert(
        $triadEndIndex,
        'END_IF;' + $relocationEol).Insert(
            $triadHandleMatches[0].Index,
            'IF FALSE THEN' + $relocationEol)
    if ($triadWrapperFixture -match '\r(?!\n)') {
        throw "$Owner reserve triad-wrapper fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationThreeMethodFalseWrapper'] =
        $triadWrapperFixture
    $crossBodyStartIndex =
        $triadHandleMatches[0].Groups['End'].Index
    $crossBodyEndIndex =
        $triadValidateMatches[0].Groups['End'].Index
    $crossBodyWrapperFixture = $ControlServiceText.Insert(
        $crossBodyEndIndex,
        'END_IF;' + $relocationEol).Insert(
            $crossBodyStartIndex,
            'IF FALSE THEN' + $relocationEol)
    if ($crossBodyWrapperFixture -match '\r(?!\n)') {
        throw "$Owner reserve cross-body fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationCrossFunctionBodyWrapper'] =
        $crossBodyWrapperFixture
    $validateHeaderLineMatches = [regex]::Matches(
        $relocationScan,
        ('(?im)^FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ValidateAxisOwnership' +
         '[^\S\r\n]*(?<Eol>\r?\n)'))
    if ($validateHeaderLineMatches.Count -ne 1) {
        throw "$Owner reserve block-order fixture target drifted."
    }
    $validateBodyStartIndex =
        $validateHeaderLineMatches[0].Index +
        $validateHeaderLineMatches[0].Length
    $badOrderWrapperFixture = $ControlServiceText.Insert(
        $validateBodyStartIndex,
        'END_IF;' + $relocationEol +
        'IF TRUE THEN' + $relocationEol).Insert(
            $crossBodyStartIndex,
            'END_IF;' + $relocationEol +
            'IF FALSE THEN' + $relocationEol)
    if ($badOrderWrapperFixture -match '\r(?!\n)') {
        throw "$Owner reserve block-order fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationBalancedCountBadBlockOrder'] =
        $badOrderWrapperFixture
    $repeatCrossFunctionFixture = $ControlServiceText.Insert(
        $validateBodyStartIndex,
        'UNTIL TRUE END_REPEAT;' + $relocationEol).Insert(
            $crossBodyStartIndex,
            'REPEAT' + $relocationEol)
    if ($repeatCrossFunctionFixture -match '\r(?!\n)') {
        throw "$Owner reserve repeat-wrapper fixture introduced bare CR."
    }
    $negativeFixtures['ImplementationCrossFunctionRepeatWrapper'] =
        $repeatCrossFunctionFixture

    $negativeCount = 0
    foreach ($negativeFixture in $negativeFixtures.GetEnumerator()) {
        if ($negativeFixture.Value -ceq $ControlServiceText) {
            throw (
                "$Owner reserve negative fixture did not mutate " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeOwner = $Owner + ' negative ' + $negativeFixture.Key
        $negativeRejected = $false
        try {
            $negativeScan = Get-LasalLexicalScanText $negativeFixture.Value
            $publishMatches = [regex]::Matches(
                $negativeScan,
                ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
                 'LMCControlCommandService::PublishAxisOwnership\s*$' +
                 '.*?^\s*END_FUNCTION\s*$'))
            if ($publishMatches.Count -ne 1) {
                throw (
                    "$negativeOwner publish implementation count is " +
                    "$($publishMatches.Count), expected one.")
            }
            $null = Assert-LasalAxisOwnershipPublishStateContract `
                -ControlServiceText $negativeFixture.Value `
                -Owner $negativeOwner
            $reserveMatches = [regex]::Matches(
                $negativeScan,
                ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
                 'LMCControlCommandService::ReserveAxisOwnership\s*$' +
                 '.*?^\s*END_FUNCTION\s*$'))
            if ($reserveMatches.Count -ne 1) {
                throw (
                    "$negativeOwner reserve implementation count is " +
                    "$($reserveMatches.Count), expected one.")
            }
            Assert-LasalAxisOwnershipReserveMutationFences `
                -ReserveBlock $reserveMatches[0].Value `
                -ControlServiceText $negativeFixture.Value `
                -Owner $negativeOwner `
                -SharedControlClosureAlreadyChecked
        }
        catch {
            $negativeMessage = $_.Exception.Message
            $allowedNegativePrefixes = @(
                ($negativeOwner +
                 ' axis ownership publish mutation blocker:'),
                ($negativeOwner +
                 ' axis ownership publish split blocker:'),
                ($negativeOwner +
                 ' axis ownership reserve mutation blocker:'),
                ($negativeOwner + ' publish implementation count is '),
                ($negativeOwner + ' reserve implementation count is '))
            $recognizedContractFailure = $false
            foreach ($allowedNegativePrefix in
                $allowedNegativePrefixes) {
                if ($negativeMessage.StartsWith(
                        $allowedNegativePrefix,
                        [StringComparison]::Ordinal)) {
                    $recognizedContractFailure = $true
                }
            }
            if (-not $recognizedContractFailure) {
                throw (
                    "$Owner reserve negative fixture " +
                    "'$($negativeFixture.Key)' failed outside its contract " +
                    "assertion: $negativeMessage")
            }
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner reserve verifier accepted negative fixture " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeCount += 1
    }

    $positiveRegex = [regex]::new(
        ('(?is)(FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership\b.*?' +
         '\bResult\s*:=\s*-1\s*;)'),
        [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
        [Text.RegularExpressions.RegexOptions]::Singleline)
    if ($positiveRegex.Matches($ControlServiceText).Count -ne 1) {
        throw "$Owner reserve positive comment fixture target drifted."
    }
    $positiveFixture = $positiveRegex.Replace(
        $ControlServiceText,
        '${1} // verifier comment-only fixture',
        1)
    $positiveScan = Get-LasalLexicalScanText $positiveFixture
    $positivePublishMatches = [regex]::Matches(
        $positiveScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    $positiveReserveMatches = [regex]::Matches(
        $positiveScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if (($positivePublishMatches.Count -ne 1) -or
        ($positiveReserveMatches.Count -ne 1)) {
        throw "$Owner reserve positive comment fixture lost a method."
    }
    $null = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $positiveFixture `
        -Owner "$Owner positive comment-only fixture"
    Assert-LasalAxisOwnershipReserveMutationFences `
        -ReserveBlock $positiveReserveMatches[0].Value `
        -ControlServiceText $positiveFixture `
        -Owner "$Owner positive comment-only fixture" `
        -SharedControlClosureAlreadyChecked

    if ($negativeCount -ne 62) {
        throw "$Owner reserve negative count is $negativeCount, expected 62."
    }
    return $negativeCount
}

function Assert-LasalAxisOwnershipIdentityPreemptionContract {
    param(
        [string]$ControlServiceText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $ControlServiceText
    $blocker = "$Owner compact ownership identity/preemption blocker:"
    if ($scan -match '(?i)\bIdentityCount\b' -or
        $scan -match '(?i)\bpIdentity\s*:\s*\^UDINT\b') {
        throw "$blocker stale DINT-count identity ABI remains."
    }

    $methodBlocks = [ordered]@{}
    foreach ($methodName in @(
            'ReserveAxisOwnership',
            'RollbackAxisOwnership',
            'PublishAxisOwnership',
            'ValidateAxisOwnershipIdentity',
            'CopyAxisOwnershipPreemption',
            'PublishAxisOwnershipPreemptionCleanup')) {
        $matches = [regex]::Matches(
            $scan,
            ('(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::' +
             [regex]::Escape($methodName) + '\b.*?END_FUNCTION'))
        if ($matches.Count -ne 1) {
            throw "$blocker $methodName implementation count is $($matches.Count), expected one."
        }
        $methodBlocks[$methodName] = $matches[0].Value
    }
    $reserveBlock = $methodBlocks['ReserveAxisOwnership']
    $rollbackBlock = $methodBlocks['RollbackAxisOwnership']
    $publishBlock = $methodBlocks['PublishAxisOwnership']
    $validateIdentityBlock = $methodBlocks['ValidateAxisOwnershipIdentity']
    $copyBlock = $methodBlocks['CopyAxisOwnershipPreemption']
    $cleanupBlock = $methodBlocks['PublishAxisOwnershipPreemptionCleanup']
    $replacementMatches = [regex]::Matches(
        $scan,
        ('(?is)FUNCTION\s+LMCControlCommandService::' +
         'ValidateAxisOwnershipPreemptionReplacement\b.*?END_FUNCTION'))
    if ($replacementMatches.Count -ne 1) {
        throw (
            "$blocker ValidateAxisOwnershipPreemptionReplacement private " +
            "implementation count is $($replacementMatches.Count), expected one.")
    }
    $replacementBlock = $replacementMatches[0].Value
    $rollbackHelperMatches = [regex]::Matches(
        $scan,
        ('(?is)FUNCTION\s+LMCControlCommandService::' +
         'ValidateAxisOwnershipRollbackPreemptBank\b.*?END_FUNCTION'))
    if ($rollbackHelperMatches.Count -ne 1) {
        throw (
            "$blocker ValidateAxisOwnershipRollbackPreemptBank private " +
            "implementation count is $($rollbackHelperMatches.Count), expected one.")
    }
    $rollbackHelperBlock = $rollbackHelperMatches[0].Value
    Assert-LasalAxisOwnershipPreemptionCleanupMutationFences `
        -CleanupBlock $cleanupBlock `
        -ReplacementBlock $replacementBlock `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
    Assert-LasalAxisOwnershipRollbackSplitMutationFences `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
    $publishProviderState =
        Assert-LasalAxisOwnershipPublishStateContract `
            -ControlServiceText $ControlServiceText `
            -Owner $Owner
    $publishProofBlock = if ($publishProviderState.Mode -ceq 'Split') {
        $publishProviderState.Decision + "`n" +
            $publishProviderState.Adapter
    }
    else {
        $publishBlock
    }
    Assert-LasalAxisOwnershipReserveMutationFences `
        -ReserveBlock $reserveBlock `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner `
        -SharedControlClosureAlreadyChecked

    foreach ($identityAbiBlock in @($reserveBlock, $validateIdentityBlock)) {
        Assert-Match $identityAbiBlock (
            '(?s)\bpIdentity\s*:\s*\^void\s*;.*?' +
            '\bIdentitySize\s*:\s*UDINT\s*;') (
            "$blocker identity ABI must remain pIdentity:^void plus byte IdentitySize:UDINT.")
    }
    Assert-Match $copyBlock (
        '(?s)PreemptedAdmissionToken\s*:\s*UDINT\s*;\s*' +
        'PreemptedOwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'pDest\s*:\s*\^void\s*;\s*DestSize\s*:\s*UDINT\s*;') (
        "$blocker preemption-copy ABI drifted.")
    Assert-Match $cleanupBlock (
        '(?s)ExpectedAxisMask\s*:\s*UDINT\s*;\s*' +
        'PreemptedAdmissionToken\s*:\s*UDINT\s*;\s*' +
        'PreemptedOwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'SafetyAdmissionToken\s*:\s*UDINT\s*;\s*' +
        'SafetyOwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'CleanupKind\s*:\s*UINT\s*;\s*' +
        'ReportValue0\s*:\s*UDINT\s*;\s*' +
        'ReportValue1\s*:\s*UDINT\s*;\s*' +
        'ObservationCycle\s*:\s*UDINT\s*;') (
        "$blocker cleanup-publication ABI drifted.")

    $storageContracts = [ordered]@{
        'OwnershipLeaseState' = 323
        'OwnershipPreemptedState' = 323
        'OwnershipIdentityState' = 431
        'OwnershipLeaseIdentityState' = 323
        'OwnershipPreemptedIdentityState' = 431
    }
    foreach ($storage in $storageContracts.GetEnumerator()) {
        Assert-Match $scan (
            '(?im)^\s*' + [regex]::Escape($storage.Key) +
            '\s*:\s*ARRAY\s*\[\s*0\.\.' + $storage.Value +
            '\s*\]\s*OF\s*DINT\s*;') (
            "$blocker $($storage.Key) compact storage bound drifted.")
    }

    $constantContracts = [ordered]@{
        'LMC_OWNER_IDENTITY_PREFIX_BYTES' = '0x00000040'
        'LMC_OWNER_IDENTITY_SUFFIX_DINTS' = '314'
        'LMC_OWNER_IDENTITY_SUFFIX_BYTES' = '1256'
        'LMC_OWNER_IDENTITY_AXIS_HEADER_BASE' = '314'
        'LMC_OWNER_IDENTITY_AXIS_HEADER_STRIDE' = '12'
        'LMC_OWNER_IDENTITY_GROUP_HEADER_BASE' = '422'
        'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE' = '314'
        'LMC_OWNER_PREEMPT_OBSERVER_BASE' = '314'
        'LMC_OWNER_PREEMPT_HEADER_BASE' = '422'
        'LMC_OWNER_IDENTITY_AXIS_MAGIC' = '0x49444100'
        'LMC_OWNER_IDENTITY_GROUP_MAGIC' = '0x49444752'
        'LMC_OWNER_LEASE_IDENTITY_MAGIC' = '0x49444C53'
        'LMC_OWNER_PREEMPT_IDENTITY_MAGIC' = '0x49445052'
        'LMC_OWNER_PREEMPT_COPY_MAGIC' = '0x4C4D4350'
        'LMC_OWNER_IDENTITY_VERSION' = '1'
        'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE' = '0x00010000'
        'LMC_OWNER_PREEMPT_COPY_HEADER_BYTES' = '144'
        'LMC_OWNER_PREEMPT_STATUS_NONE' = '0'
        'LMC_OWNER_PREEMPT_STATUS_PENDING_FREEZE' = '1'
        'LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED' = '2'
        'LMC_OWNER_PREEMPT_STATUS_CLEANUP_COMPLETE' = '3'
        'LMC_OWNER_PREEMPT_STATUS_CLEANUP_QUARANTINED' = '4'
        'LMC_OWNER_CLEANUP_COMPLETE_SAFE' = '1'
        'LMC_OWNER_CLEANUP_COMPLETE_QUARANTINE' = '2'
        'LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE' = '3'
    }
    foreach ($constant in $constantContracts.GetEnumerator()) {
        Assert-Match $scan (
            '(?im)^\s*#define\s+' + [regex]::Escape($constant.Key) +
            '\s+' + [regex]::Escape($constant.Value) + '\s*$') (
            "$blocker constant $($constant.Key) drifted.")
    }

    $reserveIdentityShapes = @(
        @{ Condition = 'CommandId\s*=\s*0x2023'; Size = 8 },
        @{ Condition = 'CommandId\s*=\s*0x2024'; Size = 1 },
        @{ Condition = 'CommandId\s*=\s*0x2022'; Size = 16 },
        @{ Condition = '\(CommandId\s*=\s*0x209F\)\s*\|\s*\(CommandId\s*=\s*0x20A0\)'; Size = 32 },
        @{ Condition = 'CommandId\s*=\s*0x20A2'; Size = 24 },
        @{ Condition = ('\(CommandId\s*=\s*0x2047\)\s*\|\s*' +
                '\(CommandId\s*=\s*0x2048\)\s*\|\s*' +
                '\(CommandId\s*=\s*0x2049\)\s*\|\s*' +
                '\(CommandId\s*=\s*0x204A\)\s*\|\s*' +
                '\(CommandId\s*=\s*0x204B\)'); Size = 1 },
        @{ Condition = 'CommandId\s*=\s*0x2085'; Size = 16 },
        @{ Condition = 'CommandId\s*=\s*0x20A4'; Size = 96 },
        @{ Condition = 'CommandId\s*=\s*0x7D22'; Size = 104 },
        @{ Condition = 'CommandId\s*=\s*0x20E7'; Size = 1320 },
        @{ Condition = 'CommandId\s*=\s*0x7D13'; Size = 56 },
        @{ Condition = '\(CommandId\s*=\s*0x7D15\)\s*\|\s*\(CommandId\s*=\s*0x7E53\)'; Size = 72 })
    foreach ($shape in $reserveIdentityShapes) {
        Assert-Match $reserveBlock (
            '(?is)(?:if|elsif)\s+' + $shape.Condition + '\s+then\s*' +
            'identityShapeValid\s*:=\s*IdentitySize\s*=\s*' +
            $shape.Size + '\s*;') (
            "$blocker exact byte identity size $($shape.Size) is missing for $($shape.Condition).")
    }
    Assert-Match $reserveBlock (
        '(?s)identityShapeValid\s*:=\s*FALSE\s*;.*?' +
        'if\s+identityShapeValid\s*=\s*FALSE\s+then\s*RETURN\s*;\s*end_if\s*;') (
        "$blocker identity-size classifier is not fail closed.")
    Assert-Match $reserveBlock (
        '(?s)identityPrefixSize\s*:=\s*IdentitySize\s*;\s*' +
        'if\s+identityPrefixSize\s*>\s*LMC_OWNER_IDENTITY_PREFIX_BYTES\s+then\s*' +
        'identityPrefixSize\s*:=\s*LMC_OWNER_IDENTITY_PREFIX_BYTES\s*;.*?' +
        'if\s+IdentitySize\s*>\s*LMC_OWNER_IDENTITY_PREFIX_BYTES\s+then\s*' +
        'identityTailSize\s*:=\s*IdentitySize\s*-\s*LMC_OWNER_IDENTITY_PREFIX_BYTES\s*;.*?' +
        'if\s+OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP\s+then.*?' +
        'identityTailOffset\s*:=\s*TO_UDINT\(Reference\s*-\s*1\)\s*\*\s*8\s*;.*?' +
        'if\s+identityTailSize\s*>\s*8\s+then\s*RETURN\s*;') (
        "$blocker exact 64-byte prefix and per-axis 8-byte tail packing drifted.")
    Assert-Match $reserveBlock (
        '(?s)OwnershipState\[recordBase\s*\+\s*15\]\s*:=\s*TO_DINT\(IdentitySize\)\s*;\s*' +
        '_memset\(dest:=#OwnershipState\[recordBase\s*\+\s*16\],\s*' +
        'usByte:=0,\s*cntr:=LMC_OWNER_IDENTITY_PREFIX_BYTES\)\s*;\s*' +
        'if\s+identityPrefixSize\s*>\s*0\s+then\s*' +
        '_memcpy\(ptr1:=#OwnershipState\[recordBase\s*\+\s*16\],\s*' +
        'ptr2:=pIdentityBytes,\s*cntr:=identityPrefixSize\)\s*;') (
        "$blocker exact prefix-byte snapshot is incomplete.")
    Assert-Match $reserveBlock (
        '(?s)if\s+identityTailSize\s*>\s*0\s+then\s*' +
        '_memcpy\(ptr1:=#OwnershipIdentityState\[\s*' +
        'TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*' +
        'ptr2:=pIdentityBytes\s*\+\s*LMC_OWNER_IDENTITY_PREFIX_BYTES,\s*' +
        'cntr:=identityTailSize\)\s*;') (
        "$blocker exact unrounded identity-tail copy is missing.")
    Assert-Match $reserveBlock (
        '(?s)if\s+OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP\s+then\s*' +
        'OwnershipIdentityState\[identityHeaderBase\s*\+\s*1\]\s*:=\s*' +
        'LMC_OWNER_IDENTITY_VERSION\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*2\]\$UDINT\s*:=\s*IdentitySize\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*3\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*4\]\$UDINT\s*:=\s*nextGeneration\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*5\]\$UDINT\s*:=\s*effectiveAxisMask\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*6\]\$UDINT\s*:=\s*CallerSessionEpoch\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*7\]\$UDINT\s*:=\s*RequestSequence\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*8\]\$UDINT\s*:=\s*identityPackedCommand\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*9\]\$UDINT\s*:=\s*identityPackedOwner\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*10\]\$UDINT\s*:=\s*identityTailOffset\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*11\]\$UDINT\s*:=\s*identityTailSize\s*;.*?' +
        'OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_IDENTITY_AXIS_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\s*;') (
        "$blocker per-axis identity header fields or magic-last publication drifted.")
    Assert-Match $reserveBlock (
        '(?s)if\s+OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\s+then\s*' +
        'identityHeaderBase\s*:=\s*LMC_OWNER_IDENTITY_GROUP_HEADER_BASE\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*1\]\s*:=\s*LMC_OWNER_IDENTITY_VERSION\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*2\]\$UDINT\s*:=\s*IdentitySize\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*3\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*4\]\$UDINT\s*:=\s*nextGeneration\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*5\]\$UDINT\s*:=\s*effectiveAxisMask\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*6\]\$UDINT\s*:=\s*CallerSessionEpoch\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*7\]\$UDINT\s*:=\s*RequestSequence\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*8\]\$UDINT\s*:=\s*identityPackedCommand\s*;.*?' +
        '\[identityHeaderBase\s*\+\s*9\]\$UDINT\s*:=\s*identityPackedOwner\s*;.*?' +
        'OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_IDENTITY_GROUP_MAGIC\s*;') (
        "$blocker group identity header fields or magic-last publication drifted.")
    Assert-Match $reserveBlock (
        '(?s)if\s+leaseCapture\s+then\s*' +
        'OwnershipLeaseIdentityState\[\s*LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\]\s*:=\s*0\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipLeaseState\[0\],\s*' +
        'ptr2:=#OwnershipState\[LMC_OWNER_GLOBAL_SLOTS\],\s*' +
        'cntr:=sizeof\(OwnershipLeaseState\)\)\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipLeaseIdentityState\[0\],\s*' +
        'ptr2:=#OwnershipIdentityState\[0\],\s*' +
        'cntr:=LMC_OWNER_IDENTITY_SUFFIX_BYTES\)\s*;.*?' +
        'OwnershipLeaseIdentityState\[\s*LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_LEASE_IDENTITY_MAGIC\s*;') (
        "$blocker compact lease snapshot or magic-last publication drifted.")
    Assert-Match $reserveBlock (
        '(?s)if\s+preemptCapture\s+then\s*' +
        'OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\s*:=\s*0\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipPreemptedState\[0\],\s*' +
        'ptr2:=#OwnershipState\[LMC_OWNER_GLOBAL_SLOTS\],\s*' +
        'cntr:=sizeof\(OwnershipPreemptedState\)\)\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipPreemptedIdentityState\[0\],\s*' +
        'ptr2:=#OwnershipIdentityState\[0\],\s*' +
        'cntr:=LMC_OWNER_IDENTITY_SUFFIX_BYTES\)\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipPreemptedIdentityState\[\s*' +
        'LMC_OWNER_PREEMPT_OBSERVER_BASE\],\s*' +
        'ptr2:=#OwnershipObserverState\[0\],\s*' +
        'cntr:=sizeof\(OwnershipObserverState\)\)\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*2\]\$UDINT\s*:=\s*nextToken\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*3\]\$UDINT\s*:=\s*nextGeneration\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*4\]\$UDINT\s*:=\s*effectiveAxisMask\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*5\]\$UDINT\s*:=\s*CallerSessionEpoch\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*6\]\$UDINT\s*:=\s*RequestSequence\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*7\]\$UDINT\s*:=\s*identityPackedCommand\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*8\]\$UDINT\s*:=\s*cleanupRequiredMask\s*;.*?' +
        '\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*9\]\s*:=\s*0\s*;.*?' +
        'OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_PREEMPT_IDENTITY_MAGIC\s*;') (
        "$blocker compact preemption snapshot, root fields, or magic-last publication drifted.")

    Assert-Match $validateIdentityBlock (
        '(?s)Result\s*:=\s*ValidateAxisOwnership\(\s*' +
        'CommandId:=CommandId,\s*Reference:=Reference,\s*' +
        'ExpectedAxisMask:=ExpectedAxisMask,\s*OwnerKind:=OwnerKind,\s*' +
        'ResourceKind:=ResourceKind,\s*AdmissionMode:=AdmissionMode,\s*' +
        'CallerSessionEpoch:=CallerSessionEpoch,\s*' +
        'RequestSequence:=RequestSequence,\s*AdmissionToken:=AdmissionToken,\s*' +
        'OwnerGeneration:=OwnerGeneration,\s*RequiredPhase:=RequiredPhase\)\s*;\s*' +
        'if\s+Result\s*<>\s*0\s+then\s*RETURN\s*;\s*end_if\s*;') (
        "$blocker identity validation must first pass the plain ownership validator.")
    Assert-Match $validateIdentityBlock (
        '(?s)if\s+OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\s+then.*?' +
        'OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*<>\s*' +
        'LMC_OWNER_IDENTITY_GROUP_MAGIC.*?' +
        '\[identityHeaderBase\s*\+\s*2\]\$UDINT\s*<>\s*IdentitySize.*?' +
        '\[identityHeaderBase\s*\+\s*3\]\$UDINT\s*<>\s*AdmissionToken.*?' +
        '\[identityHeaderBase\s*\+\s*4\]\$UDINT\s*<>\s*OwnerGeneration.*?' +
        '\[identityHeaderBase\s*\+\s*5\]\$UDINT\s*<>\s*ExpectedAxisMask.*?' +
        '\[identityHeaderBase\s*\+\s*6\]\$UDINT\s*<>\s*CallerSessionEpoch.*?' +
        '\[identityHeaderBase\s*\+\s*7\]\$UDINT\s*<>\s*RequestSequence.*?' +
        '\[identityHeaderBase\s*\+\s*8\]\$UDINT\s*<>\s*identityPackedCommand.*?' +
        '\[identityHeaderBase\s*\+\s*9\]\$UDINT\s*<>\s*identityPackedOwner') (
        "$blocker group identity validation header is incomplete.")
    Assert-Match $validateIdentityBlock (
        '(?s)OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*<>\s*' +
        '\(LMC_OWNER_IDENTITY_AXIS_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\).*?' +
        '\[identityHeaderBase\s*\+\s*10\]\$UDINT\s*<>\s*identityTailOffset.*?' +
        '\[identityHeaderBase\s*\+\s*11\]\$UDINT\s*<>\s*identityTailSize') (
        "$blocker per-axis identity validation header is incomplete.")
    Assert-Match $validateIdentityBlock (
        '(?s)identityCompareResult\s*:=\s*_memcmp\(\s*' +
        'ptr1:=#OwnershipState\[recordBase\s*\+\s*16\],\s*' +
        'ptr2:=pIdentityBytes,\s*cntr:=identityPrefixSize\)\s*;.*?' +
        'if\s+identityTailSize\s*>\s*0\s+then\s*' +
        'identityCompareResult\s*:=\s*_memcmp\(\s*' +
        'ptr1:=#OwnershipIdentityState\[\s*TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*' +
        'ptr2:=pIdentityBytes\s*\+\s*LMC_OWNER_IDENTITY_PREFIX_BYTES,\s*' +
        'cntr:=identityTailSize\)\s*;.*?' +
        'Result\s*:=\s*0\s*;\s*END_FUNCTION') (
        "$blocker exact byte prefix/tail identity comparison drifted.")

    Assert-Match $copyBlock (
        '(?s)Result\s*:=\s*-1\s*;.*?' +
        'if\s+DestSize\s*<\s*LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\s+then\s*' +
        'Result\s*:=\s*-4\s*;\s*RETURN\s*;.*?' +
        '_memset\(dest:=pDestBytes,\s*usByte:=0,\s*' +
        'cntr:=LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\)\s*;') (
        "$blocker preemption copy does not zero and bound its 144-byte header.")
    Assert-Match $copyBlock (
        '(?s)while\s+stateIndex\s*<=\s*323\s+do.*?' +
        'OwnershipPreemptedState\[stateIndex\].*?end_while\s*;.*?' +
        'while\s+stateIndex\s*<=\s*431\s+do.*?' +
        'OwnershipPreemptedIdentityState\[stateIndex\].*?end_while\s*;.*?' +
        'if\s+bankDirty\s+then.*?Result\s*:=\s*-3\s*;\s*' +
        'else\s*Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_NONE\s*;') (
        "$blocker absent preemption root does not distinguish zero bank from corruption.")
    Assert-Match $copyBlock (
        '(?s)\(\(preemptFlags\s+and\s+0x0000FFFF\)\s*<>\s*' +
        'LMC_OWNER_IDENTITY_VERSION\)\s*\|\s*' +
        '\(\(preemptFlags\s+and\s+0xFFFE0000\)\s*<>\s*0\).*?' +
        '\(safetySession\s*=\s*0\)\s*\|\s*\(safetySequence\s*=\s*0\).*?' +
        '\(\(cleanupCompleteMask\s+and\s+\(not\s+cleanupRequiredMask\)\)\s*<>\s*0\)') (
        "$blocker preemption root version/flags/session/mask validation is incomplete.")

    $copyIdentityShapes = @(
        @{ Label = '0x2022'; Pattern = '0x2022\s*:\s*identityExpectedSize\s*:=\s*16\s*;' },
        @{ Label = '0x2023'; Pattern = '0x2023\s*:\s*identityExpectedSize\s*:=\s*8\s*;' },
        @{ Label = '0x2024'; Pattern = '0x2024\s*:\s*identityExpectedSize\s*:=\s*1\s*;' },
        @{ Label = '0x209F/0x20A0'; Pattern = '0x209F\s*,\s*0x20A0\s*:\s*identityExpectedSize\s*:=\s*32\s*;' },
        @{ Label = '0x20A2'; Pattern = '0x20A2\s*:\s*identityExpectedSize\s*:=\s*24\s*;' },
        @{ Label = '0x2047'; Pattern = '0x2047\s*:\s*identityExpectedSize\s*:=\s*1\s*;' },
        @{ Label = '0x20A4'; Pattern = '0x20A4\s*:\s*identityExpectedSize\s*:=\s*96\s*;' },
        @{ Label = '0x7D22'; Pattern = '0x7D22\s*:\s*identityExpectedSize\s*:=\s*104\s*;' },
        @{ Label = '0x2048'; Pattern = '0x2048\s*:\s*identityExpectedSize\s*:=\s*1\s*;' },
        @{ Label = '0x2085'; Pattern = '0x2085\s*:\s*identityExpectedSize\s*:=\s*16\s*;' },
        @{ Label = '0x2049/0x204A'; Pattern = '0x2049\s*,\s*0x204A\s*:\s*identityExpectedSize\s*:=\s*1\s*;' },
        @{ Label = '0x204B'; Pattern = '0x204B\s*:\s*identityExpectedSize\s*:=\s*1\s*;' },
        @{ Label = '0x20E7'; Pattern = '0x20E7\s*:\s*identityExpectedSize\s*:=\s*1320\s*;' },
        @{ Label = '0x7D13'; Pattern = '0x7D13\s*:\s*identityExpectedSize\s*:=\s*56\s*;' },
        @{ Label = '0x7D15'; Pattern = '0x7D15\s*:\s*identityExpectedSize\s*:=\s*72\s*;' },
        @{ Label = '0x7E53'; Pattern = '0x7E53\s*:\s*identityExpectedSize\s*:=\s*72\s*;' })
    foreach ($shape in $copyIdentityShapes) {
        Assert-Match $copyBlock $shape.Pattern (
            "$blocker reconstructed old identity metadata size drifted for $($shape.Label).")
    }
    Assert-Match $copyBlock (
        '(?s)if\s+\(identityMetadataValid\s*=\s*FALSE\)\s*\|\s*' +
        '\(identitySize\s*<>\s*identityExpectedSize\)\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;') (
        "$blocker reconstructed old identity metadata is not fail closed.")
    Assert-Match $copyBlock (
        '(?s)if\s+\(\(oldAxisMask\s+and\s+safetyAxisMask\)\s*<>\s*0\s*\)\s*&\s*' +
        '\(\(oldAxisMask\s+and\s+safetyAxisMask\)\s*<>\s*oldAxisMask\)\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker partial-overlap preemption is not rejected as corrupt.")

    $disjointMatch = [regex]::Match(
        $copyBlock,
        ('(?is)if\s+\(oldAxisMask\s+and\s+safetyAxisMask\)\s*=\s*0\s+then.*?' +
         'RETURN\s*;\s*end_if\s*;\s*safetyFound\s*:=\s*FALSE'))
    if (-not $disjointMatch.Success) {
        throw "$blocker fully-disjoint proof block is missing or misplaced."
    }
    $disjointBlock = $disjointMatch.Value
    if ($disjointBlock -match '(?i)LMC_OWNER_STATE_RESERVED|LMC_OWNER_STATE_QUARANTINED') {
        throw "$blocker disjoint proof accepts a non-active Reserved/Quarantined state."
    }
    Assert-Match $disjointBlock (
        '(?s)LMC_OWNER_KIND_DIRECT\s*:\s*currentStateValid\s*:=\s*' +
        'OwnershipState\[currentRecordBase\s*\+\s*1\]\s*=\s*' +
        'LMC_OWNER_STATE_DIRECT_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_GROUP\s*:\s*currentStateValid\s*:=\s*' +
        '\(OwnershipState\[currentRecordBase\s*\+\s*1\]\s*=\s*' +
        'LMC_OWNER_STATE_GROUP_LEASE\)\s*\|\s*' +
        '\(OwnershipState\[currentRecordBase\s*\+\s*1\]\s*=\s*' +
        'LMC_OWNER_STATE_GROUP_ACTIVE\).*?' +
        'LMC_OWNER_KIND_LMC_HOME\s*:\s*currentStateValid\s*:=.*?' +
        'LMC_OWNER_STATE_LMC_HOME_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_DS402_HOME\s*:\s*currentStateValid\s*:=.*?' +
        'LMC_OWNER_STATE_DS402_HOME_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_ENCODER\s*:\s*currentStateValid\s*:=.*?' +
        'LMC_OWNER_STATE_TW20_QUEUED.*?LMC_OWNER_STATE_TW20_RUNNING.*?' +
        'LMC_OWNER_STATE_TW20_DRAINING') (
        "$blocker disjoint proof active-state classifier drifted.")
    Assert-Match $disjointBlock (
        '(?s)OwnershipState\[currentRecordBase\]\s*<>\s*axisIndex.*?' +
        '\[currentRecordBase\s*\+\s*35\]\$UDINT\s*<>.*?' +
        '\[currentRecordBase\s*\+\s*2\]\s*<>\s*oldOwnerKind.*?' +
        '\[currentRecordBase\s*\+\s*3\]\s*<>\s*oldCommand.*?' +
        '\[currentRecordBase\s*\+\s*4\]\$UDINT\s*<>\s*oldToken.*?' +
        '\[currentRecordBase\s*\+\s*5\]\$UDINT\s*<>\s*oldGeneration.*?' +
        '\[currentRecordBase\s*\+\s*6\]\$UDINT\s*<>\s*oldSession.*?' +
        '\[currentRecordBase\s*\+\s*7\]\$UDINT\s*<>\s*oldSequence.*?' +
        '\[currentRecordBase\s*\+\s*11\]\$UDINT\s*<>\s*oldAxisMask.*?' +
        '\[currentRecordBase\s*\+\s*12\]\s*<>\s*oldReference.*?' +
        '\[currentRecordBase\s*\+\s*13\]\s*<>\s*oldResourceKind.*?' +
        '\[currentRecordBase\s*\+\s*14\]\s*<>\s*oldAdmissionMode.*?' +
        '\[currentRecordBase\s*\+\s*15\]\$UDINT\s*<>\s*identitySize.*?' +
        'currentStateValid\s*=\s*FALSE') (
        "$blocker disjoint proof does not require the complete live immutable tuple.")
    Assert-Match $disjointBlock (
        '(?s)OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*<>\s*' +
        'LMC_OWNER_IDENTITY_GROUP_MAGIC.*?' +
        '\[identityHeaderBase\s*\+\s*2\]\$UDINT\s*<>\s*identitySize.*?' +
        '\[identityHeaderBase\s*\+\s*3\]\$UDINT\s*<>\s*oldToken.*?' +
        '\[identityHeaderBase\s*\+\s*4\]\$UDINT\s*<>\s*oldGeneration.*?' +
        '\[identityHeaderBase\s*\+\s*5\]\$UDINT\s*<>\s*oldAxisMask.*?' +
        '\[identityHeaderBase\s*\+\s*6\]\$UDINT\s*<>\s*oldSession.*?' +
        '\[identityHeaderBase\s*\+\s*7\]\$UDINT\s*<>\s*oldSequence.*?' +
        '\[identityHeaderBase\s*\+\s*8\]\$UDINT\s*<>\s*identityPackedCommand.*?' +
        '\[identityHeaderBase\s*\+\s*9\]\$UDINT\s*<>\s*identityPackedOwner') (
        "$blocker disjoint group identity header proof is incomplete.")
    Assert-Match $disjointBlock (
        '(?s)OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*<>\s*' +
        '\(LMC_OWNER_IDENTITY_AXIS_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\).*?' +
        '\[identityHeaderBase\s*\+\s*10\]\$UDINT\s*<>\s*identityTailOffset.*?' +
        '\[identityHeaderBase\s*\+\s*11\]\$UDINT\s*<>\s*identityTailSize') (
        "$blocker disjoint axis identity header proof is incomplete.")
    Assert-Match $disjointBlock (
        '(?s)identityCompareResult\s*:=\s*_memcmp\(\s*' +
        'ptr1:=#OwnershipState\[currentRecordBase\s*\+\s*16\],\s*' +
        'ptr2:=#OwnershipPreemptedState\[recordBase\s*\+\s*16\],\s*' +
        'cntr:=identityPrefixSize\)\s*;.*?' +
        'identityCompareResult\s*:=\s*_memcmp\(\s*' +
        'ptr1:=#OwnershipIdentityState\[\s*TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*' +
        'ptr2:=#OwnershipPreemptedIdentityState\[\s*' +
        'TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*cntr:=identityTailSize\)') (
        "$blocker disjoint proof does not compare exact prefix and tail bytes.")
    Assert-Match $disjointBlock (
        '(?s)if\s+disjointCurrentValid\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;\s*' +
        'else\s*Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_NONE\s*;\s*' +
        'end_if\s*;\s*RETURN\s*;') (
        "$blocker disjoint proof failure/success results drifted.")
    $zeroHeader = [regex]::Match(
        $copyBlock,
        '(?is)_memset\(dest:=pDestBytes,\s*usByte:=0,\s*' +
            'cntr:=LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\)')
    $firstHeaderWrite = [regex]::Match(
        $copyBlock,
        '(?is)\(pDestBytes\s*\+\s*4\)\^\$UDINT\s*:=' )
    if (-not $zeroHeader.Success -or -not $firstHeaderWrite.Success -or
        $zeroHeader.Index -ge $disjointMatch.Index -or
        $disjointMatch.Index -ge $firstHeaderWrite.Index) {
        throw "$blocker disjoint NONE path does not preserve an all-zero output header."
    }

    Assert-Match $copyBlock (
        '(?s)if\s+\(safetyFound\s*=\s*FALSE\)\s*\|\s*' +
        '\(tupleValid\s*=\s*FALSE\).*?' +
        'LMC_OWNER_STATE_RESERVED.*?LMC_OWNER_STATE_SAFETY_PREEMPTING.*?' +
        'LMC_OWNER_STATE_QUARANTINED.*?Result\s*:=\s*-3\s*;') (
        "$blocker overlapping safety tuple/state proof is incomplete.")
    Assert-Match $copyBlock (
        '(?s)if\s+safetyState\s*=\s*LMC_OWNER_STATE_RESERVED\s+then\s*' +
        'Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_PENDING_FREEZE\s*;\s*' +
        'elsif.*?LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE.*?then\s*' +
        'Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_CLEANUP_QUARANTINED\s*;\s*' +
        'elsif.*?cleanupCompleteMask.*?cleanupRequiredMask.*?then\s*' +
        'Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED\s*;\s*' +
        'else\s*Result\s*:=\s*LMC_OWNER_PREEMPT_STATUS_CLEANUP_COMPLETE\s*;') (
        "$blocker preemption status mapping drifted.")

    $copyHeaderFields = @(
        @{ Offset = 4; Type = 'UDINT'; Value = 'LMC_OWNER_IDENTITY_VERSION' },
        @{ Offset = 8; Type = 'UDINT'; Value = 'LMC_OWNER_PREEMPT_COPY_HEADER_BYTES' },
        @{ Offset = 12; Type = 'UDINT'; Value = 'totalSize' },
        @{ Offset = 16; Type = 'DINT'; Value = 'Result' },
        @{ Offset = 20; Type = 'UDINT'; Value = 'preemptFlags\s+and\s+0xFFFF0000' },
        @{ Offset = 24; Type = 'UDINT'; Value = 'cleanupRequiredMask' },
        @{ Offset = 28; Type = 'UDINT'; Value = 'cleanupCompleteMask' },
        @{ Offset = 32; Type = 'UDINT'; Value = 'oldAxisMask' },
        @{ Offset = 36; Type = 'UDINT'; Value = 'oldToken' },
        @{ Offset = 40; Type = 'UDINT'; Value = 'oldGeneration' },
        @{ Offset = 44; Type = 'UDINT'; Value = 'oldSession' },
        @{ Offset = 48; Type = 'UDINT'; Value = 'oldSequence' },
        @{ Offset = 52; Type = 'DINT'; Value = 'oldCommand' },
        @{ Offset = 56; Type = 'DINT'; Value = 'oldReference' },
        @{ Offset = 60; Type = 'DINT'; Value = 'oldOwnerKind' },
        @{ Offset = 64; Type = 'DINT'; Value = 'oldResourceKind' },
        @{ Offset = 68; Type = 'DINT'; Value = 'oldAdmissionMode' },
        @{ Offset = 72; Type = 'DINT'; Value = 'oldState' },
        @{ Offset = 76; Type = 'UDINT'; Value = 'identitySize' },
        @{ Offset = 80; Type = 'UDINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*8\]\$UDINT' },
        @{ Offset = 84; Type = 'UDINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*9\]\$UDINT' },
        @{ Offset = 88; Type = 'UDINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*10\]\$UDINT' },
        @{ Offset = 92; Type = 'DINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*32\]' },
        @{ Offset = 96; Type = 'UDINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*33\]\$UDINT' },
        @{ Offset = 100; Type = 'UDINT'; Value = 'OwnershipPreemptedState\[recordBase\s*\+\s*34\]\$UDINT' },
        @{ Offset = 104; Type = 'UDINT'; Value = 'safetyAxisMask' },
        @{ Offset = 108; Type = 'UDINT'; Value = 'safetyToken' },
        @{ Offset = 112; Type = 'UDINT'; Value = 'safetyGeneration' },
        @{ Offset = 116; Type = 'UDINT'; Value = 'safetyCommand' },
        @{ Offset = 120; Type = 'UDINT'; Value = 'safetyReference' },
        @{ Offset = 124; Type = 'DINT'; Value = 'safetyState' },
        @{ Offset = 128; Type = 'UDINT'; Value = 'safetySession' },
        @{ Offset = 132; Type = 'UDINT'; Value = 'safetySequence' },
        @{ Offset = 136; Type = 'DINT'; Value = 'safetyAdmission' },
        @{ Offset = 140; Type = 'UDINT'; Value = '0' })
    foreach ($field in $copyHeaderFields) {
        $fieldMatches = [regex]::Matches(
            $copyBlock,
            ('(?is)\(pDestBytes\s*\+\s*' + $field.Offset +
             '\)\^\$' + $field.Type + '\s*:=\s*' + $field.Value + '\s*;'))
        if ($fieldMatches.Count -ne 1) {
            throw "$blocker copy header offset $($field.Offset) field drifted."
        }
    }
    Assert-Match $copyBlock (
        '(?s)totalSize\s*:=\s*LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\s*\+\s*identitySize\s*;\s*' +
        'if\s+DestSize\s*<\s*totalSize\s+then\s*Result\s*:=\s*-4\s*;.*?' +
        '_memcpy\(ptr1:=pDestBytes\s*\+\s*LMC_OWNER_PREEMPT_COPY_HEADER_BYTES,\s*' +
        'ptr2:=#OwnershipPreemptedState\[recordBase\s*\+\s*16\],\s*' +
        'cntr:=identityPrefixSize\)\s*;.*?' +
        '_memcpy\(ptr1:=pDestBytes\s*\+\s*LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\s*\+\s*' +
        'identityPrefixSize,\s*ptr2:=#OwnershipPreemptedIdentityState\[\s*' +
        'TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*cntr:=identityTailSize\)\s*;.*?' +
        'pDestBytes\^\$UDINT\s*:=\s*LMC_OWNER_PREEMPT_COPY_MAGIC\s*;\s*END_FUNCTION') (
        "$blocker variable-length identity copy or copy-magic-last publication drifted.")

    Assert-Match $cleanupBlock (
        '(?s)Result\s*:=\s*-1\s*;\s*if\s+\(ExpectedAxisMask\s*=\s*0\).*?' +
        '\(CleanupKind\s*<\s*LMC_OWNER_CLEANUP_COMPLETE_SAFE\).*?' +
        '\(CleanupKind\s*>\s*LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\).*?' +
        '\(ObservationCycle\s*=\s*0\)\s+then\s*RETURN\s*;') (
        "$blocker cleanup input/kind validation drifted.")
    Assert-Match $cleanupBlock (
        '(?s)rootValid\s*:=\s*' +
        '\(OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*=\s*' +
        'LMC_OWNER_PREEMPT_IDENTITY_MAGIC\)\s*&\s*' +
        '\(\(preemptFlags\s+and\s+0x0000FFFF\)\s*=\s*LMC_OWNER_IDENTITY_VERSION\)\s*&\s*' +
        '\(\(preemptFlags\s+and\s+0xFFFE0000\)\s*=\s*0\).*?' +
        '\(safetySession\s*<>\s*0\)\s*&\s*\(safetySequence\s*<>\s*0\).*?' +
        '\(\(cleanupRequiredMask\s+and\s+\(not\s+safetyAxisMask\)\)\s*=\s*0\).*?' +
        '\(\(cleanupCompleteMask\s+and\s+\(not\s+cleanupRequiredMask\)\)\s*=\s*0\)\s*;\s*' +
        'if\s+rootValid\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;') (
        "$blocker cleanup root/version corruption guard drifted.")
    Assert-Match $cleanupBlock (
        '(?s)LMC_OWNER_KIND_LMC_HOME\s*:.*?' +
        'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE.*?LMC_OWNER_STATE_LMC_HOME_ACTIVE.*?' +
        'LMC_OWNER_KIND_DS402_HOME\s*:.*?' +
        'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE.*?LMC_OWNER_STATE_DS402_HOME_ACTIVE.*?' +
        'LMC_OWNER_KIND_ENCODER\s*:.*?' +
        'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE.*?' +
        'LMC_OWNER_STATE_TW20_QUEUED.*?LMC_OWNER_STATE_TW20_RUNNING.*?' +
        'LMC_OWNER_STATE_TW20_DRAINING') (
        "$blocker cleanup old special-owner proof drifted.")
    Assert-Match $cleanupBlock (
        '(?s)if\s+\(safetyFound\s*=\s*FALSE\)\s*\|\s*' +
        '\(tupleValid\s*=\s*FALSE\).*?' +
        '\(\(safetyState\s*<>\s*LMC_OWNER_STATE_SAFETY_PREEMPTING\)\s*&\s*' +
        '\(safetyState\s*<>\s*LMC_OWNER_STATE_QUARANTINED\)\)\s+then.*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker cleanup accepts a safety phase outside Preempting/Quarantined.")
    Assert-Match $cleanupBlock (
        '(?s)replayEvidenceMatch\s*:=\s*' +
        '\(OwnershipState\[safetyRecordBase\s*\+\s*32\]\s*=\s*TO_DINT\(CleanupKind\)\)\s*&\s*' +
        '\(OwnershipState\[safetyRecordBase\s*\+\s*33\]\$UDINT\s*=\s*ReportValue0\)\s*&\s*' +
        '\(OwnershipState\[safetyRecordBase\s*\+\s*34\]\$UDINT\s*=\s*ReportValue1\)\s*&\s*' +
        '\(OwnershipObserverState\[evidenceObserverBase\s*\+\s*11\]\$UDINT\s*=\s*ObservationCycle\)\s*;\s*' +
        'exactReplay\s*:=\s*replayEvidenceMatch\s*;.*?' +
        'if\s+replayEvidenceMatch\s*&\s*\(exactReplay\s*=\s*FALSE\)\s+then.*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'if\s+exactReplay\s+then\s*Result\s*:=\s*1\s*;\s*RETURN\s*;') (
        "$blocker cleanup exact idempotent replay evidence drifted.")
    Assert-Match $cleanupBlock (
        '(?s)case\s+oldResourceKind\s+of\s*' +
        'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\s*:.*?OwnershipState\[7\].*?OwnershipState\[8\].*?OwnershipState\[9\].*?' +
        'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE\s*:.*?OwnershipState\[10\].*?OwnershipState\[11\].*?OwnershipState\[12\].*?' +
        'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE\s*:.*?OwnershipState\[13\].*?OwnershipState\[14\].*?OwnershipState\[15\].*?' +
        'if\s+tupleValid\s*=\s*FALSE\s+then\s*Result\s*:=\s*-2\s*;') (
        "$blocker cleanup does not require the exact singleton token/generation/mask.")
    Assert-Match $cleanupBlock (
        '(?s)OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\s*:=\s*0\s*;\s*' +
        'if\s+CleanupKind\s*<>\s*LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\s+then.*?' +
        'cleanupCompleteMask\s*:=\s*cleanupCompleteMask\s+or\s+ExpectedAxisMask\s*;\s*' +
        'end_if\s*;\s*if\s+\(CleanupKind\s*=\s*LMC_OWNER_CLEANUP_COMPLETE_QUARANTINE\)\s*\|\s*' +
        '\(CleanupKind\s*=\s*LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\)\s+then\s*' +
        'preemptFlags\s*:=\s*preemptFlags\s+or\s+' +
        'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE\s*;') (
        "$blocker complete/incomplete cleanup or quarantine publication drifted.")
    Assert-Match $cleanupBlock (
        '(?s)OwnershipPreemptedIdentityState\[\s*' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*1\]\$UDINT\s*:=\s*preemptFlags\s*;\s*' +
        'OwnershipPreemptedIdentityState\[\s*' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*9\]\$UDINT\s*:=\s*cleanupCompleteMask\s*;\s*' +
        'OwnershipState\[safetyRecordBase\s*\+\s*32\]\s*:=\s*TO_DINT\(CleanupKind\)\s*;\s*' +
        'OwnershipState\[safetyRecordBase\s*\+\s*33\]\$UDINT\s*:=\s*ReportValue0\s*;\s*' +
        'OwnershipState\[safetyRecordBase\s*\+\s*34\]\$UDINT\s*:=\s*ReportValue1\s*;\s*' +
        'OwnershipObserverState\[evidenceObserverBase\s*\+\s*11\]\$UDINT\s*:=\s*ObservationCycle\s*;\s*' +
        'OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_PREEMPT_IDENTITY_MAGIC\s*;\s*Result\s*:=\s*0\s*;\s*END_FUNCTION') (
        "$blocker cleanup evidence or root-magic-last publication drifted.")

    # Reserve must reject global ownership collisions and stale compact evidence
    # before it changes a record. Safety Group admission may overlap selected
    # owners, but a fresh Group may not silently absorb a disjoint owner.
    Assert-Match $reserveBlock (
        '(?s)liveNonGroupMask\s*:\s*UDINT\s*;.*?' +
        'liveNonGroupMask\s*:=\s*0\s*;.*?' +
        'liveNonGroupMask\s*:=\s*liveNonGroupMask\s+or\s+axisBit\s*;.*?' +
        'if\s+\(OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\)\s*&\s*' +
        '\(AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY\)\s*&\s*' +
        'liveNonGroupFound\s+then\s*Result\s*:=\s*-2\s*;\s*RETURN\s*;.*?' +
        'if\s+\(OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\)\s*&\s*' +
        '\(AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY\)\s*&\s*' +
        '\(liveGroupFound\s*=\s*FALSE\)\s*&\s*' +
        '\(\(liveNonGroupMask\s+and\s+RequestedAxisMask\)\s*<>\s*' +
        'liveNonGroupMask\)\s+then\s*Result\s*:=\s*-2\s*;\s*RETURN\s*;.*?' +
        'if\s+\(OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP\)\s*&\s*' +
        '\(AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY\)\s*&\s*' +
        'liveGroupFound\s+then\s*Result\s*:=\s*-2\s*;\s*RETURN\s*;') (
        "$blocker global Group/non-Group collision policy drifted.")
    Assert-Match $reserveBlock (
        '(?s)if\s+\(liveGroupFound\s*=\s*FALSE\)\s*&\s*' +
        '\(liveNonGroupFound\s*=\s*FALSE\)\s+then\s*' +
        'if\s+leaseAvailable\s+then\s*Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'stateIndex\s*:=\s*7\s*;\s*while\s+stateIndex\s*<=\s*15\s+do\s*' +
        'if\s+OwnershipState\[stateIndex\]\s*<>\s*0\s+then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker all-idle reservation accepts orphan lease/singleton evidence.")
    Assert-Match $reserveBlock (
        '(?s)if\s+\(OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\)\s*&\s*' +
        '\(liveGroupFound\s*=\s*FALSE\)\s*&\s*' +
        '\(liveNonGroupFound\s*=\s*FALSE\)\s+then.*?' +
        'OwnershipObserverState\[observerBase\s*\+\s*observerIndex\]\s*<>\s*0.*?' +
        'OwnershipIdentityState\[identityHeaderBase\s*\+\s*identityIndex\]\s*<>\s*0.*?' +
        'while\s+identityIndex\s*<\s*LMC_OWNER_IDENTITY_SUFFIX_DINTS\s+do.*?' +
        'OwnershipIdentityState\[identityIndex\]\s*<>\s*0.*?' +
        'while\s+identityIndex\s*<\s*10\s+do.*?' +
        'LMC_OWNER_IDENTITY_GROUP_HEADER_BASE\s*\+\s*identityIndex\]\s*<>\s*0') (
        "$blocker fresh Group reservation does not prove an all-zero identity/observer surface.")
    Assert-Match $reserveBlock (
        '(?s)if\s+safetyPreemption\s*&\s*\(identityTailSize\s*>\s*0\)\s+then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'if\s+\(OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP\)\s*&\s*' +
        '\(identityTailSize\s*>\s*0\)\s+then\s*' +
        '_memset\(dest:=#OwnershipIdentityState.*?cntr:=identityTailSize\)\s*;\s*' +
        'end_if\s*;\s*if\s+identityTailSize\s*>\s*0\s+then\s*' +
        '_memcpy\(ptr1:=#OwnershipIdentityState.*?cntr:=identityTailSize\)\s*;') (
        "$blocker safety TailSize=0/shared-suffix mutation guard drifted.")
    Assert-Match $reserveBlock (
        '(?s)if\s+leaseAvailable\s+then\s*existingIdentityValid\s*:=.*?' +
        'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\s*\+\s*2\]\$UDINT\s*=\s*1\).*?' +
        '\+\s*6\]\$UDINT\s*<>\s*0\).*?\+\s*7\]\$UDINT\s*<>\s*0\).*?' +
        'TO_UDINT\(0x2047\)\s+or\s+\(TO_UDINT\(0x0100\)\s+shl\s+16\).*?' +
        'LMC_OWNER_ADMISSION_ORDINARY.*?' +
        'OwnershipLeaseState\[recordBase\s*\+\s*15\]\$UDINT\s*<>\s*1.*?' +
        'OwnershipLeaseState\[recordBase\s*\+\s*16\]\$UDINT\s*<>\s*1.*?' +
        'identityIndex\s*:=\s*17\s*;\s*while\s+identityIndex\s*<=\s*31.*?' +
        'identityIndex\s*:=\s*1\s*;\s*while\s+identityIndex\s*<=\s*34.*?' +
        'while\s+identityIndex\s*<\s*LMC_OWNER_IDENTITY_SUFFIX_DINTS.*?' +
        'OwnershipLeaseIdentityState\[identityIndex\]\s*<>\s*0') (
        "$blocker exact one-byte 0x2047 lease-bank proof drifted in Reserve.")

    # Rollback validates every captured bank before mutation, aggregates the
    # restored Group state globally, and publishes the shared Group magic last.
    Assert-Match $rollbackHelperBlock (
        '(?s)restoredGroupActive\s*:=\s*FALSE\s*;.*?' +
        'restoredGroupFound\s*:=\s*FALSE\s*;.*?' +
        'restoredNonSafetyFound\s*:=\s*FALSE\s*;.*?' +
        'if\s+\(snapshotState\s*=\s*LMC_OWNER_STATE_GROUP_ACTIVE\)\s*&\s*' +
        '\(snapshotOwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\)\s+then\s*' +
        'restoredGroupActive\s*:=\s*TRUE\s*;.*?' +
        'if\s+restoredGroupFound\s*&\s*restoredNonSafetyFound\s+then\s*' +
        'preemptBankValid\s*:=\s*FALSE\s*;') (
        "$blocker rollback Group aggregation/global exclusivity proof drifted.")
    Assert-Match $rollbackBlock (
        '(?s)if\s+restoreLease\s*\|\s*restoredGroupActive\s+then.*?' +
        'leaseBankValid\s*:=.*?' +
        'LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\s*\+\s*2\]\$UDINT\s*=\s*1\).*?' +
        '\+\s*6\]\$UDINT\s*<>\s*0\).*?\+\s*7\]\$UDINT\s*<>\s*0\).*?' +
        'TO_UDINT\(0x2047\)\s+or\s+\(TO_UDINT\(0x0100\)\s+shl\s+16\).*?' +
        'OwnershipLeaseState\[recordBase\s*\+\s*15\]\$UDINT\s*<>\s*1.*?' +
        'OwnershipLeaseState\[recordBase\s*\+\s*16\]\$UDINT\s*<>\s*1.*?' +
        'identityIndex\s*:=\s*17\s*;\s*while\s+identityIndex\s*<=\s*31.*?' +
        'identityIndex\s*:=\s*1\s*;\s*while\s+identityIndex\s*<=\s*34.*?' +
        'while\s+identityIndex\s*<\s*LMC_OWNER_IDENTITY_SUFFIX_DINTS.*?' +
        'if\s+\(leaseBankValid\s*=\s*FALSE\)\s*\|\s*' +
        '\(firstRecordBase\s*<\s*0\)\s+then.*?Result\s*:=\s*-3\s*;') (
        "$blocker rollback exact one-byte 0x2047 lease proof drifted.")
    Assert-Match $rollbackBlock (
        '(?s)groupHeaderPublished\s*:=\s*FALSE\s*;.*?' +
        'OwnershipIdentityState\[identityHeaderBase\]\s*:=\s*0\s*;.*?' +
        '_memcpy\(ptr1:=#OwnershipState\[recordBase\],\s*' +
        'ptr2:=#OwnershipPreemptedState\[clearIndex\],\s*' +
        'cntr:=LMC_OWNER_AXIS_STRIDE\s*\*\s*4\)\s*;.*?' +
        'if\s+identityTailSize\s*>\s*0\s+then\s*' +
        '_memset\(dest:=#OwnershipIdentityState.*?' +
        '_memcpy\(ptr1:=#OwnershipIdentityState.*?cntr:=identityTailSize\)\s*;.*?' +
        'if\s+groupHeaderPublished\s+then\s*' +
        'OwnershipIdentityState\[\s*LMC_OWNER_IDENTITY_GROUP_HEADER_BASE\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_IDENTITY_GROUP_MAGIC\s*;') (
        "$blocker rollback exact record restore, TailSize=0 guard, or Group-magic-last publication drifted.")
    $rollbackBankGate = $rollbackHelperBlock.LastIndexOf(
        'if preemptBankValid = FALSE then')
    $rollbackHelperCall = $rollbackBlock.IndexOf(
        'rollbackPreemptResult := ValidateAxisOwnershipRollbackPreemptBank(')
    $rollbackLeaseGate = $rollbackBlock.LastIndexOf('if (leaseBankValid = FALSE) | (firstRecordBase < 0) then')
    $rollbackFirstMutation = $rollbackBlock.IndexOf('groupHeaderPublished := FALSE;')
    if ($rollbackBankGate -lt 0 -or $rollbackLeaseGate -lt 0 -or
        $rollbackHelperCall -lt 0 -or
        $rollbackFirstMutation -lt 0 -or
        $rollbackHelperCall -ge $rollbackFirstMutation -or
        $rollbackLeaseGate -ge $rollbackFirstMutation) {
        throw "$blocker rollback bank validation is not complete before live mutation."
    }

    # Publish must prove the full preemption root/bank and any completed special
    # replacement before report fields, live records, or bank destruction move.
    Assert-Match $publishProofBlock (
        '(?s)preemptRootValid\s*:=.*?' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*2\]\$UDINT\s*=\s*AdmissionToken.*?' +
        '\+\s*3\]\$UDINT\s*=\s*OwnerGeneration.*?' +
        '\+\s*4\]\$UDINT\s*=\s*AxisMask.*?' +
        '\+\s*5\]\$UDINT\s*=\s*expectedSession.*?' +
        '\+\s*6\]\$UDINT\s*=\s*expectedSequence.*?' +
        '\+\s*7\]\$UDINT\s*=\s*\(TO_UDINT\(expectedCommandId\)\s+or\s+' +
        '\(TO_UDINT\(expectedReference\)\s+shl\s+16\)\).*?' +
        '0xFFFE0000\)\s*=\s*0\)\s*;') (
        "$blocker Publish preemption-root tuple/version proof drifted.")
    Assert-Match $publishProofBlock (
        '(?s)if\s+\(expectedAdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY\)\s*&\s*' +
        '\(preemptRootValid\s*=\s*FALSE\)\s+then\s*preemptBankValid\s*:=\s*TRUE\s*;.*?' +
        'while\s+identityIndex\s*<=\s*323\s+do.*?' +
        'while\s+identityIndex\s*<=\s*431\s+do.*?' +
        'if\s+preemptBankValid\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;') (
        "$blocker Publish accepts a dirty bank behind an absent root.")
    Assert-Match $publishProofBlock (
        '(?s)if\s+preemptRootValid\s+then.*?' +
        '\(\(cleanupRequiredMask\s+and\s+\(not\s+AxisMask\)\)\s*<>\s*0\)\s*\|\s*' +
        '\(\(cleanupCompleteMask\s+and\s+\(not\s+cleanupRequiredMask\)\)\s*<>\s*0\).*?' +
        'if\s+preemptSpecialValid\s+then.*?' +
        '\(\(cleanupRequiredMask\s+and\s+axisBit\)\s*=\s*0\).*?' +
        'if\s+\(cleanupCompleteMask\s+and\s+axisBit\)\s*=\s*0\s+then.*?' +
        'OwnershipState\[7\].*?OwnershipState\[10\].*?OwnershipState\[13\].*?' +
        'else\s*singletonToken\s*:=\s*0.*?' +
        '\(singletonToken\s*<>\s*preemptToken\)\s*&\s*' +
        '\(singletonGeneration\s*<>\s*preemptGeneration\).*?' +
        'while\s+probeAxisIndex\s*<=\s*LMC_OWNER_AXIS_COUNT\s+do.*?' +
        'OwnershipIdentityState\[replacementHeaderBase\s*\+\s*11\].*?' +
        'OwnershipState\[replacementRecordBase\s*\+\s*4\]\$UDINT\s*=\s*preemptToken.*?' +
        'preemptBankValid\s*:=\s*FALSE\s*;') (
        "$blocker Publish special-owner singleton/replacement proof drifted.")
    Assert-Match $publishProofBlock (
        '(?s)end_while\s*;\s*if\s+preemptBankValid\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;\s*' +
        'RETURN\s*;\s*end_if\s*;\s*end_if\s*;\s*cleanupReady\s*:=' ) (
        "$blocker Publish full preemption-bank gate is missing before cleanup/mutation.")
    $publishRootIndex = $publishProofBlock.IndexOf('preemptRootValid :=')
    $publishBankGate = $publishProofBlock.LastIndexOf(
        'if preemptBankValid = FALSE then')
    $publishCleanupReady = $publishProofBlock.IndexOf('cleanupReady :=')
    $publishLiveMutation = $publishProofBlock.IndexOf(
        'OwnershipState[recordBase + 9]$UDINT := ObservationCycle;')
    $publishRootDestroy = $publishProofBlock.IndexOf(
        'OwnershipPreemptedIdentityState[' + [Environment]::NewLine +
        "`t`t`t`tLMC_OWNER_PREEMPT_HEADER_BASE] := 0;")
    if ($publishRootIndex -lt 0 -or $publishBankGate -lt 0 -or
        $publishCleanupReady -lt 0 -or $publishLiveMutation -lt 0 -or
        $publishBankGate -ge $publishCleanupReady -or
        $publishCleanupReady -ge $publishLiveMutation) {
        throw "$blocker Publish preemption proof is not complete before terminal mutation."
    }
    Assert-Match $publishProofBlock (
        '(?s)if\s+clearOwner\s+then.*?' +
        'if\s+expectedOwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\s+then.*?' +
        'if\s+expectedAdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY\s+then\s*' +
        '_memset\(dest:=#OwnershipIdentityState\[0\].*?' +
        'elsif\s+identityTailSize\s*>\s*0\s+then.*?' +
        'cntr:=identityTailSize\)\s*;.*?' +
        'if\s+\(ReportKind\s*=\s*LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*&\s*' +
        '\(forceQuarantine\s*=\s*FALSE\)\s+then\s*' +
        'if\s+preemptRootValid\s+then.*?' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\]\s*:=\s*0\s*;.*?' +
        'sizeof\(OwnershipPreemptedIdentityState\)') (
        "$blocker Publish TailSize=0 preservation or terminal-success bank destruction guard drifted.")

    # Lock the Cleanup implementation's private working set. LASAL local
    # declarations are part of the generated class ABI and accidental moves to
    # VAR_INPUT/VAR_OUTPUT or undeclared implicit names must fail verification.
    $cleanupLocalMatch = [regex]::Match(
        $cleanupBlock,
        '(?is)\bVAR\s+(?<locals>.*?)\s+END_VAR\s+Result\s*:=' )
    if (-not $cleanupLocalMatch.Success) {
        throw "$blocker cleanup local VAR block is missing."
    }
    $cleanupLocals = @([regex]::Matches(
        $cleanupLocalMatch.Groups['locals'].Value,
        '(?im)^\s*([A-Za-z][A-Za-z0-9_]*)\s*:\s*([A-Za-z][A-Za-z0-9_]*)\s*;\s*$') |
        ForEach-Object { $_.Groups[1].Value + ':' + $_.Groups[2].Value })
    $expectedCleanupLocals = @(
        'axisIndex:DINT','axisBit:UDINT','identityIndex:DINT',
        'oldRecordBase:DINT','safetyRecordBase:DINT',
        'firstSafetyRecordBase:DINT','evidenceRecordBase:DINT','observerBase:DINT',
        'evidenceObserverBase:DINT','preemptObserverBase:DINT','identityHeaderBase:DINT',
        'identityCompareResult:UDINT','preemptFlags:UDINT','cleanupRequiredMask:UDINT',
        'cleanupCompleteMask:UDINT','safetyAxisMask:UDINT','safetySession:UDINT',
        'safetySequence:UDINT','safetyPackedCommand:UDINT','safetyPackedOwner:UDINT',
        'safetyIdentitySize:UDINT','safetyIdentityPrefixSize:UDINT',
        'safetyIdentityTailOffset:UDINT','referenceAxisMask:UDINT','observerFlags:UDINT',
        'oldAxisMask:UDINT','oldSession:UDINT','oldSequence:UDINT','oldIdentitySize:UDINT',
        'oldIdentityExpectedSize:UDINT','oldIdentityPrefixSize:UDINT',
        'oldIdentityTailSize:UDINT','oldIdentityTailOffset:UDINT',
        'oldIdentityPackedCommand:UDINT','oldIdentityPackedOwner:UDINT',
        'oldCommand:DINT','oldReference:DINT',
        'oldOwnerKind:DINT','oldResourceKind:DINT','oldAdmissionMode:DINT','oldState:DINT',
        'safetyCommand:DINT','safetyReference:DINT','safetyOwnerKind:DINT',
        'safetyResourceKind:DINT','safetyAdmissionMode:DINT','safetyState:DINT',
        'publishedCleanupKind:DINT','oldFound:BOOL','safetyFound:BOOL','tupleValid:BOOL',
        'exactReplay:BOOL','replayEvidenceMatch:BOOL','cleanupAlreadyPublished:BOOL',
        'publishedCleanupValid:BOOL','oldSpecialValid:BOOL','oldBankValid:BOOL',
        'rootValid:BOOL','safetyEscalated:BOOL','safetyForceQuarantine:BOOL',
        'safetyOverlayFound:BOOL','oldIdentityValid:BOOL','oldObserverValid:BOOL',
        'safetyIdentityValid:BOOL','safetyObserverValid:BOOL')
    if ([string]::Join('|', $cleanupLocals) -cne
        [string]::Join('|', $expectedCleanupLocals)) {
        throw "$blocker cleanup local declaration inventory drifted."
    }
    Assert-Match $cleanupBlock (
        '(?s)oldFound\s*:=\s*FALSE\s*;\s*oldBankValid\s*:=\s*TRUE\s*;.*?' +
        'if\s+oldBankValid\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker Cleanup old-bank structural proof is not fail closed.")
    Assert-Match $cleanupBlock (
        '(?s)publishedCleanupKind\s*:=\s*OwnershipState\[safetyRecordBase\s*\+\s*32\]\s*;\s*' +
        'publishedCleanupValid\s*:=\s*TRUE\s*;\s*if\s+cleanupAlreadyPublished\s+then.*?' +
        'LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE.*?' +
        'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE.*?' +
        'ValidateAxisOwnershipPreemptionReplacement\s*\(.*?' +
        'OldIdentitySize\s*:=\s*oldIdentitySize\s*\)\s*;\s*' +
        'end_if\s*;\s*if\s+tupleValid\s*=\s*FALSE\s+then\s*' +
        'publishedCleanupValid\s*:=\s*FALSE\s*;.*?' +
        'if\s+cleanupAlreadyPublished\s*&\s*' +
        '\(publishedCleanupValid\s*=\s*FALSE\)\s+then.*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'if\s+exactReplay\s+then\s*Result\s*:=\s*1\s*;\s*RETURN\s*;.*?' +
        'if\s+cleanupAlreadyPublished\s+then\s*Result\s*:=\s*-2\s*;\s*RETURN\s*;') (
        "$blocker Cleanup publication/replacement replay result mapping drifted.")
}

function Invoke-LasalAxisOwnershipPreemptionCleanupVerifierSelfTest {
    param(
        [string]$RepositoryRoot
    )

    $root = (Resolve-Path -LiteralPath $RepositoryRoot).Path
    $controlPath = Join-Path $root (
        'Lasal_PRG\Elmo_EtherCAT_Test_4Axis\Class\' +
        'LMCControlCommandService\LMCControlCommandService.st')
    $control = Get-Content -Raw -LiteralPath $controlPath
    $controlScan = Get-LasalScanText $control
    $cleanupMatches = [regex]::Matches(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::' +
         'PublishAxisOwnershipPreemptionCleanup\b.*?END_FUNCTION'))
    if ($cleanupMatches.Count -ne 1) {
        throw (
            'Axis ownership preemption cleanup focused self-test found ' +
            "$($cleanupMatches.Count) implementations, expected one.")
    }
    $replacementMatches = [regex]::Matches(
        $controlScan,
        ('(?is)FUNCTION\s+' +
         'LMCControlCommandService::' +
         'ValidateAxisOwnershipPreemptionReplacement\b.*?END_FUNCTION'))
    if ($replacementMatches.Count -ne 1) {
        throw (
            'Axis ownership preemption replacement focused self-test found ' +
            "$($replacementMatches.Count) private implementations, expected one.")
    }
    $cleanupBlock = $cleanupMatches[0].Value
    $replacementBlock = $replacementMatches[0].Value
    Assert-LasalAxisOwnershipPreemptionCleanupMutationFences `
        -CleanupBlock $cleanupBlock `
        -ReplacementBlock $replacementBlock `
        -ControlServiceText $controlScan `
        -Owner 'preemption cleanup focused self-test baseline'

    $negativeFixtures = @(
        @{
            Name = 'ValidationPrefixPersistentWrite'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nOwnershipState[23] := 1;"
        },
        @{
            Name = 'ValidationPrefixLeaseStateWrite'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nOwnershipLeaseState[0] := 0;"
        },
        @{
            Name = 'ValidationPrefixStartupStateWrite'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nOwnershipStartupState[0] := 0;"
        },
        @{
            Name = 'ValidationPrefixCompoundBankWrite'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nOwnershipPreemptedState[0] += 1;"
        },
        @{
            Name = 'ValidationPrefixClientResample'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nInputLatch.CopySnapshot();"
        },
        @{
            Name = 'ValidationPrefixClockResample'
            Pattern = 'Result\s*:=\s*-1\s*;'
            Replacement = "Result := -1;`nserviceNow := ops.tAbsolute;"
        },
        @{
            Name = 'RootSafetyGenerationComparedToToken'
            Pattern = ('OwnershipPreemptedIdentityState\[\s*' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*3\]\$UDINT\s*<>\s*' +
                'SafetyOwnerGeneration')
            Replacement = ('OwnershipPreemptedIdentityState[' +
                'LMC_OWNER_PREEMPT_HEADER_BASE + 3]$UDINT <> ' +
                'SafetyAdmissionToken')
        },
        @{
            Name = 'OldRecordGenerationComparedToToken'
            Pattern = ('OwnershipPreemptedState\[' +
                'safetyRecordBase\s*\+\s*5\]\$UDINT\s*<>\s*' +
                'PreemptedOwnerGeneration')
            Replacement = ('OwnershipPreemptedState[' +
                'safetyRecordBase + 5]$UDINT <> PreemptedAdmissionToken')
        },
        @{
            Name = 'OldObserverGenerationComparedToToken'
            Pattern = ('OwnershipPreemptedIdentityState\[' +
                'preemptObserverBase\s*\+\s*2\]\$UDINT\s*=\s*' +
                'PreemptedOwnerGeneration')
            Replacement = ('OwnershipPreemptedIdentityState[' +
                'preemptObserverBase + 2]$UDINT = PreemptedAdmissionToken')
        },
        @{
            Name = 'LiveSafetyGenerationComparedToToken'
            Pattern = ('OwnershipState\[' +
                'safetyRecordBase\s*\+\s*5\]\$UDINT\s*<>\s*' +
                'SafetyOwnerGeneration')
            Replacement = ('OwnershipState[' +
                'safetyRecordBase + 5]$UDINT <> SafetyAdmissionToken')
        },
        @{
            Name = 'ExactReplayPersistentMutation'
            Pattern = 'if\s+exactReplay\s+then\s*Result\s*:=\s*1\s*;'
            Replacement = (
                "if exactReplay then`n" +
                "OwnershipState[23] := 1;`nResult := 1;")
        },
        @{
            Name = 'OldTupleFullBankAbsenceUsesAnd'
            Pattern = ('elsif\s*\(OwnershipPreemptedState\[' +
                'safetyRecordBase\s*\+\s*4\]\$UDINT\s*=\s*' +
                'PreemptedAdmissionToken\s*\)\s*\|')
            Replacement = ('elsif (OwnershipPreemptedState[' +
                'safetyRecordBase + 4]$UDINT = ' +
                'PreemptedAdmissionToken) &')
        },
        @{
            Name = 'LiveSafetyFullBankAbsenceUsesAnd'
            Pattern = ('elsif\s*\(OwnershipState\[' +
                'safetyRecordBase\s*\+\s*4\]\$UDINT\s*=\s*' +
                'SafetyAdmissionToken\s*\)\s*\|')
            Replacement = ('elsif (OwnershipState[' +
                'safetyRecordBase + 4]$UDINT = SafetyAdmissionToken) &')
        },
        @{
            Name = 'ReplacementAbsenceGenerationComparedToToken'
            Target = 'Replacement'
            Pattern = ('OwnershipState\[' +
                'replacementRecordBase\s*\+\s*5\]\$UDINT\s*=\s*' +
                'PreemptedOwnerGeneration')
            Replacement = ('OwnershipState[' +
                'replacementRecordBase + 5]$UDINT = ' +
                'PreemptedAdmissionToken')
        },
        @{
            Name = 'ReplacementAbsenceLoopDropsLastAxis'
            Target = 'Replacement'
            Pattern = ('replacementValid\s*:=\s*replacementValid\s*&\s*' +
                'replacementFound\s*;\s*end_if\s*;\s*' +
                'probeAxisIndex\s*:=\s*1\s*;\s*' +
                'while\s+probeAxisIndex\s*<=\s*LMC_OWNER_AXIS_COUNT\s+do')
            Replacement = ('replacementValid := replacementValid & ' +
                'replacementFound; end_if; probeAxisIndex := 1; ' +
                'while probeAxisIndex < LMC_OWNER_AXIS_COUNT do')
        },
        @{
            Name = 'IncompleteBankDirectDestruction'
            Pattern = ('OwnershipPreemptedIdentityState\[\s*' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\s*\]\s*:=\s*0\s*;')
            Replacement = ('OwnershipPreemptedIdentityState[' +
                'LMC_OWNER_PREEMPT_HEADER_BASE] := 0; ' +
                'OwnershipPreemptedState[0] := 0;')
        },
        @{
            Name = 'IncompleteBankMemsetDestruction'
            Pattern = ('OwnershipPreemptedIdentityState\[\s*' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\s*\]\s*:=\s*0\s*;')
            Replacement = ('OwnershipPreemptedIdentityState[' +
                'LMC_OWNER_PREEMPT_HEADER_BASE] := 0; ' +
                '_memset(dest:=#OwnershipPreemptedState[0], ' +
                'value:=0, cntr:=4);')
        },
        @{
            Name = 'QuarantineObserverUsesAnd'
            Pattern = ('OwnershipObserverState\[' +
                'observerBase\s*\+\s*5\]\$UDINT\s+or\s+' +
                'LMC_OWNER_OBSERVER_FORCE_QUARANTINE')
            Replacement = ('OwnershipObserverState[' +
                'observerBase + 5]$UDINT and ' +
                'LMC_OWNER_OBSERVER_FORCE_QUARANTINE')
        },
        @{
            Name = 'QuarantineObserverLoopDropsLastAxis'
            Pattern = ('preemptFlags\s*:=\s*preemptFlags\s+or\s+' +
                'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE\s*;\s*' +
                'axisIndex\s*:=\s*1\s*;\s*while\s+axisIndex\s*<=\s*' +
                'LMC_OWNER_AXIS_COUNT\s+do')
            Replacement = ('preemptFlags := preemptFlags or ' +
                'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE; ' +
                'axisIndex := 1; while axisIndex < ' +
                'LMC_OWNER_AXIS_COUNT do')
        },
        @{
            Name = 'QuarantineObserverLoopEarlyExit'
            Pattern = ('preemptFlags\s*:=\s*preemptFlags\s+or\s+' +
                'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE\s*;\s*' +
                'axisIndex\s*:=\s*1\s*;\s*while\s+axisIndex\s*<=\s*' +
                'LMC_OWNER_AXIS_COUNT\s+do')
            Replacement = ('preemptFlags := preemptFlags or ' +
                'LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE; ' +
                'axisIndex := 1; while axisIndex <= ' +
                'LMC_OWNER_AXIS_COUNT do EXIT;')
        },
        @{
            Name = 'EvidenceWrittenBeforeSingletonClear'
            Pattern = ('OwnershipPreemptedIdentityState\[\s*' +
                'LMC_OWNER_PREEMPT_HEADER_BASE\s*\]\s*:=\s*0\s*;')
            Replacement = ('OwnershipPreemptedIdentityState[' +
                'LMC_OWNER_PREEMPT_HEADER_BASE] := 0; ' +
                'OwnershipState[safetyRecordBase + 32] := ' +
                'TO_DINT(CleanupKind);')
        },
        @{
            Name = 'ExactReplayReturnsTwo'
            Pattern = ('if\s+exactReplay\s+then\s*' +
                'Result\s*:=\s*1\s*;')
            Replacement = 'if exactReplay then Result := 2;'
        },
        @{
            Name = 'IncompleteCleanupClearsSingleton'
            Pattern = ('if\s+CleanupKind\s*<>\s*' +
                'LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\s+then')
            Replacement = ('if CleanupKind = ' +
                'LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE then')
        },
        @{
            Name = 'ReplacementHelperMadeGlobal'
            Target = 'Replacement'
            Pattern = ('FUNCTION\s+' +
                'LMCControlCommandService::' +
                'ValidateAxisOwnershipPreemptionReplacement')
            Replacement = ('FUNCTION GLOBAL ' +
                'LMCControlCommandService::' +
                'ValidateAxisOwnershipPreemptionReplacement')
        },
        @{
            Name = 'ReplacementLocalTypeChanged'
            Target = 'Replacement'
            Pattern = 'replacementHeaderBase\s*:\s*DINT\s*;'
            Replacement = 'replacementHeaderBase : UDINT;'
        },
        @{
            Name = 'ReplacementInputAssigned'
            Target = 'Replacement'
            Pattern = 'singletonToken\s*:=\s*0\s*;'
            Replacement = (
                'singletonToken := 0; ' +
                'PreemptedAdmissionToken := singletonToken;')
        },
        @{
            Name = 'ReplacementPersistentWrite'
            Target = 'Replacement'
            Pattern = 'singletonToken\s*:=\s*0\s*;'
            Replacement = (
                'singletonToken := 0; OwnershipState[7] := 0;')
        },
        @{
            Name = 'ReplacementUnsupportedBankRead'
            Target = 'Replacement'
            Pattern = 'singletonToken\s*:=\s*OwnershipState\[7\]\$UDINT\s*;'
            Replacement = (
                'singletonToken := OwnershipLeaseState[7]$UDINT;')
        },
        @{
            Name = 'ReplacementReturnAdded'
            Target = 'Replacement'
            Pattern = 'singletonToken\s*:=\s*0\s*;'
            Replacement = 'singletonToken := 0; RETURN;'
        },
        @{
            Name = 'ReplacementCustomCallAdded'
            Target = 'Replacement'
            Pattern = 'singletonToken\s*:=\s*0\s*;'
            Replacement = 'singletonToken := 0; ProbeReplacement();'
        },
        @{
            Name = 'ReplacementSingletonMapChanged'
            Target = 'Replacement'
            Pattern = ('singletonGeneration\s*:=\s*' +
                'OwnershipState\[14\]\$UDINT\s*;')
            Replacement = 'singletonGeneration := OwnershipState[13]$UDINT;'
        },
        @{
            Name = 'ReplacementStateMapChanged'
            Target = 'Replacement'
            Pattern = 'LMC_OWNER_STATE_DS402_HOME_ACTIVE'
            Replacement = 'LMC_OWNER_STATE_LMC_HOME_ACTIVE'
        },
        @{
            Name = 'ReplacementHeaderSlotChanged'
            Target = 'Replacement'
            Pattern = ('OwnershipIdentityState\[' +
                'replacementHeaderBase\s*\+\s*11\]\$UDINT\s*=\s*' +
                'replacementTailSize')
            Replacement = ('OwnershipIdentityState[' +
                'replacementHeaderBase + 10]$UDINT = replacementTailSize')
        },
        @{
            Name = 'ReplacementResultTailChanged'
            Target = 'Replacement'
            Pattern = 'Result\s*:=\s*replacementValid\s*;'
            Replacement = 'Result := replacementFound;'
        },
        @{
            Name = 'ReplacementCallOldIdentityArgumentChanged'
            Pattern = 'OldIdentitySize\s*:=\s*oldIdentitySize'
            Replacement = 'OldIdentitySize:=oldAxisMask'
        },
        @{
            Name = 'ReplacementCallImmediateConsumerChanged'
            Pattern = ('if\s+tupleValid\s*=\s*FALSE\s+then\s*' +
                'publishedCleanupValid\s*:=\s*FALSE\s*;')
            Replacement = (
                'if exactReplay = FALSE then ' +
                'publishedCleanupValid := FALSE;')
        },
        @{
            Name = 'ReplacementCallDuplicated'
            Pattern = ('(tupleValid\s*:=\s*' +
                'ValidateAxisOwnershipPreemptionReplacement\s*\(.*?\)\s*;)')
            Replacement = '${1} ${1}'
        }
    )

    $evidenceMovePattern = (
        'OwnershipPreemptedIdentityState\[\s*' +
        'LMC_OWNER_PREEMPT_HEADER_BASE\s*\]\s*:=\s*0\s*;.*?' +
        'OwnershipState\[safetyRecordBase\s*\+\s*32\]\s*:=\s*' +
        'TO_DINT\(CleanupKind\)\s*;')
    $evidenceMoveRegex = [regex]::new(
        $evidenceMovePattern,
        [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
        [Text.RegularExpressions.RegexOptions]::Singleline)
    $evidenceMoveTargets = $evidenceMoveRegex.Matches($cleanupBlock)
    if ($evidenceMoveTargets.Count -ne 1) {
        throw (
            'Preemption cleanup pure evidence-move fixture found ' +
            "$($evidenceMoveTargets.Count) targets, expected exactly one.")
    }
    $evidenceMoveScope = $evidenceMoveTargets[0].Value
    $evidenceWriteRegex = [regex]::new(
        ('OwnershipState\[safetyRecordBase\s*\+\s*32\]\s*:=\s*' +
         'TO_DINT\(CleanupKind\)\s*;'),
        [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
        [Text.RegularExpressions.RegexOptions]::Singleline)
    $evidenceWrites = $evidenceWriteRegex.Matches($evidenceMoveScope)
    if ($evidenceWrites.Count -ne 1) {
        throw (
            'Preemption cleanup pure evidence-move fixture found ' +
            "$($evidenceWrites.Count) writes, expected exactly one.")
    }
    $evidenceWrite = $evidenceWrites[0]
    $evidenceMoveReplacement =
        $evidenceWrite.Value + "`n" +
        $evidenceMoveScope.Remove($evidenceWrite.Index, $evidenceWrite.Length)
    $negativeFixtures += @{
        Name = 'EvidenceMovedBeforeSingletonClear'
        Pattern = $evidenceMovePattern
        Replacement = $evidenceMoveReplacement
    }

    $rejected = 0
    foreach ($fixture in $negativeFixtures) {
        $fixtureTarget = if ($fixture.ContainsKey('Target')) {
            $fixture.Target
        }
        else {
            'Cleanup'
        }
        $fixtureBlock = if ($fixtureTarget -ceq 'Replacement') {
            $replacementBlock
        }
        elseif ($fixtureTarget -ceq 'Cleanup') {
            $cleanupBlock
        }
        else {
            throw (
                "Preemption cleanup focused fixture '$($fixture.Name)' has " +
                "unsupported target '$fixtureTarget'.")
        }
        $fixtureRegex = [regex]::new(
            $fixture.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline)
        $targets = $fixtureRegex.Matches($fixtureBlock)
        if ($targets.Count -ne 1) {
            throw (
                "Preemption cleanup focused fixture '$($fixture.Name)' found " +
                "$($targets.Count) $fixtureTarget targets, expected exactly one.")
        }
        $target = $targets[0]
        $mutated =
            $fixtureBlock.Substring(0, $target.Index) +
            $fixture.Replacement +
            $fixtureBlock.Substring($target.Index + $target.Length)
        if ($mutated -ceq $fixtureBlock) {
            throw (
                "Preemption cleanup focused fixture '$($fixture.Name)' " +
                'did not mutate the baseline.')
        }
        $mutatedCleanup = if ($fixtureTarget -ceq 'Cleanup') {
            $mutated
        }
        else {
            $cleanupBlock
        }
        $mutatedReplacement = if ($fixtureTarget -ceq 'Replacement') {
            $mutated
        }
        else {
            $replacementBlock
        }
        $mutatedControl = if ($fixtureTarget -ceq 'Cleanup') {
            $controlScan.Replace($cleanupBlock, $mutatedCleanup)
        }
        else {
            $controlScan.Replace($replacementBlock, $mutatedReplacement)
        }
        try {
            Assert-LasalAxisOwnershipPreemptionCleanupMutationFences `
                -CleanupBlock $mutatedCleanup `
                -ReplacementBlock $mutatedReplacement `
                -ControlServiceText $mutatedControl `
                -Owner (
                    "preemption cleanup focused negative '$($fixture.Name)'")
        }
        catch {
            if ($_.Exception.Message -notmatch
                    'axis ownership preemption cleanup blocker:') {
                throw
            }
            $rejected++
            continue
        }
        throw (
            'Preemption cleanup focused verifier accepted negative fixture ' +
            "'$($fixture.Name)'.")
    }
    if ($rejected -ne $negativeFixtures.Count) {
        throw (
            "Preemption cleanup focused verifier rejected $rejected/" +
            "$($negativeFixtures.Count) negative fixtures.")
    }

    $positiveReplacement = $replacementBlock.Replace(
        'singletonToken := 0;',
        'singletonToken := 0; // focused comment-only fixture')
    if ($positiveReplacement -ceq $replacementBlock) {
        throw 'Preemption cleanup focused positive comment fixture did not mutate.'
    }
    $positiveControl = $controlScan.Replace(
        $replacementBlock,
        $positiveReplacement)
    Assert-LasalAxisOwnershipPreemptionCleanupMutationFences `
        -CleanupBlock $cleanupBlock `
        -ReplacementBlock $positiveReplacement `
        -ControlServiceText $positiveControl `
        -Owner 'preemption cleanup focused positive comment-only fixture'
    return $rejected
}

function Invoke-LasalAxisOwnershipIdentityPreemptionVerifierSelfTest {
    param(
        [string]$RepositoryRoot
    )

    $root = (Resolve-Path -LiteralPath $RepositoryRoot).Path
    $controlPath = Join-Path $root (
        'Lasal_PRG\Elmo_EtherCAT_Test_4Axis\Class\' +
        'LMCControlCommandService\LMCControlCommandService.st')
    $control = Get-Content -Raw -LiteralPath $controlPath
    Assert-LasalAxisOwnershipIdentityPreemptionContract `
        -ControlServiceText $control `
        -Owner 'compact identity/preemption self-test baseline'
    $publishMode = Get-LasalAxisOwnershipPublishMode `
        -ControlServiceText $control
    $publishDecisionFunctionPattern = if (
        $publishMode -ceq 'SplitCandidate') {
        'FUNCTION\s+LMCControlCommandService::' +
            'PrepareAxisOwnershipPublishDecision'
    }
    else {
        'FUNCTION\s+GLOBAL\s+' +
            'LMCControlCommandService::PublishAxisOwnership'
    }

    $negativeFixtures = @(
        @{ Name = 'PrefixBytes'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_PREFIX_BYTES\s+0x00000040\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_PREFIX_BYTES 0x00000044' },
        @{ Name = 'SuffixBytes'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_SUFFIX_BYTES\s+1256\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_SUFFIX_BYTES 1252' },
        @{ Name = 'AxisHeaderBase'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_AXIS_HEADER_BASE\s+314\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_AXIS_HEADER_BASE 313' },
        @{ Name = 'GroupHeaderBase'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_GROUP_HEADER_BASE\s+422\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_GROUP_HEADER_BASE 421' },
        @{ Name = 'AxisMagic'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_AXIS_MAGIC\s+0x49444100\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_AXIS_MAGIC 0x49444110' },
        @{ Name = 'GroupMagic'; Pattern = '(?m)^#define\s+LMC_OWNER_IDENTITY_GROUP_MAGIC\s+0x49444752\s*$'; Replacement = '#define LMC_OWNER_IDENTITY_GROUP_MAGIC 0x49444753' },
        @{ Name = 'LeaseMagic'; Pattern = '(?m)^#define\s+LMC_OWNER_LEASE_IDENTITY_MAGIC\s+0x49444C53\s*$'; Replacement = '#define LMC_OWNER_LEASE_IDENTITY_MAGIC 0x49444C54' },
        @{ Name = 'PreemptMagic'; Pattern = '(?m)^#define\s+LMC_OWNER_PREEMPT_IDENTITY_MAGIC\s+0x49445052\s*$'; Replacement = '#define LMC_OWNER_PREEMPT_IDENTITY_MAGIC 0x49445053' },
        @{ Name = 'CopyMagic'; Pattern = '(?m)^#define\s+LMC_OWNER_PREEMPT_COPY_MAGIC\s+0x4C4D4350\s*$'; Replacement = '#define LMC_OWNER_PREEMPT_COPY_MAGIC 0x4C4D4351' },
        @{ Name = 'CopyHeaderSize'; Pattern = '(?m)^#define\s+LMC_OWNER_PREEMPT_COPY_HEADER_BYTES\s+144\s*$'; Replacement = '#define LMC_OWNER_PREEMPT_COPY_HEADER_BYTES 140' },
        @{ Name = 'CleanupStatus'; Pattern = '(?m)^#define\s+LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED\s+2\s*$'; Replacement = '#define LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED 5' },
        @{ Name = 'CleanupKind'; Pattern = '(?m)^#define\s+LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\s+3\s*$'; Replacement = '#define LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE 4' },
        @{ Name = 'OneByteIdentityRounded'; Pattern = '(?is)(elsif\s+CommandId\s*=\s*0x2024\s+then\s*identityShapeValid\s*:=\s*IdentitySize\s*=\s*)1(\s*;)'; Replacement = '${1}4${2}' },
        @{ Name = 'GroupIdentitySize'; Pattern = '(?is)(elsif\s+CommandId\s*=\s*0x20E7\s+then\s*identityShapeValid\s*:=\s*IdentitySize\s*=\s*)1320(\s*;)'; Replacement = '${1}1316${2}' },
        @{ Name = 'HomeIdentitySize'; Pattern = '(?is)(elsif\s+CommandId\s*=\s*0x7D13\s+then\s*identityShapeValid\s*:=\s*IdentitySize\s*=\s*)56(\s*;)'; Replacement = '${1}52${2}' },
        @{ Name = 'DiagnosticsIdentitySize'; Pattern = '(?is)(elsif\s+\(CommandId\s*=\s*0x7D15\).*?identityShapeValid\s*:=\s*IdentitySize\s*=\s*)72(\s*;)'; Replacement = '${1}68${2}' },
        @{ Name = 'TailAxisOffset'; Pattern = 'identityTailOffset\s*:=\s*TO_UDINT\(Reference\s*-\s*1\)\s*\*\s*8\s*;'; Replacement = 'identityTailOffset := TO_UDINT(Reference) * 8;' },
        @{ Name = 'PrefixCopyRounded'; Pattern = '(?is)(_memcpy\(ptr1:=#OwnershipState\[recordBase\s*\+\s*16\],\s*ptr2:=pIdentityBytes,\s*cntr:=)identityPrefixSize(\)\s*;)'; Replacement = '${1}LMC_OWNER_IDENTITY_PREFIX_BYTES${2}' },
        @{ Name = 'AxisHeaderMagicLast'; Pattern = '(?is)(OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*:=\s*)LMC_OWNER_IDENTITY_AXIS_MAGIC(\s*\+\s*TO_UDINT\(axisIndex\)\s*;)'; Replacement = '${1}LMC_OWNER_IDENTITY_GROUP_MAGIC${2}' },
        @{ Name = 'GroupHeaderMagicLast'; Pattern = '(?is)(OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*:=\s*)LMC_OWNER_IDENTITY_GROUP_MAGIC(\s*;)'; Replacement = '${1}LMC_OWNER_IDENTITY_AXIS_MAGIC${2}' },
        @{ Name = 'LeaseSuffixCopy'; Pattern = '(?is)(_memcpy\(ptr1:=#OwnershipLeaseIdentityState\[0\],.*?cntr:=)LMC_OWNER_IDENTITY_SUFFIX_BYTES(\)\s*;)'; Replacement = '${1}sizeof(OwnershipLeaseIdentityState)${2}' },
        @{ Name = 'PreemptObserverCopy'; Pattern = '(?is)(_memcpy\(ptr1:=#OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_OBSERVER_BASE\],.*?cntr:=)sizeof\(OwnershipObserverState\)(\)\s*;)'; Replacement = '${1}104${2}' },
        @{ Name = 'PreemptRootPublish'; Pattern = '(?is)(OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*:=\s*)LMC_OWNER_PREEMPT_IDENTITY_MAGIC(\s*;)'; Replacement = '${1}LMC_OWNER_PREEMPT_COPY_MAGIC${2}' },
        @{ Name = 'ValidateWrapperBypass'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::ValidateAxisOwnershipIdentity.*?Result\s*:=\s*)ValidateAxisOwnership(\s*\()'; Replacement = '${1}ValidateAxisOwnershipIdentity${2}' },
        @{ Name = 'ValidatePrefixLength'; Pattern = '(?is)(_memcmp\(\s*ptr1:=#OwnershipState\[recordBase\s*\+\s*16\],\s*ptr2:=pIdentityBytes,\s*cntr:=)identityPrefixSize(\))'; Replacement = '${1}IdentitySize${2}' },
        @{ Name = 'ValidateTailSource'; Pattern = '(?is)(ptr2:=pIdentityBytes\s*\+\s*)LMC_OWNER_IDENTITY_PREFIX_BYTES(,\s*cntr:=identityTailSize)'; Replacement = '${1}identityPrefixSize${2}' },
        @{ Name = 'AbsentBankUpperBound'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::CopyAxisOwnershipPreemption.*?while\s+stateIndex\s*<=\s*323\s+do.*?while\s+stateIndex\s*<=\s*)431(\s+do)'; Replacement = '${1}430${2}' },
        @{ Name = 'OldHomeMetadataSize'; Pattern = '(?is)(0x7D13\s*:\s*identityExpectedSize\s*:=\s*)56(\s*;)'; Replacement = '${1}52${2}' },
        @{ Name = 'PartialOverlapAccepted'; Pattern = '(?is)(\(\(oldAxisMask\s+and\s+safetyAxisMask\)\s*<>\s*0\)\s*&\s*\(\(oldAxisMask\s+and\s+safetyAxisMask\)\s*)<>\s*oldAxisMask'; Replacement = '${1}= oldAxisMask' },
        @{ Name = 'DisjointCondition'; Pattern = 'if\s+\(oldAxisMask\s+and\s+safetyAxisMask\)\s*=\s*0\s+then'; Replacement = 'if (oldAxisMask and safetyAxisMask) <> 0 then' },
        @{ Name = 'DisjointReservedState'; Pattern = '(?is)(LMC_OWNER_KIND_DIRECT\s*:\s*currentStateValid\s*:=\s*OwnershipState\[currentRecordBase\s*\+\s*1\]\s*=\s*)LMC_OWNER_STATE_DIRECT_ACTIVE'; Replacement = '${1}LMC_OWNER_STATE_RESERVED' },
        @{ Name = 'DisjointTupleSession'; Pattern = '(?is)(OwnershipState\[currentRecordBase\s*\+\s*6\]\$UDINT\s*<>\s*)oldSession'; Replacement = '${1}oldSequence' },
        @{ Name = 'DisjointGroupHeader'; Pattern = '(?is)(if\s+oldOwnerKind\s*=\s*LMC_OWNER_KIND_GROUP.*?OwnershipIdentityState\[identityHeaderBase\]\$UDINT\s*<>\s*)LMC_OWNER_IDENTITY_GROUP_MAGIC'; Replacement = '${1}LMC_OWNER_IDENTITY_AXIS_MAGIC' },
        @{ Name = 'DisjointPrefixSource'; Pattern = '(?is)(ptr1:=#OwnershipState\[currentRecordBase\s*\+\s*16\],\s*ptr2:=#)OwnershipPreemptedState(\[recordBase\s*\+\s*16\])'; Replacement = '${1}OwnershipState${2}' },
        @{ Name = 'DisjointTailLength'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::CopyAxisOwnershipPreemption.*?ptr2:=#OwnershipPreemptedIdentityState\[\s*TO_DINT\(identityTailOffset\s*/\s*4\)\],\s*cntr:=)identityTailSize'; Replacement = '${1}identityPrefixSize' },
        @{ Name = 'DisjointFailureQuarantine'; Pattern = '(?is)(if\s+disjointCurrentValid\s*=\s*FALSE\s+then\s*OwnershipState\[24\]\s*:=\s*1\s*;\s*Result\s*:=\s*)-3'; Replacement = '${1}LMC_OWNER_PREEMPT_STATUS_NONE' },
        @{ Name = 'PendingFreezeStatus'; Pattern = '(?is)(if\s+safetyState\s*=\s*LMC_OWNER_STATE_RESERVED\s+then\s*Result\s*:=\s*)LMC_OWNER_PREEMPT_STATUS_PENDING_FREEZE'; Replacement = '${1}LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED' },
        @{ Name = 'PayloadCapacityError'; Pattern = '(?is)(totalSize\s*:=.*?if\s+DestSize\s*<\s*totalSize\s+then\s*Result\s*:=\s*)-4'; Replacement = '${1}-3' },
        @{ Name = 'CopyHeaderTokenOffset'; Pattern = '(?is)(\(pDestBytes\s*\+\s*36\)\^\$UDINT\s*:=\s*)oldToken'; Replacement = '${1}oldGeneration' },
        @{ Name = 'CopyHeaderReserved'; Pattern = '(?is)(\(pDestBytes\s*\+\s*140\)\^\$UDINT\s*:=\s*)0'; Replacement = '${1}1' },
        @{ Name = 'CopyIdentityOffset'; Pattern = '(?is)(_memcpy\(ptr1:=pDestBytes\s*\+\s*)LMC_OWNER_PREEMPT_COPY_HEADER_BYTES(,\s*ptr2:=#OwnershipPreemptedState)'; Replacement = '${1}140${2}' },
        @{ Name = 'CopyMagicLast'; Pattern = '(?is)(pDestBytes\^\$UDINT\s*:=\s*)LMC_OWNER_PREEMPT_COPY_MAGIC(\s*;\s*END_FUNCTION)'; Replacement = '${1}LMC_OWNER_PREEMPT_IDENTITY_MAGIC${2}' },
        @{ Name = 'CleanupAllowsReserved'; Pattern = '(?is)(\(\(safetyState\s*<>\s*LMC_OWNER_STATE_SAFETY_PREEMPTING\)\s*&\s*\(safetyState\s*<>\s*LMC_OWNER_STATE_QUARANTINED\)\))'; Replacement = '(($1) & (safetyState <> LMC_OWNER_STATE_RESERVED))' },
        @{ Name = 'CleanupReplayObserver'; Pattern = '(?is)(OwnershipObserverState\[evidenceObserverBase\s*\+\s*)11(\]\$UDINT\s*=\s*ObservationCycle)'; Replacement = '${1}10${2}' },
        @{ Name = 'CleanupReplayResult'; Pattern = '(?is)(if\s+exactReplay\s+then\s*Result\s*:=\s*)1(\s*;\s*RETURN)'; Replacement = '${1}0${2}' },
        @{ Name = 'IncompleteClearsSingleton'; Pattern = '(?is)(if\s+CleanupKind\s*)<>(\s*LMC_OWNER_CLEANUP_INCOMPLETE_QUARANTINE\s+then)'; Replacement = '${1}=${2}' },
        @{ Name = 'CleanupForceFlag'; Pattern = '(?is)(preemptFlags\s*:=\s*preemptFlags\s+)or(\s+LMC_OWNER_PREEMPT_FLAG_FORCE_QUARANTINE\s*;)'; Replacement = '${1}and${2}' },
        @{ Name = 'CleanupEvidenceSlot'; Pattern = '(?is)(OwnershipState\[safetyRecordBase\s*\+\s*)33(\]\$UDINT\s*:=\s*ReportValue0)'; Replacement = '${1}32${2}' },
        @{ Name = 'CleanupRootMagicLast'; Pattern = '(?is)(OwnershipPreemptedIdentityState\[\s*LMC_OWNER_PREEMPT_HEADER_BASE\]\$UDINT\s*:=\s*)LMC_OWNER_PREEMPT_IDENTITY_MAGIC(\s*;\s*Result\s*:=\s*0)'; Replacement = '${1}LMC_OWNER_PREEMPT_COPY_MAGIC${2}' },
        @{ Name = 'ReserveOrdinaryGroupGlobalCollision'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::ReserveAxisOwnership.*?\(AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY\)\s*&\s*)liveNonGroupFound(\s+then)'; Replacement = '${1}((liveNonGroupMask and RequestedAxisMask) <> 0)${2}' },
        @{ Name = 'ReserveFreshSafetyOutsideMask'; Pattern = '(?is)(\(\(liveNonGroupMask\s+and\s+RequestedAxisMask\)\s*<>\s*)liveNonGroupMask(\))'; Replacement = '${1}RequestedAxisMask${2}' },
        @{ Name = 'ReserveOrphanLeaseAccepted'; Pattern = '(?is)(if\s+\(liveGroupFound\s*=\s*FALSE\)\s*&\s*\(liveNonGroupFound\s*=\s*FALSE\)\s+then\s*)if\s+leaseAvailable\s+then'; Replacement = '${1}if FALSE then' },
        @{ Name = 'ReserveDirtyObserverAccepted'; Pattern = '(?is)(if\s+\(OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP\).*?OwnershipObserverState\[observerBase\s*\+\s*observerIndex\]\s*)<>(\s*0)'; Replacement = '${1}=${2}' },
        @{ Name = 'ReserveSafetyTailAllowed'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::ReserveAxisOwnership.*?if\s+)safetyPreemption(\s*&\s*\(identityTailSize\s*>\s*0\)\s+then)'; Replacement = '${1}FALSE${2}' },
        @{ Name = 'ReserveLeaseIdentitySize'; Pattern = '(?is)(if\s+leaseAvailable\s+then\s*existingIdentityValid\s*:=.*?LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\s*\+\s*2\]\$UDINT\s*=\s*)1(\))'; Replacement = '${1}4${2}' },
        @{ Name = 'RollbackGroupAggregation'; Pattern = '(?is)(FUNCTION\s+LMCControlCommandService::ValidateAxisOwnershipRollbackPreemptBank.*?restoredGroupActive\s*:=\s*)TRUE(\s*;)'; Replacement = '${1}FALSE${2}' },
        @{ Name = 'RollbackMixedGroupAccepted'; Pattern = '(?is)(FUNCTION\s+LMCControlCommandService::ValidateAxisOwnershipRollbackPreemptBank.*?if\s+restoredGroupFound\s*&\s*)restoredNonSafetyFound(\s+then)'; Replacement = '${1}FALSE${2}' },
        @{ Name = 'RollbackLeaseIdentitySize'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::RollbackAxisOwnership.*?if\s+restoreLease\s*\|\s*restoredGroupActive\s+then.*?LMC_OWNER_LEASE_IDENTITY_HEADER_BASE\s*\+\s*2\]\$UDINT\s*=\s*)1(\))'; Replacement = '${1}4${2}' },
        @{ Name = 'RollbackRecordRestoreLength'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::RollbackAxisOwnership.*?_memcpy\(ptr1:=#OwnershipState\[recordBase\],\s*ptr2:=#OwnershipPreemptedState\[clearIndex\],\s*cntr:=)LMC_OWNER_AXIS_STRIDE\s*\*\s*4(\))'; Replacement = '${1}140${2}' },
        @{ Name = 'RollbackTailZeroClear'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::RollbackAxisOwnership.*?if\s+restorePreempt\s+then\s*)if\s+identityTailSize\s*>\s*0\s+then'; Replacement = '${1}if TRUE then' },
        @{ Name = 'RollbackGroupMagicSuppressed'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::RollbackAxisOwnership.*?end_while\s*;\s*if\s+)groupHeaderPublished(\s+then\s*OwnershipIdentityState\[\s*LMC_OWNER_IDENTITY_GROUP_HEADER_BASE\])'; Replacement = '${1}FALSE${2}' },
        @{ Name = 'PublishRootSequence'; Pattern = ('(?is)(' + $publishDecisionFunctionPattern + '.*?LMC_OWNER_PREEMPT_HEADER_BASE\s*\+\s*6\]\$UDINT\s*=\s*)expectedSequence'); Replacement = '${1}expectedSession' },
        @{ Name = 'PublishDirtyAbsentRoot'; Pattern = ('(?is)(' + $publishDecisionFunctionPattern + '.*?preemptRootValid\s*=\s*FALSE.*?while\s+identityIndex\s*<=\s*)431(\s+do)'); Replacement = '${1}430${2}' },
        @{ Name = 'PublishReplacementOldToken'; Pattern = ('(?is)(' + $publishDecisionFunctionPattern + '.*?singletonToken\s*)<>(\s*preemptToken)'); Replacement = '${1}=${2}' },
        @{ Name = 'PublishPreproofBypass'; Pattern = ('(?is)(' + $publishDecisionFunctionPattern + '.*?if\s+preemptBankValid\s*=\s*)FALSE(\s+then\s*OwnershipState\[24\].*?Result\s*:=\s*-3\s*;\s*RETURN\s*;)'); Replacement = '${1}TRUE${2}' },
        @{ Name = 'PublishTailZeroClear'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnership.*?if\s+clearOwner\s+then.*?)elsif\s+identityTailSize\s*>\s*0\s+then'; Replacement = '${1}elsif TRUE then' },
        @{ Name = 'CleanupLocalMoved'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnershipPreemptionCleanup.*?publishedCleanupValid\s*:\s*)BOOL(\s*;)'; Replacement = '${1}DINT${2}' },
        @{ Name = 'CleanupOldBankStartsInvalid'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnershipPreemptionCleanup.*?oldBankValid\s*:=\s*)TRUE(\s*;)'; Replacement = '${1}FALSE${2}' },
        @{ Name = 'CleanupPublishedValidationBypass'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnershipPreemptionCleanup.*?if\s+cleanupAlreadyPublished\s*&\s*\(publishedCleanupValid\s*=\s*)FALSE(\)\s+then)'; Replacement = '${1}TRUE${2}' },
        @{ Name = 'CleanupPublishedCallerMismatch'; Pattern = '(?is)(FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnershipPreemptionCleanup.*?if\s+cleanupAlreadyPublished\s+then\s*Result\s*:=\s*)-2(\s*;\s*RETURN)'; Replacement = '${1}-3${2}' },
        @{ Name = 'CleanupReplacementOldToken'; Pattern = '(?is)(FUNCTION\s+LMCControlCommandService::ValidateAxisOwnershipPreemptionReplacement.*?singletonToken\s*)<>(\s*PreemptedAdmissionToken)'; Replacement = '${1}=${2}' })

    $rejected = 0
    foreach ($fixture in $negativeFixtures) {
        $fixtureRegex = [regex]::new(
            $fixture.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase)
        $mutated = $fixtureRegex.Replace($control, $fixture.Replacement, 1)
        if ($mutated -ceq $control) {
            throw "Compact identity/preemption negative fixture '$($fixture.Name)' did not mutate the baseline."
        }
        try {
            Assert-LasalAxisOwnershipIdentityPreemptionContract `
                -ControlServiceText $mutated `
                -Owner "compact identity/preemption negative self-test '$($fixture.Name)'"
        }
        catch {
            if ($_.Exception.Message -notmatch
                    ('compact ownership identity/preemption blocker|' +
                     'axis ownership preemption cleanup blocker:|' +
                      'axis ownership rollback mutation blocker:|' +
                      'axis ownership rollback split blocker:|' +
                      'axis ownership publish mutation blocker:|' +
                      'axis ownership publish split blocker:|' +
                      'axis ownership reserve mutation blocker:')) {
                throw
            }
            $rejected++
            continue
        }
        throw (
            'Compact identity/preemption verifier accepted negative fixture ' +
            "'$($fixture.Name)'.")
    }
    if ($rejected -ne $negativeFixtures.Count) {
        throw "Compact identity/preemption verifier rejected $rejected/$($negativeFixtures.Count) negative fixtures."
    }
    return $rejected
}

function Assert-LasalAxisOwnershipCommitAtomicity {
    param(
        [string]$ControlServiceText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $ControlServiceText
    $commitBlock = [regex]::Match(
        $scan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::CommitAxisOwnership.*?END_FUNCTION')).Value
    $blocker = "$Owner common axis ownership activation blocker: ownership commit"
    if ([string]::IsNullOrWhiteSpace($commitBlock)) {
        throw "$blocker CommitAxisOwnership implementation is missing."
    }

    $validateMatches = [regex]::Matches(
        $commitBlock,
        ('(?is)Result\s*:=\s*ValidateAxisOwnership\(\s*' +
         'CommandId\s*:=\s*CommandId\s*,\s*' +
         'Reference\s*:=\s*Reference\s*,\s*' +
         'ExpectedAxisMask\s*:=\s*ExpectedAxisMask\s*,\s*' +
         'OwnerKind\s*:=\s*ownerKind\s*,\s*' +
         'ResourceKind\s*:=\s*resourceKind\s*,\s*' +
         'AdmissionMode\s*:=\s*admissionMode\s*,\s*' +
         'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
         'RequestSequence\s*:=\s*RequestSequence\s*,\s*' +
         'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
         'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
         'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*\)\s*;\s*' +
         'if\s+Result\s*<>\s*0\s+then\s*RETURN\s*;\s*end_if\s*;'))
    if ($validateMatches.Count -ne 1) {
        throw (
            "$blocker the exact command/axis/admission/session/sequence/" +
            'token/generation tuple must be validated once, and its result ' +
            'must reject before mutation.')
    }

    $loopMatches = [regex]::Matches(
        $commitBlock,
        '(?i)\bwhile\s+axisIndex\s*<=\s*LMC_OWNER_AXIS_COUNT\s+do\b')
    $endLoopMatches = [regex]::Matches(
        $commitBlock,
        '(?i)\bend_while\s*;')
    $mutationMatches = [regex]::Matches(
        $commitBlock,
        ('(?i)OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]' +
         '\s*:=\s*activeState\s*;'))
    if (($loopMatches.Count -ne 2) -or
        ($endLoopMatches.Count -ne 2) -or
        ($mutationMatches.Count -ne 1)) {
        throw "$blocker expected one read loop and one mutation loop."
    }

    $validateIndex = $validateMatches[0].Index
    $mutationIndex = $mutationMatches[0].Index
    if (-not (
            $loopMatches[0].Index -lt $endLoopMatches[0].Index -and
            $endLoopMatches[0].Index -lt $validateIndex -and
            $validateIndex -lt $loopMatches[1].Index -and
            $loopMatches[1].Index -lt $mutationIndex -and
            $mutationIndex -lt $endLoopMatches[1].Index)) {
        throw (
            "$blocker validation must finish before any selected axis is " +
            'changed from Reserved to Active.')
    }
}

function Assert-LasalAxisOwnershipStartupReconcilerContract {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$InputLatchText,
        [string]$Owner
    )

    $tcpScan = Get-LasalScanText $TcpText
    $controlScan = Get-LasalScanText $ControlServiceText
    $diagnosticsScan = Get-LasalScanText $DiagnosticsText
    $latchScan = Get-LasalScanText $InputLatchText
    $combinedScan = ($tcpScan, $controlScan, $diagnosticsScan, $latchScan) -join "`n"
    $blocker = "$Owner common axis ownership activation blocker: startup reconciliation"

    foreach ($removedPattern in @(
            '(?i)\bLMC_OWNER_STARTUP_PROOF_BOOT_ID\b',
            '(?i)\bReportAxisOwnershipStartup\b',
            ('(?i)FUNCTION\s+(?:VIRTUAL\s+)?(?:GLOBAL\s+)?' +
             'LMCEcatInputLatch::Get[A-Za-z0-9_]*AxisOwnership[A-Za-z0-9_]*Flags\b'))) {
        if ($combinedScan -match $removedPattern) {
            throw "$blocker removed partial-proof or scalar startup ABI remains."
        }
    }

    $reconcileMatches = [regex]::Matches(
        $controlScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::' +
            'ReconcileAxisOwnershipStartup\b.*?END_FUNCTION')
    $copyMatches = [regex]::Matches(
        $latchScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCEcatInputLatch::' +
            'CopyAxisOwnershipStartupSnapshot\b.*?END_FUNCTION')
    $diagnosticsStartupMatches = [regex]::Matches(
        $diagnosticsScan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::' +
            'ProcessAxisOwnershipStartup\b.*?END_FUNCTION')
    if ($reconcileMatches.Count -ne 1 -or
        $copyMatches.Count -ne 1 -or
        $diagnosticsStartupMatches.Count -ne 1) {
        throw (
            "$blocker expected exactly one reconciler, coherent snapshot " +
            'reader, and private diagnostics startup implementation.')
    }
    if ($diagnosticsScan -match
            '(?i)FUNCTION\s+GLOBAL\s+LMCDiagnosticsService::' +
            'ProcessAxisOwnershipStartup\b') {
        throw "$blocker ProcessAxisOwnershipStartup must remain PRIVATE."
    }

    $reconcileBlock = $reconcileMatches[0].Value
    $copyBlock = $copyMatches[0].Value
    $diagnosticsStartupBlock = $diagnosticsStartupMatches[0].Value
    $processOperationsBlock = [regex]::Match(
        $diagnosticsScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCDiagnosticsService::' +
            'ProcessOperations\b.*?END_FUNCTION').Value
    $tcpCyWorkBlock = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+' +
            'TCPMotionInterface::CyWork\b.*?END_FUNCTION').Value
    $latchRtWorkBlock = [regex]::Match(
        $latchScan,
        '(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+' +
            'LMCEcatInputLatch::RtWork\b.*?END_FUNCTION').Value
    if ([string]::IsNullOrWhiteSpace($processOperationsBlock) -or
        [string]::IsNullOrWhiteSpace($tcpCyWorkBlock) -or
        [string]::IsNullOrWhiteSpace($latchRtWorkBlock)) {
        throw "$blocker required cyclic producer/caller block is missing."
    }

    if ($tcpCyWorkBlock -match
            '(?i)ReconcileAxisOwnershipStartup|CopyAxisOwnershipStartupSnapshot') {
        throw "$blocker TCP CyWork bypasses the diagnostics startup owner."
    }
    Assert-Match $tcpCyWorkBlock (
        '(?s)ControlCommands\.ProcessAxisZeroHome\(\).*?' +
        'ControlCommands\.ProcessAxisOwnership\(\).*?' +
        'Diagnostics\.ProcessOperations\(\)') (
        "$blocker TCP cyclic Home/ownership/diagnostics processing is incomplete.")

    Assert-Match $processOperationsBlock (
        '(?s)ProcessEncoderMaintenance\(\);\s*' +
        'ProcessAxisDs402Home\(\);\s*' +
        'ProcessAxisOwnershipStartup\(\);\s*' +
        'if\s*\(LMC_DIAG_D5_SDO_READ_ENABLED\s*=\s*FALSE\)\s*&\s*' +
        '\(LMC_DIAG_D5_SDO_WRITE_GLOBAL_ENABLED\s*=\s*FALSE\)\s*then\s*' +
        'RETURN;') (
        "$blocker diagnostics startup call is not before the generic-SDO early return.")

    Assert-Match $copyBlock (
        '(?s)Result\s*:=\s*-1;\s*' +
        'if\s*\(pDest\s*=\s*NIL\)\s*\|\s*\(DestSize\s*<\s*48\)\s*then\s*' +
        'Result\s*:=\s*-2;\s*RETURN;\s*end_if;\s*' +
        'retryCount\s*:=\s*0;\s*while\s+retryCount\s*<\s*3\s+do.*?' +
        'sequenceBefore\s*:=\s*sigclib_atomic_getU32\(' +
        'pValue:=#PublishSequence\);.*?' +
        'if\s*\(sequenceBefore\s+and\s+1\)\s*=\s*0\s+then\s*' +
        '_memcpy\(ptr1:=pDest,\s*ptr2:=#SnapshotBytes\[464\],\s*cntr:=48\);.*?' +
        'sequenceAfter\s*:=\s*sigclib_atomic_getU32\(' +
        'pValue:=#PublishSequence\);.*?' +
        'sequenceBefore\s*=\s*sequenceAfter.*?' +
        'sequenceAfter\s+and\s+1.*?sequenceAfter\s*<>\s*0.*?' +
        'Result\s*:=\s*0;\s*RETURN;.*?' +
        'retryCount\s*\+=\s*1;\s*end_while;') (
        "$blocker 48-byte offset-464 bounded seqlock copy is incomplete.")
    if ([regex]::Matches($copyBlock, 'Result\s*:=\s*0;').Count -ne 1 -or
        [regex]::Matches($copyBlock, 'retryCount\s*\+=\s*1;').Count -ne 1) {
        throw "$blocker snapshot reader must have one success and one retry increment."
    }

    $startupSnapshotFields = @(
        @{ Offset = 464; Value = 'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC' },
        @{ Offset = 468; Value = 'cycleCounter' },
        @{ Offset = 472; Value = 'ownershipAxis1Status\$UDINT' },
        @{ Offset = 476; Value = 'ownershipAxis2Status\$UDINT' },
        @{ Offset = 480; Value = 'ownershipAxis3Status\$UDINT' },
        @{ Offset = 484; Value = 'ownershipAxis4Status\$UDINT' },
        @{ Offset = 488; Value = 'SnapshotBytes\[84\]\$UDINT' },
        @{ Offset = 492; Value = 'SnapshotBytes\[120\]\$UDINT' },
        @{ Offset = 496; Value = 'SnapshotBytes\[156\]\$UDINT' },
        @{ Offset = 500; Value = 'SnapshotBytes\[192\]\$UDINT' },
        @{ Offset = 504; Value = 'ownershipLatchDrainFlags' },
        @{ Offset = 508; Value = '0' })
    $writerOpen = [regex]::Match(
        $latchRtWorkBlock,
        'sigclib_atomic_setU32\(pValue:=#PublishSequence,\s*value:=writeSequence\)')
    $writerClose = [regex]::Match(
        $latchRtWorkBlock,
        'sigclib_atomic_setU32\(pValue:=#PublishSequence,\s*value:=finalSequence\)')
    if (-not $writerOpen.Success -or -not $writerClose.Success -or
        $writerOpen.Index -ge $writerClose.Index) {
        throw "$blocker RT snapshot writer interval is missing."
    }
    foreach ($startupField in $startupSnapshotFields) {
        $fieldMatches = [regex]::Matches(
            $latchRtWorkBlock,
            'SnapshotBytes\[' + $startupField.Offset + '\]\$UDINT\s*:=\s*' +
                $startupField.Value + '\s*;')
        if ($fieldMatches.Count -ne 1 -or
            $fieldMatches[0].Index -le $writerOpen.Index -or
            $fieldMatches[0].Index -ge $writerClose.Index) {
            throw (
                "$blocker RT startup snapshot offset $($startupField.Offset) " +
                'must have one exact UDINT write inside the publish interval.')
        }
    }
    $latchDrainMatch = [regex]::Match(
        $latchRtWorkBlock,
        'SnapshotBytes\[504\]\$UDINT\s*:=\s*' +
            '(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*;')
    if (-not $latchDrainMatch.Success) {
        throw "$blocker latch drain-flag publication was not found."
    }
    $latchDrainName = [regex]::Escape($latchDrainMatch.Groups['Name'].Value)
    if ([regex]::Matches(
            $latchRtWorkBlock,
            '\b' + $latchDrainName + '\s*:=\s*0\s*;').Count -ne 1) {
        throw "$blocker latch drain flags need one fail-closed zero initialization."
    }
    Assert-Match $latchScan (
        '(?m)^\s*#define\s+LMC_OWNER_STARTUP_SNAPSHOT_MAGIC\s+' +
        '0x4C4D4353\s*$') (
        "$blocker latch startup snapshot magic must remain exact.")
    $latchDrainContracts = [ordered]@{
        'LMC_OWNER_STARTUP_LATCH_PHYSICAL' = @{
            Value = '0x00000001'; Uses = 1
        }
        'LMC_OWNER_STARTUP_LATCH_ZERO_HOME' = @{
            Value = '0x00000002'; Uses = 2
        }
        'LMC_OWNER_STARTUP_LATCH_DS402' = @{
            Value = '0x00000004'; Uses = 1
        }
        'LMC_OWNER_STARTUP_LATCH_OWNER' = @{
            Value = '0x00000008'; Uses = 1
        }
        'LMC_OWNER_STARTUP_LATCH_START_LOW' = @{
            Value = '0x00000010'; Uses = 1
        }
    }
    foreach ($drainContract in $latchDrainContracts.GetEnumerator()) {
        Assert-Match $latchScan (
            '(?m)^\s*#define\s+' + [regex]::Escape($drainContract.Key) +
            '\s+' + [regex]::Escape($drainContract.Value.Value) + '\s*$') (
            "$blocker latch drain constant $($drainContract.Key) drifted.")
        $drainUseCount = [regex]::Matches(
                $latchRtWorkBlock,
                '\b' + $latchDrainName + '\s*:=\s*' + $latchDrainName +
                    '\s+or\s+' + [regex]::Escape($drainContract.Key) +
                    '\s*;').Count
        if ($drainUseCount -ne $drainContract.Value.Uses) {
            throw (
                "$blocker latch drain bit $($drainContract.Key) is not " +
                "published exactly $($drainContract.Value.Uses) time(s).")
        }
    }
    Assert-Match $latchRtWorkBlock (
        '(?s)AxisZeroHomeRequestSequence.*?AxisZeroHomeAppliedSequence.*?' +
        'if\s+zeroHomeRequestSequence\s*=\s*zeroHomeAppliedSequence\s+then\s*' +
        'if\s*\(zeroHomeRequestSequence\s*=\s*0\)\s*&\s*' +
        '\(AxisZeroHomeResult\[0\]\s*=\s*0\)\s*&\s*' +
        '\(AxisZeroHomeResult\[1\]\s*=\s*0\)\s*&\s*' +
        '\(AxisZeroHomeResult\[22\]\s*=\s*0\)\s*then.*?' +
        'LMC_OWNER_STARTUP_LATCH_ZERO_HOME.*?' +
        'elsif\s*\(AxisZeroHomeMailbox\[3\]\$UDINT\s*=\s*' +
        'zeroHomeRequestSequence\)\s*&\s*' +
        '\(AxisZeroHomeResult\[0\]\$UDINT\s*=\s*' +
        'AxisZeroHomeMailbox\[0\]\$UDINT\)\s*&\s*' +
        '\(AxisZeroHomeResult\[3\]\s*=\s*AxisZeroHomeMailbox\[1\]\)\s*&\s*' +
        '\(AxisZeroHomeResult\[4\]\s*=\s*AxisZeroHomeMailbox\[2\]\)\s*&\s*' +
        '\(AxisZeroHomeResult\[22\]\$UDINT\s*=\s*' +
        'zeroHomeAppliedSequence\)\s*&\s*' +
        '\(\(AxisZeroHomeResult\[1\]\s*=\s*' +
        'LMC_ZERO_HOME_STATE_SUCCEEDED\)\s*\|\s*' +
        '\(AxisZeroHomeResult\[1\]\s*=\s*' +
        'LMC_ZERO_HOME_STATE_FAILED\)\)\s*then.*?' +
        'LMC_OWNER_STARTUP_LATCH_ZERO_HOME') (
        "$blocker Zero Home request/applied terminal drain predicate is incomplete.")
    Assert-Match $latchRtWorkBlock (
        '(?s)Ds402HomeRequestSequence.*?Ds402HomeAppliedSequence.*?' +
        'if\s+homeRequestSequence\s*=\s*homeAppliedSequence\s+then.*?' +
        'LMC_OWNER_STARTUP_LATCH_DS402.*?' +
        'if\s*\(Ds402HomeMailbox\[0\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeMailbox\[1\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeMailbox\[10\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeMailbox\[11\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeAlignmentState\[0\]\s*=\s*0\)\s*then.*?' +
        'LMC_OWNER_STARTUP_LATCH_OWNER') (
        "$blocker DS402 request/owner/alignment drain predicate is incomplete.")
    foreach ($controlWordOffset in @(216, 240, 264, 288)) {
        Assert-Match $latchRtWorkBlock (
            'SnapshotBytes\[' + $controlWordOffset + '\]\$UDINT\s+and\s+' +
            '0x00000010') (
            "$blocker ControlWord bit 4 drain guard is missing at offset $controlWordOffset.")
    }

    Assert-Match $reconcileBlock (
        '(?s)if\s*\(DiagnosticsBootId\s*=\s*0\)\s*\|\s*' +
        '\(ObservationCycle\s*=\s*0\)\s*\|\s*' +
        '\(ReportCycle\s*=\s*0\)\s*then\s*RETURN;') (
        "$blocker reconciler does not reject zero identity/cycle/time inputs.")
    $controlStartupConstants = [ordered]@{
        'LMC_OWNER_STARTUP_STATE_MAGIC' = '0x4F575350'
        'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC' = '0x4C4D4353'
        'LMC_OWNER_STARTUP_LATCH_REQUIRED' = '0x0000001F'
        'LMC_OWNER_STARTUP_DIAG_REQUIRED' = '0x0000001F'
        'LMC_OWNER_STARTUP_STABLE_SAMPLES' = '3'
        'LMC_OWNER_STARTUP_STABLE_MS' = '100'
        'LMC_OWNER_STARTUP_AXIS_CLEAR_MASK' = '0x05028890'
        'LMC_OWNER_STARTUP_AXIS_LOCK_MASK' = '0x01000800'
    }
    foreach ($startupConstant in $controlStartupConstants.GetEnumerator()) {
        Assert-Match $controlScan (
            '(?m)^\s*#define\s+' + [regex]::Escape($startupConstant.Key) +
            '\s+' + [regex]::Escape($startupConstant.Value) + '\s*$') (
            "$blocker control startup constant $($startupConstant.Key) drifted.")
    }
    $sameBootMatch = [regex]::Match(
        $reconcileBlock,
        ('(?s)if\s*\(OwnershipState\[0\]\$UDINT\s*=\s*' +
         'LMC_OWNER_TABLE_MAGIC\)\s*&\s*' +
         '\(OwnershipState\[3\]\$UDINT\s*=\s*DiagnosticsBootId\)\s*then\s*' +
         'if\s*\(OwnershipState\[4\]\$UDINT\s*<>\s*0\)\s*&\s*' +
         '\(OwnershipState\[5\]\$UDINT\s*=\s*' +
         'LMC_OWNER_STARTUP_PROOF_REQUIRED\)\s*&\s*' +
         '\(OwnershipState\[6\]\s*=\s*0\)\s*&\s*' +
         '\(OwnershipState\[24\]\s*=\s*0\)\s*then\s*' +
         'Result\s*:=\s*0;\s*else\s*Result\s*:=\s*-3;\s*' +
         'end_if;\s*RETURN;\s*end_if;'))
    $reconcileCopyMatch = [regex]::Match(
        $reconcileBlock,
        ('InputLatch\.CopyAxisOwnershipStartupSnapshot\(\s*' +
         'pDest:=#[A-Za-z_][A-Za-z0-9_]*\[0\],\s*DestSize:=48\)'))
    if (-not $sameBootMatch.Success -or -not $reconcileCopyMatch.Success -or
        $sameBootMatch.Index -ge $reconcileCopyMatch.Index) {
        throw (
            "$blocker same-BootId exact-proof/non-quarantine success must " +
            'precede transient snapshot re-evaluation.')
    }
    Assert-Match $reconcileBlock (
        '(?s)startupSnapshot\[0\](?:\$UDINT)?\s*<>\s*' +
        'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC.*?' +
        'startupSnapshot\[1\](?:\$UDINT)?\s*=\s*0.*?' +
        'startupSnapshot\[1\](?:\$UDINT)?\s*<>\s*ObservationCycle.*?' +
        'startupSnapshot\[11\](?:\$UDINT)?\s*<>\s*0') (
        "$blocker reconciler snapshot magic/cycle/reserved validation is incomplete.")
    if ($reconcileBlock -match '(?i)ReadAxisError\s*\(' -or
        $reconcileBlock -match '(?i)\bLMCAxis[5-9]\b') {
        throw "$blocker reconciler adds an AxisError-zero or simulation-axis startup dependency."
    }
    Assert-Match $reconcileBlock (
        'startupSnapshot\[10\]\s+and\s+0x00000001\)\s*<>\s*0') (
        "$blocker coherent latch physical-health bit is not required.")
    foreach ($axisNumber in 1..4) {
        $axisName = "LMCAxis$axisNumber"
        Assert-Match $reconcileBlock (
            'IsClientConnected\(#' + $axisName + '\)') (
            "$blocker reconciler physical connection proof is missing $axisName.")
        Assert-Match $latchRtWorkBlock (
            '(?s)IsClientConnected\(#' + $axisName + '\).*?' +
            'ownershipAxis' + $axisNumber + 'Status\s*:=\s*' +
            $axisName + '\.ReadAxisStatus\(\)') (
            "$blocker RT physical status observation is missing $axisName.")
        $snapshotAxisIndex = $axisNumber + 1
        Assert-Match $reconcileBlock (
            'startupSnapshot\[' + $snapshotAxisIndex + '\]\s+and\s+' +
            'LMC_AXIS_STATUS_STANDSTILL\)\s*<>\s*0') (
            "$blocker Standstill proof is missing for physical axis $axisNumber.")
        Assert-Match $reconcileBlock (
            'startupSnapshot\[' + $snapshotAxisIndex + '\]\s+and\s+' +
            'LMC_OWNER_STARTUP_AXIS_CLEAR_MASK\)\s*=\s*0') (
            "$blocker moving/lock/brake clear mask is missing for physical axis $axisNumber.")
        Assert-Match $reconcileBlock (
            'startupSnapshot\[' + $snapshotAxisIndex + '\]\s+and\s+' +
            'LMC_OWNER_STARTUP_AXIS_LOCK_MASK\)\s*=\s*0') (
            "$blocker Group master-lock proof is missing for physical axis $axisNumber.")
    }
    foreach ($groupProofPattern in @(
            'IsClientConnected\(#LMCRobot\)',
            '(?s)ReadRobotParameter\(.*?_ROBOT_STATE',
            '(?s)ReadProfileParameter\(.*?_LMCPROF_LockState',
            '(?s)ProfileInPosition\(.*?_LMCPROF_ProfileFinished',
            'profileLock(?:State)?\s*=\s*0',
            '(?s)_ROBOT_PASSIVE.*?_ROBOT_DIRECT.*?profileFinished')) {
        Assert-Match $reconcileBlock $groupProofPattern (
            "$blocker Group/profile/robot idle proof is incomplete.")
    }
    $drainedContract = [regex]::Match(
        $reconcileBlock,
        ('(?s)(?:' +
         'drained\s*:=\s*' +
         '\(startupSnapshot\[10\]\s*=\s*LMC_OWNER_STARTUP_LATCH_REQUIRED\)\s*&\s*' +
         '\(DiagnosticsDrainFlags\s*=\s*LMC_OWNER_STARTUP_DIAG_REQUIRED\)\s*&\s*' +
         '\(ZeroHomeState\[0\]\s*<>\s*LMC_HOME_RECORD_RUNNING\)\s*&\s*' +
         '\(ZeroHomeState\[0\]\s*<>\s*LMC_HOME_RECORD_QUARANTINED\)' +
         '|' +
         'if\s*\(startupSnapshot\[10\]\s*<>\s*LMC_OWNER_STARTUP_LATCH_REQUIRED\)\s*\|\s*' +
         '\(DiagnosticsDrainFlags\s*<>\s*LMC_OWNER_STARTUP_DIAG_REQUIRED\)\s*\|\s*' +
         '\(ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_RUNNING\)\s*\|\s*' +
         '\(ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_QUARANTINED\)\s*then' +
         ')'))
    if (-not $drainedContract.Success) {
        throw (
            "$blocker local and diagnostics drain proof is incomplete.")
    }
    $sameCycleDirect = [regex]::Match(
        $reconcileBlock,
        ('(?s)if\s+OwnershipStartupState\[2\]\$UDINT\s*=\s*' +
         'ObservationCycle\s+then\s*Result\s*:=\s*1;\s*RETURN;\s*end_if;'))
    $sameCycleFresh = [regex]::Match(
        $reconcileBlock,
        ('(?s)elsif\s+OwnershipStartupState\[2\]\$UDINT\s*<>\s*' +
         'ObservationCycle\s+then.*?freshObservation\s*:=\s*TRUE;.*?' +
         'if\s+freshObservation\s*=\s*FALSE\s+then\s*RETURN;\s*end_if;'))
    if (-not $sameCycleDirect.Success -and -not $sameCycleFresh.Success) {
        throw "$blocker same-cycle replay can increase startup stability."
    }
    Assert-Match $reconcileBlock (
        'OwnershipStartupState\[3\]\s*<\s*' +
        'LMC_OWNER_STARTUP_STABLE_SAMPLES') (
        "$blocker exact three-fresh-sample guard is missing.")
    Assert-Match $reconcileBlock (
        '(?s)ReportCycle\s*-\s*OwnershipStartupState\[14\]\$UDINT.*?' +
        'LMC_OWNER_STARTUP_STABLE_MS') (
        "$blocker exact 100-ms stability guard is missing.")
    foreach ($startupSlot in 0..15) {
        Assert-Match $reconcileBlock ('OwnershipStartupState\[' + $startupSlot + '\]') (
            "$blocker fixed OwnershipStartupState slot $startupSlot is unused.")
    }
    Assert-Match $reconcileBlock (
        'OwnershipStartupState\[0\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_STARTUP_STATE_MAGIC') (
        "$blocker startup state magic is not retained.")
    $fullProofMatch = [regex]::Match(
        $reconcileBlock,
        '(?:combinedProof|proofFlags)\s*<>\s*LMC_OWNER_STARTUP_PROOF_REQUIRED')
    $ownerInitializeMatch = [regex]::Match(
        $reconcileBlock,
        '_memset\(dest:=#OwnershipState\[0\],\s*usByte:=0,\s*cntr:=1408\)')
    $ownerMagicMatch = [regex]::Match(
        $reconcileBlock,
        'OwnershipState\[0\]\$UDINT\s*:=\s*LMC_OWNER_TABLE_MAGIC')
    $ownerProofMatch = [regex]::Match(
        $reconcileBlock,
        'OwnershipState\[5\]\$UDINT\s*:=\s*LMC_OWNER_STARTUP_PROOF_REQUIRED')
    if (-not $fullProofMatch.Success -or -not $ownerInitializeMatch.Success -or
        -not $ownerMagicMatch.Success -or -not $ownerProofMatch.Success -or
        $fullProofMatch.Index -ge $ownerInitializeMatch.Index -or
        $ownerInitializeMatch.Index -ge $ownerMagicMatch.Index -or
        $ownerMagicMatch.Index -ge $ownerProofMatch.Index) {
        throw "$blocker full proof does not dominate owner-table initialization."
    }

    $diagnosticsStartupConstants = [ordered]@{
        'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC' = '0x4C4D4353'
        'LMC_OWNER_STARTUP_DIAG_SNAPSHOT' = '0x00000001'
        'LMC_OWNER_STARTUP_DIAG_DS402' = '0x00000002'
        'LMC_OWNER_STARTUP_DIAG_ENCODER' = '0x00000004'
        'LMC_OWNER_STARTUP_DIAG_GENERIC' = '0x00000008'
        'LMC_OWNER_STARTUP_DIAG_EXECUTOR' = '0x00000010'
    }
    foreach ($startupConstant in
            $diagnosticsStartupConstants.GetEnumerator()) {
        Assert-Match $diagnosticsScan (
            '(?m)^\s*#define\s+' + [regex]::Escape($startupConstant.Key) +
            '\s+' + [regex]::Escape($startupConstant.Value) + '\s*$') (
            "$blocker diagnostics startup constant $($startupConstant.Key) drifted.")
    }
    Assert-Match $diagnosticsStartupBlock (
        '(?s)InputLatch\.CopyAxisOwnershipStartupSnapshot\(\s*' +
        'pDest:=#[A-Za-z_][A-Za-z0-9_]*\[0\],\s*DestSize:=48\).*?' +
        'startupSnapshot\[0\](?:\$UDINT)?\s*(?:=|<>)\s*' +
        'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC.*?' +
        'startupSnapshot\[1\](?:\$UDINT)?\s*(?:=|<>)\s*0.*?' +
        'startupSnapshot\[11\](?:\$UDINT)?\s*(?:=|<>)\s*0') (
        "$blocker diagnostics does not validate one coherent startup snapshot.")
    Assert-Match $diagnosticsStartupBlock (
        '(?s)Ds402HomeState\[92\]\s*=\s*0.*?' +
        'EncoderMaintenanceState\[152\]\s*=\s*0.*?' +
        'OperationState\s*<>\s*LMC_DIAG_SDO_STATE_QUEUED.*?' +
        'OperationState\s*<>\s*LMC_DIAG_SDO_STATE_RUNNING.*?' +
        'SdoInternalDrainState\s*=\s*0') (
        "$blocker diagnostics lifecycle/generic-SDO drain proof is incomplete.")
    foreach ($sdoAxis in 1..4) {
        Assert-Match $diagnosticsStartupBlock (
            '(?s)IsClientConnected\(#SdoAxis' + $sdoAxis + '\).*?' +
            'SdoAxis' + $sdoAxis + '\.IsReusable\(\)') (
            "$blocker diagnostics executor $sdoAxis drain proof is incomplete.")
    }
    $startupReconcileCall = [regex]::Match(
        $diagnosticsStartupBlock,
        ('(?s)AxisOwnership\.ReconcileAxisOwnershipStartup\(\s*' +
         'DiagnosticsBootId:=(?<Boot>[A-Za-z_][A-Za-z0-9_]*),\s*' +
         'ObservationCycle:=(?<Observation>' +
         '[A-Za-z_][A-Za-z0-9_]*(?:\[\d+\])?),\s*' +
         'ReportCycle:=(?<Report>[A-Za-z_][A-Za-z0-9_]*),\s*' +
         'DiagnosticsDrainFlags:=(?<Drain>[A-Za-z_][A-Za-z0-9_]*)\)'))
    if (-not $startupReconcileCall.Success) {
        throw "$blocker diagnostics reconciler call ABI/order is incomplete."
    }
    $diagnosticsDrainName = [regex]::Escape(
        $startupReconcileCall.Groups['Drain'].Value)
    $diagnosticsDrainProofs = [ordered]@{
        'snapshot' =
            ('startupSnapshot\[11\](?:\$UDINT)?\s*(?:=|<>)\s*0.*?' +
             $diagnosticsDrainName + '\s*:=\s*(?:' +
             $diagnosticsDrainName + '\s+or\s+)?' +
             'LMC_OWNER_STARTUP_DIAG_SNAPSHOT')
        'DS402 Home' =
            ('Ds402HomeState\[92\]\s*=\s*0.*?' +
             $diagnosticsDrainName + '\s*:=\s*' +
             $diagnosticsDrainName + '\s+or\s+' +
             'LMC_OWNER_STARTUP_DIAG_DS402')
        'encoder maintenance' =
            ('EncoderMaintenanceState\[152\]\s*=\s*0.*?' +
             $diagnosticsDrainName + '\s*:=\s*' +
             $diagnosticsDrainName + '\s+or\s+' +
             'LMC_OWNER_STARTUP_DIAG_ENCODER')
        'generic SDO' =
            ('(?s)OperationState\s*<>\s*LMC_DIAG_SDO_STATE_QUEUED.*?' +
             'SdoInternalDrainState\s*=\s*0.*?' +
             $diagnosticsDrainName + '\s*:=\s*' +
             $diagnosticsDrainName + '\s+or\s+' +
             'LMC_OWNER_STARTUP_DIAG_GENERIC')
        'executor' =
            ($diagnosticsDrainName + '\s*:=\s*' +
             $diagnosticsDrainName + '\s+or\s+' +
             'LMC_OWNER_STARTUP_DIAG_EXECUTOR')
    }
    foreach ($diagnosticsDrainProof in
            $diagnosticsDrainProofs.GetEnumerator()) {
        Assert-Match $diagnosticsStartupBlock (
            '(?s)' + $diagnosticsDrainProof.Value) (
            "$blocker diagnostics $($diagnosticsDrainProof.Key) drain bit is incomplete.")
    }
    $startupCallCount = [regex]::Matches(
        $controlScan + "`n" + $diagnosticsScan + "`n" + $tcpScan,
        '\.ReconcileAxisOwnershipStartup\s*\(').Count
    if ($startupCallCount -ne 1) {
        throw "$blocker reconciler call count is $startupCallCount, expected diagnostics-only one."
    }
}

function Assert-LasalAxisOwnershipPhaseContract {
    param(
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $controlScan = Get-LasalScanText $ControlServiceText
    $diagnosticsScan = Get-LasalScanText $DiagnosticsText
    $blocker = "$Owner common axis ownership activation blocker: phase contract"

    foreach ($constant in @(
            @{ Text = $controlScan; Name = 'LMC_OWNER_PHASE_RESERVED'; Value = '1' },
            @{ Text = $controlScan; Name = 'LMC_OWNER_PHASE_ACTIVE'; Value = '2' },
            @{ Text = $diagnosticsScan; Name = 'LMC_DIAG_OWNER_PHASE_RESERVED'; Value = '1' },
            @{ Text = $diagnosticsScan; Name = 'LMC_DIAG_OWNER_PHASE_ACTIVE'; Value = '2' })) {
        $matches = [regex]::Matches(
            $constant.Text,
            ('(?im)^\s*#define\s+' + [regex]::Escape($constant.Name) +
             '\s+(?<Value>[^\s]+)\s*$'))
        if ($matches.Count -ne 1 -or
            $matches[0].Groups['Value'].Value -cne $constant.Value) {
            throw (
                "$blocker $($constant.Name) must occur exactly once with " +
                "value $($constant.Value).")
        }
    }

    $validateBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ValidateAxisOwnership.*?END_FUNCTION')).Value
    $reserveBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership.*?END_FUNCTION')).Value
    $handleRequestBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::HandleRequest.*?END_FUNCTION')).Value
    $commitBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::CommitAxisOwnership.*?END_FUNCTION')).Value
    $homeStartBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+LMCControlCommandService::' +
         'HandleAxisZeroHomeCommands.*?END_FUNCTION')).Value
    $homeProcessBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ProcessAxisZeroHome.*?END_FUNCTION')).Value
    $encoderStartBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleEncoderMaintenanceStart.*?END_FUNCTION')).Value
    $encoderProcessBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'ProcessEncoderMaintenance.*?END_FUNCTION')).Value
    $ds402StartBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeStart.*?END_FUNCTION')).Value
    $ds402ProcessBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'ProcessAxisDs402Home.*?END_FUNCTION')).Value
    $ds402ReceiptBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeReceiptStages.*?END_FUNCTION')).Value
    $ds402CleanupStagesBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeCleanupStages.*?END_FUNCTION')).Value
    $ds402ReceiptPresent =
        -not [string]::IsNullOrWhiteSpace($ds402ReceiptBlock)
    $ds402CleanupPresent =
        -not [string]::IsNullOrWhiteSpace($ds402CleanupStagesBlock)
    if ($ds402ReceiptPresent -ne $ds402CleanupPresent) {
        throw "$blocker DS402 split helpers must be both present or both absent."
    }
    $requiredBlocks = @(
            @{ Name = 'ValidateAxisOwnership'; Text = $validateBlock },
            @{ Name = 'ReserveAxisOwnership'; Text = $reserveBlock },
            @{ Name = 'HandleRequest'; Text = $handleRequestBlock },
            @{ Name = 'CommitAxisOwnership'; Text = $commitBlock },
            @{ Name = 'Home Start'; Text = $homeStartBlock },
            @{ Name = 'Home Process'; Text = $homeProcessBlock },
            @{ Name = 'Encoder Start'; Text = $encoderStartBlock },
            @{ Name = 'Encoder Process'; Text = $encoderProcessBlock },
            @{ Name = 'DS402 Start'; Text = $ds402StartBlock },
            @{ Name = 'DS402 Process'; Text = $ds402ProcessBlock })
    if ($ds402ReceiptPresent) {
        $requiredBlocks += @(
            @{ Name = 'DS402 receipt helper'; Text = $ds402ReceiptBlock },
            @{ Name = 'DS402 cleanup helper'; Text = $ds402CleanupStagesBlock })
    }
    foreach ($requiredBlock in $requiredBlocks) {
        if ([string]::IsNullOrWhiteSpace($requiredBlock.Text)) {
            throw "$blocker $($requiredBlock.Name) implementation is missing."
        }
    }

    if ($ds402ReceiptPresent) {
        $ds402SteadyProcessBlock =
            $ds402ProcessBlock + "`n" + $ds402CleanupStagesBlock
        $ds402CleanupSearchBlock = $ds402CleanupStagesBlock
        $diagnosticsActivationScan = $diagnosticsScan.Replace(
            $ds402ReceiptBlock,
            '')
    }
    else {
        $ds402PreparedReconcile = [regex]::Match(
            $ds402ProcessBlock,
            ('(?is)if\s+stage\s*=\s*89\s+then.*?' +
             '(?=_memset\(dest:=#preemptionSnapshot\[0\])'))
        $ds402SteadyProcessBlock = $ds402ProcessBlock
        $diagnosticsActivationScan = $diagnosticsScan
        if ($ds402PreparedReconcile.Success) {
            $ds402SteadyProcessBlock = $ds402ProcessBlock.Remove(
                $ds402PreparedReconcile.Index,
                $ds402PreparedReconcile.Length)
            $diagnosticsActivationScan = $diagnosticsScan.Replace(
                $ds402PreparedReconcile.Value,
                '')
        }
        $ds402CleanupSearchBlock = $ds402ProcessBlock
    }

    Assert-Match $validateBlock (
        '(?s)RequiredPhase\s*:\s*UINT\s*;.*?' +
        'Result\s*:=\s*-1\s*;.*?' +
        'RequiredPhase\s*<>\s*LMC_OWNER_PHASE_RESERVED.*?' +
        'RequiredPhase\s*<>\s*LMC_OWNER_PHASE_ACTIVE.*?' +
        'RequiredPhase\s*<>\s*' +
        'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK.*?' +
        'RETURN\s*;') (
        "$blocker RequiredPhase is not a final fail-closed UINT selector.")
    foreach ($specialReserve in @(
            @{ Resource = 'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE';
                Kind = 'LMC_OWNER_KIND_LMC_HOME'; Command = '0x7D13' },
            @{ Resource = 'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE';
                Kind = 'LMC_OWNER_KIND_DS402_HOME'; Command = '0x7D15' },
            @{ Resource = 'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE';
                Kind = 'LMC_OWNER_KIND_ENCODER'; Command = '0x7E53' })) {
        $reserveBranch = [regex]::Match(
            $reserveBlock,
            ('(?is)elsif\s+ResourceKind\s*=\s*' +
             $specialReserve.Resource + '\s+then(?<Body>.*?)' +
             '(?=\s*elsif\s+ResourceKind\s*=|\s*else\s+RETURN\s*;)'))
        if (-not $reserveBranch.Success) {
            throw "$blocker reserve resource branch for $($specialReserve.Command) is missing."
        }
        Assert-Match $reserveBranch.Groups['Body'].Value (
            '(?s)' +
            'OwnerKind\s*<>\s*' + $specialReserve.Kind + '.*?' +
            'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_LIFECYCLE.*?' +
            'CommandId\s*<>\s*' + $specialReserve.Command + '.*?' +
            'referenceAxisMask\s*=\s*0.*?' +
            'referenceAxisMask\s*>\s*0x00000008.*?' +
            'RequestedAxisMask\s*<>\s*referenceAxisMask.*?RETURN\s*;') (
            "$blocker reserve tuple for $($specialReserve.Command) is not exact.")
    }
    Assert-Match $validateBlock (
        '(?s)case\s+Reference\s+of\s*' +
        '1\s*:\s*referenceAxisMask\s*:=\s*0x00000001\s*;.*?' +
        '2\s*:\s*referenceAxisMask\s*:=\s*0x00000002\s*;.*?' +
        '3\s*:\s*referenceAxisMask\s*:=\s*0x00000004\s*;.*?' +
        '4\s*:\s*referenceAxisMask\s*:=\s*0x00000008\s*;.*?' +
        '5\s*:\s*referenceAxisMask\s*:=\s*0x00000010\s*;.*?' +
        '6\s*:\s*referenceAxisMask\s*:=\s*0x00000020\s*;.*?' +
        '7\s*:\s*referenceAxisMask\s*:=\s*0x00000040\s*;.*?' +
        '8\s*:\s*referenceAxisMask\s*:=\s*0x00000080\s*;.*?' +
        '9\s*:\s*referenceAxisMask\s*:=\s*0x00000100\s*;') (
        "$blocker validation reference-to-axis mask is not exact Axis1..9.")
    $tupleCase = [regex]::Match(
        $validateBlock,
        '(?is)tupleValid\s*:=\s*FALSE\s*;\s*(?<Body>case\s+CommandId\s+of.*?end_case\s*;)')
    if (-not $tupleCase.Success) {
        throw "$blocker ValidateAxisOwnership exact command tuple case is missing."
    }
    $tupleAssignments = [regex]::Matches(
        $validateBlock,
        '(?i)\btupleValid\s*:=')
    $tupleArmAssignments = [regex]::Matches(
        $tupleCase.Groups['Body'].Value,
        '(?i)\btupleValid\s*:=')
    $tupleInitializers = [regex]::Matches(
        $validateBlock,
        '(?i)\btupleValid\s*:=\s*FALSE\s*;')
    $tupleCaseEnd = $tupleCase.Index + $tupleCase.Length
    $tupleAssignmentOutsideClassifier = $false
    foreach ($tupleAssignment in $tupleAssignments) {
        if ($tupleAssignment.Index -lt $tupleCase.Index -or
            $tupleAssignment.Index -ge $tupleCaseEnd) {
            $tupleAssignmentOutsideClassifier = $true
            break
        }
    }
    if ($tupleAssignments.Count -ne 13 -or
        $tupleArmAssignments.Count -ne 12 -or
        $tupleInitializers.Count -ne 1 -or
        $tupleAssignmentOutsideClassifier) {
        throw (
            "$blocker tupleValid assignment inventory drifted; expected " +
            'one FALSE initializer and one assignment in each of 12 tuple arms.')
    }
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $tupleCase.Groups['Body'].Value `
        -Owner "$blocker ValidateAxisOwnership tuple classifier" `
        -ExpectedCommandIds @(
            '2022', '2023', '2024', '2047', '2048', '2049', '204A',
            '204B', '2085', '209F', '20A0', '20A2', '20A4', '20E7',
            '7D22', '7D13', '7D15', '7E53')
    $tupleArms = @{}
    foreach ($command in @('0x2022', '0x2023', '0x2048', '0x2085',
            '0x7D13', '0x7D15', '0x7E53')) {
        $arm = [regex]::Match(
            $tupleCase.Groups['Body'].Value,
            ('(?ims)^\s*' + [regex]::Escape($command) +
             '\s*:\s*(?<Body>.*?)(?=^\s*(?:0x[0-9A-Fa-f]|else\b))'))
        if (-not $arm.Success) {
            throw "$blocker validation tuple arm $command is missing."
        }
        $tupleArms[$command] = $arm.Groups['Body'].Value
    }
    Assert-Match $tupleArms['0x2022'] (
        '(?s)OwnerKind\s*=\s*LMC_OWNER_KIND_DIRECT.*?' +
        'ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY.*?' +
        'referenceAxisMask\s*<>\s*0.*?' +
        'ExpectedAxisMask\s*<=\s*LMC_OWNER_ROBOT_AXIS_MASK.*?' +
        '\(ExpectedAxisMask\s+and\s+referenceAxisMask\)\s*<>\s*0') (
        "$blocker 0x2022 validation must retain the widened safety mask containing Reference.")
    Assert-Match $tupleArms['0x2023'] (
        '(?s)OwnerKind\s*=\s*LMC_OWNER_KIND_DIRECT.*?' +
        'ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?' +
        'referenceAxisMask\s*<>\s*0.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_ORDINARY.*?' +
        'ExpectedAxisMask\s*=\s*referenceAxisMask.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY.*?' +
        'ExpectedAxisMask\s*<=\s*LMC_OWNER_ROBOT_AXIS_MASK.*?' +
        '\(ExpectedAxisMask\s+and\s+referenceAxisMask\)\s*<>\s*0') (
        "$blocker 0x2023 ordinary/safety mask alternatives drifted.")
    Assert-Match $tupleArms['0x2048'] (
        '(?s)OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP.*?' +
        'ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY.*?' +
        'Reference\s*=\s*0x0100.*?' +
        'ExpectedAxisMask\s*=\s*LMC_OWNER_PROFILE_AXIS_MASK') (
        "$blocker 0x2048 validation must retain the exact profile-axis mask.")
    Assert-Match $tupleArms['0x2085'] (
        '(?s)OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP.*?' +
        'ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY.*?' +
        'Reference\s*=\s*0x0100.*?' +
        'ExpectedAxisMask\s*=\s*LMC_OWNER_PROFILE_AXIS_MASK.*?\|.*?' +
        'ExpectedAxisMask\s*=\s*LMC_OWNER_ROBOT_AXIS_MASK') (
        "$blocker 0x2085 validation must accept only profile or robot mask.")
    foreach ($specialTuple in @(
            @{ Command = '0x7D13'; Kind = 'LMC_OWNER_KIND_LMC_HOME';
                Resource = 'LMC_OWNER_RESOURCE_LMC_HOME_ENGINE' },
            @{ Command = '0x7D15'; Kind = 'LMC_OWNER_KIND_DS402_HOME';
                Resource = 'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE' },
            @{ Command = '0x7E53'; Kind = 'LMC_OWNER_KIND_ENCODER';
                Resource = 'LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE' })) {
        Assert-Match $tupleArms[$specialTuple.Command] (
            '(?s)tupleValid\s*:=.*?' +
            'OwnerKind\s*=\s*' + $specialTuple.Kind + '.*?' +
            'ResourceKind\s*=\s*' + $specialTuple.Resource + '.*?' +
            'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_LIFECYCLE.*?' +
            'referenceAxisMask\s*<>\s*0.*?' +
            'referenceAxisMask\s*<=\s*0x00000008.*?' +
            'ExpectedAxisMask\s*=\s*referenceAxisMask') (
            "$blocker validation tuple for $($specialTuple.Command) is not exact.")
    }
    $tupleReject = [regex]::Match(
        $validateBlock,
        '(?is)if\s+tupleValid\s*=\s*FALSE\s+then\s*RETURN\s*;\s*end_if\s*;')
    $phaseSelection = [regex]::Match(
        $validateBlock,
        'expectedState\s*:=\s*LMC_OWNER_STATE_RESERVED')
    if (-not ($tupleReject.Success -and $phaseSelection.Success) -or
        $tupleReject.Index -ge $phaseSelection.Index) {
        throw "$blocker malformed command tuples are not rejected before phase selection."
    }
    $phaseStateAssignments = [regex]::Matches(
        $validateBlock,
        '(?i)\bexpectedState\s*:=')
    if ($phaseStateAssignments.Count -ne 8 -or
        $phaseStateAssignments[0].Index -ne $phaseSelection.Index) {
        throw (
            "$blocker expectedState assignment inventory drifted; expected " +
            'one RESERVED default, one exact session-close rollback state, ' +
            'and six exact ACTIVE selections.')
    }
    Assert-Match $validateBlock (
        '(?s)expectedState\s*:=\s*LMC_OWNER_STATE_RESERVED\s*;.*?' +
        'RequiredPhase\s*=\s*' +
        'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK.*?' +
        'CommandId\s*<>\s*0x7D15.*?' +
        'OwnerKind\s*<>\s*LMC_OWNER_KIND_DS402_HOME.*?' +
        'ResourceKind\s*<>\s*LMC_OWNER_RESOURCE_DS402_HOME_ENGINE.*?' +
        'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_LIFECYCLE.*?' +
        'expectedState\s*:=\s*LMC_OWNER_STATE_QUARANTINED\s*;.*?' +
        'RequiredPhase\s*=\s*LMC_OWNER_PHASE_ACTIVE.*?' +
        'AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY.*?' +
        'OwnerKind\s*=\s*LMC_OWNER_KIND_DIRECT.*?' +
        'OwnerKind\s*=\s*LMC_OWNER_KIND_GROUP.*?' +
        'expectedState\s*:=\s*LMC_OWNER_STATE_SAFETY_PREEMPTING\s*;.*?' +
        'case\s+OwnerKind\s+of.*?' +
        'LMC_OWNER_KIND_DIRECT\s*:\s*expectedState\s*:=\s*' +
        'LMC_OWNER_STATE_DIRECT_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_GROUP\s*:\s*expectedState\s*:=\s*' +
        'LMC_OWNER_STATE_GROUP_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_LMC_HOME\s*:\s*expectedState\s*:=\s*' +
        'LMC_OWNER_STATE_LMC_HOME_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_DS402_HOME\s*:\s*expectedState\s*:=\s*' +
        'LMC_OWNER_STATE_DS402_HOME_ACTIVE\s*;.*?' +
        'LMC_OWNER_KIND_ENCODER\s*:\s*expectedState\s*:=\s*' +
        'LMC_OWNER_STATE_TW20_QUEUED\s*;.*?' +
        'else\s+RETURN\s*;.*?end_case\s*;') (
        "$blocker session-close rollback or ACTIVE owner-state matrix is incomplete.")
    Assert-Match $validateBlock (
        '(?s)OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*=\s*' +
        'LMC_OWNER_STATE_QUARANTINED\s*\)\s*&\s*' +
        '\(RequiredPhase\s*<>\s*' +
        'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK\)\s*then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker quarantined records are not restricted to the exact " +
        'session-close rollback phase.')
    $phaseStateComparison = [regex]::Match(
        $validateBlock,
        'OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*<>\s*expectedState')
    if (-not $phaseStateComparison.Success) {
        throw "$blocker selected records are not compared with the phase state."
    }
    foreach ($phaseStateAssignment in $phaseStateAssignments) {
        if ($phaseStateAssignment.Index -lt $phaseSelection.Index -or
            $phaseStateAssignment.Index -ge $phaseStateComparison.Index) {
            throw (
                "$blocker expectedState assignment location drifted; phase " +
                'selection must complete exactly once before record comparison.')
        }
    }
    foreach ($forbiddenState in @(
            'LMC_OWNER_STATE_GROUP_LEASE',
            'LMC_OWNER_STATE_TW20_RUNNING',
            'LMC_OWNER_STATE_TW20_DRAINING')) {
        if ($validateBlock -match ('(?i)\b' + [regex]::Escape($forbiddenState) + '\b')) {
            throw "$blocker $forbiddenState must never satisfy ACTIVE validation."
        }
    }

    $handleRequestCall = (
        'ownershipValidationResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*CommandId\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*\(pRequestFrame\s*\+\s*8\)\$\^void\s*,\s*' +
        'IdentitySize\s*:=\s*ownershipPayloadSize\s*\)\s*;')
    $commitCall = (
        'Result\s*:=\s*ValidateAxisOwnership\(\s*' +
        'CommandId\s*:=\s*CommandId\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*\)\s*;')
    $homeStartCall = (
        'adminHomeOwnerResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*0x7D13\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnershipState\[19\]\$UDINT\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*pRequest(?:\$\^void)?\s*,\s*' +
        'IdentitySize\s*:=\s*RequestSize\s*\)\s*;')
    $encoderStartCall = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*0x7E53\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*pRequest(?:\$\^void)?\s*,\s*' +
        'IdentitySize\s*:=\s*RequestSize\s*\)\s*;')
    $encoderProcessCall = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7E53\s*,.*?' +
        'OwnerGeneration\s*:=\s*ownerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;')
    $ds402StartCall = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*0x7D15\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*pRequest(?:\$\^void)?\s*,\s*' +
        'IdentitySize\s*:=\s*RequestSize\s*\)\s*;')
    $ds402StartActiveCall = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7D15\s*,.*?' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;')
    $ds402ProcessCall = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7D15\s*,.*?' +
        'OwnerGeneration\s*:=\s*ownerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;')
    foreach ($call in @(
            @{ Name = 'HandleRequest RESERVED'; Block = $handleRequestBlock; Pattern = $handleRequestCall },
            @{ Name = 'Commit RESERVED'; Block = $commitBlock; Pattern = $commitCall },
            @{ Name = 'Home Start RESERVED'; Block = $homeStartBlock; Pattern = $homeStartCall },
            @{ Name = 'Encoder Start RESERVED'; Block = $encoderStartBlock; Pattern = $encoderStartCall },
            @{ Name = 'Encoder Process ACTIVE'; Block = $encoderProcessBlock; Pattern = $encoderProcessCall })) {
        $exactCalls = [regex]::Matches($call.Block, '(?is)' + $call.Pattern)
        $broadCalls = [regex]::Matches(
            $call.Block,
            '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership(?:Identity)?\s*\(')
        if ($exactCalls.Count -ne 1 -or $broadCalls.Count -ne 1) {
            throw "$blocker $($call.Name) call is not exact and unique."
        }
    }
    $ds402StartReservedCalls = [regex]::Matches(
        $ds402StartBlock, '(?is)' + $ds402StartCall)
    $ds402StartActiveCalls = [regex]::Matches(
        $ds402StartBlock, '(?is)' + $ds402StartActiveCall)
    $ds402StartBroadCalls = [regex]::Matches(
        $ds402StartBlock,
        '(?i)AxisOwnership\s*\.\s*ValidateAxisOwnership(?:Identity)?\s*\(')
    if ($ds402StartReservedCalls.Count -ne 1 -or
        $ds402StartActiveCalls.Count -ne 1 -or
        $ds402StartBroadCalls.Count -ne 2) {
        throw (
            "$blocker DS402 Start must contain one RESERVED identity check and " +
            'one exact ACTIVE Commit-response recovery check.')
    }

    $homeProcessCall = (
        'homeOwnerResult\s*:=\s*ValidateAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7D13\s*,\s*' +
        'Reference\s*:=\s*ZeroHomeState\[9\]\$UINT\s*,\s*' +
        'ExpectedAxisMask\s*:=\s*homeAxisMask\s*,\s*' +
        'OwnerKind\s*:=\s*LMC_OWNER_KIND_LMC_HOME\s*,\s*' +
        'ResourceKind\s*:=\s*LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\s*,\s*' +
        'AdmissionMode\s*:=\s*LMC_OWNER_ADMISSION_LIFECYCLE\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*homeSessionEpoch\s*,\s*' +
        'RequestSequence\s*:=\s*homeRequestSequence\s*,\s*' +
        'AdmissionToken\s*:=\s*homeAdmissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*homeOwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_ACTIVE\s*\)\s*;')
    $homeProcessMatches = [regex]::Matches(
        $homeProcessBlock,
        '(?is)' + $homeProcessCall)
    $homeProcessBroadCalls = [regex]::Matches(
        $homeProcessBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership\s*\(')
    if ($homeProcessMatches.Count -ne 1 -or $homeProcessBroadCalls.Count -ne 1) {
        throw "$blocker Home Process ACTIVE call is not exact and unique."
    }
    $homeIntegrity = [regex]::Match(
        $homeProcessBlock,
        ('(?is)homeIdentityValid\s*:=\s*' +
         '\(ZeroHomeState\[51\]\$UDINT\s*=\s*LMC_HOME_RECORD_MAGIC\).*?' +
         'homeAdmissionToken\s*<>\s*0.*?' +
         'homeOwnerGeneration\s*<>\s*0.*?' +
         'homeSessionEpoch\s*<>\s*0.*?' +
         'homeRequestSequence\s*<>\s*0.*?' +
         'homeAxisMask\s*<>\s*0'))
    $homeNormalCancel = [regex]::Match(
        $homeProcessBlock.Substring($homeProcessMatches[0].Index),
        '(?is)InputLatch\.CancelAxisZeroHome\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*\)\s*;')
    $homeNormalCopy = [regex]::Match(
        $homeProcessBlock.Substring($homeProcessMatches[0].Index),
        '(?is)InputLatch\.CopyAxisZeroHomeResult\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*,')
    $homePublish = [regex]::Match(
        $homeProcessBlock,
        'PublishAxisOwnership\s*\(')
    $homeFailureFence = [regex]::Match(
        $homeProcessBlock,
        ('(?is)' + $homeProcessCall + '\s*' +
         'if\s+homeOwnerResult\s*<>\s*0\s+then\s*' +
         'homeCancelRequired\s*:=\s*TRUE\s*;\s*' +
         'homeFlags\s*:=\s*homeFlags\s+or\s+' +
         'LMC_HOME_FLAG_CANCEL_REQUIRED\s*;.*?' +
         'ZeroHomeState\[39\]\s*:=\s*' +
         'LMC_HOME_ENGINE_CANCEL_DRAIN\s*;'))
    if (-not ($homeIntegrity.Success -and $homeNormalCancel.Success -and
            $homeNormalCopy.Success -and $homePublish.Success -and
            $homeFailureFence.Success) -or
        $homeIntegrity.Index -ge $homeProcessMatches[0].Index -or
        $homeProcessMatches[0].Index -ge $homePublish.Index) {
        throw (
            "$blocker Home normal ACTIVE validation must enter exact-token " +
            'cancel/drain before final owner publication.')
    }

    $encoderActiveCall = [regex]::Match(
        $encoderProcessBlock,
        '(?is)' + $encoderProcessCall)
    $encoderClaim = [regex]::Match(
        $encoderProcessBlock,
        'EncoderMaintenanceState\[189\]\^?\$UDINT\s*:=')
    $encoderTryStart = [regex]::Match(
        $encoderProcessBlock,
        '(?i)\.TryStartWrite\s*\(')
    Assert-Match $encoderProcessBlock (
        '(?is)' + $encoderProcessCall + '\s*' +
        'if\s+ownerResult\s*<>\s*0\s+then.*?' +
        'quarantine\s*:=\s*TRUE\s*;.*?' +
        'elsif\s+EncoderMaintenanceState\[189\]\^?\$UDINT\s*<>\s*0\s+then') (
        "$blocker Encoder ACTIVE failure does not dominate the one-shot claim.")
    if (-not ($encoderActiveCall.Success -and $encoderClaim.Success -and
            $encoderTryStart.Success) -or
        $encoderActiveCall.Index -ge $encoderClaim.Index -or
        $encoderClaim.Index -ge $encoderTryStart.Index) {
        throw "$blocker Encoder ACTIVE validation must precede claim and SDO dispatch."
    }

    $ds402StartRegion = [regex]::Match(
        $ds402ProcessBlock,
        ('(?is)if\s+startSdo\s+then(?<Body>.*?)end_if\s*;\s*' +
         'if\s+startSdo\s*&\s*\(failure\s*=\s*FALSE\)\s+then'))
    if (-not $ds402StartRegion.Success) {
        throw "$blocker DS402 common SDO start region is missing."
    }
    $ds402StartBody = $ds402StartRegion.Groups['Body'].Value
    $ds402ActiveCall = [regex]::Match(
        $ds402StartBody,
        '(?is)' + $ds402ProcessCall)
    $ds402FirstDispatch = [regex]::Match(
        $ds402StartBody,
        'Ds402HomeState\[126\]\s*=\s*0')
    $ds402Publish = [regex]::Match(
        $ds402StartBody,
        'PublishAxisOwnership\s*\(')
    $ds402TokenMutation = [regex]::Match(
        $ds402ProcessBlock,
        'Ds402HomeState\[99\]\s*:=')
    $ds402TryStart = [regex]::Match(
        $ds402ProcessBlock,
        '(?i)\.TryStart(?:Read|Write)\s*\(')
    Assert-Match $ds402StartBody (
        '(?is)' + $ds402ProcessCall + '\s*' +
        'if\s+ownerResult\s*<>\s*0\s+then.*?' +
        'failure\s*:=\s*TRUE\s*;.*?' +
        'elsif\s+Ds402HomeState\[126\]\s*=\s*0\s+then.*?' +
        'PublishAxisOwnership\s*\(') (
        "$blocker DS402 ACTIVE failure or first-dispatch publication fence drifted.")
    if (-not ($ds402ActiveCall.Success -and $ds402FirstDispatch.Success -and
            $ds402Publish.Success -and $ds402TokenMutation.Success -and
            $ds402TryStart.Success) -or
        $ds402ActiveCall.Index -ge $ds402FirstDispatch.Index -or
        $ds402FirstDispatch.Index -ge $ds402Publish.Index -or
        ($ds402StartRegion.Index + $ds402ActiveCall.Index) -ge
            $ds402TokenMutation.Index -or
        ($ds402StartRegion.Index + $ds402ActiveCall.Index) -ge
            $ds402TryStart.Index) {
        throw (
            "$blocker every DS402 SDO start must revalidate ACTIVE before " +
            'the one-time DISPATCH publication, token mutation, and executor call.')
    }

    $ds402ProcessExactCalls = [regex]::Matches(
        $ds402SteadyProcessBlock,
        '(?is)' + $ds402ProcessCall)
    $ds402ProcessBroadCalls = [regex]::Matches(
        $ds402SteadyProcessBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership\s*\(')
    if ($ds402ProcessExactCalls.Count -ne 3 -or
        $ds402ProcessBroadCalls.Count -ne 3) {
        throw (
            "$blocker DS402 Process must contain exactly three ACTIVE " +
            'validation fences: main dispatch and cleanup stages 94/96.')
    }
    foreach ($cleanup in @(
            @{ Stage = '94'; Next = '95'; Method = 'Write'; Index = '0x6060' },
            @{ Stage = '96'; Next = '97'; Method = 'Read'; Index = '0x6061' })) {
        $cleanupBlock = [regex]::Match(
            $ds402CleanupSearchBlock,
            ('(?ims)^\s*' + $cleanup.Stage + '\s*:\s*' +
             '(?<Body>.*?)(?=^\s*' + $cleanup.Next + '\s*:)')).Groups['Body'].Value
        if ([string]::IsNullOrWhiteSpace($cleanupBlock)) {
            throw "$blocker DS402 cleanup stage $($cleanup.Stage) is missing."
        }
        $cleanupActiveCall = [regex]::Match(
            $cleanupBlock,
            '(?is)' + $ds402ProcessCall)
        $cleanupTokenMutation = [regex]::Match(
            $cleanupBlock,
            'Ds402HomeState\[99\]\s*:=')
        $cleanupTryStart = [regex]::Match(
            $cleanupBlock,
            ('(?i)\.TryStart' + $cleanup.Method + '\s*\([^;]*?' +
             [regex]::Escape($cleanup.Index)))
        Assert-Match $cleanupBlock (
            '(?is)ownerResult\s*:=\s*-3\s*;.*?' +
            'IsClientConnected\s*\(\s*#AxisOwnership\s*\).*?' +
            $ds402ProcessCall + '\s*end_if\s*;\s*' +
            'if\s+ownerResult\s*<>\s*0\s+then.*?' +
            'Ds402HomeState\[108\]\s*:=.*?' +
            'Ds402HomeState\[92\]\s*:=\s*98\s*;\s*else') (
            "$blocker DS402 cleanup stage $($cleanup.Stage) does not " +
            'fail to stage 98 before dispatch.')
        if (-not ($cleanupActiveCall.Success -and
                $cleanupTokenMutation.Success -and $cleanupTryStart.Success) -or
            $cleanupActiveCall.Index -ge $cleanupTokenMutation.Index -or
            $cleanupTokenMutation.Index -ge $cleanupTryStart.Index) {
            throw (
                "$blocker DS402 cleanup stage $($cleanup.Stage) ACTIVE " +
                'validation must precede token mutation and executor dispatch.')
        }
    }

    $controlCallCount = [regex]::Matches(
        $controlScan,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership\s*\(').Count
    $diagnosticsCallCount = [regex]::Matches(
        $diagnosticsActivationScan,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership\s*\(').Count
    $controlIdentityCallCount = [regex]::Matches(
        $controlScan,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnershipIdentity\s*\(').Count
    $diagnosticsIdentityCallCount = [regex]::Matches(
        $diagnosticsScan,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnershipIdentity\s*\(').Count
    $expectedControlIdentityCallCount = 2
    if ($controlScan -match
        '(?i)FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnershipDs402Receipt') {
        $expectedControlIdentityCallCount = 3
        if ($controlScan -match
            '(?i)LMC_DS402_OWNER_STAGE_RESERVE_INTENT') {
            $expectedControlIdentityCallCount = 5
        }
    }
    if ($controlScan -match
        '(?i)FUNCTION\s+LMCControlCommandService::HandleAxisOwnershipSafetyRepeat\b') {
        $expectedControlIdentityCallCount += 4
    }
    if ($controlCallCount -ne 3 -or $diagnosticsCallCount -ne 5 -or
        $controlIdentityCallCount -ne $expectedControlIdentityCallCount -or
        $diagnosticsIdentityCallCount -ne 2) {
        throw (
            "$blocker ValidateAxisOwnership call inventory is control=" +
            "$controlCallCount diagnostics=$diagnosticsCallCount; identity=" +
            "$controlIdentityCallCount/$diagnosticsIdentityCallCount, " +
            ('expected plain 3/5 and identity ' +
             "$expectedControlIdentityCallCount/2."))
    }
}

function Assert-LasalDs402CommonOwnershipActivationMatrix {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$InputLatchText,
        [string]$SdkErrorCatalogText,
        [string]$SdkAdminModelsText,
        [string]$Owner
    )

    $tcpScan = Get-LasalScanText $TcpText
    $controlScan = Get-LasalScanText $ControlServiceText
    $diagnosticsScan = Get-LasalScanText $DiagnosticsText
    $inputLatchScan = Get-LasalScanText $InputLatchText
    $blocker = "$Owner common axis ownership activation blocker: atomic DS402 matrix"
    $gateSpecifications = [ordered]@{
        TcpOrdinary = @{
            Name = 'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED'
            Text = $tcpScan
        }
        ControlOrdinary = @{
            Name = 'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED'
            Text = $controlScan
        }
        DiagnosticsDs402 = @{
            Name = 'LMC_DIAG_DS402_HOME_ENABLED'
            Text = $diagnosticsScan
        }
        InputLatchSweep = @{
            Name = 'LMC_DS402_HOME_STARTUP_SWEEP_ENABLED'
            Text = $inputLatchScan
        }
    }
    $gateValues = @{}
    foreach ($gateEntry in $gateSpecifications.GetEnumerator()) {
        $gate = $gateEntry.Value
        $definitionPattern =
            '(?im)^[ \t]*#define[ \t]+' + [regex]::Escape($gate.Name) +
            '\b[^\r\n]*\r?$'
        $literalPattern =
            '(?m)^[ \t]*#define[ \t]+' + [regex]::Escape($gate.Name) +
            '[ \t]+(?<Value>TRUE|FALSE)[ \t]*\r?$'
        $definitions = [regex]::Matches($gate.Text, $definitionPattern)
        $literalDefinitions = [regex]::Matches($gate.Text, $literalPattern)
        if ($definitions.Count -ne 1 -or $literalDefinitions.Count -ne 1) {
            throw (
                "$blocker $($gate.Name) in $($gateEntry.Key) must be " +
                'one exact TRUE/FALSE literal definition.')
        }
        $gateValues[$gateEntry.Key] =
            $literalDefinitions[0].Groups['Value'].Value
    }

    $adminCapabilityBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+LMCControlCommandService::HandleAdminCommands.*?' +
         '0x7D00\s*:.*?(?=\s*0x7D10\s*:)')).Value
    if ([string]::IsNullOrWhiteSpace($adminCapabilityBlock)) {
        throw "$blocker Admin 0x7D00 capability block is missing."
    }
    $adminFeatureWrites = [regex]::Matches(
        $adminCapabilityBlock,
        '(?i)\(pResponseFrame\s*\+\s*24\)\^\$UDINT\s*:=\s*[^;]+;')
    $adminFeatureLiterals = [regex]::Matches(
        $adminCapabilityBlock,
        ('\(pResponseFrame\s*\+\s*24\)\^\$UDINT\s*:=\s*' +
         '(?<Value>0x000000(?:17|57))\s*;'))
    if ($adminFeatureWrites.Count -ne 1 -or
        $adminFeatureLiterals.Count -ne 1) {
        throw (
            "$blocker Admin FeatureBits must be exactly one literal " +
            '0x00000017 or 0x00000057 write.')
    }
    $adminFeatureLiteral =
        $adminFeatureLiterals[0].Groups['Value'].Value
    $allDormant =
        ($gateValues['TcpOrdinary'] -ceq 'FALSE') -and
        ($gateValues['ControlOrdinary'] -ceq 'FALSE') -and
        ($gateValues['DiagnosticsDs402'] -ceq 'FALSE') -and
        ($gateValues['InputLatchSweep'] -ceq 'FALSE') -and
        ($adminFeatureLiteral -ceq '0x00000017')
    $allActive =
        ($gateValues['TcpOrdinary'] -ceq 'TRUE') -and
        ($gateValues['ControlOrdinary'] -ceq 'TRUE') -and
        ($gateValues['DiagnosticsDs402'] -ceq 'TRUE') -and
        ($gateValues['InputLatchSweep'] -ceq 'TRUE') -and
        ($adminFeatureLiteral -ceq '0x00000057')
    if (-not ($allDormant -or $allActive)) {
        throw (
            "$blocker only all-dormant FALSE/FALSE/FALSE/FALSE + " +
            '0x00000017 or all-active TRUE/TRUE/TRUE/TRUE + ' +
            '0x00000057 is permitted.')
    }

    foreach ($inventory in @(
            @{ Name = 'TCP ordinary'; Text = $tcpScan;
                Symbol = 'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED'; Count = 2 },
            @{ Name = 'Control ordinary'; Text = $controlScan;
                Symbol = 'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED'; Count = 4 },
            @{ Name = 'Diagnostics DS402'; Text = $diagnosticsScan;
                Symbol = 'LMC_DIAG_DS402_HOME_ENABLED'; Count = 3 },
            @{ Name = 'InputLatch sweep'; Text = $inputLatchScan;
                Symbol = 'LMC_DS402_HOME_STARTUP_SWEEP_ENABLED'; Count = 2 })) {
        $useCount = [regex]::Matches(
            $inventory.Text,
            ('(?i)\b' + [regex]::Escape($inventory.Symbol) + '\b')).Count
        if ($useCount -ne $inventory.Count) {
            throw (
                "$blocker $($inventory.Name) gate-use inventory is " +
                "$useCount, expected $($inventory.Count).")
        }
    }

    $tcpMsgParserBlock = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::MsgPaser.*?END_FUNCTION').Value
    Assert-Match $tcpMsgParserBlock (
        '(?s)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*&\s*' +
        '\(\s*CommandID\s*<>\s*0x7D13\s*\)\s+then\s*case\s+CommandID\s+of') (
        "$blocker TCP classifier is not exactly ordinary-gate dominated.")

    $controlHandleBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::HandleRequest.*?END_FUNCTION')).Value
    Assert-Match $controlHandleBlock (
        '(?s)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s+then\s*' +
        'case\s+CommandId\s+of.*?ownershipManagedCommand\s*:=\s*TRUE') (
        "$blocker Control HandleRequest reachability guard is missing.")
    $controlReserveBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership.*?END_FUNCTION')).Value
    Assert-Match $controlReserveBlock (
        '(?s)if\s+\(?\s*ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?then.*?' +
        'if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*=\s*FALSE\s+then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$blocker Control Reserve reachability guard is missing.")
    $controlProcessBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ProcessAxisOwnership.*?END_FUNCTION')).Value
    Assert-Match $controlProcessBlock (
        '(?s)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*=\s*FALSE\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;.*?OwnershipObserverState\s*\[') (
        "$blocker Control Process reachability guard is missing.")

    $diagnosticsStartBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeStart.*?END_FUNCTION')).Value
    Assert-Match $diagnosticsStartBlock (
        '(?s)elsif\s*\(\s*LMC_DIAG_DS402_HOME_ENABLED\s*=\s*FALSE\s*\)\s*\|' +
        '.*?then\s*detailCode\s*:=\s*10\s*;') (
        "$blocker Diagnostics DS402 Start false fence is missing.")
    $diagnosticsProcessBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'ProcessAxisDs402Home.*?END_FUNCTION')).Value
    Assert-Match $diagnosticsProcessBlock (
        '(?s)elsif\s+stage\s*<\s*90\s+then\s*' +
        'if\s+LMC_DIAG_DS402_HOME_ENABLED\s*=\s*FALSE\s+then\s*' +
        'failure\s*:=\s*TRUE\s*;\s*failureNative\s*:=\s*10\s*;') (
        "$blocker Diagnostics DS402 Process false fence is missing.")

    $inputLatchRtBlock = [regex]::Match(
        $inputLatchScan,
        ('(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+' +
         'LMCEcatInputLatch::RtWork.*?END_FUNCTION')).Value
    Assert-Match $inputLatchRtBlock (
        '(?s)if\s+LMC_DS402_HOME_STARTUP_SWEEP_ENABLED\s*&\s*' +
        '\(SnapshotBytes\[464\]\$UDINT\s*=\s*' +
        'LMC_OWNER_STARTUP_SNAPSHOT_MAGIC\)\s*&\s*' +
        '\(homeStartupProofComplete\s*=\s*FALSE\).*?' +
        'homeStartupOwnerLedgerIdle\s*&\s*homeStartupAlignmentIdle\s+then.*?' +
        'homeStartupSweepActive\s*:=\s*TRUE\s*;') (
        "$blocker InputLatch startup sweep reachability guard is missing.")

    $sdkAxisDs402Assignments = [regex]::Matches(
        $SdkAdminModelsText,
        '(?im)^[ \t]*AxisDs402Home\s*=\s*[^,\r\n]+,?[ \t]*\r?$')
    $sdkAxisDs402Exact = [regex]::Matches(
        $SdkAdminModelsText,
        '(?m)^[ \t]*AxisDs402Home\s*=\s*1u\s*<<\s*6\s*,?[ \t]*\r?$')
    if ($sdkAxisDs402Assignments.Count -ne 1 -or
        $sdkAxisDs402Exact.Count -ne 1) {
        throw "$blocker C# AxisDs402Home must be exactly 1u << 6."
    }

    $sdkCatalogDefinitions = [regex]::Matches(
        $SdkErrorCatalogText,
        ('(?im)^[ \t]*public\s+const\s+uint\s+CurrentCatalogVersion' +
         '\b[^\r\n]*\r?$'))
    $sdkCatalogExact = [regex]::Matches(
        $SdkErrorCatalogText,
        ('(?m)^[ \t]*public\s+const\s+uint\s+CurrentCatalogVersion' +
         '\s*=\s*2\s*;[ \t]*\r?$'))
    $sdkConflictEntries = [regex]::Matches(
        $SdkErrorCatalogText,
        ('(?s)LMCErrorDomain\.AdapterCommand\s*,\s*-9\s*,\s*' +
         '"AxisOwnershipConflict"'))
    if ($sdkCatalogDefinitions.Count -ne 1 -or
        $sdkCatalogExact.Count -ne 1 -or
        $sdkConflictEntries.Count -ne 1) {
        throw (
            "$blocker SDK adapter catalog must independently remain v2 " +
            'with exact -9 AxisOwnershipConflict.')
    }

    $plcCatalogWrites = [regex]::Matches(
        $adminCapabilityBlock,
        '(?i)\(pResponseFrame\s*\+\s*44\)\^\$UINT\s*:=\s*[^;]+;')
    $plcCatalogExact = [regex]::Matches(
        $adminCapabilityBlock,
        '\(pResponseFrame\s*\+\s*44\)\^\$UINT\s*:=\s*5\s*;')
    if ($plcCatalogWrites.Count -ne 1 -or $plcCatalogExact.Count -ne 1) {
        throw (
            "$blocker PLC Admin ErrorCatalogVersion must independently " +
            'remain exact literal 5.')
    }

    if ($allActive) {
        return 'TRUE'
    }
    return 'FALSE'
}

function Assert-LasalOrdinaryAxisGroupOwnershipDormantContract {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$SdkErrorCatalogText,
        [ValidateSet('TRUE', 'FALSE')]
        [string]$ExpectedOrdinaryGate,
        [string]$Owner
    )

    $tcpScan = Get-LasalScanText $TcpText
    $controlScan = Get-LasalScanText $ControlServiceText
    $blocker = "$Owner common axis ownership activation blocker: ordinary ownership"
    $sharedConstants = [ordered]@{
        LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED = $ExpectedOrdinaryGate
        LMC_OWNER_PROFILE_AXIS_MASK = '0x0000000F'
        LMC_OWNER_ROBOT_AXIS_MASK = '0x000001FF'
        LMC_OWNER_KIND_DIRECT = '1'
        LMC_OWNER_KIND_GROUP = '2'
        LMC_OWNER_RESOURCE_AXIS = '1'
        LMC_OWNER_ADMISSION_ORDINARY = '1'
        LMC_OWNER_ADMISSION_SAFETY = '2'
        LMC_OWNER_ADMISSION_LIFECYCLE = '4'
        LMC_OWNER_ADAPTER_ERROR_CONFLICT = '-9'
    }
    foreach ($source in @(
            @{ Name = 'TCPMotionInterface'; Text = $tcpScan },
            @{ Name = 'LMCControlCommandService'; Text = $controlScan })) {
        foreach ($constant in $sharedConstants.GetEnumerator()) {
            $matches = [regex]::Matches(
                $source.Text,
                ('(?im)^\s*#define\s+' + [regex]::Escape($constant.Key) +
                 '\s+(?<Value>[^\s]+)\s*$'))
            if ($matches.Count -ne 1) {
                throw (
                    "$blocker $($source.Name) $($constant.Key) count is " +
                    "$($matches.Count), expected one.")
            }
            if ($matches[0].Groups['Value'].Value -cne $constant.Value) {
                throw (
                    "$blocker $($source.Name) $($constant.Key) is " +
                    "$($matches[0].Groups['Value'].Value), expected " +
                    "$($constant.Value).")
            }
        }
    }

    Assert-Match $controlScan (
        'OwnershipObserverState\s*:\s*ARRAY\s*\[\s*0\.\.107\s*\]\s*OF\s*DINT') (
        "$blocker exact nine-axis observer storage is missing.")
    Assert-Match $controlScan (
        '(?m)^\s*#define\s+LMC_OWNER_AXIS_COUNT\s+9\s*$') (
        "$blocker observer axis count is not exact nine.")
    Assert-Match $controlScan (
        '(?m)^\s*#define\s+LMC_OWNER_OBSERVER_STRIDE\s+12\s*$') (
        "$blocker observer stride is not exact twelve.")

    $expectedCommandIds = @(
        '2022', '2023', '2024', '2047', '2048', '2049', '204A',
        '204B', '2085', '209F', '20A0', '20A2', '20A4', '20E7',
        '7D22')
    $tcpClassifierBlock = [regex]::Match(
        $tcpScan,
        ('(?is)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*&\s*' +
         '\(\s*CommandID\s*<>\s*0x7D13\s*\)\s+then.*?' +
         '(?=\s*if\s+controlInvokeService\s*&\s*' +
         'IsClientConnected\s*\(\s*#ControlCommands\s*\)\s+then)')).Value
    if ([string]::IsNullOrWhiteSpace($tcpClassifierBlock)) {
        throw "$blocker TCP dormant classifier block is missing or not gate-dominated."
    }
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $tcpClassifierBlock `
        -Owner "$blocker TCP classifier" `
        -ExpectedCommandIds $expectedCommandIds

    $directKind = '(?:LMC_OWNER_KIND_DIRECT|1)'
    $groupKind = '(?:LMC_OWNER_KIND_GROUP|2)'
    $axisResource = '(?:LMC_OWNER_RESOURCE_AXIS|1)'
    $ordinaryAdmission = '(?:LMC_OWNER_ADMISSION_ORDINARY|1)'
    $safetyAdmission = '(?:LMC_OWNER_ADMISSION_SAFETY|2)'
    $lifecycleAdmission = '(?:LMC_OWNER_ADMISSION_LIFECYCLE|4)'
    $conflictError = '(?:LMC_OWNER_ADAPTER_ERROR_CONFLICT|-9)'
    $directKindAssignment = 'controlOwnerKind\s*:=\s*' + $directKind
    $groupKindAssignment = 'controlOwnerKind\s*:=\s*' + $groupKind
    $axisResourceAssignment = 'controlResourceKind\s*:=\s*' + $axisResource
    $ordinaryAdmissionAssignment =
        'controlAdmissionMode\s*:=\s*' + $ordinaryAdmission
    $safetyAdmissionAssignment =
        'controlAdmissionMode\s*:=\s*' + $safetyAdmission
    $lifecycleAdmissionAssignment =
        'controlAdmissionMode\s*:=\s*' + $lifecycleAdmission
    $tcpPowerArm = [regex]::Match(
        $tcpClassifierBlock,
        '(?ims)^\s*0x2023\s*:\s*(?<Body>.*?)(?=^\s*0x2024\s*:)').Groups['Body'].Value
    Assert-Match $tcpPowerArm (
        '(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*8.*?' +
        'AxisRef\s*>=\s*1.*?AxisRef\s*<=\s*9.*?' +
        'controlOwnerKind\s*:=\s*' + $directKind + '.*?' +
        'controlResourceKind\s*:=\s*' + $axisResource + '.*?' +
        'RequestBuf\[12\]\s*=\s*1\s+then.*?' +
        'controlAdmissionMode\s*:=\s*' + $ordinaryAdmission + '.*?' +
        'else.*?controlAdmissionMode\s*:=\s*' + $safetyAdmission) (
        "$blocker TCP classifier Axis PowerOn/PowerOff payload split drifted.")
    $tcpArmSpecifications = @(
        @{ Name = 'Axis Reset'; Start = '0x2024'; End = '0x2022';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1.*?AxisRef\s*>=\s*1.*?AxisRef\s*<=\s*9',
                $directKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Axis Stop'; Start = '0x2022'; End = '0x209F\s*,\s*0x20A0';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*16.*?AxisRef\s*>=\s*1.*?AxisRef\s*<=\s*9',
                $directKindAssignment, $axisResourceAssignment, $safetyAdmissionAssignment) },
        @{ Name = 'Axis position move'; Start = '0x209F\s*,\s*0x20A0'; End = '0x20A2';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*32.*?AxisRef\s*>=\s*1.*?AxisRef\s*<=\s*9',
                $directKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Axis velocity move'; Start = '0x20A2'; End = '0x2047';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*24.*?AxisRef\s*>=\s*1.*?AxisRef\s*<=\s*9',
                $directKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Group Enable'; Start = '0x2047'; End = '0x2048';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_PROFILE_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Group Disable'; Start = '0x2048'; End = '0x2049\s*,\s*0x204A';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_PROFILE_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $safetyAdmissionAssignment) },
        @{ Name = 'Group Reset/PowerOn'; Start = '0x2049\s*,\s*0x204A'; End = '0x204B';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_ROBOT_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Group PowerOff'; Start = '0x204B'; End = '0x2085';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_ROBOT_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $safetyAdmissionAssignment) },
        @{ Name = 'Group Stop'; Start = '0x2085'; End = '0x20A4';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*16.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_PROFILE_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $safetyAdmissionAssignment) },
        @{ Name = 'Group Move'; Start = '0x20A4'; End = '0x7D22';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*96.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_PROFILE_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Admin Group Move'; Start = '0x7D22'; End = '0x20E7';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*104.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_PROFILE_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $ordinaryAdmissionAssignment) },
        @{ Name = 'Group configuration'; Start = '0x20E7'; End = 'else';
            Required = @('(?s)controlClassifierValid\s*:=.*?Payload\s*=\s*1320.*?AxisRef\s*=\s*0x0100',
                'LMC_OWNER_ROBOT_AXIS_MASK', $groupKindAssignment, $axisResourceAssignment, $lifecycleAdmissionAssignment) })
    foreach ($specification in $tcpArmSpecifications) {
        $armBlock = [regex]::Match(
            $tcpClassifierBlock,
            ('(?ims)^\s*' + $specification.Start + '\s*:\s*' +
             '(?<Body>.*?)(?=^\s*' + $specification.End + '\s*(?::|$))')).Groups['Body'].Value
        if ([string]::IsNullOrWhiteSpace($armBlock)) {
            throw "$blocker TCP classifier $($specification.Name) arm is missing."
        }
        foreach ($requiredPattern in $specification.Required) {
            Assert-Match $armBlock $requiredPattern (
                "$blocker TCP classifier $($specification.Name) tuple drifted.")
        }
    }
    Assert-Match $tcpClassifierBlock (
        '(?s)case\s+AxisRef\s+of\s*' +
        '1\s*:\s*controlAxisMask\s*:=\s*0x00000001\s*;.*?' +
        '2\s*:\s*controlAxisMask\s*:=\s*0x00000002\s*;.*?' +
        '3\s*:\s*controlAxisMask\s*:=\s*0x00000004\s*;.*?' +
        '4\s*:\s*controlAxisMask\s*:=\s*0x00000008\s*;.*?' +
        '5\s*:\s*controlAxisMask\s*:=\s*0x00000010\s*;.*?' +
        '6\s*:\s*controlAxisMask\s*:=\s*0x00000020\s*;.*?' +
        '7\s*:\s*controlAxisMask\s*:=\s*0x00000040\s*;.*?' +
        '8\s*:\s*controlAxisMask\s*:=\s*0x00000080\s*;.*?' +
        '9\s*:\s*controlAxisMask\s*:=\s*0x00000100\s*;') (
        "$blocker TCP exact Axis1..9 bit mapping drifted.")
    $tcpReservationGuard = [regex]::Match(
        $tcpClassifierBlock,
        ('(?is)if\s+controlClassifierValid\s*&\s*' +
         '\(\s*controlAxisMask\s*<>\s*0\s*\)\s+then'))
    $tcpReservationCall = [regex]::Match(
        $tcpClassifierBlock,
        ('(?is)controlAdmissionResult\s*:=\s*' +
         'ControlCommands\.ReserveAxisOwnership\(\s*' +
         'CommandId:=CommandID\$UINT\s*,\s*Reference:=AxisRef\$UINT\s*,\s*' +
         'RequestedAxisMask:=controlAxisMask\s*,\s*' +
         'OwnerKind:=controlOwnerKind\s*,\s*' +
         'ResourceKind:=controlResourceKind\s*,\s*' +
         'AdmissionMode:=controlAdmissionMode\s*,\s*' +
         'CallerSessionEpoch:=ActiveRequest\.SessionEpoch\s*,\s*' +
         'RequestSequence:=ActiveRequest\.Sequence\s*,\s*' +
         'pIdentity:=\(#RequestBuf\[8\]\)\$\^void\s*,\s*' +
         'IdentitySize:=Payload\$UDINT\s*,\s*' +
         'pEffectiveAxisMask:=#controlEffectiveAxisMask\s*,\s*' +
         'pAdmissionToken:=#controlAdmissionToken\s*,\s*' +
         'pOwnerGeneration:=#controlOwnerGeneration\s*\)\s*;'))
    $tcpReservationFailure = [regex]::Match(
        $tcpClassifierBlock,
        ('(?is)if\s+controlAdmissionResult\s*<\s*0\s+then' +
         '(?<Body>.*?controlInvokeService\s*:=\s*FALSE\s*;)\s*end_if\s*;'))
    if (-not ($tcpReservationGuard.Success -and
            $tcpReservationCall.Success -and $tcpReservationFailure.Success) -or
        $tcpReservationGuard.Index -ge $tcpReservationCall.Index -or
        $tcpReservationCall.Index -ge $tcpReservationFailure.Index -or
        [regex]::Matches(
            $tcpClassifierBlock,
            '(?i)controlInvokeService\s*:=\s*FALSE\s*;').Count -ne 2) {
        throw (
            "$blocker TCP reservation/rejection is not classifier-guarded " +
            'or does not export the complete final-prewire tuple.')
    }
    Assert-Match $tcpClassifierBlock (
        '(?is)controlManagedCommand\s*:=\s*controlOwnerKind\s*<>\s*0\s*;.*?' +
        'if\s+controlManagedCommand\s*&\s*' +
        '\(controlClassifierValid\s*=\s*FALSE\)\s+then\s*' +
        'controlInvokeService\s*:=\s*FALSE\s*;\s*end_if\s*;.*?' +
        'if\s+controlClassifierValid\s*&\s*' +
        '\(controlAxisMask\s*<>\s*0\)\s+then') (
        "$blocker malformed managed commands are not rejected before Reserve/service dispatch.")
    $tcpReservationFailureBlock =
        $tcpReservationFailure.Groups['Body'].Value
    $configConflictBranch = [regex]::Match(
        $tcpReservationFailureBlock,
        ('(?ims)(?:if|elsif)\s+CommandID\s*=\s*0x20E7\s+then' +
         '(?<Body>.*?)(?=^\s*else\s*$)'))
    $configConflictTail = if ($configConflictBranch.Success) {
        $tcpReservationFailureBlock.Substring(
            $configConflictBranch.Index + $configConflictBranch.Length)
    }
    else {
        ''
    }
    $genericConflictBranch = [regex]::Match(
        $configConflictTail,
        ('(?ims)^\s*else\s*$' +
         '(?<Body>.*?)(?=^\s*end_if\s*;)'))
    if (-not ($configConflictBranch.Success -and
            $genericConflictBranch.Success) -or
        [regex]::Matches(
            $configConflictBranch.Groups['Body'].Value,
            'Sendbuf\[10\]\$INT\s*:=\s*' + $conflictError).Count -ne 1 -or
        $configConflictBranch.Groups['Body'].Value -match
            'Sendbuf\[14\]\$INT\s*:=' -or
        [regex]::Matches(
            $genericConflictBranch.Groups['Body'].Value,
            'Sendbuf\[14\]\$INT\s*:=\s*' + $conflictError).Count -ne 1 -or
        $genericConflictBranch.Groups['Body'].Value -match
            'Sendbuf\[10\]\$INT\s*:=') {
        throw "$blocker TCP conflict rejection branches changed wire shape."
    }

    $tcpMsgParserBlock = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::MsgPaser.*?END_FUNCTION').Value
    $tcpServiceDispatch = [regex]::Match(
        $tcpMsgParserBlock,
        ('(?is)if\s+controlInvokeService\s*&\s*' +
         'IsClientConnected\(#ControlCommands\)\s+then\s*' +
         'controlResponseSize\s*:=\s*ControlCommands\.HandleRequest\(\s*' +
         'CommandId:=CommandID\$UINT\s*,\s*Reference:=AxisRef\$UINT\s*,\s*' +
         'pRequestFrame:=\(#RequestBuf\[0\]\)\$\^USINT\s*,\s*' +
         'RequestFrameSize:=\(Payload\s*\+\s*8\)\$UDINT\s*,\s*' +
         'pResponseFrame:=\(#Sendbuf\[0\]\)\$\^USINT\s*,\s*' +
         'ResponseCapacity:=sizeof\(Sendbuf\)\s*,\s*' +
         'CallerSessionEpoch:=ActiveRequest\.SessionEpoch\s*,\s*' +
         'RequestSequence:=ActiveRequest\.Sequence\s*,\s*' +
         'AdmissionToken:=controlAdmissionToken\s*,\s*' +
         'OwnerGeneration:=controlOwnerGeneration\s*\)\s*;\s*end_if\s*;'))
    $tcpClassifierIndex = $tcpMsgParserBlock.IndexOf(
        $tcpClassifierBlock,
        [System.StringComparison]::Ordinal)
    if (-not $tcpServiceDispatch.Success -or
        $tcpClassifierIndex -lt 0 -or
        $tcpServiceDispatch.Index -le
            ($tcpClassifierIndex + $tcpReservationFailure.Index)) {
        throw (
            "$blocker TCP service dispatch does not preserve reservation " +
            'token/generation or bypasses the rejection fence.')
    }

    $reserveBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership.*?END_FUNCTION')).Value
    if ([string]::IsNullOrWhiteSpace($reserveBlock)) {
        throw "$blocker ReserveAxisOwnership implementation is missing."
    }
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $reserveBlock `
        -Owner "$blocker service reservation classifier" `
        -ExpectedCommandIds $expectedCommandIds
    Assert-Match $reserveBlock (
        '(?s)ResourceKind\s*=\s*LMC_OWNER_RESOURCE_AXIS.*?' +
        'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*=\s*FALSE\s+then\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN') (
        "$blocker direct/group reserve is not disabled by the dormant gate.")
    Assert-Match $reserveBlock (
        '(?s)case\s+Reference\s+of\s*' +
        '1\s*:\s*referenceAxisMask\s*:=\s*0x00000001\s*;.*?' +
        '2\s*:\s*referenceAxisMask\s*:=\s*0x00000002\s*;.*?' +
        '3\s*:\s*referenceAxisMask\s*:=\s*0x00000004\s*;.*?' +
        '4\s*:\s*referenceAxisMask\s*:=\s*0x00000008\s*;.*?' +
        '5\s*:\s*referenceAxisMask\s*:=\s*0x00000010\s*;.*?' +
        '6\s*:\s*referenceAxisMask\s*:=\s*0x00000020\s*;.*?' +
        '7\s*:\s*referenceAxisMask\s*:=\s*0x00000040\s*;.*?' +
        '8\s*:\s*referenceAxisMask\s*:=\s*0x00000080\s*;.*?' +
        '9\s*:\s*referenceAxisMask\s*:=\s*0x00000100\s*;') (
        "$blocker service exact Axis1..9 bit mapping drifted.")
    $serviceClassifierSpecifications = @(
        @{ Name = 'Axis Stop'; Start = '0x2022'; End = '0x2023';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_DIRECT',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY',
                'RequestedAxisMask\s*<>\s*referenceAxisMask') },
        @{ Name = 'Axis Power'; Start = '0x2023';
            End = '0x2024\s*,\s*0x209F\s*,\s*0x20A0\s*,\s*0x20A2';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_DIRECT',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_ORDINARY',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY',
                'RequestedAxisMask\s*<>\s*referenceAxisMask') },
        @{ Name = 'Axis ordinary mutation';
            Start = '0x2024\s*,\s*0x209F\s*,\s*0x20A0\s*,\s*0x20A2';
            End = '0x2047\s*,\s*0x20A4\s*,\s*0x7D22';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_DIRECT',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_ORDINARY',
                'RequestedAxisMask\s*<>\s*referenceAxisMask') },
        @{ Name = 'Profile ordinary mutation';
            Start = '0x2047\s*,\s*0x20A4\s*,\s*0x7D22';
            End = '0x2048\s*,\s*0x2085';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_ORDINARY',
                'RequestedAxisMask\s*<>\s*LMC_OWNER_PROFILE_AXIS_MASK',
                'Reference\s*<>\s*0x0100') },
        @{ Name = 'Profile safety mutation';
            Start = '0x2048\s*,\s*0x2085'; End = '0x2049\s*,\s*0x204A';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY',
                'RequestedAxisMask\s*<>\s*LMC_OWNER_PROFILE_AXIS_MASK',
                'Reference\s*<>\s*0x0100') },
        @{ Name = 'Robot ordinary mutation'; Start = '0x2049\s*,\s*0x204A';
            End = '0x204B';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_ORDINARY',
                'RequestedAxisMask\s*<>\s*LMC_OWNER_ROBOT_AXIS_MASK',
                'Reference\s*<>\s*0x0100') },
        @{ Name = 'Robot safety mutation'; Start = '0x204B'; End = '0x20E7';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_SAFETY',
                'RequestedAxisMask\s*<>\s*LMC_OWNER_ROBOT_AXIS_MASK',
                'Reference\s*<>\s*0x0100') },
        @{ Name = 'Robot lifecycle mutation'; Start = '0x20E7'; End = 'else';
            Required = @('OwnerKind\s*<>\s*LMC_OWNER_KIND_GROUP',
                'AdmissionMode\s*<>\s*LMC_OWNER_ADMISSION_LIFECYCLE',
                'RequestedAxisMask\s*<>\s*LMC_OWNER_ROBOT_AXIS_MASK',
                'Reference\s*<>\s*0x0100') })
    foreach ($specification in $serviceClassifierSpecifications) {
        $armBlock = [regex]::Match(
            $reserveBlock,
            ('(?ims)^\s*' + $specification.Start + '\s*:\s*' +
             '(?<Body>.*?)(?=^\s*' + $specification.End + '\s*(?::|$))')).Groups['Body'].Value
        if ([string]::IsNullOrWhiteSpace($armBlock)) {
            throw "$blocker service classifier $($specification.Name) arm is missing."
        }
        foreach ($requiredPattern in $specification.Required) {
            Assert-Match $armBlock $requiredPattern (
                "$blocker service classifier $($specification.Name) tuple drifted.")
        }
    }

    $handleRequestBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::HandleRequest.*?END_FUNCTION')).Value
    if ([string]::IsNullOrWhiteSpace($handleRequestBlock)) {
        throw "$blocker HandleRequest implementation is missing."
    }
    $finalPrewireMatch = [regex]::Match(
        $handleRequestBlock,
        ('(?is)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s+then\s*' +
         '(?<Body>.*?' +
         'ownershipArmed\s*:=\s*ownershipManagedCommand\s*&\s*\(\s*' +
         'ownershipRequestShapeValid\s*\|\s*' +
         '\(\s*AdmissionToken\s*<>\s*0\s*\)\s*\|\s*' +
         '\(\s*OwnerGeneration\s*<>\s*0\s*\)\s*\)\s*;.*?' +
         'if\s+ownershipManagedCommand\s*&\s*' +
         '\(ownershipRequestShapeValid\s*=\s*FALSE\)\s+then\s*' +
         'ownershipInvokeHandler\s*:=\s*FALSE\s*;\s*end_if\s*;)\s*' +
         'end_if\s*;\s*(?=if\s+ownershipArmed\s+then)'))
    if (-not $finalPrewireMatch.Success) {
        throw (
            "$blocker final-prewire arm must be gate-dominated and fail " +
            'closed for both untagged valid requests and tagged malformed requests.')
    }
    $finalPrewireBlock = $finalPrewireMatch.Groups['Body'].Value
    $managedClassifier = [regex]::Match(
        $finalPrewireBlock,
        ('(?is)^(?<Body>case\s+CommandId\s+of.*?' +
         'ownershipManagedCommand\s*:=\s*TRUE\s*;.*?' +
         'end_case\s*;)\s*(?=if\s+ownershipManagedCommand\s+then)'))
    if (-not $managedClassifier.Success) {
        throw "$blocker final-prewire managed-command classifier is missing."
    }
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $managedClassifier.Groups['Body'].Value `
        -Owner "$blocker final-prewire managed-command classifier" `
        -ExpectedCommandIds $expectedCommandIds
    $shapeClassifier = [regex]::Match(
        $finalPrewireBlock,
        ('(?is)if\s+ownershipManagedCommand\s+then\s*' +
         '(?<Body>case\s+CommandId\s+of.*?end_case\s*;)\s*end_if\s*;' +
         '\s*(?=ownershipArmed\s*:=)'))
    if (-not $shapeClassifier.Success) {
        throw "$blocker final-prewire request-shape classifier is missing."
    }
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $shapeClassifier.Groups['Body'].Value `
        -Owner "$blocker final-prewire request-shape classifier" `
        -ExpectedCommandIds $expectedCommandIds
    $shapeClassifierBlock = $shapeClassifier.Groups['Body'].Value
    $shapeSpecifications = @(
        @{ Name = 'Axis Power'; Start = '0x2023'; End = '0x2024';
            Size = '8'; Reference = 'Reference\s*>=\s*1.*?Reference\s*<=\s*9' },
        @{ Name = 'Axis Reset'; Start = '0x2024'; End = '0x2022';
            Size = '1'; Reference = 'Reference\s*>=\s*1.*?Reference\s*<=\s*9' },
        @{ Name = 'Axis Stop'; Start = '0x2022';
            End = '0x209F\s*,\s*0x20A0'; Size = '16';
            Reference = 'Reference\s*>=\s*1.*?Reference\s*<=\s*9' },
        @{ Name = 'Axis position move'; Start = '0x209F\s*,\s*0x20A0';
            End = '0x20A2'; Size = '32';
            Reference = 'Reference\s*>=\s*1.*?Reference\s*<=\s*9' },
        @{ Name = 'Axis velocity move'; Start = '0x20A2';
            End = '0x2047\s*,\s*0x2048\s*,\s*0x2049\s*,\s*0x204A\s*,\s*0x204B';
            Size = '24'; Reference = 'Reference\s*>=\s*1.*?Reference\s*<=\s*9' },
        @{ Name = 'Group one-byte control';
            Start = '0x2047\s*,\s*0x2048\s*,\s*0x2049\s*,\s*0x204A\s*,\s*0x204B';
            End = '0x2085'; Size = '1'; Reference = 'Reference\s*=\s*0x0100' },
        @{ Name = 'Group Stop'; Start = '0x2085'; End = '0x20A4';
            Size = '16'; Reference = 'Reference\s*=\s*0x0100' },
        @{ Name = 'Group Move'; Start = '0x20A4'; End = '0x7D22';
            Size = '96'; Reference = 'Reference\s*=\s*0x0100' },
        @{ Name = 'Admin Group Move'; Start = '0x7D22'; End = '0x20E7';
            Size = '104'; Reference = 'Reference\s*=\s*0x0100' },
        @{ Name = 'Group configuration'; Start = '0x20E7'; End = 'else';
            Size = '1320'; Reference = 'Reference\s*=\s*0x0100' })
    foreach ($specification in $shapeSpecifications) {
        $armBlock = [regex]::Match(
            $shapeClassifierBlock,
            ('(?ims)^\s*' + $specification.Start + '\s*:\s*' +
             '(?<Body>.*?)(?=^\s*' + $specification.End + '\s*(?::|$))')).Groups['Body'].Value
        if ([string]::IsNullOrWhiteSpace($armBlock)) {
            throw "$blocker final-prewire $($specification.Name) shape arm is missing."
        }
        $nestedShapeAssignment = [regex]::Match(
            $armBlock,
            ('(?is)if\s+ownershipPayloadSize\s*=\s*' +
             $specification.Size + '\s+then' +
             '(?:(?!end_if).)*?ownershipRequestShapeValid\s*:=' +
             '(?<Expression>.*?);'))
        $directShapeAssignment = [regex]::Match(
            $armBlock,
            ('(?is)ownershipRequestShapeValid\s*:=' +
             '(?<Expression>.*?ownershipPayloadSize\s*=\s*' +
             $specification.Size + '.*?);'))
        $shapeExpression = if ($nestedShapeAssignment.Success) {
            $nestedShapeAssignment.Groups['Expression'].Value
        }
        elseif ($directShapeAssignment.Success) {
            $directShapeAssignment.Groups['Expression'].Value
        }
        else {
            ''
        }
        if ([string]::IsNullOrWhiteSpace($shapeExpression) -or
            $shapeExpression -match '(?i)\bFALSE\b' -or
            $shapeExpression -notmatch ('(?s)' + $specification.Reference)) {
            throw (
                "$blocker final-prewire $($specification.Name) " +
                'payload/reference shape cannot arm a valid request.')
        }
    }
    $armAssignments = [regex]::Matches(
        $handleRequestBlock,
        '(?i)\bownershipArmed\s*:=' )
    if ($armAssignments.Count -ne 2 -or
        [regex]::Matches(
            $handleRequestBlock,
            '(?i)\bownershipManagedCommand\s*:=\s*TRUE\s*;').Count -ne 1) {
        throw "$blocker final-prewire arm has an alternate activation path."
    }
    $validateCallPattern = (
        'ownershipValidationResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId:=CommandId\s*,\s*Reference:=Reference\s*,\s*' +
        'ExpectedAxisMask:=ownershipAxisMask\s*,\s*' +
        'OwnerKind:=ownershipOwnerKind\s*,\s*' +
        'ResourceKind:=ownershipResourceKind\s*,\s*' +
        'AdmissionMode:=ownershipAdmissionMode\s*,\s*' +
        'CallerSessionEpoch:=CallerSessionEpoch\s*,\s*' +
        'RequestSequence:=RequestSequence\s*,\s*' +
        'AdmissionToken:=AdmissionToken\s*,\s*' +
        'OwnerGeneration:=OwnerGeneration\s*,\s*' +
        'RequiredPhase:=LMC_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity:=\(pRequestFrame\s*\+\s*8\)\$\^void\s*,\s*' +
        'IdentitySize:=ownershipPayloadSize\s*\)\s*;')
    $validateCalls = [regex]::Matches(
        $handleRequestBlock,
        '(?is)' + $validateCallPattern)
    $broadValidateCalls = [regex]::Matches(
        $handleRequestBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership(?:Identity)?\s*\(')
    if ($validateCalls.Count -ne 1 -or $broadValidateCalls.Count -ne 1) {
        throw "$blocker HandleRequest must perform one exact final-prewire validation."
    }
    $validationReject = [regex]::Match(
        $handleRequestBlock,
        ('(?is)if\s+ownershipValidationResult\s*<>\s*0\s+then.*?' +
         'ownershipInvokeHandler\s*:=\s*FALSE\s*;'))
    if (-not $validationReject.Success) {
        throw "$blocker validation failure does not suppress native handler dispatch."
    }
    $dispatchGate = [regex]::Match(
        $handleRequestBlock,
        '(?i)if\s+ownershipInvokeHandler\s+then')
    $axisHandlerCall = [regex]::Match(
        $handleRequestBlock,
        '(?i)ResponseSize\s*:=\s*HandleAxisCommands\s*\(')
    $groupHandlerCall = [regex]::Match(
        $handleRequestBlock,
        '(?i)ResponseSize\s*:=\s*HandleGroupCommands\s*\(')
    $adminHandlerCall = [regex]::Match(
        $handleRequestBlock,
        '(?i)ResponseSize\s*:=\s*HandleAdminCommands\s*\(')
    $commitCallPattern = (
        'ownershipCommitResult\s*:=\s*CommitAxisOwnership\(\s*' +
        'CommandId:=CommandId\s*,\s*Reference:=Reference\s*,\s*' +
        'ExpectedAxisMask:=ownershipAxisMask\s*,\s*' +
        'CallerSessionEpoch:=CallerSessionEpoch\s*,\s*' +
        'RequestSequence:=RequestSequence\s*,\s*' +
        'AdmissionToken:=AdmissionToken\s*,\s*' +
        'OwnerGeneration:=OwnerGeneration\s*\)\s*;')
    $commitCalls = [regex]::Matches(
        $handleRequestBlock,
        '(?is)' + $commitCallPattern)
    $broadCommitCalls = [regex]::Matches(
        $handleRequestBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?CommitAxisOwnership\s*\(')
    if ($commitCalls.Count -ne 1 -or $broadCommitCalls.Count -ne 1) {
        throw "$blocker HandleRequest must perform one exact accepted-response commit."
    }
    $acceptedCommit = [regex]::Match(
        $handleRequestBlock,
        '(?is)if\s+ownershipAccepted\s+then\s*' + $commitCallPattern)
    $acceptanceBlock = [regex]::Match(
        $handleRequestBlock,
        ('(?is)if\s+ownershipArmed\s*&\s*' +
         '\(\s*ownershipSafetyPumpRejected\s*=\s*FALSE\s*\)\s*&\s*' +
         '\(\s*ownershipValidationResult\s*=\s*0\s*\)\s+then' +
         '(?<Body>.*?)(?=if\s+ownershipAccepted\s+then)'))
    if (-not ($acceptedCommit.Success -and $acceptanceBlock.Success) -or
        [regex]::Matches(
            $handleRequestBlock,
            '(?i)\bownershipAccepted\s*:=').Count -ne 4 -or
        $handleRequestBlock -match
            '(?i)\bownershipAccepted\s*:=\s*TRUE\s*;' -or
        $acceptanceBlock.Groups['Body'].Value -match '(?i)\bTRUE\b') {
        throw (
            "$blocker accepted-response commit has an unconditional or " +
            'alternate acceptance path.')
    }
    $acceptanceBody = $acceptanceBlock.Groups['Body'].Value
    foreach ($acceptancePattern in @(
            ('(?s)if\s+CommandId\s*=\s*0x7D22\s+then.*?' +
             'ResponseSize\s*=\s*24.*?ResponseCapacity\s*>=\s*24.*?' +
             'ownershipAccepted\s*:=.*?' +
             '\(pResponseFrame\s*\+\s*12\)\^\$UINT\s*=\s*0.*?' +
             '\(pResponseFrame\s*\+\s*14\)\^\$INT\s*=\s*0.*?' +
             '\(pResponseFrame\s*\+\s*20\)\^\$UDINT\s*=\s*0'),
            ('(?s)elsif\s+CommandId\s*=\s*0x20E7\s+then.*?' +
             'ResponseSize\s*=\s*12.*?ResponseCapacity\s*>=\s*12.*?' +
             'ownershipAccepted\s*:=.*?' +
             '\(pResponseFrame\s*\+\s*8\)\^\$UINT\s*=\s*0.*?' +
             '\(pResponseFrame\s*\+\s*10\)\^\$INT\s*=\s*0'),
            ('(?s)else.*?ResponseSize\s*=\s*16.*?' +
             'ResponseCapacity\s*>=\s*16.*?' +
             'ownershipAccepted\s*:=.*?' +
             '\(pResponseFrame\s*\+\s*12\)\^\$UINT\s*=\s*0.*?' +
             '\(pResponseFrame\s*\+\s*14\)\^\$INT\s*=\s*0'))) {
        Assert-Match $acceptanceBody $acceptancePattern (
            "$blocker handler result can reach Commit without an exact accepted response.")
    }
    if (-not ($dispatchGate.Success -and $axisHandlerCall.Success -and
            $groupHandlerCall.Success -and $adminHandlerCall.Success)) {
        throw "$blocker ordinary native handler dispatch shape is incomplete."
    }
    $firstHandlerIndex = @(
        $axisHandlerCall.Index,
        $groupHandlerCall.Index,
        $adminHandlerCall.Index) | Measure-Object -Minimum |
        Select-Object -ExpandProperty Minimum
    if (-not (
            $validateCalls[0].Index -lt $validationReject.Index -and
            $validationReject.Index -lt $dispatchGate.Index -and
            $dispatchGate.Index -lt $firstHandlerIndex -and
            $firstHandlerIndex -lt $commitCalls[0].Index)) {
        throw (
            "$blocker expected Validate -> reject fence -> handler -> " +
            'accepted-response Commit ordering.')
    }

    $observerBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ProcessAxisOwnership.*?END_FUNCTION')).Value
    if ([string]::IsNullOrWhiteSpace($observerBlock)) {
        throw "$blocker ProcessAxisOwnership implementation is missing."
    }
    $observerGate = [regex]::Match(
        $observerBlock,
        ('(?is)if\s+LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED\s*=\s*FALSE\s+' +
         'then\s*RETURN\s*;\s*end_if\s*;'))
    $observerUse = [regex]::Match(
        $observerBlock,
        ('(?i)OwnershipObserverState\s*\[|' +
         'LMCAxis[1-9]\s*\.|LMCRobot\s*\.|' +
         'PublishAxisOwnership\s*\('))
    $observerPreGateBlock = if ($observerGate.Success) {
        $observerBlock.Substring(0, $observerGate.Index)
    }
    else {
        ''
    }
    $unexpectedPreGateOwnershipWrites = @(
        [regex]::Matches(
            $observerPreGateBlock,
            ('(?i)OwnershipState\[\s*(?<Target>[^\]]+?)\s*\]' +
             '(?:\$UDINT)?\s*:=')) |
            Where-Object {
                ($_.Groups['Target'].Value -replace '\s', '') -notin @(
                    '23', '24', 'recordBase+1')
            })
    if (-not $observerGate.Success -or -not $observerUse.Success -or
        $observerGate.Index -ge $observerUse.Index -or
        $unexpectedPreGateOwnershipWrites.Count -ne 0) {
        throw (
            "$blocker terminal observer is not dormant before its first " +
            'observer state, hardware read, or publish action.')
    }

    Assert-Match $SdkErrorCatalogText (
        '(?m)^\s*public\s+const\s+uint\s+CurrentCatalogVersion\s*=\s*2\s*;') (
        "$blocker SDK error catalog version must remain two.")
    Assert-Match $SdkErrorCatalogText (
        '(?s)public\s+const\s+string\s+AdapterSourceVersion\s*=\s*' +
        '"Elmo_Master TCPMotionInterface local errors v2"\s*;') (
        "$blocker SDK adapter source version must remain v2.")
    $adapterCatalogBlock = [regex]::Match(
        $SdkErrorCatalogText,
        ('(?is)CreateAdapterEntries\s*\(\s*\)\s*\{.*?' +
         '(?=\s*private\s+static.*?CreateAdminEntries\s*\()')).Value
    if ([string]::IsNullOrWhiteSpace($adapterCatalogBlock)) {
        throw "$blocker SDK adapter error catalog block is missing."
    }
    $adapterEntryIds = @(
        [regex]::Matches(
            $adapterCatalogBlock,
            ('(?is)\bAdd\s*\(\s*entries\s*,\s*' +
             'LMCErrorDomain\.AdapterCommand\s*,\s*' +
             '(?<Id>-[1-9])\s*,')) |
            ForEach-Object { $_.Groups['Id'].Value } |
            Sort-Object)
    $expectedAdapterEntryIds = @(
        '-1', '-2', '-3', '-4', '-5', '-6', '-7', '-8', '-9') | Sort-Object
    $adapterEntryDifference = @(
        Compare-Object $expectedAdapterEntryIds $adapterEntryIds)
    if ([regex]::Matches(
            $adapterCatalogBlock,
            '(?i)\bAdd\s*\(').Count -ne 9 -or
        $adapterEntryIds.Count -ne 9 -or
        $adapterEntryDifference.Count -ne 0) {
        throw (
            "$blocker SDK adapter catalog must expose exactly the paired " +
            '-9 through -1 entries.')
    }
    Assert-Match $adapterCatalogBlock (
        '(?s)LMCErrorDomain\.AdapterCommand\s*,\s*-9\s*,\s*' +
        '"AxisOwnershipConflict".*?AdapterSourceVersion\s*\)\s*;') (
        "$blocker paired adapter error -9 AxisOwnershipConflict is missing.")
    $adminCapabilityBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+LMCControlCommandService::HandleAdminCommands.*?' +
         '0x7D00\s*:.*?(?=\s*0x7D10\s*:)')).Value
    Assert-Match $adminCapabilityBlock (
        '\(pResponseFrame\s*\+\s*44\)\^\$UINT\s*:=\s*5\s*;') (
        "$blocker PLC advertised error catalog version must remain five.")
}

function Assert-LasalOrdinarySafetyRepeatContract {
    param(
        [string]$ControlServiceText,
        [string]$TcpText,
        [string]$Owner
    )

    $controlScan = Get-LasalScanText $ControlServiceText
    $tcpScan = Get-LasalScanText $TcpText
    $blocker = "$Owner common axis ownership activation blocker: ordinary safety repeat"

    $constantContracts = [ordered]@{
        LMC_OWNER_SAFETY_REPEAT_NOT_APPLICABLE = '-11'
        LMC_OWNER_OBSERVER_POWER_OFF_ESCALATED = '0x00000100'
        LMC_OWNER_OBSERVER_KNOWN_MASK = '0x000001FF'
    }
    foreach ($constant in $constantContracts.GetEnumerator()) {
        $matches = [regex]::Matches(
            $controlScan,
            ('(?im)^\s*#define\s+' + [regex]::Escape($constant.Key) +
             '\s+(?<Value>[^\s]+)\s*$'))
        if ($matches.Count -ne 1 -or
            $matches[0].Groups['Value'].Value -cne $constant.Value) {
            throw (
                "$blocker $($constant.Key) must be exactly " +
                "$($constant.Value), once.")
        }
    }

    $implementationSpecifications = @(
        @{ Name = 'HandleRequest'; Global = $true },
        @{ Name = 'HandleAxisOwnershipSafetyRepeat'; Global = $false },
        @{ Name = 'ReserveAxisOwnership'; Global = $true },
        @{ Name = 'ProcessAxisOwnership'; Global = $true })
    $blocks = [ordered]@{}
    foreach ($specification in $implementationSpecifications) {
        $scope = if ($specification.Global) { 'GLOBAL\s+' } else { '' }
        $pattern = (
            '(?is)FUNCTION\s+' + $scope +
            'LMCControlCommandService::' +
            [regex]::Escape($specification.Name) + '\b.*?END_FUNCTION')
        $matches = [regex]::Matches($ControlServiceText, $pattern)
        if ($matches.Count -ne 1) {
            throw (
                "$blocker $($specification.Name) implementation count is " +
                "$($matches.Count), expected one.")
        }
        $blocks[$specification.Name] = $matches[0].Value
    }
    $handle = Get-LasalScanText $blocks['HandleRequest']
    $helper = Get-LasalScanText $blocks['HandleAxisOwnershipSafetyRepeat']
    $reserve = Get-LasalScanText $blocks['ReserveAxisOwnership']
    $process = Get-LasalScanText $blocks['ProcessAxisOwnership']

    if ($ControlServiceText -match
        '(?i)FUNCTION\s+GLOBAL\s+LMCControlCommandService::HandleAxisOwnershipSafetyRepeat\b') {
        throw "$blocker repeat helper must remain private."
    }
    Assert-Match $helper (
        '(?is)\AFUNCTION\s+' +
        'LMCControlCommandService::HandleAxisOwnershipSafetyRepeat\s*' +
        'VAR_INPUT\s*' +
        'CommandId\s*:\s*UINT\s*;\s*' +
        'Reference\s*:\s*UINT\s*;\s*' +
        'pRequestFrame\s*:\s*\^USINT\s*;\s*' +
        'RequestFrameSize\s*:\s*UDINT\s*;\s*' +
        'pResponseFrame\s*:\s*\^USINT\s*;\s*' +
        'ResponseCapacity\s*:\s*UDINT\s*;\s*' +
        'CallerSessionEpoch\s*:\s*UDINT\s*;\s*' +
        'RequestSequence\s*:\s*UDINT\s*;\s*' +
        'AdmissionToken\s*:\s*UDINT\s*;\s*' +
        'OwnerGeneration\s*:\s*UDINT\s*;\s*END_VAR\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR') (
        "$blocker repeat helper implementation ABI drifted.")

    foreach ($entry in @(
            @{ Name = 'HandleRequest'; Block = $blocks['HandleRequest'] },
            @{ Name = 'HandleAxisOwnershipSafetyRepeat';
                Block = $blocks['HandleAxisOwnershipSafetyRepeat'] })) {
        $rawBytes = [Text.Encoding]::UTF8.GetByteCount($entry.Block)
        $lfBlock = $entry.Block.Replace("`r`n", "`n").Replace("`r", "`n")
        $lfBytes = [Text.Encoding]::UTF8.GetByteCount($lfBlock)
        $crlfBlock = $lfBlock.Replace("`n", "`r`n")
        $crlfBytes = [Text.Encoding]::UTF8.GetByteCount($crlfBlock)
        if ($rawBytes -gt 32768 -or
            $lfBytes -gt 32768 -or
            $crlfBytes -gt 32768) {
            throw (
                "$blocker $($entry.Name) is raw=$rawBytes, LF=$lfBytes, " +
                "CRLF=$crlfBytes UTF-8 bytes; all must be at most 32768.")
        }
    }

    $knownMaskPattern =
        '0xFFFFFFFF\s+xor\s+LMC_OWNER_OBSERVER_KNOWN_MASK'
    $knownMaskUses = [regex]::Matches($controlScan, $knownMaskPattern)
    if ($knownMaskUses.Count -ne 5 -or
        [regex]::Matches($helper, $knownMaskPattern).Count -ne 1 -or
        [regex]::Matches($reserve, $knownMaskPattern).Count -ne 1) {
        throw (
            "$blocker observer unknown-bit validation must use the expanded " +
            'known-mask expression at the three existing sites plus helper and Reserve.')
    }
    $oneByteIdentityGuards = [regex]::Matches(
        $controlScan,
        '(?i)\band\s+0xFFFFFF00\b')
    if ($oneByteIdentityGuards.Count -ne 1) {
        throw (
            "$blocker 0xFFFFFF00 must remain only the single one-byte identity guard; " +
            "found $($oneByteIdentityGuards.Count).")
    }
    foreach ($repeatBlock in @(
            @{ Name = 'helper'; Text = $helper },
            @{ Name = 'Reserve'; Text = $reserve })) {
        if ([regex]::Matches(
                $repeatBlock.Text,
                '(?i)\band\s+0xFFFE0000\b').Count -ne 1) {
            throw (
                "$blocker $($repeatBlock.Name) root known-flag mask must " +
                'remain exactly 0xFFFE0000.')
        }
    }

    $sentinelAssignments = [regex]::Matches(
        $helper,
        ('(?i)Result\s*:=\s*' +
         'LMC_OWNER_SAFETY_REPEAT_NOT_APPLICABLE\s*;'))
    if ($sentinelAssignments.Count -ne 2) {
        throw (
            "$blocker helper sentinel assignment inventory is " +
            "$($sentinelAssignments.Count), expected initial and exact-RESERVED only.")
    }
    Assert-Match $helper (
        '(?is)if\s+repeatFresh\s+then\s*' +
        'Result\s*:=\s*LMC_OWNER_SAFETY_REPEAT_NOT_APPLICABLE\s*;\s*' +
        'RETURN\s*;\s*end_if\s*;') (
        "$blocker exact first RESERVED dispatch must fall through via sentinel -11.")
    if ($helper -match
        '(?i)\b(?:Reserve|Commit|Rollback)AxisOwnership\s*\(') {
        throw "$blocker repeat helper must not reserve, commit, or roll back ownership."
    }
    if ([regex]::Matches(
            $helper,
            '(?i)\bValidateAxisOwnershipIdentity\s*\(').Count -ne 2 -or
        [regex]::Matches(
            $reserve,
            '(?i)\bValidateAxisOwnershipIdentity\s*\(').Count -ne 2) {
        throw "$blocker helper and Reserve must each expose two exact identity validation sites."
    }

    $helperPreemptionCopyPattern = (
        'preemptCopyResult\s*:=\s*CopyAxisOwnershipPreemption\(\s*' +
        'PreemptedAdmissionToken:=preemptedAdmissionToken\s*,\s*' +
        'PreemptedOwnerGeneration:=preemptedOwnerGeneration\s*,\s*' +
        'pDest:=#preemptProbe\[0\]\s*,\s*DestSize:=144\s*\)\s*;')
    if ([regex]::Matches(
            $helper,
            '(?i)\bCopyAxisOwnershipPreemption\s*\(').Count -ne 1) {
        throw "$blocker helper must expose exactly one full preemption-copy validation."
    }
    Assert-Match $helper (
        '(?is)if\s+repeatValid\s*&\s*repeatRootPresent\s+then.*?' +
        $helperPreemptionCopyPattern + '\s*' +
        'if\s+preemptCopyResult\s*<>\s*-4\s+then\s*' +
        'repeatValid\s*:=\s*FALSE\s*;\s*' +
        'repeatStructuralFailure\s*:=\s*TRUE\s*;') (
        "$blocker helper root-present path must complete the 144-byte copy validation.")

    $reservePreemptionCopyPattern = (
        'repeatPreemptCopyResult\s*:=\s*CopyAxisOwnershipPreemption\(\s*' +
        'PreemptedAdmissionToken:=repeatPreemptedToken\s*,\s*' +
        'PreemptedOwnerGeneration:=repeatPreemptedGeneration\s*,\s*' +
        'pDest:=#repeatPreemptProbe\[0\]\s*,\s*DestSize:=144\s*\)\s*;')
    $reservePreemptionCopies = [regex]::Matches(
        $reserve,
        '(?is)' + $reservePreemptionCopyPattern)
    if ($reservePreemptionCopies.Count -ne 2 -or
        [regex]::Matches(
            $reserve,
            '(?i)\bCopyAxisOwnershipPreemption\s*\(').Count -ne 2) {
        throw "$blocker Reserve must preserve both exact 144-byte preemption-copy validations."
    }
    $reserveRootFullCopy = [regex]::Match(
        $reserve,
        ('(?is)if\s+repeatRootPresent\s+then.*?' +
         $reservePreemptionCopyPattern + '\s*' +
         'if\s+repeatPreemptCopyResult\s*<>\s*-4\s+then\s*' +
         'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
         'Result\s*:=\s*-3\s*;\s*RETURN\s*;'))
    $reserveRootConflict = [regex]::Match(
        $reserve,
        ('(?is)if\s+repeatRootPresent\s*&\s*safetyPreemption\s*&\s*' +
         '\(repeatMode\s*=\s*0\)\s+then\s*' +
         'Result\s*:=\s*-2\s*;\s*RETURN\s*;'))
    if (-not $reserveRootFullCopy.Success -or
        -not $reserveRootConflict.Success -or
        $reserveRootFullCopy.Index -ge $reserveRootConflict.Index) {
        throw (
            "$blocker Reserve must validate a root-present full copy before " +
            'the no-repeatFound conflict return.')
    }

    $helperCallPattern = (
        'ResponseSize\s*:=\s*HandleAxisOwnershipSafetyRepeat\(\s*' +
        'CommandId:=CommandId\s*,\s*Reference:=Reference\s*,\s*' +
        'pRequestFrame:=pRequestFrame\s*,\s*' +
        'RequestFrameSize:=RequestFrameSize\s*,\s*' +
        'pResponseFrame:=pResponseFrame\s*,\s*' +
        'ResponseCapacity:=ResponseCapacity\s*,\s*' +
        'CallerSessionEpoch:=CallerSessionEpoch\s*,\s*' +
        'RequestSequence:=RequestSequence\s*,\s*' +
        'AdmissionToken:=AdmissionToken\s*,\s*' +
        'OwnerGeneration:=OwnerGeneration\s*\)\s*;')
    $helperCalls = [regex]::Matches($handle, '(?is)' + $helperCallPattern)
    $broadHelperCalls = [regex]::Matches(
        $handle,
        '(?i)\bHandleAxisOwnershipSafetyRepeat\s*\(')
    if ($helperCalls.Count -ne 1 -or $broadHelperCalls.Count -ne 1) {
        throw "$blocker HandleRequest must call the repeat helper exactly once with the exact tuple."
    }
    Assert-Match $handle (
        '(?is)' + $helperCallPattern + '\s*' +
        'if\s+ResponseSize\s*<>\s*' +
        'LMC_OWNER_SAFETY_REPEAT_NOT_APPLICABLE\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'OwnershipState\[25\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[26\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[27\]\s*:=\s*0\s*;') (
        "$blocker HandleRequest must return every handled repeat before fresh-path marker reset.")

    $coalescedBranch = [regex]::Match(
        $helper,
        ('(?is)if\s+repeatValid\s*&\s*repeatCoalesced\s+then' +
         '(?<Body>.*?)elsif\s+repeatValid\s*&\s*repeatEscalation\s+then'))
    if (-not $coalescedBranch.Success -or
        $coalescedBranch.Groups['Body'].Value -match (
            '(?i)Handle(?:Axis|Group)Commands\s*\(|' +
            '(?:OwnershipState|OwnershipObserverState)\s*\[[^\]]+\](?:\$UDINT)?\s*:=' ) -or
        $coalescedBranch.Groups['Body'].Value -notmatch
            '(?is)nativeResponseSize\s*:=\s*16\s*;.*?repeatResponseReady\s*:=\s*TRUE') {
        throw "$blocker coalesced ACK must be canonical and mutation/native free."
    }
    if ([regex]::Matches(
            $helper,
            '(?i)\bHandleAxisCommands\s*\(').Count -ne 1 -or
        [regex]::Matches(
            $helper,
            '(?i)\bHandleGroupCommands\s*\(').Count -ne 1) {
        throw "$blocker escalation helper must expose exactly one Axis and one Group dispatch site."
    }
    Assert-Match $helper (
        '(?is)elsif\s+repeatValid\s*&\s*repeatEscalation\s+then\s*' +
        'if\s+markerNone\s*&\s*' +
        '\(pResponseFrame\s*<>\s*NIL\)\s*&\s*' +
        '\(ResponseCapacity\s*>=\s*16\)\s+then\s*' +
        'if\s+CommandId\s*=\s*LMC_OWNER_COMMAND_AXIS_POWER\s+then\s*' +
        'nativeResponseSize\s*:=\s*HandleAxisCommands\(.*?' +
        'else\s*nativeResponseSize\s*:=\s*HandleGroupCommands\(') (
        "$blocker escalation dispatch is not marker-before and PowerOff-only.")
    if ([regex]::Matches(
            $helper,
            '(?i)\bmarkerNone\s*:=').Count -ne 2 -or
        [regex]::Matches(
            $helper,
            '(?i)\bmarkerExact\s*:=').Count -ne 1 -or
        [regex]::Matches(
            $helper,
            '(?i)\bmarkerAny\s*:=').Count -ne 1) {
        throw "$blocker native marker observation inventory drifted."
    }
    Assert-Match $helper (
        '(?is)markerExact\s*:=\s*' +
        '\(OwnershipState\[25\]\s*=\s*1\)\s*&\s*' +
        '\(OwnershipState\[26\]\s*=\s*TO_DINT\(CommandId\)\)\s*&\s*' +
        '\(OwnershipState\[27\]\s*=\s*TO_DINT\(Reference\)\).*?' +
        'repeatNativeAccepted\s*:=.*?markerExact\s*;.*?' +
        'repeatPrewireNack\s*:=.*?markerNone\s*;') (
        "$blocker exact marker must prove success while marker-none alone proves prewire NACK.")
    Assert-Match $helper (
        '(?is)if\s+repeatNativeAccepted\s+then.*?' +
        'OwnershipObserverState\[observerBase\s*\+\s*5\]\$UDINT\s*:=' +
        '.*?LMC_OWNER_OBSERVER_POWER_OFF_ESCALATED\s*;\s*' +
        'OwnershipObserverState\[observerBase\s*\+\s*6\]\s*:=\s*0\s*;\s*' +
        'OwnershipObserverState\[observerBase\s*\+\s*7\]\s*:=\s*0\s*;\s*' +
        'OwnershipObserverState\[observerBase\s*\+\s*8\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*9\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*10\]\s*:=\s*0\s*;') (
        "$blocker accepted escalation does not publish the bit before resetting all evidence slots.")
    Assert-Match $helper (
        '(?is)OwnershipState\[25\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[26\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[27\]\s*:=\s*0\s*;\s*' +
        'if\s+repeatResponseReady\s+then\s*' +
        'Result\s*:=\s*nativeResponseSize') (
        "$blocker handled repeat exits must consume dispatch-marker evidence exactly once.")

    Assert-Match $reserve (
        '(?is)repeatMode\s*:=\s*0\s*;.*?' +
        'repeatCandidate\s*:=\s*safetyPreemption\s*&\s*' +
        '\(\(CommandId\s*=\s*LMC_OWNER_COMMAND_AXIS_STOP\)\s*\|\s*' +
        '\(CommandId\s*=\s*LMC_OWNER_COMMAND_AXIS_POWER\)\s*\|\s*' +
        '\(CommandId\s*=\s*LMC_OWNER_COMMAND_GROUP_DISABLE\)\s*\|\s*' +
        '\(CommandId\s*=\s*LMC_OWNER_COMMAND_GROUP_STOP\)\s*\|\s*' +
        '\(CommandId\s*=\s*LMC_OWNER_COMMAND_GROUP_POWER_OFF\)\)') (
        "$blocker Reserve repeat candidate set drifted.")
    $repeatModeValues = @(
        [regex]::Matches(
            $reserve,
            '(?i)\brepeatMode\s*:=\s*(?<Value>-?[0-9]+)\s*;') |
            ForEach-Object { $_.Groups['Value'].Value } |
            Sort-Object -Unique)
    if (@(Compare-Object @('0', '1', '2') $repeatModeValues).Count -ne 0) {
        throw "$blocker Reserve repeatMode may only encode 0, 1, or 2."
    }
    $repeatReturn = [regex]::Match(
        $reserve,
        ('(?is)if\s+repeatMode\s*>\s*0\s+then' +
         '(?<Body>.*?)end_if\s*;\s*(?=nextToken\s*:=)'))
    if (-not $repeatReturn.Success) {
        throw "$blocker Reserve repeat return must precede fresh token allocation."
    }
    $repeatReturnBody = $repeatReturn.Groups['Body'].Value
    Assert-Match $repeatReturnBody (
        '(?is)pEffectiveAxisMask\^\s*:=\s*repeatAxisMask\s*;\s*' +
        'pAdmissionToken\^\s*:=\s*repeatAdmissionToken\s*;\s*' +
        'pOwnerGeneration\^\s*:=\s*repeatOwnerGeneration\s*;\s*' +
        'Result\s*:=\s*repeatMode\s*;\s*RETURN\s*;\s*\z') (
        "$blocker Reserve positive result does not return the immutable retained tuple immediately.")
    $repeatReturnWithoutCorruptionFlag = [regex]::Replace(
        $repeatReturnBody,
        '(?i)OwnershipState\[24\]\s*:=\s*1\s*;',
        '')
    if ($repeatReturnWithoutCorruptionFlag -match
            '(?i)(?:OwnershipState|OwnershipObserverState|' +
            'OwnershipIdentityState|OwnershipLeaseState|' +
            'OwnershipPreemptedState|OwnershipLeaseIdentityState|' +
            'OwnershipPreemptedIdentityState)\s*\[[^\]]+\]' +
            '(?:\$UDINT)?\s*:=' -or
        $repeatReturnBody -match
            '(?i)\b(?:HandleAxisCommands|HandleGroupCommands|' +
            'CommitAxisOwnership|RollbackAxisOwnership)\s*\(') {
        throw "$blocker Reserve positive return mutates retained evidence or dispatches native work."
    }
    if ($reserve -match
        '(?is)OwnershipObserverState\s*\[[^\]]+\](?:\$UDINT)?\s*:=' +
        '.*?LMC_OWNER_OBSERVER_POWER_OFF_ESCALATED') {
        throw "$blocker Reserve must not publish the escalation bit."
    }

    Assert-Match $process (
        '(?is)powerOffEscalated\s*:=\s*' +
        '\(OwnershipObserverState\[observerBase\s*\+\s*5\]\$UDINT\s+and\s+' +
        'LMC_OWNER_OBSERVER_POWER_OFF_ESCALATED\)\s*<>\s*0\s*;.*?' +
        '\(\(\(OwnershipObserverState\[selectedObserverBase\s*\+\s*5\]' +
        '\$UDINT\s+and\s+LMC_OWNER_OBSERVER_POWER_OFF_ESCALATED\)\s*<>\s*0\)\s*<>\s*' +
        'powerOffEscalated\).*?' +
        'if\s+powerOffEscalated\s*&\s*' +
        '\(commandId\s*<>\s*LMC_OWNER_COMMAND_AXIS_STOP\)\s*&\s*' +
        '\(commandId\s*<>\s*LMC_OWNER_COMMAND_GROUP_DISABLE\)\s*&\s*' +
        '\(commandId\s*<>\s*LMC_OWNER_COMMAND_GROUP_STOP\)\s+then') (
        "$blocker Process does not bind the escalation bit across the retained tuple.")
    Assert-Match $process (
        '(?is)referencePowerOff\s*:=\s*FALSE\s*;.*?' +
        'if\s+selectedAxisIndex\s*=\s*ownerReference\s+then\s*' +
        'referencePowerOff\s*:=\s*' +
        '\(\(axisStatusRaw\s+and\s+LMC_OWNER_AXIS_POWER_ON_MASK\)\s*=\s*0\)\s*&\s*' +
        '\(\(ds402StatusRaw\s+and\s+' +
        'LMC_OWNER_DS402_OPERATION_ENABLED_MASK\)\s*=\s*0\)') (
        "$blocker direct escalation lacks an exact reference-axis PowerOff predicate.")
    Assert-Match $process (
        '(?is)0x2022\s*:\s*if\s+powerOffEscalated\s+then\s*' +
        'terminalCandidate\s*:=\s*referencePowerOff\s*;\s*' +
        'else\s*terminalCandidate\s*:=\s*allStandstill\s*;') (
        "$blocker Axis Stop escalation does not use the stronger PowerOff predicate.")
    foreach ($commandId in @('0x2048', '0x2085')) {
        Assert-Match $process (
            '(?is)' + $commandId + '\s*:\s*' +
            'if\s+powerOffEscalated\s+then\s*' +
            'terminalCandidate\s*:=\s*' +
            '\(groupPowerState\s*=\s*0\)\s*&\s*allPowerOff\s*;\s*else') (
            "$blocker $commandId escalation does not use the stronger Group PowerOff predicate.")
    }

    $ordinaryRaw = [regex]::Match(
        $TcpText,
        ('(?is)//\s*LMC_OWNER_ORDINARY_CLASSIFIER_BEGIN\s*' +
         '(?<Body>.*?)//\s*LMC_OWNER_ORDINARY_CLASSIFIER_END'))
    if (-not $ordinaryRaw.Success) {
        throw "$blocker TCP ordinary classifier boundary markers are missing."
    }
    $ordinary = Get-LasalScanText $ordinaryRaw.Groups['Body'].Value
    $negativeAdmission = [regex]::Matches(
        $ordinary,
        '(?i)if\s+controlAdmissionResult\s*<\s*0\s+then')
    if ($negativeAdmission.Count -ne 1 -or
        $ordinary -match
            '(?i)if\s+controlAdmissionResult\s*<>\s*0\s+then' -or
        $ordinary -notmatch (
            '(?is)if\s+controlAdmissionResult\s*<\s*0\s+then.*?' +
            'controlInvokeService\s*:=\s*FALSE\s*;')) {
        throw "$blocker TCP must reject only negative Reserve results."
    }
    if ($ordinary -match
            '(?i)controlReserved\s*:=\s*TRUE\s*;' -or
        $ordinary -match
            '(?i)\b(?:Commit|Rollback)AxisOwnership\s*\(') {
        throw "$blocker ordinary TCP routing must not own Home reservation or terminal ownership."
    }
    $parser = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::MsgPaser\b.*?END_FUNCTION').Value
    if ([string]::IsNullOrWhiteSpace($parser)) {
        throw "$blocker TCP MsgPaser implementation is missing."
    }
    $homeReservationWrites = [regex]::Matches(
        $parser,
        '(?i)controlReserved\s*:=\s*TRUE\s*;')
    if ($homeReservationWrites.Count -ne 1) {
        throw (
            "$blocker controlReserved TRUE assignment count is " +
            "$($homeReservationWrites.Count), expected Home-only one.")
    }
    Assert-Match $parser (
        '(?is)if\s*\(CommandID\s*=\s*0x7D13\)\s*&\s*' +
        '\(Payload\s*=\s*56\)\s+then.*?' +
        'if\s+controlAdmissionResult\s*=\s*0\s+then\s*' +
        'controlReserved\s*:=\s*TRUE\s*;') (
        "$blocker controlReserved must remain exclusive to successful 0x7D13 reservation.")
}

function Assert-LasalTcpImplementationPrefix {
    param(
        [string]$TcpText,
        [ValidateSet('TRUE', 'FALSE')]
        [string]$ExpectedOrdinaryGate,
        [string]$Owner,
        [switch]$AllowMissingImplementationMarker
    )

    $blocker = "$Owner common axis ownership activation blocker:"
    $markerMatches = [regex]::Matches(
        $TcpText,
        '(?m)^[ \t]*//\{\{LSL_IMPLEMENTATION[ \t]*\r?$')
    if (($markerMatches.Count -eq 0) -and
        $AllowMissingImplementationMarker) {
        return
    }
    if ($markerMatches.Count -ne 1) {
        throw (
            "$blocker TCP implementation marker count is " +
            "$($markerMatches.Count), expected exactly one.")
    }

    $implementationStart =
        $markerMatches[0].Index + $markerMatches[0].Length
    $implementationScan = Get-LasalScanText(
        $TcpText.Substring($implementationStart))
    $expectedPrefixPattern = (
        '\A[ \t\r\n]*#define[ \t]+' +
        'LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED[ \t]+' +
        [regex]::Escape($ExpectedOrdinaryGate) +
        '[ \t]*(?:\r?\n|\z)')
    if ($implementationScan -notmatch $expectedPrefixPattern) {
        throw (
            "$blocker TCP implementation prefix first meaningful token must " +
            'be the exact #define LMC_AXIS_OWNERSHIP_ORDINARY_ENABLED ' +
            "$ExpectedOrdinaryGate line.")
    }
}

function Assert-LasalAxisOwnershipActivationGuard {
    param(
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$DiagnosticsText,
        [string]$InputLatchText,
        [string]$SdkErrorCatalogText,
        [string]$SdkAdminModelsText,
        [ValidateSet('TRUE', 'FALSE')]
        [string]$ExpectedTw20Gate = 'FALSE',
        [ValidateSet('TRUE', 'FALSE')]
        [string]$ExpectedTw19Gate = 'FALSE',
        [string]$Owner,
        [switch]$AllowLegacyTcpFinalizerFixture
    )

    $tcpScan = Get-LasalScanText $TcpText
    $controlScan = Get-LasalScanText $ControlServiceText
    $diagnosticsScan = Get-LasalScanText $DiagnosticsText
    $inputLatchScan = Get-LasalScanText $InputLatchText
    $combinedScan = ($tcpScan, $controlScan, $diagnosticsScan, $inputLatchScan) -join "`n"
    $blocker = "$Owner common axis ownership activation blocker:"

    foreach ($obsoletePattern in @(
            '(?i)\bLMC_ADMIN_AXIS_REFERENCE_ENABLED\b',
            '(?i)\bLMC_DIAG_D5_TW20_TEST_RESET_ENABLED\b',
            '(?i)\bProcessAxisReference\b',
            '(?i)\bReferenceState\b',
            '(?i)\bMoveReference\s*\(')) {
        if ($combinedScan -match $obsoletePattern) {
            throw "$blocker obsolete switch-search Home or generic-TW20 symbol remains."
        }
    }

    foreach ($methodName in @(
            'ReserveAxisOwnership',
            'ValidateAxisOwnership',
            'CommitAxisOwnership',
            'RollbackAxisOwnership',
            'PublishAxisOwnership',
            'ReconcileAxisOwnershipStartup',
            'NotifyAxisOwnershipSessionClosed',
            'ProcessAxisOwnership',
            'ProcessAxisZeroHome')) {
        $methodCount = [regex]::Matches(
            $controlScan,
            ('(?im)^\s*FUNCTION\s+(?:GLOBAL\s+)?' +
             'LMCControlCommandService::' +
             [regex]::Escape($methodName) + '\s*$')).Count
        if ($methodCount -ne 1) {
            throw "$blocker LMCControlCommandService.$methodName count is $methodCount, expected one."
        }
    }

    Assert-Match $controlScan 'OwnershipState\s*:\s*ARRAY\s*\[\s*0\.\.351\s*\]\s*OF\s*DINT' (
        "$blocker exact nine-axis ownership storage is missing.")
    Assert-Match $controlScan 'OwnershipStartupState\s*:\s*ARRAY\s*\[\s*0\.\.15\s*\]\s*OF\s*DINT' (
        "$blocker exact startup reconciliation storage is missing.")
    foreach ($ownershipStorage in @(
            @{ Name = 'OwnershipLeaseState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedState'; Upper = 323 },
            @{ Name = 'OwnershipIdentityState'; Upper = 431 },
            @{ Name = 'OwnershipLeaseIdentityState'; Upper = 323 },
            @{ Name = 'OwnershipPreemptedIdentityState'; Upper = 431 })) {
        Assert-Match $controlScan (
            [regex]::Escape($ownershipStorage.Name) +
            '\s*:\s*ARRAY\s*\[\s*0\.\.' +
            $ownershipStorage.Upper + '\s*\]\s*OF\s*DINT') (
            "$blocker $($ownershipStorage.Name) compact storage is missing or has the wrong bound.")
    }
    Assert-Match $controlScan 'ZeroHomeState\s*:\s*ARRAY\s*\[\s*0\.\.63\s*\]\s*OF\s*DINT' (
        "$blocker LMC_Home retained runtime state is missing.")
    Assert-Match $controlScan 'InputLatch\s*:\s*CltChCmd_LMCEcatInputLatch' (
        "$blocker LMC_Home InputLatch client is missing.")
    Assert-Match $controlScan (
        '(?s)InputLatch\.SubmitAxisZeroHome\(.*?' +
        'OperationToken:=.*?AxisReference:=.*?' +
        'ExpectedActualPosition:=') (
        "$blocker RT LMC_Home submit does not carry the exact stale-position guard.")
    Assert-LasalAxisOwnershipCommitAtomicity `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner
    $reserveOwnershipBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership.*?END_FUNCTION')).Value
    $validateOwnershipBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ValidateAxisOwnership.*?END_FUNCTION')).Value
    $rollbackOwnershipBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::RollbackAxisOwnership.*?END_FUNCTION')).Value
    $publishOwnershipBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership.*?END_FUNCTION')).Value
    Assert-LasalAxisOwnershipPhaseContract `
        -ControlServiceText $ControlServiceText `
        -DiagnosticsText $DiagnosticsText `
        -Owner $Owner
    Assert-Match $reserveOwnershipBlock (
        '(?s)' +
        'LMC_OWNER_STATE_IDLE.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*:=' +
        '\s*LMC_OWNER_STATE_RESERVED.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*11\s*\]\$UDINT' +
        '\s*:=\s*(?:RequestedAxisMask|effectiveAxisMask).*?END_FUNCTION') (
        "$blocker reserve is not a preflight-then-Reserved exact-mask write.")
    Assert-Match $validateOwnershipBlock (
        '(?s)' +
        'LMC_OWNER_STATE_RESERVED.*?AdmissionToken.*?OwnerGeneration.*?' +
        'CallerSessionEpoch.*?RequestSequence') (
        "$blocker reserved ownership validation body is incomplete.")
    Assert-Match $validateOwnershipBlock (
        '(?s)' +
        'elsif\s*\(OwnershipState\s*\[\s*recordBase\s*\+\s*4\s*\]' +
        '\$UDINT\s*=\s*AdmissionToken\)\s*\|.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*5\s*\]' +
        '\$UDINT\s*=\s*OwnerGeneration') (
        "$blocker validation does not reject a token/generation outside the exact mask.")
    $zeroHomeHandlerBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+LMCControlCommandService::' +
         'HandleAxisZeroHomeCommands.*?END_FUNCTION')).Value
    if ([string]::IsNullOrWhiteSpace($zeroHomeHandlerBlock)) {
        throw "$blocker zero-Home ownership handler is missing."
    }
    $adminHomeValidateCallPattern = (
        'adminHomeOwnerResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*0x7D13\s*,\s*' +
        'Reference\s*:=\s*Reference\s*,\s*' +
        'ExpectedAxisMask\s*:=\s*adminHomeAxisMask\s*,\s*' +
        'OwnerKind\s*:=\s*LMC_OWNER_KIND_LMC_HOME\s*,\s*' +
        'ResourceKind\s*:=\s*LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\s*,\s*' +
        'AdmissionMode\s*:=\s*LMC_OWNER_ADMISSION_LIFECYCLE\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*OwnershipState\[16\]\$UDINT\s*,\s*' +
        'RequestSequence\s*:=\s*OwnershipState\[17\]\$UDINT\s*,\s*' +
        'AdmissionToken\s*:=\s*OwnershipState\[18\]\$UDINT\s*,\s*' +
        'OwnerGeneration\s*:=\s*OwnershipState\[19\]\$UDINT\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*pRequest(?:\$\^void)?\s*,\s*' +
        'IdentitySize\s*:=\s*RequestSize\s*\)\s*;')
    $adminHomeCommitCallPattern = (
        'adminHomeOwnerResult\s*:=\s*CommitAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7D13\s*,\s*' +
        'Reference\s*:=\s*Reference\s*,\s*' +
        'ExpectedAxisMask\s*:=\s*adminHomeAxisMask\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*OwnershipState\[16\]\$UDINT\s*,\s*' +
        'RequestSequence\s*:=\s*OwnershipState\[17\]\$UDINT\s*,\s*' +
        'AdmissionToken\s*:=\s*OwnershipState\[18\]\$UDINT\s*,\s*' +
        'OwnerGeneration\s*:=\s*OwnershipState\[19\]\$UDINT\s*\)\s*;')
    $adminHomeValidateCalls = [regex]::Matches(
        $zeroHomeHandlerBlock,
        '(?is)' + $adminHomeValidateCallPattern)
    $adminHomeCommitCalls = [regex]::Matches(
        $zeroHomeHandlerBlock,
        '(?is)' + $adminHomeCommitCallPattern)
    $adminHomeBroadValidateCalls = [regex]::Matches(
        $zeroHomeHandlerBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?ValidateAxisOwnership(?:Identity)?\s*\(')
    $adminHomeBroadCommitCalls = [regex]::Matches(
        $zeroHomeHandlerBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?CommitAxisOwnership\s*\(')
    if ($adminHomeValidateCalls.Count -ne 1 -or
        $adminHomeCommitCalls.Count -ne 1 -or
        $adminHomeBroadValidateCalls.Count -ne 1 -or
        $adminHomeBroadCommitCalls.Count -ne 1) {
        throw (
            "$blocker zero-Home handler must call ValidateAxisOwnershipIdentity and " +
            'CommitAxisOwnership exactly once each, regardless of call syntax.')
    }
    $adminHomeValidateContract = [regex]::Match(
        $zeroHomeHandlerBlock,
        ('(?is)' + $adminHomeValidateCallPattern + '\s*' +
        'if\s+adminHomeOwnerResult\s*=\s*-3\s+then.*?' +
        'elsif\s+adminHomeOwnerResult\s*<>\s*0\s+then.*?else'))
    if (-not $adminHomeValidateContract.Success) {
        throw (
        "$blocker zero-Home validation does not bind the exact tuple or its result.")
    }
    $adminHomeCommitContract = [regex]::Match(
        $zeroHomeHandlerBlock,
        ('(?is)if\s+adminHomeSubmitResult\s*=\s*1\s+then\s*' +
        $adminHomeCommitCallPattern + '\s*' +
        'ZeroHomeState\[47\]\s*:=\s*adminHomeOwnerResult\s*;\s*' +
        'if\s+adminHomeOwnerResult\s*<>\s*0\s+then\s*' +
        'ZeroHomeState\[53\]\s*:=\s*1\s*;'))
    if (-not $adminHomeCommitContract.Success) {
        throw (
        "$blocker zero-Home commit does not bind the exact tuple or retain failure.")
    }
    if ($adminHomeValidateCalls[0].Index -ge $adminHomeCommitCalls[0].Index -or
        $adminHomeValidateContract.Index -ge $adminHomeCommitContract.Index) {
        throw (
            "$blocker zero-Home commit must be dominated by successful " +
            'validation and mailbox submission.')
    }
    Assert-Match $rollbackOwnershipBlock (
        '(?s)' +
        'expectedAxisMask\s*:=\s*' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*11\s*\]\$UDINT.*?' +
        'expectedAxisMask\s+and\s+axisBit.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*6\s*\]\$UDINT\s*<>' +
        '\s*CallerSessionEpoch.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*7\s*\]\$UDINT\s*<>' +
        '\s*RequestSequence.*?' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*11\s*\]\$UDINT\s*<>' +
        '\s*expectedAxisMask.*?' +
        'expectedResourceKind.*?resourceValid\s*:=\s*FALSE.*?' +
        'case\s+expectedResourceKind\s+of.*?' +
        'if\s+Reason\s*=\s*0\s+then') (
        "$blocker rollback does not validate one complete exact set before mutation.")
    Assert-Match $publishOwnershipBlock (
        '(?s)' +
        'OwnershipState\s*\[\s*recordBase\s*\+\s*11\s*\]\$UDINT\s*<>' +
        '\s*AxisMask.*?' +
        'elsif\s*\(OwnershipState\s*\[\s*recordBase\s*\+\s*4\s*\]' +
        '\$UDINT\s*=\s*AdmissionToken\)\s*\|.*?' +
        'resourceValid\s*:=\s*FALSE.*?' +
        'case\s+expectedResourceKind\s+of') (
        "$blocker publish permits a subset or mismatched stored axis mask.")
    $notifyBlock = [regex]::Match(
        $controlScan,
        ('(?is)FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::NotifyAxisOwnershipSessionClosed.*?' +
         'END_FUNCTION')).Value
    Assert-Match $notifyBlock (
        'OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*=' +
        '\s*LMC_OWNER_STATE_RESERVED') (
        "$blocker session close does not quarantine uncertain Reserved state.")
    if ($notifyBlock -match
            '(?i)OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*<>\s*LMC_OWNER_STATE_IDLE') {
        throw "$blocker session close incorrectly quarantines committed active owners."
    }
    Assert-Match $controlScan (
        '(?m)^\s*#define\s+LMC_OWNER_STARTUP_PROOF_REQUIRED\s+' +
        '0x0000000F\s*$') (
        "$blocker exact internal full-proof constant is missing.")
    Assert-LasalAxisOwnershipStartupReconcilerContract `
        -TcpText $TcpText `
        -ControlServiceText $ControlServiceText `
        -DiagnosticsText $DiagnosticsText `
        -InputLatchText $InputLatchText `
        -Owner $Owner
    $ordinaryActivationGate =
        Assert-LasalDs402CommonOwnershipActivationMatrix `
            -TcpText $TcpText `
            -ControlServiceText $ControlServiceText `
            -DiagnosticsText $DiagnosticsText `
            -InputLatchText $InputLatchText `
            -SdkErrorCatalogText $SdkErrorCatalogText `
            -SdkAdminModelsText $SdkAdminModelsText `
            -Owner $Owner
    Assert-LasalTcpImplementationPrefix `
        -TcpText $TcpText `
        -ExpectedOrdinaryGate $ordinaryActivationGate `
        -Owner $Owner `
        -AllowMissingImplementationMarker:$AllowLegacyTcpFinalizerFixture
    Assert-LasalOrdinaryAxisGroupOwnershipDormantContract `
        -TcpText $TcpText `
        -ControlServiceText $ControlServiceText `
        -SdkErrorCatalogText $SdkErrorCatalogText `
        -ExpectedOrdinaryGate $ordinaryActivationGate `
        -Owner $Owner
    Assert-Match $tcpScan (
        '(?s)ReserveAxisOwnership\(.*?' +
        'CallerSessionEpoch:=ActiveRequest\.SessionEpoch.*?' +
        'RequestSequence:=ActiveRequest\.Sequence.*?' +
        'pIdentity:=\(#RequestBuf\[8\]\)\$\^void.*?' +
        'IdentitySize:=Payload\$UDINT.*?' +
        'Sendbuf\[16\]\$UDINT\s*=\s*RequestBuf\[12\]\$UDINT.*?' +
        'controlExactFailure.*?' +
        'controlExactAccepted\s*=\s*FALSE') (
        "$blocker TCP Home admission lacks exact payload identity/correlation fencing.")
    if (-not $AllowLegacyTcpFinalizerFixture) {
        Assert-Match $tcpScan (
            '(?s)controlExactAccepted\s*=\s*FALSE.*?' +
            'Sendbuf\[20\]\$UDINT\s*:=\s*42') (
            "$blocker TCP malformed response adapter detail drifted.")
        if ($tcpScan -match
            ('(?i)(?<![A-Za-z0-9_])control(?:Rollback|Publish)Result' +
             '(?![A-Za-z0-9_])')) {
            throw (
                "$blocker TCP must not duplicate Control HandleRequest " +
                'rollback/publish authority.')
        }
    }

    foreach ($methodName in @(
            'HandleEncoderMaintenanceStart',
            'HandleEncoderMaintenanceOutcome',
            'HandleEncoderMaintenanceRetire',
            'ProcessEncoderMaintenance')) {
        Assert-Match $diagnosticsScan (
            '(?im)^\s*FUNCTION\s+(?:GLOBAL\s+)?' +
            'LMCDiagnosticsService::' +
            [regex]::Escape($methodName) + '\s*$') (
            "$blocker LMCDiagnosticsService.$methodName is missing.")
    }
    Assert-Match $diagnosticsScan 'AxisOwnership\s*:\s*CltChCmd_LMCControlCommandService' (
        "$blocker diagnostics-to-common-owner client is missing.")

    $gateSpecifications = @(
        @{ Name = 'LMC_ADMIN_AXIS_HOME_ENABLED'; Text = $controlScan; Required = 'TRUE' },
        @{ Name = 'LMC_DIAG_DS402_HOME_ENABLED'; Text = $diagnosticsScan; Required = $ordinaryActivationGate },
        @{ Name = 'LMC_DIAG_ENCODER_TW20_ENABLED'; Text = $diagnosticsScan; Required = $ExpectedTw20Gate },
        @{ Name = 'LMC_DIAG_ENCODER_TW19_ENABLED'; Text = $diagnosticsScan; Required = $ExpectedTw19Gate })
    $gateValues = @{}
    foreach ($gate in $gateSpecifications) {
        $matches = [regex]::Matches(
            $gate.Text,
            ('(?im)^\s*#define\s+' + [regex]::Escape($gate.Name) +
             '\s+(?<Value>TRUE|FALSE)\s*$'))
        if ($matches.Count -ne 1) {
            throw "$blocker gate $($gate.Name) must be defined exactly once."
        }
        if ($null -ne $gate.Required -and
            $matches[0].Groups['Value'].Value -cne $gate.Required) {
            throw "$blocker gate $($gate.Name) must remain $($gate.Required)."
        }
        $gateValues[$gate.Name] = $matches[0].Groups['Value'].Value
    }

    $adminCapabilityBlock = [regex]::Match(
        $controlScan,
        '(?ims)^\s*0x7D00\s*:\s*$.*?(?=^\s*0x7D10\s*:\s*$)').Value
    $adminFeatureMatch = [regex]::Match(
        $adminCapabilityBlock,
        '(?i)\(pResponseFrame\s*\+\s*24\)\^\$UDINT\s*:=\s*0x(?<Hex>[0-9A-F]+)\s*;')
    if (-not $adminFeatureMatch.Success) {
        throw "$blocker Admin capability mask must be one auditable literal."
    }
    $adminFeatureBits = [Convert]::ToUInt32(
        $adminFeatureMatch.Groups['Hex'].Value,
        16)
    $homeAdvertised = ($adminFeatureBits -band 0x00000010) -ne 0
    $ds402Advertised = ($adminFeatureBits -band 0x00000040) -ne 0
    if ($homeAdvertised -ne
            ($gateValues['LMC_ADMIN_AXIS_HOME_ENABLED'] -ceq 'TRUE')) {
        throw "$blocker Admin bit 4 does not match the LMC_Home gate."
    }
    if ($ds402Advertised -ne
            ($gateValues['LMC_DIAG_DS402_HOME_ENABLED'] -ceq 'TRUE')) {
        throw "$blocker Admin bit 6 does not match the DS402 Home gate."
    }
    $catalogMatch = [regex]::Match(
        $adminCapabilityBlock,
        '(?i)\(pResponseFrame\s*\+\s*44\)\^\$UINT\s*:=\s*(?<Value>[0-9]+)\s*;')
    if (-not $catalogMatch.Success) {
        throw "$blocker Admin ErrorCatalogVersion must be one auditable literal."
    }
    $catalogVersion = [Convert]::ToUInt32(
        $catalogMatch.Groups['Value'].Value,
        10)
    if ($homeAdvertised -and $catalogVersion -lt 5) {
        throw "$blocker Admin bit 4 requires ErrorCatalogVersion at least 5."
    }
    Assert-Match $diagnosticsScan (
        '(?is)LMC_DIAG_ENCODER_TW20_ENABLED\s*=\s*TRUE.*?0x00040000') (
        "$blocker Diagnostics bit 18 is not separated behind the TW20 gate.")
    Assert-Match $diagnosticsScan (
        '(?is)LMC_DIAG_ENCODER_TW19_ENABLED\s*=\s*TRUE.*?0x00080000') (
        "$blocker Diagnostics bit 19 is not separated behind the TW19 gate.")

    $genericPolicy = [regex]::Match(
        $diagnosticsScan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::GetSdoWritePolicyDetail.*?END_FUNCTION').Value
    if ([string]::IsNullOrWhiteSpace($genericPolicy)) {
        throw "$blocker generic SDO Write policy was not found."
    }
    if ($genericPolicy -match '(?i)0x3204|0x20FC|TW19|TW20') {
        throw "$blocker generic 0x7E50 policy contains a forbidden encoder-maintenance bypass."
    }
}

function Invoke-LasalAxisOwnershipActivationGuardSelfTest {
    $control = @'
#define LMC_ADMIN_AXIS_HOME_ENABLED TRUE
#define LMC_OWNER_STARTUP_PROOF_REQUIRED 0x0000000F
OwnershipState : ARRAY [0..351] OF DINT;
OwnershipLeaseState : ARRAY [0..323] OF DINT;
OwnershipPreemptedState : ARRAY [0..323] OF DINT;
OwnershipIdentityState : ARRAY [0..431] OF DINT;
OwnershipLeaseIdentityState : ARRAY [0..323] OF DINT;
OwnershipPreemptedIdentityState : ARRAY [0..431] OF DINT;
ZeroHomeState : ARRAY [0..63] OF DINT;
InputLatch : CltChCmd_LMCEcatInputLatch;
FUNCTION GLOBAL LMCControlCommandService::ReserveAxisOwnership
if OwnershipState[recordBase + 1] <> LMC_OWNER_STATE_IDLE then RETURN; end_if;
OwnershipState[recordBase + 1] := LMC_OWNER_STATE_RESERVED;
OwnershipState[recordBase + 11]$UDINT := RequestedAxisMask;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::ValidateAxisOwnership
if OwnershipState[recordBase + 1] <> LMC_OWNER_STATE_RESERVED then RETURN; end_if;
check := AdmissionToken + OwnerGeneration + CallerSessionEpoch + RequestSequence;
if selected then
    exact := TRUE;
elsif (OwnershipState[recordBase + 4]$UDINT = AdmissionToken) |
      (OwnershipState[recordBase + 5]$UDINT = OwnerGeneration) then
    RETURN;
end_if;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::CommitAxisOwnership
axisIndex := 1;
while axisIndex <= LMC_OWNER_AXIS_COUNT do
    if selected then
        ownerKind := OwnershipState[recordBase + 2]$UINT;
        exit;
    end_if;
    axisIndex += 1;
end_while;
Result := ValidateAxisOwnership(
    CommandId:=CommandId,
    Reference:=Reference,
    ExpectedAxisMask:=ExpectedAxisMask,
    OwnerKind:=ownerKind,
    ResourceKind:=resourceKind,
    AdmissionMode:=admissionMode,
    CallerSessionEpoch:=CallerSessionEpoch,
    RequestSequence:=RequestSequence,
    AdmissionToken:=AdmissionToken,
    OwnerGeneration:=OwnerGeneration);
if Result <> 0 then
    RETURN;
end_if;
axisIndex := 1;
while axisIndex <= LMC_OWNER_AXIS_COUNT do
    if selected then
        OwnershipState[recordBase + 1] := activeState;
    end_if;
    axisIndex += 1;
end_while;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::RollbackAxisOwnership
expectedAxisMask := OwnershipState[recordBase + 11]$UDINT;
if (expectedAxisMask and axisBit) <> 0 then
if (OwnershipState[recordBase + 6]$UDINT <> CallerSessionEpoch) |
       (OwnershipState[recordBase + 7]$UDINT <> RequestSequence) |
       (OwnershipState[recordBase + 11]$UDINT <> expectedAxisMask) then RETURN; end_if;
end_if;
expectedResourceKind := OwnershipState[recordBase + 13];
resourceValid := FALSE;
case expectedResourceKind of
1: resourceValid := TRUE;
else
end_case;
if Reason = 0 then clear := TRUE; end_if;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::PublishAxisOwnership
if OwnershipState[recordBase + 11]$UDINT <> AxisMask then RETURN; end_if;
if selected then
    expectedResourceKind := OwnershipState[recordBase + 13];
elsif (OwnershipState[recordBase + 4]$UDINT = AdmissionToken) |
      (OwnershipState[recordBase + 5]$UDINT = OwnerGeneration) then
    RETURN;
end_if;
resourceValid := FALSE;
case expectedResourceKind of
1: resourceValid := TRUE;
else
end_case;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::ReconcileAxisOwnershipStartup
if DiagnosticsDrainFlags = LMC_OWNER_STARTUP_PROOF_REQUIRED then
    ready := TRUE;
else
    OwnershipState[24] := 1;
end_if;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::NotifyAxisOwnershipSessionClosed
if OwnershipState[recordBase + 1] = LMC_OWNER_STATE_RESERVED then
    OwnershipState[recordBase + 1] := LMC_OWNER_STATE_QUARANTINED;
end_if;
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::ProcessAxisOwnership
END_FUNCTION
FUNCTION GLOBAL LMCControlCommandService::ProcessAxisZeroHome
homeAdmissionToken := ZeroHomeState[34]$UDINT;
homeOwnerGeneration := ZeroHomeState[35]$UDINT;
homeSessionEpoch := ZeroHomeState[36]$UDINT;
homeRequestSequence := ZeroHomeState[37]$UDINT;
homeAxisMask := ZeroHomeState[38]$UDINT;
if ZeroHomeState[51]$UDINT <> LMC_HOME_RECORD_MAGIC then RETURN; end_if;
homeOwnerResult := ValidateAxisOwnership(
    CommandId:=0x7D13,
    Reference:=ZeroHomeState[9]$UINT,
    ExpectedAxisMask:=homeAxisMask,
    OwnerKind:=LMC_OWNER_KIND_LMC_HOME,
    ResourceKind:=LMC_OWNER_RESOURCE_LMC_HOME_ENGINE,
    AdmissionMode:=LMC_OWNER_ADMISSION_LIFECYCLE,
    CallerSessionEpoch:=homeSessionEpoch,
    RequestSequence:=homeRequestSequence,
    AdmissionToken:=homeAdmissionToken,
    OwnerGeneration:=homeOwnerGeneration,
    RequiredPhase:=LMC_OWNER_PHASE_ACTIVE);
if homeOwnerResult <> 0 then
    homeCancelRequired := TRUE;
    homeFlags := homeFlags or LMC_HOME_FLAG_CANCEL_REQUIRED;
    ZeroHomeState[39] := LMC_HOME_ENGINE_CANCEL_DRAIN;
end_if;
homeCancelResult := InputLatch.CancelAxisZeroHome(
    OperationToken:=homeAdmissionToken);
homeCopyResult := InputLatch.CopyAxisZeroHomeResult(
    OperationToken:=homeAdmissionToken,
    pDest:=pDest,
    DestSize:=128);
homePublishResult := PublishAxisOwnership(
    AxisMask:=homeAxisMask,
    AdmissionToken:=homeAdmissionToken,
    OwnerGeneration:=homeOwnerGeneration);
END_FUNCTION
FUNCTION LMCControlCommandService::HandleAxisZeroHomeCommands
adminHomeOwnerResult := ValidateAxisOwnership(
    CommandId:=0x7D13,
    Reference:=Reference,
    ExpectedAxisMask:=adminHomeAxisMask,
    OwnerKind:=LMC_OWNER_KIND_LMC_HOME,
    ResourceKind:=LMC_OWNER_RESOURCE_LMC_HOME_ENGINE,
    AdmissionMode:=LMC_OWNER_ADMISSION_LIFECYCLE,
    CallerSessionEpoch:=OwnershipState[16]$UDINT,
    RequestSequence:=OwnershipState[17]$UDINT,
    AdmissionToken:=OwnershipState[18]$UDINT,
    OwnerGeneration:=OwnershipState[19]$UDINT);
if adminHomeOwnerResult = -3 then
    detailCode := 42;
elsif adminHomeOwnerResult <> 0 then
    detailCode := 41;
else
    adminHomeSubmitResult := 1;
    if adminHomeSubmitResult = 1 then
    adminHomeOwnerResult := CommitAxisOwnership(
        CommandId:=0x7D13,
        Reference:=Reference,
        ExpectedAxisMask:=adminHomeAxisMask,
        CallerSessionEpoch:=OwnershipState[16]$UDINT,
        RequestSequence:=OwnershipState[17]$UDINT,
        AdmissionToken:=OwnershipState[18]$UDINT,
        OwnerGeneration:=OwnershipState[19]$UDINT);
    ZeroHomeState[47] := adminHomeOwnerResult;
    if adminHomeOwnerResult <> 0 then
        ZeroHomeState[53] := 1;
    end_if;
    end_if;
end_if;
END_FUNCTION
FUNCTION LMCControlCommandService::HandleAdminCommands
case CommandId of
0x7D00:
(pResponseFrame + 24)^$UDINT := 0x00000057;
(pResponseFrame + 44)^$UINT := 5;
0x7D10:
end_case;
END_FUNCTION
'@
