FUNCTION LMCDiagnosticsService::Capabilities
if LMC_DIAG_DS402_HOME_ENABLED = TRUE then bits := bits or 0x00000040; end_if;
if LMC_DIAG_ENCODER_TW20_ENABLED = TRUE then bits := bits or 0x00040000; end_if;
