        -DiagnosticsText $activeDiagnostics `
        -InputLatchText $activeInputLatch `
        -SdkErrorCatalogText $errorCatalog `
        -SdkAdminModelsText $adminModels `
        -AllowLegacyTcpFinalizerFixture `
        -Owner 'ownership active-endpoint self-test'
    $adminHomeValidateFixtureCall = [regex]::Match(
        $control,
        ('(?is)adminHomeOwnerResult\s*:=\s*ValidateAxisOwnershipIdentity\(.*?' +
         'OwnerGeneration:=OwnershipState\[19\]\$UDINT,\s*' +
         'RequiredPhase:=LMC_OWNER_PHASE_RESERVED,\s*' +
         'pIdentity:=pRequest\$\^void,\s*IdentitySize:=RequestSize\);'))
    $adminHomeCommitFixtureCall = [regex]::Match(
        $control,
        ('(?is)adminHomeOwnerResult\s*:=\s*CommitAxisOwnership\(.*?' +
         'OwnerGeneration:=OwnershipState\[19\]\$UDINT\);'))
    if (-not $adminHomeValidateFixtureCall.Success -or
        -not $adminHomeCommitFixtureCall.Success) {
        throw 'Common axis ownership self-test cannot isolate Home owner calls.'
    }
    $adminHomeDuplicateValidateControl = $control.Insert(
        $adminHomeValidateFixtureCall.Index + $adminHomeValidateFixtureCall.Length,
        [Environment]::NewLine + $adminHomeValidateFixtureCall.Value)
    $adminHomeDuplicateCommitControl = $control.Insert(
        $adminHomeCommitFixtureCall.Index + $adminHomeCommitFixtureCall.Length,
        [Environment]::NewLine + $adminHomeCommitFixtureCall.Value)
    $adminHomeCommitBeforeValidateControl = $control.Remove(
        $adminHomeCommitFixtureCall.Index,
        $adminHomeCommitFixtureCall.Length)
    $adminHomeCommitBeforeValidateControl =
        $adminHomeCommitBeforeValidateControl.Insert(
            $adminHomeValidateFixtureCall.Index,
            $adminHomeCommitFixtureCall.Value + [Environment]::NewLine)
    $adminHomeCommitResultOverwriteControl = $control.Insert(
        $adminHomeCommitFixtureCall.Index + $adminHomeCommitFixtureCall.Length,
        [Environment]::NewLine + '    adminHomeOwnerResult := 0;')
    $adminHomeEquivalentValidateCall =
        $adminHomeValidateFixtureCall.Value.Replace(
            'ExpectedAxisMask:=adminHomeAxisMask,',
            'ExpectedAxisMask:=TO_UDINT(adminHomeAxisMask),')
    $adminHomeEquivalentCommitCall =
        $adminHomeCommitFixtureCall.Value.Replace(
            'ExpectedAxisMask:=adminHomeAxisMask,',
            'ExpectedAxisMask:=TO_UDINT(adminHomeAxisMask),')
    if ($adminHomeEquivalentValidateCall -ceq
            $adminHomeValidateFixtureCall.Value -or
        $adminHomeEquivalentCommitCall -ceq
            $adminHomeCommitFixtureCall.Value) {
        throw 'Common axis ownership equivalent-call fixtures did not mutate.'
    }
    $adminHomeEquivalentValidateDuplicateControl = $control.Insert(
        $adminHomeValidateFixtureCall.Index,
        $adminHomeEquivalentValidateCall + [Environment]::NewLine)
    $adminHomeEquivalentCommitBeforeValidateControl = $control.Insert(
        $adminHomeValidateFixtureCall.Index,
        $adminHomeEquivalentCommitCall + [Environment]::NewLine)
    $negativeFixtures = @($baselineFixture.NegativeFixtures) + @(
        @{
            Name = 'TcpImplementationPrefixStrayU'
            ExpectedMessage = 'implementation prefix first meaningful token'
            Control = $control
            Diagnostics = $diagnostics
            Tcp = $tcp.Replace(
                '//{{LSL_IMPLEMENTATION',
                ('//{{LSL_IMPLEMENTATION' + [Environment]::NewLine + 'U'))
        },
        @{
            Name = 'TcpImplementationPrefixStrayUdint'
            ExpectedMessage = 'implementation prefix first meaningful token'
            Control = $control
            Diagnostics = $diagnostics
            Tcp = $tcp.Replace(
                '//{{LSL_IMPLEMENTATION',
                ('//{{LSL_IMPLEMENTATION' + [Environment]::NewLine + 'UDINT'))
        },
        @{ Control = $control + "`nLMCAxis1.MoveReference();"; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace('ExpectedActualPosition:=expected', 'ExpectedPosition:=expected'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = ([regex]::new(
            ('(?is)(end_while;\s*)' +
             '(Result\s*:=\s*ValidateAxisOwnership\(\s*' +
             'CommandId:=CommandId,.*?' +
             'OwnerGeneration:=OwnerGeneration,\s*' +
             'RequiredPhase:=LMC_OWNER_PHASE_RESERVED\);\s*' +
             'if\s+Result\s*<>\s*0\s+then\s*RETURN;\s*end_if;)'))).Replace(
                $control,
                '$2$1',
                1); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace('OwnershipState[recordBase + 11]$UDINT <> AxisMask', 'FALSE'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = ([regex]::new(
            ('(?is)elsif\s*\(OwnershipState\[recordBase\s*\+\s*4\]' +
             '\$UDINT\s*=\s*AdmissionToken\)\s*\|\s*' +
             '\(OwnershipState\[recordBase\s*\+\s*5\]\$UDINT\s*=\s*' +
             'OwnerGeneration\)\s*then'))).Replace(
                $control,
                'elsif FALSE then',
                1); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace('OwnershipState[recordBase + 11]$UDINT <> expectedAxisMask', 'FALSE'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace('OwnershipState[recordBase + 1] = LMC_OWNER_STATE_RESERVED', 'OwnershipState[recordBase + 1] <> LMC_OWNER_STATE_IDLE'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace('0x0000000F', '0x00000001'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control; Diagnostics = $diagnostics; Tcp = $tcp.Replace('(#RequestBuf[8])$^void', '(#RequestBuf[16])$^void') },
        @{ Control = $control; Diagnostics = $diagnostics; Tcp = $tcp.Replace('RequestBuf[12]$UDINT', '0') },
        @{ Control = $control.Replace(
            'ExpectedAxisMask:=adminHomeAxisMask,',
            'ExpectedAxisMask:=0,'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = ([regex]::new(
            ('(?is)(OwnerGeneration:=OwnershipState\[19\]\$UDINT,\s*' +
             'RequiredPhase:=LMC_OWNER_PHASE_RESERVED,\s*' +
             'pIdentity:=pRequest\$\^void,\s*' +
             'IdentitySize:=RequestSize\);\s*)' +
             '(if\s+adminHomeOwnerResult\s*=\s*-3\s+then)'))).Replace(
                $control,
                '${1}adminHomeOwnerResult := 0;${2}',
                1); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeDuplicateValidateControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeDuplicateCommitControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeCommitBeforeValidateControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeCommitResultOverwriteControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeEquivalentValidateDuplicateControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $adminHomeEquivalentCommitBeforeValidateControl; Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control.Replace(
            'if adminHomeSubmitResult = 1 then',
            'if TRUE then'); Diagnostics = $diagnostics; Tcp = $tcp },
        @{ Control = $control; Diagnostics = $diagnostics; Tcp = $tcp.Replace(
            'RequestSequence:=ActiveRequest.Sequence,',
            'RequestSequence:=0,') },
        @{ Control = $control; Diagnostics = $diagnostics.Replace('#define LMC_DIAG_ENCODER_TW20_ENABLED FALSE', '#define LMC_DIAG_ENCODER_TW20_ENABLED TRUE'); Tcp = $tcp },
        @{ Control = $control; Diagnostics = $diagnostics.Replace('DetailCode := 0;', 'if ObjectIndex = 0x3204 then DetailCode := 0; end_if;'); Tcp = $tcp },
        @{ Control = $control.Replace('0x00000017', '0x00000057'); Diagnostics = $diagnostics; Tcp = $tcp })
    $rejected = 0
    $fixtureIndex = 0
    foreach ($fixture in $negativeFixtures) {
        $fixtureIndex++
        $fixtureInputLatchProperty =
            $fixture.PSObject.Properties['InputLatch']
        $fixtureInputLatch = if (
            $null -eq $fixtureInputLatchProperty -or
            [string]::IsNullOrWhiteSpace(
                [string]$fixtureInputLatchProperty.Value)) {
            $inputLatch
        }
        else {
            [string]$fixtureInputLatchProperty.Value
        }
        $fixtureErrorCatalogProperty =
            $fixture.PSObject.Properties['ErrorCatalog']
        $fixtureErrorCatalog = if (
            $null -eq $fixtureErrorCatalogProperty -or
            [string]::IsNullOrWhiteSpace(
                [string]$fixtureErrorCatalogProperty.Value)) {
            $errorCatalog
        }
        else {
            [string]$fixtureErrorCatalogProperty.Value
        }
        $fixtureAdminModelsProperty =
            $fixture.PSObject.Properties['AdminModels']
        $fixtureAdminModels = if (
            $null -eq $fixtureAdminModelsProperty -or
            [string]::IsNullOrWhiteSpace(
                [string]$fixtureAdminModelsProperty.Value)) {
            $adminModels
        }
        else {
            [string]$fixtureAdminModelsProperty.Value
        }
        $fixtureNameProperty = $fixture.PSObject.Properties['Name']
        $fixtureName = if (
            $null -eq $fixtureNameProperty -or
            [string]::IsNullOrWhiteSpace([string]$fixtureNameProperty.Value)) {
            "index $fixtureIndex"
        }
        else {
            [string]$fixtureNameProperty.Value
        }
        $fixtureExpectedMessageProperty =
            $fixture.PSObject.Properties['ExpectedMessage']
        $fixtureExpectedMessage = if (
            $null -eq $fixtureExpectedMessageProperty) {
            ''
        }
        else {
            [string]$fixtureExpectedMessageProperty.Value
        }
        if (($fixture.Control -ceq $control) -and
            ($fixture.Diagnostics -ceq $diagnostics) -and
            ($fixtureInputLatch -ceq $inputLatch) -and
            ($fixture.Tcp -ceq $tcp) -and
            ($fixtureErrorCatalog -ceq $errorCatalog) -and
            ($fixtureAdminModels -ceq $adminModels)) {
            throw (
                "Common axis ownership negative fixture '$fixtureName' " +
                'did not mutate the baseline.')
        }
        try {
            Assert-LasalAxisOwnershipActivationGuard `
                -TcpText $fixture.Tcp `
                -ControlServiceText $fixture.Control `
                -DiagnosticsText $fixture.Diagnostics `
                -InputLatchText $fixtureInputLatch `
                -SdkErrorCatalogText $fixtureErrorCatalog `
                -SdkAdminModelsText $fixtureAdminModels `
                -AllowLegacyTcpFinalizerFixture `
                -Owner "ownership negative self-test '$fixtureName'"
        }
        catch {
            if ($_.Exception.Message -notmatch 'common axis ownership activation blocker') {
                throw
            }
            if (-not [string]::IsNullOrWhiteSpace($fixtureExpectedMessage) -and
                $_.Exception.Message.IndexOf(
                    $fixtureExpectedMessage,
                    [StringComparison]::OrdinalIgnoreCase) -lt 0) {
                throw (
                    "Common axis ownership negative fixture '$fixtureName' " +
                    "failed for an unexpected assertion: $($_.Exception.Message)")
            }
            $rejected++
            continue
        }
        throw (
            "Common axis ownership verifier accepted negative fixture " +
            "'$fixtureName'.")
    }
    if ($rejected -ne $negativeFixtures.Count) {
        throw "Common axis ownership guard rejected $rejected/$($negativeFixtures.Count) negative fixtures."
    }
    return $rejected
}

function Invoke-LasalOrdinarySafetyRepeatVerifierSelfTest {
    $fixturePath = Join-Path $PSScriptRoot (
        'Verify-LasalAxisOwnershipActivationGuard.Fixture.ps1')
    if (-not (Test-Path -LiteralPath $fixturePath -PathType Leaf)) {
        throw "Ordinary safety-repeat verifier fixture is missing: $fixturePath"
    }
    $fixture = & $fixturePath -RepositoryRoot $RepositoryRoot
    if ($null -eq $fixture -or
        [string]::IsNullOrWhiteSpace($fixture.SafetyRepeatControl) -or
        [string]::IsNullOrWhiteSpace($fixture.SafetyRepeatTcp) -or
        $null -eq $fixture.SafetyRepeatNegativeFixtures) {
        throw 'Ordinary safety-repeat verifier fixture is incomplete.'
    }

    Assert-LasalOrdinarySafetyRepeatContract `
        -ControlServiceText $fixture.SafetyRepeatControl `
        -TcpText $fixture.SafetyRepeatTcp `
        -Owner 'ordinary safety-repeat self-test'

    $negativeFixtures = @($fixture.SafetyRepeatNegativeFixtures)
    if ($negativeFixtures.Count -lt 20) {
        throw (
            'Ordinary safety-repeat verifier fixture count is ' +
            "$($negativeFixtures.Count), expected at least 20.")
    }
    $rejected = 0
    foreach ($negativeFixture in $negativeFixtures) {
        if ($null -eq $negativeFixture -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Name) -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Control) -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Tcp)) {
            throw 'Ordinary safety-repeat negative fixture is incomplete.'
        }
        if (($negativeFixture.Control -ceq $fixture.SafetyRepeatControl) -and
            ($negativeFixture.Tcp -ceq $fixture.SafetyRepeatTcp)) {
            throw (
                "Ordinary safety-repeat negative fixture " +
                "'$($negativeFixture.Name)' did not mutate the baseline.")
        }
        try {
            Assert-LasalOrdinarySafetyRepeatContract `
                -ControlServiceText $negativeFixture.Control `
                -TcpText $negativeFixture.Tcp `
                -Owner "ordinary safety-repeat negative self-test '$($negativeFixture.Name)'"
        }
        catch {
            if ($_.Exception.Message -notmatch
                'common axis ownership activation blocker: ordinary safety repeat') {
                throw
            }
            if (-not [string]::IsNullOrWhiteSpace(
                    [string]$negativeFixture.ExpectedMessage) -and
                $_.Exception.Message.IndexOf(
                    [string]$negativeFixture.ExpectedMessage,
                    [StringComparison]::OrdinalIgnoreCase) -lt 0) {
                throw (
                    "Ordinary safety-repeat negative fixture " +
                    "'$($negativeFixture.Name)' failed for an unexpected assertion: " +
                    $_.Exception.Message)
            }
            $rejected++
            continue
        }
        throw (
            'Ordinary safety-repeat verifier accepted negative fixture ' +
            "'$($negativeFixture.Name)'.")
    }
    if ($rejected -ne $negativeFixtures.Count) {
        throw (
            "Ordinary safety-repeat verifier rejected $rejected/" +
            "$($negativeFixtures.Count) negative fixtures.")
    }
    return $rejected
}

function Assert-LasalAxisRebaseBarrierContract {
    param(
        [string]$ControlServiceText,
        [object[]]$NetworkArtifacts,
        [string]$Owner
    )

    $blocker = "$Owner TW19 Home barrier blocker:"
    $scan = Get-LasalScanText $ControlServiceText
    if ($null -eq $NetworkArtifacts -or $NetworkArtifacts.Count -eq 0) {
        throw "$blocker Network artifact inventory is empty."
    }
    $endpoint = 'LMCControlCommandService1.AxisRebaseRequiredState'
    $authoritativeNetworkCount = 0
    $generatedNetworkCount = 0
    $connectionViolations = [System.Collections.Generic.List[string]]::new()
    foreach ($networkArtifact in $NetworkArtifacts) {
        if ($null -eq $networkArtifact -or
            [string]::IsNullOrWhiteSpace([string]$networkArtifact.Name) -or
            $null -eq $networkArtifact.Text) {
            throw "$blocker Network artifact inventory contains an invalid entry."
        }
        $artifactName = [string]$networkArtifact.Name
        $artifactText = [string]$networkArtifact.Text
        if ($artifactName -match '(?i)\.lcn$') {
            $authoritativeNetworkCount++
            try {
                [xml]$networkXml = $artifactText
            }
            catch {
                throw "$blocker $artifactName is not valid Network XML."
            }
            $endpointConnections = @($networkXml.SelectNodes(
                "//Connection[@Source='$endpoint' or @Destination='$endpoint']"))
            if ($endpointConnections.Count -ne 0) {
                $connectionViolations.Add(
                    "$artifactName has $($endpointConnections.Count) endpoint connection(s).")
            }
        }
        elseif ($artifactName -match
                '(?i)(?:^|\\)ONE_[^\\]+_Table\.st$') {
            $generatedNetworkCount++
            $connectionBlocks = @(
                [regex]::Match(
                    $artifactText,
                    '(?s)//Internal connections(?<Body>.*?)' +
                    '//Initialization values'),
                [regex]::Match(
                    $artifactText,
                    '(?s)//External connections(?<Body>.*?)' +
                    '//Magic internal connections'))
            if (@($connectionBlocks |
                    Where-Object { -not $_.Success }).Count -ne 0) {
                throw "$blocker $artifactName connection blocks were not found."
            }
            $generatedConnectionTokenCount = 0
            foreach ($connectionBlock in $connectionBlocks) {
                $generatedConnectionTokenCount += [regex]::Matches(
                    $connectionBlock.Groups['Body'].Value,
                    '(?i)"AxisRebaseRequiredState"').Count
            }
            if ($generatedConnectionTokenCount -ne 0) {
                $connectionViolations.Add(
                    "$artifactName has $generatedConnectionTokenCount " +
                    'generated connection entry token(s).')
            }
        }
    }
    if ($authoritativeNetworkCount -eq 0 -or $generatedNetworkCount -eq 0) {
        throw "$blocker authoritative or generated Network inventory is missing."
    }
    if ($connectionViolations.Count -ne 0) {
        throw (
            "$blocker the retained server must have zero Network connection " +
            "endpoints: $($connectionViolations -join ' ')")
    }
    foreach ($define in @(
            @{ Name = 'LMC_OWNER_REBASE_PERSIST_RETRY'; Value = '-4' },
            @{ Name = 'LMC_AXIS_REBASE_BARRIER_ENABLED'; Value = 'TRUE' },
            @{ Name = 'LMC_AXIS_REBASE_STATE_MAGIC'; Value = '0x52425300' },
            @{ Name = 'LMC_AXIS_REBASE_STATE_MAGIC_MASK'; Value = '0xFFFFFF00' },
            @{ Name = 'LMC_AXIS_REBASE_STATE_AXIS_MASK'; Value = '0x0000000F' },
            @{ Name = 'LMC_AXIS_REBASE_STATE_INVERSE_MASK'; Value = '0x000000F0' })) {
        $pattern = ('(?m)^\s*#define\s+' + [regex]::Escape($define.Name) +
            '\s+' + [regex]::Escape($define.Value) + '\s*$')
        if ([regex]::Matches($scan, $pattern).Count -ne 1) {
            throw "$blocker $($define.Name) must be defined exactly once as $($define.Value)."
        }
    }

    foreach ($codecName in @(
            'ReadAxisRebaseRequiredMask',
            'UpdateAxisRebaseRequiredState')) {
        $codecImplementationPattern = (
            '(?im)^[ \t]*FUNCTION[^\r\n]*' +
            'LMCControlCommandService::' + [regex]::Escape($codecName) +
            '[ \t]*\r?$')
        $codecPrivatePattern = (
            '(?im)^[ \t]*FUNCTION[ \t]+LMCControlCommandService::' +
            [regex]::Escape($codecName) + '[ \t]*\r?$')
        if ([regex]::Matches($scan, $codecImplementationPattern).Count -ne 1 -or
            [regex]::Matches($scan, $codecPrivatePattern).Count -ne 1) {
            throw (
                "$blocker $codecName implementation must exist exactly once " +
                'as a private, non-GLOBAL function before IDE declaration.')
        }
    }

    $blocks = @{}
    foreach ($name in @(
            'ReadAxisRebaseRequiredMask',
            'UpdateAxisRebaseRequiredState',
            'HandleAxisOwnershipSafetyRepeat',
            'HandleGroupCommands',
            'ReserveAxisOwnership',
            'CommitAxisOwnership',
            'PublishAxisOwnership',
            'ProcessAxisZeroHome')) {
        $blocks[$name] = [regex]::Match(
            $scan,
            ('(?is)FUNCTION\s+(?:GLOBAL\s+)?LMCControlCommandService::' +
             [regex]::Escape($name) + '\b.*?END_FUNCTION')).Value
        if ([string]::IsNullOrWhiteSpace($blocks[$name])) {
            throw "$blocker $name implementation is missing."
        }
    }

    $reader = $blocks['ReadAxisRebaseRequiredMask']
    Assert-Match $reader (
        '(?is)rawState\s*:=\s*AxisRebaseRequiredState\.Read\(\)\s*;.*?' +
        'axisMask\s*:=\s*rawState\s+and\s+LMC_AXIS_REBASE_STATE_AXIS_MASK\s*;.*?' +
        'inverseMask\s*:=\s*\(rawState\s+and\s+' +
        'LMC_AXIS_REBASE_STATE_INVERSE_MASK\)\s+shr\s+4\s*;.*?' +
        'if\s+stateValid\s*=\s*FALSE\s+then\s*' +
        'axisMask\s*:=\s*LMC_AXIS_REBASE_STATE_AXIS_MASK\s*;.*?' +
        'Result\s*:=\s*TO_DINT\(axisMask\)\s*;') (
        "$blocker retained-state reader must decode invalid data to physical mask 0xF.")
    $updater = $blocks['UpdateAxisRebaseRequiredState']
    Assert-Match $updater (
        '(?is)if\s*\(\(SetAxisMask\s+or\s+ClearAxisMask\)\s*>\s*' +
        'LMC_AXIS_REBASE_STATE_AXIS_MASK\)\s*\|\s*' +
        '\(\(SetAxisMask\s+and\s+ClearAxisMask\)\s*<>\s*0\)\s+then.*?' +
        'readResult\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;.*?' +
        'axisMask\s*:=\s*\(axisMask\s+or\s+SetAxisMask\)\s+and\s*' +
        '\(LMC_AXIS_REBASE_STATE_AXIS_MASK\s+xor\s+ClearAxisMask\)\s*;.*?' +
        'newState\s*:=\s*LMC_AXIS_REBASE_STATE_MAGIC\s+or\s+axisMask\s+or.*?' +
        'AxisRebaseRequiredState\.Write\(\s*input\s*:=\s*newState\s*\)\s*;\s*' +
        'if\s+AxisRebaseRequiredState\.Read\(\)\s*<>\s*newState\s+then\s*' +
        'Result\s*:=\s*LMC_OWNER_REBASE_PERSIST_RETRY\s*;\s*RETURN\s*;.*?' +
        'Result\s*:=\s*0\s*;') (
        "$blocker retained-state updater must encode, write, read back, and return retry.")
    $updaterInitialFailures = [regex]::Matches(
        $updater,
        '(?im)^[ \t]*Result[ \t]*:=[ \t]*-1[ \t]*;[ \t]*\r?$')
    $updaterInputFence = [regex]::Match(
        $updater,
        ('(?is)if\s*\(\(SetAxisMask\s+or\s+ClearAxisMask\)\s*>\s*' +
         'LMC_AXIS_REBASE_STATE_AXIS_MASK\)\s*\|\s*' +
         '\(\(SetAxisMask\s+and\s+ClearAxisMask\)\s*<>\s*0\)\s+then\s*' +
         'RETURN\s*;\s*end_if\s*;'))
    $updaterRead = [regex]::Match(
        $updater,
        'readResult\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;')
    $updaterRangeFence = [regex]::Match(
        $updater,
        ('(?is)if\s*\(readResult\s*<\s*0\)\s*\|\s*' +
         '\(readResult\s*>\s*15\)\s+then\s*RETURN\s*;\s*end_if\s*;'))
    $updaterConversion = [regex]::Match(
        $updater,
        'axisMask\s*:=\s*TO_UDINT\(readResult\)\s*;')
    $updaterWrite = [regex]::Match(
        $updater,
        'AxisRebaseRequiredState\.Write\s*\(')
    if ($updaterInitialFailures.Count -ne 1 -or
        -not $updaterInputFence.Success -or
        -not $updaterRead.Success -or -not $updaterRangeFence.Success -or
        -not $updaterConversion.Success -or -not $updaterWrite.Success -or
        $updaterInitialFailures[0].Index -ge $updaterInputFence.Index -or
        $updaterInputFence.Index -ge $updaterRead.Index -or
        $updaterRead.Index -ge $updaterRangeFence.Index -or
        $updaterRangeFence.Index -ge $updaterConversion.Index -or
        $updaterConversion.Index -ge $updaterWrite.Index) {
        throw (
            "$blocker updater must initialize failure exactly once, reject " +
            'invalid masks, and reject readResult outside 0..15 before unsigned ' +
            'conversion or retained-server write.')
    }
    $updaterBeforeConversion = $updater.Substring(
        $updaterInitialFailures[0].Index,
        $updaterConversion.Index - $updaterInitialFailures[0].Index)
    $updaterEarlyResultAssignments = [regex]::Matches(
        $updaterBeforeConversion,
        '(?i)(?<![A-Za-z0-9_])Result(?![A-Za-z0-9_])\s*:=' )
    if ($updaterEarlyResultAssignments.Count -ne 1) {
        throw (
            "$blocker updater must retain failure from its initial assignment " +
            'through validated signed-to-unsigned conversion; no early success ' +
            'assignment is allowed.')
    }
    if ([regex]::Matches(
            $scan,
            'AxisRebaseRequiredState\.Write\s*\(').Count -ne 1) {
        throw "$blocker only the private updater may write the retained server."
    }

    $helper = $blocks['HandleAxisOwnershipSafetyRepeat']
    $repeatCase = [regex]::Match(
        $helper,
        '(?is)case\s+CommandId\s+of\s+LMC_OWNER_COMMAND_AXIS_STOP\s*:')
    $rebaseRead = [regex]::Match(
        $helper,
        '(?is)rebaseReadResult\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;\s*' +
        'rebaseAxisMask\s*:=\s*TO_UDINT\(rebaseReadResult\)\s*;')
    if (-not $rebaseRead.Success -or -not $repeatCase.Success -or
        $rebaseRead.Index -ge $repeatCase.Index) {
        throw "$blocker the retained-state guard must run at the top of the repeat helper."
    }
    $helperGuard = $helper.Substring(0, $repeatCase.Index)
    foreach ($pattern in @(
            '0x2023\s*:\s*if\s*\(RequestFrameSize\s*=\s*16\).*?\(pRequestFrame\s*\+\s*12\)\^\s*=\s*1',
            '0x209F\s*,\s*0x20A0\s*:\s*if\s*\(RequestFrameSize\s*=\s*40\)',
            '0x20A2\s*:\s*if\s*\(RequestFrameSize\s*=\s*32\)',
            '0x2047\s*,\s*0x204A\s*:.*?\(pRequestFrame\s*\+\s*8\)\^\s*=\s*1',
            '0x20A4\s*:\s*if\s*\(RequestFrameSize\s*=\s*104\)',
            '0x7D22\s*:\s*if\s*\(RequestFrameSize\s*=\s*112\)')) {
        Assert-Match $helperGuard ('(?is)' + $pattern) (
            "$blocker guarded mutation shape is missing: $pattern")
    }
    foreach ($allowedCommand in @(
            '0x2022', '0x2024', '0x2048', '0x2049', '0x204B', '0x2085',
            '0x20E7', '0x7D13', '0x7D18', '0x7D19',
            '0x7E53', '0x7E54', '0x7E55')) {
        if ($helperGuard -match ('(?<![A-Fa-f0-9])' + $allowedCommand + '(?![A-Fa-f0-9])')) {
            throw "$blocker reset, safety, Home, and maintenance command $allowedCommand must fall through."
        }
    }
    Assert-Match $helperGuard (
        '(?is)0x7D22\s*:.*?_memset\([^;]*cntr\s*:=\s*24\).*?' +
        '\(pResponseFrame\s*\+\s*14\)\^\$INT\s*:=\s*-31000\s*;.*?' +
        '\(pResponseFrame\s*\+\s*20\)\^\$UDINT\s*:=\s*41\s*;.*?' +
        'Result\s*:=\s*24\s*;') (
        "$blocker Group Admin conflict envelope is not canonical 24-byte output.")
    Assert-Match $helperGuard (
        '(?is)else\s+if\s+ResponseCapacity\s*<\s*16\s+then.*?' +
        '_memset\([^;]*cntr\s*:=\s*16\).*?' +
        '\(pResponseFrame\s*\+\s*14\)\^\$INT\s*:=\s*' +
        'LMC_OWNER_ADAPTER_ERROR_CONFLICT\s*;.*?Result\s*:=\s*16\s*;') (
        "$blocker legacy conflict envelope is not canonical 16-byte adapter output.")
    if ($helperGuard -match
        '(?i)HandleAxisCommands|HandleGroupCommands|HandleAdminCommands|' +
        'CommitAxisOwnership|RollbackAxisOwnership|PublishAxisOwnership') {
        throw "$blocker a blocked request can reach owner or native dispatch."
    }

    $groupHandler = $blocks['HandleGroupCommands']
    Assert-Match $groupHandler (
        '(?is)0x20E7\s*:.*?groupReadErrorId\s*:=\s*-7\s*;\s*' +
        'if\s+kinValid\s*=\s*TRUE\s+then\s*' +
        'kinRebaseMask\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;\s*' +
        'if\s+LMC_AXIS_REBASE_BARRIER_ENABLED\s*&\s*' +
        '\(\(TO_UDINT\(kinRebaseMask\)\s+and\s+' +
        'LMC_AXIS_REBASE_STATE_AXIS_MASK\)\s*<>\s*0\)\s+then\s*' +
        'groupReadErrorId\s*:=\s*LMC_OWNER_ADAPTER_ERROR_CONFLICT\s*;\s*' +
        'else.*?GroupKinematicReady\s*:=\s*TRUE\s*;.*?' +
        '_memset\([^;]*cntr\s*:=\s*12\).*?' +
        '\(pResponseFrame\s*\+\s*10\)\^\$INT\s*:=\s*groupReadErrorId\$INT\s*;.*?' +
        'ResponseSize\s*:=\s*12\s*;') (
        "$blocker SetKin must preserve malformed -7, then block valid mutation with canonical output.")
    $kinFinalShape = [regex]::Match(
        $groupHandler,
        '(?is)\(pRequestFrame\s*\+\s*1320\)\^\$DINT\s*<>\s*1.*?' +
        'kinValid\s*:=\s*FALSE\s*;')
    $kinBarrier = [regex]::Match(
        $groupHandler,
        'kinRebaseMask\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;')
    $kinMutation = @([regex]::Matches(
            $groupHandler,
            'OwnershipState\[26\]\s*:=\s*TO_DINT\(CommandId\)\s*;') |
        Where-Object { $_.Index -gt $kinBarrier.Index } |
        Select-Object -First 1)
    if (-not $kinFinalShape.Success -or -not $kinBarrier.Success -or
        $kinMutation.Count -ne 1 -or
        $kinFinalShape.Index -ge $kinBarrier.Index -or
        $kinBarrier.Index -ge $kinMutation[0].Index) {
        throw "$blocker SetKin barrier must be after full shape proof and before mutation."
    }

    $reserve = $blocks['ReserveAxisOwnership']
    Assert-Match $reserve (
        '(?is)rebaseReadResult\s*:=\s*ReadAxisRebaseRequiredMask\(\)\s*;\s*' +
        'rebaseAxisMask\s*:=\s*TO_UDINT\(rebaseReadResult\)\s*;.*?' +
        'rebaseAdmissionAllowed\s*:=\s*' +
        '\(AdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY\).*?' +
        '\(CommandId\s*=\s*0x7D13\).*?' +
        '\(CommandId\s*=\s*0x7E53\).*?' +
        '\(CommandId\s*=\s*0x2024\)\s*\|\s*' +
        '\(CommandId\s*=\s*0x2049\)\s*;.*?' +
        'if\s*\(\(effectiveAxisMask\s+and\s+rebaseAxisMask\)\s*<>\s*0\)\s*&\s*' +
        '\(rebaseAdmissionAllowed\s*=\s*FALSE\)\s+then\s*' +
        'Result\s*:=\s*-2\s*;\s*RETURN\s*;') (
        "$blocker ReserveAxisOwnership duplicate guard or allow matrix drifted.")
    if ([regex]::Matches(
            $reserve,
            'AxisRebaseRequiredState\.Write\s*\(').Count -ne 0) {
        throw "$blocker ReserveAxisOwnership must never mutate the retained barrier."
    }

    $commit = $blocks['CommitAxisOwnership']
    $validateEnd = [regex]::Match(
        $commit,
        ('(?is)Result\s*:=\s*ValidateAxisOwnership\(\s*' +
         'CommandId\s*:=\s*CommandId\s*,\s*' +
         'Reference\s*:=\s*Reference\s*,\s*' +
         'ExpectedAxisMask\s*:=\s*ExpectedAxisMask\s*,\s*' +
         'OwnerKind\s*:=\s*ownerKind\s*,\s*' +
         'ResourceKind\s*:=\s*resourceKind\s*,\s*' +
         'AdmissionMode\s*:=\s*admissionMode\s*,\s*' +
         'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
         'RequestSequence\s*:=\s*RequestSequence\s*,\s*' +
         'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
         'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
         'RequiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*\)\s*;\s*' +
         'if\s+Result\s*<>\s*0\s+then\s*RETURN\s*;\s*end_if\s*;'))
    $armWrite = [regex]::Match(
        $commit,
        '(?is)rebaseUpdateResult\s*:=\s*UpdateAxisRebaseRequiredState\(\s*' +
        'SetAxisMask\s*:=\s*ExpectedAxisMask\s*,\s*' +
        'ClearAxisMask\s*:=\s*0\s*\)\s*;')
    $firstOwnerMutation = [regex]::Match(
        $commit,
        'OwnershipState\s*\[\s*recordBase\s*\+\s*1\s*\]\s*:=')
    if (-not $validateEnd.Success -or -not $armWrite.Success -or
        -not $firstOwnerMutation.Success -or
        $validateEnd.Index -ge $armWrite.Index -or
        $armWrite.Index -ge $firstOwnerMutation.Index) {
        throw "$blocker TW19 must arm after full RESERVED validation and before owner mutation."
    }
    $commitPrefix = $commit.Substring(0, $armWrite.Index)
    $ownershipSurface = (
        'OwnershipState|OwnershipObserverState|OwnershipLeaseState|' +
        'OwnershipPreemptedState|OwnershipIdentityState|' +
        'OwnershipLeaseIdentityState|OwnershipPreemptedIdentityState')
    if ($commitPrefix -match (
            '(?is)(?:' + $ownershipSurface + ')\s*\[[^\]]+\]' +
            '(?:\$[A-Za-z_][A-Za-z0-9_]*)?\s*(?::=|\+=|-=)')) {
        throw "$blocker TW19 pre-arm prefix mutates an ownership surface."
    }
    if ($commitPrefix -match (
            '(?is)_(?:memset|memcpy)\s*\([^;]*' +
            '(?:' + $ownershipSurface + ')\s*\[')) {
        throw "$blocker TW19 pre-arm prefix clears or copies an ownership surface."
    }
    if ($commitPrefix -match (
            '(?is)(?<![A-Za-z0-9_])(?:LMCAxis[1-9]|LMCRobot|InputLatch|' +
            'SdoAxis[1-4]|AxisRebaseRequiredState)(?![A-Za-z0-9_])')) {
        throw "$blocker TW19 pre-arm prefix touches native, SDO, or client state."
    }

    $controlMethodNames = @(
        [regex]::Matches(
            $scan,
            ('(?im)^[ \t]*FUNCTION[^\r\n]*?' +
             'LMCControlCommandService::' +
             '(?<Name>[A-Za-z_][A-Za-z0-9_]*)[ \t]*\r?$')) |
            ForEach-Object { $_.Groups['Name'].Value } |
            Sort-Object -Unique)
    foreach ($requiredMethodName in @(
            'ValidateAxisOwnership',
            'UpdateAxisRebaseRequiredState',
            'PublishAxisOwnership')) {
        if ($controlMethodNames -cnotcontains $requiredMethodName) {
            throw (
                "$blocker class method inventory is missing " +
                "$requiredMethodName.")
        }
    }
    foreach ($controlMethodName in $controlMethodNames) {
        $prefixMethodCalls = [regex]::Matches(
            $commitPrefix,
            ('(?i)(?<![A-Za-z0-9_])' +
             [regex]::Escape($controlMethodName) +
             '(?![A-Za-z0-9_])\s*\('))
        if ($controlMethodName -ceq 'ValidateAxisOwnership') {
            if ($prefixMethodCalls.Count -ne 1) {
                throw (
                    "$blocker exact ValidateAxisOwnership must be the only " +
                    'allowed class method call in the pre-arm prefix.')
            }
        }
        elseif ($prefixMethodCalls.Count -ne 0) {
            throw (
                "$blocker pre-arm prefix invokes forbidden class method " +
                "$controlMethodName.")
        }
    }
    Assert-Match $commit (
        '(?is)if\s+LMC_AXIS_REBASE_BARRIER_ENABLED\s*&.*?' +
        '\(CommandId\s*=\s*0x7E53\).*?' +
        '\(ownerKind\s*=\s*LMC_OWNER_KIND_ENCODER\).*?' +
        '\(resourceKind\s*=\s*LMC_OWNER_RESOURCE_DIAGNOSTICS_SDO_ENGINE\).*?' +
        '\(admissionMode\s*=\s*LMC_OWNER_ADMISSION_LIFECYCLE\).*?' +
        '\(Reference\s*>=\s*1\)\s*&\s*\(Reference\s*<=\s*4\).*?' +
        '\(ExpectedAxisMask\s*=\s*axisBit\).*?' +
        'OwnershipState\[recordBase\s*\+\s*15\]\$UDINT\s*=\s*72.*?' +
        'OwnershipState\[recordBase\s*\+\s*25\]\$UINT\s*=\s*2.*?' +
        'OwnershipState\[recordBase\s*\+\s*26\]\$UINT\s*=\s*Reference.*?' +
        'OwnershipState\[recordBase\s*\+\s*27\]\$UDINT\s*=\s*1\)\s*then') (
        "$blocker CommitAxisOwnership does not select the exact TW19 identity only.")
    Assert-Match $commit (
        '(?is)rebaseUpdateResult\s*:=\s*UpdateAxisRebaseRequiredState\(\s*' +
        'SetAxisMask\s*:=\s*ExpectedAxisMask\s*,\s*' +
        'ClearAxisMask\s*:=\s*0\s*\)\s*;\s*' +
        'if\s+rebaseUpdateResult\s*<>\s*0\s+then\s*' +
        'Result\s*:=\s*rebaseUpdateResult\s*;\s*RETURN\s*;') (
        "$blocker TW19 arm must call the retryable retained-state updater exactly.")
    if ([regex]::Matches(
            $commit,
            'UpdateAxisRebaseRequiredState\s*\(').Count -ne 1) {
        throw "$blocker CommitAxisOwnership must contain exactly one retained update."
    }

    $publish = $blocks['PublishAxisOwnership']
    $publishHomeProvider = $publish
    $publishMode = Get-LasalAxisOwnershipPublishMode `
        -ControlServiceText $ControlServiceText
    if ($publishMode -ceq 'SplitCandidate') {
        try {
            $publishSplitFragments =
                Get-LasalAxisOwnershipPublishSplitFragments `
                    -ControlServiceText $ControlServiceText `
                    -Owner "$Owner TW19 Home provider"
        }
        catch {
            throw (
                "$blocker split Home provider closure is invalid: " +
                $_.Exception.Message)
        }
        $publish = Get-LasalScanText $publishSplitFragments.Adapter
        $publishHomeProvider = Get-LasalScanText $publishSplitFragments.Home
        Assert-Match $publish (
            '(?is)homeReceiptResult\s*:=\s*' +
            'HandleAxisOwnershipPublishHomeReceipt\s*\(\s*' +
            'AxisMask\s*:=\s*AxisMask\s*,\s*' +
            'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
            'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
            'ReportKind\s*:=\s*ReportKind\s*,\s*' +
            'ReportValue0\s*:=\s*ReportValue0\s*,\s*' +
            'ReportValue1\s*:=\s*ReportValue1\s*,\s*' +
            'ObservationCycle\s*:=\s*ObservationCycle\s*\)\s*;\s*' +
            'if\s+homeReceiptResult\s*<>\s*2\s+then\s*' +
            'Result\s*:=\s*homeReceiptResult\s*;\s*' +
            'RETURN\s*;\s*end_if\s*;') (
            "$blocker split adapter must call the exact Home provider and " +
            'return every non-continuation result.')
    }
    $completeFence = [regex]::Match(
        $publishHomeProvider,
        '(?is)if\s*\(ZeroHomeState\[61\]\s*<>\s*' +
        'LMC_HOME_OWNER_RECEIPT_COMPLETE\).*?Result\s*:=\s*-3\s*;\s*RETURN\s*;')
    $clearWrite = [regex]::Match(
        $publishHomeProvider,
        '(?is)rebaseUpdateResult\s*:=\s*UpdateAxisRebaseRequiredState\(\s*' +
        'SetAxisMask\s*:=\s*0\s*,\s*' +
        'ClearAxisMask\s*:=\s*AxisMask\s*\)\s*;')
    $successReturn = [regex]::Match(
        $publishHomeProvider,
        'Result\s*:=\s*1\s*;\s*RETURN\s*;',
        [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if (-not $completeFence.Success -or -not $clearWrite.Success -or
        -not $successReturn.Success -or
        $completeFence.Index -ge $clearWrite.Index -or
        $clearWrite.Index -ge $successReturn.Index) {
        throw "$blocker Home clear must follow COMPLETE receipt proof and precede Result=1."
    }
    Assert-Match $publishHomeProvider (
        '(?is)if\s+LMC_AXIS_REBASE_BARRIER_ENABLED\s*&\s*' +
        '\(ReportKind\s*=\s*LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*&\s*' +
        '\(ReportValue0\s*=\s*LMC_HOME_RECORD_SUCCEEDED\)\s*&\s*' +
        '\(ZeroHomeState\[57\]\s*=\s*LMC_HOME_RECORD_SUCCEEDED\)\s+then.*?' +
        'rebaseUpdateResult\s*:=\s*UpdateAxisRebaseRequiredState\(\s*' +
        'SetAxisMask\s*:=\s*0\s*,\s*ClearAxisMask\s*:=\s*AxisMask\s*\)\s*;\s*' +
        'if\s+rebaseUpdateResult\s*<>\s*0\s+then\s*' +
        'Result\s*:=\s*rebaseUpdateResult\s*;\s*RETURN\s*;') (
        "$blocker only exact terminal-success Home may clear one selected axis with readback.")
    if ([regex]::Matches(
            $publishHomeProvider,
            'UpdateAxisRebaseRequiredState\s*\(').Count -ne 1 -or
        [regex]::Matches(
            $scan,
            'UpdateAxisRebaseRequiredState\s*\(').Count -ne 2) {
        throw "$blocker retained updates must be limited to one TW19 arm and one Home clear."
    }

    $process = $blocks['ProcessAxisZeroHome']
    Assert-Match $process (
        '(?is)if\s+homePublishResult\s*=\s*' +
        'LMC_OWNER_REBASE_PERSIST_RETRY\s+then\s*RETURN\s*;\s*end_if\s*;\s*' +
        'if\s*\(homePublishResult\s*<>\s*1\).*?' +
        'OwnershipState\[24\]\s*:=\s*1\s*;') (
        "$blocker ProcessAxisZeroHome must retry persistence without global quarantine.")
}

function Invoke-LasalAxisRebaseBarrierVerifierSelfTest {
    $fixturePath = Join-Path $PSScriptRoot (
        'Verify-LasalAxisRebaseBarrier.Fixture.ps1')
    if (-not (Test-Path -LiteralPath $fixturePath -PathType Leaf)) {
        throw "TW19 Home barrier verifier fixture is missing: $fixturePath"
    }
    $fixture = & $fixturePath -RepositoryRoot $RepositoryRoot
    if ($null -eq $fixture -or
        [string]::IsNullOrWhiteSpace($fixture.Control) -or
        $null -eq $fixture.NetworkArtifacts -or
        @($fixture.NetworkArtifacts).Count -eq 0 -or
        $null -eq $fixture.NegativeFixtures) {
        throw 'TW19 Home barrier verifier fixture is incomplete.'
    }
    Assert-LasalAxisRebaseBarrierContract `
        -ControlServiceText $fixture.Control `
        -NetworkArtifacts @($fixture.NetworkArtifacts) `
        -Owner 'TW19 Home barrier self-test'
    $baselineNetworkSignature = (@($fixture.NetworkArtifacts) |
        ForEach-Object {
            ([string]$_.Name).Length.ToString() + ':' +
            [string]$_.Name +
            ([string]$_.Text).Length.ToString() + ':' +
            [string]$_.Text
        }) -join ''
    $negativeFixtures = @($fixture.NegativeFixtures)
    if ($negativeFixtures.Count -lt 16 -or $negativeFixtures.Count -gt 40) {
        throw (
            'TW19 Home barrier negative fixture count is ' +
            "$($negativeFixtures.Count), expected 16..40 bounded mutations.")
    }
    $rejected = 0
    foreach ($negativeFixture in $negativeFixtures) {
        if ($null -eq $negativeFixture -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Name) -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Control)) {
            throw 'TW19 Home barrier negative fixture is incomplete or unchanged.'
        }
        $negativeNetworkArtifactsProperty =
            $negativeFixture.PSObject.Properties['NetworkArtifacts']
        $negativeNetworkArtifacts = if (
            $null -eq $negativeNetworkArtifactsProperty -or
            $null -eq $negativeNetworkArtifactsProperty.Value) {
            @($fixture.NetworkArtifacts)
        }
        else {
            @($negativeNetworkArtifactsProperty.Value)
        }
        if ($negativeNetworkArtifacts.Count -eq 0) {
            throw 'TW19 Home barrier negative fixture has no Network artifacts.'
        }
        $negativeNetworkSignature = ($negativeNetworkArtifacts |
            ForEach-Object {
                ([string]$_.Name).Length.ToString() + ':' +
                [string]$_.Name +
                ([string]$_.Text).Length.ToString() + ':' +
                [string]$_.Text
            }) -join ''
        $controlChanged = $negativeFixture.Control -cne $fixture.Control
        $networkChanged =
            $negativeNetworkSignature -cne $baselineNetworkSignature
        if ($controlChanged -eq $networkChanged) {
            throw (
                'TW19 Home barrier negative fixture must mutate exactly one ' +
                'of Control or NetworkArtifacts.')
        }
        try {
            Assert-LasalAxisRebaseBarrierContract `
                -ControlServiceText $negativeFixture.Control `
                -NetworkArtifacts $negativeNetworkArtifacts `
                -Owner "TW19 Home barrier negative self-test '$($negativeFixture.Name)'"
        }
        catch {
            if ($_.Exception.Message -notmatch 'TW19 Home barrier blocker:') {
                throw
            }
            $rejected++
            continue
        }
        throw (
            'TW19 Home barrier verifier accepted negative fixture ' +
            "'$($negativeFixture.Name)'.")
    }
    return $rejected
}

function Get-LasalDiagnosticsImplementationBlock {
    param(
        [string]$DiagnosticsText,
        [string]$FunctionName,
        [string]$Owner
    )

    $pattern = (
        '(?ims)^[ \t]*FUNCTION[ \t]+' +
        '(?:(?:VIRTUAL[ \t]+)?GLOBAL[ \t]+)?' +
        'LMCDiagnosticsService::' + [regex]::Escape($FunctionName) +
        '[ \t]*\r?$.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
    $matches = [regex]::Matches($DiagnosticsText, $pattern)
    if ($matches.Count -ne 1) {
        throw (
            "$Owner diagnostics method split blocker: $FunctionName " +
            "implementation count is $($matches.Count), expected one.")
    }
    return $matches[0].Value
}

function Get-LasalImplementationVariableInventory {
    param(
        [string]$FunctionBlock,
        [ValidateSet('INPUT', 'OUTPUT')]
        [string]$Kind,
        [string]$Owner
    )

    $sectionPattern = (
        '(?ims)^[ \t]*VAR_' + $Kind + '[ \t]*\r?$' +
        '(?<Body>.*?)^[ \t]*END_VAR[ \t]*\r?$')
    $sections = [regex]::Matches($FunctionBlock, $sectionPattern)
    if ($sections.Count -gt 1) {
        throw (
            "$Owner diagnostics method split blocker: duplicate VAR_$Kind " +
            'sections are forbidden.')
    }
    if ($sections.Count -eq 0) {
        return @()
    }

    $body = $sections[0].Groups['Body'].Value
    $declarationPattern = (
        '(?im)^[ \t]*(?<Names>[A-Za-z_][A-Za-z0-9_]*' +
        '(?:[ \t]*,[ \t]*[A-Za-z_][A-Za-z0-9_]*)*)[ \t]*:[ \t]*' +
        '(?<Type>[^;\r\n]+)[ \t]*;[ \t]*\r?$')
    $declarations = [regex]::Matches($body, $declarationPattern)
    $unparsed = [regex]::Replace($body, $declarationPattern, '')
    if (-not [string]::IsNullOrWhiteSpace($unparsed)) {
        throw (
            "$Owner diagnostics method split blocker: VAR_$Kind contains " +
            'an unsupported or malformed declaration.')
    }

    $inventory = [System.Collections.Generic.List[object]]::new()
    foreach ($declaration in $declarations) {
        $typeName = $declaration.Groups['Type'].Value.Trim()
        foreach ($variableName in
                ($declaration.Groups['Names'].Value -split ',')) {
            $inventory.Add([pscustomobject]@{
                    Name = $variableName.Trim()
                    Type = $typeName
                })
        }
    }
    return $inventory.ToArray()
}

function Assert-LasalDiagnosticsImplementationAbi {
    param(
        [string]$FunctionBlock,
        [string]$FunctionName,
        [object[]]$Inputs,
        [object[]]$Outputs,
        [string]$Owner
    )

    $privateHeaderPattern = (
        '(?m)^[ \t]*FUNCTION[ \t]+LMCDiagnosticsService::' +
        [regex]::Escape($FunctionName) + '[ \t]*\r?$')
    if ([regex]::Matches($FunctionBlock, $privateHeaderPattern).Count -ne 1) {
        throw (
            "$Owner diagnostics method split blocker: $FunctionName must " +
            'remain one private implementation.')
    }
    $actualInputs = @(Get-LasalImplementationVariableInventory `
        -FunctionBlock $FunctionBlock -Kind INPUT -Owner $Owner)
    $actualOutputs = @(Get-LasalImplementationVariableInventory `
        -FunctionBlock $FunctionBlock -Kind OUTPUT -Owner $Owner)
    foreach ($comparison in @(
            @{ Kind = 'input'; Actual = $actualInputs; Expected = @($Inputs) },
            @{ Kind = 'output'; Actual = $actualOutputs; Expected = @($Outputs) })) {
        if ($comparison.Actual.Count -ne $comparison.Expected.Count) {
            throw (
                "$Owner diagnostics method split blocker: $FunctionName " +
                "$($comparison.Kind) ABI count is $($comparison.Actual.Count), " +
                "expected $($comparison.Expected.Count).")
        }
        for ($index = 0; $index -lt $comparison.Expected.Count; $index++) {
            if ($comparison.Actual[$index].Name -cne
                    $comparison.Expected[$index].Name -or
                $comparison.Actual[$index].Type -cne
                    $comparison.Expected[$index].Type) {
                throw (
                    "$Owner diagnostics method split blocker: $FunctionName " +
                    "$($comparison.Kind) ABI/order drifted at index $index.")
            }
        }
    }
}

function Assert-LasalDiagnosticsMethodSplitContract {
    param(
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $blocker = "$Owner diagnostics method split blocker:"
    $rawFunctionPattern = (
        '(?ims)^[ \t]*FUNCTION[ \t]+' +
        '(?:(?:VIRTUAL[ \t]+)?GLOBAL[ \t]+)?(?:TAB[ \t]+)?' +
        'LMCDiagnosticsService::' +
        '(?<Name>@?[A-Za-z_][A-Za-z0-9_]*)[ \t]*\r?$' +
        '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
    $rawFunctionBlocks = [regex]::Matches(
        $DiagnosticsText,
        $rawFunctionPattern)
    $rawFunctionHeaders = [regex]::Matches(
        $DiagnosticsText,
        ('(?im)^[ \t]*FUNCTION[ \t]+' +
         '(?:(?:VIRTUAL[ \t]+)?GLOBAL[ \t]+)?(?:TAB[ \t]+)?' +
         'LMCDiagnosticsService::' +
         '(?<Name>@?[A-Za-z_][A-Za-z0-9_]*)[ \t]*\r?$'))
    if ($rawFunctionBlocks.Count -ne $rawFunctionHeaders.Count -or
        $rawFunctionBlocks.Count -lt 20) {
        throw (
            "$blocker complete LMCDiagnosticsService implementation inventory " +
            "is $($rawFunctionBlocks.Count)/$($rawFunctionHeaders.Count), " +
            'expected matching counts of at least twenty.')
    }
    $functionNames = @{}
    foreach ($rawFunctionBlock in $rawFunctionBlocks) {
        $functionName = $rawFunctionBlock.Groups['Name'].Value
        if ($functionNames.ContainsKey($functionName.ToLowerInvariant())) {
            throw "$blocker duplicate implementation name $functionName."
        }
        $functionNames[$functionName.ToLowerInvariant()] = $true
        $rawBytes = [Text.Encoding]::UTF8.GetByteCount(
            $rawFunctionBlock.Value)
        $lfBlock = $rawFunctionBlock.Value.Replace("`r`n", "`n").Replace(
            "`r", "`n")
        $lfBytes = [Text.Encoding]::UTF8.GetByteCount($lfBlock)
        $crlfBytes = [Text.Encoding]::UTF8.GetByteCount(
            $lfBlock.Replace("`n", "`r`n"))
        if ($rawBytes -ge 32768 -or $lfBytes -ge 32768 -or
            $crlfBytes -ge 32768) {
            throw (
                "$blocker $functionName is raw=$rawBytes, LF=$lfBytes, " +
                "CRLF=$crlfBytes UTF-8 bytes; every diagnostics function " +
                'must remain under 32768.')
        }
    }

    $encoderMain = Get-LasalDiagnosticsImplementationBlock `
        -DiagnosticsText $DiagnosticsText `
        -FunctionName 'ProcessEncoderMaintenance' `
        -Owner $Owner
    $encoderHelper = Get-LasalDiagnosticsImplementationBlock `
        -DiagnosticsText $DiagnosticsText `
        -FunctionName 'HandleEncoderMaintenancePreemption' `
        -Owner $Owner
    $ds402Main = Get-LasalDiagnosticsImplementationBlock `
        -DiagnosticsText $DiagnosticsText `
        -FunctionName 'ProcessAxisDs402Home' `
        -Owner $Owner
    $receiptHelper = Get-LasalDiagnosticsImplementationBlock `
        -DiagnosticsText $DiagnosticsText `
        -FunctionName 'HandleAxisDs402HomeReceiptStages' `
        -Owner $Owner
    $cleanupHelper = Get-LasalDiagnosticsImplementationBlock `
        -DiagnosticsText $DiagnosticsText `
        -FunctionName 'HandleAxisDs402HomeCleanupStages' `
        -Owner $Owner

    Assert-LasalDiagnosticsImplementationAbi `
        -FunctionBlock $encoderHelper `
        -FunctionName 'HandleEncoderMaintenancePreemption' `
        -Inputs @(
            @{ Name = 'Stage'; Type = 'DINT' },
            @{ Name = 'PreemptionResult'; Type = 'DINT' },
            @{ Name = 'pPreemptionSnapshot'; Type = '^USINT' },
            @{ Name = 'ServiceNow'; Type = 'UDINT' }) `
        -Outputs @(@{ Name = 'Result'; Type = 'DINT' }) `
        -Owner $Owner
    Assert-LasalDiagnosticsImplementationAbi `
        -FunctionBlock $receiptHelper `
        -FunctionName 'HandleAxisDs402HomeReceiptStages' `
        -Inputs @(@{ Name = 'Stage'; Type = 'DINT' }) `
        -Outputs @(@{ Name = 'Result'; Type = 'DINT' }) `
        -Owner $Owner
    Assert-LasalDiagnosticsImplementationAbi `
        -FunctionBlock $cleanupHelper `
        -FunctionName 'HandleAxisDs402HomeCleanupStages' `
        -Inputs @(
            @{ Name = 'Stage'; Type = 'DINT' },
            @{ Name = 'AxisReference'; Type = 'UINT' },
            @{ Name = 'AxisMask'; Type = 'UDINT' },
            @{ Name = 'AdmissionToken'; Type = 'UDINT' },
            @{ Name = 'OwnerGeneration'; Type = 'UDINT' },
            @{ Name = 'Ds402ProcessOwnerSessionEpoch'; Type = 'UDINT' },
            @{ Name = 'OwnerRequestSequence'; Type = 'UDINT' },
            @{ Name = 'SafetyAdmissionToken'; Type = 'UDINT' },
            @{ Name = 'SafetyOwnerGeneration'; Type = 'UDINT' },
            @{ Name = 'InitialCurrentCycle'; Type = 'UDINT' },
            @{ Name = 'ServiceNow'; Type = 'UDINT' },
            @{ Name = 'ActualPosition'; Type = 'DINT' },
            @{ Name = 'PreemptionCleanup'; Type = 'BOOL' }) `
        -Outputs @() `
        -Owner $Owner

    $encoderMainScan = Get-LasalScanText $encoderMain
    $encoderHelperScan = Get-LasalScanText $encoderHelper
    $ds402MainScan = Get-LasalScanText $ds402Main
    $receiptHelperScan = Get-LasalScanText $receiptHelper
    $cleanupHelperScan = Get-LasalScanText $cleanupHelper

    Assert-Match $encoderHelperScan (
        '(?is)END_VAR\s*Result\s*:=\s*1\s*;') (
        "$blocker encoder helper must enter fail-closed pending state.")
    Assert-Match $receiptHelperScan (
        '(?is)END_VAR\s*Result\s*:=\s*1\s*;') (
        "$blocker receipt helper must consume stages by default.")
    Assert-Match $receiptHelperScan (
        '(?is)Result\s*:=\s*0\s*;\s*END_FUNCTION\s*\z') (
        "$blocker receipt helper must release only its final normal path.")

    $encoderCall = (
        'preemptionResult\s*:=\s*HandleEncoderMaintenancePreemption\(\s*' +
        'Stage\s*:=\s*stage\s*,\s*' +
        'PreemptionResult\s*:=\s*preemptionResult\s*,\s*' +
        'pPreemptionSnapshot\s*:=\s*#preemptionSnapshot\[0\]\s*,\s*' +
        'ServiceNow\s*:=\s*serviceNow\s*\)\s*;')
    if ([regex]::Matches(
            $encoderMainScan,
            '(?is)' + $encoderCall).Count -ne 1 -or
        [regex]::Matches(
            $encoderMainScan,
            '(?i)HandleEncoderMaintenancePreemption\s*\(').Count -ne 1) {
        throw "$blocker encoder helper call ABI is not exact and unique."
    }
    Assert-Match $encoderMainScan (
        '(?is)' + $encoderCall + '\s*' +
        'if\s+preemptionResult\s*<>\s*0\s+then\s*RETURN\s*;\s*end_if\s*;\s*' +
        'if\s+stage\s*=\s*LMC_DIAG_ENCODER_STAGE_QUARANTINED\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'EncoderMaintenanceServiceMilliseconds\s*:=\s*serviceNow\s*;') (
        "$blocker encoder helper result/quarantine/service-clock fence drifted.")

    Assert-Match $ds402MainScan (
        '(?is)stage\s*:=\s*Ds402HomeState\[92\]\s*;\s*' +
        'receiptResult\s*:=\s*HandleAxisDs402HomeReceiptStages\(\s*' +
        'Stage\s*:=\s*stage\s*\)\s*;\s*' +
        'if\s+receiptResult\s*<>\s*0\s+then\s*RETURN\s*;\s*end_if\s*;\s*' +
        'activeIndex\s*:=\s*Ds402HomeState\[93\]\s*;') (
        "$blocker DS402 receipt helper must be the first exact guarded stage consumer.")
    if ([regex]::Matches(
            $ds402MainScan,
            '(?i)HandleAxisDs402HomeReceiptStages\s*\(').Count -ne 1) {
        throw "$blocker DS402 receipt helper call count must be one."
    }

    $cleanupCallPrefix = (
        'HandleAxisDs402HomeCleanupStages\(\s*' +
        'Stage\s*:=\s*stage\s*,\s*' +
        'AxisReference\s*:=\s*axisReference\s*,\s*' +
        'AxisMask\s*:=\s*axisMask\s*,\s*' +
        'AdmissionToken\s*:=\s*admissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*ownerGeneration\s*,\s*' +
        'Ds402ProcessOwnerSessionEpoch\s*:=\s*' +
        'ds402ProcessOwnerSessionEpoch\s*,\s*' +
        'OwnerRequestSequence\s*:=\s*ownerRequestSequence\s*,\s*')
    $cleanupCallSuffix = (
        'InitialCurrentCycle\s*:=\s*currentCycle\s*,\s*' +
        'ServiceNow\s*:=\s*serviceNow\s*,\s*' +
        'ActualPosition\s*:=\s*actualPosition\s*,\s*')
    $cleanupTrueCall = (
        $cleanupCallPrefix +
        'SafetyAdmissionToken\s*:=\s*safetyAdmissionToken\s*,\s*' +
        'SafetyOwnerGeneration\s*:=\s*safetyOwnerGeneration\s*,\s*' +
        $cleanupCallSuffix + 'PreemptionCleanup\s*:=\s*TRUE\s*\)\s*;')
    $cleanupFalseCall = (
        $cleanupCallPrefix +
        'SafetyAdmissionToken\s*:=\s*0\s*,\s*' +
        'SafetyOwnerGeneration\s*:=\s*0\s*,\s*' +
        $cleanupCallSuffix + 'PreemptionCleanup\s*:=\s*FALSE\s*\)\s*;')
    Assert-Match $ds402MainScan (
        '(?is)stage\s*:=\s*Ds402HomeState\[92\]\s*;\s*' +
        'if\s+stage\s*<\s*90\s+then\s*RETURN\s*;\s*end_if\s*;\s*' +
        'if\s+preemptionCleanup\s+then\s*' + $cleanupTrueCall + '\s*' +
        'else\s*' + $cleanupFalseCall + '\s*end_if\s*;') (
        "$blocker cleanup dispatch must preserve exact TRUE/FALSE token provenance.")
    if ([regex]::Matches(
            $ds402MainScan,
            '(?i)HandleAxisDs402HomeCleanupStages\s*\(').Count -ne 2) {
        throw "$blocker cleanup helper call count must be exactly two."
    }

    foreach ($samplingContract in @(
            @{ Name = 'encoder main ops.tAbsolute'; Block = $encoderMainScan;
                Pattern = '\bops\.tAbsolute\b'; Count = 1 },
            @{ Name = 'encoder main preemption copy'; Block = $encoderMainScan;
                Pattern = 'CopyAxisOwnershipPreemption\s*\('; Count = 1 },
            @{ Name = 'encoder main latch snapshot'; Block = $encoderMainScan;
                Pattern = 'InputLatch\.CopySnapshot\s*\('; Count = 1 },
            @{ Name = 'DS402 main ops.tAbsolute'; Block = $ds402MainScan;
                Pattern = '\bops\.tAbsolute\b'; Count = 2 },
            @{ Name = 'DS402 main preemption copy'; Block = $ds402MainScan;
                Pattern = 'CopyAxisOwnershipPreemption\s*\('; Count = 1 },
            @{ Name = 'DS402 main latch snapshot'; Block = $ds402MainScan;
                Pattern = 'InputLatch\.CopySnapshot\s*\('; Count = 1 })) {
        $actualCount = [regex]::Matches(
            $samplingContract.Block,
            '(?i)' + $samplingContract.Pattern).Count
        if ($actualCount -ne $samplingContract.Count) {
            throw (
                "$blocker $($samplingContract.Name) count is $actualCount, " +
                "expected $($samplingContract.Count).")
        }
    }
    foreach ($helperSamplingContract in @(
            @{ Name = 'encoder helper'; Block = $encoderHelperScan;
                Patterns = @('\bops\.tAbsolute\b',
                    'CopyAxisOwnershipPreemption\s*\(',
                    'InputLatch\.CopySnapshot\s*\(', '\.TryStart(?:Read|Write)\s*\(',
                    'ValidateAxisOwnership\s*\(',
                    'AxisOwnership\.PublishAxisOwnership\s*\(') },
            @{ Name = 'receipt helper'; Block = $receiptHelperScan;
                Patterns = @('\bops\.tAbsolute\b',
                    'CopyAxisOwnershipPreemption\s*\(', '\bInputLatch\.',
                    '\bSdoAxis[1-4]\.', '\.TryStart(?:Read|Write)\s*\(',
                    '\.CopyCompletion\s*\(', '\.MarkOrphan\s*\(') },
            @{ Name = 'cleanup helper'; Block = $cleanupHelperScan;
                Patterns = @('\bops\.tAbsolute\b',
                    'CopyAxisOwnershipPreemption\s*\(',
                    'InputLatch\.CopySnapshot\s*\(') })) {
        foreach ($forbiddenSampling in $helperSamplingContract.Patterns) {
            if ($helperSamplingContract.Block -match
                    ('(?i)' + $forbiddenSampling)) {
                throw (
                    "$blocker $($helperSamplingContract.Name) re-samples or " +
                    'relocates forbidden live evidence.')
            }
        }
    }
    Assert-Match $cleanupHelperScan (
        '(?is)END_VAR\s*currentCycle\s*:=\s*InitialCurrentCycle\s*;') (
        "$blocker cleanup helper must start from the passed InitialCurrentCycle.")

    foreach ($phaseInventory in @(
            @{ Name = 'DS402 main'; Block = $ds402MainScan;
                Count = 1; Active = 1; Reserved = 0 },
            @{ Name = 'receipt helper'; Block = $receiptHelperScan;
                Count = 3; Active = 2; Reserved = 1 },
            @{ Name = 'cleanup helper'; Block = $cleanupHelperScan;
                Count = 2; Active = 2; Reserved = 0 })) {
        $broadPhaseCalls = [regex]::Matches(
            $phaseInventory.Block,
            '(?i)AxisOwnership\.ValidateAxisOwnership\s*\(').Count
        $activePhaseCalls = [regex]::Matches(
            $phaseInventory.Block,
            ('(?is)AxisOwnership\.ValidateAxisOwnership\s*\(.*?' +
             'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)')).Count
        $reservedPhaseCalls = [regex]::Matches(
            $phaseInventory.Block,
            ('(?is)AxisOwnership\.ValidateAxisOwnership\s*\(.*?' +
             'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_RESERVED\s*\)')).Count
        if ($broadPhaseCalls -ne $phaseInventory.Count -or
            $activePhaseCalls -ne $phaseInventory.Active -or
            $reservedPhaseCalls -ne $phaseInventory.Reserved) {
            throw (
                "$blocker $($phaseInventory.Name) phase fence inventory is " +
                "ACTIVE=$activePhaseCalls RESERVED=$reservedPhaseCalls " +
                "broad=$broadPhaseCalls, expected $($phaseInventory.Active)/" +
                "$($phaseInventory.Reserved)/$($phaseInventory.Count).")
        }
    }
    $cleanupOrdinaryGuards = [regex]::Matches(
        $cleanupHelperScan,
        ('(?is)if\s+IsClientConnected\(#AxisOwnership\)\s*&\s*' +
         '\(preemptionCleanup\s*=\s*FALSE\)\s+then\s*' +
         'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnership\s*\(.*?' +
         'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;\s*' +
         'end_if\s*;'))
    if ($cleanupOrdinaryGuards.Count -ne 2) {
        throw (
            "$blocker cleanup ACTIVE validation must occur exactly twice " +
            'behind the ordinary non-preemption guard.')
    }
}

function Invoke-LasalDiagnosticsMethodSplitVerifierSelfTest {
    $fixturePath = Join-Path $PSScriptRoot (
        'Verify-LasalDiagnosticsMethodSplit.Fixture.ps1')
    if (-not (Test-Path -LiteralPath $fixturePath -PathType Leaf)) {
        throw "Diagnostics method split verifier fixture is missing: $fixturePath"
    }
    $fixture = & $fixturePath -RepositoryRoot $RepositoryRoot
    if ($null -eq $fixture -or
        [string]::IsNullOrWhiteSpace($fixture.Diagnostics) -or
        $null -eq $fixture.NegativeFixtures) {
        throw 'Diagnostics method split verifier fixture is incomplete.'
    }
    Assert-LasalDiagnosticsMethodSplitContract `
        -DiagnosticsText $fixture.Diagnostics `
        -Owner 'diagnostics method split self-test'
    $negativeFixtures = @($fixture.NegativeFixtures)
    if ($negativeFixtures.Count -lt 16 -or $negativeFixtures.Count -gt 32) {
        throw (
            'Diagnostics method split negative fixture count is ' +
            "$($negativeFixtures.Count), expected 16..32 bounded mutations.")
    }
    $rejected = 0
    foreach ($negativeFixture in $negativeFixtures) {
        if ($null -eq $negativeFixture -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Name) -or
            [string]::IsNullOrWhiteSpace($negativeFixture.Diagnostics) -or
            $negativeFixture.Diagnostics -ceq $fixture.Diagnostics) {
            throw 'Diagnostics method split negative fixture is incomplete or unchanged.'
        }
        try {
            Assert-LasalDiagnosticsMethodSplitContract `
                -DiagnosticsText $negativeFixture.Diagnostics `
                -Owner "diagnostics method split negative '$($negativeFixture.Name)'"
        }
        catch {
            if ($_.Exception.Message -notmatch
                    'diagnostics method split blocker:') {
                throw
            }
            $rejected++
            continue
        }
        throw (
            'Diagnostics method split verifier accepted negative fixture ' +
            "'$($negativeFixture.Name)'.")
    }
    return $rejected
}

function Assert-DiagnosticsCapabilityWriteInventory {
    param(
        [string]$CapabilitiesBlock,
        [string]$ExpectedBootZeroCapabilities,
        [string]$ExpectedStableCapabilities,
        [string]$Owner
    )

    $scanText = Get-LasalScanText $CapabilitiesBlock
    $target = '\(pResponse\s*\+\s*20\)\^\$UDINT'
    $writes = [regex]::Matches(
        $scanText,
        ($target + '\s*:=\s*(?<Rhs>[^;]+);'))
    if ($writes.Count -ne 5) {
        throw (
            "$Owner capability-mask write count is $($writes.Count), " +
            'expected exactly five.')
    }

    $normalizedRightSides = @($writes | ForEach-Object {
            [regex]::Replace($_.Groups['Rhs'].Value, '\s+', '')
        })
    $expectedRightSides = @(
        [regex]::Replace($ExpectedBootZeroCapabilities, '\s+', ''),
        [regex]::Replace($ExpectedStableCapabilities, '\s+', ''),
        '(pResponse+20)^$UDINTOR0x00000200',
        '(pResponse+20)^$UDINTOR0x00040000',
        '(pResponse+20)^$UDINTOR0x00080000')
    foreach ($expectedRightSide in $expectedRightSides) {
        if (@($normalizedRightSides | Where-Object {
                    $_ -ceq $expectedRightSide
                }).Count -ne 1) {
            throw (
                "$Owner capability-mask RHS '$expectedRightSide' must occur " +
                'exactly once.')
        }
    }
}

function Assert-TCPMotionInterfaceFreshOwnerReset {
    param(
        [string]$TcpText,
        [string]$Owner
    )

    $scanText = Get-LasalScanText $TcpText
    $connSocketInfoMatches = [regex]::Matches(
        $scanText,
        ('(?ims)^[ \t]*FUNCTION[ \t]+VIRTUAL[ \t]+GLOBAL[ \t]+' +
         'TCPMotionInterface::ConnSocketInfo[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    if ($connSocketInfoMatches.Count -ne 1) {
        throw "$Owner ConnSocketInfo implementation was not found exactly once."
    }

    $connectBranchMatches = [regex]::Matches(
        $connSocketInfoMatches[0].Value,
        ('(?is)TCP_SVR_SOCK_INFO_CONNECT\s*:' +
         '(?<Body>.*?)TCP_SVR_SOCK_INFO_DISCONNECT\s*:'))
    if ($connectBranchMatches.Count -ne 1) {
        throw "$Owner CONNECT branch was not found exactly once."
    }

    if ($scanText -notmatch
        '(?i)(?<![A-Za-z0-9_])TCPMI_QUEUE_FREE\s*:=\s*0') {
        throw "$Owner queue zeroing is unsafe because TCPMI_QUEUE_FREE is not zero."
    }

    $freshOwnerMatch = [regex]::Match(
        $connectBranchMatches[0].Groups['Body'].Value,
        ('(?is)(?<Body>' +
         '(?<![A-Za-z0-9_])ActiveRequestValid\s*:=\s*FALSE\s*;' +
         '.*?' +
         '(?<![A-Za-z0-9_])CurrentSock\s*:=\s*dSock\s*;)'))
    if (-not $freshOwnerMatch.Success) {
        throw "$Owner fresh-owner reset-and-publish block was not found."
    }
    $connectCurrentPublishCount = [regex]::Matches(
        $connectBranchMatches[0].Groups['Body'].Value,
        '(?i)(?<![A-Za-z0-9_])CurrentSock\s*:=\s*dSock\s*;').Count
    if ($connectCurrentPublishCount -ne 1) {
        throw (
            "$Owner CONNECT CurrentSock publish count is " +
            "$connectCurrentPublishCount, expected one post-reset publish.")
    }
    $freshOwnerBody = $freshOwnerMatch.Groups['Body'].Value

    $orderedStatements = [ordered]@{
        ActiveRequestInvalid =
            '(?i)(?<![A-Za-z0-9_])ActiveRequestValid\s*:=\s*FALSE\s*;'
        RequestQueueZero =
            ('(?i)_memset\s*\(\s*dest\s*:=\s*#\s*RequestQueue\s*' +
             '\[\s*0\s*\]\s*,\s*usByte\s*:=\s*0\s*,\s*' +
             'cntr\s*:=\s*sizeof\s*\(\s*RequestQueue\s*\)\s*\)\s*;')
        QueueWriteIndexZero =
            '(?i)(?<![A-Za-z0-9_])QueueWriteIndex\s*:=\s*0\s*;'
        QueueReadIndexZero =
            '(?i)(?<![A-Za-z0-9_])QueueReadIndex\s*:=\s*0\s*;'
        ActiveRequestPreserveOrZero =
            ('(?is)(?<![A-Za-z0-9_])preservePendingActive\s*:=\s*' +
             '.*?;\s*if\s+preservePendingActive\s*=\s*FALSE\s+then\s*' +
             '_memset\s*\(\s*dest\s*:=\s*#\s*ActiveRequest\s*,' +
             '\s*usByte\s*:=\s*0\s*,\s*cntr\s*:=\s*sizeof\s*\(' +
             '\s*ActiveRequest\s*\)\s*\)\s*;\s*end_if\s*;')
        RequestBufferZero =
            ('(?i)_memset\s*\(\s*dest\s*:=\s*#\s*RequestBuf\s*,' +
             '\s*usByte\s*:=\s*0\s*,\s*cntr\s*:=\s*sizeof\s*\(' +
             '\s*RequestBuf\s*\)\s*\)\s*;')
        CommandIdZero =
            '(?i)(?<![A-Za-z0-9_])CommandID\s*:=\s*0\s*;'
        AxisReferenceZero =
            '(?i)(?<![A-Za-z0-9_])AxisRef\s*:=\s*0\s*;'
        PayloadZero =
            '(?i)(?<![A-Za-z0-9_])Payload\s*:=\s*0\s*;'
        ReceiveFillZero =
            '(?i)(?<![A-Za-z0-9_])ReceiveFill\s*:=\s*0\s*;'
        ReceiveSocketZero =
            '(?i)(?<![A-Za-z0-9_])ReceiveSocket\s*:=\s*0\s*;'
        ReceiveBufferZero =
            ('(?i)_memset\s*\(\s*dest\s*:=\s*#\s*ReceiveBuf\s*,' +
             '\s*usByte\s*:=\s*0\s*,\s*cntr\s*:=\s*sizeof\s*\(' +
             '\s*ReceiveBuf\s*\)\s*\)\s*;')
        RpcSocketZero =
            '(?i)(?<![A-Za-z0-9_])RpcSocket\s*:=\s*0\s*;'
        RpcInitializedFalse =
            '(?i)(?<![A-Za-z0-9_])RpcInitialized\s*:=\s*FALSE\s*;'
        RpcCallbackRegisteredFalse =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackRegistered\s*:=\s*FALSE\s*;'
        RpcCallbackEventMaskZero =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackEventMask\s*:=\s*0\s*;'
        RpcCallbackPortZero =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackPort\s*:=\s*0\s*;'
        RpcCallbackIPv4_0 =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackIPv4\s*\[\s*0\s*\]\s*:=\s*0\s*;'
        RpcCallbackIPv4_1 =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackIPv4\s*\[\s*1\s*\]\s*:=\s*0\s*;'
        RpcCallbackIPv4_2 =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackIPv4\s*\[\s*2\s*\]\s*:=\s*0\s*;'
        RpcCallbackIPv4_3 =
            '(?i)(?<![A-Za-z0-9_])RpcCallbackIPv4\s*\[\s*3\s*\]\s*:=\s*0\s*;'
        IngressFaultPendingFalse =
            '(?i)(?<![A-Za-z0-9_])IngressFaultPending\s*:=\s*FALSE\s*;'
        IngressBlockedFalse =
            '(?i)(?<![A-Za-z0-9_])IngressBlocked\s*:=\s*FALSE\s*;'
        IngressFaultCloseRequiredFalse =
            '(?i)(?<![A-Za-z0-9_])IngressFaultCloseRequired\s*:=\s*FALSE\s*;'
        IngressFaultSocketZero =
            '(?i)(?<![A-Za-z0-9_])IngressFaultSocket\s*:=\s*0\s*;'
        IngressFaultEpochZero =
            '(?i)(?<![A-Za-z0-9_])IngressFaultEpoch\s*:=\s*0\s*;'
        IngressFaultErrorZero =
            '(?i)(?<![A-Za-z0-9_])IngressFaultError\s*:=\s*0\s*;'
        IngressDiscardRemainingZero =
            '(?i)(?<![A-Za-z0-9_])IngressDiscardRemaining\s*:=\s*0\s*;'
        IngressDiscardSocketZero =
            '(?i)(?<![A-Za-z0-9_])IngressDiscardSocket\s*:=\s*0\s*;'
        SessionEpochAdvanceAndWrap =
            ('(?is)(?<![A-Za-z0-9_])SessionEpoch\s*\+=\s*1\s*;' +
             '\s*(?<![A-Za-z0-9_])if\s+SessionEpoch\s*=\s*0\s+then' +
             '\s*(?<![A-Za-z0-9_])SessionEpoch\s*:=\s*1\s*;' +
             '\s*(?<![A-Za-z0-9_])end_if\s*;')
        CurrentSocketPublish =
            '(?i)(?<![A-Za-z0-9_])CurrentSock\s*:=\s*dSock\s*;'
    }

    $lastStatementIndex = -1
    foreach ($statement in $orderedStatements.GetEnumerator()) {
        $matches = [regex]::Matches($freshOwnerBody, $statement.Value)
        if ($matches.Count -ne 1) {
            throw (
                "$Owner fresh-owner reset '$($statement.Key)' must occur " +
                "exactly once; found $($matches.Count).")
        }
        if ($matches[0].Index -le $lastStatementIndex) {
            throw (
                "$Owner fresh-owner reset '$($statement.Key)' is out of " +
                'canonical order.')
        }
        $lastStatementIndex = $matches[0].Index
    }

    $bodyWithoutCanonicalControlFlow =
        ([regex]::new($orderedStatements['ActiveRequestPreserveOrZero'])).Replace(
            $freshOwnerBody,
            '',
            1)
    $bodyWithoutCanonicalControlFlow =
        ([regex]::new($orderedStatements['SessionEpochAdvanceAndWrap'])).Replace(
            $bodyWithoutCanonicalControlFlow,
            '',
            1)
    $unexpectedControlFlowPattern = (
        '(?i)(?<![A-Za-z0-9_])(?:IF|THEN|ELSIF|ELSE|END_IF|' +
        'CASE|OF|END_CASE|FOR|TO|BY|DO|END_FOR|WHILE|END_WHILE|' +
        'REPEAT|UNTIL|END_REPEAT|RETURN|EXIT|CONTINUE|GOTO|JMP)' +
        '(?![A-Za-z0-9_])')
    $unexpectedControlFlow = [regex]::Match(
        $bodyWithoutCanonicalControlFlow,
        $unexpectedControlFlowPattern)
    if ($unexpectedControlFlow.Success) {
        throw (
            "$Owner fresh-owner reset contains non-canonical control flow " +
            "'$($unexpectedControlFlow.Value)'.")
    }

    $unexpectedExecutableBody = $freshOwnerBody
    foreach ($statement in $orderedStatements.GetEnumerator()) {
        $unexpectedExecutableBody =
            ([regex]::new($statement.Value)).Replace(
                $unexpectedExecutableBody,
                '',
                1)
    }
    if (-not [string]::IsNullOrWhiteSpace($unexpectedExecutableBody)) {
        throw (
            "$Owner fresh-owner reset contains an unexpected executable " +
            'statement outside the exact allowed inventory.')
    }

    if ($freshOwnerBody -notmatch
        '(?is)CurrentSock\s*:=\s*dSock\s*;\s*$') {
        throw "$Owner must publish CurrentSock only after the complete reset."
    }
    if ($freshOwnerBody -match
        ('(?i)(?<![A-Za-z0-9_])PendingClosedSessionEpoch\s*' +
         '(?::=|\+=|-=|\*=|/=|&=|\|=|\^=|\+\+|--)')) {
        throw (
            "$Owner must preserve PendingClosedSessionEpoch until CyWork " +
            'notifies Diagnostics.')
    }
}

function Assert-TCPMotionInterfaceCallbackEndpointOwnership {
    param(
        [string]$TcpText,
        [string]$Owner
    )

    $rawMsgParserMatches = [regex]::Matches(
        $TcpText,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'TCPMotionInterface::MsgPaser[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    $rawHelperMatches = [regex]::Matches(
        $TcpText,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'TCPMotionInterface::HandleRpcLifecycleCommands[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    if ($rawMsgParserMatches.Count -ne 1) {
        throw "$Owner MsgPaser implementation was not found exactly once."
    }
    if ($rawHelperMatches.Count -ne 1 -or
        $TcpText -match (
            '(?im)^[ \t]*FUNCTION[ \t]+GLOBAL[ \t]+' +
            'TCPMotionInterface::HandleRpcLifecycleCommands\b')) {
        throw "$Owner RPC lifecycle helper must have one private implementation."
    }
    foreach ($sizeEntry in @(
            @{ Name = 'MsgPaser'; Block = $rawMsgParserMatches[0].Value },
            @{ Name = 'HandleRpcLifecycleCommands';
                Block = $rawHelperMatches[0].Value })) {
        $rawBytes = [Text.Encoding]::UTF8.GetByteCount($sizeEntry.Block)
        $lfBlock = $sizeEntry.Block.Replace("`r`n", "`n").Replace("`r", "`n")
        $lfBytes = [Text.Encoding]::UTF8.GetByteCount($lfBlock)
        $crlfBytes = [Text.Encoding]::UTF8.GetByteCount(
            $lfBlock.Replace("`n", "`r`n"))
        if ($rawBytes -gt 32768 -or
            $lfBytes -gt 32768 -or
            $crlfBytes -gt 32768) {
            throw (
                "$Owner $($sizeEntry.Name) is raw=$rawBytes, LF=$lfBytes, " +
                "CRLF=$crlfBytes UTF-8 bytes; all must be at most 32768.")
        }
    }

    $scanText = Get-LasalScanText $TcpText
    $msgParserBlock = [regex]::Match(
        $scanText,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'TCPMotionInterface::MsgPaser[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')).Value
    $helperBlock = [regex]::Match(
        $scanText,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'TCPMotionInterface::HandleRpcLifecycleCommands[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')).Value
    if ($helperBlock -match '(?i)\bVAR_(?:INPUT|OUTPUT)\b') {
        throw "$Owner RPC lifecycle helper must have no VAR_INPUT or VAR_OUTPUT ABI."
    }
    $helperVarMatch = [regex]::Match(
        $helperBlock,
        ('(?ims)\AFUNCTION[ \t]+' +
         'TCPMotionInterface::HandleRpcLifecycleCommands[ \t]*\r?\n' +
         '[ \t]*VAR[ \t]*\r?\n(?<Body>.*?)' +
         '^[ \t]*END_VAR[ \t]*\r?$'))
    if (-not $helperVarMatch.Success) {
        throw "$Owner RPC lifecycle helper local declaration block was not found."
    }
    $helperLocals = @([regex]::Matches(
        $helperVarMatch.Groups['Body'].Value,
        '(?im)^[ \t]*(?<Name>[A-Za-z][A-Za-z0-9_]*)[ \t]*:[ \t]*' +
        '(?<Type>[A-Za-z][A-Za-z0-9_]*)[ \t]*;[ \t]*\r?$') |
        ForEach-Object {
            $_.Groups['Name'].Value + ':' + $_.Groups['Type'].Value
        })
    $expectedHelperLocals = @(
        'callbackEventMask:UDINT',
        'callbackPort:DINT',
        'callbackIPv4:UDINT')
    if ([string]::Join('|', $helperLocals) -cne
        [string]::Join('|', $expectedHelperLocals)) {
        throw "$Owner RPC lifecycle helper local declaration inventory drifted."
    }
    if ($msgParserBlock -match
        '(?i)\b(?:callbackEventMask|callbackPort|callbackIPv4)\s*:') {
        throw "$Owner callback scratch declarations must remain helper-private."
    }

    $aggregateRouteMatches = [regex]::Matches(
        $msgParserBlock,
        ('(?im)^[ \t]*0x8080[ \t]*,[ \t]*0x405C[ \t]*,[ \t]*' +
         '0x405D[ \t]*:[ \t]*HandleRpcLifecycleCommands\(\)[ \t]*;[ \t]*\r?$'))
    if ($aggregateRouteMatches.Count -ne 1 -or
        [regex]::Matches(
            $msgParserBlock,
            '(?i)\bHandleRpcLifecycleCommands\s*\(').Count -ne 1 -or
        [regex]::Matches(
            $scanText,
            '(?i)\bHandleRpcLifecycleCommands\s*\(').Count -ne 1 -or
        $msgParserBlock -match
            '(?im)^[ \t]*0x(?:8080|405C|405D)[ \t]*:[ \t]*') {
        throw (
            "$Owner MsgPaser must route 0x8080/0x405C/0x405D through " +
            'one exact aggregate helper call.')
    }

    $helperCaseMatch = [regex]::Match(
        $helperBlock,
        '(?is)\bcase\s+CommandID\s+of(?<Body>.*?)\bend_case\s*;')
    if (-not $helperCaseMatch.Success -or
        [regex]::Matches(
            $helperBlock,
            '(?i)\bcase\s+CommandID\s+of').Count -ne 1 -or
        [regex]::Matches(
            $helperBlock,
            '(?i)\bend_case\s*;').Count -ne 1) {
        throw "$Owner RPC lifecycle helper must contain one exact CommandID case."
    }
    $helperCaseBody = $helperCaseMatch.Groups['Body'].Value
    $helperCaseLabels = @([regex]::Matches(
        $helperCaseBody,
        '(?im)^[ \t]*0x(?<Id>[0-9A-F]{4})[ \t]*:[ \t]*\r?$') |
        ForEach-Object { $_.Groups['Id'].Value.ToUpperInvariant() })
    if ([string]::Join('|', $helperCaseLabels) -cne '8080|405C|405D') {
        throw (
            "$Owner RPC lifecycle helper case IDs are " +
            "$([string]::Join(',', $helperCaseLabels)); expected 8080,405C,405D.")
    }
    $initCaseMatches = [regex]::Matches(
        $helperCaseBody,
        ('(?ims)^[ \t]*0x8080[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)' +
         '(?=^[ \t]*0x405C[ \t]*:[ \t]*\r?$)'))
    $callbackCaseMatches = [regex]::Matches(
        $helperCaseBody,
        ('(?ims)^[ \t]*0x405C[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)' +
         '(?=^[ \t]*0x405D[ \t]*:[ \t]*\r?$)'))
    $closeCaseMatches = [regex]::Matches(
        $helperCaseBody,
        ('(?ims)^[ \t]*0x405D[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)\z'))
    if ($initCaseMatches.Count -ne 1 -or
        $callbackCaseMatches.Count -ne 1 -or
        $closeCaseMatches.Count -ne 1) {
        throw "$Owner exact RPC lifecycle helper arms were not found once each."
    }
    $initCaseBlock = $initCaseMatches[0].Groups['Body'].Value
    if ($callbackCaseMatches.Count -ne 1) {
        throw "$Owner 0x405C callback-registration case was not found exactly once."
    }
    $callbackCaseBlock = $callbackCaseMatches[0].Groups['Body'].Value
    $closeCaseBlock = $closeCaseMatches[0].Groups['Body'].Value

    Assert-Match $initCaseBlock (
        '(?is)\A\s*' +
        '_memset\(dest:=#Sendbuf,\s*usByte:=0,\s*' +
        'cntr:=sizeof\(Sendbuf\)\);\s*' +
        'if\s+\(Payload\s*=\s*1\)\s*&\s*' +
        '\(RequestBuf\[8\]\s*=\s*0\)\s*&\s*' +
        '\(\(RpcInitialized\s*=\s*FALSE\)\s*\|\s*' +
        '\(RpcSocket\s*=\s*CurrentSock\)\)\s+then\s*' +
        'RpcSocket\s*:=\s*CurrentSock;\s*' +
        'RpcInitialized\s*:=\s*TRUE;\s*' +
        'RpcCallbackRegistered\s*:=\s*FALSE;\s*' +
        'RpcCallbackEventMask\s*:=\s*0;\s*' +
        'RpcCallbackPort\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[0\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[1\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[2\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[3\]\s*:=\s*0;\s*' +
        'Sendbuf\[0\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[2\]\$UINT\s*:=\s*24;\s*' +
        'Sendbuf\[4\]\$UDINT\s*:=\s*0;\s*' +
        'Sendbuf\[8\]\$UDINT\s*:=\s*64;\s*' +
        'SendData\(\s*pData:=#Sendbuf\[0\],\s*udSize:=32,\s*' +
        'dSocket:=CurrentSock,\s*bDirect:=TRUE\s*\);\s*' +
        'else\s*' +
        'Sendbuf\[0\]\$UINT\s*:=\s*1;\s*' +
        'Sendbuf\[2\]\$UINT\s*:=\s*4;\s*' +
        'Sendbuf\[4\]\$UDINT\s*:=\s*0;\s*' +
        'Sendbuf\[8\]\$UINT\s*:=\s*1;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*-1;\s*' +
        'SendData\(\s*pData:=#Sendbuf\[0\],\s*udSize:=12,\s*' +
        'dSocket:=CurrentSock,\s*bDirect:=TRUE\s*\);\s*' +
        'end_if;\s*\z') (
        "$Owner 0x8080 RPC initialization arm drifted.")

    Assert-Match $closeCaseBlock (
        '(?is)\A\s*' +
        '_memset\(dest:=#Sendbuf,\s*usByte:=0,\s*' +
        'cntr:=sizeof\(Sendbuf\)\);\s*' +
        'Sendbuf\[0\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[2\]\$UINT\s*:=\s*4;\s*' +
        'Sendbuf\[4\]\$UDINT\s*:=\s*0;\s*' +
        'if\s+\(Payload\s*=\s*1\)\s*&\s*' +
        '\(RpcInitialized\s*=\s*TRUE\)\s*&\s*' +
        '\(RpcSocket\s*=\s*CurrentSock\)\s+then\s*' +
        'Sendbuf\[8\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*0;\s*' +
        'SendData\(\s*pData:=#Sendbuf\[0\],\s*udSize:=12,\s*' +
        'dSocket:=CurrentSock,\s*bDirect:=TRUE\s*\);\s*' +
        'RpcSocket\s*:=\s*0;\s*' +
        'RpcInitialized\s*:=\s*FALSE;\s*' +
        'RpcCallbackRegistered\s*:=\s*FALSE;\s*' +
        'RpcCallbackEventMask\s*:=\s*0;\s*' +
        'RpcCallbackPort\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[0\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[1\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[2\]\s*:=\s*0;\s*' +
        'RpcCallbackIPv4\[3\]\s*:=\s*0;\s*' +
        'if\s+\(SessionEpoch\s*<>\s*0\)\s*&\s*' +
        '\(PendingClosedSessionEpoch\s*=\s*0\)\s+then\s*' +
        'PendingClosedSessionEpoch\s*:=\s*SessionEpoch;\s*end_if;\s*' +
        'SessionEpoch\s*\+=\s*1;\s*' +
        'if\s+SessionEpoch\s*=\s*0\s+then\s*' +
        'SessionEpoch\s*:=\s*1;\s*end_if;\s*' +
        'else\s*' +
        'Sendbuf\[8\]\$UINT\s*:=\s*1;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*-1;\s*' +
        'SendData\(\s*pData:=#Sendbuf\[0\],\s*udSize:=12,\s*' +
        'dSocket:=CurrentSock,\s*bDirect:=TRUE\s*\);\s*' +
        'end_if;\s*\z') (
        "$Owner 0x405D RPC close arm drifted.")

    $ownershipFlowPattern = (
        '(?is)\A\s*' +
        '_memset\(dest:=#Sendbuf,\s*usByte:=0,\s*' +
        'cntr:=sizeof\(Sendbuf\)\);\s*' +
        'Sendbuf\[0\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[2\]\$UINT\s*:=\s*4;\s*' +
        'Sendbuf\[4\]\$UDINT\s*:=\s*0;\s*' +
        'callbackEventMask\s*:=\s*0;\s*' +
        'callbackPort\s*:=\s*0;\s*' +
        'callbackIPv4\s*:=\s*0;\s*' +
        'if\s+\(Payload\s*=\s*12\)\s*&\s*' +
        '\(RpcInitialized\s*=\s*TRUE\)\s*&\s*' +
        '\(RpcSocket\s*=\s*CurrentSock\)\s+then\s*' +
        '_StdLib\.MemCpy\(dest:=#callbackEventMask,\s*' +
        'source:=#RequestBuf\[8\],\s*size:=4\);\s*' +
        '_StdLib\.MemCpy\(dest:=#callbackPort,\s*' +
        'source:=#RequestBuf\[12\],\s*size:=4\);\s*' +
        '_StdLib\.MemCpy\(dest:=#callbackIPv4,\s*' +
        'source:=#RequestBuf\[16\],\s*size:=4\);\s*' +
        'if\s+\(CurrentPeerValid\s*=\s*TRUE\)\s*&\s*' +
        '\(callbackIPv4\s*=\s*CurrentPeerIPv4\)\s*&\s*' +
        '\(callbackPort\s*>\s*0\)\s*&\s*' +
        '\(callbackPort\s*<=\s*65535\)\s+then\s*' +
        'if\s+RpcCallbackRegistered\s*=\s*FALSE\s+then\s*' +
        '(?<InitialRegistration>.*?)' +
        'elsif\s+\(RpcCallbackEventMask\s*=\s*callbackEventMask\)\s*&\s*' +
        '\(RpcCallbackPort\s*=\s*callbackPort\)\s*&\s*' +
        '\(RpcCallbackIPv4\[0\]\s*=\s*RequestBuf\[16\]\)\s*&\s*' +
        '\(RpcCallbackIPv4\[1\]\s*=\s*RequestBuf\[17\]\)\s*&\s*' +
        '\(RpcCallbackIPv4\[2\]\s*=\s*RequestBuf\[18\]\)\s*&\s*' +
        '\(RpcCallbackIPv4\[3\]\s*=\s*RequestBuf\[19\]\)\s+then\s*' +
        '(?<ExactDuplicate>.*?)' +
        'else\s*(?<MismatchFailure>.*?)\s*end_if;\s*' +
        'else\s*(?<ValidationFailure>.*?)\s*end_if;\s*' +
        'else\s*(?<EnvelopeFailure>.*?)\s*end_if;\s*' +
        'SendData\(\s*pData:=#Sendbuf\[0\],\s*udSize:=12,\s*' +
        'dSocket:=CurrentSock,\s*bDirect:=TRUE\s*\);\s*\z')
    $ownershipFlowMatch = [regex]::Match(
        $callbackCaseBlock,
        $ownershipFlowPattern)
    if (-not $ownershipFlowMatch.Success) {
        throw (
            "$Owner 0x405C must validate the session envelope, copy the " +
            'request into locals, validate current-peer ownership and port ' +
            'bounds, then branch to first registration, exact duplicate, ' +
            'or fail-closed acknowledgement in canonical order.')
    }

    $initialRegistrationPattern = (
        '(?is)\A\s*' +
        'RpcCallbackEventMask\s*:=\s*callbackEventMask;\s*' +
        'RpcCallbackPort\s*:=\s*callbackPort;\s*' +
        '_StdLib\.MemCpy\(dest:=#RpcCallbackIPv4\[0\],\s*' +
        'source:=#RequestBuf\[16\],\s*size:=4\);\s*' +
        'RpcCallbackRegistered\s*:=\s*TRUE;\s*' +
        'Sendbuf\[8\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*0;\s*\z')
    if ($ownershipFlowMatch.Groups['InitialRegistration'].Value -notmatch
            $initialRegistrationPattern) {
        throw (
            "$Owner first callback registration must commit mask, port and " +
            'IPv4 only after validation, publish Registered last, and ACK ' +
            'status=0/error=0.')
    }

    $successAckPattern = (
        '(?is)\A\s*Sendbuf\[8\]\$UINT\s*:=\s*0;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*0;\s*\z')
    if ($ownershipFlowMatch.Groups['ExactDuplicate'].Value -notmatch
            $successAckPattern) {
        throw (
            "$Owner only an exact existing mask/port/IPv4 duplicate may " +
            'receive an idempotent status=0/error=0 ACK.')
    }

    $failureAckPattern = (
        '(?is)\A\s*Sendbuf\[8\]\$UINT\s*:=\s*1;\s*' +
        'Sendbuf\[10\]\$INT\s*:=\s*-1;\s*\z')
    foreach ($failureGroupName in @(
            'MismatchFailure',
            'ValidationFailure',
            'EnvelopeFailure')) {
        if ($ownershipFlowMatch.Groups[$failureGroupName].Value -notmatch
                $failureAckPattern) {
            throw (
                "$Owner $failureGroupName must preserve the accepted tuple " +
                'and ACK status=1/error=-1 with no other executable action.')
        }
    }

    $persistentMutationCounts = [ordered]@{
        EventMask = [regex]::Matches(
            $callbackCaseBlock,
            '(?i)(?<![A-Za-z0-9_])RpcCallbackEventMask\s*:=').Count
        Port = [regex]::Matches(
            $callbackCaseBlock,
            '(?i)(?<![A-Za-z0-9_])RpcCallbackPort\s*:=').Count
        IPv4Copy = [regex]::Matches(
            $callbackCaseBlock,
            ('(?i)_StdLib\.MemCpy\(dest:=#RpcCallbackIPv4\[0\],' +
             '\s*source:=#RequestBuf\[16\],\s*size:=4\);')).Count
        IPv4Direct = [regex]::Matches(
            $callbackCaseBlock,
            '(?i)(?<![A-Za-z0-9_])RpcCallbackIPv4\s*\[[^\]]+\]\s*:=').Count
        RegisteredTrue = [regex]::Matches(
            $callbackCaseBlock,
            '(?i)(?<![A-Za-z0-9_])RpcCallbackRegistered\s*:=\s*TRUE\s*;').Count
        RegisteredFalse = [regex]::Matches(
            $callbackCaseBlock,
            '(?i)(?<![A-Za-z0-9_])RpcCallbackRegistered\s*:=\s*FALSE\s*;').Count
    }
    $expectedPersistentMutationCounts = [ordered]@{
        EventMask = 1
        Port = 1
        IPv4Copy = 1
        IPv4Direct = 0
        RegisteredTrue = 1
        RegisteredFalse = 0
    }
    foreach ($mutationName in $expectedPersistentMutationCounts.Keys) {
        if ($persistentMutationCounts[$mutationName] -ne
                $expectedPersistentMutationCounts[$mutationName]) {
            throw (
                "$Owner persistent callback mutation '$mutationName' count " +
                "is $($persistentMutationCounts[$mutationName]), expected " +
                "$($expectedPersistentMutationCounts[$mutationName]).")
        }
    }
}

function Assert-LasalAdminSetAxisPositionContract {
    param(
        [string]$ControlServiceText,
        [string]$TcpText,
        [string]$Owner
    )

    $serviceScan = Get-LasalScanText $ControlServiceText
    $tcpScan = Get-LasalScanText $TcpText
    $handleRequestMatches = [regex]::Matches(
        $serviceScan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+GLOBAL[ \t]+' +
         'LMCControlCommandService::HandleRequest[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    $adminHandlerMatches = [regex]::Matches(
        $serviceScan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'LMCControlCommandService::HandleAdminCommands[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    $msgParserMatches = [regex]::Matches(
        $tcpScan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'TCPMotionInterface::MsgPaser[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$'))
    if ($handleRequestMatches.Count -ne 1 -or
        $adminHandlerMatches.Count -ne 1 -or
        $msgParserMatches.Count -ne 1) {
        throw "$Owner router or Admin handler was not found exactly once."
    }

    $handleRequestBlock = $handleRequestMatches[0].Value
    $adminHandlerBlock = $adminHandlerMatches[0].Value
    $msgParserBlock = $msgParserMatches[0].Value
    $setPositionCaseMatches = [regex]::Matches(
        $adminHandlerBlock,
        ('(?ims)^[ \t]*0x7D12[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)' +
         '(?=^[ \t]*0x7D13[ \t]*,[ \t]*0x7D18[ \t]*,[ \t]*' +
         '0x7D19[ \t]*:[ \t]*\r?$)'))
    $capabilityCaseMatches = [regex]::Matches(
        $adminHandlerBlock,
        ('(?ims)^[ \t]*0x7D00[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)' +
         '(?=^[ \t]*0x7D10[ \t]*:[ \t]*\r?$)'))
    if ($setPositionCaseMatches.Count -ne 1 -or
        $capabilityCaseMatches.Count -ne 1) {
        throw "$Owner 0x7D00 or 0x7D12 case was not found exactly once."
    }
    $caseBlock = $setPositionCaseMatches[0].Groups['Body'].Value
    $capabilityBlock = $capabilityCaseMatches[0].Groups['Body'].Value

    Assert-Match $handleRequestBlock (
        '(?s)0x7D00,\s*0x7D10,\s*0x7D12,\s*0x7D13,\s*0x7D18,\s*0x7D19,\s*0x7D20,\s*0x7D22:\s*' +
        'ResponseSize\s*:=\s*HandleAdminCommands\s*\(') (
        "$Owner control-service Admin route does not own 0x7D12.")
    Assert-Match $msgParserBlock (
        '(?s)0x7D00,\s*0x7D10,\s*0x7D12,\s*0x7D13,\s*0x7D18,\s*0x7D19,\s*0x7D20,\s*0x7D22:\s*' +
        'controlResponseSize\s*:=\s*-1.*?' +
        'ControlCommands\.HandleRequest\s*\(') (
        "$Owner TCP transport route does not delegate 0x7D12.")

    $capabilityWrite = [regex]::Match(
        $capabilityBlock,
        '(?i)\(pResponseFrame\s*\+\s*24\)\^\$UDINT\s*:=\s*0x(?<Hex>[0-9A-F]+)\s*;')
    if (-not $capabilityWrite.Success) {
        throw (
            "$Owner Admin capability mask must remain one auditable literal.")
    }
    $capabilityBits = [Convert]::ToUInt32(
        $capabilityWrite.Groups['Hex'].Value,
        16)
    if (($capabilityBits -band 0x00000028) -ne 0) {
        throw "$Owner dormant SetPosition bits 3/5 were advertised before activation proof."
    }

    foreach ($requiredLocal in @(
            @{ Name = 'adminDiagnosticsBuild'; Type = 'UDINT' },
            @{ Name = 'adminBootId'; Type = 'UDINT' },
            @{ Name = 'adminMapRevision'; Type = 'UDINT' },
            @{ Name = 'adminClientIntentId0'; Type = 'UDINT' },
            @{ Name = 'adminClientIntentId1'; Type = 'UDINT' },
            @{ Name = 'adminClientIntentId2'; Type = 'UDINT' },
            @{ Name = 'adminClientIntentId3'; Type = 'UDINT' },
            @{ Name = 'adminAxisPosition'; Type = 'DINT' },
            @{ Name = 'adminExpectedActualPosition'; Type = 'DINT' },
            @{ Name = 'adminExecuteToken'; Type = 'UDINT' },
            @{ Name = 'adminAppliedPosition'; Type = 'DINT' })) {
        $localCount = [regex]::Matches(
            $adminHandlerBlock,
            ('(?im)^[ \t]*' + [regex]::Escape($requiredLocal.Name) +
             '[ \t]*:[ \t]*' + [regex]::Escape($requiredLocal.Type) +
             '[ \t]*;[ \t]*\r?$')).Count
        if ($localCount -ne 1) {
            throw (
                "$Owner local '$($requiredLocal.Name)' count is $localCount, " +
                "expected one $($requiredLocal.Type).")
        }
    }

    Assert-Match $caseBlock (
        '(?s)ResponseCapacity\s*<\s*36.*?' +
        'adminDiagnosticsBuild\s*:=\s*0.*?' +
        'adminBootId\s*:=\s*0.*?' +
        'adminMapRevision\s*:=\s*0.*?' +
        'adminClientIntentId0\s*:=\s*0.*?' +
        'adminClientIntentId1\s*:=\s*0.*?' +
        'adminClientIntentId2\s*:=\s*0.*?' +
        'adminClientIntentId3\s*:=\s*0.*?' +
        'adminAxisPosition\s*:=\s*0.*?' +
        'adminExpectedActualPosition\s*:=\s*0.*?' +
        'adminExecuteToken\s*:=\s*0.*?' +
        'adminAppliedPosition\s*:=\s*0.*?' +
        'adminErrorId\s*:=\s*-31000.*?' +
        'if\s+RequestFrameSize\s*>=\s*16\s+then.*?' +
        'adminSchemaVersion\s*:=\s*\(pRequestFrame\s*\+\s*8\)\^\$UINT.*?' +
        'adminRequestFlags\s*:=\s*\(pRequestFrame\s*\+\s*10\)\^\$UINT.*?' +
        'adminRequestId\s*:=\s*\(pRequestFrame\s*\+\s*12\)\^\$UDINT.*?' +
        'if\s+RequestFrameSize\s*>=\s*56\s+then.*?' +
        'adminDiagnosticsBuild\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*16\)\^\$UDINT.*?' +
        'adminBootId\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*20\)\^\$UDINT.*?' +
        'adminMapRevision\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*24\)\^\$UDINT.*?' +
        'adminClientIntentId0\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*28\)\^\$UDINT.*?' +
        'adminClientIntentId1\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*32\)\^\$UDINT.*?' +
        'adminClientIntentId2\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*36\)\^\$UDINT.*?' +
        'adminClientIntentId3\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*40\)\^\$UDINT.*?' +
        'adminAxisPosition\s*:=\s*\(pRequestFrame\s*\+\s*44\)\^\$DINT.*?' +
        'adminExpectedActualPosition\s*:=\s*' +
        '\(pRequestFrame\s*\+\s*48\)\^\$DINT.*?' +
        'adminExecuteToken\s*:=\s*\(pRequestFrame\s*\+\s*52\)\^\$UDINT') (
        "$Owner 0x7D12 bounded pointer decode or field offsets are incomplete.")
    Assert-Match $caseBlock (
        '(?s)if\s+RequestFrameSize\s*<>\s*56\s+then\s*' +
        'adminDetailCode\s*:=\s*5;\s*' +
        'elsif\s+\(Reference\s*<\s*1\)\s*\|\s*' +
        '\(Reference\s*>\s*4\)\s+then\s*' +
        'adminDetailCode\s*:=\s*4;\s*' +
        'elsif\s+adminSchemaVersion\s*<>\s*1\s+then\s*' +
        'adminDetailCode\s*:=\s*1;\s*' +
        'elsif\s+adminRequestFlags\s*<>\s*0\s+then\s*' +
        'adminDetailCode\s*:=\s*2;\s*' +
        'elsif\s+adminRequestId\s*=\s*0\s+then\s*' +
        'adminDetailCode\s*:=\s*3;\s*' +
        'elsif\s+adminDiagnosticsBuild\s*=\s*0\s+then\s*' +
        'adminDetailCode\s*:=\s*9;\s*' +
        'elsif\s+adminBootId\s*=\s*0\s+then\s*' +
        'adminDetailCode\s*:=\s*9;\s*' +
        'elsif\s+adminMapRevision\s*=\s*0\s+then\s*' +
        'adminDetailCode\s*:=\s*9;\s*' +
        'elsif\s+\(adminClientIntentId0\s*=\s*0\)\s*&\s*' +
        '\(adminClientIntentId1\s*=\s*0\)\s*&\s*' +
        '\(adminClientIntentId2\s*=\s*0\)\s*&\s*' +
        '\(adminClientIntentId3\s*=\s*0\)\s+then\s*' +
        'adminDetailCode\s*:=\s*9;\s*' +
        'elsif\s+adminExecuteToken\s*<>\s*0x50544553\s+then\s*' +
        'adminDetailCode\s*:=\s*9;\s*' +
        'else\s+adminDetailCode\s*:=\s*10;\s*end_if;') (
        "$Owner 0x7D12 must validate the exact dormant request and then fail closed.")

    $forbiddenMutationPattern = (
        '(?i)\bLMCAxis[1-9]\.(?:SetPosition|ReadAxisStatus|' +
        'ReadVelocity|ReadAxisError|ReadPosition|ReadSWEndPos|' +
        'ReadParameter)\s*\(')
    if ($caseBlock -match $forbiddenMutationPattern -or
        $caseBlock -match '(?i)LMCAXIS_SET_ACTPOS_APPUNIT_DEST' -or
        $caseBlock -match '(?i)LMCAXIS_PAR_RD_SWLIMWINDOW') {
        throw (
            "$Owner dormant 0x7D12 must perform no native axis read or " +
            'SetPosition mutation.')
    }
    if ([regex]::Matches(
            $caseBlock,
            '(?i)adminAppliedPosition\s*:=').Count -ne 1) {
        throw "$Owner dormant 0x7D12 must never publish a position as applied."
    }

    Assert-Match $caseBlock (
        '(?s)_memset\(dest:=pResponseFrame,\s*usByte:=0,\s*cntr:=36\).*?' +
        'pResponseFrame\^\$UINT\s*:=\s*0.*?' +
        '\(pResponseFrame\s*\+\s*2\)\^\$UINT\s*:=\s*28.*?' +
        '\(pResponseFrame\s*\+\s*8\)\^\$UINT\s*:=\s*1.*?' +
        '\(pResponseFrame\s*\+\s*10\)\^\$UINT\s*:=\s*0.*?' +
        '\(pResponseFrame\s*\+\s*12\)\^\$UINT\s*:=\s*1.*?' +
        '\(pResponseFrame\s*\+\s*14\)\^\$INT\s*:=\s*adminErrorId.*?' +
        '\(pResponseFrame\s*\+\s*16\)\^\$UDINT\s*:=\s*adminRequestId.*?' +
        '\(pResponseFrame\s*\+\s*20\)\^\$UDINT\s*:=\s*adminDetailCode.*?' +
        '\(pResponseFrame\s*\+\s*24\)\^\$DINT\s*:=\s*adminAppliedPosition.*?' +
        '\(pResponseFrame\s*\+\s*28\)\^\$UINT\s*:=\s*1.*?' +
        '\(pResponseFrame\s*\+\s*30\)\^\$UINT\s*:=\s*0.*?' +
        '\(pResponseFrame\s*\+\s*32\)\^\$UDINT\s*:=\s*0.*?' +
        'ResponseSize\s*:=\s*36') (
        "$Owner 0x7D12 fixed fail-closed 28-byte Admin response is incomplete.")
}

function Assert-LasalAxisZeroHomeRtMailboxContract {
    param(
        [string]$InputLatchText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $InputLatchText
    $blocker = "$Owner AxisZeroHome RT/mailbox contract:"

    Assert-Match $scan (
        'AxisZeroHomeMailbox\s*:\s*ARRAY\s*\[\s*0\.\.7\s*\]\s*OF\s*DINT') (
        "$blocker mailbox must remain exactly eight DINTs.")
    Assert-Match $scan (
        'AxisZeroHomeResult\s*:\s*ARRAY\s*\[\s*0\.\.31\s*\]\s*OF\s*DINT') (
        "$blocker result must remain exactly 32 DINTs/128 bytes.")
    Assert-Match $scan (
        'AxisZeroHomeCancelSequence\s*:\s*UDINT') (
        "$blocker cancel sequence must remain an atomic UDINT.")

    $rtMatches = [regex]::Matches(
        $scan,
        '(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+' +
        'LMCEcatInputLatch::RtWork\b.*?END_FUNCTION')
    $submitMatches = [regex]::Matches(
        $scan,
        '(?is)FUNCTION\s+GLOBAL\s+' +
        'LMCEcatInputLatch::SubmitAxisZeroHome\b.*?END_FUNCTION')
    $copyMatches = [regex]::Matches(
        $scan,
        '(?is)FUNCTION\s+GLOBAL\s+' +
        'LMCEcatInputLatch::CopyAxisZeroHomeResult\b.*?END_FUNCTION')
    $cancelMatches = [regex]::Matches(
        $scan,
        '(?is)FUNCTION\s+GLOBAL\s+' +
        'LMCEcatInputLatch::CancelAxisZeroHome\b.*?END_FUNCTION')
    if ($rtMatches.Count -ne 1 -or
        $submitMatches.Count -ne 1 -or
        $cancelMatches.Count -ne 1 -or
        $copyMatches.Count -ne 1) {
        throw (
            "$blocker expected one RtWork, SubmitAxisZeroHome, " +
            'CancelAxisZeroHome, and CopyAxisZeroHomeResult implementation.')
    }

    $rtBlock = $rtMatches[0].Value
    $submitBlock = $submitMatches[0].Value
    $cancelBlock = $cancelMatches[0].Value
    $copyBlock = $copyMatches[0].Value
    $zeroHomeStart = [regex]::Match(
        $rtBlock,
        '(?is)\bzeroHomeRequestSequence\s*:=\s*' +
        'sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeRequestSequence\s*\)\s*;')
    $ds402Start = [regex]::Match(
        $rtBlock,
        '(?is)\bhomeRequestSequence\s*:=\s*' +
        'sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#Ds402HomeRequestSequence\s*\)\s*;')
    if (-not $zeroHomeStart.Success -or
        -not $ds402Start.Success -or
        $ds402Start.Index -le $zeroHomeStart.Index) {
        throw "$blocker cannot isolate the AxisZeroHome RT producer/consumer block."
    }
    $zeroHomeRtBlock = $rtBlock.Substring(
        $zeroHomeStart.Index,
        $ds402Start.Index - $zeroHomeStart.Index)

    $constantSpecifications = [ordered]@{
        LMC_ZERO_HOME_STATE_RUNNING = '1'
        LMC_ZERO_HOME_STATE_SUCCEEDED = '2'
        LMC_ZERO_HOME_STATE_FAILED = '3'
        LMC_ZERO_HOME_PHASE_VERIFY = '1'
        LMC_ZERO_HOME_REQUIRED_STABLE = '3'
        LMC_ZERO_HOME_EVIDENCE_EXPECTED = '0x00000001'
        LMC_ZERO_HOME_EVIDENCE_STATE = '0x00000002'
        LMC_ZERO_HOME_EVIDENCE_APP = '0x00000008'
        LMC_ZERO_HOME_EVIDENCE_INTERNAL = '0x00000010'
        LMC_ZERO_HOME_EVIDENCE_STABLE = '0x00000020'
        LMC_ZERO_HOME_EVIDENCE_VERIFIED = '0x0000001B'
        LMC_ZERO_HOME_EVIDENCE_COMPLETE = '0x0000003B'
        LMC_ZERO_HOME_FAILURE_CANCELLED = '-10'
    }
    foreach ($constantName in $constantSpecifications.Keys) {
        $allDefinitions = [regex]::Matches(
            $scan,
            ('(?im)^\s*#define\s+' + [regex]::Escape($constantName) +
             '\s+[^\r\n]+(?=\r?$)'))
        $exactDefinitions = [regex]::Matches(
            $scan,
            ('(?im)^\s*#define\s+' + [regex]::Escape($constantName) +
             '\s+' +
             [regex]::Escape($constantSpecifications[$constantName]) +
             '\s*$'))
        if ($allDefinitions.Count -ne 1 -or $exactDefinitions.Count -ne 1) {
            throw (
                "$blocker $constantName must be defined exactly once as " +
                "$($constantSpecifications[$constantName]).")
        }
    }

    $allMailboxWrites = [regex]::Matches(
        $scan,
        '(?is)AxisZeroHomeMailbox\s*\[\s*\d+\s*\]' +
        '(?:\s*\$UDINT)?\s*:=\s*[^;]+;')
    $submitMailboxWrites = [regex]::Matches(
        $submitBlock,
        '(?is)AxisZeroHomeMailbox\s*\[\s*\d+\s*\]' +
        '(?:\s*\$UDINT)?\s*:=\s*[^;]+;')
    $rtMailboxWrites = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)AxisZeroHomeMailbox\s*\[\s*\d+\s*\]' +
        '(?:\s*\$UDINT)?\s*:=\s*[^;]+;')
    $cancelMailboxWrites = [regex]::Matches(
        $cancelBlock,
        '(?is)AxisZeroHomeMailbox\s*\[\s*\d+\s*\]' +
        '(?:\s*\$UDINT)?\s*:=\s*[^;]+;')
    if ($allMailboxWrites.Count -ne 10 -or
        $submitMailboxWrites.Count -ne 8 -or
        $cancelMailboxWrites.Count -ne 1 -or
        $rtMailboxWrites.Count -ne 1) {
        throw (
            "$blocker mailbox writes must be exactly eight submit fields, " +
            'one cancel echo, and one RT-owned native-dispatch claim.')
    }
    $mailboxWriteSpecifications = @(
        @{ Slot = 0; Cast = '\$UDINT'; Rhs = 'OperationToken' },
        @{ Slot = 1; Cast = ''; Rhs = 'AxisReference' },
        @{ Slot = 2; Cast = ''; Rhs = 'ExpectedActualPosition' },
        @{ Slot = 3; Cast = '\$UDINT'; Rhs = 'nextRequestSequence' },
        @{ Slot = 4; Cast = ''; Rhs = '0' },
        @{ Slot = 5; Cast = ''; Rhs = '0' },
        @{ Slot = 6; Cast = ''; Rhs = '0' },
        @{ Slot = 7; Cast = ''; Rhs = '0' })
    $lastMailboxWriteEnd = -1
    foreach ($specification in $mailboxWriteSpecifications) {
        $pattern = (
            '(?is)AxisZeroHomeMailbox\s*\[\s*' +
            $specification.Slot + '\s*\]\s*' +
            $specification.Cast + '\s*:=\s*' +
            [regex]::Escape($specification.Rhs) + '\s*;')
        $matches = [regex]::Matches($submitBlock, $pattern)
        if ($matches.Count -ne 1) {
            throw (
                "$blocker mailbox slot $($specification.Slot) must be written " +
                "exactly once from $($specification.Rhs).")
        }
        $writeEnd = $matches[0].Index + $matches[0].Length
        if ($writeEnd -gt $lastMailboxWriteEnd) {
            $lastMailboxWriteEnd = $writeEnd
        }
    }

    Assert-Match $zeroHomeRtBlock (
        '(?is)zeroHomeRequestToken\s*:=\s*' +
        'AxisZeroHomeMailbox\s*\[\s*0\s*\]\s*\$UDINT\s*;.*?' +
        'zeroHomeRequestAxis\s*:=\s*' +
        'AxisZeroHomeMailbox\s*\[\s*1\s*\]\s*;.*?' +
        'zeroHomeExpectedActualPosition\s*:=\s*' +
        'AxisZeroHomeMailbox\s*\[\s*2\s*\]\s*;') (
        "$blocker RT request fields do not use mailbox slots 0, 1, and 2 exactly.")
    $expectedPositionAssignments = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?im)^\s*zeroHomeExpectedActualPosition\s*:=[^;]+;')
    if ($expectedPositionAssignments.Count -ne 1 -or
        $expectedPositionAssignments[0].Value -notmatch
            '(?is):=\s*AxisZeroHomeMailbox\s*\[\s*2\s*\]\s*;') {
        throw (
            "$blocker expected actual position must be sampled exactly once " +
            'from mailbox slot 2.')
    }
    $actualPositionAssignments = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?im)^\s*zeroHomeActualAppPosition\s*:=[^;]+;')
    $actualPositionZeroAssignments = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?im)^\s*zeroHomeActualAppPosition\s*:=\s*0\s*;')
    if ($actualPositionAssignments.Count -ne 9 -or
        $actualPositionZeroAssignments.Count -ne 1) {
        throw (
            "$blocker actual application position inventory must be one zero " +
            'initialization and two native samples per axis.')
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeMailbox\s*\[\s*3\s*\]\s*\$UDINT\s*' +
        '<>\s*zeroHomeRequestSequence') (
        "$blocker RT request-sequence echo validation is missing.")
    Assert-Match $submitBlock (
        '(?is)AxisZeroHomeMailbox\s*\[\s*3\s*\]\s*\$UDINT\s*=\s*' +
        'requestSequence') (
        "$blocker pending exact retry does not validate the request-sequence echo.")
    if ([regex]::Matches(
            $zeroHomeRtBlock,
            '(?is)AxisZeroHomeMailbox\s*\[\s*4\s*\]\s*\$UDINT\s*' +
            ':=\s*zeroHomeRequestSequence\s*;').Count -ne 1) {
        throw (
            "$blocker RT must write slot 4 exactly once as the current " +
            'request-sequence native-dispatch claim.')
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)elsif\s+zeroHomePhase\s*=\s*0\s+then\s*' +
        'if\s*\(\s*AxisZeroHomeResult\s*\[\s*8\s*\]\s*<>\s*0\s*\)\s*' +
        '\|\s*\(\s*AxisZeroHomeMailbox\s*\[\s*4\s*\]\s*\$UDINT\s*' +
        '<>\s*0\s*\)\s*then.*?' +
        'zeroHomeFailure\s*:=\s*LMC_ZERO_HOME_FAILURE_CORRUPT\s*;.*?' +
        'zeroHomeTerminal\s*:=\s*TRUE\s*;') (
        "$blocker phase 0 must terminally reject an existing native-call/claim marker.")
    $axisReferenceCaseMatches = @([regex]::Matches(
            $zeroHomeRtBlock,
            '(?is)case\s+zeroHomeRequestAxis\s+of(?<Body>.*?)end_case\s*;'))
    $preDispatchSampleCases = @($axisReferenceCaseMatches | Where-Object {
            $_.Groups['Body'].Value -match '(?i)LMCAXIS_ACTPOS_APPUNIT' -and
            $_.Groups['Body'].Value -notmatch '(?i)\.SetPosition\s*\('
        })
    $nativeDispatchCases = @($axisReferenceCaseMatches | Where-Object {
            $_.Groups['Body'].Value -match '(?i)\.SetPosition\s*\('
        })
    if ($preDispatchSampleCases.Count -ne 1 -or
        $nativeDispatchCases.Count -ne 1) {
        throw (
            "$blocker RT must contain one pre-dispatch sample case and one " +
            'native-dispatch case.')
    }
    foreach ($axis in 1..4) {
        $preDispatchAxisBranch = [regex]::Match(
            $preDispatchSampleCases[0].Groups['Body'].Value,
            ('(?ims)^\s*' + $axis + '\s*:\s*(?<Body>.*?)' +
             '(?=^\s*(?:[1-4]\s*:|else\s*$)|\z)'))
        $nativeDispatchAxisBranch = [regex]::Match(
            $nativeDispatchCases[0].Groups['Body'].Value,
            ('(?ims)^\s*' + $axis + '\s*:\s*(?<Body>.*?)' +
             '(?=^\s*(?:[1-4]\s*:|else\s*$)|\z)'))
        if (-not $preDispatchAxisBranch.Success -or
            -not $nativeDispatchAxisBranch.Success) {
            throw "$blocker axis $axis zero-Home branch is missing."
        }
        $preDispatchActualReads = [regex]::Matches(
            $preDispatchAxisBranch.Groups['Body'].Value,
            ('(?is)zeroHomeActualAppPosition\s*:=\s*LMCAxis' + $axis +
             '\.ReadPosition\s*\(\s*Mode\s*:=\s*' +
             'LMCAXIS_ACTPOS_APPUNIT\s*\)\s*;'))
        if ($preDispatchActualReads.Count -ne 1) {
            throw (
                "$blocker axis $axis must provide exactly one bound actual " +
                'application-position sample before stale detection.')
        }
        Assert-Match $nativeDispatchAxisBranch.Groups['Body'].Value (
            '(?is)zeroHomeNativeState\s*:=\s*LMCAxis' + $axis +
            '\.SetPosition\s*\(.*?\)\s*;.*?' +
            'zeroHomeActualAppPosition\s*:=\s*LMCAxis' + $axis +
            '\.ReadPosition\s*\(\s*Mode\s*:=\s*' +
            'LMCAXIS_ACTPOS_APPUNIT\s*\)\s*;') (
            "$blocker axis $axis must resample actual position after SetPosition.")
    }

    $staleActualPositionGuard = [regex]::Match(
        $zeroHomeRtBlock,
        ('(?is)elsif\s+zeroHomeActualAppPosition\s*<>\s*' +
        'zeroHomeExpectedActualPosition\s+then\s*' +
        'zeroHomeFailure\s*:=\s*LMC_ZERO_HOME_FAILURE_STALE\s*;\s*' +
        'zeroHomeTerminal\s*:=\s*TRUE\s*;\s*else\s*' +
        'zeroHomeEvidence\s*:=.*?' +
        'AxisZeroHomeMailbox\s*\[\s*4\s*\]\s*\$UDINT\s*:=\s*' +
        'zeroHomeRequestSequence\s*;.*?\.SetPosition\s*\('))
    if (-not $staleActualPositionGuard.Success) {
        throw (
            "$blocker stale actual/expected position must terminate before the " +
            'irrevocable dispatch claim and SetPosition call.')
    }
    $preDispatchCaseEnd =
        $preDispatchSampleCases[0].Index + $preDispatchSampleCases[0].Length
    if ($preDispatchCaseEnd -ge $staleActualPositionGuard.Index) {
        throw "$blocker stale guard must follow the complete actual-position sample."
    }
    $sampleToGuardText = $zeroHomeRtBlock.Substring(
        $preDispatchCaseEnd,
        $staleActualPositionGuard.Index - $preDispatchCaseEnd)
    if ($sampleToGuardText -match
            '(?i)zeroHome(?:ActualApp|ExpectedActual)Position\s*:=') {
        throw (
            "$blocker actual/expected stale operands cannot be overwritten " +
            'after sampling and before the terminal guard.')
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeMailbox\s*\[\s*4\s*\]\s*\$UDINT\s*:=\s*' +
        'zeroHomeRequestSequence\s*;.*?' +
        'AxisZeroHomeResult\s*\[\s*8\s*\]\s*:=\s*1\s*;.*?' +
        'AxisZeroHomeResult\s*\[\s*13\s*\]\s*:=\s*' +
        'zeroHomeRawDrivePosition\s*;.*?' +
        '\.SetPosition\s*\(') (
        "$blocker RT dispatch claim/call-count/raw-before markers must precede SetPosition.")
    Assert-Match $zeroHomeRtBlock (
        '(?is)elsif\s+zeroHomePhase\s*=\s*' +
        'LMC_ZERO_HOME_PHASE_VERIFY\s+then.*?' +
        'AxisZeroHomeResult\s*\[\s*8\s*\]\s*<>\s*1.*?' +
        'AxisZeroHomeMailbox\s*\[\s*4\s*\]\s*\$UDINT\s*<>\s*' +
        'zeroHomeRequestSequence') (
        "$blocker verify phase does not require the current request's RT dispatch claim.")

    $rtCancelReadMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)zeroHomeCancelSequence\s*:=\s*' +
        'sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*\)\s*;')
    $rtCancelEchoMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)zeroHomeCancelEcho\s*:=\s*' +
        'AxisZeroHomeMailbox\s*\[\s*5\s*\]\s*\$UDINT\s*;')
    $rtCancelledMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)zeroHomeFailure\s*:=\s*' +
        'LMC_ZERO_HOME_FAILURE_CANCELLED\s*;\s*' +
        'zeroHomeTerminal\s*:=\s*TRUE\s*;')
    $rtCancelGapMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)\(\s*zeroHomeCancelSequence\s*=\s*0\s*\)\s*&\s*' +
        '\(\s*zeroHomeCancelEcho\s*=\s*zeroHomeRequestSequence\s*\)\s*' +
        'then.*?zeroHomeCancelPublishing\s*:=\s*TRUE\s*;')
    if ($rtCancelReadMatches.Count -ne 4 -or
        $rtCancelEchoMatches.Count -ne 4 -or
        $rtCancelledMatches.Count -ne 4 -or
        $rtCancelGapMatches.Count -ne 4) {
        throw (
            "$blocker RT must perform the exact four cancel checks at phase 0, " +
            'pre-claim, verify entry, and final-success linearization.')
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)zeroHomeEvidence\s*:=\s*zeroHomeEvidence\s+or\s*' +
        'LMC_ZERO_HOME_EVIDENCE_INTERNAL\s*;\s*' +
        '.*?pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*\)\s*;\s*' +
        'zeroHomeCancelEcho\s*:=\s*AxisZeroHomeMailbox\s*\[\s*5\s*\]' +
        '\s*\$UDINT\s*;.*?' +
        'elsif\s*\(\s*zeroHomeCancelSequence\s*=\s*0\s*\)\s*&\s*' +
        '\(\s*zeroHomeCancelEcho\s*=\s*zeroHomeRequestSequence\s*\)\s*then\s*' +
        'if\s+zeroHomeStableSampleCount\s*=\s*0\s+then\s*' +
        'zeroHomeEvidence\s*:=\s*LMC_ZERO_HOME_EVIDENCE_DISPATCH\s*;\s*' +
        'else\s*zeroHomeEvidence\s*:=\s*' +
        'LMC_ZERO_HOME_EVIDENCE_VERIFIED\s*;\s*end_if\s*;\s*' +
        'zeroHomeCancelPublishing\s*:=\s*TRUE\s*;.*?' +
        'else\s*zeroHomeStableSampleCount\s*\+=\s*1\s*;') (
        "$blocker final cancel check must precede stable/evidence commit and " +
        'restore prior evidence across the echo-before-atomic gap.')

    $requestPublishMatches = [regex]::Matches(
        $submitBlock,
        '(?is)sigclib_atomic_setU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeRequestSequence\s*,\s*' +
        'value\s*:=\s*nextRequestSequence\s*\)\s*;')
    $cancelClearMatches = [regex]::Matches(
        $submitBlock,
        '(?is)sigclib_atomic_setU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*,\s*' +
        'value\s*:=\s*0\s*\)\s*;')
    if ($requestPublishMatches.Count -ne 1 -or
        $cancelClearMatches.Count -ne 1 -or
        $cancelClearMatches[0].Index -le $lastMailboxWriteEnd -or
        $requestPublishMatches[0].Index -le
            ($cancelClearMatches[0].Index + $cancelClearMatches[0].Length)) {
        throw (
            "$blocker cancel reset and request sequence must each be atomically " +
            'published once, in that order, after all mailbox payload writes.')
    }
    $mailboxWriteAfterPublish = [regex]::Match(
        $submitBlock.Substring(
            $requestPublishMatches[0].Index + $requestPublishMatches[0].Length),
        '(?is)AxisZeroHomeMailbox\s*\[\s*\d+\s*\].*?:=')
    if ($mailboxWriteAfterPublish.Success) {
        throw "$blocker mailbox changes after its request sequence is published."
    }

    if ($cancelBlock -match
            ('(?is)sigclib_atomic_setU32\s*\(\s*pValue\s*:=\s*' +
             '#AxisZeroHome(?:Request|Applied)Sequence')) {
        throw "$blocker CancelAxisZeroHome may not publish request/applied sequence."
    }
    Assert-Match $cancelBlock (
        '(?is)\(\s*requestSequenceBefore\s*=\s*0\s*\)\s*\|\s*' +
        '\(AxisZeroHomeMailbox\[0\]\$UDINT\s*<>\s*OperationToken\)') (
        "$blocker CancelAxisZeroHome mailbox is not fenced by the exact operation token.")
    $cancelTerminalTokenFences = [regex]::Matches(
        $cancelBlock,
        '(?is)AxisZeroHomeResult\[0\]\$UDINT\s*=\s*OperationToken')
    if ($cancelTerminalTokenFences.Count -ne 3) {
        throw (
            "$blocker CancelAxisZeroHome has $($cancelTerminalTokenFences.Count) " +
            'terminal token fences, expected exactly three.')
    }
    $cancelEchoWriteMatches = [regex]::Matches(
        $cancelBlock,
        '(?is)AxisZeroHomeMailbox\s*\[\s*5\s*\]\s*\$UDINT\s*:=\s*' +
        'requestSequenceBefore\s*;')
    $cancelPublishMatches = [regex]::Matches(
        $cancelBlock,
        '(?is)sigclib_atomic_setU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*,\s*' +
        'value\s*:=\s*requestSequenceBefore\s*\)\s*;')
    $cancelReadMatches = [regex]::Matches(
        $cancelBlock,
        '(?is)cancelSequence\s*:=\s*sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*\)\s*;')
    if ($cancelEchoWriteMatches.Count -ne 1 -or
        $cancelPublishMatches.Count -ne 1 -or
        $cancelReadMatches.Count -ne 2 -or
        $cancelEchoWriteMatches[0].Index -ge $cancelPublishMatches[0].Index) {
        throw (
            "$blocker CancelAxisZeroHome must publish slot 5 before the one " +
            'atomic cancel sequence and re-read that publication afterward.')
    }
    Assert-Match $cancelBlock (
        '(?is)if\s+cancelEcho\s*=\s*0\s+then\s*' +
        'AxisZeroHomeMailbox\s*\[\s*5\s*\]\s*\$UDINT\s*:=\s*' +
        'requestSequenceBefore\s*;\s*end_if\s*;.*?' +
        'requestSequenceAfter\s*:=\s*sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeRequestSequence\s*\)\s*;.*?' +
        'appliedSequenceAfter\s*:=\s*sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeAppliedSequence\s*\)\s*;.*?' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*,\s*' +
        'value\s*:=\s*requestSequenceBefore\s*\)\s*;.*?' +
        'cancelSequence\s*:=\s*sigclib_atomic_getU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeCancelSequence\s*\)\s*;.*?' +
        'Result\s*:=\s*1\s*;') (
        "$blocker CancelAxisZeroHome does not preserve echo-before-atomic " +
        'publication with request/applied fencing and post-publication proof.')

    $resultWriteSpecifications = @(
        @{ Slot = 0; Cast = '\$UDINT'; Rhs = 'zeroHomeRequestToken'; Count = 2 },
        @{ Slot = 1; Cast = ''; Rhs = 'LMC_ZERO_HOME_STATE_RUNNING'; Count = 2 },
        @{ Slot = 1; Cast = ''; Rhs = 'LMC_ZERO_HOME_STATE_SUCCEEDED'; Count = 1 },
        @{ Slot = 1; Cast = ''; Rhs = 'LMC_ZERO_HOME_STATE_FAILED'; Count = 1 },
        @{ Slot = 2; Cast = ''; Rhs = 'zeroHomeFailure'; Count = 1 },
        @{ Slot = 2; Cast = ''; Rhs = '0'; Count = 1 },
        @{ Slot = 3; Cast = ''; Rhs = 'zeroHomeRequestAxis'; Count = 2 },
        @{ Slot = 4; Cast = ''; Rhs = 'zeroHomeExpectedActualPosition'; Count = 2 },
        @{ Slot = 5; Cast = ''; Rhs = 'zeroHomePhase'; Count = 2 },
        @{ Slot = 6; Cast = ''; Rhs = 'zeroHomeStableSampleCount'; Count = 1 },
        @{ Slot = 7; Cast = '\$UDINT'; Rhs = 'zeroHomeEvidence'; Count = 2 },
        @{ Slot = 8; Cast = ''; Rhs = '1'; Count = 1 },
        @{ Slot = 9; Cast = '\$UDINT'; Rhs = 'zeroHomeCycle'; Count = 2 },
        @{ Slot = 10; Cast = '\$UDINT'; Rhs = 'zeroHomeCycle'; Count = 1 },
        @{ Slot = 11; Cast = '\$UDINT'; Rhs = 'zeroHomeAxisStatus$UDINT'; Count = 1 },
        @{ Slot = 12; Cast = '\$UDINT'; Rhs = 'zeroHomeAxisError$UDINT'; Count = 1 },
        @{ Slot = 13; Cast = ''; Rhs = 'zeroHomeRawDrivePosition'; Count = 1 },
        @{ Slot = 14; Cast = ''; Rhs = 'zeroHomeRawDrivePosition'; Count = 1 },
        @{ Slot = 15; Cast = ''; Rhs = 'zeroHomeActualAppPosition'; Count = 1 },
        @{ Slot = 16; Cast = ''; Rhs = 'zeroHomeSetAppPosition'; Count = 1 },
        @{ Slot = 17; Cast = ''; Rhs = 'zeroHomeActualIntPosition'; Count = 1 },
        @{ Slot = 18; Cast = ''; Rhs = 'zeroHomeSetIntPosition'; Count = 1 },
        @{ Slot = 19; Cast = ''; Rhs = 'zeroHomeDestinationPosition'; Count = 1 },
        @{ Slot = 20; Cast = ''; Rhs = 'zeroHomeMasterPosition'; Count = 1 },
        @{ Slot = 21; Cast = '\$UDINT'; Rhs = 'zeroHomeNativeState$UDINT'; Count = 2 },
        @{ Slot = 22; Cast = '\$UDINT'; Rhs = 'zeroHomeRequestSequence'; Count = 2 },
        @{ Slot = 23; Cast = '\$UDINT'; Rhs = 'zeroHomeCycle'; Count = 1 })
    $expectedResultWriteCount = 0
    foreach ($specification in $resultWriteSpecifications) {
        $expectedResultWriteCount += $specification.Count
        $pattern = (
            '(?is)AxisZeroHomeResult\s*\[\s*' +
            $specification.Slot + '\s*\]\s*' +
            $specification.Cast + '\s*:=\s*' +
            [regex]::Escape($specification.Rhs) + '\s*;')
        $matches = [regex]::Matches($zeroHomeRtBlock, $pattern)
        if ($matches.Count -ne $specification.Count) {
            throw (
                "$blocker result slot $($specification.Slot) write from " +
                "$($specification.Rhs) count is $($matches.Count), expected " +
                "$($specification.Count).")
        }
    }
    $allResultWrites = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)AxisZeroHomeResult\s*\[\s*\d+\s*\]' +
        '(?:\s*\$UDINT)?\s*:=\s*[^;]+;')
    if ($allResultWrites.Count -ne $expectedResultWriteCount) {
        throw (
            "$blocker result has $($allResultWrites.Count) explicit writes, " +
            "expected the exact $expectedResultWriteCount-write slot mapping.")
    }
    $reservedResultReferences = [regex]::Matches(
        $scan,
        '(?is)AxisZeroHomeResult\s*\[\s*(?:2[4-9]|3[01])\s*\]')
    if ($reservedResultReferences.Count -ne 0) {
        throw "$blocker reserved result slots 24..31 must remain zero and unreferenced."
    }
    $resultClearMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)_memset\s*\(\s*dest\s*:=\s*#AxisZeroHomeResult\s*' +
        '\[\s*0\s*\]\s*,\s*usByte\s*:=\s*0\s*,\s*' +
        'cntr\s*:=\s*128\s*\)\s*;')
    if ($resultClearMatches.Count -ne 1) {
        throw "$blocker the complete 32-DINT result must be zeroed exactly once per new request."
    }

    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeResult\s*\[\s*22\s*\]\s*\$UDINT\s*' +
        '<>\s*zeroHomeRequestSequence.*?' +
        'AxisZeroHomeResult\s*\[\s*22\s*\]\s*\$UDINT\s*:=\s*' +
        'zeroHomeRequestSequence\s*;') (
        "$blocker new results do not retain the exact request-sequence echo.")
    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeResult\s*\[\s*22\s*\]\s*\$UDINT\s*' +
        '<>\s*zeroHomeRequestSequence') (
        "$blocker runtime identity does not revalidate the result sequence echo.")
    Assert-Match $submitBlock (
        '(?is)Result\s*:=\s*LMC_ZERO_HOME_FAILURE_INVALID\s*;.*?' +
        'if\s*\(\s*appliedSequence\s*<>\s*0\s*\)\s*&\s*' +
        '\(\s*AxisZeroHomeResult\s*\[\s*0\s*\]\s*\$UDINT\s*=\s*' +
        'OperationToken\s*\)\s*then\s*' +
        'if\s*\(\s*AxisZeroHomeResult\s*\[\s*22\s*\]\s*\$UDINT\s*' +
        '<>\s*appliedSequence\s*\)\s*\|\s*' +
        '\(\s*AxisZeroHomeResult\s*\[\s*3\s*\]\s*<>\s*' +
        'AxisReference\s*\)\s*\|\s*' +
        '\(\s*AxisZeroHomeResult\s*\[\s*4\s*\]\s*<>\s*' +
        'ExpectedActualPosition\s*\)\s*then\s*RETURN\s*;\s*end_if\s*;.*?' +
        'AxisZeroHomeResult\s*\[\s*1\s*\]\s*=\s*' +
        'LMC_ZERO_HOME_STATE_SUCCEEDED.*?' +
        'AxisZeroHomeResult\s*\[\s*1\s*\]\s*=\s*' +
        'LMC_ZERO_HOME_STATE_FAILED.*?' +
        'Result\s*:=\s*0\s*;.*?RETURN\s*;\s*end_if\s*;') (
        "$blocker same-token/different-key rejection or exact terminal retry is missing.")

    $allSetPositionCalls = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)\.SetPosition\s*\(')
    if ($allSetPositionCalls.Count -ne 4) {
        throw (
            "$blocker contains $($allSetPositionCalls.Count) SetPosition call " +
            'sites, expected one mutually-exclusive site for each of axes 1..4.')
    }
    foreach ($axis in 1..4) {
        $exactCallMatches = [regex]::Matches(
            $zeroHomeRtBlock,
            ('(?is)zeroHomeNativeState\s*:=\s*LMCAxis' + $axis +
             '\.SetPosition\s*\(\s*' +
             'Mode\s*:=\s*LMCAXIS_SET_ACTPOS_APPUNIT_DEST\s*,\s*' +
             'Position\s*:=\s*0\s*\)\s*;'))
        if ($exactCallMatches.Count -ne 1) {
            throw (
                "$blocker axis $axis must have exactly one current-position-zero " +
                'native call site.')
        }
    }
    if (($submitBlock + "`n" + $copyBlock) -match '(?is)\.SetPosition\s*\(') {
        throw "$blocker non-RT producer/copy path calls SetPosition."
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeResult\s*\[\s*8\s*\]\s*:=\s*1\s*;.*?' +
        'AxisZeroHomeResult\s*\[\s*8\s*\]\s*<>\s*1') (
        "$blocker NativeCallCount is not latched and revalidated as exactly one.")

    $readSpecifications = @(
        @{ Variable = 'zeroHomeActualAppPosition'; Mode = 'LMCAXIS_ACTPOS_APPUNIT' },
        @{ Variable = 'zeroHomeSetAppPosition'; Mode = 'LMCAXIS_SETPOS_APPUNIT' },
        @{ Variable = 'zeroHomeActualIntPosition'; Mode = 'LMCAXIS_ACTPOS_INTUNIT' },
        @{ Variable = 'zeroHomeSetIntPosition'; Mode = 'LMCAXIS_SETPOS_INTUNIT' },
        @{ Variable = 'zeroHomeDestinationPosition'; Mode = 'LMCAXIS_DESTPOS_INTUNIT' },
        @{ Variable = 'zeroHomeMasterPosition'; Mode = 'LMCAXIS_MASTERPOS_INTUNIT' })
    foreach ($axis in 1..4) {
        $rawReads = [regex]::Matches(
            $zeroHomeRtBlock,
            ('(?is)zeroHomeRawDrivePosition\s*:=\s*Drive' + $axis +
             '\.ActPos\.Read\s*\(\s*\)\s*;'))
        if ($rawReads.Count -ne 2) {
            throw (
                "$blocker axis $axis must have one pre-dispatch raw read and " +
                'one immediate post-call raw read.')
        }
        foreach ($readSpecification in $readSpecifications) {
            $positionReads = [regex]::Matches(
                $zeroHomeRtBlock,
                ('(?is)' + [regex]::Escape($readSpecification.Variable) +
                 '\s*:=\s*LMCAxis' + $axis +
                 '\.ReadPosition\s*\(\s*Mode\s*:=\s*' +
                 [regex]::Escape($readSpecification.Mode) + '\s*\)\s*;'))
            if ($positionReads.Count -ne 2) {
                throw (
                    "$blocker axis $axis $($readSpecification.Mode) must be " +
                    'read once on every RT pass and immediately after the native call.')
            }
        }
    }

    Assert-Match $zeroHomeRtBlock (
        '(?is)AxisZeroHomeResult\s*\[\s*13\s*\]\s*:=\s*' +
        'zeroHomeRawDrivePosition\s*;.*?\.SetPosition\s*\(') (
        "$blocker RawDrivePositionBefore is not captured before the native call.")
    if ($scan -match
            '(?i)\b(?:zeroHomeRawDelta|LMC_ZERO_HOME_(?:RAW_WINDOW|' +
            'RAW_NEGATIVE_WINDOW|EVIDENCE_RAW))\b') {
        throw (
            "$blocker temporary SetPosition-only Home must not gate success " +
            'or publish evidence from the raw-drive delta.')
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)\(\s*zeroHomeActualAppPosition\s*<>\s*0\s*\)\s*\|\s*' +
        '\(\s*zeroHomeSetAppPosition\s*<>\s*0\s*\).*?' +
        'LMC_ZERO_HOME_EVIDENCE_APP.*?' +
        '\(\s*zeroHomeActualIntPosition\s*<>\s*0\s*\)\s*\|\s*' +
        '\(\s*zeroHomeSetIntPosition\s*<>\s*0\s*\)\s*\|\s*' +
        '\(\s*zeroHomeDestinationPosition\s*<>\s*0\s*\)\s*\|\s*' +
        '\(\s*zeroHomeMasterPosition\s*<>\s*0\s*\).*?' +
        'LMC_ZERO_HOME_EVIDENCE_INTERNAL') (
        "$blocker all six LASAL actual/set/destination/master positions must be zero.")
    Assert-Match $zeroHomeRtBlock (
        '(?is)zeroHomeStableSampleCount\s*:=\s*' +
        'AxisZeroHomeResult\s*\[\s*6\s*\]\s*;.*?' +
        'elsif\s+zeroHomePhase\s*=\s*LMC_ZERO_HOME_PHASE_VERIFY\s+then.*?' +
        'zeroHomeStableSampleCount\s*\+=\s*1\s*;.*?' +
        'zeroHomeStableSampleCount\s*>=\s*' +
        'LMC_ZERO_HOME_REQUIRED_STABLE.*?' +
        'LMC_ZERO_HOME_EVIDENCE_STABLE.*?' +
        'zeroHomeEvidence\s*<>\s*' +
        'LMC_ZERO_HOME_EVIDENCE_COMPLETE') (
        "$blocker three verify samples and exact 0x3B non-raw evidence are " +
        'not enforced.')
    if ([regex]::Matches(
            $zeroHomeRtBlock,
            '(?is)zeroHomeStableSampleCount\s*\+=\s*1\s*;').Count -ne 1) {
        throw "$blocker StableSampleCount must advance exactly once per valid verify RT pass."
    }

    $appliedPublishMatches = [regex]::Matches(
        $zeroHomeRtBlock,
        '(?is)sigclib_atomic_setU32\s*\(\s*' +
        'pValue\s*:=\s*#AxisZeroHomeAppliedSequence\s*,\s*' +
        'value\s*:=\s*zeroHomeRequestSequence\s*\)\s*;')
    if ($appliedPublishMatches.Count -ne 1) {
        throw "$blocker terminal applied sequence must be published exactly once."
    }
    $lastResultWriteEnd = -1
    foreach ($write in $allResultWrites) {
        $writeEnd = $write.Index + $write.Length
        if ($writeEnd -gt $lastResultWriteEnd) {
            $lastResultWriteEnd = $writeEnd
        }
    }
    if ($appliedPublishMatches[0].Index -le $lastResultWriteEnd) {
        throw "$blocker applied sequence is not the last terminal result publication."
    }
    Assert-Match $zeroHomeRtBlock (
        '(?is)if\s+zeroHomeTerminal\s+then.*?' +
        'AxisZeroHomeResult\s*\[\s*1\s*\].*?:=.*?' +
        'AxisZeroHomeResult\s*\[\s*10\s*\]\s*\$UDINT\s*:=\s*' +
        'zeroHomeCycle\s*;.*?' +
        'pValue\s*:=\s*#AxisZeroHomeAppliedSequence') (
        "$blocker applied sequence is not guarded by terminal state after completion fields.")

    Assert-Match $copyBlock (
        '(?is)\(\s*pDest\s*=\s*NIL\s*\)\s*\|\s*' +
        '\(\s*DestSize\s*<\s*128\s*\)') (
        "$blocker copy destination must reject null or fewer than 128 bytes.")
    $copyMatches128 = [regex]::Matches(
        $copyBlock,
        '(?is)_memcpy\s*\(\s*ptr1\s*:=\s*pDest\s*,\s*' +
        'ptr2\s*:=\s*#AxisZeroHomeResult\s*\[\s*0\s*\]\s*,\s*' +
        'cntr\s*:=\s*128\s*\)\s*;')
    if ($copyMatches128.Count -ne 1) {
        throw "$blocker copy must transfer the exact 32-DINT/128-byte result once."
    }
    Assert-Match $copyBlock (
        '(?is)requestSequenceBefore\s*:=\s*sigclib_atomic_getU32\s*' +
        '\(\s*pValue\s*:=\s*#AxisZeroHomeRequestSequence\s*\)\s*;.*?' +
        'appliedSequenceBefore\s*:=\s*sigclib_atomic_getU32\s*' +
        '\(\s*pValue\s*:=\s*#AxisZeroHomeAppliedSequence\s*\)\s*;.*?' +
        'requestSequenceBefore\s*<>\s*appliedSequenceBefore.*?' +
        'appliedSequenceBefore\s*=\s*0.*?' +
        'AxisZeroHomeResult\s*\[\s*0\s*\]\s*\$UDINT\s*<>\s*' +
        'OperationToken.*?' +
        'AxisZeroHomeResult\s*\[\s*22\s*\]\s*\$UDINT\s*<>\s*' +
        'appliedSequenceBefore.*?' +
        'AxisZeroHomeResult\s*\[\s*1\s*\]\s*<>\s*' +
        'LMC_ZERO_HOME_STATE_SUCCEEDED.*?' +
        'AxisZeroHomeResult\s*\[\s*1\s*\]\s*<>\s*' +
        'LMC_ZERO_HOME_STATE_FAILED.*?' +
        '_memcpy\s*\(.*?cntr\s*:=\s*128\s*\)\s*;.*?' +
        'requestSequenceAfter\s*:=\s*sigclib_atomic_getU32\s*' +
        '\(\s*pValue\s*:=\s*#AxisZeroHomeRequestSequence\s*\)\s*;.*?' +
        'appliedSequenceAfter\s*:=\s*sigclib_atomic_getU32\s*' +
        '\(\s*pValue\s*:=\s*#AxisZeroHomeAppliedSequence\s*\)\s*;.*?' +
        'requestSequenceBefore\s*=\s*requestSequenceAfter.*?' +
        'appliedSequenceBefore\s*=\s*appliedSequenceAfter.*?' +
        'requestSequenceAfter\s*=\s*appliedSequenceAfter.*?' +
        'Result\s*:=\s*0') (
        "$blocker copy is not a stable terminal-only request/applied seqlock copy.")
}

function Assert-LasalDs402SafetyDrainRetryContract {
    param(
        [string]$ControlServiceText,
        [string]$TcpText,
        [string]$Owner
    )

    $controlScan = Get-LasalScanText $ControlServiceText
    $tcpScan = Get-LasalScanText $TcpText
    $blocker = "$Owner DS402 safety-drain SAME RESERVED continuation"

    foreach ($source in @(
            @{ Name = 'LMCControlCommandService'; Text = $controlScan },
            @{ Name = 'TCPMotionInterface'; Text = $tcpScan })) {
        $matches = [regex]::Matches(
            $source.Text,
            '(?im)^\s*#define\s+LMC_OWNER_SAFETY_DRAIN_PENDING\s+(?<V>[^\s]+)\s*$')
        if ($matches.Count -ne 1 -or $matches[0].Groups['V'].Value -cne '-10') {
            throw "$blocker $($source.Name) pending sentinel must be exactly -10."
        }
    }

    $constants = [ordered]@{
        LMC_OWNER_SAFETY_PHASE_PREPARE = '1'
        LMC_OWNER_SAFETY_PHASE_RETAIN = '2'
        LMC_OWNER_SAFETY_PHASE_TERMINAL = '3'
        LMC_OWNER_SAFETY_PENDING_MAGIC = '0x5344504E'
        LMC_OWNER_SAFETY_DRAIN_TIMEOUT_MS = '1000'
        LMC_OWNER_SAFETY_PENDING_RESPONSE_OFFSET = '1252'
        LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET = '1264'
        LMC_OWNER_SAFETY_PENDING_MASK_OFFSET = '1268'
        LMC_OWNER_SAFETY_PENDING_TOKEN_OFFSET = '1272'
        LMC_OWNER_SAFETY_PENDING_GENERATION_OFFSET = '1276'
        LMC_OWNER_SAFETY_PENDING_START_OFFSET = '1280'
        LMC_OWNER_SAFETY_PENDING_SESSION_OFFSET = '1284'
        LMC_OWNER_SAFETY_PENDING_SEQUENCE_OFFSET = '1288'
        LMC_OWNER_SAFETY_PENDING_CHECK_OFFSET = '1292'
        LMC_OWNER_SAFETY_PENDING_MASK_COPY_OFFSET = '1296'
        LMC_OWNER_SAFETY_PENDING_TOKEN_COPY_OFFSET = '1300'
        LMC_OWNER_SAFETY_PENDING_GENERATION_COPY_OFFSET = '1304'
        LMC_OWNER_SAFETY_PENDING_SESSION_COPY_OFFSET = '1308'
        LMC_OWNER_SAFETY_PENDING_SEQUENCE_COPY_OFFSET = '1312'
        LMC_OWNER_SAFETY_PENDING_CHECK_COPY_OFFSET = '1316'
    }
    foreach ($name in $constants.Keys) {
        $matches = [regex]::Matches(
            $tcpScan,
            ('(?im)^\s*#define\s+' + [regex]::Escape($name) +
             '\s+(?<V>[^\s]+)\s*$'))
        if ($matches.Count -ne 1 -or
            $matches[0].Groups['V'].Value -cne $constants[$name]) {
            throw "$blocker $name must be exactly $($constants[$name])."
        }
    }

    $handle = [regex]::Match(
        $controlScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::HandleRequest.*?END_FUNCTION').Value
    $helper = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::HandleControlSafetyDrainPending.*?END_FUNCTION').Value
    $parser = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::MsgPaser.*?END_FUNCTION').Value
    $cyclic = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+TCPMotionInterface::CyWork.*?END_FUNCTION').Value
    $connection = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+VIRTUAL\s+GLOBAL\s+TCPMotionInterface::ConnSocketInfo.*?END_FUNCTION').Value
    if (@($handle, $helper, $parser, $cyclic, $connection) |
        Where-Object { [string]::IsNullOrWhiteSpace($_) }) {
        throw "$blocker service/helper/parser/cyclic/connection block is missing."
    }

    foreach ($entry in @(
            @{ Name = 'MsgPaser'; Block = $parser },
            @{ Name = 'HandleControlSafetyDrainPending'; Block = $helper },
            @{ Name = 'HandleRequest'; Block = $handle })) {
        $bytes = [Text.Encoding]::UTF8.GetByteCount(
            ($entry.Block -replace ([char]13 + [char]10), [char]10))
        if ($bytes -gt 32768) {
            throw "$blocker $($entry.Name) is $bytes UTF-8 bytes, above 32768."
        }
    }

    Assert-Match $handle (
        '(?is)ownershipDs402DrainResult\s*:=\s*' +
        'InputLatch\.RequestDs402HomeSafetyDrain\(.*?' +
        'ownershipDs402DrainReady\s*:=\s*ownershipDs402DrainResult\s*=\s*0\s*;.*?' +
        'if\s+ownershipDs402DrainReady\s*=\s*FALSE\s+then\s*' +
        'ownershipInvokeHandler\s*:=\s*FALSE\s*;\s*' +
        'ownershipSafetyPumpRejected\s*:=\s*TRUE\s*;\s*' +
        'if\s+ownershipDs402DrainResult\s*=\s*1\s+then\s*' +
        'ResponseSize\s*:=\s*LMC_OWNER_SAFETY_DRAIN_PENDING\s*;\s*' +
        'else\s*ownershipRollbackResult\s*:=\s*RollbackAxisOwnership\(.*?' +
        'Reason:=0\s*\)\s*;') (
        "$blocker result 1 must retain the tuple and only terminal drain errors roll back.")
    $pendingArm = [regex]::Match(
        $handle,
        '(?is)if\s+ownershipDs402DrainResult\s*=\s*1\s+then(?<B>.*?)else\s*ownershipRollbackResult').Groups['B'].Value
    if ([string]::IsNullOrWhiteSpace($pendingArm) -or
        $pendingArm -match
            '(?i)RollbackAxisOwnership|CommitAxisOwnership|PublishAxisOwnership|HandleAxisCommands|HandleGroupCommands|pResponseFrame') {
        throw "$blocker service pending arm performs ownership/native/wire work."
    }
    Assert-Match $handle (
        '(?is)if\s+ownershipManagedCommand\s*&\s*' +
        '\(ownershipRequestShapeValid\s*=\s*FALSE\)\s+then\s*' +
        'ownershipInvokeHandler\s*:=\s*FALSE\s*;') (
        "$blocker Control managed invalid shapes can still reach native handlers.")

    Assert-Match $helper (
        '(?is)FUNCTION\s+TCPMotionInterface::HandleControlSafetyDrainPending\s*' +
        'VAR_INPUT\s*Phase\s*:\s*UINT\s*;\s*' +
        'EffectiveAxisMask\s*:\s*UDINT\s*;\s*' +
        'AdmissionToken\s*:\s*UDINT\s*;\s*' +
        'OwnerGeneration\s*:\s*UDINT\s*;\s*END_VAR\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;') (
        "$blocker helper implementation ABI changed.")
    if ($helper -match
            '(?i)ReserveAxisOwnership\s*\(|CommitAxisOwnership\s*\(|HandleAxisCommands\s*\(|HandleGroupCommands\s*\(') {
        throw "$blocker helper reserves, commits, or invokes native handlers."
    }
    if ([regex]::Matches(
            $helper,
            '(?is)if\s+IsClientConnected\(#ControlCommands\)\s+then\s*' +
            'pendingRollbackResult\s*:=').Count -ne 2 -or
        [regex]::Matches(
            $helper,
            '(?is)if\s+IsClientConnected\(#ControlCommands\)\s+then\s*' +
            'pendingPublishResult\s*:=').Count -ne 3) {
        throw "$blocker helper Rollback/Publish calls are not channel guarded."
    }

    $shape = [regex]::Match(
        $helper,
        '(?is)case\s+CommandID\s+of(?<B>.*?)else\s*end_case\s*;').Groups['B'].Value
    $actualIds = @(Get-LasalCommandCaseIds $shape)
    $expectedIds = @('2022', '2023', '2048', '204B', '2085')
    if (@(Compare-Object $expectedIds $actualIds).Count -ne 0 -or
        $actualIds.Count -ne $expectedIds.Count) {
        throw "$blocker helper safety IDs are [$($actualIds -join ', ')]."
    }
    Assert-Match $shape (
        '(?is)0x2023:.*?\(RequestBuf\[12\]\s*=\s*0\).*?' +
        '0x2048:.*?LMC_OWNER_PROFILE_AXIS_MASK.*?' +
        '0x204B:.*?LMC_OWNER_ROBOT_AXIS_MASK.*?' +
        '0x2085:.*?LMC_OWNER_PROFILE_AXIS_MASK') (
        "$blocker exact PowerOff/Group safety shapes changed.")

    $phaseBody = [regex]::Match(
        $helper,
        '(?is)case\s+Phase\s+of(?<B>.*?)else\s*end_case\s*;').Groups['B'].Value
    $prepare = [regex]::Match(
        $phaseBody,
        '(?is)LMC_OWNER_SAFETY_PHASE_PREPARE:(?<B>.*?)LMC_OWNER_SAFETY_PHASE_RETAIN:').Groups['B'].Value
    $retain = [regex]::Match(
        $phaseBody,
        '(?is)LMC_OWNER_SAFETY_PHASE_RETAIN:(?<B>.*?)LMC_OWNER_SAFETY_PHASE_TERMINAL:').Groups['B'].Value
    $terminal = [regex]::Match(
        $phaseBody,
        '(?is)LMC_OWNER_SAFETY_PHASE_TERMINAL:(?<B>.*)').Groups['B'].Value
    if (@($prepare, $retain, $terminal) |
        Where-Object { [string]::IsNullOrWhiteSpace($_) }) {
        throw "$blocker PREPARE/RETAIN/TERMINAL phase boundary is missing."
    }
    Assert-Match $prepare (
        '(?is)pendingPrimaryValid\s*:=.*?LMC_OWNER_SAFETY_PENDING_CHECK_OFFSET.*?' +
        'pendingCopyValid\s*:=.*?LMC_OWNER_SAFETY_PENDING_CHECK_COPY_OFFSET.*?' +
        'pendingTimedOut\s*:=\s*pendingContextValid\s*&\s*' +
        '\(\(ops\.tAbsolute\s*-\s*pendingStart\)\s*>=\s*' +
        'LMC_OWNER_SAFETY_DRAIN_TIMEOUT_MS\).*?' +
        'ControlCommands\.RollbackAxisOwnership\(.*?Reason:=0\s*\)') (
        "$blocker PREPARE dual-copy validation, timeout, or exact rollback changed.")
    Assert-Match $prepare (
        '(?is)if\s*\(ActiveRequest\.Reserved\s*<>\s*1\)\s*&\s*' +
        '\(ActiveRequest\.PayloadData\[.*?' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET\]\$UDINT\s*<>\s*' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC\)\s+then.*?' +
        'if\s+pendingContextValid\s*&\s*' +
        '\(pendingTimedOut\s*=\s*FALSE\)\s+then.*?' +
        'ActiveRequest\.Reserved\s*:=\s*1\s*;\s*Result\s*:=\s*1\s*;') (
        "$blocker PREPARE cannot recover a valid dual-tail tuple after marker loss.")
    if ($prepare -match '(?i)ControlCommands\.HandleRequest|ReserveAxisOwnership|CommitAxisOwnership') {
        throw "$blocker PREPARE dispatches or finalizes ownership."
    }
    Assert-Match $retain (
        '(?is)LMC_OWNER_SAFETY_PENDING_MASK_OFFSET\]\$UDINT\s*:=\s*EffectiveAxisMask.*?' +
        'LMC_OWNER_SAFETY_PENDING_TOKEN_COPY_OFFSET\]\$UDINT\s*:=\s*AdmissionToken.*?' +
        'LMC_OWNER_SAFETY_PENDING_CHECK_OFFSET\]\$UDINT\s*:=.*?' +
        'LMC_OWNER_SAFETY_PENDING_CHECK_COPY_OFFSET\]\$UDINT\s*:=.*?' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC\s*;\s*' +
        'ActiveRequest\.Reserved\s*:=\s*1\s*;') (
        "$blocker RETAIN dual tuple/check or magic-last marker publication changed.")
    Assert-Match $terminal (
        '(?is)LMC_OWNER_SAFETY_PENDING_RESPONSE_OFFSET\]\$DINT.*?' +
        'pendingAccepted\s*:=.*?pendingFailure\s*:=.*?' +
        'ActiveRequest\.Reserved\s*:=\s*0\s*;.*?' +
        'pendingSendResponse\s*:=\s*TRUE\s*;') (
        "$blocker TERMINAL does not validate shape and clear the marker.")
    if ($terminal -match
            '(?i)RollbackAxisOwnership|CommitAxisOwnership|ReserveAxisOwnership') {
        throw "$blocker TERMINAL duplicates service ownership finalization."
    }
    Assert-Match $helper (
        '(?is)if\s+pendingSendResponse\s+then.*?' +
        'SendData\(\s*pData:=#Sendbuf\[0\]\s*,\s*udSize:=16\s*,.*?' +
        'if\s+pendingCloseRequired\s+then\s*' +
        'if\s*\(ActiveRequest\.SessionEpoch\s*<>\s*0\)\s*&\s*' +
        '\(PendingClosedSessionEpoch\s*=\s*0\)\s+then\s*' +
        'PendingClosedSessionEpoch\s*:=\s*ActiveRequest\.SessionEpoch\s*;\s*' +
        'SessionEpoch\s*\+=\s*1\s*;\s*' +
        'if\s+SessionEpoch\s*=\s*0\s+then\s*' +
        'SessionEpoch\s*:=\s*1\s*;\s*end_if\s*;\s*end_if\s*;.*?' +
        'IngressBlocked\s*:=\s*TRUE\s*;.*?' +
        'SetSocketParameter\(.*?Cmd:=100') (
        "$blocker helper close does not atomically fence and roll the failed epoch.")
    if ([regex]::Matches(
            $helper,
            '(?i)PendingClosedSessionEpoch\s*:=\s*ActiveRequest\.SessionEpoch\s*;').Count -ne 1 -or
        [regex]::Matches(
            $helper,
            '(?i)SessionEpoch\s*\+=\s*1\s*;').Count -ne 1) {
        throw "$blocker helper close epoch fence must publish and roll exactly once."
    }
    if ([regex]::Matches(
            $helper,
            '(?i)ActiveRequest\.Reserved\s*:=\s*1\s*;').Count -ne 2 -or
        $tcpScan -match
            '(?i)Sendbuf\[[^\]]+\](?:\$[A-Za-z]+)?\s*:=\s*LMC_OWNER_SAFETY_DRAIN_PENDING') {
        throw "$blocker marker publication/recovery inventory or no-wire sentinel changed."
    }

    $continuationAssignment = [regex]::Match(
        $parser,
        '(?is)controlPendingContinuation\s*:=\s*(?<B>.*?);').Groups['B'].Value
    if ([string]::IsNullOrWhiteSpace($continuationAssignment)) {
        throw "$blocker parser continuation classifier is missing."
    }
    Assert-Match $continuationAssignment (
        '(?is)^\s*\(ActiveRequest\.Reserved\s*=\s*1\)\s*\|.*?' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET\]\$UDINT\s*=\s*' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC') (
        "$blocker parser does not recover a published tail after marker loss.")
    foreach ($shapePattern in @(
            '\(CommandID\s*=\s*0x2022\)\s*&\s*\(Payload\s*=\s*16\)',
            '\(CommandID\s*=\s*0x2023\)\s*&\s*\(Payload\s*=\s*8\)',
            '\(CommandID\s*=\s*0x2048\)\s*&\s*\(Payload\s*=\s*1\)',
            '\(CommandID\s*=\s*0x204B\)\s*&\s*\(Payload\s*=\s*1\)',
            '\(CommandID\s*=\s*0x2085\)\s*&\s*\(Payload\s*=\s*16\)')) {
        Assert-Match $continuationAssignment $shapePattern (
            "$blocker parser marker recovery safety-form inventory changed.")
    }
    if ([regex]::Matches(
            $continuationAssignment,
            '(?i)CommandID\s*=\s*0x[0-9A-F]{4}').Count -ne 5 -or
        $continuationAssignment -match '(?i)0x20E7') {
        throw "$blocker parser marker recovery accepts a non-safety or large-payload form."
    }

    if ([regex]::Matches(
            $parser,
            '(?i)HandleControlSafetyDrainPending\s*\(').Count -ne 3 -or
        [regex]::Matches(
            $parser,
            '(?i)ControlCommands\.HandleRequest\s*\(').Count -ne 1) {
        throw "$blocker parser must have three helper phases and one common service call."
    }
    Assert-Match $parser (
        '(?is)controlPendingContinuation\s*:=.*?;.*?' +
        'Phase:=LMC_OWNER_SAFETY_PHASE_PREPARE.*?' +
        'if\s+controlPendingResult\s*<>\s*1\s+then\s*RETURN\s*;.*?' +
        'LMC_OWNER_SAFETY_PENDING_MASK_OFFSET.*?' +
        'LMC_OWNER_SAFETY_PENDING_TOKEN_OFFSET.*?' +
        'LMC_OWNER_SAFETY_PENDING_GENERATION_OFFSET.*?' +
        'else\s*if\s*\(CommandID\s*=\s*0x7D13\)') (
        "$blocker parser continuation does not bypass fresh Reserve.")
    Assert-Match $parser (
        '(?is)if\s+controlResponseSize\s*=\s*LMC_OWNER_SAFETY_DRAIN_PENDING\s+then.*?' +
        'Phase:=LMC_OWNER_SAFETY_PHASE_RETAIN.*?RETURN\s*;\s*' +
        'elsif\s+controlPendingContinuation\s+then.*?' +
        'LMC_OWNER_SAFETY_PENDING_RESPONSE_OFFSET\]\$DINT\s*:=\s*controlResponseSize\s*;.*?' +
        'Phase:=LMC_OWNER_SAFETY_PHASE_TERMINAL.*?RETURN\s*;') (
        "$blocker RETAIN/TERMINAL caller boundary or pending no-wire return changed.")
    $continuation = [regex]::Match(
        $parser,
        '(?is)if\s+controlPendingContinuation\s+then(?<B>.*?)else\s*if\s*\(CommandID\s*=\s*0x7D13\)').Groups['B'].Value
    if ($continuation -match '(?i)ReserveAxisOwnership|SendData\s*\(') {
        throw "$blocker continuation performs Reserve or wire send before the helper."
    }
    Assert-Match $parser (
        '(?is)controlManagedCommand\s*:=\s*' +
        'controlOwnerKind\s*<>\s*0\s*;.*?' +
        'if\s+controlManagedCommand\s*&\s*' +
        '\(controlClassifierValid\s*=\s*FALSE\)\s+then\s*' +
        'controlInvokeService\s*:=\s*FALSE\s*;') (
        "$blocker TCP managed classifier-invalid requests can reach the service.")

    $close = [regex]::Match(
        $cyclic,
        '(?is)if\s*\(ActiveRequest\.Reserved\s*<\s*2\)\s*&\s*' +
        '\(PendingClosedSessionEpoch\s*<>\s*0\).*?' +
        'PendingClosedSessionEpoch\s*:=\s*0\s*;\s*end_if\s*;').Value
    $cleanupAssignment = [regex]::Match(
        $close,
        '(?is)cleanupPendingActive\s*:=\s*(?<B>.*?);').Groups['B'].Value
    Assert-Match $cleanupAssignment (
        '(?is)^\s*\(ActiveRequest\.Reserved\s*=\s*1\)\s*\|.*?' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET\]\$UDINT\s*=\s*' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC') (
        "$blocker disconnect cleanup does not recover a retained tail marker.")
    foreach ($shapePattern in @(
            'CommandId\s*=\s*0x2022.*?PayloadLength\s*=\s*16',
            'CommandId\s*=\s*0x2023.*?PayloadLength\s*=\s*8',
            'CommandId\s*=\s*0x2048.*?PayloadLength\s*=\s*1',
            'CommandId\s*=\s*0x204B.*?PayloadLength\s*=\s*1',
            'CommandId\s*=\s*0x2085.*?PayloadLength\s*=\s*16')) {
        Assert-Match $cleanupAssignment ('(?is)' + $shapePattern) (
            "$blocker disconnect cleanup safety-form inventory changed.")
    }
    if ([regex]::Matches(
            $cleanupAssignment,
            '(?i)CommandId\s*=\s*0x[0-9A-F]{4}').Count -ne 5 -or
        $cleanupAssignment -match '(?i)0x20E7') {
        throw "$blocker disconnect cleanup accepts a non-safety form."
    }
    Assert-Match $close (
        '(?is)cleanupPendingActive\s*:=.*?;\s*' +
        'if\s+cleanupPendingActive\s*&\s*' +
        '\(ActiveRequest\.SessionEpoch\s*=\s*PendingClosedSessionEpoch\)\s+then.*?' +
        'ControlCommands\.RollbackAxisOwnership\(.*?Reason:=0\s*\).*?' +
        'Diagnostics\.NotifySessionClosed\(.*?' +
        'ControlCommands\.NotifyAxisOwnershipSessionClosed\(') (
        "$blocker disconnect exact rollback must precede both close notifications.")
    if ([regex]::Matches(
            $close,
            '(?i)ControlCommands\.RollbackAxisOwnership\s*\(').Count -ne 1 -or
        [regex]::Matches(
            $close,
            '(?i)Diagnostics\.NotifySessionClosed\s*\(').Count -ne 1 -or
        [regex]::Matches(
            $close,
            '(?i)ControlCommands\.NotifyAxisOwnershipSessionClosed\s*\(').Count -ne 1) {
        throw "$blocker disconnect rollback/notification inventory changed."
    }
    $closeEnd = $cyclic.IndexOf(
        'PendingClosedSessionEpoch := 0;',
        [StringComparison]::OrdinalIgnoreCase)
    $staleGuard = $cyclic.IndexOf(
        'if (PendingClosedSessionEpoch = 0) &',
        [StringComparison]::OrdinalIgnoreCase)
    if ($closeEnd -lt 0 -or $staleGuard -le $closeEnd -or
        [regex]::Matches(
            $cyclic,
            '(?i)PendingClosedSessionEpoch\s*=\s*0').Count -ne 4) {
        throw "$blocker close-pending epoch does not fence stale/dequeue/dispatch admission."
    }
    Assert-Match $cyclic (
        '(?is)if\s*\(PendingClosedSessionEpoch\s*=\s*0\)\s*&\s*' +
        '\(ActiveRequestValid\s*=\s*TRUE\).*?ActiveRequestValid\s*:=\s*FALSE.*?' +
        'if\s*\(PendingClosedSessionEpoch\s*=\s*0\)\s*&\s*' +
        '\(ActiveRequestValid\s*=\s*FALSE\).*?' +
        'if\s*\(PendingClosedSessionEpoch\s*=\s*0\)\s*&\s*' +
        '\(ActiveRequestValid\s*=\s*TRUE\).*?MsgPaser\(\)') (
        "$blocker stale invalidation, dequeue, or MsgPaser is not close-pending fenced.")
    $preserveAssignment = [regex]::Match(
        $connection,
        '(?is)preservePendingActive\s*:=\s*(?<B>.*?);').Groups['B'].Value
    Assert-Match $preserveAssignment (
        '(?is)^\s*\(ActiveRequest\.Reserved\s*=\s*1\)\s*\|.*?' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC_OFFSET\]\$UDINT\s*=\s*' +
        'LMC_OWNER_SAFETY_PENDING_MAGIC') (
        "$blocker fresh-owner reset does not recognize a retained tail marker.")
    foreach ($shapePattern in @(
            'CommandId\s*=\s*0x2022.*?PayloadLength\s*=\s*16',
            'CommandId\s*=\s*0x2023.*?PayloadLength\s*=\s*8',
            'CommandId\s*=\s*0x2048.*?PayloadLength\s*=\s*1',
            'CommandId\s*=\s*0x204B.*?PayloadLength\s*=\s*1',
            'CommandId\s*=\s*0x2085.*?PayloadLength\s*=\s*16')) {
        Assert-Match $preserveAssignment ('(?is)' + $shapePattern) (
            "$blocker fresh-owner pending-tail safety-form inventory changed.")
    }
    if ([regex]::Matches(
            $preserveAssignment,
            '(?i)CommandId\s*=\s*0x[0-9A-F]{4}').Count -ne 5 -or
        $preserveAssignment -match '(?i)0x20E7') {
        throw "$blocker fresh-owner preservation accepts a non-safety form."
    }
    Assert-Match $connection (
        '(?is)ActiveRequestValid\s*:=\s*FALSE\s*;.*?' +
        'preservePendingActive\s*:=.*?;\s*' +
        'if\s+preservePendingActive\s*=\s*FALSE\s+then\s*' +
        '_memset\(dest:=#ActiveRequest.*?end_if\s*;') (
        "$blocker fresh-owner reset drops the retained tuple before CyWork cleanup.")
}
function Assert-LasalAdminLmcHomeContract {
    param(
        [string]$ControlServiceText,
        [string]$TcpText,
        [string]$InputLatchText,
        [string]$Owner
    )

    $serviceScan = Get-LasalScanText $ControlServiceText
    $tcpScan = Get-LasalScanText $TcpText
    $latchScan = Get-LasalScanText $InputLatchText
    $combinedScan = $serviceScan + "`n" + $tcpScan + "`n" + $latchScan

    if ($combinedScan -match
            '(?i)\b(?:StartAxisReference|ProcessAxisReference|ReferenceState|MoveReference)\b') {
        throw "$Owner contains the retired switch-search Home implementation."
    }

    $handleRequestBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::HandleRequest.*?END_FUNCTION').Value
    $adminHandlerBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+LMCControlCommandService::HandleAdminCommands.*?END_FUNCTION').Value
    $zeroHomeHandlerBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+LMCControlCommandService::HandleAxisZeroHomeCommands.*?END_FUNCTION').Value
    $msgParserBlock = [regex]::Match(
        $tcpScan,
        '(?is)FUNCTION\s+TCPMotionInterface::MsgPaser.*?END_FUNCTION').Value
    $processBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::ProcessAxisZeroHome.*?END_FUNCTION').Value
    $reserveOwnershipBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::ReserveAxisOwnership.*?END_FUNCTION').Value
    $publishOwnershipBlock = [regex]::Match(
        $serviceScan,
        '(?is)FUNCTION\s+GLOBAL\s+LMCControlCommandService::PublishAxisOwnership\b.*?END_FUNCTION').Value
    $publishMode = Get-LasalAxisOwnershipPublishMode `
        -ControlServiceText $ControlServiceText
    if ($publishMode -ceq 'SplitCandidate') {
        $publishSplitFragments =
            Get-LasalAxisOwnershipPublishSplitFragments `
                -ControlServiceText $ControlServiceText `
                -Owner "$Owner Home receipt provider"
        $publishHomeReceiptReplayBlock =
            Get-LasalScanText $publishSplitFragments.Home
        $publishHomeReceiptPrepareBlock = $publishOwnershipBlock
        $homeReceiptReplayTailPattern =
            'end_if\s*;\s*(?=END_FUNCTION)'
    }
    else {
        $publishHomeReceiptPrepareBlock = $publishOwnershipBlock
        $publishHomeReceiptReplayBlock = $publishOwnershipBlock
        $homeReceiptReplayTailPattern =
            'end_if\s*;\s*expectedResourceKind\s*:=\s*0\s*;'
    }
    if ([string]::IsNullOrWhiteSpace($handleRequestBlock) -or
        [string]::IsNullOrWhiteSpace($adminHandlerBlock) -or
        [string]::IsNullOrWhiteSpace($zeroHomeHandlerBlock) -or
        [string]::IsNullOrWhiteSpace($msgParserBlock) -or
        [string]::IsNullOrWhiteSpace($processBlock) -or
        [string]::IsNullOrWhiteSpace($reserveOwnershipBlock) -or
        [string]::IsNullOrWhiteSpace($publishOwnershipBlock)) {
        throw (
            "$Owner router, Admin/zero-Home handler, zero-Home processor, " +
            'ownership reserve/publish, or TCP parser is missing.')
    }
    Assert-Match $serviceScan (
        '(?im)^\s*#define\s+LMC_HOME_EVIDENCE_COMPLETE\s+' +
        '0x0000003B\s*$') (
        "$Owner SetPosition-only evidence mask must remain 0x3B.")
    if ($serviceScan -match
            '(?i)\b(?:homeRawDelta|LMC_HOME_RAW_(?:WINDOW|' +
            'NEGATIVE_WINDOW))\b') {
        throw (
            "$Owner temporary SetPosition-only Home must not mirror a raw " +
            'delta success gate.')
    }
    Assert-Match $processBlock (
        '(?is)\(\s*homeLatchResult\s*\[\s*6\s*\]\s*=\s*3\s*\)\s*&\s*' +
        '\(\s*homeLatchResult\s*\[\s*7\s*\]\s*\$UDINT\s*=\s*' +
        'LMC_HOME_EVIDENCE_COMPLETE\s*\)\s*&.*?' +
        '\(\s*homeLatchResult\s*\[\s*15\s*\]\s*=\s*0\s*\).*?' +
        '\(\s*homeLatchResult\s*\[\s*16\s*\]\s*=\s*0\s*\).*?' +
        '\(\s*homeLatchResult\s*\[\s*17\s*\]\s*=\s*0\s*\).*?' +
        '\(\s*homeLatchResult\s*\[\s*18\s*\]\s*=\s*0\s*\).*?' +
        '\(\s*homeLatchResult\s*\[\s*19\s*\]\s*=\s*0\s*\).*?' +
        '\(\s*homeLatchResult\s*\[\s*20\s*\]\s*=\s*0\s*\)') (
        "$Owner service does not require three samples, exact 0x3B evidence, " +
        'and six zero coordinates.')
    Assert-Match $zeroHomeHandlerBlock (
        '(?s)ResponseSize\s*:=\s*-1\s*;.*?' +
        'pRequest\s*:=\s*pRequestFrame\s*\+\s*8\s*;.*?' +
        'RequestSize\s*:=\s*RequestFrameSize\s*-\s*8\s*;') (
        "$Owner zero-Home handler does not preserve fail-closed payload aliasing.")
    Assert-Match $serviceScan '(?im)^\s*#define\s+LMC_OWNER_GLOBAL_SLOTS\s+28\s*$' (
        "$Owner ownership global-slot layout drifted.")
    Assert-Match $serviceScan '(?im)^\s*#define\s+LMC_OWNER_AXIS_STRIDE\s+36\s*$' (
        "$Owner ownership per-axis stride drifted.")
    Assert-Match $serviceScan '(?im)^\s*#define\s+LMC_OWNER_AXIS_COUNT\s+9\s*$' (
        "$Owner ownership axis-count layout drifted.")
    Assert-Match $serviceScan (
        '(?s)ZeroHomeState\s*\[\s*33\s*\].*?' +
        'ZeroHomeState\s*\[\s*50\s*\].*?' +
        'ZeroHomeState\s*\[\s*51\s*\]\$UDINT\s*:=\s*' +
        'LMC_HOME_RECORD_MAGIC') (
        "$Owner retained LMC_Home generation and integrity slots drifted.")
    $homeReceiptConstants = [ordered]@{
        LMC_HOME_OWNER_RECEIPT_MAGIC = '0x484F4D50'
        LMC_HOME_OWNER_RECEIPT_PREPARED = '1'
        LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY = '2'
        LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER = '3'
        LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON = '4'
        LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD = '5'
        LMC_HOME_OWNER_RECEIPT_COMPLETE = '6'
    }
    foreach ($homeReceiptConstant in $homeReceiptConstants.GetEnumerator()) {
        Assert-Match $serviceScan (
            '(?im)^\s*#define\s+' + [regex]::Escape($homeReceiptConstant.Key) +
            '\s+' + [regex]::Escape($homeReceiptConstant.Value) + '\s*$') (
            "$Owner Home owner-receipt constant $($homeReceiptConstant.Key) drifted.")
    }

    $routePattern = (
        '(?s)0x7D00,\s*0x7D10,\s*0x7D12,\s*0x7D13,\s*' +
        '0x7D18,\s*0x7D19,\s*0x7D20,\s*0x7D22:')
    Assert-Match $handleRequestBlock (
        $routePattern + '.*?HandleAdminCommands\s*\(') (
        "$Owner control service does not own the complete 0x7D13/18/19 triad.")
    Assert-Match $msgParserBlock (
        $routePattern + '.*?ControlCommands\.HandleRequest\s*\(') (
        "$Owner TCP parser does not delegate the complete 0x7D13/18/19 triad.")
    Assert-Match $adminHandlerBlock (
        '(?s)0x7D13\s*,\s*0x7D18\s*,\s*0x7D19\s*:\s*' +
        'ResponseSize\s*:=\s*HandleAxisZeroHomeCommands\s*\(') (
        "$Owner Admin handler does not delegate the complete zero-Home triad.")
    Assert-ExactLasalCommandCaseIds `
        -FunctionBlock $zeroHomeHandlerBlock `
        -Owner 'LMCControlCommandService.HandleAxisZeroHomeCommands' `
        -ExpectedCommandIds @('7D13', '7D18', '7D19')

    $startBlock = [regex]::Match(
        $zeroHomeHandlerBlock,
        '(?ims)^\s*0x7D13\s*:\s*$.*?(?=^\s*0x7D18\s*:\s*$)').Value
    $outcomeBlock = [regex]::Match(
        $zeroHomeHandlerBlock,
        '(?ims)^\s*0x7D18\s*:\s*$.*?(?=^\s*0x7D19\s*:\s*$)').Value
    $retireBlock = [regex]::Match(
        $zeroHomeHandlerBlock,
        '(?ims)^\s*0x7D19\s*:\s*$.*?(?=^\s*else\s*$)').Value
    if ([string]::IsNullOrWhiteSpace($startBlock) -or
        [string]::IsNullOrWhiteSpace($outcomeBlock) -or
        [string]::IsNullOrWhiteSpace($retireBlock)) {
        throw "$Owner exact 0x7D13/18/19 cases were not found."
    }

    Assert-Match $startBlock (
        '(?s)RequestSize\s*>=\s*56.*?' +
        'adminDiagnosticsBuild\s*:=\s*\(pRequest\s*\+\s*8\)\^\$UDINT.*?' +
        'adminBootId\s*:=\s*\(pRequest\s*\+\s*12\)\^\$UDINT.*?' +
        'adminMapRevision\s*:=\s*\(pRequest\s*\+\s*16\)\^\$UDINT.*?' +
        'adminClientIntentId0\s*:=\s*\(pRequest\s*\+\s*20\)\^\$UDINT.*?' +
        'adminClientIntentId3\s*:=\s*\(pRequest\s*\+\s*32\)\^\$UDINT.*?' +
        'adminHomeSemanticMode\s*:=\s*\(pRequest\s*\+\s*36\)\^\$UINT.*?' +
        'adminHomeReserved\s*:=\s*\(pRequest\s*\+\s*38\)\^\$UINT.*?' +
        'adminHomeExpectedActualPosition\s*:=\s*\(pRequest\s*\+\s*40\)\^\$DINT.*?' +
        'adminHomeTargetPosition\s*:=\s*\(pRequest\s*\+\s*44\)\^\$DINT.*?' +
        'adminHomeTimeoutMs\s*:=\s*\(pRequest\s*\+\s*48\)\^\$UDINT.*?' +
        'adminHomeExecuteToken\s*:=\s*\(pRequest\s*\+\s*52\)\^\$UDINT.*?' +
        'RequestSize\s*<>\s*56') (
        "$Owner 0x7D13 is not the exact 56-byte current-position-zero schema.")
    Assert-Match $startBlock (
        '(?s)adminHomeSemanticMode\s*<>\s*1.*?' +
        'adminHomeReserved\s*<>\s*0.*?' +
        'adminHomeTargetPosition\s*<>\s*0.*?' +
        'adminHomeTimeoutMs\s*<\s*100.*?' +
        'adminHomeTimeoutMs\s*>\s*5000.*?' +
        'adminHomeExecuteToken\s*<>\s*0x454D4F48') (
        "$Owner 0x7D13 does not fail closed outside CurrentPositionZero/HOME.")
    Assert-Match $startBlock (
        '(?s)LMC_ADMIN_AXIS_HOME_ENABLED\s*=\s*FALSE.*?' +
        'InputLatch\.SubmitAxisZeroHome\(.*?' +
        'ExpectedActualPosition:=adminHomeExpectedActualPosition') (
        "$Owner 0x7D13 gate or RT stale-position-guarded submit is missing.")
    Assert-Match $startBlock (
        '(?s)\(pResponseFrame\s*\+\s*2\)\^\$UINT\s*:=\s*24.*?' +
        '\(pResponseFrame\s*\+\s*24\)\^\$UINT\s*:=\s*adminHomeSemanticMode.*?' +
        '\(pResponseFrame\s*\+\s*26\)\^\$UINT\s*:=\s*0.*?' +
        '\(pResponseFrame\s*\+\s*28\)\^\$UDINT\s*:=\s*0.*?' +
        'ResponseSize\s*:=\s*32') (
        "$Owner 0x7D13 ACK is not the exact 24-byte LMC_Home response.")
    Assert-Match $startBlock (
        '(?is)adminHomeEmptyValid\s*:=\s*TRUE\s*;\s*' +
        'if\s+adminHomeRecordState\s*=\s*LMC_HOME_RECORD_EMPTY\s+then\s*' +
        'adminHomeStateIndex\s*:=\s*1\s*;\s*' +
        'while\s+adminHomeStateIndex\s*<=\s*63\s+do\s*' +
        'if\s*\(adminHomeStateIndex\s*<>\s*50\)\s*&\s*' +
        '\(ZeroHomeState\[adminHomeStateIndex\]\s*<>\s*0\)\s+then\s*' +
        'adminHomeEmptyValid\s*:=\s*FALSE\s*;.*?' +
        'adminHomeStateIndex\s*\+=\s*1\s*;.*?' +
        'elsif\s*\(adminHomeRecordState\s*=\s*LMC_HOME_RECORD_EMPTY\)\s*&\s*' +
        '\(adminHomeEmptyValid\s*=\s*FALSE\)\s+then\s*' +
        'adminDetailCode\s*:=\s*42') (
        "$Owner 0x7D13 does not reject a public-empty record with retained ledger state.")

    Assert-Match $outcomeBlock (
        '(?s)RequestSize\s*>=\s*56.*?' +
        '\(pRequest\s*\+\s*20\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*24\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*44\)\^\$UINT.*?' +
        '\(pRequest\s*\+\s*48\)\^\$DINT.*?' +
        '\(pRequest\s*\+\s*52\)\^\$DINT.*?' +
        'RequestSize\s*<>\s*56') (
        "$Owner 0x7D18 exact durable identity offsets are missing.")
    Assert-Match $outcomeBlock (
        '(?s)ResponseCapacity\s*<\s*152.*?' +
        '\(pResponseFrame\s*\+\s*2\)\^\$UINT\s*:=\s*144.*?' +
        '\(pResponseFrame\s*\+\s*148\)\^\$UDINT.*?' +
        'ResponseSize\s*:=\s*152') (
        "$Owner 0x7D18 does not publish the complete 144-byte retained record.")
    Assert-Match $outcomeBlock (
        '(?is)case\s+Reference\s+of\s*' +
        '1\s*:\s*adminHomeAxisMask\s*:=\s*0x00000001\s*;\s*' +
        '2\s*:\s*adminHomeAxisMask\s*:=\s*0x00000002\s*;\s*' +
        '3\s*:\s*adminHomeAxisMask\s*:=\s*0x00000004\s*;\s*' +
        '4\s*:\s*adminHomeAxisMask\s*:=\s*0x00000008\s*;.*?' +
        'adminHomeStateConsistent\s*:=\s*FALSE\s*;\s*' +
        'if\s+ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_RUNNING\s+then\s*' +
        'adminHomeStateConsistent\s*:=.*?' +
        'ZeroHomeState\[39\]\s*>=\s*LMC_HOME_ENGINE_WAIT_RT.*?' +
        'ZeroHomeState\[39\]\s*<=\s*LMC_HOME_ENGINE_FINALIZE.*?' +
        'ZeroHomeState\[34\]\$UDINT\s*<>\s*0.*?' +
        'ZeroHomeState\[35\]\$UDINT\s*<>\s*0.*?' +
        'ZeroHomeState\[36\]\$UDINT\s*<>\s*0.*?' +
        'ZeroHomeState\[37\]\$UDINT\s*<>\s*0.*?' +
        'ZeroHomeState\[38\]\$UDINT\s*=\s*adminHomeAxisMask.*?' +
        'OwnershipState\[7\]\$UDINT\s*=\s*ZeroHomeState\[34\]\$UDINT.*?' +
        'OwnershipState\[8\]\$UDINT\s*=\s*ZeroHomeState\[35\]\$UDINT.*?' +
        'OwnershipState\[9\]\$UDINT\s*=\s*ZeroHomeState\[38\]\$UDINT\s*\)\s*;') (
        "$Owner 0x7D18 Running outcome is not fenced by the retained engine and owner tuple.")
    Assert-Match $outcomeBlock (
        '(?is)elsif\s+adminHomeTerminal\s+then\s*' +
        'adminHomeStateConsistent\s*:=.*?' +
        'ZeroHomeState\[39\]\s*=\s*LMC_HOME_ENGINE_TERMINAL.*?' +
        'ZeroHomeState\[57\]\s*=\s*ZeroHomeState\[0\].*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED.*?' +
        'LMC_HOME_FLAG_TERMINAL_PUBLISHED.*?' +
        'ZeroHomeState\[47\]\s*=\s*0.*?' +
        'ZeroHomeState\[47\]\s*=\s*1.*?' +
        'LMC_HOME_FLAG_EXACT_RT_TERMINAL.*?' +
        'case\s+ZeroHomeState\[0\]\s+of.*?' +
        'LMC_HOME_RECORD_SUCCEEDED\s*:.*?' +
        'LMC_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'LMC_HOME_RECORD_FAILED\s*,\s*LMC_HOME_RECORD_ABORTED\s*:.*?' +
        'LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE.*?' +
        'LMC_HOME_RECORD_QUARANTINED\s*:.*?' +
        'LMC_OWNER_REPORT_QUARANTINE.*?' +
        'elsif\s*\(\(ZeroHomeState\[0\]\s*<>\s*LMC_HOME_RECORD_RUNNING\)\s*&\s*' +
        '\(adminHomeTerminal\s*=\s*FALSE\)\)\s*\|\s*' +
        '\(adminHomeStateConsistent\s*=\s*FALSE\)\s+then\s*' +
        'adminDetailCode\s*:=\s*35') (
        "$Owner 0x7D18 terminal outcome does not prove ledger consistency and report kind.")
    Assert-Match $retireBlock (
        '(?s)ResponseCapacity\s*<\s*152.*?' +
        'RequestSize\s*>=\s*60.*?' +
        '\(pRequest\s*\+\s*56\)\^\$UDINT.*?' +
        'RequestSize\s*<>\s*60.*?' +
        '\(pResponseFrame\s*\+\s*2\)\^\$UINT\s*:=\s*144.*?' +
        '\(pResponseFrame\s*\+\s*148\)\^\$UDINT.*?' +
        'ResponseSize\s*:=\s*152') (
        "$Owner 0x7D19 does not use exact-generation terminal retirement.")

    Assert-Match $reserveOwnershipBlock (
        '(?is)if\s*\(ZeroHomeState\[60\]\s*=\s*0\)\s*&\s*' +
        '\(\(ZeroHomeState\[61\]\s*<>\s*0\)\s*\|\s*' +
        '\(ZeroHomeState\[62\]\s*<>\s*0\)\s*\|\s*' +
        '\(ZeroHomeState\[63\]\s*<>\s*0\)\)\s+then\s*' +
        'if\s*\(ZeroHomeState\[51\]\$UDINT\s*=\s*' +
        'LMC_HOME_RECORD_MAGIC\)\s*&\s*' +
        '\(ZeroHomeState\[33\]\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[39\]\s*=\s*LMC_HOME_ENGINE_FINALIZE\)\s*&\s*' +
        '\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_INTENT\)\s*<>\s*0\)\s*&\s*' +
        '\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED\)\s*=\s*0\)\s+then\s*' +
        'Result\s*:=\s*-2\s*;\s*else\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
        'Result\s*:=\s*-3\s*;\s*end_if\s*;\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'if\s+ZeroHomeState\[60\]\s*<>\s*0\s+then') (
        "$Owner ReserveAxisOwnership does not distinguish a recoverable " +
        'pre-magic Home receipt tail from malformed retained state.')

    $reserveReceiptMatch = [regex]::Match(
        $reserveOwnershipBlock,
        ('(?is)if\s+ZeroHomeState\[60\]\s*<>\s*0\s+then' +
         '(?<Body>.*?)end_if\s*;\s*effectiveAxisMask\s*:=\s*RequestedAxisMask\s*;'))
    if (-not $reserveReceiptMatch.Success) {
        throw "$Owner ReserveAxisOwnership Home receipt blocker was not found."
    }
    $reserveReceiptBlock = $reserveReceiptMatch.Groups['Body'].Value
    foreach ($reserveReceiptPattern in @(
            'ZeroHomeState\[60\]\$UDINT\s*<>\s*LMC_HOME_OWNER_RECEIPT_MAGIC',
            'ZeroHomeState\[51\]\$UDINT\s*<>\s*LMC_HOME_RECORD_MAGIC',
            'ZeroHomeState\[33\]\$UDINT\s*=\s*0',
            'ZeroHomeState\[63\]\$UDINT\s*<>\s*ZeroHomeState\[33\]\$UDINT',
            'ZeroHomeState\[62\]\s*<>\s*0',
            'ZeroHomeState\[61\]\s*<\s*LMC_HOME_OWNER_RECEIPT_PREPARED',
            'ZeroHomeState\[61\]\s*>\s*LMC_HOME_OWNER_RECEIPT_COMPLETE')) {
        Assert-Match $reserveReceiptBlock $reserveReceiptPattern (
            "$Owner ReserveAxisOwnership corrupt receipt fence is incomplete: $reserveReceiptPattern")
    }
    $reserveIncompleteReceiptMatch = [regex]::Match(
        $reserveReceiptBlock,
        ('(?is)if\s*\(ZeroHomeState\[61\]\s*<>\s*' +
         'LMC_HOME_OWNER_RECEIPT_COMPLETE\)(?<Body>.*?)' +
         'Result\s*:=\s*-2\s*;\s*RETURN\s*;'))
    if (-not $reserveIncompleteReceiptMatch.Success) {
        throw "$Owner ReserveAxisOwnership incomplete Home receipt blocker was not found."
    }
    foreach ($reserveIncompletePattern in @(
            'ZeroHomeState\[47\]\s*<>\s*1',
            'LMC_HOME_FLAG_TERMINAL_PUBLISHED\)\s*=\s*0',
            'ZeroHomeState\[39\]\s*<>\s*LMC_HOME_ENGINE_TERMINAL',
            'ZeroHomeState\[0\]\s*<\s*LMC_HOME_RECORD_SUCCEEDED',
            'ZeroHomeState\[0\]\s*>\s*LMC_HOME_RECORD_ABORTED',
            'ZeroHomeState\[0\]\s*<>\s*ZeroHomeState\[57\]')) {
        Assert-Match $reserveIncompleteReceiptMatch.Groups['Body'].Value `
            $reserveIncompletePattern (
            "$Owner ReserveAxisOwnership incomplete receipt fence is missing: $reserveIncompletePattern")
    }

    $homeReceiptPrepareMatch = [regex]::Match(
        $publishHomeReceiptPrepareBlock,
        ('(?is)if\s*\(expectedCommandId\s*=\s*0x7D13\)\s*&\s*' +
         '\(expectedOwnerKind\s*=\s*LMC_OWNER_KIND_LMC_HOME\)\s*&\s*' +
         '\(expectedResourceKind\s*=\s*LMC_OWNER_RESOURCE_LMC_HOME_ENGINE\)\s*&\s*' +
         '\(expectedAdmissionMode\s*=\s*LMC_OWNER_ADMISSION_LIFECYCLE\).*?' +
         '(?<Body>.*?)' +
         'end_if\s*;\s*axisIndex\s*:=\s*1\s*;\s*' +
         'while\s+axisIndex\s*<=\s*LMC_OWNER_AXIS_COUNT\s+do'))
    if (-not $homeReceiptPrepareMatch.Success) {
        throw "$Owner normal Home receipt-prepare branch was not found."
    }
    $homeReceiptPrepareBlock = $homeReceiptPrepareMatch.Groups['Body'].Value
    $homeReceiptPrepareGuard = [regex]::Match(
        $homeReceiptPrepareBlock,
        ('(?is)if\s*\(homeReceiptAxisMaskValid\s*=\s*FALSE\).*?' +
         '\(ZeroHomeState\[60\]\s*<>\s*0\)\s+then'))
    if (-not $homeReceiptPrepareGuard.Success) {
        throw "$Owner Home receipt prepare does not use slot 60 as its only commit-word guard."
    }
    if ($homeReceiptPrepareGuard.Value -match 'ZeroHomeState\[(?:61|62|63)\]') {
        throw "$Owner Home receipt prepare rejects a recoverable magic-zero partial tail."
    }
    Assert-Match $homeReceiptPrepareBlock (
        '(?is)ZeroHomeState\[60\]\s*:=\s*0\s*;\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_PREPARED\s*;\s*' +
        'ZeroHomeState\[62\]\s*:=\s*0\s*;\s*' +
        'ZeroHomeState\[63\]\$UDINT\s*:=\s*ZeroHomeState\[33\]\$UDINT\s*;\s*' +
        'ZeroHomeState\[60\]\$UDINT\s*:=\s*LMC_HOME_OWNER_RECEIPT_MAGIC\s*;\s*' +
        'Result\s*:=\s*0\s*;\s*RETURN\s*;') (
        "$Owner Home receipt is not prepared magic-last before returning result 0.")

    $homeReceiptReplayMatch = [regex]::Match(
        $publishHomeReceiptReplayBlock,
        ('(?is)if\s+ZeroHomeState\[60\]\$UDINT\s*=\s*' +
         'LMC_HOME_OWNER_RECEIPT_MAGIC\s+then(?<Body>.*?)' +
         $homeReceiptReplayTailPattern))
    if (-not $homeReceiptReplayMatch.Success) {
        throw "$Owner Home receipt replay/cleanup branch was not found."
    }
    $homeReceiptReplayBlock = $homeReceiptReplayMatch.Groups['Body'].Value
    Assert-Match $homeReceiptReplayBlock (
        '(?is)homeReceiptCallMatches\s*:=\s*' +
        '\(ZeroHomeState\[34\]\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(ZeroHomeState\[35\]\$UDINT\s*=\s*OwnerGeneration\)\s*&\s*' +
        '\(ZeroHomeState\[38\]\$UDINT\s*=\s*AxisMask\)\s*&\s*' +
        '\(ZeroHomeState\[58\]\s*=\s*TO_DINT\(ReportKind\)\)\s*&\s*' +
        '\(ZeroHomeState\[57\]\$UDINT\s*=\s*ReportValue0\)\s*&\s*' +
        '\(ZeroHomeState\[31\]\$UDINT\s*=\s*ReportValue1\)\s*&\s*' +
        '\(ZeroHomeState\[46\]\$UDINT\s*=\s*ObservationCycle\)\s*;\s*' +
        'homeReceiptTerminalComplete\s*:=.*?' +
        'ZeroHomeState\[51\]\$UDINT\s*=\s*LMC_HOME_RECORD_MAGIC.*?' +
        'ZeroHomeState\[63\]\$UDINT\s*=\s*ZeroHomeState\[33\]\$UDINT.*?' +
        'ZeroHomeState\[61\]\s*=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE.*?' +
        'ZeroHomeState\[39\]\s*=\s*LMC_HOME_ENGINE_TERMINAL.*?' +
        'ZeroHomeState\[57\]\s*=\s*ZeroHomeState\[0\].*?' +
        'ZeroHomeState\[47\]\s*=\s*1.*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED.*?' +
        'LMC_HOME_FLAG_TERMINAL_PUBLISHED.*?' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*=\s*0.*?' +
        'LMC_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE.*?' +
        'if\s+homeReceiptCallMatches\s+then') (
        "$Owner completed Home receipt routing is not bound to the exact " +
        'incoming publish tuple and authenticated terminal proof.')
    Assert-Match $homeReceiptReplayBlock (
        '(?is)homeReceiptExact\s*:=.*?' +
        'homeReceiptAxisMaskValid.*?' +
        'ZeroHomeState\[51\]\$UDINT\s*=\s*LMC_HOME_RECORD_MAGIC.*?' +
        'ZeroHomeState\[63\]\$UDINT\s*=\s*ZeroHomeState\[33\]\$UDINT.*?' +
        'ZeroHomeState\[62\]\s*=\s*0.*?' +
        'ZeroHomeState\[34\]\$UDINT\s*=\s*AdmissionToken.*?' +
        'ZeroHomeState\[35\]\$UDINT\s*=\s*OwnerGeneration.*?' +
        'ZeroHomeState\[38\]\$UDINT\s*=\s*AxisMask.*?' +
        'ZeroHomeState\[58\]\s*=\s*TO_DINT\(ReportKind\).*?' +
        'ZeroHomeState\[57\]\$UDINT\s*=\s*ReportValue0.*?' +
        'ZeroHomeState\[31\]\$UDINT\s*=\s*ReportValue1.*?' +
        'ZeroHomeState\[46\]\$UDINT\s*=\s*ObservationCycle.*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_INTENT.*?' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*=\s*0.*?' +
        'homeReceiptPhase\s*>=\s*LMC_HOME_OWNER_RECEIPT_PREPARED.*?' +
        'homeReceiptPhase\s*<=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE.*?' +
        'if\s+homeReceiptExact\s*=\s*FALSE\s+then.*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;') (
        "$Owner Home receipt replay is not fenced by the immutable operation tuple.")
    Assert-Match $homeReceiptReplayBlock (
        '(?is)if\s*\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED\)\s*=\s*0\s+then\s*' +
        'if\s+homeReceiptPhase\s*<>\s*LMC_HOME_OWNER_RECEIPT_PREPARED\s+then.*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'Result\s*:=\s*0\s*;\s*RETURN\s*;') (
        "$Owner unaccepted Home receipt replay can mutate ownership surfaces.")
    Assert-Match $homeReceiptReplayBlock (
        '(?is)LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s*:\s*' +
        'homeReceiptSurfaceValid\s*:=\s*homeReceiptIdentityPost\s*&\s*' +
        'homeReceiptObserverPost\s*&\s*homeReceiptRecordPre\s*&\s*' +
        '\(homeReceiptSingletonPre\s*\|\s*' +
        '\(\(OwnershipState\[7\]\$UDINT\s*=\s*0\)\s*&\s*' +
        '\(OwnershipState\[8\]\$UDINT\s*=\s*OwnerGeneration\)\s*&\s*' +
        '\(OwnershipState\[9\]\$UDINT\s*=\s*AxisMask\)\)\s*\|\s*' +
        '\(\(OwnershipState\[7\]\$UDINT\s*=\s*0\)\s*&\s*' +
        '\(OwnershipState\[8\]\$UDINT\s*=\s*0\)\s*&\s*' +
        '\(OwnershipState\[9\]\$UDINT\s*=\s*AxisMask\)\)\s*\|\s*' +
        'homeReceiptSingletonPost\s*\)\s*;\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s*:\s*' +
        'homeReceiptSurfaceValid\s*:=\s*homeReceiptIdentityPost\s*&\s*' +
        'homeReceiptObserverPost\s*&\s*homeReceiptSingletonPost') (
        "$Owner Home singleton phase cannot resume its exact prefix states before record cleanup.")
    Assert-Match $homeReceiptReplayBlock (
        '(?is)if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_CLEAR_IDENTITY\s*;.*?' +
        '_memset\(dest:=#OwnershipIdentityState\[identityHeaderBase\].*?' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_CLEAR_OBSERVER\s*;.*?' +
        '_memset\(dest:=#OwnershipObserverState\[observerBase\].*?' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_CLEAR_SINGLETON\s*;\s*' +
        'OwnershipState\[7\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[8\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[9\]\s*:=\s*0\s*;\s*end_if\s*;\s*' +
        'if\s+homeReceiptPhase\s*<=\s*' +
        'LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s+then\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_CLEAR_RECORD\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*35\]\s*:=\s*0\s*;\s*' +
        '_memset\(dest:=#OwnershipState\[recordBase\].*?' +
        'OwnershipState\[recordBase\]\s*:=\s*axisIndex\s*;\s*' +
        'ZeroHomeState\[61\]\s*:=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*35\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)') (
        "$Owner Home receipt cleanup order or record magic-last commit drifted.")
    Assert-Match $homeReceiptReplayBlock (
        '(?is)if\s*\(ZeroHomeState\[61\]\s*<>\s*' +
        'LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s*\|.*?' +
        'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\).*?' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;.*?' +
        'Result\s*:=\s*1\s*;\s*RETURN\s*;') (
        "$Owner Home receipt cleanup does not require COMPLETE plus record commit before result 1.")
    Assert-Match $homeReceiptReplayBlock (
        '(?is)Result\s*:=\s*1\s*;\s*RETURN\s*;\s*' +
        'elsif\s+homeReceiptTerminalComplete\s*=\s*FALSE\s+then\s*' +
        'OwnershipState\[24\]\s*:=\s*1\s*;\s*' +
        'Result\s*:=\s*-3\s*;\s*RETURN\s*;\s*end_if\s*;\s*$') (
        "$Owner completed Home receipt does not fall through for a different " +
        'incoming owner, or incomplete/corrupt receipt replay is not fail closed.')

    $safetyPumpMatch = [regex]::Match(
        $handleRequestBlock,
        ('(?is)if\s+ownershipArmed\s*&\s*ownershipInvokeHandler\s*&\s*' +
         '\(ownershipValidationResult\s*=\s*0\)\s*&\s*' +
         '\(ownershipAdmissionMode\s*=\s*LMC_OWNER_ADMISSION_SAFETY\)\s*then' +
         '(?<Body>.*?)' +
         'end_if\s*;\s*if\s+ownershipInvokeHandler\s+then\s*' +
         'case\s+CommandId\s+of'))
    if (-not $safetyPumpMatch.Success) {
        throw "$Owner exact Home safety-pump block was not found."
    }
    $safetyPumpBlock = $safetyPumpMatch.Groups['Body'].Value
    $homeWorkPredicateMatch = [regex]::Match(
        $safetyPumpBlock,
        '(?is)ownershipHomeWorkSuspect\s*:=\s*(?<Body>.*?);')
    if (-not $homeWorkPredicateMatch.Success) {
        throw "$Owner Home safety live-work predicate was not found."
    }
    $homeWorkPredicate = $homeWorkPredicateMatch.Groups['Body'].Value
    foreach ($workPattern in @(
            'ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_RUNNING',
            'ZeroHomeState\[39\]\s*>=\s*LMC_HOME_ENGINE_WAIT_RT',
            'ZeroHomeState\[39\]\s*<=\s*LMC_HOME_ENGINE_FINALIZE',
            'ZeroHomeState\[34\]\$UDINT\s*<>\s*0',
            'ZeroHomeState\[35\]\$UDINT\s*<>\s*0',
            'ZeroHomeState\[38\]\$UDINT\s*<>\s*0',
            'OwnershipState\[7\]\$UDINT\s*<>\s*0',
            'OwnershipState\[8\]\$UDINT\s*<>\s*0',
            'OwnershipState\[9\]\$UDINT\s*<>\s*0')) {
        Assert-Match $homeWorkPredicate $workPattern (
            "$Owner Home safety live-work predicate is incomplete: $workPattern")
    }
    $homeTerminalPredicates = [regex]::Matches(
        $safetyPumpBlock,
        '(?is)ownershipHomeTerminalProof\s*:=\s*(?<Body>.*?);')
    if ($homeTerminalPredicates.Count -ne 2) {
        throw (
            "$Owner Home safety terminal-proof count is " +
            "$($homeTerminalPredicates.Count), expected pre-pump plus post-pump proof.")
    }
    foreach ($terminalPredicate in $homeTerminalPredicates) {
        $terminalBody = $terminalPredicate.Groups['Body'].Value
        foreach ($terminalPattern in @(
                'ZeroHomeState\[0\]\s*>=\s*LMC_HOME_RECORD_SUCCEEDED',
                'ZeroHomeState\[0\]\s*<=\s*LMC_HOME_RECORD_QUARANTINED',
                'ZeroHomeState\[39\]\s*=\s*LMC_HOME_ENGINE_TERMINAL',
                'ZeroHomeState\[57\]\s*=\s*ZeroHomeState\[0\]',
                'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED',
                'LMC_HOME_FLAG_TERMINAL_PUBLISHED',
                'ZeroHomeState\[47\]\s*=\s*0',
                'ZeroHomeState\[47\]\s*=\s*1',
                'LMC_HOME_FLAG_EXACT_RT_TERMINAL')) {
            Assert-Match $terminalBody $terminalPattern (
                "$Owner Home safety terminal proof is incomplete: $terminalPattern")
        }
        Assert-Match $terminalBody (
            '(?is)\(ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_QUARANTINED\)\s*\|\s*' +
            '\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
            'LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*<>\s*0\)\s*\|\s*' +
            '\(\(ZeroHomeState\[60\]\$UDINT\s*=\s*' +
            'LMC_HOME_OWNER_RECEIPT_MAGIC\)\s*&\s*' +
            '\(ZeroHomeState\[61\]\s*=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s*&\s*' +
            '\(ZeroHomeState\[62\]\s*=\s*0\)\s*&\s*' +
            '\(ZeroHomeState\[63\]\$UDINT\s*=\s*ZeroHomeState\[33\]\$UDINT\)\)') (
            "$Owner nonquarantine non-preemption safety terminal lacks a complete receipt proof.")
    }
    Assert-Match $safetyPumpBlock (
        '(?is)if\s+ownershipHomeWorkSuspect\s*&\s*' +
        '\(ownershipHomeTerminalProof\s*=\s*FALSE\)\s+then.*?' +
        'LMC_HOME_FLAG_SAFETY_DISPATCH_READY.*?' +
        'ProcessAxisZeroHome\(\)\s*;.*?' +
        'if\s*\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_SAFETY_DISPATCH_READY\)\s*=\s*0\)\s*&\s*' +
        '\(ownershipHomeTerminalProof\s*=\s*FALSE\)\s+then.*?' +
        'RollbackAxisOwnership\(.*?Reason\s*:=\s*0\s*\)\s*;.*?' +
        'ownershipInvokeHandler\s*:=\s*FALSE\s*;.*?' +
        'ownershipSafetyPumpRejected\s*:=\s*TRUE\s*;.*?' +
        'else.*?LMC_HOME_FLAG_SAFETY_DISPATCH_READY.*?' +
        'elsif\s+ownershipHomeTerminalProof\s+then.*?' +
        'LMC_HOME_FLAG_SAFETY_DISPATCH_READY') (
        "$Owner safety dispatch is not dominated by READY or exact terminal proof.")
    Assert-Match $handleRequestBlock (
        '(?is)if\s+ownershipArmed\s*&\s*' +
        '\(ownershipSafetyPumpRejected\s*=\s*FALSE\)\s+then\s*' +
        'ownershipDispatchEntered\s*:=' ) (
        "$Owner rejected Home safety pump can still enter dispatch accounting.")
    Assert-Match $handleRequestBlock (
        '(?is)if\s+ownershipArmed\s*&\s*' +
        '\(ownershipSafetyPumpRejected\s*=\s*FALSE\)\s*&\s*' +
        '\(ownershipValidationResult\s*=\s*0\)\s+then') (
        "$Owner rejected Home safety pump can still reach ownership commit/rollback postlude.")
    Assert-Match $processBlock (
        '(?is)homePreemptionSnapshot\s*:\s*ARRAY\s*\[\s*0\.\.199\s*\]\s*' +
        'OF\s+USINT\s*;.*?' +
        'homeAdmissionToken\s*:=\s*ZeroHomeState\[34\]\$UDINT\s*;\s*' +
        'homeOwnerGeneration\s*:=\s*ZeroHomeState\[35\]\$UDINT\s*;\s*' +
        'homeSessionEpoch\s*:=\s*ZeroHomeState\[36\]\$UDINT\s*;\s*' +
        'homeRequestSequence\s*:=\s*ZeroHomeState\[37\]\$UDINT\s*;\s*' +
        'homeAxisMask\s*:=\s*ZeroHomeState\[38\]\$UDINT\s*;.*?' +
        'homePreemptionResult\s*:=\s*CopyAxisOwnershipPreemption\(\s*' +
        'PreemptedAdmissionToken\s*:=\s*homeAdmissionToken\s*,\s*' +
        'PreemptedOwnerGeneration\s*:=\s*homeOwnerGeneration\s*,\s*' +
        'pDest\s*:=\s*#homePreemptionSnapshot\[0\]\s*,\s*' +
        'DestSize\s*:=\s*sizeof\(homePreemptionSnapshot\)\s*\)\s*;') (
        "$Owner Home preemption copy is not bound to one captured old-owner tuple.")
    foreach ($snapshotPattern in @(
            'homePreemptionSnapshot\[0\]\$UDINT\s*=\s*LMC_OWNER_PREEMPT_COPY_MAGIC',
            'homePreemptionSnapshot\[4\]\$UDINT\s*=\s*LMC_OWNER_IDENTITY_VERSION',
            'homePreemptionSnapshot\[8\]\$UDINT\s*=\s*LMC_OWNER_PREEMPT_COPY_HEADER_BYTES',
            'homePreemptionSnapshot\[12\]\$UDINT\s*=\s*sizeof\(homePreemptionSnapshot\)',
            'homePreemptionSnapshot\[16\]\$DINT\s*=\s*homePreemptionResult',
            'homePreemptionSnapshot\[32\]\$UDINT\s*=\s*homeAxisMask',
            'homePreemptionSnapshot\[36\]\$UDINT\s*=\s*homeAdmissionToken',
            'homePreemptionSnapshot\[40\]\$UDINT\s*=\s*homeOwnerGeneration',
            'homePreemptionSnapshot\[44\]\$UDINT\s*=\s*homeSessionEpoch',
            'homePreemptionSnapshot\[48\]\$UDINT\s*=\s*homeRequestSequence',
            'homePreemptionSnapshot\[52\]\$UDINT\s*=\s*0x7D13',
            'homePreemptionSnapshot\[56\]\$DINT\s*=\s*ZeroHomeState\[9\]',
            'homePreemptionSnapshot\[60\]\$DINT\s*=\s*LMC_OWNER_KIND_LMC_HOME',
            'homePreemptionSnapshot\[64\]\$DINT\s*=\s*LMC_OWNER_RESOURCE_LMC_HOME_ENGINE',
            'homePreemptionSnapshot\[68\]\$DINT\s*=\s*LMC_OWNER_ADMISSION_LIFECYCLE',
            'homePreemptionSnapshot\[72\]\$DINT\s*=\s*LMC_OWNER_STATE_LMC_HOME_ACTIVE',
            'homePreemptionSnapshot\[76\]\$UDINT\s*=\s*56',
            'homePreemptionSnapshot\[104\]\$UDINT\s+and\s+homeAxisMask',
            'homePreemptionSnapshot\[108\]\$UDINT\s*<>\s*0',
            'homePreemptionSnapshot\[112\]\$UDINT\s*<>\s*0',
            'homePreemptionSnapshot\[124\]\$DINT',
            'homePreemptionSnapshot\[128\]\$UDINT\s*<>\s*0',
            'homePreemptionSnapshot\[132\]\$UDINT\s*<>\s*0',
            'homePreemptionSnapshot\[136\]\$DINT\s*=\s*LMC_OWNER_ADMISSION_SAFETY',
            'homePreemptionSnapshot\[140\]\$UDINT\s*=\s*0',
            'homePreemptionSnapshot\[144\]\$UINT\s*=\s*1',
            'homePreemptionSnapshot\[146\]\$UINT\s*=\s*0',
            'homePreemptionSnapshot\[148\]\$UDINT\s*=\s*ZeroHomeState\[4\]\$UDINT',
            'homePreemptionSnapshot\[152\]\$UDINT\s*=\s*ZeroHomeState\[1\]\$UDINT',
            'homePreemptionSnapshot\[156\]\$UDINT\s*=\s*ZeroHomeState\[2\]\$UDINT',
            'homePreemptionSnapshot\[160\]\$UDINT\s*=\s*ZeroHomeState\[3\]\$UDINT',
            'homePreemptionSnapshot\[164\]\$UDINT\s*=\s*ZeroHomeState\[5\]\$UDINT',
            'homePreemptionSnapshot\[168\]\$UDINT\s*=\s*ZeroHomeState\[6\]\$UDINT',
            'homePreemptionSnapshot\[172\]\$UDINT\s*=\s*ZeroHomeState\[7\]\$UDINT',
            'homePreemptionSnapshot\[176\]\$UDINT\s*=\s*ZeroHomeState\[8\]\$UDINT',
            'homePreemptionSnapshot\[180\]\$UINT\s*=\s*TO_UINT\(ZeroHomeState\[10\]\)',
            'homePreemptionSnapshot\[182\]\$UINT\s*=\s*0',
            'homePreemptionSnapshot\[184\]\$DINT\s*=\s*ZeroHomeState\[11\]',
            'homePreemptionSnapshot\[188\]\$DINT\s*=\s*ZeroHomeState\[12\]',
            'homePreemptionSnapshot\[192\]\$UDINT\s*=\s*ZeroHomeState\[13\]\$UDINT',
            'homePreemptionSnapshot\[196\]\$UDINT\s*=\s*0x454D4F48')) {
        Assert-Match $processBlock $snapshotPattern (
            "$Owner Home preemption snapshot validation is incomplete: $snapshotPattern")
    }
    Assert-Match $processBlock (
        '(?is)homePreemptionResult\s*=\s*' +
        'LMC_OWNER_PREEMPT_STATUS_PENDING_FREEZE\s+then.*?' +
        'InputLatch\.CancelAxisZeroHome\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*\)\s*;.*?' +
        'homePreemptionSnapshotValid\s*&\s*\(homeCancelResult\s*>=\s*0\)\s+then.*?' +
        'LMC_HOME_FLAG_CANCEL_PUBLISHED\s+or\s*' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP\s+or\s*' +
        'LMC_HOME_FLAG_SAFETY_DISPATCH_READY.*?' +
        'RETURN\s*;') (
        "$Owner pending safety reservation can authorize dispatch without exact cancel proof.")
    Assert-Match $processBlock (
        '(?is)elsif\s+homePreemptionResult\s*=\s*' +
        'LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED\s+then\s*' +
        'homePreemptionCleanup\s*:=\s*TRUE\s*;.*?' +
        'LMC_HOME_FLAG_CANCEL_REQUIRED\s+or\s*' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP.*?' +
        'InputLatch\.CancelAxisZeroHome\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*\).*?' +
        'InputLatch\.CopyAxisZeroHomeResult\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*,') (
        "$Owner committed safety preemption does not cancel before draining Home RT.")
    $invalidSnapshotBranchMatch = [regex]::Match(
        $processBlock,
        ('(?is)elsif\s*\(homePreemptionResult\s*<>\s*' +
         'LMC_OWNER_PREEMPT_STATUS_NONE\).*?' +
         '\(homePreemptionSnapshotValid\s*=\s*FALSE\)\)\s+then' +
         '(?<Body>.*?)' +
         '(?=\s*elsif\s+homePreemptionResult\s*=\s*' +
         'LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED\s+then)'))
    if (-not $invalidSnapshotBranchMatch.Success) {
        throw "$Owner invalid Home preemption snapshot branch was not found."
    }
    Assert-Match $invalidSnapshotBranchMatch.Groups['Body'].Value (
        '(?is)InputLatch\.CancelAxisZeroHome\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*\)') (
        "$Owner invalid Home preemption snapshot does not attempt exact-token cancel.")
    $directHomeTokenUsePattern =
        '(?is)(?<![A-Za-z0-9_])' +
        '(?:OperationToken|PreemptedAdmissionToken)\s*:=\s*' +
        'ZeroHomeState\[34\]'
    $directHomeGenerationUsePattern =
        '(?is)(?<![A-Za-z0-9_])' +
        '(?:OwnerGeneration|PreemptedOwnerGeneration)\s*:=\s*' +
        'ZeroHomeState\[35\]'
    if (($processBlock -match $directHomeTokenUsePattern) -or
        ($processBlock -match $directHomeGenerationUsePattern)) {
        throw "$Owner Home cancellation/publication bypasses the captured owner tuple."
    }
    Assert-Match $processBlock (
        '(?is)homeEngineState\s*:=\s*ZeroHomeState\[39\]\s*;.*?' +
        'homeAdmissionToken\s*:=\s*ZeroHomeState\[34\]\$UDINT\s*;\s*' +
        'homeOwnerGeneration\s*:=\s*ZeroHomeState\[35\]\$UDINT\s*;\s*' +
        'homeSessionEpoch\s*:=\s*ZeroHomeState\[36\]\$UDINT\s*;\s*' +
        'homeRequestSequence\s*:=\s*ZeroHomeState\[37\]\$UDINT\s*;\s*' +
        'homeAxisMask\s*:=\s*ZeroHomeState\[38\]\$UDINT\s*;.*?' +
        'homeIdentityValid\s*:=.*?LMC_HOME_RECORD_MAGIC.*?' +
        'homeAdmissionToken\s*<>\s*0.*?homeOwnerGeneration\s*<>\s*0.*?' +
        'homeSessionEpoch\s*<>\s*0.*?homeRequestSequence\s*<>\s*0.*?' +
        'homeAxisMask\s*<>\s*0\s*\)\s*;\s*' +
        'homeWorkSuspect\s*:=.*?' +
        'ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_RUNNING.*?' +
        'homeEngineState\s*>=\s*LMC_HOME_ENGINE_WAIT_RT.*?' +
        'homeEngineState\s*<=\s*LMC_HOME_ENGINE_TERMINAL.*?' +
        'homeAdmissionToken\s*<>\s*0.*?homeOwnerGeneration\s*<>\s*0.*?' +
        'homeAxisMask\s*<>\s*0.*?' +
        'OwnershipState\[7\]\$UDINT\s*<>\s*0.*?' +
        'OwnershipState\[8\]\$UDINT\s*<>\s*0.*?' +
        'OwnershipState\[9\]\$UDINT\s*<>\s*0\s*\)\s*;\s*' +
        'if\s+homeWorkSuspect\s*=\s*FALSE\s+then\s*RETURN\s*;') (
        "$Owner Home processor can return before detecting retained live work.")
    Assert-Match $processBlock (
        '(?is)if\s+homeEngineState\s*=\s*LMC_HOME_ENGINE_TERMINAL\s+then\s*' +
        'homeReceiptRequired\s*:=\s*' +
        '\(homePendingRecordState\s*<>\s*LMC_HOME_RECORD_QUARANTINED\)\s*&\s*' +
        '\(\(homeFlags\s+and\s+LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*=\s*0\).*?' +
        'LMC_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE.*?' +
        '\(\(homeReceiptRequired\s*&\s*' +
        '\(ZeroHomeState\[60\]\$UDINT\s*=\s*LMC_HOME_OWNER_RECEIPT_MAGIC\)\s*&\s*' +
        '\(ZeroHomeState\[61\]\s*=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s*&\s*' +
        '\(ZeroHomeState\[62\]\s*=\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[63\]\$UDINT\s*=\s*ZeroHomeState\[33\]\$UDINT\)\)\s*\|\s*' +
        '\(\(homeReceiptRequired\s*=\s*FALSE\)\s*&\s*' +
        '\(ZeroHomeState\[60\]\s*=\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[61\]\s*=\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[62\]\s*=\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[63\]\s*=\s*0\)\)\)\s+then\s*' +
        'ZeroHomeState\[0\]\s*:=\s*homePendingRecordState\s*;') (
        "$Owner Home terminal recovery can publish without complete receipt or exact receipt absence.")
    $invalidEngineBranch = [regex]::Match(
        $processBlock,
        ('(?is)if\s*\(homeEngineState\s*<\s*LMC_HOME_ENGINE_WAIT_RT\)\s*\|\s*' +
         '\(homeEngineState\s*>\s*LMC_HOME_ENGINE_FINALIZE\)\s+then' +
         '(?<Body>.*?)' +
         '(?=\s*if\s*\(ZeroHomeState\[0\]\s*<>\s*' +
         'LMC_HOME_RECORD_RUNNING\))'))
    $invalidPublicStateBranch = [regex]::Match(
        $processBlock,
        ('(?is)elsif\s+ZeroHomeState\[0\]\s*<>\s*' +
         'LMC_HOME_RECORD_RUNNING\s+then(?<Body>.*?)' +
         '(?=\s*end_if\s*;\s*homeElapsedMs\s*:=)'))
    $invalidIdentityBranch = [regex]::Match(
        $processBlock,
        ('(?is)if\s+homeIdentityValid\s*=\s*FALSE\s+then(?<Body>.*?)' +
         '(?=\s*end_if\s*;\s*homePreemptionResult\s*:=)'))
    foreach ($recoveryBranch in ([ordered]@{
            InvalidEngine = $invalidEngineBranch
            InvalidPublicState = $invalidPublicStateBranch
            InvalidIdentity = $invalidIdentityBranch
        }).GetEnumerator()) {
        if (-not $recoveryBranch.Value.Success) {
            throw "$Owner $($recoveryBranch.Key) Home cancel/drain branch was not found."
        }
        Assert-Match $recoveryBranch.Value.Groups['Body'].Value (
            '(?is)LMC_HOME_FLAG_CANCEL_REQUIRED.*?' +
            'InputLatch\.CancelAxisZeroHome\(\s*' +
            'OperationToken\s*:=\s*homeAdmissionToken\s*\)\s*;.*?' +
            'ZeroHomeState\[54\]\$UDINT\s*:=\s*homeServiceNow\s*;.*?' +
            'LMC_HOME_FLAG_CANCEL_PUBLISHED.*?' +
            'ZeroHomeState\[39\]\s*:=\s*LMC_HOME_ENGINE_CANCEL_DRAIN\s*;.*?' +
            'OwnershipState\[24\]\s*:=\s*1\s*;\s*RETURN\s*;') (
            "$Owner $($recoveryBranch.Key) Home branch lacks exact-token cancel/drain recovery.")
    }
    Assert-Match $processBlock (
        '(?is)homeElapsedMs\s*>=\s*ZeroHomeState\[13\]\$UDINT\s+then\s*' +
        'homeCancelResult\s*:=\s*InputLatch\.CancelAxisZeroHome\(\s*' +
        'OperationToken\s*:=\s*homeAdmissionToken\s*\).*?' +
        'ZeroHomeState\[54\]\$UDINT\s*:=\s*homeServiceNow\s*;.*?' +
        'LMC_HOME_FLAG_CANCEL_PUBLISHED') (
        "$Owner normal Home timeout does not start one exact-token cancel drain.")
    Assert-Match $processBlock (
        '(?is)homeCancelElapsedMs\s*:=\s*homeServiceNow\s*-\s*' +
        'ZeroHomeState\[54\]\$UDINT\s*;.*?' +
        'homeCancelElapsedMs\s*>=\s*LMC_HOME_CANCEL_DRAIN_TIMEOUT_MS.*?' +
        'homeQuarantine\s*:=\s*TRUE\s*;.*?homeTerminal\s*:=\s*TRUE\s*;') (
        "$Owner Home cancel drain lacks its independent service-clock deadline.")
    $cancelStartStores = [regex]::Matches(
        $processBlock,
        '(?is)ZeroHomeState\[54\]\$UDINT\s*:=\s*homeServiceNow\s*;')
    if ($cancelStartStores.Count -ne 7) {
        throw (
            "$Owner Home cancel-start store count is $($cancelStartStores.Count), " +
            'expected exactly seven first-publication paths.')
    }
    Assert-Match $processBlock (
        '(?is)if\s+homeEngineState\s*=\s*LMC_HOME_ENGINE_FINALIZE\s+then.*?' +
        'if\s+homePreemptionCleanup\s+then.*?' +
        'homePreemptionResult\s*<>\s*' +
        'LMC_OWNER_PREEMPT_STATUS_CLEANUP_REQUIRED.*?' +
        'PublishAxisOwnershipPreemptionCleanup\(\s*' +
        'ExpectedAxisMask\s*:=\s*homeAxisMask\s*,\s*' +
        'PreemptedAdmissionToken\s*:=\s*homeAdmissionToken\s*,\s*' +
        'PreemptedOwnerGeneration\s*:=\s*homeOwnerGeneration\s*,\s*' +
        'SafetyAdmissionToken\s*:=\s*homePreemptionSnapshot\[108\]\$UDINT\s*,\s*' +
        'SafetyOwnerGeneration\s*:=\s*homePreemptionSnapshot\[112\]\$UDINT.*?' +
        'else\s*if\s+homePreemptionResult\s*<>\s*' +
        'LMC_OWNER_PREEMPT_STATUS_NONE\s+then.*?RETURN\s*;\s*end_if\s*;\s*' +
        'homePublishResult\s*:=\s*PublishAxisOwnership\(') (
        "$Owner Home finalize does not freshly separate authenticated preemption and ordinary publication.")
    Assert-Match $processBlock (
        '(?is)ZeroHomeState\[57\]\s*:=\s*homePendingRecordState\s*;\s*' +
        'ZeroHomeState\[58\]\s*:=\s*TO_DINT\(homeReportKind\)\s*;\s*' +
        'ZeroHomeState\[59\]\s*:=\s*TO_DINT\(homeCleanupKind\)\s*;\s*' +
        'ZeroHomeState\[39\]\s*:=\s*LMC_HOME_ENGINE_FINALIZE\s*;') (
        "$Owner Home terminal intent is not retained before owner finalization.")
    $ordinaryHomePublishes = [regex]::Matches(
        $processBlock,
        '(?i)(?<![A-Za-z0-9_])PublishAxisOwnership\s*\(')
    $preemptionHomePublishes = [regex]::Matches(
        $processBlock,
        '(?i)(?<![A-Za-z0-9_])PublishAxisOwnershipPreemptionCleanup\s*\(')
    if ($ordinaryHomePublishes.Count -ne 2 -or
        $preemptionHomePublishes.Count -ne 1) {
        throw (
            "$Owner zero-Home processor must contain two receipt-handshake " +
            'publishes and one preemption-cleanup publish.')
    }
    $homeFinalizeMatch = [regex]::Match(
        $processBlock,
        ('(?is)if\s+homeEngineState\s*=\s*LMC_HOME_ENGINE_FINALIZE\s+then' +
         '(?<Body>.*?)end_if\s*;\s*if\s+homeCancelRequired\s*\|'))
    if (-not $homeFinalizeMatch.Success) {
        throw "$Owner Home finalize receipt-handshake block was not found."
    }
    $homeFinalizeBlock = $homeFinalizeMatch.Groups['Body'].Value
    $ordinaryPublishCallPattern = (
        '(?is)(?<![A-Za-z0-9_])homePublishResult\s*:=\s*' +
        'PublishAxisOwnership\(\s*' +
        'AxisMask\s*:=\s*homeAxisMask\s*,\s*' +
        'AdmissionToken\s*:=\s*homeAdmissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*homeOwnerGeneration\s*,\s*' +
        'ReportKind\s*:=\s*homeReportKind\s*,\s*' +
        'ReportValue0\s*:=\s*TO_UDINT\(homePendingRecordState\)\s*,\s*' +
        'ReportValue1\s*:=\s*ZeroHomeState\[31\]\$UDINT\s*,\s*' +
        'ObservationCycle\s*:=\s*ZeroHomeState\[46\]\$UDINT\s*\)\s*;')
    $finalizeOrdinaryPublishes = [regex]::Matches(
        $homeFinalizeBlock,
        $ordinaryPublishCallPattern)
    $receiptResultZero = [regex]::Match(
        $homeFinalizeBlock,
        ('(?is)ZeroHomeState\[47\]\s*:=\s*homePublishResult\s*;\s*' +
         'if\s+homeReceiptRequired\s+then\s*' +
         'if\s*\(homePublishResult\s*<>\s*0\)\s*\|.*?' +
         'LMC_HOME_OWNER_RECEIPT_MAGIC.*?' +
         'LMC_HOME_OWNER_RECEIPT_PREPARED.*?' +
         'ZeroHomeState\[63\]\$UDINT\s*<>\s*ZeroHomeState\[33\]\$UDINT.*?' +
         'RETURN\s*;'))
    $receiptAccepted = [regex]::Match(
        $homeFinalizeBlock,
        ('(?is)homeFlags\s*:=\s*homeFlags\s+or\s*' +
         'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED\s*;\s*' +
         'ZeroHomeState\[56\]\$UDINT\s*:=\s*homeFlags\s*;'))
    $receiptResultOne = [regex]::Match(
        $homeFinalizeBlock,
        ('(?is)if\s*\(homePublishResult\s*<>\s*1\)\s*\|\s*' +
         '\(ZeroHomeState\[61\]\s*<>\s*' +
         'LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s+then.*?RETURN\s*;'))
    $terminalCommit = [regex]::Match(
        $homeFinalizeBlock,
        ('(?is)homeFlags\s*:=\s*homeFlags\s+or\s*' +
         'LMC_HOME_FLAG_TERMINAL_PUBLISHED\s*;\s*' +
         'ZeroHomeState\[56\]\$UDINT\s*:=\s*homeFlags\s*;\s*' +
         'ZeroHomeState\[39\]\s*:=\s*LMC_HOME_ENGINE_TERMINAL\s*;\s*' +
         'ZeroHomeState\[0\]\s*:=\s*homePendingRecordState\s*;\s*RETURN\s*;'))
    if ($finalizeOrdinaryPublishes.Count -ne 2 -or
        -not $receiptResultZero.Success -or
        -not $receiptAccepted.Success -or
        -not $receiptResultOne.Success -or
        -not $terminalCommit.Success -or
        $finalizeOrdinaryPublishes[0].Index -ge $receiptResultZero.Index -or
        $receiptResultZero.Index -ge $receiptAccepted.Index -or
        $receiptAccepted.Index -ge $finalizeOrdinaryPublishes[1].Index -or
        $finalizeOrdinaryPublishes[1].Index -ge $receiptResultOne.Index -or
        $receiptResultOne.Index -ge $terminalCommit.Index) {
        throw (
            "$Owner Home finalize does not complete result0-accept-replay-" +
            'result1 before terminal commit.')
    }
    $pendingTerminalStores = [regex]::Matches(
        $processBlock,
        '(?is)ZeroHomeState\[0\]\s*:=\s*homePendingRecordState\s*;')
    if ($pendingTerminalStores.Count -ne 2) {
        throw (
            "$Owner retained Home pending-terminal store count is " +
            "$($pendingTerminalStores.Count), expected recovery plus final commit only.")
    }
    Assert-Match $startBlock (
        '(?is)adminHomeRecordState\s*=\s*LMC_HOME_RECORD_QUARANTINED.*?' +
        'ZeroHomeState\[39\]\s*<>\s*LMC_HOME_ENGINE_TERMINAL.*?' +
        'LMC_HOME_FLAG_EXACT_RT_TERMINAL.*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED.*?' +
        'LMC_HOME_FLAG_TERMINAL_PUBLISHED.*?' +
        'ZeroHomeState\[49\]\$UDINT\s*<>\s*ZeroHomeState\[33\]\$UDINT') (
        "$Owner LMC Home restart guard permits quarantine or incomplete finalization.")
    Assert-Match $retireBlock (
        '(?is)ZeroHomeState\[39\]\s*<>\s*LMC_HOME_ENGINE_TERMINAL.*?' +
        'LMC_HOME_FLAG_OWNER_FINALIZE_ACCEPTED.*?' +
        'LMC_HOME_FLAG_TERMINAL_PUBLISHED.*?' +
        'ZeroHomeState\[0\]\s*<>\s*LMC_HOME_RECORD_QUARANTINED.*?' +
        'LMC_HOME_FLAG_EXACT_RT_TERMINAL') (
        "$Owner LMC Home retirement can precede accepted terminal finalization.")
    Assert-Match $outcomeBlock (
        '(?is)\(ZeroHomeState\[0\]\s*=\s*LMC_HOME_RECORD_QUARANTINED\)\s*\|\s*' +
        '\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*<>\s*0\)\s*\|\s*' +
        '\(\(ZeroHomeState\[60\]\$UDINT\s*=\s*LMC_HOME_OWNER_RECEIPT_MAGIC\)\s*&\s*' +
        '\(ZeroHomeState\[61\]\s*=\s*LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s*&\s*' +
        '\(ZeroHomeState\[62\]\s*=\s*0\)\s*&\s*' +
        '\(ZeroHomeState\[63\]\$UDINT\s*=\s*ZeroHomeState\[33\]\$UDINT\)\)') (
        "$Owner 0x7D18 nonquarantine non-preemption outcome lacks complete receipt proof.")
    Assert-Match $retireBlock (
        '(?is)\(\(ZeroHomeState\[0\]\s*<>\s*LMC_HOME_RECORD_QUARANTINED\)\s*&\s*' +
        '\(\(ZeroHomeState\[56\]\$UDINT\s+and\s*' +
        'LMC_HOME_FLAG_PREEMPTION_CLEANUP\)\s*=\s*0\)\)\s*&\s*' +
        '\(\(ZeroHomeState\[60\]\$UDINT\s*<>\s*LMC_HOME_OWNER_RECEIPT_MAGIC\)\s*\|\s*' +
        '\(ZeroHomeState\[61\]\s*<>\s*LMC_HOME_OWNER_RECEIPT_COMPLETE\)\s*\|\s*' +
        '\(ZeroHomeState\[62\]\s*<>\s*0\)\s*\|\s*' +
        '\(ZeroHomeState\[63\]\$UDINT\s*<>\s*ZeroHomeState\[33\]\$UDINT\)\)') (
        "$Owner 0x7D19 can retire a nonquarantine non-preemption record without complete receipt.")
    Assert-Match $latchScan (
        '(?s)FUNCTION\s+GLOBAL\s+LMCEcatInputLatch::SubmitAxisZeroHome.*?' +
        'ExpectedActualPosition\s*:\s*DINT.*?' +
        'END_FUNCTION') (
        "$Owner InputLatch SubmitAxisZeroHome signature lacks ExpectedActualPosition.")
    Assert-LasalAxisZeroHomeRtMailboxContract `
        -InputLatchText $InputLatchText `
        -Owner $Owner
}
function Assert-LasalDs402HomeGenerationClearContract {
    param(
        [string]$StartBlock,
        [string]$ProcessBlock,
        [string]$Owner
    )

    $combined = $StartBlock + [Environment]::NewLine + $ProcessBlock
    $headClears = [regex]::Matches(
        $combined,
        ('(?is)_memset\(dest:=#Ds402HomeState\[92\]\s*,\s*' +
         'usByte:=0\s*,\s*cntr:=68\s*\)'))
    $tailClears = [regex]::Matches(
        $combined,
        ('(?is)_memset\(dest:=#Ds402HomeState\[110\]\s*,\s*' +
         'usByte:=0\s*,\s*cntr:=72\s*\)'))
    if ($headClears.Count -ne 1 -or $tailClears.Count -ne 1) {
        throw (
            "$Owner DS402 runtime must clear the intent segments only during " +
            'the next write-ahead preflight around generation slot 109.')
    }
    $discardClear = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+stage\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR\s+then\s*' +
         '(?<Body>.*?)\s*end_if\s*;\s*if\s+stage\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_RESERVE_INTENT'))
    if (-not $discardClear.Success) {
        throw "$Owner DS402 durable record-discard stage is missing."
    }
    $discardClearBody = $discardClear.Groups['Body'].Value
    Assert-Match $discardClearBody (
        ('(?is)activeIndex\s*:=\s*Ds402HomeState\[93\]\s*;.*?' +
         '\(activeIndex\s*<\s*0\)\s*\|\s*' +
         '\(activeIndex\s*>\s*3\)\s*\|.*?' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*RETURN\s*;.*?' +
         'recordBase\s*:=\s*activeIndex\s*\*\s*23\s*;')) (
        "$Owner stage86 must validate its retained selector before record clear.")
    $discardRecordClear = [regex]::Match(
        $discardClearBody,
        ('(?is)_memset\(dest:=#Ds402HomeState\[recordBase\]\s*,\s*' +
         'usByte:=0\s*,\s*cntr:=92\s*\)'))
    $discardIdleCommit = [regex]::Match(
        $discardClearBody,
        '(?i)Ds402HomeState\[92\]\s*:=\s*0\s*;')
    if (-not $discardRecordClear.Success -or -not $discardIdleCommit.Success -or
        $discardRecordClear.Index -ge $discardIdleCommit.Index -or
        $discardClearBody -match
            '(?i)_memset\(dest:=#Ds402HomeState\[(?:92|93|110)\]') {
        throw (
            "$Owner stage86 must clear only the selected record and publish idle " +
            'last without invalidating its selector or WAL first.')
    }

    $numericClears = [regex]::Matches(
        $combined,
        ('(?is)_memset\(\s*dest:=#Ds402HomeState\[' +
         '(?<Start>\d+)\]\s*,[^;]*?\bcntr\s*:=\s*' +
         '(?<Bytes>\d+)\s*\)'))
    foreach ($clear in $numericClears) {
        $start = [int]$clear.Groups['Start'].Value
        $bytes = [int]$clear.Groups['Bytes'].Value
        $endExclusive = $start + [int][Math]::Ceiling($bytes / 4.0)
        if ($start -le 109 -and $endExclusive -gt 109) {
            throw (
                "$Owner DS402 runtime clear at slot $start/$bytes bytes " +
                'covers monotonic generation slot 109.')
        }
    }
    if ($combined -match
        '(?i)Ds402HomeState\[109\](?:\^?\$DINT)?\s*:=\s*0\s*;') {
        throw "$Owner DS402 monotonic generation slot 109 must never be zeroed."
    }
    $generationPublishes = [regex]::Matches(
        $StartBlock,
        ('(?i)Ds402HomeState\[109\]\s*:=\s*' +
         'nextGeneration\^?\$DINT\s*;'))
    if ($generationPublishes.Count -ne 1) {
        throw (
            "$Owner DS402 Start must publish computed nextGeneration to " +
            'monotonic slot 109 exactly once.')
    }
}

function Assert-LasalDs402HomeWarmReconcileContract {
    param(
        [string]$StartBlock,
        [string]$ProcessBlock,
        [string]$Owner
    )

    $memcmpAssignments = @([regex]::Matches(
        $StartBlock,
        ('(?im)^[ \t]*(?<Receiver>[A-Za-z_][A-Za-z0-9_]*)[ \t]*' +
         ':=[ \t]*_memcmp[ \t]*\(')))
    if ($memcmpAssignments.Count -ne 4) {
        throw (
            "$Owner DS402 Start _memcmp assignment count is " +
            "$($memcmpAssignments.Count), expected exactly four.")
    }
    $memcmpReceiverNames = @($memcmpAssignments |
        ForEach-Object { $_.Groups['Receiver'].Value } |
        Sort-Object -Unique)
    foreach ($memcmpReceiverName in $memcmpReceiverNames) {
        Assert-LasalExactDeclaredType `
            -Text $StartBlock `
            -Name $memcmpReceiverName `
            -ExpectedType 'UDINT' `
            -Owner "$Owner DS402 Start _memcmp receiver $memcmpReceiverName"
    }

    $preparePhase = [regex]::Match(
        $StartBlock,
        ('(?i)Ds402HomeState\[125\]\s*:=\s*' +
         'LMC_DIAG_DS402_RECEIPT_PREPARED\s*;'))
    $prepareRecord = [regex]::Match(
        $StartBlock,
        '(?i)Ds402HomeState\[recordBase\]\s*:=\s*1\s*;')
    $adoptMarker = [regex]::Match(
        $StartBlock,
        ('(?i)Ds402HomeState\[119\]\$UDINT\s*:=\s*' +
         'LMC_DIAG_DS402_INTENT_ADOPT_MAGIC\s*;'))
    $selectedRecordStateZero = [regex]::Match(
        $StartBlock,
        '(?i)Ds402HomeState\[recordBase\]\s*:=\s*0\s*;')
    $selectedRecordBodyClear = [regex]::Match(
        $StartBlock,
        ('(?is)_memset\(dest:=#Ds402HomeState\[recordBase\s*\+\s*1\]\s*,\s*' +
         'usByte:=0\s*,\s*cntr:=88\s*\)'))
    $rollbackOnlyStage = [regex]::Match(
        $StartBlock,
        ('(?i)Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s*;'))
    $snapshotCall = [regex]::Match(
        $StartBlock,
        '(?i)InputLatch\.CopySnapshot\s*\(')
    $executorFence = [regex]::Match(
        $StartBlock,
        ('(?is)if\s+\(executorConnected\s*=\s*FALSE\)\s*\|\s*' +
         '\(executorReusable\s*=\s*FALSE\)\s+then'))
    $commitReadyStage = [regex]::Match(
        $StartBlock,
        '(?i)Ds402HomeState\[92\]\s*:=\s*89\s*;')
    $commitCalls = [regex]::Matches(
        $StartBlock,
        '(?i)AxisOwnership\.CommitAxisOwnership\s*\(')
    $activePhase = [regex]::Match(
        $StartBlock,
        '(?i)Ds402HomeState\[125\]\s*:=\s*2\s*;')
    $activeStage = [regex]::Match(
        $StartBlock,
        '(?i)Ds402HomeState\[92\]\s*:=\s*1\s*;')
    $ackWrites = [regex]::Matches(
        $StartBlock,
        '(?i)\(pResponse\s*\+\s*4\)\^\$UINT\s*:=\s*0\s*;')
    $ackWrite = $null
    if ($ackWrites.Count -gt 0) {
        $ackWrite = $ackWrites[$ackWrites.Count - 1]
    }
    Assert-LasalDs402HomeGenerationClearContract `
        -StartBlock $StartBlock `
        -ProcessBlock $ProcessBlock `
        -Owner $Owner
    if (-not $preparePhase.Success -or -not $prepareRecord.Success -or
        -not $adoptMarker.Success -or -not $selectedRecordStateZero.Success -or
        -not $selectedRecordBodyClear.Success -or
        -not $rollbackOnlyStage.Success -or -not $snapshotCall.Success -or
        -not $executorFence.Success -or -not $commitReadyStage.Success -or
        $commitCalls.Count -ne 1 -or
        -not $activePhase.Success -or -not $activeStage.Success -or
        $ackWrites.Count -ne 1 -or $null -eq $ackWrite -or
        $preparePhase.Index -ge $adoptMarker.Index -or
        $adoptMarker.Index -ge $selectedRecordStateZero.Index -or
        $selectedRecordStateZero.Index -ge $selectedRecordBodyClear.Index -or
        $selectedRecordBodyClear.Index -ge $prepareRecord.Index -or
        $prepareRecord.Index -ge $rollbackOnlyStage.Index -or
        $rollbackOnlyStage.Index -ge $snapshotCall.Index -or
        $snapshotCall.Index -ge $executorFence.Index -or
        $executorFence.Index -ge $commitReadyStage.Index -or
        $commitReadyStage.Index -ge $commitCalls[0].Index -or
        $commitCalls[0].Index -ge $activePhase.Index -or
        $activePhase.Index -ge $activeStage.Index -or
        $activeStage.Index -ge $ackWrite.Index) {
        throw (
            "$Owner Start must publish phase1/adoption/state0/body/record/stage88, " +
            'pass snapshot and executor gates, publish commit-ready stage89, ' +
            'then phase2/stage1 before ACK.')
    }
    $journalPredicate = [regex]::Match(
        $StartBlock,
        ('(?is)journalEligible\s*:=\s*\r?\n\s*' +
         '(?<Body>\(Reference.*?)\s*;\s*' +
         'if\s+journalEligible\s+then\s*nextGeneration'))
    if (-not $journalPredicate.Success -or
        $journalPredicate.Groups['Body'].Value -match
            '(?i)IsClientConnected\s*\(\s*#AxisOwnership\s*\)') {
        throw (
            "$Owner exact rollback journal eligibility must not depend on " +
            'the transient AxisOwnership client connection.')
    }
    Assert-Match $StartBlock (
        ('(?is)if\s+journalEligible\s*&\s*' +
         'IsClientConnected\(#AxisOwnership\)\s+then\s*' +
         'ownerResult\s*:=\s*' +
         'AxisOwnership\.ValidateAxisOwnershipIdentity\(.*?' +
         'RequiredPhase:=LMC_DIAG_OWNER_PHASE_RESERVED.*?' +
         'if\s+ownerResult\s*=\s*-1\s+then\s*' +
         'detailCode\s*:=\s*10\s*;\s*' +
         'elsif\s+ownerResult\s*<>\s*0\s+then\s*' +
         'journalEligible\s*:=\s*FALSE\s*;')) (
        "$Owner connected Start must journal transient validation and reject only definitive identity failure.")
    $preflightBlock = [regex]::Match(
        $StartBlock,
        ('(?is)preflightOnly\s*:=\s*\(AdmissionToken\s*=\s*0\)\s*&\s*' +
         '\(OwnerGeneration\s*=\s*0\)\s*;.*?' +
         'if\s+preflightOnly\s+then\s*(?<Body>.*?)' +
         'ResponseSize\s*:=\s*LMC_DIAG_DS402_PREFLIGHT_READY\s*;\s*' +
         'RETURN\s*;.*?end_if\s*;\s*' +
         'if\s+\(Reference\s*<\s*1\)'))
    if (-not $preflightBlock.Success -or
        $preflightBlock.Groups['Body'].Value -notmatch
            '(?is)rawStartState\s*=\s*2.*?detailCode\s*:=\s*32' -or
        $preflightBlock.Groups['Body'].Value -notmatch
            ('(?is)diagnosticsBuild\s*<>\s*1.*?' +
             'detailCode\s*:=\s*16.*?bootId\s*<>\s*currentBootId.*?' +
             'detailCode\s*:=\s*17.*?mapRevision\s*<>\s*' +
             'LMC_DIAG_MAP_REVISION.*?detailCode\s*:=\s*18') -or
        $preflightBlock.Groups['Body'].Value -notmatch
            ('(?is)Ds402HomeState\[92\]\s*<>\s*0.*?' +
             'Ds402HomeState\[109\]\$UDINT\s*=\s*0xFFFFFFFF') -or
        $preflightBlock.Groups['Body'].Value -match
            ('(?i)(AxisOwnership\.|LMC_DIAG_DS402_HOME_ENABLED|' +
             'IsClientConnected\s*\(|InputLatch\.|nextGeneration\s*\+=|' +
             'Ds402HomeState\[109\]\s*:=)')) {
        throw (
            "$Owner DS402 Start must reject a pending terminal outcome in a " +
            'write-ahead zero-token preflight before any common reservation.')
    }
    $preflightBody = $preflightBlock.Groups['Body'].Value
    $intentHeadClear = [regex]::Match(
        $preflightBody,
        '(?is)_memset\(dest:=#Ds402HomeState\[92\].*?cntr:=68\s*\)')
    $intentRequestHead = [regex]::Match(
        $preflightBody,
        '(?is)_memcpy\(ptr1:=#Ds402HomeState\[94\].*?cntr:=60\s*\)')
    $intentRequestTail = [regex]::Match(
        $preflightBody,
        '(?is)_memcpy\(ptr1:=#Ds402HomeState\[110\].*?cntr:=12\s*\)')
    $intentMagic = [regex]::Match(
        $preflightBody,
        ('(?i)Ds402HomeState\[116\]\$UDINT\s*:=\s*' +
         'LMC_DIAG_DS402_INTENT_MAGIC\s*;'))
    $intentSession = [regex]::Match(
        $preflightBody,
        '(?i)Ds402HomeState\[113\]\s*:=\s*CallerSessionEpoch\$DINT\s*;')
    $intentSequence = [regex]::Match(
        $preflightBody,
        '(?i)Ds402HomeState\[114\]\s*:=\s*RequestSequence\$DINT\s*;')
    $intentStage = [regex]::Match(
        $preflightBody,
        ('(?i)Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s*;'))
    if (-not $intentHeadClear.Success -or -not $intentRequestHead.Success -or
        -not $intentRequestTail.Success -or -not $intentMagic.Success -or
        -not $intentSession.Success -or -not $intentSequence.Success -or
        -not $intentStage.Success -or
        $intentHeadClear.Index -ge $intentRequestHead.Index -or
        $intentRequestHead.Index -ge $intentRequestTail.Index -or
        $intentRequestTail.Index -ge $intentSession.Index -or
        $intentSession.Index -ge $intentSequence.Index -or
        $intentSequence.Index -ge $intentMagic.Index -or
        $intentMagic.Index -ge $intentStage.Index) {
        throw (
            "$Owner DS402 preflight must publish the exact request/session/" +
            'sequence intent body before stage87 as its final commit word.')
    }
    $intentRecovery = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+stage\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then\s*' +
         '(?<Body>.*?)\s*if\s+stage\s*=\s*0\s+then'))
    if (-not $intentRecovery.Success) {
        throw "$Owner DS402 cyclic processor lacks stage87 recovery."
    }
    $intentRecoveryBody = $intentRecovery.Groups['Body'].Value
    Assert-Match $intentRecoveryBody (
        ('(?is)PublishAxisOwnershipDs402Receipt\(.*?' +
         'AdmissionToken:=0\s*,\s*OwnerGeneration:=0\s*,.*?' +
         'ReportKind:=LMC_DIAG_DS402_RECEIPT_ROLLBACK')) (
        "$Owner stage87 recovery lacks its exact tokenless rollback provider call.")
    Assert-Match $intentRecoveryBody (
        ('(?is)if\s+IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\s+then\s*' +
         'RETURN\s*;\s*end_if\s*;')) (
        "$Owner stage87 disconnect must retain the intent without poisoning it.")
    Assert-Match $intentRecoveryBody (
        ('(?is)if\s+receiptResult\s*=\s*1\s+then.*?' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR\s*;\s*' +
         'elsif\s+receiptResult\s*=\s*2\s+then.*?' +
         'elsif\s+receiptResult\s*=\s*-1\s+then\s*' +
         '.*?elsif\s+receiptResult\s*<>\s*0\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;')) (
        "$Owner stage87 recovery result handling is not retain/clear/fail-closed exact.")
    $absenceBranch = [regex]::Match(
        $intentRecoveryBody,
        ('(?is)elsif\s+receiptResult\s*=\s*2\s+then\s*' +
         '(?<Body>.*?)\s*elsif\s+receiptResult\s*=\s*-1'))
    if (-not $absenceBranch.Success -or
        $absenceBranch.Groups['Body'].Value -notmatch
            ('(?is)Ds402HomeState\[119\]\$UDINT\s*=\s*' +
             'LMC_DIAG_DS402_INTENT_ADOPT_MAGIC.*?' +
             'Ds402HomeState\[recordBase\]\s*=\s*1.*?' +
             'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR.*?' +
             'elsif\s+Ds402HomeState\[recordBase\]\$UDINT\s*<>\s*' +
             'Ds402HomeState\[115\]\$UDINT.*?' +
             'Ds402HomeState\[92\]\s*:=\s*101.*?' +
             'RETURN.*?else.*?Ds402HomeState\[92\]\s*:=\s*0')) {
        throw (
            "$Owner stage87 result2 must preserve only an untouched tombstone " +
            'and durably schedule a committed adoption/record bridge for clear.')
    }
    if ($intentRecoveryBody -match '(?i)_memset\s*\(') {
        throw (
            "$Owner stage87 must publish a discard commit word before any local " +
            'record or WAL clear.')
    }
    if ($intentRecoveryBody -match
        '(?i)(CommitAxisOwnership|RollbackAxisOwnership)') {
        throw "$Owner stage87 recovery must never Commit or issue generic rollback."
    }
    Assert-Match $StartBlock (
        ('(?is)Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s*;\s*' +
         'journalPrepared\s*:=\s*TRUE\s*;.*?' +
         'if\s+journalPrepared\s*&\s*\(detailCode\s*=\s*0\)\s*&\s*' +
         '\(IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\)\s+then\s*' +
         'detailCode\s*:=\s*10\s*;.*?' +
         'if\s+detailCode\s*=\s*0\s+then\s*' +
         'copyResult\s*:=\s*-1')) (
        "$Owner disconnected Start must retain stage88 before later gates.")
    Assert-Match $StartBlock (
        ('(?is)Ds402HomeState\[92\]\s*:=\s*89\s*;.*?' +
         'if\s+\(detailCode\s*=\s*0\)\s*&\s*' +
         '\(IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\)\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s*;\s*' +
         'detailCode\s*:=\s*10\s*;\s*end_if\s*;\s*' +
         'if\s+detailCode\s*=\s*0\s+then\s*' +
         'ownerResult\s*:=\s*AxisOwnership\.CommitAxisOwnership')) (
        "$Owner Commit-ready Start must downgrade to rollback-only before reporting a final disconnect.")
    Assert-Match $StartBlock (
        ('(?is)\(Ds402HomeState\[92\]\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\)\s*\|.*?' +
         'AxisOwnership\.PublishAxisOwnershipDs402Receipt\(.*?' +
         'ReportKind:=LMC_DIAG_DS402_RECEIPT_ROLLBACK.*?' +
         'if\s+rollbackResult\s*=\s*1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_FINALIZE.*?' +
         'else.*?detailCode\s*:=\s*42')) (
        "$Owner rejected Start lacks durable rollback receipt or reports " +
        'quarantine after successful cleanup.')
    $startRejectedReceipt = [regex]::Match(
        $StartBlock,
        ('(?is)if\s+\(detailCode\s*<>\s*0\)\s*&.*?then\s*' +
         'if\s+\(Reference\s*>=\s*1\).*?' +
         '\(Ds402HomeState\[124\]\$UDINT\s*=\s*axisMask\)\s+then\s*' +
         '(?<Body>rollbackResult\s*:=\s*-1\s*;.*?' +
         'detailCode\s*:=\s*42\s*;\s*end_if\s*;)\s*' +
         'elsif\s+Ds402HomeState\[92\]\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then\s*' +
         '(?<IntentBody>.*?)\s*else\s+' +
         'rollbackResult\s*:=\s*-1\s*;\s*' +
         'if\s+IsClientConnected\(#AxisOwnership\)\s+then\s*' +
         'rollbackResult\s*:=\s*' +
         'AxisOwnership\.RollbackAxisOwnership'))
    if (-not $startRejectedReceipt.Success) {
        throw "$Owner rejected Start durable receipt block is missing."
    }
    $startRejectedBody = $startRejectedReceipt.Groups['Body'].Value
    $startIntentBody = $startRejectedReceipt.Groups['IntentBody'].Value
    if ($startIntentBody -notmatch '(?i)detailCode\s*:=\s*42\s*;' -or
        $startIntentBody -match
            '(?i)(RollbackAxisOwnership|CommitAxisOwnership|' +
            'PublishAxisOwnershipDs402Receipt)') {
        throw (
            "$Owner stage87 rejection must defer to cyclic tokenless proof " +
            'without mutating common ownership.')
    }
    $startRejectedInventory = @{
        Defaults = [regex]::Matches(
            $startRejectedBody, '(?i)rollbackResult\s*:=\s*-1\s*;').Count
        Calls = [regex]::Matches(
            $startRejectedBody,
            '(?i)PublishAxisOwnershipDs402Receipt\s*\(').Count
        Finalize = [regex]::Matches(
            $startRejectedBody,
            ('(?i)Ds402HomeState\[92\]\s*:=\s*' +
             'LMC_DIAG_DS402_STAGE_FINALIZE\s*;')).Count
        Quarantine = [regex]::Matches(
            $startRejectedBody,
            '(?i)Ds402HomeState\[92\]\s*:=\s*101\s*;').Count
        Guards = [regex]::Matches(
            $startRejectedBody,
            ('(?is)if\s+\(rollbackResult\s*<>\s*-1\)\s*\|\s*' +
             '\(Ds402HomeState\[92\]\s*<>\s*' +
             'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\)\s+then\s*' +
             'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*end_if\s*;')).Count
    }
    if ($startRejectedInventory.Defaults -ne 2 -or
        $startRejectedInventory.Calls -ne 2 -or
        $startRejectedInventory.Finalize -ne 2 -or
        $startRejectedInventory.Quarantine -ne 2 -or
        $startRejectedInventory.Guards -ne 2 -or
        $startRejectedBody -match '(?i)_memset\s*\(.*?Ds402HomeState') {
        throw (
            "$Owner rejected Start must preserve the exact two-call receipt " +
            'journal on disconnect/result -1 and quarantine only definitive failures.')
    }
    foreach ($stateWrite in [regex]::Matches(
            $startRejectedBody,
            '(?i)Ds402HomeState\[(?<Index>[0-9]+)\].*?:=')) {
        if ($stateWrite.Groups['Index'].Value -notin @('92', '125')) {
            throw (
                "$Owner rejected Start writes forbidden journal slot " +
                "$($stateWrite.Groups['Index'].Value).")
        }
    }
    $firstReceipt = [regex]::Match(
        $StartBlock,
        '(?i)AxisOwnership\.PublishAxisOwnershipDs402Receipt\s*\(')
    $genericRollback = [regex]::Match(
        $StartBlock,
        '(?i)AxisOwnership\.RollbackAxisOwnership\s*\(')
    if (-not $firstReceipt.Success -or -not $genericRollback.Success -or
        $firstReceipt.Index -ge $genericRollback.Index) {
        throw (
            "$Owner Start must prefer the durable local receipt before the " +
            'non-journalled exact-reservation fallback.')
    }
    Assert-Match $StartBlock (
        ('(?is)AxisOwnership\.CommitAxisOwnership\(.*?' +
         'if\s+ownerResult\s*=\s*0\s+then.*?' +
         'else\s+.*?RequiredPhase:=LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;.*?' +
         'if\s+ownerResult\s*=\s*0\s+then.*?' +
         'else\s+.*?Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s*;\s*' +
         'detailCode\s*:=\s*10\s*;')) (
        "$Owner a failed Commit without exact ACTIVE proof must publish the " +
        'rollback-only stage before returning a rejected Start.')

    $commonReceipt = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+Ds402HomeState\[124\]\$UDINT\s*=\s*' +
         'LMC_DIAG_DS402_RECEIPT_MAGIC\s+then' +
         '(?<Body>.*?)if\s+stage\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s+then'))
    if (-not $commonReceipt.Success) {
        throw "$Owner common durable receipt replay branch is missing."
    }
    $commonReceiptBody = $commonReceipt.Groups['Body'].Value
    $commonDisconnectFences = [regex]::Matches(
        $commonReceiptBody,
        ('(?is)if\s+IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\s+then\s*' +
         'RETURN\s*;\s*end_if\s*;'))
    if ($commonDisconnectFences.Count -ne 2) {
        throw (
            "$Owner common durable receipt replay must retain its journal " +
            'across both AxisOwnership disconnect windows.')
    }
    Assert-Match $commonReceiptBody (
        ('(?is)if\s+receiptResult\s*=\s*1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_FINALIZE\s*;\s*' +
         'elsif\s*\(receiptResult\s*<>\s*0\)\s*&\s*' +
         '\(receiptResult\s*<>\s*-1\)\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;.*?' +
         'elsif\s+receiptResult\s*<>\s*-1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;')) (
        "$Owner common receipt replay must preserve result 0/-1 and " +
        'quarantine only definitive provider failures.')

    $stage88 = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+stage\s*=\s*' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s+then' +
         '(?<Body>.*?)if\s+stage\s*=\s*101\s+then'))
    if (-not $stage88.Success) {
        throw "$Owner Process rollback-only stage88 branch is missing."
    }
    $stage88Body = $stage88.Groups['Body'].Value
    if ($stage88Body -match '(?i)CommitAxisOwnership\s*\(' -or
        [regex]::Matches(
            $stage88Body,
            '(?i)PublishAxisOwnershipDs402Receipt\s*\(').Count -ne 2) {
        throw (
            "$Owner stage88 must never Commit and must support first/replay " +
            'durable rollback receipt publication.')
    }
    $stage88DisconnectFences = [regex]::Matches(
        $stage88Body,
        ('(?is)if\s+IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\s+then\s*' +
         'RETURN\s*;\s*end_if\s*;'))
    if ($stage88DisconnectFences.Count -ne 2) {
        throw (
            "$Owner stage88 must retain the rollback journal across both " +
            'transient AxisOwnership disconnect windows without timeout ' +
            'poisoning.')
    }
    Assert-Match $stage88Body (
        ('(?is)if\s+receiptResult\s*=\s*1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_FINALIZE\s*;\s*' +
         'elsif\s*\(receiptResult\s*<>\s*0\)\s*&\s*' +
         '\(receiptResult\s*<>\s*-1\)\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;.*?' +
         'elsif\s+receiptResult\s*<>\s*-1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;')) (
        "$Owner stage88 receipt replay must preserve result 0/-1 and " +
        'quarantine only definitive provider failures.')

    $stage89 = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+stage\s*=\s*89\s+then' +
         '(?<Body>.*?)' +
         '_memset\(dest:=#preemptionSnapshot\[0\]'))
    if (-not $stage89.Success) {
        throw "$Owner Process stage89 must dominate preemption inspection."
    }
    $body = $stage89.Groups['Body'].Value
    Assert-Match $body (
        ('(?is)if\s+IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\s+then\s*' +
         'RETURN\s*;\s*end_if\s*;')) (
        "$Owner stage89 must retain its exact journal while AxisOwnership is disconnected.")
    $activeMatches = [regex]::Matches(
        $body,
        '(?i)RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_ACTIVE')
    $reservedMatch = [regex]::Match(
        $body,
        '(?i)RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_RESERVED')
    $reconcileCommit = [regex]::Match(
        $body,
        '(?i)AxisOwnership\.CommitAxisOwnership\s*\(')
    $reconcileReceipts = [regex]::Matches(
        $body,
        '(?i)AxisOwnership\.PublishAxisOwnershipDs402Receipt\s*\(')
    if ($activeMatches.Count -ne 2 -or -not $reservedMatch.Success -or
        -not $reconcileCommit.Success -or $reconcileReceipts.Count -ne 2 -or
        $activeMatches[0].Index -ge $reservedMatch.Index -or
        $reservedMatch.Index -ge $reconcileCommit.Index -or
        $reconcileCommit.Index -ge $activeMatches[1].Index -or
        $activeMatches[1].Index -ge $reconcileReceipts[0].Index) {
        throw (
            "$Owner stage89 order must be ACTIVE, RESERVED, Commit, " +
            'ACTIVE recheck, then durable rollback receipt.')
    }
    $activeSuccessFences = [regex]::Matches(
        $body,
        ('(?is)RequiredPhase:=LMC_DIAG_OWNER_PHASE_ACTIVE\s*\)\s*;\s*' +
         'if\s+ownerResult\s*=\s*0\s+then\s*' +
         'Ds402HomeState\[125\]\s*:=\s*2\s*;\s*' +
         'Ds402HomeState\[92\]\s*:=\s*1\s*;\s*' +
         'RETURN\s*;\s*end_if\s*;'))
    if ($activeSuccessFences.Count -ne 2) {
        throw (
            "$Owner stage89 must activate only both exact ACTIVE " +
            'validation successes.')
    }
    Assert-Match $body (
        ('(?is)RequiredPhase:=LMC_DIAG_OWNER_PHASE_RESERVED\s*\)\s*;\s*' +
         'if\s+\(ownerResult\s*=\s*0\)\s*&\s*' +
         '\(Ds402HomeState\[125\]\s*=\s*1\)\s+then\s*' +
         'ownerResult\s*:=\s*AxisOwnership\.CommitAxisOwnership\s*\(')) (
        "$Owner stage89 RESERVED result and prepared phase must both gate Commit.")
    Assert-Match $body (
        '(?s)\(Ds402HomeState\[recordBase\s*\+\s*5\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeState\[recordBase\s*\+\s*6\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeState\[recordBase\s*\+\s*7\]\s*=\s*0\)\s*&\s*' +
        '\(Ds402HomeState\[recordBase\s*\+\s*8\]\s*=\s*0\).*?' +
        'Ds402HomeState\[94\]\s*<>\s*0.*?' +
        'Ds402HomeState\[113\]\s*<>\s*0.*?' +
        'Ds402HomeState\[116\]\s*<>\s*0.*?' +
        'Ds402HomeState\[117\]\s*<>\s*0.*?' +
        'Ds402HomeState\[127\]\s*<>\s*0.*?' +
        '\(Ds402HomeState\[125\]\s*<>\s*1\)\s*&\s*' +
        '\(Ds402HomeState\[125\]\s*<>\s*2\)') (
        "$Owner stage89 prepared-state integrity guard is incomplete.")
    Assert-Match $body (
        ('(?is)ReportKind:=LMC_DIAG_DS402_RECEIPT_ROLLBACK.*?' +
         'if\s+receiptResult\s*=\s*0\s+then.*?' +
         'Ds402HomeState\[125\]\s*:=\s*2.*?' +
         'ReportKind:=LMC_DIAG_DS402_RECEIPT_ROLLBACK.*?' +
         'if\s+receiptResult\s*=\s*1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*' +
         'LMC_DIAG_DS402_STAGE_FINALIZE\s*;\s*' +
         'elsif\s*\(receiptResult\s*<>\s*0\)\s*&\s*' +
         '\(receiptResult\s*<>\s*-1\)\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;.*?' +
         'elsif\s+receiptResult\s*<>\s*-1\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;')) (
        "$Owner stage89 failed Commit lacks durable rollback receipt replay.")
    if ($body -match '(?i)Ds402HomeState\[109\].*?:=') {
        throw "$Owner stage89 must never rewrite monotonic generation slot 109."
    }
    Assert-Match $ProcessBlock (
        ('(?s)if\s+Ds402HomeState\[124\]\$UDINT\s*=\s*' +
         'LMC_DIAG_DS402_RECEIPT_MAGIC.*?' +
         'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED.*?' +
         '89:\s*receiptKind\s*:=\s*LMC_DIAG_DS402_RECEIPT_ROLLBACK')) (
        "$Owner receipt replay must recognize rollback-only stage88 and " +
        'commit-ready stage89.')
    Assert-Match $ProcessBlock (
        '(?s)_memset\(dest:=#preemptionSnapshot\[0\].*?' +
        '\(Ds402HomeState\[125\]\s*<>\s*2\)\s+then\s*' +
        'Ds402HomeState\[92\]\s*:=\s*101') (
        "$Owner normal DS402 processing must require committed phase 2.")
}

function Invoke-LasalDs402HomeDurableReceiptVerifierSelfTest {
    param(
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $negativeFixtures = [ordered]@{}
    $negativeFixtures['MemcmpReceiverTypeChanged'] =
        $DiagnosticsText.Replace(
            'intentBodyCompareResult, intentTailCompareResult : UDINT;',
            'intentBodyCompareResult, intentTailCompareResult : DINT;')
    $negativeFixtures['MemcmpSignedReceiverReintroduced'] =
        ([regex]::new(
            ('(?im)^(?<Indent>[ \t]*)intentBodyCompareResult' +
             '(?<Assign>[ \t]*:=[ \t]*_memcmp\()'))).Replace(
                $DiagnosticsText,
                '${Indent}copyResult${Assign}',
                1)
    $negativeFixtures['RollbackOnlyStageRemoved'] =
        $DiagnosticsText.Replace(
            'Ds402HomeState[92] := LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED;',
            'Ds402HomeState[92] := 89;')
    $negativeFixtures['CommitReadyStageRemoved'] =
        ([regex]::new(
            ('(?im)^(?<Indent>[ \t]*)Ds402HomeState\[92\]\s*:=\s*89;[ \t]*$'))).Replace(
                $DiagnosticsText,
                '${Indent}Ds402HomeState[92] := ' +
                'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED;',
                1)
    $negativeFixtures['Stage88CanCommit'] =
        ([regex]::new(
            ('(?im)^(?<Indent>[ \t]*)// This state is rollback-only\.[^\r\n]*$'))).Replace(
                $DiagnosticsText,
                ('${Indent}AxisOwnership.CommitAxisOwnership(' +
                 'CommandId:=0x7D15);' + [Environment]::NewLine +
                 '${Indent}// This state is rollback-only.'),
                1)
    $negativeFixtures['GenerationCounterConstant'] =
        $DiagnosticsText.Replace(
            'Ds402HomeState[109] := nextGeneration$DINT;',
            'Ds402HomeState[109] := 1;')
    $negativeFixtures['GenerationHeadClearCoversSlot109'] =
        $DiagnosticsText.Replace(
            ('_memset(dest:=#Ds402HomeState[92], usByte:=0, ' +
             'cntr:=68);'),
            ('_memset(dest:=#Ds402HomeState[92], usByte:=0, ' +
             'cntr:=72);'))
    $negativeFixtures['GenerationTailClearCoversSlot109'] =
        $DiagnosticsText.Replace(
            ('_memset(dest:=#Ds402HomeState[110], usByte:=0, ' +
             'cntr:=72);'),
            ('_memset(dest:=#Ds402HomeState[109], usByte:=0, ' +
             'cntr:=72);'))
    $negativeFixtures['WarmActivePhaseChanged'] =
