             'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED\s*;)' +
             '(\s*detailCode\s*:=\s*10\s*;)'))).Replace(
                $DiagnosticsText,
                '${1}${2}${4}',
                1)
    $negativeFixtures['PreflightReadyWithoutIntent'] =
        ([regex]::new(
            ('(?is)(if\s+preflightOnly\s+then.*?)' +
             'Ds402HomeState\[92\]\s*:=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s*;'))).Replace(
                $DiagnosticsText,
                '${1}',
                1)
    $negativeFixtures['IntentMarkerBeforeBody'] =
        ([regex]::new(
            ('(?is)(if\s+preflightOnly\s+then.*?' +
             '_memset\(dest:=#Ds402HomeState\[92\].*?cntr:=68\s*\))'))).Replace(
                $DiagnosticsText,
                ('${1}' + [Environment]::NewLine +
                 'Ds402HomeState[92] := LMC_DIAG_DS402_STAGE_RESERVE_INTENT;'),
                1)
    $negativeFixtures['IntentPublishedAsStage88'] =
        ([regex]::new(
            ('(?is)(if\s+preflightOnly\s+then.*?)' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT'))).Replace(
                $DiagnosticsText,
                '${1}LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED',
                1)
    $negativeFixtures['FinalStage88BeforeTuple'] =
        ([regex]::new(
            ('(?is)(if\s+journalEligible\s+then.*?' +
             'Ds402HomeState\[120\]\s*:=)'))).Replace(
                $DiagnosticsText,
                ('Ds402HomeState[92] := ' +
                 'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED;' +
                 [Environment]::NewLine + '${1}'),
                1)
    $negativeFixtures['IntentStateZeroAfterBodyClear'] =
        ([regex]::new(
            ('(?is)(if\s+journalEligible\s+then.*?)' +
             '(Ds402HomeState\[recordBase\]\s*:=\s*0\s*;)' +
             '(.*?)(_memset\(dest:=#Ds402HomeState\[' +
             'recordBase\s*\+\s*1\]\s*,\s*usByte:=0\s*,\s*cntr:=88\s*\))'))).Replace(
                $DiagnosticsText,
                '${1}${3}${4}' + [Environment]::NewLine + '${2}',
                1)
    $negativeFixtures['IntentPathCanCommit'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then\s*)'))).Replace(
                $DiagnosticsText,
                '${1}ownerResult := AxisOwnership.CommitAxisOwnership();' +
                [Environment]::NewLine,
                1)
    $negativeFixtures['IntentDisconnectPoisonsJournal'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then.*?' +
             'if\s+IsClientConnected\(#AxisOwnership\)\s*=\s*FALSE\s+then\s*)' +
             '(RETURN\s*;)'))).Replace(
                $DiagnosticsText,
                '${1}Ds402HomeState[92] := 101;' +
                [Environment]::NewLine + '${2}',
                1)
    $negativeFixtures['IntentResultZeroPoisonsJournal'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then.*?' +
             'elsif\s+)receiptResult\s*<>\s*0'))).Replace(
                $DiagnosticsText,
                '${1}receiptResult = 0',
                1)
    $negativeFixtures['IntentResultOneSkipsDiscard'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then.*?' +
             'if\s+receiptResult\s*=\s*1\s+then.*?' +
             'Ds402HomeState\[92\]\s*:=\s*)' +
             'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR'))).Replace(
                $DiagnosticsText,
                '${1}0',
                1)
    $negativeFixtures['IntentResultTwoClearsBeforeCommit'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_RESERVE_INTENT\s+then.*?' +
             'elsif\s+receiptResult\s*=\s*2\s+then\s*)'))).Replace(
                $DiagnosticsText,
                ('${1}_memset(dest:=#Ds402HomeState[recordBase], ' +
                 'usByte:=0, cntr:=92);' + [Environment]::NewLine),
                1)
    $negativeFixtures['DiscardClearsSelectorBeforeRecord'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR\s+then\s*)'))).Replace(
                $DiagnosticsText,
                ('${1}_memset(dest:=#Ds402HomeState[93], ' +
                 'usByte:=0, cntr:=64);' + [Environment]::NewLine),
                1)
    $negativeFixtures['DiscardPublishesIdleBeforeRecord'] =
        ([regex]::new(
            ('(?is)(if\s+stage\s*=\s*' +
             'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR\s+then.*?)' +
             '(_memset\(dest:=#Ds402HomeState\[recordBase\]\s*,\s*' +
             'usByte:=0\s*,\s*cntr:=92\s*\)\s*;)' +
             '(.*?)(Ds402HomeState\[92\]\s*:=\s*0\s*;)'))).Replace(
                $DiagnosticsText,
                '${1}${4}' + [Environment]::NewLine + '${2}${3}',
                1)

    $negativeCount = 0
    foreach ($negativeFixture in $negativeFixtures.GetEnumerator()) {
        if ($negativeFixture.Value -ceq $DiagnosticsText) {
            throw (
                "$Owner durable receipt negative fixture did not mutate " +
                "'$($negativeFixture.Key)'.")
        }
        $scan = Get-LasalScanText $negativeFixture.Value
        $startBlock = [regex]::Match(
            $scan,
            ('(?is)FUNCTION\s+' +
             'LMCDiagnosticsService::HandleAxisDs402HomeStart.*?' +
             'END_FUNCTION')).Value
        $processBlock = [regex]::Match(
            $scan,
            ('(?is)FUNCTION\s+' +
             'LMCDiagnosticsService::ProcessAxisDs402Home.*?' +
             'END_FUNCTION')).Value
        $receiptBlock = [regex]::Match(
            $scan,
            ('(?is)FUNCTION\s+' +
             'LMCDiagnosticsService::HandleAxisDs402HomeReceiptStages.*?' +
             'END_FUNCTION')).Value
        $warmProcessBlock = $processBlock
        if (-not [string]::IsNullOrWhiteSpace($receiptBlock)) {
            $warmProcessBlock = $receiptBlock + "`n" + $processBlock
        }
        $negativeRejected = $false
        try {
            Assert-LasalDs402HomeWarmReconcileContract `
                -StartBlock $startBlock `
                -ProcessBlock $warmProcessBlock `
                -Owner ($Owner + ' negative ' + $negativeFixture.Key)
        }
        catch {
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner durable receipt verifier accepted negative fixture " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeCount++
    }
    if ($negativeCount -ne $negativeFixtures.Count) {
        throw (
            "$Owner durable receipt negative count is $negativeCount, expected " +
            "$($negativeFixtures.Count).")
    }
    return $negativeCount
}

function Assert-LasalDs402HomePendingFreezeCleanupContract {
    param(
        [string]$ProcessBlock,
        [string]$Owner
    )

    $pendingFreeze = [regex]::Match(
        $ProcessBlock,
        ('(?is)if\s+preemptionResult\s*=\s*' +
         'LMC_DIAG_PREEMPT_PENDING_FREEZE\s+then' +
         '(?<Body>.*?)RETURN\s*;\s*end_if'))
    if (-not $pendingFreeze.Success) {
        throw "$Owner Process PENDING_FREEZE cleanup branch is missing."
    }
    $body = $pendingFreeze.Groups['Body'].Value
    if ($ProcessBlock -match
        '(?i)LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED') {
        Assert-Match $body (
            '(?s)serviceStart\s*:=\s*Ds402HomeState\[118\]\^?\$UDINT\s*;.*?' +
            'cleanupExpired\s*:=\s*\(serviceStart\s*<>\s*0\)\s*&\s*' +
            '\(\(ops\.tAbsolute\s*-\s*serviceStart\)\s*>=\s*1000\)\s*;.*?' +
            'if\s+cleanupExpired\s+then\s*' +
            'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*end_if\s*;?\s*$') (
            "$Owner PENDING_FREEZE must bound every frozen normal stage from " +
            'the nonzero service start, not only stages 90..99.')
    }
    else {
        Assert-Match $body (
            '(?s)cleanupStart\s*:=\s*Ds402HomeState\[119\]\^?\$UDINT\s*;.*?' +
            'cleanupExpired\s*:=\s*\(cleanupStart\s*<>\s*0\)\s*&\s*' +
            '\(stage\s*>=\s*90\)\s*&\s*\(stage\s*<=\s*99\)\s*&\s*' +
            '\(\(ops\.tAbsolute\s*-\s*cleanupStart\)\s*>=\s*1000\)\s*;.*?' +
            'if\s+cleanupExpired\s+then\s*' +
            'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*end_if\s*;?\s*$') (
            "$Owner legacy fixture PENDING_FREEZE cleanup guard is incomplete.")
    }

    if ($body -match '(?i)AxisOwnership\.') {
        throw "$Owner PENDING_FREEZE cleanup must not mutate or publish ownership."
    }
    if ([regex]::Matches($body, '(?i)\bRETURN\s*;').Count -ne 0) {
        throw (
            "$Owner PENDING_FREEZE expiry check must execute before its " +
            'single final return.')
    }
    $stateWrites = [regex]::Matches(
        $body,
        '(?i)Ds402HomeState\[[^\]]+\](?:\^?\$[A-Za-z0-9_]+)?\s*:=' )
    if ($stateWrites.Count -ne 1 -or
        $stateWrites[0].Value -notmatch
            '(?i)^Ds402HomeState\[92\]\s*:=') {
        throw (
            "$Owner PENDING_FREEZE cleanup may write only local stage 101; " +
            'owner receipt and pending flags must remain unchanged.')
    }
}

function Assert-LasalDs402HomeBoundedCleanupContract {
    param(
        [string]$ProcessBlock,
        [string]$Owner,
        [ValidateSet(1, 4)]
        [int]$ExpectedExpiredFailClosedArmCount = 4
    )

    Assert-Match $ProcessBlock (
        ('(?is)preemptionCleanup\s*:=\s*FALSE\s*;\s*' +
         'if\s+preemptionResult\s*<>\s*0\s+then.*?' +
         'preemptionSnapshotValid\s*:=\s*.*?' +
         'preemptionSnapshot\[0\]\^?\$UDINT\s*=\s*' +
         'LMC_DIAG_PREEMPT_SNAPSHOT_MAGIC.*?' +
         'preemptionSnapshot\[32\]\^?\$UDINT\s*=\s*axisMask.*?' +
         'preemptionSnapshot\[36\]\^?\$UDINT\s*=\s*admissionToken.*?' +
         'preemptionSnapshot\[40\]\^?\$UDINT\s*=\s*ownerGeneration.*?' +
         'preemptionSnapshot\[108\]\^?\$UDINT\s*<>\s*0.*?' +
         'preemptionSnapshot\[112\]\^?\$UDINT\s*<>\s*0.*?' +
         'if\s+preemptionSnapshotValid\s*=\s*FALSE\s+then\s*' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*RETURN\s*;\s*' +
         'end_if\s*;.*?' +
         'safetyAdmissionToken\s*:=\s*' +
         'preemptionSnapshot\[108\]\^?\$UDINT\s*;\s*' +
         'safetyOwnerGeneration\s*:=\s*' +
         'preemptionSnapshot\[112\]\^?\$UDINT\s*;\s*' +
         'preemptionCleanup\s*:=\s*TRUE\s*;\s*end_if\s*;')) (
        "$Owner preemption cleanup flag and safety tokens lack exact " +
        'validated preemption-snapshot provenance.')

    $expired = [regex]::Match(
        $ProcessBlock,
        ('(?is)cleanupStart\s*:=\s*Ds402HomeState\[119\]\^?\$UDINT\s*;\s*' +
         'cleanupExpired\s*:=\s*\(cleanupStart\s*<>\s*0\)\s*&\s*' +
         '\(stage\s*>=\s*90\)\s*&\s*\(stage\s*<=\s*99\)\s*&\s*' +
         '\(\(serviceNow\s*-\s*cleanupStart\)\s*>=\s*1000\)\s*;\s*' +
         'if\s+cleanupExpired\s+then(?<Body>.*?)' +
         'end_if\s*;\s*case\s+stage\s+of'))
    if (-not $expired.Success) {
        throw (
            "$Owner common cleanup must bound every stage 90..99 before " +
            'the cleanup state dispatch.')
    }
    $body = $expired.Groups['Body'].Value
    Assert-Match $body (
        '(?s)if\s+Ds402HomeState\[94\]\s*<>\s*0\s+then.*?' +
        'Ds402HomeState\[127\]\s*:=\s*1\s*;.*?' +
        'if\s+Ds402HomeState\[113\]\s*<>\s*0\s+then\s*' +
        'Ds402HomeState\[127\]\s*:=\s*1\s*;') (
        "$Owner expired cleanup does not preserve SDO retirement uncertainty.")

    $orphanCalls = [regex]::Matches(
        $body,
        ('(?i)\.MarkOrphan\(\s*' +
         'Ds402HomeState\[99\]\^?\$UDINT\s*\)'))
    if ($orphanCalls.Count -ne 4) {
        throw (
            "$Owner expired cleanup has $($orphanCalls.Count) exact-token " +
            'MarkOrphan axis paths, expected four.')
    }
    Assert-Match $body (
        ('(?s)if\s+preemptionCleanup\s+then.*?' +
         'PublishAxisOwnershipPreemptionCleanup\(.*?' +
         'ExpectedAxisMask:=axisMask.*?' +
         'PreemptedAdmissionToken:=admissionToken.*?' +
         'PreemptedOwnerGeneration:=ownerGeneration.*?' +
         'SafetyAdmissionToken:=safetyAdmissionToken.*?' +
         'SafetyOwnerGeneration:=safetyOwnerGeneration.*?' +
         'CleanupKind:=\s*' +
         'LMC_DIAG_PREEMPT_CLEANUP_INCOMPLETE_QUARANTINE.*?' +
         'else.*?PublishAxisOwnership\(.*?' +
         'AxisMask:=axisMask.*?AdmissionToken:=admissionToken.*?' +
         'OwnerGeneration:=ownerGeneration.*?' +
         'ReportKind:=LMC_DIAG_OWNER_REPORT_QUARANTINE.*?' +
         'end_if\s*;.*?' +
         'Ds402HomeState\[92\]\s*:=\s*101\s*;\s*RETURN\s*;\s*$')) (
        "$Owner expired cleanup must best-effort publish quarantine and stop.")

    if ($body -match
        ('(?i)Ds402HomeState\[(?:94|113|116|117|127)\]' +
         '(?:\^?\$[A-Za-z0-9_]+)?\s*:=\s*0\s*;')) {
        throw (
            "$Owner expired cleanup must not clear unproved pending or " +
            'retirement flags.')
    }
    $terminalWrites = [regex]::Matches(
        $body,
        '(?i)Ds402HomeState\[92\]\s*:=\s*101\s*;')
    if ($terminalWrites.Count -ne $ExpectedExpiredFailClosedArmCount) {
        throw (
            "$Owner expired cleanup stage 101 count is " +
            "$($terminalWrites.Count), expected " +
            "$ExpectedExpiredFailClosedArmCount fail-closed arm(s).")
    }
    $expiredReturnCount =
        [regex]::Matches($body, '(?i)\bRETURN\s*;').Count
    if ($expiredReturnCount -ne $ExpectedExpiredFailClosedArmCount) {
        throw (
            "$Owner expired cleanup RETURN count is $expiredReturnCount, " +
            "expected $ExpectedExpiredFailClosedArmCount fail-closed arm(s).")
    }
}

function Assert-LasalDs402HomeContract {
    param(
        [string]$DiagnosticsText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $DiagnosticsText
    Assert-Match $scan (
        '(?im)^\s*#define\s+' +
        'LMC_DIAG_DS402_INTENT_ADOPT_MAGIC\s+0x44344144\s*$') (
        "$Owner exact stage87 adoption marker constant is missing.")
    Assert-Match $scan (
        '(?im)^\s*#define\s+' +
        'LMC_DIAG_DS402_STAGE_INTENT_DISCARD_CLEAR\s+86\s*$') (
        "$Owner exact durable intent-discard stage constant is missing.")
    $startBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeStart.*?END_FUNCTION').Value
    $outcomeBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeOutcome.*?END_FUNCTION').Value
    $retireBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeRetire.*?END_FUNCTION').Value
    $processBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::ProcessAxisDs402Home.*?END_FUNCTION').Value
    $receiptBlock = [regex]::Match(
        $scan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeReceiptStages.*?END_FUNCTION')).Value
    $cleanupBlock = [regex]::Match(
        $scan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleAxisDs402HomeCleanupStages.*?END_FUNCTION')).Value
    if ([string]::IsNullOrWhiteSpace($startBlock) -or
        [string]::IsNullOrWhiteSpace($outcomeBlock) -or
        [string]::IsNullOrWhiteSpace($retireBlock) -or
        [string]::IsNullOrWhiteSpace($processBlock)) {
        throw "$Owner DS402 start, outcome, retire, or cyclic processor is missing."
    }
    $splitPresent = -not [string]::IsNullOrWhiteSpace($receiptBlock)
    if ($splitPresent -ne
        (-not [string]::IsNullOrWhiteSpace($cleanupBlock))) {
        throw "$Owner DS402 receipt/cleanup split helpers must be paired."
    }
    $warmProcessBlock = $processBlock
    $processAndCleanupBlock = $processBlock
    if ($splitPresent) {
        $warmProcessBlock = $receiptBlock + "`n" + $processBlock
        $processAndCleanupBlock = $processBlock + "`n" + $cleanupBlock
    }
    $receiptFinalizerBlock = if ($splitPresent) {
        $receiptBlock
    }
    else {
        $processBlock
    }

    Assert-LasalDs402HomeWarmReconcileContract `
        -StartBlock $startBlock `
        -ProcessBlock $warmProcessBlock `
        -Owner $Owner
    Assert-LasalDs402HomePendingFreezeCleanupContract `
        -ProcessBlock $warmProcessBlock `
        -Owner $Owner
    Assert-LasalDs402HomeBoundedCleanupContract `
        -ProcessBlock $processAndCleanupBlock `
        -ExpectedExpiredFailClosedArmCount $(if ($splitPresent) { 4 } else { 1 }) `
        -Owner $Owner

    Assert-Match $scan (
        '(?s)if\s+CommandId\s*=\s*0x7D15\s+then.*?' +
        'HandleAxisDs402HomeStart\(.*?' +
        'elsif\s+CommandId\s*=\s*0x7D16\s+then.*?' +
        'HandleAxisDs402HomeOutcome\(') (
        "$Owner does not route the exact 0x7D15/0x7D16 pair.")
    Assert-Match $scan (
        '(?s)FUNCTION\s+GLOBAL\s+LMCDiagnosticsService::ProcessOperations.*?' +
        'ProcessAxisDs402Home\(\).*?END_FUNCTION') (
        "$Owner cyclic processor does not invoke the DS402 Home state machine.")
    Assert-Match $startBlock (
        '(?s)(?=.*?RequestSize\s*<>\s*72)' +
        '(?=.*?homingMethod\s*:=\s*\(pRequest\s*\+\s*36\)\^\$DINT)' +
        '(?=.*?homePosition\s*:=\s*\(pRequest\s*\+\s*40\)\^\$DINT)' +
        '(?=.*?velocity\s*:=\s*\(pRequest\s*\+\s*44\)\^\$DINT)' +
        '(?=.*?acceleration\s*:=\s*\(pRequest\s*\+\s*48\)\^\$DINT)' +
        '(?=.*?distanceLimit\s*:=\s*\(pRequest\s*\+\s*52\)\^\$DINT)' +
        '(?=.*?torqueLimit\s*:=\s*\(pRequest\s*\+\s*56\)\^\$DINT)' +
        '(?=.*?bufferMode\s*:=\s*\(pRequest\s*\+\s*60\)\^\$UINT)' +
        '(?=.*?reservedValue\s*:=\s*\(pRequest\s*\+\s*62\)\^\$UINT)' +
        '(?=.*?timeoutMs\s*:=\s*\(pRequest\s*\+\s*64\)\^\$UDINT)' +
        '(?=.*?executeToken\s*:=\s*\(pRequest\s*\+\s*68\)\^\$UDINT)') (
        "$Owner 0x7D15 exact 72-byte request decode is incomplete.")
    Assert-Match $startBlock (
        '(?s)homingMethod\s*<>\s*37.*?' +
        'homePosition\s*<>\s*0.*?' +
        'velocity\s*<>\s*0.*?' +
        'acceleration\s*<>\s*0.*?' +
        'distanceLimit\s*<>\s*0.*?' +
        'torqueLimit\s*<>\s*0.*?' +
        'bufferMode\s*<>\s*1.*?' +
        'reservedValue\s*<>\s*0.*?' +
        'timeoutMs\s*=\s*0.*?' +
        'executeToken\s*<>\s*0x32303448') (
        "$Owner 0x7D15 must accept only method 37, offset/dynamics zero and Aborting.")
    Assert-Match $startBlock (
        '(?s)\(statusWord\s+and\s+0x006F\)\s*<>\s*0x0040.*?' +
        '\(statusWord\s+and\s+0x006F\)\s*<>\s*0x0021.*?' +
        '\(statusWord\s+and\s+0x006F\)\s*<>\s*0x0023.*?' +
        '\(statusWord\s+and\s+0x006F\)\s*<>\s*0x0027') (
        "$Owner method 37 start does not admit the complete non-fault DS402 state set.")
    if ($startBlock -match
            '(?i)\(statusWord\s+and\s+0x(?:0*6F)\)\s*=\s*0x(?:0*27)|OperationEnabled\s*=\s*TRUE') {
        throw "$Owner method 37 start incorrectly requires DS402 Operation Enabled."
    }
    if ($processBlock -match '(?i)0x6099|0x609A') {
        throw "$Owner method 37 processor still writes unused switch-search dynamics."
    }
    Assert-Match $processBlock (
        '(?s)sdoIndex\s*:=\s*0x607C.*?' +
        'sdoData\s*:=\s*Ds402HomeState\[recordBase\s*\+\s*10\]\^?\$UDINT.*?' +
        'sdoIndex\s*:=\s*0x6098.*?' +
        'sdoData\s*:=\s*Ds402HomeState\[recordBase\s*\+\s*9\]\^?\$UDINT.*?' +
        'sdoIndex\s*:=\s*0x6060.*?' +
        'sdoData\s*:=\s*6') (
        "$Owner method 37 setup must write 0x607C=0, 0x6098=37 and mode 6.")
    Assert-Match $scan '#define\s+LMC_DIAG_DS402_HOME_ENABLED\s+(?:TRUE|FALSE)' (
        "$Owner dedicated DS402 Home gate is missing.")
    Assert-Match $startBlock (
        '(?s)currentCycle\s*:=\s*ops\.tAbsolute.*?' +
        'Ds402HomeState\[118\](?:\^?\$UDINT)?\s*:=\s*currentCycle.*?' +
        'Ds402HomeState\[119\]\s*:=\s*0') (
        "$Owner preflight does not pin the absolute service-clock epoch in slots 118/119.")
    Assert-Match $processAndCleanupBlock (
        '(?s)serviceNow\s*:=\s*ops\.tAbsolute.*?' +
        'serviceStart\s*:=\s*Ds402HomeState\[118\]\^?\$UDINT.*?' +
        'cleanupStart\s*:=\s*Ds402HomeState\[119\]\^?\$UDINT.*?' +
        '\(serviceNow\s*-\s*serviceStart\)\s*>=\s*timeoutMs.*?' +
        'Ds402HomeState\[119\]\^?\$UDINT\s*:=\s*serviceNow.*?' +
        '\(serviceNow\s*-\s*cleanupStart\)\s*>=\s*1000') (
        "$Owner timeout/cleanup is not independent of a frozen latch cycle.")
    if ($processAndCleanupBlock -match
            ('(?is)\bif\b(?:(?!\bthen\b).)*\bnewCycle\b' +
             '(?:(?!\bthen\b).)*\(serviceNow\s*-\s*' +
             '(?:serviceStart|cleanupStart)\)') -or
        $processAndCleanupBlock -match
            ('(?is)\bif\b(?:(?!\bthen\b).)*\(serviceNow\s*-\s*' +
             '(?:serviceStart|cleanupStart)\)(?:(?!\bthen\b).)*' +
             '\bnewCycle\b') -or
        $processAndCleanupBlock -match
            '(?is)if\s+newCycle\s+then\s*if\s+\(serviceNow\s*-') {
        throw "$Owner incorrectly gates a service-clock timeout behind newCycle."
    }
    Assert-Match $outcomeBlock (
        '(?s)RequestSize\s*<>\s*44.*?' +
        'ResponseCapacity\s*<\s*92.*?' +
        '\(pResponse\s*\+\s*88\)\^\$UDINT.*?' +
        'ResponseSize\s*:=\s*92') (
        "$Owner 0x7D16 does not publish the exact 92-byte retained outcome.")
    foreach ($identityBlock in @(
            @{ Name = 'Outcome'; Text = $outcomeBlock },
            @{ Name = 'Retire'; Text = $retireBlock })) {
        if ([regex]::Matches(
                $identityBlock.Text,
                '(?i)currentBootId\s*:=\s*GetDiagnosticsBootId\(\s*\)\s*;').Count -ne 1) {
            throw (
                "$Owner $($identityBlock.Name) must sample current BootId " +
                'exactly once from GetDiagnosticsBootId.')
        }
        Assert-Match $identityBlock.Text (
            '(?s)if\s+\(schemaVersion\s*<>\s*1\).*?' +
            'detailCode\s*:=\s*28\s*;\s*' +
            'elsif\s+diagnosticsBuild\s*<>\s*1\s+then\s*' +
            'detailCode\s*:=\s*16\s*;\s*' +
            'elsif\s+\(currentBootId\s*=\s*0\)\s*\|\s*' +
            '\(bootId\s*<>\s*currentBootId\)\s+then\s*' +
            'detailCode\s*:=\s*17\s*;\s*' +
            'elsif\s+mapRevision\s*<>\s*LMC_DIAG_MAP_REVISION\s+then\s*' +
            'detailCode\s*:=\s*18\s*;\s*' +
            'elsif\s+\(sizeof\(Ds402HomeState\)\s*<>\s*512\).*?' +
            'detailCode\s*:=\s*29') (
            "$Owner $($identityBlock.Name) does not preserve detail " +
            '28/16/17/18/29 identity classification order.')
    }
    Assert-Match $outcomeBlock (
        '(?s)\(baseOutcomeState\s*=\s*1\)\s*&\s*' +
        '\(Ds402HomeState\[92\]\s*=\s*101\)\s*&\s*' +
        '\(Ds402HomeState\[93\]\s*=\s*TO_DINT\(Reference\s*-\s*1\)\).*?' +
        'detailCode\s*:=\s*26') (
        "$Owner stage-101 active DS402 record is not reported as indeterminate.")
    Assert-Match $outcomeBlock (
        '(?s)baseOutcomeState\s*=\s*2.*?' +
        'Ds402HomeState\[recordBase\s*\+\s*18\]\s*=\s*0.*?' +
        'Ds402HomeState\[recordBase\s*\+\s*17\]\^?\$UDINT\s+and\s*' +
        '0x0008\)\s*=\s*0.*?' +
        'Ds402HomeState\[recordBase\s*\+\s*17\]\^?\$UDINT\s+and\s*' +
        '0x2000\)\s*=\s*0.*?' +
        '0x006F\)\s*=\s*0x0040\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0021\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0023\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0027') (
        "$Owner succeeded outcome does not retain exact position/status evidence.")
    Assert-Match $processBlock (
        '(?s)currentCycle\s*:=\s*Ds402HomeState\[110\]\^?\$UDINT\s*;\s*' +
        'previousCycle\s*:=\s*currentCycle\s*;.*?' +
        'newCycle\s*:=\s*currentCycle\s*<>\s*previousCycle\s*;.*?' +
        'if\s+newCycle\s+then\s*' +
        'Ds402HomeState\[110\]\s*:=\s*currentCycle\^?\$DINT') (
        "$Owner fresh-cycle provenance is not tied to retained slot 110.")
    Assert-Match $processBlock (
        '(?s)snapshot\[TO_DINT\(healthOffset\s*\+\s*28\)\]\^?\$UDINT\s*' +
        '<>\s*currentCycle') (
        "$Owner axis-health snapshot freshness is not tied to currentCycle.")
    Assert-Match $processBlock (
        '(?s)32\s*:.*?Ds402HomeState\[112\]\s*:=\s*currentCycle\^?\$DINT.*?' +
        '33\s*:.*?Ds402HomeState\[112\]\s*:=\s*currentCycle\^?\$DINT.*?' +
        '34\s*:.*?if\s+newCycle\s*&\s*' +
        '\(currentCycle\s*<>\s*Ds402HomeState\[112\]\^?\$UDINT\)\s+then.*?' +
        'Ds402HomeState\[94\]\s*<>\s*0.*?' +
        'Ds402HomeState\[113\]\s*<>\s*0.*?' +
        'Ds402HomeState\[116\]\s*<>\s*0.*?' +
        'Ds402HomeState\[117\]\s*<>\s*0.*?' +
        'Ds402HomeState\[127\]\s*<>\s*0.*?' +
        'statusWord\s+and\s+0x0008.*?' +
        'statusWord\s+and\s+0x2000.*?' +
        'baseState\s*<>\s*0x0040.*?' +
        'baseState\s*<>\s*0x0021.*?' +
        'baseState\s*<>\s*0x0023.*?' +
        'baseState\s*<>\s*0x0027.*?' +
        'actualPosition\s*<>\s*0') (
        "$Owner final success is not dominated by a fresh post-release sample.")
    Assert-Match $processBlock (
        '(?s)34\s*:.*?if\s+newCycle\s*&.*?then\s*' +
        'if\s+\(Ds402HomeState\[94\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[113\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[116\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[117\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[127\]\s*<>\s*0\)\s*\|.*?' +
        'Ds402HomeState\[106\]\s*:=\s*2.*?' +
        'ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'if\s+ownerResult\s*=\s*0\s+then.*?' +
        'Ds402HomeState\[125\]\s*:=\s*2.*?' +
        'ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'if\s+ownerResult\s*=\s*1\s+then.*?' +
        'Ds402HomeState\[92\]\s*:=\s*LMC_DIAG_DS402_STAGE_FINALIZE') (
        "$Owner stage 34 does not preserve fail-closed ORs and durable " +
        'terminal-success receipt publication.')
    Assert-Match $receiptFinalizerBlock (
        ('(?s)if\s+stage\s*=\s*LMC_DIAG_DS402_STAGE_FINALIZE.*?' +
         'LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
         'Ds402HomeState\[recordBase\]\s*:=\s*terminalRecordState.*?' +
         'Ds402HomeState\[92\]\s*:=\s*0')) (
        "$Owner terminal receipt finalizer does not publish the retained " +
        'record before clearing the lifecycle stage.')
}
function Assert-LasalDs402OwnerReceiptProviderMutationFences {
    param(
        [string]$ProviderBlock,
        [string]$Stage87HelperBlock,
        [string]$ControlServiceText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $ProviderBlock
    $helperScan = Get-LasalScanText $Stage87HelperBlock
    $controlScan = Get-LasalScanText $ControlServiceText
    $blocker = "$Owner DS402 owner receipt mutation blocker:"
    Assert-Match $scan (
        '(?is)^\s*FUNCTION\s+GLOBAL\s+' +
        'LMCControlCommandService::PublishAxisOwnershipDs402Receipt\b.*?' +
        'END_FUNCTION\s*$') (
        "$blocker provider implementation scope drifted.")
    Assert-Match $helperScan (
        '(?is)^\s*FUNCTION\s+' +
        'LMCControlCommandService::' +
        'HandleAxisOwnershipDs402ReceiptStage87Recovery\b.*?' +
        'END_FUNCTION\s*$') (
        "$blocker stage87 helper implementation scope drifted.")

    $abiBodyPattern = (
        'VAR_INPUT\s*' +
        'AxisMask\s*:\s*UDINT\s*;\s*' +
        'AdmissionToken\s*:\s*UDINT\s*;\s*' +
        'OwnerGeneration\s*:\s*UDINT\s*;\s*' +
        'ReportKind\s*:\s*UINT\s*;\s*' +
        'ReportValue0\s*:\s*UDINT\s*;\s*' +
        'ReportValue1\s*:\s*UDINT\s*;\s*' +
        'ObservationCycle\s*:\s*UDINT\s*;\s*' +
        'pDs402State\s*:\s*\^void\s*;\s*' +
        'Ds402StateSize\s*:\s*UDINT\s*;\s*' +
        'END_VAR\s*;?\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
    $classAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+' +
         'PublishAxisOwnershipDs402Receipt\s*' +
         $abiBodyPattern + '\s*(?=FUNCTION\b)'))
    $implementationAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::' +
         'PublishAxisOwnershipDs402Receipt\s*' +
         $abiBodyPattern + '\s*(?=VAR\b)'))
    if (($classAbiMatches.Count -ne 1) -or
        ($implementationAbiMatches.Count -ne 1)) {
        throw (
            "$blocker public declaration and implementation must expose " +
            'the exact closed nine-input/one-output ABI.')
    }

    $stage87AbiBodyPattern = (
        'VAR_INPUT\s*' +
        'pState\s*:\s*\^USINT\s*;\s*' +
        'activeIndex\s*:\s*DINT\s*;\s*' +
        'AxisMask\s*:\s*UDINT\s*;\s*' +
        'ReportKind\s*:\s*UINT\s*;\s*' +
        'ReportValue0\s*:\s*UDINT\s*;\s*' +
        'ReportValue1\s*:\s*UDINT\s*;\s*' +
        'ObservationCycle\s*:\s*UDINT\s*;\s*' +
        'END_VAR\s*;?\s*' +
        'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*;?')
    $stage87ClassAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*' +
         $stage87AbiBodyPattern + '\s*(?=FUNCTION\b)'))
    $stage87ImplementationAbiMatches = [regex]::Matches(
        $controlScan,
        ('(?is)\bFUNCTION\s+' +
         'LMCControlCommandService::' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*' +
         $stage87AbiBodyPattern + '\s*(?=VAR\b)'))
    $stage87BroadHeaders = [regex]::Matches(
        $controlScan,
        ('(?im)^\s*FUNCTION\b[^\r\n]*' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*$'))
    if (($stage87ClassAbiMatches.Count -ne 1) -or
        ($stage87ImplementationAbiMatches.Count -ne 1) -or
        ($stage87BroadHeaders.Count -ne 2)) {
        throw (
            "$blocker stage87 helper declaration and implementation must " +
            'remain private with the exact closed seven-input/one-output ABI.')
    }

    $controlProviderMatches = [regex]::Matches(
        $controlScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnershipDs402Receipt\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    $controlStage87HelperMatches = [regex]::Matches(
        $controlScan,
        ('(?ims)^\s*FUNCTION\s+' +
         'LMCControlCommandService::' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if (($controlProviderMatches.Count -ne 1) -or
        ($controlStage87HelperMatches.Count -ne 1) -or
        ($controlProviderMatches[0].Value.Trim() -cne $scan.Trim()) -or
        ($controlStage87HelperMatches[0].Value.Trim() -cne
            $helperScan.Trim())) {
        throw (
            "$blocker composite adapter/helper implementation scope or " +
            'private helper identity drifted.')
    }

    Assert-Match $controlScan (
        '(?ims)^\s*#define\s+LMC_DS402_OWNER_RECEIPT_MAGIC\s+' +
        '0x44344850\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_PREPARED\s+1\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_CLEAR_IDENTITY\s+2\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_CLEAR_OBSERVER\s+3\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_CLEAR_SINGLETON\s+4\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_CLEAR_RECORD\s+5\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_COMPLETE\s+6\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_RECEIPT_ROLLBACK\s+0\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_STAGE_RESERVE_INTENT\s+87\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_STAGE_ROLLBACK_PREPARED\s+88\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_INTENT_MAGIC\s+0x4434494E\s*$\s*' +
        '^\s*#define\s+LMC_DS402_OWNER_ADOPT_MAGIC\s+0x44344144\s*$') (
        "$blocker durable receipt/stage ABI constants drifted.")

    if (($scan + $helperScan) -match
            ('(?is)\b[A-Za-z_][A-Za-z0-9_]*\s*\.\s*' +
             '[A-Za-z_][A-Za-z0-9_]*|\b_gettime\s*\(')) {
        throw "$blocker adapter/helper may not resample a client or clock."
    }

    $localVarMatch = [regex]::Match(
        $scan,
        ('(?is)VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*' +
         'VAR\s*(?<Body>.*?)\s*END_VAR'))
    if (-not $localVarMatch.Success) {
        throw "$blocker local variable block is missing."
    }
    $stage87LocalVarMatch = [regex]::Match(
        $helperScan,
        ('(?is)VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*' +
         'VAR\s*(?<Body>.*?)\s*END_VAR'))
    if (-not $stage87LocalVarMatch.Success) {
        throw "$blocker stage87 helper local variable block is missing."
    }

    $expectedAdapterLocalInventory = @(
        'pstate:^usint',
        'identity:array[0..71]ofusint',
        'activeindex:dint',
        'axisindex:dint',
        'recordbase:dint',
        'observerbase:dint',
        'identityheaderbase:dint',
        'identitytailbase:dint',
        'receiptphase:dint',
        'receiptkind:dint',
        'expectedownerstate:dint',
        'requiredphase:uint',
        'clearindex:dint',
        'recordbytebase:udint',
        'recordgeneration:udint',
        'callersessionepoch:udint',
        'requestsequence:udint',
        'receiptgeneration:udint',
        'ownerresult:dint',
        'identitycompareresult:udint',
        'firstreceipt:bool',
        'partialreceipt:bool',
        'stagevalid:bool',
        'identitypre:bool',
        'identitypost:bool',
        'observerpre:bool',
        'observerpost:bool',
        'recordpre:bool',
        'recordbodypost:bool',
        'recordpost:bool',
        'singletonpre:bool',
        'singletonpost:bool',
        'preemptioncompatible:bool',
        'sessionclosedrollback:bool',
        'surfacevalid:bool')
    $expectedStage87LocalInventory = @(
        'identity:array[0..71]ofusint',
        'axisindex:dint',
        'recordbase:dint',
        'identityheaderbase:dint',
        'identitytailbase:dint',
        'intentrecordstate:dint',
        'intentrawstate:dint',
        'intentscanindex:dint',
        'requiredphase:uint',
        'clearindex:dint',
        'recordbytebase:udint',
        'recordgeneration:udint',
        'callersessionepoch:udint',
        'requestsequence:udint',
        'intentgenerationsnapshot:udint',
        'intentobservationcycle:udint',
        'candidateadmissiontoken:udint',
        'candidateownergeneration:udint',
        'candidateidentitysize:udint',
        'candidateidentityprefixsize:udint',
        'candidateidentitytailsize:udint',
        'candidateownerkind:uint',
        'candidatecommandid:uint',
        'candidatereference:uint',
        'candidateresourcekind:uint',
        'candidateadmissionmode:uint',
        'ownerresult:dint',
        'adoptionprepared:bool',
        'rawintentvalid:bool',
        'bridgeintentvalid:bool',
        'intentidentityvalid:bool',
        'candidaterecordvalid:bool',
        'candidateobservervalid:bool',
        'candidatereserved:bool',
        'candidatesessionclosed:bool',
        'candidateactive:bool',
        'canonicalidle:bool',
        'idlesurfacevalid:bool',
        'intenttupleelsewhere:bool',
        'differentownervalid:bool',
        'stagevalid:bool',
        'preemptioncompatible:bool')
    $adapterLocalInventory = @(
        [regex]::Matches(
            $localVarMatch.Groups['Body'].Value,
            ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
             '(?<Type>[^;\r\n]+)\s*;')) |
            ForEach-Object {
                ($_.Groups['Name'].Value + ':' +
                 $_.Groups['Type'].Value).ToLowerInvariant() -replace '\s+', ''
            })
    $stage87LocalInventory = @(
        [regex]::Matches(
            $stage87LocalVarMatch.Groups['Body'].Value,
            ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
             '(?<Type>[^;\r\n]+)\s*;')) |
            ForEach-Object {
                ($_.Groups['Name'].Value + ':' +
                 $_.Groups['Type'].Value).ToLowerInvariant() -replace '\s+', ''
            })
    if (([string]::Join('|', $adapterLocalInventory) -cne
            [string]::Join('|', $expectedAdapterLocalInventory)) -or
        ([string]::Join('|', $stage87LocalInventory) -cne
            [string]::Join('|', $expectedStage87LocalInventory))) {
        throw (
            "$blocker exact adapter/helper local inventory drifted " +
            "($($adapterLocalInventory.Count)/35, " +
            "$($stage87LocalInventory.Count)/42).")
    }
    $localPointerDeclarations = [regex]::Matches(
        $localVarMatch.Groups['Body'].Value,
        ('(?im)^\s*(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*:\s*' +
         '\^(?<Type>[A-Za-z_][A-Za-z0-9_]*)\s*;'))
    if (($localPointerDeclarations.Count -ne 1) -or
        ([regex]::Replace(
                $localPointerDeclarations[0].Value,
                '\s+',
                '').ToLowerInvariant() -cne 'pstate:^usint;')) {
        throw "$blocker pState must remain the only local pointer."
    }
    $pStateAssignments = [regex]::Matches(
        $scan,
        '(?im)^\s*pState\s*:=\s*(?<Value>[^\r\n;,]+)\s*;')
    if (($pStateAssignments.Count -ne 1) -or
        ([regex]::Replace(
                $pStateAssignments[0].Groups['Value'].Value,
                '\s+',
                '').ToLowerInvariant() -cne 'pds402state$^usint')) {
        throw "$blocker pState initialization or reassignment drifted."
    }

    Assert-Match $scan (
        '(?is)END_VAR\s*' +
        'Result\s*:=\s*-1\s*;\s*' +
        'if\s*\(pDs402State\s*=\s*NIL\)\s*\|\s*' +
        '\(Ds402StateSize\s*<>\s*512\)\s*\|\s*' +
        '\(AxisMask\s*=\s*0\)\s*\|\s*' +
        '\(AxisMask\s*>\s*0x00000008\)\s*\|\s*' +
        '\(\(AxisMask\s+and\s+\(AxisMask\s*-\s*1\)\)\s*<>\s*0\)\s*\|\s*' +
        '\(\(ReportKind\s*<>\s*LMC_DS402_OWNER_RECEIPT_ROLLBACK\)\s*&\s*' +
        '\(ReportKind\s*<>\s*LMC_OWNER_REPORT_TERMINAL_SUCCESS\)\s*&\s*' +
        '\(ReportKind\s*<>\s*' +
        'LMC_OWNER_REPORT_TERMINAL_SAFE_FAILURE\)\)\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'pState\s*:=\s*pDs402State\$\^USINT\s*;\s*' +
        'activeIndex\s*:=\s*\(pState\s*\+\s*372\)\^\$DINT\s*;\s*' +
        'if\s*\(activeIndex\s*<\s*0\)\s*\|\s*' +
        '\(activeIndex\s*>\s*3\)\s+then\s*' +
        'RETURN\s*;\s*end_if\s*;\s*' +
        'axisIndex\s*:=\s*activeIndex\s*\+\s*1\s*;\s*' +
        'recordBase\s*:=\s*LMC_OWNER_GLOBAL_SLOTS\s*\+\s*' +
        '\(activeIndex\s*\*\s*LMC_OWNER_AXIS_STRIDE\)\s*;\s*' +
        'recordByteBase\s*:=\s*TO_UDINT\(' +
        'activeIndex\s*\*\s*92\)\s*;\s*' +
        $stage87AdapterCallPattern) (
        "$blocker input guard or state-selection prefix drifted.")

    $ignoredCallNames = @('and', 'else', 'if', 'not', 'or', 'then')
    $callContracts = @(
        [pscustomobject]@{
            Label = 'adapter'
            Text = $scan
            Expected = [ordered]@{
                '_memcmp' = 1
                '_memset' = 5
                'sizeof' = 2
                'to_dint' = 1
                'to_udint' = 15
                'to_uint' = 1
                'validateaxisownershipidentity' = 1
                'handleaxisownershipds402receiptstage87recovery' = 1
            }
        },
        [pscustomobject]@{
            Label = 'stage87 helper'
            Text = $helperScan
            Expected = [ordered]@{
                '_memcpy' = 4
                '_memset' = 6
                'sizeof' = 4
                'to_dint' = 1
                'to_udint' = 8
                'to_uint' = 6
                'validateaxisownershipidentity' = 2
            }
        })
    foreach ($callContract in $callContracts) {
        $actualCallHistogram = [ordered]@{}
        foreach ($callMatch in [regex]::Matches(
                $callContract.Text,
                ('(?i)(?<![A-Za-z0-9_])' +
                 '(?<Name>[A-Za-z_][A-Za-z0-9_]*)\s*\('))) {
            $callName = $callMatch.Groups['Name'].Value.ToLowerInvariant()
            if ($ignoredCallNames -contains $callName) {
                continue
            }
            if (-not $callContract.Expected.Contains($callName)) {
                throw (
                    "$blocker $($callContract.Label) unsupported call " +
                    "'$callName'.")
            }
            if (-not $actualCallHistogram.Contains($callName)) {
                $actualCallHistogram[$callName] = 0
            }
            $actualCallHistogram[$callName]++
        }
        foreach ($callName in $callContract.Expected.Keys) {
            if ((-not $actualCallHistogram.Contains($callName)) -or
                ($actualCallHistogram[$callName] -ne
                    $callContract.Expected[$callName])) {
                throw (
                    "$blocker $($callContract.Label) call '$callName' count is " +
                    "$($actualCallHistogram[$callName]), expected " +
                    "$($callContract.Expected[$callName]).")
            }
        }
    }

    $persistentMutationPattern = (
        '(?is)(?:' +
        '(?:\(\s*(?:pState|pDs402State)\s*\+\s*[^)]*\)|' +
        '(?:pState|pDs402State))\s*\^\$' +
        '[A-Za-z_][A-Za-z0-9_]*\s*' +
        '(?::|\+|-|\*|/|and|or|xor)\s*=\s*[^;]+;' +
        '|' +
        '\bOwnership[A-Za-z0-9_]*State\s*\[[^\]]+\]\s*' +
        '(?:\$[A-Za-z_][A-Za-z0-9_]*\s*)?' +
        '(?::|\+|-|\*|/|and|or|xor)\s*=\s*[^;]+;' +
        '|' +
        '\b_memset\s*\(\s*dest\s*:=\s*' +
        '(?:(?:pState|pDs402State)(?:\s*\+)?|' +
        '#Ownership[A-Za-z0-9_]*State\s*\[)' +
        '.*?\)\s*;' +
        '|' +
        '\b_memcpy\s*\(\s*ptr1\s*:=\s*' +
        '(?:(?:pState|pDs402State)(?:\s*\+)?|' +
        '#Ownership[A-Za-z0-9_]*State\s*\[)' +
        '.*?\)\s*;' +
        ')')
    $mutationContracts = @(
        [pscustomobject]@{
            Label = 'adapter'
            Text = $scan
            Count = 28
            Length = 1321
            Sha256 =
                '91A354E4243C20A7EFD1FCF326B04CDDD99CE80BCAF9F3ED8F7D7B4F5C5EB0E4'
        },
        [pscustomobject]@{
            Label = 'stage87 helper'
            Text = $helperScan
            Count = 49
            Length = 2225
            Sha256 =
                '3E30219133119237C9115F267CDEA3CC186759E96DC7DBCD517305FB06AC2F17'
        })
    $adapterPersistentMutations = @()
    $adapterNormalizedMutations = @()
    $stage87PersistentMutations = @()
    $stage87NormalizedMutations = @()
    foreach ($mutationContract in $mutationContracts) {
        $scopeMutations = [regex]::Matches(
            $mutationContract.Text,
            $persistentMutationPattern)
        $scopeNormalizedMutations = @(
            foreach ($mutation in $scopeMutations) {
                [regex]::Replace(
                    $mutation.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
        $scopeJoinedMutations =
            [string]::Join('|', $scopeNormalizedMutations)
        $scopeSha = [Security.Cryptography.SHA256]::Create()
        try {
            $scopeJoinedBytes =
                [Text.Encoding]::UTF8.GetBytes($scopeJoinedMutations)
            $scopeJoinedSha256 = (
                [BitConverter]::ToString(
                    $scopeSha.ComputeHash($scopeJoinedBytes))
            ).Replace('-', '')
        }
        finally {
            $scopeSha.Dispose()
        }
        if (($scopeMutations.Count -ne $mutationContract.Count) -or
            ($scopeJoinedMutations.Length -ne $mutationContract.Length) -or
            ($scopeJoinedSha256 -cne $mutationContract.Sha256)) {
            throw (
                "$blocker $($mutationContract.Label) persistent mutation " +
                "inventory/order drifted ($($scopeMutations.Count)/" +
                "$($mutationContract.Count), $($scopeJoinedMutations.Length)/" +
                "$($mutationContract.Length), $scopeJoinedSha256).")
        }
        if ($mutationContract.Label -ceq 'adapter') {
            $adapterPersistentMutations = @($scopeMutations)
            $adapterNormalizedMutations = @($scopeNormalizedMutations)
        }
        else {
            $stage87PersistentMutations = @($scopeMutations)
            $stage87NormalizedMutations = @($scopeNormalizedMutations)
        }
    }

    $persistentMutations = @(
        $stage87PersistentMutations + $adapterPersistentMutations)
    $normalizedMutations = @(
        $stage87NormalizedMutations + $adapterNormalizedMutations)
    $joinedMutations = [string]::Join('|', $normalizedMutations)
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $joinedBytes = [Text.Encoding]::UTF8.GetBytes($joinedMutations)
        $joinedSha256 = (
            [BitConverter]::ToString($sha.ComputeHash($joinedBytes))
        ).Replace('-', '')
    }
    finally {
        $sha.Dispose()
    }
    if (($persistentMutations.Count -ne 77) -or
        ($joinedMutations.Length -ne 3547) -or
        ($joinedSha256 -cne
            '95A9EAF512D0F4DCB5B406F2FB8B1B433A420A8C729C722AF3BC7C41B93388BA')) {
        throw (
            "$blocker transitive persistent mutation inventory/order drifted " +
            "($($persistentMutations.Count)/77, " +
            "$($joinedMutations.Length)/3547, $joinedSha256).")
    }
    if ($normalizedMutations[-1] -cne
        ('(pstate+500)^$dint:=' +
         'lmc_ds402_owner_receipt_complete;')) {
        throw "$blocker COMPLETE is not the final persistent mutation."
    }

    $adapterResultValues = @(
        [regex]::Matches(
            $scan,
            '(?is)\bResult\s*:=\s*(?<Value>[^;]+)\s*;') |
            ForEach-Object {
                $value = [regex]::Replace(
                    $_.Groups['Value'].Value,
                    '\s+',
                    '').ToLowerInvariant()
                if ($value.StartsWith(
                        'handleaxisownershipds402receiptstage87recovery(',
                        [StringComparison]::Ordinal)) {
                    'stage87helper'
                }
                else {
                    $value
                }
            })
    $adapterResultSequence = [string]::Join('|', $adapterResultValues)
    $expectedAdapterResultSequence = (
        '-1|stage87helper|-2|-2|-3|-3|-3|ownerresult|0|-3|0|1|' +
        '-1|-3|-3|1')
    if ($adapterResultSequence -cne $expectedAdapterResultSequence) {
        throw "$blocker adapter Result value/count/order inventory drifted."
    }

    $stage87ResultSequence = [string]::Join(
        '|',
        @([regex]::Matches(
                $helperScan,
                '(?is)\bResult\s*:=\s*(?<Value>[^;]+)\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Groups['Value'].Value,
                    '\s+',
                    '').ToLowerInvariant()
            }))
    $expectedStage87ResultSequence = (
        '-2|-3|-2|-3|-1|-3|-3|-3|-3|-3|-3|0|2|2|-1|-3')
    if ($stage87ResultSequence -cne $expectedStage87ResultSequence) {
        throw "$blocker stage87 helper Result value/count/order inventory drifted."
    }
    $stage87ControlFlowTokens = @(
        [regex]::Matches(
            $helperScan,
            '(?is)\bResult\s*:=\s*[^;]+\s*;|\bRETURN\s*;') |
            ForEach-Object {
                [regex]::Replace(
                    $_.Value,
                    '\s+',
                    '').ToLowerInvariant()
            })
    $stage87ControlFlowInventory =
        [string]::Join('|', $stage87ControlFlowTokens)
    $controlFlowSha = [Security.Cryptography.SHA256]::Create()
    try {
        $controlFlowBytes = [Text.Encoding]::UTF8.GetBytes(
            $stage87ControlFlowInventory)
        $controlFlowSha256 = (
            [BitConverter]::ToString(
                $controlFlowSha.ComputeHash($controlFlowBytes))
        ).Replace('-', '')
    }
    finally {
        $controlFlowSha.Dispose()
    }
    if (($stage87ControlFlowTokens.Count -ne 31) -or
        ($stage87ControlFlowInventory.Length -ne 308) -or
        ($controlFlowSha256 -cne
            '3286789F5AC8DBED2E7CEF8757FD0E835F76BDEA0C7374FE39484F4188014153')) {
        throw (
            "$blocker stage87 Result/RETURN control-flow inventory drifted " +
            "($($stage87ControlFlowTokens.Count)/31, " +
            "$($stage87ControlFlowInventory.Length)/308, " +
            "$controlFlowSha256).")
    }

    Assert-Match $scan (
        '(?is)\(\(pState\s*\+\s*488\)\^\$UDINT\s*<>\s*' +
        'AdmissionToken\)\s*\|\s*' +
        '\(\(pState\s*\+\s*492\)\^\$UDINT\s*<>\s*' +
        'OwnerGeneration\)') (
        "$blocker retained token/generation metadata pair drifted.")
    Assert-Match $scan (
        '(?is)identityPre\s*:=.*?' +
        'OwnershipIdentityState\[identityHeaderBase\s*\+\s*3\]' +
        '\$UDINT\s*=\s*AdmissionToken\)\s*&\s*\(' +
        'OwnershipIdentityState\[identityHeaderBase\s*\+\s*4\]' +
        '\$UDINT\s*=\s*OwnerGeneration\)') (
        "$blocker identity token/generation pair drifted.")
    Assert-Match $scan (
        '(?is)observerPre\s*:=.*?else\s*' +
        'observerPre\s*:=\s*observerPre\s*&\s*' +
        '\(OwnershipObserverState\[observerBase\s*\+\s*1\]' +
        '\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(OwnershipObserverState\[observerBase\s*\+\s*2\]' +
        '\$UDINT\s*=\s*OwnerGeneration\)') (
        "$blocker observer token/generation pair drifted.")
    Assert-Match $scan (
        '(?is)recordPre\s*:=.*?' +
        'OwnershipState\[recordBase\s*\+\s*4\]\$UDINT\s*=\s*' +
        'AdmissionToken\)\s*&\s*\(' +
        'OwnershipState\[recordBase\s*\+\s*5\]\$UDINT\s*=\s*' +
        'OwnerGeneration\)') (
        "$blocker record token/generation pair drifted.")
    Assert-Match $scan (
        '(?is)singletonPre\s*:=\s*' +
        '\(OwnershipState\[10\]\$UDINT\s*=\s*AdmissionToken\)\s*&\s*' +
        '\(OwnershipState\[11\]\$UDINT\s*=\s*OwnerGeneration\)') (
        "$blocker singleton token/generation pair drifted.")
    Assert-Match $scan (
        '(?is)if\s*\(receiptGeneration\s*<>\s*recordGeneration\)\s*\|\s*' +
        '\(\(pState\s*\+\s*504\)\^\$DINT\s*<>\s*receiptKind\)') (
        "$blocker replay generation/kind comparison drifted.")

    $stage87Validation = [regex]::Match(
        $helperScan,
        ('(?is)ownerResult\s*:=\s*ValidateAxisOwnershipIdentity\(.*?' +
         'AdmissionToken\s*:=\s*candidateAdmissionToken.*?' +
         'OwnerGeneration\s*:=\s*candidateOwnerGeneration.*?' +
         'pIdentity\s*:=\s*#identity\[0\]\s*,\s*' +
         'IdentitySize\s*:=\s*sizeof\(identity\)\s*\)\s*;\s*' +
         'if\s+ownerResult\s*<>\s*0\s+then\s*' +
         'Result\s*:=\s*-3\s*;\s*RETURN\s*;\s*end_if\s*;'))
    if (-not $stage87Validation.Success -or
        $stage87PersistentMutations[0].Index -lt
            ($stage87Validation.Index + $stage87Validation.Length)) {
        throw (
            "$blocker stage87 persistent publication precedes exact " +
            'identity validation.')
    }

    $normalValidation = [regex]::Match(
        $scan,
        ('(?is)ownerResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
         'CommandId\s*:=\s*0x7D15.*?' +
         'AdmissionToken\s*:=\s*AdmissionToken.*?' +
         'OwnerGeneration\s*:=\s*OwnerGeneration.*?' +
         'if\s+ownerResult\s*<>\s*0\s+then\s*' +
         'Result\s*:=\s*ownerResult\s*;\s*RETURN\s*;\s*end_if\s*;'))
    if (-not $normalValidation.Success) {
        throw "$blocker normal receipt identity validation drifted."
    }
    $normalTail = $scan.Substring(
        $normalValidation.Index + $normalValidation.Length)
    Assert-Match $normalTail (
        '(?is)^\s*' +
        '\(pState\s*\+\s*496\)\^\$UDINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_MAGIC\s*;\s*' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_PREPARED\s*;\s*' +
        '\(pState\s*\+\s*504\)\^\$DINT\s*:=\s*receiptKind\s*;\s*' +
        '\(pState\s*\+\s*508\)\^\$UDINT\s*:=\s*' +
        'recordGeneration\s*;\s*' +
        '\(pState\s*\+\s*476\)\^\$DINT\s*:=\s*0\s*;') (
        "$blocker first receipt publication order drifted.")

    $preparedReplayMatches = [regex]::Matches(
        $scan,
        ('(?is)if\s+receiptPhase\s*=\s*' +
         'LMC_DS402_OWNER_RECEIPT_PREPARED\s+then\s*' +
         'Result\s*:=\s*0\s*;\s*RETURN\s*;\s*end_if\s*;'))
    $completeReplayMatches = [regex]::Matches(
        $scan,
        ('(?is)if\s+receiptPhase\s*=\s*' +
         'LMC_DS402_OWNER_RECEIPT_COMPLETE\s+then\s*' +
         'Result\s*:=\s*1\s*;\s*RETURN\s*;\s*end_if\s*;'))
    if (($preparedReplayMatches.Count -ne 1) -or
        ($completeReplayMatches.Count -ne 1)) {
        throw "$blocker PREPARED/COMPLETE replay gates drifted."
    }

    Assert-Match $scan (
        '(?is)if\s+receiptPhase\s*<=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_IDENTITY\s+then\s*' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_IDENTITY\s*;\s*' +
        'OwnershipIdentityState\[identityHeaderBase\]\s*:=\s*0\s*;.*?' +
        'end_if\s*;\s*' +
        'if\s+receiptPhase\s*<=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_OBSERVER\s+then\s*' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_OBSERVER\s*;\s*' +
        'OwnershipObserverState\[observerBase\]\s*:=\s*0\s*;.*?' +
        'end_if\s*;\s*' +
        'if\s+receiptPhase\s*<=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_SINGLETON\s+then\s*' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_SINGLETON\s*;\s*' +
        'OwnershipState\[10\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[11\]\s*:=\s*0\s*;\s*' +
        'OwnershipState\[12\]\s*:=\s*0\s*;\s*end_if\s*;\s*' +
        'if\s+receiptPhase\s*<=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_RECORD\s+then\s*' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_CLEAR_RECORD\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*35\]\s*:=\s*0\s*;\s*' +
        '_memset\(dest\s*:=\s*#OwnershipState\[recordBase\].*?' +
        'OwnershipState\[recordBase\]\s*:=\s*axisIndex\s*;\s*' +
        'OwnershipState\[recordBase\s*\+\s*35\]\$UDINT\s*:=\s*' +
        'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\s*;.*?' +
        '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
        'LMC_DS402_OWNER_RECEIPT_COMPLETE\s*;\s*end_if\s*;\s*' +
        'Result\s*:=\s*1\s*;\s*END_FUNCTION\s*$') (
        "$blocker ordered destructive clear/COMPLETE sequence drifted.")

}

function Assert-LasalDs402OwnerReceiptProviderContract {
    param(
        [string]$ControlServiceText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $ControlServiceText
    $validateMatches = [regex]::Matches(
        $scan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ValidateAxisOwnership\s*\r?$' +
         '.*?^\s*END_FUNCTION\s*\r?$'))
    $providerMatches = [regex]::Matches(
        $scan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnershipDs402Receipt\s*\r?$' +
         '.*?^\s*END_FUNCTION\s*\r?$'))
    $stage87HelperMatches = [regex]::Matches(
        $scan,
        ('(?ims)^\s*FUNCTION\s+' +
         'LMCControlCommandService::' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*\r?$' +
         '.*?^\s*END_FUNCTION\s*\r?$'))
    if (($validateMatches.Count -ne 1) -or
        ($providerMatches.Count -ne 1) -or
        ($stage87HelperMatches.Count -ne 1)) {
        throw (
            "$Owner validator, DS402 receipt adapter, or private stage87 " +
            'helper is missing.')
    }
    $validateBlock = $validateMatches[0].Value
    $providerBlock = $providerMatches[0].Value
    $stage87HelperBlock = $stage87HelperMatches[0].Value
    Assert-LasalDs402OwnerReceiptProviderMutationFences `
        -ProviderBlock $providerBlock `
        -Stage87HelperBlock $stage87HelperBlock `
        -ControlServiceText $ControlServiceText `
        -Owner $Owner

    Assert-Match $scan (
        '(?im)^\s*#define\s+' +
        'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK\s+3\s*$') (
        "$Owner exact session-close rollback phase constant is missing.")
    Assert-Match $validateBlock (
        ('(?is)RequiredPhase\s*=\s*' +
         'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK\s+then\s*' +
         'if\s+\(CommandId\s*<>\s*0x7D15\)\s*\|\s*' +
         '\(OwnerKind\s*<>\s*LMC_OWNER_KIND_DS402_HOME\)\s*\|\s*' +
         '\(ResourceKind\s*<>\s*' +
         'LMC_OWNER_RESOURCE_DS402_HOME_ENGINE\)\s*\|\s*' +
         '\(AdmissionMode\s*<>\s*' +
         'LMC_OWNER_ADMISSION_LIFECYCLE\)\s+then\s*RETURN\s*;.*?' +
         'expectedState\s*:=\s*LMC_OWNER_STATE_QUARANTINED\s*;')) (
        "$Owner phase 3 is not restricted to exact DS402 lifecycle rollback.")
    Assert-Match $validateBlock (
        ('(?is)OwnershipState\[recordBase\s*\+\s*1\]\s*=\s*' +
         'LMC_OWNER_STATE_QUARANTINED\)\s*&\s*' +
         '\(RequiredPhase\s*<>\s*' +
         'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK\)\s+then\s*' +
         'Result\s*:=\s*-3\s*;\s*RETURN\s*;')) (
        "$Owner quarantined records can escape the dedicated phase-3 fence.")

    Assert-Match $scan (
        '(?im)^\s*#define\s+LMC_DS402_OWNER_STAGE_RESERVE_INTENT\s+87\s*$') (
        "$Owner DS402 tokenless recovery stage constant is missing.")
    Assert-Match $scan (
        '(?im)^\s*#define\s+LMC_DS402_OWNER_INTENT_MAGIC\s+0x4434494E\s*$') (
        "$Owner DS402 tokenless recovery intent magic is missing.")
    Assert-Match $scan (
        '(?im)^\s*#define\s+LMC_DS402_OWNER_ADOPT_MAGIC\s+0x44344144\s*$') (
        "$Owner DS402 tokenless recovery adoption magic is missing.")
    Assert-Match $providerBlock (
        ('(?is)if\s+\(AdmissionToken\s*=\s*0\)\s*&\s*' +
         '\(OwnerGeneration\s*=\s*0\)\s+then\s*' +
         'Result\s*:=\s*' +
         'HandleAxisOwnershipDs402ReceiptStage87Recovery\(\s*' +
         'pState\s*:=\s*pState\s*,\s*' +
         'activeIndex\s*:=\s*activeIndex\s*,\s*' +
         'AxisMask\s*:=\s*AxisMask\s*,\s*' +
         'ReportKind\s*:=\s*ReportKind\s*,\s*' +
         'ReportValue0\s*:=\s*ReportValue0\s*,\s*' +
         'ReportValue1\s*:=\s*ReportValue1\s*,\s*' +
         'ObservationCycle\s*:=\s*ObservationCycle\s*\)\s*;\s*' +
         'RETURN\s*;\s*end_if\s*;\s*' +
         'if\s+\(AdmissionToken\s*=\s*0\)\s*\|\s*' +
         '\(OwnerGeneration\s*=\s*0\)\s+then')) (
        "$Owner DS402 adapter lacks the exact closed stage87 helper branch.")
    $stage87Body = $stage87HelperBlock
    Assert-Match $stage87Body (
        ('(?is)if\s+\(ReportKind\s*<>\s*' +
         'LMC_DS402_OWNER_RECEIPT_ROLLBACK\)\s*\|\s*' +
         '\(ReportValue0\s*<>\s*0\)\s*\|\s*' +
         '\(ReportValue1\s*<>\s*0\).*?' +
         'LMC_DS402_OWNER_STAGE_RESERVE_INTENT.*?' +
         'Result\s*:=\s*-2\s*;\s*RETURN\s*;')) (
        "$Owner stage87 tokenless mode is broader than exact rollback intent.")
    Assert-Match $stage87Body (
        ('(?is)if\s+\(intentRecordState\s*=\s*0\)\s*\|\s*' +
         '\(intentRecordState\s*=\s*0x00008002\)\s*\|\s*' +
         '\(intentRecordState\s*=\s*0x00008003\)\s*\|\s*' +
         '\(intentRecordState\s*=\s*0x00008004\).*?' +
         '\(adoptionPrepared\s*=\s*FALSE\)\s*&\s*' +
         '\(intentRecordState\s*=\s*intentRawState\)\)\s*\|\s*' +
         '\(adoptionPrepared\s*&\s*' +
         '\(\(intentRecordState\s*=\s*intentRawState\)\s*\|\s*' +
         '\(intentRecordState\s*=\s*0\)\)\).*?' +
         'LMC_DS402_OWNER_INTENT_MAGIC.*?' +
         'intentGenerationSnapshot\s*=\s*\(pState\s*\+\s*436\).*?' +
         'ObservationCycle\s*=\s*intentObservationCycle')) (
        "$Owner stage87 raw WAL identity/state/generation proof is incomplete.")
    Assert-Match $stage87Body (
        ('(?is)candidateSessionClosed\s*:=.*?' +
         'LMC_OWNER_STATE_QUARANTINED.*?' +
         'LMC_OWNER_REPORT_QUARANTINE.*?' +
         'recordBase\s*\+\s*33\]\s*=\s*-20.*?' +
         'recordBase\s*\+\s*34\]\s*=\s*0.*?' +
         'candidateActive\s*:=.*?' +
         'LMC_OWNER_STATE_DS402_HOME_ACTIVE.*?' +
         'if\s+candidateActive\s*\|.*?Result\s*:=\s*-3\s*;')) (
        "$Owner stage87 recovery can adopt ACTIVE or a broadened quarantine.")
    Assert-Match $stage87Body (
        ('(?is)ownerResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
         'CommandId:=0x7D15.*?' +
         'CallerSessionEpoch:=callerSessionEpoch.*?' +
         'RequestSequence:=requestSequence.*?' +
         'AdmissionToken:=candidateAdmissionToken.*?' +
         'OwnerGeneration:=candidateOwnerGeneration.*?' +
         'RequiredPhase:=requiredPhase.*?' +
         'pIdentity:=#identity\[0\]\s*,\s*' +
         'IdentitySize:=sizeof\(identity\)\s*\)\s*;\s*' +
         'if\s+ownerResult\s*<>\s*0\s+then\s*' +
         'Result\s*:=\s*-3\s*;\s*RETURN\s*;')) (
        "$Owner stage87 adoption lacks exact common identity validation.")
    $stage87TargetMetadata = [regex]::Match(
        $stage87Body,
        ('(?is)\(pState\s*\+\s*480\)\^\$UDINT\s*:=\s*' +
         'callerSessionEpoch.*?' +
         '\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
         'LMC_DS402_OWNER_RECEIPT_PREPARED\s*;'))
    $stage87Adopt = [regex]::Match(
        $stage87Body,
        ('\(pState\s*\+\s*476\)\^\$UDINT\s*:=\s*' +
         'LMC_DS402_OWNER_ADOPT_MAGIC\s*;'))
    $stage87RecordStateZero = [regex]::Match(
        $stage87Body,
        '\(pState\s*\+\s*recordByteBase\)\^\$DINT\s*:=\s*0\s*;')
    $stage87RecordBodyClear = [regex]::Match(
        $stage87Body,
        ('(?is)_memset\(dest:=pState\s*\+\s*recordByteBase\s*\+\s*4\s*,\s*' +
         'usByte:=0\s*,\s*cntr:=88\s*\)'))
    $stage87Bridge = [regex]::Match(
        $stage87Body,
        '\(pState\s*\+\s*recordByteBase\)\^\$DINT\s*:=\s*1\s*;')
    $stage87WalReuse = [regex]::Match(
        $stage87Body,
        '_memset\(dest:=pState\s*\+\s*376.*?cntr:=60\s*\)')
    $stage87Publish = [regex]::Match(
        $stage87Body,
        ('\(pState\s*\+\s*368\)\^\$DINT\s*:=\s*' +
         'LMC_DS402_OWNER_STAGE_ROLLBACK_PREPARED\s*;'))
    if (-not $stage87TargetMetadata.Success -or -not $stage87Adopt.Success -or
        -not $stage87RecordStateZero.Success -or
        -not $stage87RecordBodyClear.Success -or -not $stage87Bridge.Success -or
        -not $stage87WalReuse.Success -or
        -not $stage87Publish.Success -or
        $stage87TargetMetadata.Index -ge $stage87Adopt.Index -or
        $stage87Adopt.Index -ge $stage87RecordStateZero.Index -or
        $stage87RecordStateZero.Index -ge $stage87RecordBodyClear.Index -or
        $stage87RecordBodyClear.Index -ge $stage87Bridge.Index -or
        $stage87Bridge.Index -ge $stage87WalReuse.Index -or
        $stage87WalReuse.Index -ge $stage87Publish.Index) {
        throw (
            "$Owner stage87 adoption must commit target metadata/marker/state0, " +
            'clear and bridge the body, then reuse WAL and publish stage88 last.')
    }
    if ($stage87Body -match
        ('(?is)(OwnershipState|OwnershipObserverState|' +
         'OwnershipIdentityState)\s*\[[^\]]+\](?:\^?\$[A-Z]+)?\s*:=')) {
        throw "$Owner stage87 proof branch mutates common ownership directly."
    }
    Assert-Match $stage87Body (
        ('(?is)if\s+idleSurfaceValid\s*&\s*' +
         '\(OwnershipState\[10\]\s*=\s*0\)\s*&\s*' +
         '\(OwnershipState\[11\]\s*=\s*0\)\s*&\s*' +
         '\(OwnershipState\[12\]\s*=\s*0\)\s*&\s*' +
         '\(intentTupleElsewhere\s*=\s*FALSE\)\s+then\s*' +
         'Result\s*:=\s*2\s*;')) (
        "$Owner stage87 absence result is not confined to canonical idle.")
    Assert-Match $stage87Body (
        ('(?is)differentOwnerValid\s*:=\s*ownerResult\s*=\s*0\s*;.*?' +
         'if\s+differentOwnerValid\s*&\s*' +
         '\(intentTupleElsewhere\s*=\s*FALSE\)\s+then\s*' +
         'Result\s*:=\s*2\s*;')) (
        "$Owner stage87 later-owner abandonment lacks full validator proof.")

    Assert-Match $providerBlock (
        ('(?is)sessionClosedRollback\s*:=\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*1\]\s*=\s*' +
         'LMC_OWNER_STATE_QUARANTINED\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*32\]\s*=\s*' +
         'LMC_OWNER_REPORT_QUARANTINE\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*33\]\s*=\s*-20\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*34\]\s*=\s*0\)\s*;.*?' +
         'if\s+sessionClosedRollback\s+then\s*' +
         'expectedOwnerState\s*:=\s*LMC_OWNER_STATE_QUARANTINED\s*;\s*' +
         'requiredPhase\s*:=\s*' +
         'LMC_OWNER_PHASE_SESSION_CLOSED_ROLLBACK\s*;.*?' +
         'elsif\s+OwnershipState\[recordBase\s*\+\s*1\]\s*=\s*' +
         'LMC_OWNER_STATE_DS402_HOME_ACTIVE\s+then.*?' +
         'requiredPhase\s*:=\s*LMC_OWNER_PHASE_ACTIVE\s*;.*?' +
         'else\s+expectedOwnerState\s*:=\s*LMC_OWNER_STATE_RESERVED\s*;\s*' +
         'requiredPhase\s*:=\s*LMC_OWNER_PHASE_RESERVED\s*;')) (
        "$Owner rollback state selection is not exact RESERVED/ACTIVE or " +
        'session-close QUARANTINED provenance.')
    Assert-Match $providerBlock (
        ('(?is)ownerResult\s*:=\s*ValidateAxisOwnershipIdentity\(\s*' +
         'CommandId:=0x7D15.*?RequiredPhase:=requiredPhase\s*,\s*' +
         'pIdentity:=#identity\[0\]\s*,\s*' +
         'IdentitySize:=sizeof\(identity\)\s*\)\s*;\s*' +
         'if\s+ownerResult\s*<>\s*0\s+then\s*' +
         'Result\s*:=\s*ownerResult\s*;\s*RETURN\s*;')) (
        "$Owner first receipt does not validate its reconstructed identity.")
    Assert-Match $providerBlock (
        ('(?is)if\s+\(expectedOwnerState\s*=\s*' +
         'LMC_OWNER_STATE_RESERVED\)\s*\|\s*' +
         'sessionClosedRollback\s+then\s*' +
         'observerPre\s*:=\s*observerPre\s*&.*?' +
         'OwnershipObserverState\[observerBase\s*\+\s*1\]\s*=\s*0.*?' +
         'OwnershipObserverState\[observerBase\s*\+\s*8\]\s*=\s*0')) (
        "$Owner session-close rollback lacks the original RESERVED observer shape.")
    Assert-Match $providerBlock (
        ('(?is)receiptKind\s*=\s*LMC_DS402_OWNER_RECEIPT_ROLLBACK\)\s*&\s*' +
         '\(\(\(sessionClosedRollback\s*=\s*FALSE\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*32\]\s*=\s*0\).*?' +
         '\(OwnershipState\[recordBase\s*\+\s*34\]\s*=\s*0\)\)\s*\|\s*' +
         '\(sessionClosedRollback\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*32\]\s*=\s*' +
         'LMC_OWNER_REPORT_QUARANTINE\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*33\]\s*=\s*-20\)\s*&\s*' +
         '\(OwnershipState\[recordBase\s*\+\s*34\]\s*=\s*0\)')) (
        "$Owner record cleanup does not separate zero report from 4/-20/0.")

    Assert-Match $providerBlock (
        ('(?is)if\s+receiptPhase\s*=\s*' +
         'LMC_DS402_OWNER_RECEIPT_COMPLETE\s+then\s*' +
         'Result\s*:=\s*1\s*;\s*RETURN\s*;\s*end_if\s*;')) (
        "$Owner COMPLETE replay must return without inspecting later owners.")
    Assert-Match $providerBlock (
        ('(?is)LMC_DS402_OWNER_RECEIPT_CLEAR_RECORD\s*:\s*' +
         'surfaceValid\s*:=.*?recordPre.*?' +
         'OwnershipState\[recordBase\s*\+\s*35\]\s*=\s*0.*?' +
         'recordPost.*?if\s+surfaceValid\s*=\s*FALSE\s+then\s*' +
         'if\s+receiptPhase\s*=\s*' +
         'LMC_DS402_OWNER_RECEIPT_CLEAR_RECORD\s+then\s*' +
         'Result\s*:=\s*-1\s*;\s*RETURN\s*;')) (
        "$Owner phase-5 replay can poison a later owner instead of waiting.")
    $recordMagicWrite = [regex]::Match(
        $providerBlock,
        ('(?is)OwnershipState\[recordBase\s*\+\s*35\]\$UDINT\s*:=\s*' +
         'LMC_OWNER_AXIS_RECORD_MAGIC\s*\+\s*TO_UDINT\(axisIndex\)\s*;'))
    $completeWrite = [regex]::Match(
        $providerBlock,
        ('(?is)\(pState\s*\+\s*500\)\^\$DINT\s*:=\s*' +
         'LMC_DS402_OWNER_RECEIPT_COMPLETE\s*;'))
    if (-not $recordMagicWrite.Success -or -not $completeWrite.Success -or
        $recordMagicWrite.Index -ge $completeWrite.Index) {
        throw (
            "$Owner COMPLETE must be the final commit after idle record magic.")
    }
    $afterCompleteWrite = $providerBlock.Substring(
        $completeWrite.Index + $completeWrite.Length)
    if ($afterCompleteWrite -match
        '(?i)Ownership(?:State|ObserverState|IdentityState)\s*\[') {
        throw "$Owner common ownership surfaces are mutated after COMPLETE."
    }
}

