                '${1}GLOBAL ' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery${2}')
        },
        @{
            Name = 'Stage87ImplementationPromotedGlobal'
            Pattern = (
                '(?im)^(\s*FUNCTION\s+)' +
                '(LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*)$')
            Replacement = '${1}GLOBAL ${2}'
        },
        @{
            Name = 'Stage87ClassAbiTrailingInputAdded'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*' +
                'VAR_INPUT.*?VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*' +
                'END_VAR\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tVAR_INPUT" + [Environment]::NewLine +
                "`t`tUnexpectedInput : UDINT;" + [Environment]::NewLine +
                "`tEND_VAR;")
        },
        @{
            Name = 'Stage87ImplementationAbiTrailingInputAdded'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\s*' +
                'VAR_INPUT.*?VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*' +
                'END_VAR)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`tVAR_INPUT" + [Environment]::NewLine +
                "`t`tUnexpectedInput : UDINT;" + [Environment]::NewLine +
                "`tEND_VAR")
        },
        @{
            Name = 'Stage87AdapterCallAxisMaskDrift'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::' +
                'PublishAxisOwnershipDs402Receipt\b.*?' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\(.*?' +
                'AxisMask\s*:=\s*)AxisMask')
            Replacement = '${1}ReportValue0'
        },
        @{
            Name = 'Stage87AdapterCallReturnRemoved'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::' +
                'PublishAxisOwnershipDs402Receipt\b.*?' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\(.*?' +
                'ObservationCycle\s*:=\s*ObservationCycle\s*\)\s*;)' +
                '\s*RETURN\s*;')
            Replacement = '${1}'
        },
        @{
            Name = 'Stage87AdapterCallDuplicated'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::' +
                'PublishAxisOwnershipDs402Receipt\b.*?)' +
                '(Result\s*:=\s*' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\(.*?' +
                'ObservationCycle\s*:=\s*ObservationCycle\s*\)\s*;)')
            Replacement = (
                '${1}${2}' + [Environment]::NewLine + '${2}')
        },
        @{
            Name = 'Stage87LegacyLocalRetainedInAdapter'
            Pattern = (
                '(?is)(FUNCTION\s+GLOBAL\s+' +
                'LMCControlCommandService::' +
                'PublishAxisOwnershipDs402Receipt\b.*?' +
                'VAR_OUTPUT\s*Result\s*:\s*DINT\s*;\s*END_VAR\s*' +
                'VAR\s*pState\s*:\s*\^USINT\s*;)')
            Replacement = (
                '${1}' + [Environment]::NewLine +
                "`t`tstage87Recovery : BOOL;")
        },
        @{
            Name = 'Stage87HelperLocalTypeDrift'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\b.*?' +
                'candidateOwnerKind\s*:\s*)UINT')
            Replacement = '${1}UDINT'
        },
        @{
            Name = 'Stage87HelperUnexpectedCall'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\b.*?' +
                'END_VAR\s*)(axisIndex\s*:=\s*activeIndex\s*\+\s*1\s*;)')
            Replacement = (
                '${1}ownerResult := RollbackAxisOwnership();' +
                [Environment]::NewLine + '${2}')
        },
        @{
            Name = 'Stage87HelperEarlyReturn'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\b.*?' +
                'END_VAR\s*)(axisIndex\s*:=\s*activeIndex\s*\+\s*1\s*;)')
            Replacement = (
                '${1}RETURN;' + [Environment]::NewLine + '${2}')
        },
        @{
            Name = 'Stage87HelperEarlyPStateWrite'
            Pattern = (
                '(?is)(FUNCTION\s+' +
                'LMCControlCommandService::' +
                'HandleAxisOwnershipDs402ReceiptStage87Recovery\b.*?' +
                'END_VAR\s*)(axisIndex\s*:=\s*activeIndex\s*\+\s*1\s*;)')
            Replacement = (
                '${1}(pState + 500)^$DINT := 99;' +
                [Environment]::NewLine + '${2}')
        }
    )
    foreach ($fixture in $mutationFenceFixtures) {
        $fixtureRegex = [regex]::new(
            $fixture.Pattern,
            [Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
            [Text.RegularExpressions.RegexOptions]::Singleline -bor
            [Text.RegularExpressions.RegexOptions]::Multiline)
        $fixtureMatches = $fixtureRegex.Matches($ControlServiceText)
        if ($fixtureMatches.Count -ne 1) {
            throw (
                "$Owner provider negative fixture '$($fixture.Name)' " +
                "found $($fixtureMatches.Count) targets, expected one.")
        }
        $negativeFixtures[$fixture.Name] = $fixtureRegex.Replace(
            $ControlServiceText,
            $fixture.Replacement,
            1)
    }

    $negativeCount = 0
    foreach ($negativeFixture in $negativeFixtures.GetEnumerator()) {
        if ($negativeFixture.Value -ceq $ControlServiceText) {
            throw (
                "$Owner provider negative fixture did not mutate " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeRejected = $false
        $negativeOwner = $Owner + ' negative ' + $negativeFixture.Key
        try {
            Assert-LasalDs402OwnerReceiptProviderContract `
                -ControlServiceText $negativeFixture.Value `
                -Owner $negativeOwner
        }
        catch {
            if (-not $_.Exception.Message.StartsWith(
                    $negativeOwner,
                    [StringComparison]::Ordinal)) {
                throw (
                    "$Owner provider negative fixture " +
                    "'$($negativeFixture.Key)' failed outside its " +
                    "contract assertion: $($_.Exception.Message)")
            }
            $negativeRejected = $true
        }
        if (-not $negativeRejected) {
            throw (
                "$Owner provider verifier accepted negative fixture " +
                "'$($negativeFixture.Key)'.")
        }
        $negativeCount += 1
    }
    if ($negativeCount -ne 67) {
        throw "$Owner provider negative count is $negativeCount, expected 67."
    }
    return $negativeCount
}

function Assert-LasalEncoderMaintenanceContract {
    param(
        [string]$DiagnosticsText,
        [string]$TcpText,
        [string]$Owner
    )

    $scan = Get-LasalScanText $DiagnosticsText
    $tcpScan = Get-LasalScanText $TcpText
    $startBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenanceStart.*?END_FUNCTION').Value
    $outcomeBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenanceOutcome.*?END_FUNCTION').Value
    $retireBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleEncoderMaintenanceRetire.*?END_FUNCTION').Value
    $processBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::ProcessEncoderMaintenance.*?END_FUNCTION').Value
    $preemptionBlock = [regex]::Match(
        $scan,
        ('(?is)FUNCTION\s+LMCDiagnosticsService::' +
         'HandleEncoderMaintenancePreemption.*?END_FUNCTION')).Value
    foreach ($block in @($startBlock, $outcomeBlock, $retireBlock, $processBlock)) {
        if ([string]::IsNullOrWhiteSpace($block)) {
            throw "$Owner dedicated encoder-maintenance handler set is incomplete."
        }
    }
    $processLogicalBlock = $processBlock
    if (-not [string]::IsNullOrWhiteSpace($preemptionBlock)) {
        $processLogicalBlock = $processBlock + "`n" + $preemptionBlock
    }

    Assert-Match $scan (
        '(?s)if\s+CommandId\s*=\s*0x7E53\s+then.*?' +
        'HandleEncoderMaintenanceStart\(.*?' +
        'elsif\s+CommandId\s*=\s*0x7E54\s+then.*?' +
        'HandleEncoderMaintenanceOutcome\(.*?' +
        'elsif\s+CommandId\s*=\s*0x7E55\s+then.*?' +
        'HandleEncoderMaintenanceRetire\(') (
        "$Owner does not route the complete 0x7E53/54/55 triad.")
    Assert-Match $tcpScan (
        '(?s)0x7E53,\s*0x7E54,\s*0x7E55:.*?' +
        'Diagnostics\.HandleRequest\(') (
        "$Owner TCP transport does not delegate the dedicated triad.")
    Assert-Match $scan (
        '(?s)FUNCTION\s+GLOBAL\s+LMCDiagnosticsService::ProcessOperations.*?' +
        'ProcessEncoderMaintenance\(\).*?END_FUNCTION') (
        "$Owner cyclic processor does not invoke encoder maintenance.")

    Assert-Match $scan '#define\s+LMC_DIAG_ENCODER_TW20_ENABLED\s+TRUE' (
        "$Owner TW20 exact fixed-value contract is not enabled.")
    Assert-Match $scan '#define\s+LMC_DIAG_ENCODER_TW19_ENABLED\s+TRUE' (
        "$Owner TW19 exact fixed-value contract is not enabled.")
    Assert-Match $scan '#define\s+LMC_DIAG_ENCODER_RESET_VALUE\s+1' (
        "$Owner TW19/TW20 fixed UInt16 reset value is not one.")
    Assert-Match $scan (
        '(?s)LMC_DIAG_ENCODER_TW20_ENABLED\s*=\s*TRUE.*?0x00040000.*?' +
        'LMC_DIAG_ENCODER_TW19_ENABLED\s*=\s*TRUE.*?0x00080000') (
        "$Owner capability bits 18/19 are not independently gated.")
    Assert-Match $scan (
        'EncoderMaintenanceState\s*:\s*ARRAY\s*\[\s*0\.\.191\s*\]\s*OF\s*DINT') (
        "$Owner exact encoder-maintenance retained storage is missing.")
    Assert-Match $scan (
        'EncoderMaintenanceServiceMilliseconds\s*:\s*UDINT') (
        "$Owner service-clock millisecond storage is missing.")
    Assert-Match $scan (
        'EncoderMaintenanceObservedLatchCycle\s*:\s*UDINT') (
        "$Owner RT latch-cycle evidence storage is missing.")
    Assert-Match $scan (
        'EncoderMaintenanceLatchAdvanceServiceMilliseconds\s*:\s*UDINT') (
        "$Owner latch-advance service-time evidence storage is missing.")
    Assert-Match $scan (
        'EncoderMaintenanceLatchFreshSampleCount\s*:\s*UINT') (
        "$Owner fresh-latch evidence counter is missing.")

    if ($scan -match '(?i)LMC_DIAG_ENCODER_TW(?:19|20)_AXIS[1-4]_') {
        throw (
            "$Owner still contains an obsolete per-axis profile/socket/evidence " +
            'manifest that can block the fixed drive-axis command.')
    }
    if ($startBlock -match '(?i)manifestMatched|expectedProfile|expectedSocket') {
        throw (
            "$Owner start parser still uses the obsolete compatibility manifest.")
    }

    Assert-Match $startBlock (
        '(?s)RequestSize\s*<>\s*72.*?' +
        '\(pRequest\s*\+\s*8\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*12\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*16\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*20\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*32\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*36\)\^\$UINT.*?' +
        '\(pRequest\s*\+\s*38\)\^\$UINT.*?' +
        '\(pRequest\s*\+\s*40\)\^\$UINT.*?' +
        '\(pRequest\s*\+\s*42\)\^\$UINT.*?' +
        '\(pRequest\s*\+\s*44\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*48\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*52\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*64\)\^\$UDINT.*?' +
        '\(pRequest\s*\+\s*68\)\^\$UDINT') (
        "$Owner 0x7E53 exact 72-byte identity/evidence schema is incomplete.")
    Assert-Match $startBlock (
        '(?s)(?=.*?timeoutMilliseconds\s*:=\s*' +
        '\(pRequest\s*\+\s*48\)\^\$UDINT)' +
        '(?=.*?timeoutMilliseconds\s*<\s*1)' +
        '(?=.*?timeoutMilliseconds\s*>\s*60000)' +
        '(?=.*?EncoderMaintenanceState\[[^\]]+\]\^?\$UDINT\s*:=\s*' +
        'timeoutMilliseconds)' +
        '(?=.*?(?:' +
        'EncoderMaintenanceState\[[^\]]+\]\^?\$UDINT\s*:=\s*ops\.tAbsolute|' +
        'serviceStartMs\s*:=\s*ops\.tAbsolute.*?' +
        'EncoderMaintenanceState\[[^\]]+\](?:\^?\$UDINT)?\s*:=\s*' +
        'serviceStartMs(?:\s*\$DINT)?' +
        '))') (
        "$Owner P48 is not retained as the 1..60000 ms overall service-clock budget.")
    Assert-Match $startBlock (
        '(?s)maintenanceKind\s*=\s*1.*?' +
        'maintenanceObjectIndex\s*:=\s*0x20FC.*?' +
        'maintenanceSubIndex\s*:=\s*0x02.*?' +
        'maintenanceKind\s*=\s*2.*?' +
        'maintenanceObjectIndex\s*:=\s*0x20FC.*?' +
        'maintenanceSubIndex\s*:=\s*0x01') (
        "$Owner TW20/TW19 exact 0x20FC:02/01 mapping is missing.")
    Assert-Match $startBlock (
        '(?s)(?=.*?maintenanceCommandValue\s*<>\s*' +
        'LMC_DIAG_ENCODER_RESET_VALUE)' +
        '(?=.*?maintenanceFeedbackSocket\s*<\s*1)' +
        '(?=.*?maintenanceFeedbackSocket\s*>\s*4)' +
        '(?=.*?maintenanceDataLength\s*:=\s*2)') (
        "$Owner maintenance value is not the exact fixed UInt16 value one.")
    Assert-Match $outcomeBlock (
        'maintenanceCommandValue\s*<>\s*LMC_DIAG_ENCODER_RESET_VALUE') (
        "$Owner outcome key does not preserve the exact fixed command value.")
    Assert-Match $processBlock (
        '(?s)maintenanceWriteValue\s*:=\s*LMC_DIAG_ENCODER_RESET_VALUE.*?' +
        'maintenanceCommandValue\s*<>\s*LMC_DIAG_ENCODER_RESET_VALUE.*?' +
        'TryStartWrite\(.*?WriteLength:=2') (
        "$Owner executor path does not pin the one-shot UInt16 value one.")
    Assert-Match $startBlock (
        '(?s)(?=.*?controlWord\s+and\s+0x00000008)' +
        '(?=.*?statusWord\s+and\s+0x00000004)') (
        "$Owner final motor-off admission is missing.")
    $encoderValidateCallPattern = (
        'ownerResult\s*:=\s*AxisOwnership\.ValidateAxisOwnershipIdentity\(\s*' +
        'CommandId\s*:=\s*0x7E53\s*,\s*' +
        'Reference\s*:=\s*driveReference\s*,\s*' +
        'ExpectedAxisMask\s*:=\s*axisMask\s*,\s*' +
        'OwnerKind\s*:=\s*LMC_DIAG_OWNER_KIND_ENCODER\s*,\s*' +
        'ResourceKind\s*:=\s*LMC_DIAG_RESOURCE_DIAGNOSTICS_SDO\s*,\s*' +
        'AdmissionMode\s*:=\s*LMC_DIAG_ADMISSION_LIFECYCLE\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
        'RequestSequence\s*:=\s*RequestSequence\s*,\s*' +
        'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'RequiredPhase\s*:=\s*LMC_DIAG_OWNER_PHASE_RESERVED\s*,\s*' +
        'pIdentity\s*:=\s*pRequest\$\^void\s*,\s*' +
        'IdentitySize\s*:=\s*RequestSize\s*\)\s*;')
    $encoderCommitCallPattern = (
        'ownerResult\s*:=\s*AxisOwnership\.CommitAxisOwnership\(\s*' +
        'CommandId\s*:=\s*0x7E53\s*,\s*' +
        'Reference\s*:=\s*driveReference\s*,\s*' +
        'ExpectedAxisMask\s*:=\s*axisMask\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
        'RequestSequence\s*:=\s*RequestSequence\s*,\s*' +
        'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*\)\s*;')
    $encoderValidateCalls = [regex]::Matches(
        $startBlock,
        '(?is)' + $encoderValidateCallPattern)
    $encoderCommitCalls = [regex]::Matches(
        $startBlock,
        '(?is)' + $encoderCommitCallPattern)
    $encoderBroadValidateCalls = [regex]::Matches(
        $startBlock,
        ('(?i)(?:AxisOwnership\s*\.\s*)?' +
         'ValidateAxisOwnership(?:Identity)?\s*\('))
    $encoderBroadCommitCalls = [regex]::Matches(
        $startBlock,
        '(?i)(?:AxisOwnership\s*\.\s*)?CommitAxisOwnership\s*\(')
    if ($encoderValidateCalls.Count -ne 1 -or
        $encoderCommitCalls.Count -ne 1 -or
        $encoderBroadValidateCalls.Count -ne 1 -or
        $encoderBroadCommitCalls.Count -ne 1) {
        throw (
            "$Owner Start must call ValidateAxisOwnershipIdentity and " +
            'CommitAxisOwnership exactly once each, regardless of call syntax.')
    }
    $encoderValidateContract = [regex]::Match(
        $startBlock,
        ('(?is)' + $encoderValidateCallPattern + '\s*' +
        'if\s+ownerResult\s*<>\s*0\s+then\s*' +
        'detailCode\s*:=\s*9\s*;\s*end_if\s*;'))
    if (-not $encoderValidateContract.Success) {
        throw (
            "$Owner Start validation does not bind the exact owner tuple or " +
            'consume its result immediately.')
    }
    $encoderCommitContract = [regex]::Match(
        $startBlock,
        ('(?is)if\s+detailCode\s*=\s*0\s+then\s*' +
        $encoderCommitCallPattern + '\s*' +
        'if\s+ownerResult\s*<>\s*0\s+then\s*' +
        'detailCode\s*:=\s*9\s*;\s*end_if\s*;\s*end_if\s*;'))
    if (-not $encoderCommitContract.Success) {
        throw (
            "$Owner Start commit must be detailCode-zero dominated, bind the " +
            'exact owner tuple, and consume its result immediately.')
    }
    if ($encoderValidateCalls[0].Index -ge $encoderCommitCalls[0].Index -or
        $encoderValidateContract.Index -ge $encoderCommitContract.Index) {
        throw "$Owner Start commit must occur after successful validation."
    }
    Assert-Match $startBlock (
        '(?s)if\s+detailCode\s*<>\s*0\s+then.*?' +
        'rollbackResult\s*:=\s*AxisOwnership\.RollbackAxisOwnership\(\s*' +
        'AdmissionToken\s*:=\s*AdmissionToken\s*,\s*' +
        'OwnerGeneration\s*:=\s*OwnerGeneration\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
        'RequestSequence\s*:=\s*RequestSequence\s*,\s*' +
        'Reason\s*:=\s*0\s*\)\s*;.*?' +
        '\(pResponse\s*\+\s*12\)\^\$UDINT\s*:=\s*detailCode\s*;\s*' +
        'RETURN\s*;\s*end_if\s*;.*?' +
        '_memset\(dest\s*:=\s*#EncoderMaintenanceState\[recordBase\]') (
        "$Owner Start rollback does not bind the exact tuple before failure return.")
    Assert-Match $startBlock (
        '(?s)ResponseCapacity\s*<\s*40.*?' +
        '\(pResponse\s*\+\s*36\)\^\$UDINT.*?' +
        'ResponseSize\s*:=\s*40') (
        "$Owner 0x7E53 ACK is not exactly 40 bytes.")

    Assert-Match $outcomeBlock (
        '(?s)RequestSize\s*<>\s*72.*?' +
        'timeoutMilliseconds\s*:=\s*\(pRequest\s*\+\s*52\)\^\$UDINT.*?' +
        'ResponseCapacity\s*<\s*156.*?' +
        '\(pResponse\s*\+\s*152\)\^\$UDINT.*?' +
        'ResponseSize\s*:=\s*156') (
        "$Owner 0x7E54 exact key or 156-byte retained outcome is incomplete.")
    Assert-Match $retireBlock (
        '(?s)(?=.*?RequestSize\s*<>\s*76)' +
        '(?=.*?recordGeneration\s*:=\s*' +
        '\(pRequest\s*\+\s*72\)\^\$UDINT)') (
        "$Owner 0x7E55 exact retirement request framing is incomplete.")
    $storedGenerationComparisons = [regex]::Matches(
        $retireBlock,
        ('(?is)EncoderMaintenanceState\[recordBase\s*\+\s*36\]\$UDINT' +
         '\s*<>\s*recordGeneration'))
    $retireMarkerWrites = [regex]::Matches(
        $retireBlock,
        ('(?is)EncoderMaintenanceState\[recordBase\]\s*:=\s*' +
         'TO_DINT\(baseState\s+OR\s+LMC_DIAG_ENCODER_RECORD_RETIRED\)'))
    $retirementDominancePattern = (
        '(?is)elsif\s+EncoderMaintenanceState' +
        '\[recordBase\s*\+\s*36\]\$UDINT\s*<>\s*' +
        'recordGeneration\s+then\s*' +
        'detailCode\s*:=\s*LMC_DIAG_ENCODER_DETAIL_KEY_MISMATCH\s*;\s*' +
        'else\s*ResponseSize\s*:=\s*HandleEncoderMaintenanceOutcome\(\s*' +
        'Reference\s*:=\s*Reference\s*,\s*' +
        'pRequest\s*:=\s*pRequest\s*,\s*' +
        'pResponse\s*:=\s*pResponse\s*,\s*' +
        'ResponseCapacity\s*:=\s*ResponseCapacity\s*,\s*' +
        'CallerSessionEpoch\s*:=\s*CallerSessionEpoch\s*,\s*' +
        'RequestSize\s*:=\s*72\s*\)\s*;\s*' +
        'if\s*\(\s*ResponseSize\s*=\s*156\s*\)\s*&\s*' +
        '\(\s*\(pResponse\s*\+\s*148\)\^\$UDINT\s*=\s*' +
        'recordGeneration\s*\)\s+then\s*' +
        'if\s+rawState\s*=\s*baseState\s+then\s*' +
        '(?:(?://[^\r\n]*(?:\r?\n|\z))\s*)*' +
        'EncoderMaintenanceState\[recordBase\]\s*:=\s*' +
        'TO_DINT\(baseState\s+OR\s+' +
        'LMC_DIAG_ENCODER_RECORD_RETIRED\)\s*;')
    $retirementDominanceMatches = [regex]::Matches(
        $retireBlock,
        $retirementDominancePattern)
    if ($storedGenerationComparisons.Count -ne 1 -or
        $retireMarkerWrites.Count -ne 1 -or
        $retirementDominanceMatches.Count -ne 1) {
        throw (
            "$Owner retirement must actively compare stored generation +36 " +
            'once, obtain a matching retained outcome, and only then publish ' +
            'the tombstone marker.')
    }
    $verificationMaskWrites = [regex]::Matches(
        $startBlock + "`n" + $processLogicalBlock,
        ('(?is)EncoderMaintenanceState\[recordBase\s*\+\s*27\]' +
         '\^?\$UDINT\s*:=\s*(?<Expression>[^;]+);'))
    if ($verificationMaskWrites.Count -lt 1) {
        throw "$Owner encoder verification-mask publication is missing."
    }
    foreach ($verificationMaskWrite in $verificationMaskWrites) {
        $verificationMaskExpression =
            $verificationMaskWrite.Groups['Expression'].Value
        $normalizedVerificationMaskExpression =
            ([regex]::Replace($verificationMaskExpression, '\s+', ' ')).Trim()
        if ($verificationMaskExpression -match '\|' -or
            ($verificationMaskExpression -notmatch '(?i)\bOR\b' -and
             $normalizedVerificationMaskExpression -cne
                'LMC_DIAG_ENCODER_VERIFY_ALL')) {
            throw (
                "$Owner encoder verification-mask accumulation must use " +
                'integer OR; LASAL logical pipe collapses nonzero integer ' +
                'masks to BOOL 1.')
        }
    }
    Assert-Match $processBlock (
        '(?s)TryStartWrite\(.*?' +
        'encoderProcessOperationToken.*?maintenanceObjectIndex.*?' +
        'maintenanceSubIndex.*?maintenanceWriteValue.*?' +
        'PublishAxisOwnership\(.*?' +
        'ReportValue0:=TO_UDINT\(maintenanceObjectIndex\).*?' +
        'ReportValue1:=encoderProcessOperationToken') (
        "$Owner encoder processor does not retain the exact SDO target and token through owner publication.")
    Assert-Match $processBlock (
        '(?s)maintenanceWriteValue\s*:\s*UINT.*?' +
        'maintenanceWriteValue\s*:=\s*LMC_DIAG_ENCODER_RESET_VALUE') (
        "$Owner does not stage the fixed UNSIGNED16 value one in a UINT.")

    $encoderWriteDispatchMatches = [regex]::Matches(
        $processBlock,
        ('(?is)EncoderMaintenanceState\[189\]\^?\$UDINT\s*:=\s*' +
         'encoderProcessOperationToken\s*;\s*' +
         'startResult\s*:=\s*ERROR\s*;\s*' +
         'case\s+axisReference\s+of(?<Body>.*?)end_case\s*;'))
    if ($encoderWriteDispatchMatches.Count -ne 1) {
        throw (
            "$Owner must publish one irreversible claim immediately before " +
            'one axis-bound TryStartWrite dispatch case.')
    }
    $encoderWriteDispatchBody =
        $encoderWriteDispatchMatches[0].Groups['Body'].Value
    $writeCalls = [regex]::Matches(
        $processBlock,
        '(?is)SdoAxis(?<Axis>[1-4])\.TryStartWrite\((?<Args>.*?)\);')
    if ($writeCalls.Count -ne 4) {
        throw "$Owner must contain exactly four axis-specific TryStartWrite calls."
    }
    foreach ($axis in 1..4) {
        $axisCalls = @($writeCalls | Where-Object {
                [int]$_.Groups['Axis'].Value -eq $axis
            })
        if ($axisCalls.Count -ne 1) {
            throw "$Owner SdoAxis$axis must own exactly one dedicated write call."
        }
        $axisDispatchCalls = [regex]::Matches(
            $encoderWriteDispatchBody,
            ('(?ims)^\s*' + $axis + '\s*:\s*startResult\s*:=\s*' +
             'SdoAxis' + $axis + '\.TryStartWrite\(' +
             '(?<Args>.*?)\)\s*;'))
        if ($axisDispatchCalls.Count -ne 1) {
            throw (
                "$Owner axis $axis TryStartWrite dispatch is not bound to " +
                "SdoAxis$axis.")
        }
        $writeArgs = $axisDispatchCalls[0].Groups['Args'].Value
        Assert-Match $writeArgs (
            '(?s)OperationToken\s*:=\s*encoderProcessOperationToken.*?' +
            'ObjectIndex\s*:=\s*maintenanceObjectIndex.*?' +
            'SubIndex\s*:=\s*maintenanceSubIndex.*?' +
            'pWriteData\s*:=\s*\(#maintenanceWriteValue\)\$\^USINT.*?' +
            'WriteLength\s*:=\s*2.*?' +
            'TimeoutMs\s*:=\s*remainingMs') (
            "$Owner SdoAxis$axis write does not preserve the exact UInt16 one-shot contract.")
    }
    $claimAssignments = [regex]::Matches(
        $processBlock,
        'EncoderMaintenanceState\[189\]\^?\$UDINT\s*:=\s*([^;]+);')
    if ($claimAssignments.Count -ne 1 -or
        $claimAssignments[0].Groups[1].Value.Trim() -cne
            'encoderProcessOperationToken') {
        throw ("$Owner one-shot dispatch claim must be assigned " +
            'encoderProcessOperationToken exactly once.')
    }
    Assert-Match $processBlock (
        '(?s)EncoderMaintenanceState\[189\]\^?\$UDINT\s*:=\s*' +
        'encoderProcessOperationToken\s*;\s*startResult\s*:=\s*ERROR\s*;\s*' +
        'case\s+axisReference\s+of') (
        "$Owner one-shot claim is not published before selecting the executor.")
    Assert-Match $processBlock (
        '(?s)serviceNow\s*:=\s*ops\.tAbsolute.*?' +
        'elapsedMs\s*:=\s*serviceNow\s*-\s*serviceStartMs.*?' +
        'if\s+elapsedMs\s*>=\s*timeoutMilliseconds\s+then.*?' +
        'remainingMs\s*:=\s*timeoutMilliseconds\s*-\s*elapsedMs.*?' +
        'remainingMs\s*<\s*1.*?remainingMs\s*:=\s*1.*?' +
        'remainingMs\s*>\s*60000.*?remainingMs\s*:=\s*60000.*?' +
        'TryStartWrite\(.*?TimeoutMs\s*:=\s*remainingMs') (
        "$Owner does not use the remaining unsigned service-clock milliseconds as the one-shot SDO timeout.")
    Assert-Match $processBlock (
        '(?s)if\s+\(orphanResult\s*=\s*0\)\s*\|\s*' +
        '\(orphanResult\s*=\s*-2\)\s*then.*?' +
        'LMC_DIAG_ENCODER_STAGE_DRAIN') (
        "$Owner timeout race does not drain both orphan-accepted and RESULT_READY outcomes.")
    $axisReferenceCaseBlocks = @([regex]::Matches(
            $processLogicalBlock,
            '(?is)case\s+axisReference\s+of(?<Body>.*?)end_case\s*;'))
    $orphanCaseBlocks = @($axisReferenceCaseBlocks | Where-Object {
            $_.Groups['Body'].Value -match '(?i)\.MarkOrphan\s*\('
        })
    $expectedOrphanCaseCount = if ($processLogicalBlock -match
            '(?i)CopyAxisOwnershipPreemption\s*\(') { 2 } else { 1 }
    if ($orphanCaseBlocks.Count -ne $expectedOrphanCaseCount) {
        throw (
            "$Owner must contain $expectedOrphanCaseCount exact axis-bound " +
            'timeout/preemption MarkOrphan case block(s).')
    }
    foreach ($orphanCaseBlock in $orphanCaseBlocks) {
        $orphanCaseBody = $orphanCaseBlock.Groups['Body'].Value
        if ([regex]::Matches(
                $orphanCaseBody,
                '(?i)SdoAxis[1-4]\.MarkOrphan\s*\(').Count -ne 4) {
            throw (
                "$Owner each timeout/preemption MarkOrphan case must contain " +
                'four executor calls.')
        }
        foreach ($axis in 1..4) {
            Assert-Match $orphanCaseBody (
                '(?ims)^\s*' + $axis + '\s*:\s*orphanResult\s*:=\s*' +
                'SdoAxis' + $axis + '\.MarkOrphan\(\s*' +
                'ExpectedToken\s*:=\s*encoderProcessOperationToken\s*\)\s*;') (
                "$Owner timeout/preemption axis $axis is not bound to " +
                "SdoAxis$axis.MarkOrphan.")
        }
    }

    $drainStageMatch = [regex]::Match(
        $processBlock,
        ('(?ims)(?:^\s*LMC_DIAG_ENCODER_STAGE_DRAIN\s*:\s*$|' +
         'if\s+EncoderMaintenanceState\[152\]\s*=\s*' +
         'LMC_DIAG_ENCODER_STAGE_DRAIN\s+then)' +
         '(?<Body>.*?)(?=^\s*if\s+\(copyResult\s*<>\s*0\))'))
    if (-not $drainStageMatch.Success) {
        throw "$Owner cannot isolate the encoder executor drain stage."
    }
    $drainCaseBlocks = @([regex]::Matches(
            $drainStageMatch.Groups['Body'].Value,
            '(?is)case\s+axisReference\s+of(?<Body>.*?)end_case\s*;'))
    if ($drainCaseBlocks.Count -ne 2) {
        throw (
            "$Owner drain stage must contain one CopyCompletion case and " +
            'one IsReusable case.')
    }
    $copyCaseBody = $drainCaseBlocks[0].Groups['Body'].Value
    $reuseCaseBody = $drainCaseBlocks[1].Groups['Body'].Value
    if ([regex]::Matches(
            $copyCaseBody,
            '(?i)SdoAxis[1-4]\.CopyCompletion\s*\(').Count -ne 4 -or
        [regex]::Matches(
            $reuseCaseBody,
            '(?i)SdoAxis[1-4]\.IsReusable\s*\(').Count -ne 4) {
        throw "$Owner drain stage must bind all four executor copy/reuse calls."
    }
    foreach ($axis in 1..4) {
        Assert-Match $copyCaseBody (
            '(?ims)^\s*' + $axis + '\s*:\s*copyResult\s*:=\s*' +
            'SdoAxis' + $axis + '\.CopyCompletion\(\s*' +
            'ExpectedToken\s*:=\s*encoderProcessOperationToken\s*,.*?' +
            'DestSize\s*:=\s*sizeof\(completion\)\s*\)\s*;') (
            "$Owner drain axis $axis is not bound to SdoAxis$axis.CopyCompletion.")
        Assert-Match $reuseCaseBody (
            '(?ims)^\s*' + $axis + '\s*:\s*executorReusable\s*:=\s*' +
            'SdoAxis' + $axis + '\.IsReusable\(\s*\)\s*;') (
            "$Owner drain axis $axis is not bound to SdoAxis$axis.IsReusable.")
    }
    Assert-Match $processBlock (
        '(?s)PublishAxisOwnership\(.*?' +
        'LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
        'if\s+ownerResult\s*=\s*0\s+then.*?' +
        'EncoderMaintenanceState\[recordBase\]\s*:=\s*' +
        'LMC_DIAG_ENCODER_RECORD_SUCCEEDED') (
        "$Owner publishes success before exact owner cleanup succeeds.")

    Assert-Match $startBlock (
        '(?s)Ds402HomeState\[92\]\s*<>\s*0.*?' +
        'OperationState\s*=\s*LMC_DIAG_SDO_STATE_QUEUED.*?' +
        'OperationState\s*=\s*LMC_DIAG_SDO_STATE_RUNNING.*?' +
        'SdoInternalDrainState\s*<>\s*0') (
        "$Owner encoder Start does not exclude DS402 Home and generic SDO activity.")
    $ds402StartBlock = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::HandleAxisDs402HomeStart.*?END_FUNCTION').Value
    Assert-Match $ds402StartBlock 'EncoderMaintenanceState\[[^\]]+\]\s*<>\s*0' (
        "$Owner DS402 Home does not exclude encoder maintenance.")
    $genericSubmitInterlock = [regex]::Match(
        $scan,
        '(?ims)^\s*0x7E50\s*:\s*$.*?(?=^\s*0x7E51\s*:\s*$)').Value
    Assert-Match $genericSubmitInterlock (
        'EncoderMaintenanceState\[[^\]]+\]\s*<>\s*0') (
        "$Owner generic SDO Submit does not exclude encoder maintenance.")

    Assert-Match $tcpScan (
        '(?s)\(CommandID\s*=\s*0x7E53\)\s*&\s*\(Payload\s*=\s*72\).*?' +
        '(?:diagnosticsOwnerReference|ownerAxisReference)\s*:=\s*' +
        'RequestBuf\[48\]\$UINT.*?' +
        '(?:OwnerKind\s*:=\s*5|diagnosticsOwnerKind\s*:=\s*5).*?' +
        '(?:ResourceKind\s*:=\s*4|diagnosticsResourceKind\s*:=\s*4)') (
        "$Owner TCP Start does not derive the exact encoder axis and owner kinds.")
    Assert-Match $tcpScan (
        '(?s)ReserveAxisOwnership\(.*?' +
        'CallerSessionEpoch\s*:=\s*ActiveRequest\.SessionEpoch.*?' +
        'RequestSequence\s*:=\s*ActiveRequest\.Sequence.*?' +
        'pIdentity\s*:=\s*\(#RequestBuf\[8\]\)\$\^void.*?' +
        'IdentitySize\s*:=\s*Payload\$UDINT.*?' +
        'pAdmissionToken\s*:=.*?pOwnerGeneration\s*:=' ) (
        "$Owner TCP Start does not reserve the exact 72-byte payload identity and generation token.")
    Assert-Match $tcpScan (
        '(?s)Diagnostics\.HandleRequest\(.*?' +
        'CallerSessionEpoch\s*:=\s*ActiveRequest\.SessionEpoch.*?' +
        'RequestSequence\s*:=\s*ActiveRequest\.Sequence.*?' +
        'AdmissionToken\s*:=.*?OwnerGeneration\s*:=' ) (
        "$Owner TCP transport does not forward the correlated common-owner tuple.")

    $dedicatedBlocks =
        $startBlock + "`n" + $outcomeBlock + "`n" + $retireBlock +
        "`n" + $processLogicalBlock
    if ($dedicatedBlocks -match '(?i)\bTimeoutCycles\b') {
        throw "$Owner dedicated maintenance path mixes the generic D5 TimeoutCycles unit."
    }
    if ($processLogicalBlock -match
            '(?is)\b(?:elapsedMs|remainingMs)\s*:=\s*[^;]*\b' +
            '(?:EncoderMaintenanceObservedLatchCycle|latchCycle)\b') {
        throw "$Owner incorrectly interprets an RT latch cycle as elapsed milliseconds."
    }
    if ($processLogicalBlock -match
            ('(?is)\bif\s+(?=[^;]{0,240}\b' +
             '(?:newCycle|latchAdvanced|freshLatch)\b)' +
             '(?=[^;]{0,240}\b(?:elapsedMs|serviceNow)\b)' +
             '[^;]{0,240}\bthen')) {
        throw "$Owner incorrectly gates a service-clock timeout behind fresh RT latch evidence."
    }

    $genericPolicy = [regex]::Match(
        $scan,
        '(?is)FUNCTION\s+LMCDiagnosticsService::GetSdoWritePolicyDetail.*?END_FUNCTION').Value
    $genericSubmit = [regex]::Match(
        $scan,
        '(?ims)^\s*0x7E50\s*:\s*$.*?(?=^\s*0x7E51\s*:\s*$)').Value
    if ($genericPolicy -match '(?i)0x3204|0x20FC|TW19|TW20' -or
        $genericSubmit -match '(?i)0x3204|0x20FC|TW19|TW20') {
        throw "$Owner generic 0x7E50 contains a forbidden dedicated-object or TW-array-alias bypass."
    }
    if ($dedicatedBlocks -match '(?i)0x3204') {
        throw "$Owner dedicated maintenance path contains the forbidden TW[] LONG alias."
    }
}

function Assert-CSharpEncoderMaintenanceTimeoutContract {
    param(
        [string]$ProtocolText,
        [string]$ModelsText,
        [string]$Owner
    )

    if (($ProtocolText + "`n" + $ModelsText) -match '(?i)\bTimeoutCycles\b') {
        throw "$Owner dedicated C# contract mixes the generic D5 TimeoutCycles unit."
    }
    Assert-Match $ModelsText (
        'MaximumTimeoutMilliseconds\s*=\s*60000') (
        "$Owner maximum encoder-maintenance timeout is not 60000 ms.")
    Assert-Match $ModelsText (
        '(?s)timeoutMilliseconds\s*==\s*0.*?' +
        'timeoutMilliseconds\s*>\s*MaximumTimeoutMilliseconds') (
        "$Owner does not reject encoder-maintenance timeouts outside 1..60000 ms.")
    Assert-Match $ModelsText (
        '(?s)class\s+LMCEncoderMaintenanceSdoContract.*?' +
        'ObjectIndex\s*=\s*0x20FC.*?' +
        'Tw19MultiturnPositionResetSubIndex\s*=\s*0x01.*?' +
        'Tw20ErrorWarningResetSubIndex\s*=\s*0x02.*?' +
        'WriteLength\s*=\s*2.*?' +
        'ValueType\s*=.*?LMCSignalValueType\.UInt16') (
        "$Owner C# contract is not exact 0x20FC:01/02 UInt16 with a 2-byte write.")
    if ($ModelsText -match '(?i)0x3204') {
        throw "$Owner C# dedicated contract contains the forbidden TW[] LONG alias."
    }
    $timeoutPropertyCount = [regex]::Matches(
        $ModelsText,
        'public\s+uint\s+TimeoutMilliseconds\s*\{').Count
    if ($timeoutPropertyCount -ne 2) {
        throw (
            "$Owner public TimeoutMilliseconds property count is " +
            "$timeoutPropertyCount, expected request plus recovery key.")
    }
    Assert-Match $ProtocolText (
        '(?s)payloadOffset\s*\+\s*48.*?' +
        'recoveryKey\.TimeoutMilliseconds.*?' +
        'payloadOffset\s*\+\s*52.*?' +
        'recoveryKey\.TimeoutMilliseconds') (
        "$Owner start/outcome request keys do not serialize TimeoutMilliseconds at exact offsets.")
    Assert-Match $ProtocolText (
        '(?s)ReadUInt32\(payload,\s*64\).*?' +
        'expected\.TimeoutMilliseconds') (
        "$Owner retained outcome does not echo TimeoutMilliseconds at P64.")
}

function Invoke-LasalEncoderMaintenanceVerifierSelfTest {
    $fixturePath = Join-Path $PSScriptRoot (
        'Verify-LasalEncoderMaintenanceContract.Fixture.ps1')
    if (-not (Test-Path -LiteralPath $fixturePath -PathType Leaf)) {
        throw "Encoder-maintenance verifier fixture is missing: $fixturePath"
    }
    $fixture = & $fixturePath
    if ($null -eq $fixture -or
        [string]::IsNullOrWhiteSpace($fixture.Diagnostics) -or
        [string]::IsNullOrWhiteSpace($fixture.Tcp) -or
        [string]::IsNullOrWhiteSpace($fixture.CSharpProtocol) -or
        [string]::IsNullOrWhiteSpace($fixture.CSharpModels)) {
        throw 'Encoder-maintenance verifier fixture is incomplete.'
    }

    Assert-LasalEncoderMaintenanceContract `
        -DiagnosticsText $fixture.Diagnostics `
        -TcpText $fixture.Tcp `
        -Owner 'encoder-maintenance verifier baseline fixture'
    Assert-CSharpEncoderMaintenanceTimeoutContract `
        -ProtocolText $fixture.CSharpProtocol `
        -ModelsText $fixture.CSharpModels `
        -Owner 'encoder-maintenance C# verifier baseline fixture'

    $negativeFixtures = @($fixture.NegativeFixtures)
    $rejected = 0
    foreach ($negativeFixture in $negativeFixtures) {
        $mutated =
            ($negativeFixture.Diagnostics -cne $fixture.Diagnostics) -or
            ($negativeFixture.Tcp -cne $fixture.Tcp) -or
            ($negativeFixture.CSharpProtocol -cne $fixture.CSharpProtocol) -or
            ($negativeFixture.CSharpModels -cne $fixture.CSharpModels)
        if (-not $mutated) {
            throw (
                'Encoder-maintenance negative fixture did not mutate the ' +
                "baseline for '$($negativeFixture.Name)'.")
        }

        try {
            Assert-LasalEncoderMaintenanceContract `
                -DiagnosticsText $negativeFixture.Diagnostics `
                -TcpText $negativeFixture.Tcp `
                -Owner 'encoder-maintenance LASAL negative fixture'
            Assert-CSharpEncoderMaintenanceTimeoutContract `
                -ProtocolText $negativeFixture.CSharpProtocol `
                -ModelsText $negativeFixture.CSharpModels `
                -Owner 'encoder-maintenance C# negative fixture'
        }
        catch {
            $rejected++
            continue
        }
        throw (
            "Encoder-maintenance verifier accepted negative fixture " +
            "'$($negativeFixture.Name)'.")
    }
    if ($rejected -ne $negativeFixtures.Count) {
        throw (
            "Encoder-maintenance verifier rejected $rejected/" +
            "$($negativeFixtures.Count) negative fixtures.")
    }
    return $rejected
}

function Get-Ds402HomeExactStateSet {
    param(
        [string]$Expression,
        [string]$StateName,
        [uint32[]]$ExpectedValues,
        [string]$Owner
    )

    $valueMatches = [regex]::Matches(
        $Expression,
        ('(?i)(?<![A-Za-z0-9_])' + [regex]::Escape($StateName) +
         '\s*=\s*(?<Value>0x[0-9A-F]+|[0-9]+)'))
    $actualValues = @($valueMatches | ForEach-Object {
            $valueText = $_.Groups['Value'].Value
            if ($valueText.StartsWith('0x', [StringComparison]::OrdinalIgnoreCase)) {
                [Convert]::ToUInt32($valueText.Substring(2), 16)
            }
            else {
                [Convert]::ToUInt32($valueText, 10)
            }
        } | Sort-Object -Unique)
    $expectedSorted = @($ExpectedValues | Sort-Object -Unique)
    if (($actualValues -join ',') -cne ($expectedSorted -join ',') -or
        $valueMatches.Count -ne $ExpectedValues.Count -or
        [regex]::Matches($Expression, '\|').Count -ne
            ($ExpectedValues.Count - 1) -or
        $Expression -match '&') {
        throw (
            "$Owner exact state set is '$($actualValues -join ',')', " +
            "expected '$($expectedSorted -join ',')' as one OR-only expression.")
    }
}

function Assert-Ds402HomeStorageUnavailableGuard {
    param(
        [string]$FunctionBlock,
        [int]$StateReadIndex,
        [string]$Owner
    )

    $guardMatches = [regex]::Matches(
        $FunctionBlock,
        ('(?is)(?:if|elsif)\s+(?<Expression>[^;]*' +
         'sizeof\(\s*Ds402HomeState\s*\)\s*<>\s*512[^;]*)\s+then\s*' +
         '(?<Body>.*?)(?<Boundary>\belse\b|\bend_if;)'))
    $matchingGuards = @($guardMatches | Where-Object {
            $_.Groups['Body'].Value -match '(?i)detailCode\s*:=\s*29\s*;'
        })
    if ($matchingGuards.Count -ne 1) {
        throw (
            "$Owner storage-unavailable detail 29 guard count is " +
            "$($matchingGuards.Count), expected one.")
    }
    $guard = $matchingGuards[0]
    $expression = $guard.Groups['Expression'].Value
    if ($expression -notmatch
            '(?i)CallerSessionEpoch\s*=\s*0' -or
        $expression -match '(?i)BootId' -or
        [regex]::Matches($expression, '\|').Count -ne 1 -or
        $expression -match '&' -or
        $guard.Index -ge $StateReadIndex) {
        throw (
            "$Owner must map only sizeof or zero session epoch to detail 29 " +
            'before any retained-state read; BootId belongs to detail 17.')
    }

    $guardBody = $guard.Groups['Body'].Value
    $guardBoundary = $guard.Groups['Boundary'].Value
    if ($guardBoundary -match '(?i)^end_if') {
        if ($guardBody -notmatch
                '(?i)\(pResponse\s*\+\s*12\)\^\$UDINT\s*:=\s*detailCode\s*;' -or
            $guardBody -notmatch '(?i)ResponseSize\s*:=\s*16\s*;' -or
            $guardBody -notmatch '(?i)\bRETURN\s*;') {
            throw (
                "$Owner standalone storage guard must return the detail 29 " +
                '16-byte failure envelope before any retained-state read.')
        }
        return
    }

    $elseIndex = $guard.Groups['Boundary'].Index
    if ($elseIndex -ge $StateReadIndex -or
        $FunctionBlock.Substring(
            $elseIndex,
            $StateReadIndex - $elseIndex) -match '(?i)\bend_if\s*;') {
        throw (
            "$Owner retained-state read must stay inside the else branch of " +
            'the storage-unavailable detail 29 guard.')
    }

    $failureTails = @([regex]::Matches(
            $FunctionBlock,
            '(?is)if\s+detailCode\s*<>\s*0\s+then(?<Body>.*?)end_if;') |
        Where-Object {
            $_.Index -gt $StateReadIndex -and
            $_.Groups['Body'].Value -match
                '(?i)\(pResponse\s*\+\s*12\)\^\$UDINT\s*:=\s*detailCode\s*;'
        })
    if ($failureTails.Count -ne 1) {
        throw (
            "$Owner guarded storage failure must reach exactly one common " +
            'detailCode failure envelope.')
    }
    $tail = $failureTails[0]
    $responseSizeInitialized =
        $FunctionBlock.Substring(0, $guard.Index) -match
            '(?i)ResponseSize\s*:=\s*16\s*;'
    $tailBody = $tail.Groups['Body'].Value
    $tailTerminates = $tailBody -match '(?i)\bRETURN\s*;'
    if (-not $tailTerminates) {
        $afterTail = $FunctionBlock.Substring($tail.Index + $tail.Length)
        $tailTerminates = $afterTail -match '(?is)^\s*END_FUNCTION\s*$'
    }
    if ((-not $responseSizeInitialized -and
            $tailBody -notmatch '(?i)ResponseSize\s*:=\s*16\s*;') -or
        -not $tailTerminates) {
        throw (
            "$Owner common storage failure path must preserve a 16-byte " +
            'response and terminate without reaching success serialization.')
    }
}

function Assert-LasalDs402HomeRetirementContract {
    param(
        [string]$DiagnosticsText,
        [string]$TcpText,
        [string]$ControlServiceText,
        [string]$Owner
    )

    $diagnosticsScan = Get-LasalScanText $DiagnosticsText
    $tcpScan = Get-LasalScanText $TcpText
    $controlScan = Get-LasalScanText $ControlServiceText
    $functionPatterns = [ordered]@{
        HandleRequest =
            ('(?ims)^[ \t]*FUNCTION[ \t]+GLOBAL[ \t]+' +
             'LMCDiagnosticsService::HandleRequest[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        Start =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCDiagnosticsService::HandleAxisDs402HomeStart[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        Outcome =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCDiagnosticsService::HandleAxisDs402HomeOutcome[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        Retire =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCDiagnosticsService::HandleAxisDs402HomeRetire[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        Process =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCDiagnosticsService::ProcessAxisDs402Home[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        MsgParser =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'TCPMotionInterface::MsgPaser[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
        Admin =
            ('(?ims)^[ \t]*FUNCTION[ \t]+' +
             'LMCControlCommandService::HandleAdminCommands[ \t]*\r?$' +
             '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')
    }
    $blocks = @{}
    foreach ($entry in $functionPatterns.GetEnumerator()) {
        $sourceText = if ($entry.Key -eq 'MsgParser') {
            $tcpScan
        }
        elseif ($entry.Key -eq 'Admin') {
            $controlScan
        }
        else {
            $diagnosticsScan
        }
        $matches = [regex]::Matches($sourceText, $entry.Value)
        if ($matches.Count -ne 1) {
            throw (
                "$Owner $($entry.Key) implementation count is " +
                "$($matches.Count), expected exactly one.")
        }
        $blocks[$entry.Key] = $matches[0].Value
    }
    $receiptBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'LMCDiagnosticsService::HandleAxisDs402HomeReceiptStages[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')).Value
    $cleanupBlock = [regex]::Match(
        $diagnosticsScan,
        ('(?ims)^[ \t]*FUNCTION[ \t]+' +
         'LMCDiagnosticsService::HandleAxisDs402HomeCleanupStages[ \t]*\r?$' +
         '.*?^[ \t]*END_FUNCTION[ \t]*\r?$')).Value
    $splitPresent = -not [string]::IsNullOrWhiteSpace($receiptBlock)
    if ($splitPresent -ne
        (-not [string]::IsNullOrWhiteSpace($cleanupBlock))) {
        throw "$Owner DS402 retirement split helpers must be paired."
    }
    $warmProcessBlock = $blocks.Process
    $processAndCleanupBlock = $blocks.Process
    if ($splitPresent) {
        $warmProcessBlock = $receiptBlock + "`n" + $blocks.Process
        $processAndCleanupBlock = $blocks.Process + "`n" + $cleanupBlock
    }

    # The retirement mutation fixture intentionally models only the retirement
    # surface. Full current source must also carry the durable stage88 contract.
    if ($DiagnosticsText -match
        '(?i)LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED') {
        Assert-LasalDs402HomeWarmReconcileContract `
            -StartBlock $blocks.Start `
            -ProcessBlock $warmProcessBlock `
            -Owner $Owner
    }
    Assert-LasalDs402HomePendingFreezeCleanupContract `
        -ProcessBlock $warmProcessBlock `
        -Owner $Owner
    Assert-LasalDs402HomeBoundedCleanupContract `
        -ProcessBlock $processAndCleanupBlock `
        -ExpectedExpiredFailClosedArmCount $(if ($splitPresent) { 4 } else { 1 }) `
        -Owner $Owner

    Assert-Match $blocks.Retire (
        '(?s)VAR_INPUT.*?Reference\s*:\s*UINT;.*?' +
        'pRequest\s*:\s*\^USINT;.*?pResponse\s*:\s*\^USINT;.*?' +
        'ResponseCapacity\s*:\s*UDINT;.*?' +
        'CallerSessionEpoch\s*:\s*UDINT;.*?' +
        'RequestSize\s*:\s*UDINT;.*?END_VAR\s*VAR_OUTPUT.*?' +
        'ResponseSize\s*:\s*DINT;.*?END_VAR') (
        "$Owner retire handler ABI must match the existing Start/Outcome ABI.")

    Assert-Match $blocks.HandleRequest (
        '(?s)if\s+CommandId\s*=\s*0x7D15\s+then.*?' +
        'HandleAxisDs402HomeStart\(.*?RETURN;\s*' +
        'elsif\s+CommandId\s*=\s*0x7D16\s+then.*?' +
        'HandleAxisDs402HomeOutcome\(.*?RETURN;\s*' +
        'elsif\s+CommandId\s*=\s*0x7D17\s+then\s*' +
        'ResponseSize\s*:=\s*HandleAxisDs402HomeRetire\(\s*' +
        'Reference:=Reference,\s*pRequest:=pRequest,\s*' +
        'pResponse:=pResponse,\s*ResponseCapacity:=ResponseCapacity,\s*' +
        'CallerSessionEpoch:=CallerSessionEpoch,\s*' +
        'RequestSize:=RequestSize\);\s*RETURN;') (
        "$Owner diagnostics route must expose the complete 0x7D15/16/17 triad.")
    Assert-Match $blocks.MsgParser (
        '(?s)0x7D15,\s*0x7D16,\s*0x7D17,\s*0x7E00.*?' +
        'Diagnostics\.HandleRequest\(') (
        "$Owner TCP route must delegate 0x7D15/16/17 to Diagnostics together.")
    Assert-Match $blocks.MsgParser (
        '(?s)diagnosticsDs402StartValid\s*:\s*BOOL\s*;.*?' +
        'diagnosticsDs402StartValid\s*:=\s*FALSE\s*;.*?' +
        'if\s+\(CommandID\s*=\s*0x7D15\)\s*&\s*' +
        '\(Payload\s*=\s*72\)\s*&\s*' +
        '\(diagnosticsAxisMask\s*<>\s*0\)\s+then\s*' +
        'diagnosticsDs402StartValid\s*:=\s*' +
        '\(RequestBuf\[8\]\^?\$UINT\s*=\s*1\)\s*&\s*' +
        '\(RequestBuf\[10\]\^?\$UINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[12\]\^?\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(RequestBuf\[16\]\^?\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(RequestBuf\[20\]\^?\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(RequestBuf\[24\]\^?\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(\s*\(RequestBuf\[28\]\^?\$UDINT\s*<>\s*0\)\s*\|\s*' +
        '\(RequestBuf\[32\]\^?\$UDINT\s*<>\s*0\)\s*\|\s*' +
        '\(RequestBuf\[36\]\^?\$UDINT\s*<>\s*0\)\s*\|\s*' +
        '\(RequestBuf\[40\]\^?\$UDINT\s*<>\s*0\)\s*\)\s*&\s*' +
        '\(RequestBuf\[44\]\^?\$DINT\s*=\s*37\)\s*&\s*' +
        '\(RequestBuf\[48\]\^?\$DINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[52\]\^?\$DINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[56\]\^?\$DINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[60\]\^?\$DINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[64\]\^?\$DINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[68\]\^?\$UINT\s*=\s*1\)\s*&\s*' +
        '\(RequestBuf\[70\]\^?\$UINT\s*=\s*0\)\s*&\s*' +
        '\(RequestBuf\[72\]\^?\$UDINT\s*<>\s*0\)\s*&\s*' +
        '\(RequestBuf\[76\]\^?\$UDINT\s*=\s*0x32303448\)\s*;') (
        "$Owner TCP admission mapper does not require the exact valid 0x7D15 operator topology.")
    $ds402ValidityWrites = [regex]::Matches(
        $blocks.MsgParser,
        '(?i)diagnosticsDs402StartValid\s*:=').Count
    if ($ds402ValidityWrites -ne 2) {
        throw (
            "$Owner TCP writes diagnosticsDs402StartValid " +
            "$ds402ValidityWrites times, expected exactly two.")
    }
    $ds402ValidityAssignment = [regex]::Match(
        $blocks.MsgParser,
        ('(?is)if\s+\(CommandID\s*=\s*0x7D15\).*?then\s*' +
         'diagnosticsDs402StartValid\s*:=\s*' +
         '(?<Expression>.*?);'))
    if (-not $ds402ValidityAssignment.Success -or
        [regex]::Matches(
            $ds402ValidityAssignment.Groups['Expression'].Value,
            '\|').Count -ne 3 -or
        [regex]::Matches(
            $ds402ValidityAssignment.Groups['Expression'].Value,
            '&').Count -ne 16) {
        throw (
            "$Owner TCP valid 0x7D15 expression must use exactly three " +
            'intent OR operators and sixteen admission AND operators.')
    }
    Assert-Match $blocks.MsgParser (
        ('(?s)diagnosticsDs402PreflightAttempted\s*:\s*BOOL\s*;.*?' +
         'diagnosticsDs402PreflightAccepted\s*:\s*BOOL\s*;.*?' +
         'diagnosticsDs402PreflightAttempted\s*:=\s*FALSE\s*;.*?' +
         'diagnosticsDs402PreflightAccepted\s*:=\s*FALSE\s*;.*?' +
         'if\s+diagnosticsDs402StartValid\s*&\s*' +
         'IsClientConnected\(#Diagnostics\)\s*&\s*' +
         'IsClientConnected\(#ControlCommands\)\s+then\s*' +
         'diagnosticsDs402PreflightAttempted\s*:=\s*TRUE\s*;.*?' +
         'Diagnostics\.HandleRequest\(.*?' +
         'AdmissionToken:=0\s*,\s*OwnerGeneration:=0\s*\)\s*;.*?' +
         'diagnosticsDs402PreflightAccepted\s*:=\s*' +
         'diagnosticsResponseSize\s*=\s*' +
         'LMC_DIAG_DS402_PREFLIGHT_READY\s*;')) (
        "$Owner TCP lacks the exact write-ahead DS402 Start preflight contract.")
    $diagnosticsCalls = [regex]::Matches(
        $blocks.MsgParser,
        '(?i)Diagnostics\.HandleRequest\s*\(')
    $reserveCall = [regex]::Match(
        $blocks.MsgParser,
        '(?i)ControlCommands\.ReserveAxisOwnership\s*\(')
    if ($diagnosticsCalls.Count -ne 2 -or -not $reserveCall.Success -or
        $diagnosticsCalls[0].Index -ge $reserveCall.Index -or
        $reserveCall.Index -ge $diagnosticsCalls[1].Index) {
        throw (
            "$Owner TCP DS402 order must be preflight, Reserve, then one final " +
            'Diagnostics call.')
    }
    Assert-Match $blocks.MsgParser (
        '(?s)if\s+\(diagnosticsAxisMask\s*<>\s*0\)\s*&\s*' +
        '\(\(CommandID\s*=\s*0x7E53\)\s*\|\s*' +
        '\(diagnosticsDs402StartValid\s*&\s*' +
        'diagnosticsDs402PreflightAccepted\)\)\s*&\s*' +
        'IsClientConnected\(#Diagnostics\)\s*&\s*' +
        'IsClientConnected\(#ControlCommands\)\s+then.*?' +
        'ControlCommands\.ReserveAxisOwnership\(.*?' +
        'elsif\s+diagnosticsDs402StartValid\s+then\s*' +
        'diagnosticsAdmissionResult\s*:=\s*-3') (
        "$Owner TCP admission/disconnect path is not valid-0x7D15 specific.")
    Assert-Match $blocks.MsgParser (
        '(?s)if\s+diagnosticsDs402StartValid\s*&\s*' +
        '\(diagnosticsAdmissionResult\s*<>\s*0\)\s*&\s*' +
        '\(\(diagnosticsDs402PreflightAttempted\s*=\s*FALSE\)\s*\|\s*' +
        'diagnosticsDs402PreflightAccepted\)\s+then\s*' +
        '_memset\(dest:=#Sendbuf\[8\],\s*usByte:=0,\s*cntr:=24\).*?' +
        'Sendbuf\[8\]\^?\$UINT\s*:=\s*1\s*;.*?' +
        'Sendbuf\[12\]\^?\$UINT\s*:=\s*1\s*;.*?' +
        'Sendbuf\[14\]\^?\$INT\s*:=\s*-31000\s*;.*?' +
        'Sendbuf\[16\]\^?\$UDINT\s*:=\s*RequestBuf\[12\]\^?\$UDINT\s*;.*?' +
        'if\s+diagnosticsAdmissionResult\s*=\s*-2\s+then\s*' +
        'Sendbuf\[20\]\^?\$UDINT\s*:=\s*41\s*;\s*else\s*' +
        'Sendbuf\[20\]\^?\$UDINT\s*:=\s*42\s*;\s*end_if\s*;.*?' +
        'Sendbuf\[24\]\^?\$DINT\s*:=\s*RequestBuf\[44\]\^?\$DINT\s*;.*?' +
        'Sendbuf\[28\]\^?\$UDINT\s*:=\s*0\s*;.*?' +
        'diagnosticsResponseSize\s*:=\s*24') (
        "$Owner TCP admission failure does not preserve the exact DS402 response.")
    Assert-Match $blocks.MsgParser (
        '(?s)if\s+\(\(diagnosticsDs402StartValid\s*=\s*FALSE\)\s*\|\s*' +
        '\(diagnosticsDs402PreflightAccepted\s*&\s*' +
        '\(diagnosticsAdmissionResult\s*=\s*0\)\)\)\s*&\s*' +
        'IsClientConnected\(#Diagnostics\)\s+then\s*' +
        'diagnosticsResponseSize\s*:=\s*Diagnostics\.HandleRequest\(') (
        "$Owner TCP must delegate malformed/final Start only and preserve a rejected preflight response.")
    Assert-Match $blocks.MsgParser (
        '(?s)if\s+\(CommandID\s*=\s*0x7E53\)\s*&\s*' +
        '\(Payload\s*=\s*72\)\s+then\s*' +
        'diagnosticsOwnerReference\s*:=\s*RequestBuf\[48\]\^?\$UINT\s*;\s*' +
        'diagnosticsOwnerKind\s*:=\s*5\s*;\s*' +
        'diagnosticsResourceKind\s*:=\s*4\s*;\s*' +
        'elsif\s+\(CommandID\s*=\s*0x7D15\)\s*&\s*' +
        '\(Payload\s*=\s*72\)\s+then\s*' +
        'diagnosticsOwnerReference\s*:=\s*AxisRef\^?\$UINT\s*;\s*' +
        'diagnosticsOwnerKind\s*:=\s*4\s*;\s*' +
        'diagnosticsResourceKind\s*:=\s*3') (
        "$Owner TCP must keep 0x7E53 and 0x7D15 owner classification isolated.")

    foreach ($identityBlock in @(
            @{ Name = 'Outcome'; Text = $blocks.Outcome },
            @{ Name = 'Retire'; Text = $blocks.Retire })) {
        if ([regex]::Matches(
                $identityBlock.Text,
                '(?i)currentBootId\s*:=\s*GetDiagnosticsBootId\(\s*\)\s*;').Count -ne 1) {
            throw (
                "$Owner $($identityBlock.Name) must sample current BootId " +
                'exactly once from GetDiagnosticsBootId.')
        }
        Assert-Match $identityBlock.Text (
            '(?s)if\s+\(schemaVersion\s*<>\s*1\).*?' +
            'detailCode\s*:=\s*28\s*;\s*' +
            'elsif\s+diagnosticsBuild\s*<>\s*1\s+then\s*' +
            'detailCode\s*:=\s*16\s*;\s*' +
            'elsif\s+\(currentBootId\s*=\s*0\)\s*\|\s*' +
            '\(bootId\s*<>\s*currentBootId\)\s+then\s*' +
            'detailCode\s*:=\s*17\s*;\s*' +
            'elsif\s+mapRevision\s*<>\s*LMC_DIAG_MAP_REVISION\s+then\s*' +
            'detailCode\s*:=\s*18') (
            "$Owner $($identityBlock.Name) identity detail order is not 28/16/17/18.")
    }
    Assert-Match $blocks.Outcome (
        '(?s)\(baseOutcomeState\s*=\s*1\)\s*&\s*' +
        '\(Ds402HomeState\[92\]\s*=\s*101\)\s*&\s*' +
        '\(Ds402HomeState\[93\]\s*=\s*TO_DINT\(Reference\s*-\s*1\)\).*?' +
        'detailCode\s*:=\s*26') (
        "$Owner Outcome stage-101 record must be detail 26 indeterminate.")
    Assert-Match $blocks.Outcome (
        '(?s)baseOutcomeState\s*=\s*2.*?' +
        'Ds402HomeState\[recordBase\s*\+\s*18\]\s*=\s*0.*?' +
        '0x0008\)\s*=\s*0.*?' +
        '0x2000\)\s*=\s*0.*?' +
        '0x006F\)\s*=\s*0x0040\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0021\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0023\)\s*\|\s*' +
        '.*?0x006F\)\s*=\s*0x0027') (
        "$Owner Outcome success evidence is incomplete.")
    Assert-Match $blocks.Process (
        '(?s)currentCycle\s*:=\s*Ds402HomeState\[110\]\^?\$UDINT\s*;\s*' +
        'previousCycle\s*:=\s*currentCycle\s*;.*?' +
        'newCycle\s*:=\s*currentCycle\s*<>\s*previousCycle\s*;.*?' +
        'if\s+newCycle\s+then\s*' +
        'Ds402HomeState\[110\]\s*:=\s*currentCycle\^?\$DINT') (
        "$Owner Process fresh-cycle provenance is incomplete.")
    Assert-Match $blocks.Process (
        '(?s)snapshot\[TO_DINT\(healthOffset\s*\+\s*28\)\]\^?\$UDINT\s*' +
        '<>\s*currentCycle') (
        "$Owner Process health snapshot freshness is incomplete.")
    Assert-Match $blocks.Process (
        '(?s)\(serviceNow\s*-\s*serviceStart\)\s*>=\s*timeoutMs.*?' +
        '32\s*:.*?Ds402HomeState\[112\]\s*:=\s*currentCycle\^?\$DINT.*?' +
        '33\s*:.*?Ds402HomeState\[112\]\s*:=\s*currentCycle\^?\$DINT.*?' +
        '34\s*:.*?if\s+newCycle\s*&\s*' +
        '\(currentCycle\s*<>\s*Ds402HomeState\[112\]\^?\$UDINT\)\s+then.*?' +
        'Ds402HomeState\[94\]\s*<>\s*0.*?' +
        'Ds402HomeState\[113\]\s*<>\s*0.*?' +
        'Ds402HomeState\[116\]\s*<>\s*0.*?' +
        'Ds402HomeState\[117\]\s*<>\s*0.*?' +
        'Ds402HomeState\[127\]\s*<>\s*0.*?' +
        'statusWord\s+and\s+0x0008.*?' +
        'statusWord\s+and\s+0x2000.*?' +
        'baseState\s*<>\s*0x0040.*?' +
        'baseState\s*<>\s*0x0021.*?' +
        'baseState\s*<>\s*0x0023.*?' +
        'baseState\s*<>\s*0x0027.*?' +
        'actualPosition\s*<>\s*0') (
        "$Owner Process final success lacks fresh post-release evidence.")
    $stage34Prefix = (
        '(?s)34\s*:.*?if\s+newCycle\s*&.*?then\s*' +
        'if\s+\(Ds402HomeState\[94\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[113\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[116\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[117\]\s*<>\s*0\)\s*\|\s*' +
        '\(Ds402HomeState\[127\]\s*<>\s*0\)\s*\|')
    if ($DiagnosticsText -match
        '(?i)LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED') {
        Assert-Match $blocks.Process (
            $stage34Prefix + '.*?Ds402HomeState\[106\]\s*:=\s*2.*?' +
            'ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
            'Ds402HomeState\[125\]\s*:=\s*2.*?' +
            'ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
            'Ds402HomeState\[92\]\s*:=\s*LMC_DIAG_DS402_STAGE_FINALIZE') (
            "$Owner Process stage 34 lacks durable exact terminal success.")
    }
    else {
        Assert-Match $blocks.Process (
            $stage34Prefix + '.*?' +
            'ReportKind\s*:=\s*LMC_DIAG_OWNER_REPORT_TERMINAL_SUCCESS.*?' +
            'if\s+ownerResult\s*=\s*0\s+then.*?' +
            'Ds402HomeState\[recordBase\]\s*:=\s*2\s*;\s*' +
            'Ds402HomeState\[92\]\s*:=\s*0') (
            "$Owner legacy fixture stage 34 terminal success is incomplete.")
    }
    $cleanupBoundaryCount = [regex]::Matches(
        $processAndCleanupBlock,
        '(?i)\(serviceNow\s*-\s*cleanupStart\)\s*>=\s*1000').Count
    if ($cleanupBoundaryCount -ne 1) {
        throw (
            "$Owner Process has $cleanupBoundaryCount inclusive cleanup " +
            'boundaries, expected one common stage 90..99 boundary.')
    }

    $capabilityCase = [regex]::Match(
        $blocks.Admin,
        ('(?ims)^[ \t]*0x7D00[ \t]*:[ \t]*\r?$' +
         '(?<Body>.*?)(?=^[ \t]*0x7D10[ \t]*:[ \t]*\r?$)'))
    if (-not $capabilityCase.Success) {
        throw "$Owner 0x7D00 capability case was not found exactly once."
    }
    $featureWrites = [regex]::Matches(
        $capabilityCase.Groups['Body'].Value,
        ('(?i)\(pResponseFrame\s*\+\s*24\)\^\$UDINT\s*:=\s*' +
         '(?<Value>0x[0-9A-F]+)\s*;'))
    $catalogWrites = [regex]::Matches(
        $capabilityCase.Groups['Body'].Value,
        ('(?i)\(pResponseFrame\s*\+\s*44\)\^\$UINT\s*:=\s*' +
         '(?<Value>[0-9]+)\s*;'))
    if ($featureWrites.Count -ne 1 -or $catalogWrites.Count -ne 1) {
        throw (
            "$Owner Admin FeatureBits and ErrorCatalogVersion must each be " +
            'written exactly once as static values.')
    }
    $featureBits = [Convert]::ToUInt32(
        $featureWrites[0].Groups['Value'].Value.Substring(2), 16)
    $errorCatalogVersion = [Convert]::ToUInt32(
        $catalogWrites[0].Groups['Value'].Value, 10)
    $homeGateMatches = [regex]::Matches(
        $diagnosticsScan,
        ('(?im)^[ \t]*#define[ \t]+LMC_DIAG_DS402_HOME_ENABLED[ \t]+' +
         '(?<Value>TRUE|FALSE)[ \t]*\r?$'))
    if ($homeGateMatches.Count -ne 1) {
        throw "$Owner DS402 Home gate must be defined exactly once."
    }
    $homeGateEnabled =
        $homeGateMatches[0].Groups['Value'].Value -ceq 'TRUE'
    $adminBitEnabled = ($featureBits -band 0x00000040) -ne 0
    if ($homeGateEnabled -ne $adminBitEnabled) {
        throw (
            "$Owner Admin bit 6 must change atomically with the DS402 Home " +
            'gate and complete 0x7D15/16/17 triad.')
    }
    if ($adminBitEnabled -and $errorCatalogVersion -lt 4) {
        throw (
            "$Owner Admin bit 6 requires ErrorCatalogVersion >= 4 for " +
            'details 25..32.')
    }

    $startStateDecode = [regex]::Match(
        $blocks.Start,
        ('(?is)(?<Raw>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*' +
         'Ds402HomeState\[\s*recordBase\s*\]\^?\$UDINT\s*;\s*' +
         '(?<Base>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*\k<Raw>\s+and\s+' +
         '0x0*7FFF\s*;'))
    if (-not $startStateDecode.Success) {
        throw "$Owner Start must decode the full raw DINT and masked base state."
    }
    $startRaw = $startStateDecode.Groups['Raw'].Value
    $startBase = $startStateDecode.Groups['Base'].Value
    $startSafeRead = [regex]::Match(
        $blocks.Start,
        ('(?is)if\s+\(\s*Reference\s*>=\s*1\s*\)\s*&\s*' +
         '\(\s*Reference\s*<=\s*4\s*\)\s+then.*?' +
         [regex]::Escape($startStateDecode.Value) + '.*?end_if;'))
    if (-not $startSafeRead.Success) {
        throw (
            "$Owner Start must range-guard recordBase before reading the " +
            'per-axis retained slot.')
    }
    $slotOccupiedBranch = [regex]::Match(
        $blocks.Start,
        ('(?is)(?:if|elsif)\s+(?<Expression>[^;]*' +
         [regex]::Escape($startRaw) + '[^;]*)\s+then\s*' +
         'detailCode\s*:=\s*32;'))
    if (-not $slotOccupiedBranch.Success) {
        throw "$Owner Start terminal-slot detail 32 branch is missing."
    }
    Get-Ds402HomeExactStateSet `
        -Expression $slotOccupiedBranch.Groups['Expression'].Value `
        -StateName $startRaw `
        -ExpectedValues @(2, 3, 4) `
        -Owner "$Owner Start unretired terminal"
    $replaceableGuard = [regex]::Match(
        $blocks.Start,
        ('(?is)(?:if|elsif)\s+(?<Expression>[^;]*' +
         [regex]::Escape($startRaw) + '[^;]*0x0*8002[^;]*)\s+then\s*' +
         'detailCode\s*:=\s*10;'))
    if (-not $replaceableGuard.Success) {
        throw "$Owner Start exact tombstone replacement guard is missing."
    }
    $excludedMatches = [regex]::Matches(
        $replaceableGuard.Groups['Expression'].Value,
        ('(?i)(?<![A-Za-z0-9_])' + [regex]::Escape($startRaw) +
         '\s*<>\s*(?<Value>0x[0-9A-F]+|[0-9]+)'))
    $excludedValues = @($excludedMatches | ForEach-Object {
            $valueText = $_.Groups['Value'].Value
            if ($valueText.StartsWith('0x', [StringComparison]::OrdinalIgnoreCase)) {
                [Convert]::ToUInt32($valueText.Substring(2), 16)
            }
            else {
                [Convert]::ToUInt32($valueText, 10)
            }
        } | Sort-Object -Unique)
    if (($excludedValues -join ',') -cne '0,32770,32771,32772' -or
        $excludedMatches.Count -ne 4 -or
        [regex]::Matches(
            $replaceableGuard.Groups['Expression'].Value,
            '&').Count -ne 3 -or
        $replaceableGuard.Groups['Expression'].Value -match '\|' -or
        $slotOccupiedBranch.Index -ge $replaceableGuard.Index) {
        throw (
            "$Owner Start must block raw 2/3/4 first, then admit only empty " +
            'or exact 0x8002/3/4 tombstones for replacement.')
    }
    if ($DiagnosticsText -match
        '(?i)LMC_DIAG_DS402_STAGE_RESERVE_INTENT') {
        Assert-Match $blocks.Start (
            '(?s)if\s+preflightOnly\s+then.*?' +
            '\(rawStartState\s*<>\s*0\).*?' +
            '\(rawStartState\s*<>\s*0x00008002\).*?' +
            '\(rawStartState\s*<>\s*0x00008003\).*?' +
            '\(rawStartState\s*<>\s*0x00008004\).*?' +
            'Ds402HomeState\[115\]\s*:=\s*rawStartState\$DINT\s*;.*?' +
            'LMC_DIAG_DS402_STAGE_RESERVE_INTENT') (
            "$Owner preflight must preserve a permitted tombstone in the " +
            'durable stage87 intent.')
        $preflightRetirement = [regex]::Match(
            $blocks.Start,
            ('(?is)if\s+preflightOnly\s+then\s*' +
             '(?<Body>.*?)ResponseSize\s*:=\s*' +
             'LMC_DIAG_DS402_PREFLIGHT_READY'))
        if (-not $preflightRetirement.Success -or
            $preflightRetirement.Groups['Body'].Value -match
                '(?i)_memset\(dest:=#Ds402HomeState\[recordBase\]') {
            throw "$Owner stage87 preflight must not consume the prior tombstone."
        }
    }
    elseif ($DiagnosticsText -match
        '(?i)LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED') {
        Assert-Match $blocks.Start (
            '(?s)journalEligible\s*:=.*?' +
            '\(rawStartState\s*=\s*0\).*?' +
            '\(rawStartState\s*=\s*0x00008002\).*?' +
            '\(rawStartState\s*=\s*0x00008003\).*?' +
            '\(rawStartState\s*=\s*0x00008004\).*?' +
            'if\s+journalEligible\s+then.*?' +
            '_memset\(dest:=#Ds402HomeState\[recordBase\].*?' +
            'Ds402HomeState\[recordBase\]\s*:=\s*1;.*?' +
            'LMC_DIAG_DS402_STAGE_ROLLBACK_PREPARED') (
            "$Owner Start must overwrite a permitted tombstone only after " +
            'exact RESERVED journal admission.')
    }
    else {
        Assert-Match $blocks.Start (
            '(?s)if\s+detailCode\s*=\s*0\s+then.*?' +
            '_memset\(dest:=#Ds402HomeState\[recordBase\].*?' +
            'Ds402HomeState\[recordBase\]\s*:=\s*1;') (
            "$Owner legacy fixture tombstone admission guard is incomplete.")
    }
    if ($startRaw -ceq $startBase) {
        throw "$Owner Start raw and base state locals must be distinct."
    }

    $outcomeStateDecode = [regex]::Match(
        $blocks.Outcome,
        ('(?is)(?<Raw>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*' +
         'Ds402HomeState\[\s*recordBase\s*\]\^?\$UDINT\s*;\s*' +
         '(?<Base>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*\k<Raw>\s+and\s+' +
         '0x0*7FFF\s*;'))
    if (-not $outcomeStateDecode.Success) {
        throw "$Owner Outcome must decode the full raw DINT and masked base state."
    }
    $outcomeRaw = $outcomeStateDecode.Groups['Raw'].Value
    $outcomeBase = $outcomeStateDecode.Groups['Base'].Value
    $outcomeRangeGuard = [regex]::Match(
        $blocks.Outcome,
        ('(?is)if\s+[^;]*\(\s*Reference\s*<\s*1\s*\)\s*\|\s*' +
         '\(\s*Reference\s*>\s*4\s*\)[^;]*then.*?' +
         'RETURN;.*?end_if;'))
    if (-not $outcomeRangeGuard.Success -or
        $outcomeRangeGuard.Index -ge $outcomeStateDecode.Index) {
        throw (
            "$Owner Outcome must reject an invalid axis before reading the " +
            'per-axis retained slot.')
    }
    Assert-Ds402HomeStorageUnavailableGuard `
        -FunctionBlock $blocks.Outcome `
        -StateReadIndex $outcomeStateDecode.Index `
        -Owner "$Owner Outcome"
    $outcomeValidity = [regex]::Match(
        $blocks.Outcome,
        ('(?is)(?<Valid>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*' +
         '(?<Expression>[^;]*' + [regex]::Escape($outcomeRaw) +
         '[^;]*\|[^;]*);'))
    if (-not $outcomeValidity.Success) {
        throw "$Owner Outcome exact raw-state validity expression is missing."
    }
    Get-Ds402HomeExactStateSet `
        -Expression $outcomeValidity.Groups['Expression'].Value `
        -StateName $outcomeRaw `
        -ExpectedValues @(1, 2, 3, 4, 0x8002, 0x8003, 0x8004) `
        -Owner "$Owner Outcome"
    Assert-Match $blocks.Outcome (
        '(?s)' + [regex]::Escape($outcomeRaw) + '\s*=\s*0.*?' +
        'detailCode\s*:=\s*25;.*?' +
        [regex]::Escape($outcomeValidity.Groups['Valid'].Value) +
        '\s*=\s*FALSE.*?detailCode\s*:=\s*27;') (
        "$Owner Outcome must distinguish empty detail 25 from corrupt detail 27.")
    $outcomeStateWrites = [regex]::Matches(
        $blocks.Outcome,
        ('(?i)\(pResponse\s*\+\s*16\)\^\$UINT\s*:=\s*' +
         '(?<Value>[A-Za-z_][A-Za-z0-9_]*)(?:\s*\$UINT)?\s*;'))
    if ($outcomeStateWrites.Count -ne 1 -or
        $outcomeStateWrites[0].Groups['Value'].Value -cne $outcomeBase) {
        throw (
            "$Owner Outcome P16 must serialize exactly one masked base state, " +
            'never the raw tombstone.')
    }
    if ($blocks.Outcome -match
            '(?i)Ds402HomeState\[[^\]]+\]\s*:=' -or
        $blocks.Outcome -match
            '(?i)_(?:memset|memcpy)\s*\([^;]*Ds402HomeState') {
        throw "$Owner Outcome query must remain side-effect free."
    }

    Assert-Match $blocks.Retire (
        '(?s)ResponseSize\s*:=\s*-1;.*?ResponseCapacity\s*<\s*16.*?' +
        '_memset\(dest:=pResponse,\s*usByte:=0,\s*cntr:=ResponseCapacity\).*?' +
        'pResponse\^\$UINT\s*:=\s*LMC_DIAG_SCHEMA_VERSION;.*?' +
        '\(pResponse\s*\+\s*4\)\^\$UINT\s*:=\s*1;.*?' +
        '\(pResponse\s*\+\s*6\)\^\$INT\s*:=\s*LMC_DIAG_ADMIN_ERROR_ID;.*?' +
        '\(pResponse\s*\+\s*8\)\^\$UDINT\s*:=\s*requestId;.*?' +
        'ResponseSize\s*:=\s*16;') (
        "$Owner Retire must begin with the exact fail-closed 16-byte envelope.")
    Assert-Match $blocks.Retire (
        '(?s)RequestSize\s*<>\s*48.*?' +
        '\(Reference\s*<\s*1\).*?\(Reference\s*>\s*4\).*?RETURN;.*?' +
        'schemaVersion\s*:=\s*pRequest\^\$UINT;.*?' +
        'requestFlags\s*:=\s*\(pRequest\s*\+\s*2\)\^\$UINT;.*?' +
        'requestId\s*:=\s*\(pRequest\s*\+\s*4\)\^\$UDINT;.*?' +
        'diagnosticsBuild\s*:=\s*\(pRequest\s*\+\s*8\)\^\$UDINT;.*?' +
        'bootId\s*:=\s*\(pRequest\s*\+\s*12\)\^\$UDINT;.*?' +
        'mapRevision\s*:=\s*\(pRequest\s*\+\s*16\)\^\$UDINT;.*?' +
        'originalRequestId\s*:=\s*\(pRequest\s*\+\s*20\)\^\$UDINT;.*?' +
        'intent0\s*:=\s*\(pRequest\s*\+\s*24\)\^\$UDINT;.*?' +
        'intent1\s*:=\s*\(pRequest\s*\+\s*28\)\^\$UDINT;.*?' +
        'intent2\s*:=\s*\(pRequest\s*\+\s*32\)\^\$UDINT;.*?' +
        'intent3\s*:=\s*\(pRequest\s*\+\s*36\)\^\$UDINT;.*?' +
        'homingMethod\s*:=\s*\(pRequest\s*\+\s*40\)\^\$DINT;.*?' +
        'recordGeneration\s*:=\s*\(pRequest\s*\+\s*44\)\^\$UDINT;') (
        "$Owner Retire exact 48-byte request offsets are incomplete.")

    $retireStateDecode = [regex]::Match(
        $blocks.Retire,
        ('(?is)(?<Raw>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*' +
         'Ds402HomeState\[\s*recordBase\s*\]\^?\$UDINT\s*;\s*' +
         '(?<Base>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*\k<Raw>\s+and\s+' +
         '0x0*7FFF\s*;'))
    if (-not $retireStateDecode.Success) {
        throw "$Owner Retire must decode the full raw DINT and masked base state."
    }
    $retireRaw = $retireStateDecode.Groups['Raw'].Value
    $retireBase = $retireStateDecode.Groups['Base'].Value
    Assert-Ds402HomeStorageUnavailableGuard `
        -FunctionBlock $blocks.Retire `
        -StateReadIndex $retireStateDecode.Index `
        -Owner "$Owner Retire"
    $retireValidity = [regex]::Match(
        $blocks.Retire,
        ('(?is)(?<Valid>[A-Za-z_][A-Za-z0-9_]*)\s*:=\s*' +
         '(?<Expression>[^;]*' + [regex]::Escape($retireRaw) +
         '[^;]*\|[^;]*);'))
    if (-not $retireValidity.Success) {
        throw "$Owner Retire exact terminal-state validity expression is missing."
    }
    Get-Ds402HomeExactStateSet `
        -Expression $retireValidity.Groups['Expression'].Value `
        -StateName $retireRaw `
        -ExpectedValues @(2, 3, 4, 0x8002, 0x8003, 0x8004) `
        -Owner "$Owner Retire"

    Assert-Match $blocks.Retire (
        '(?s)\(Ds402HomeState\[recordBase\s*\+\s*1\]\^?\$UDINT\s*<>\s*' +
        'diagnosticsBuild\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*2\]\^?\$UDINT\s*<>\s*bootId\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*3\]\^?\$UDINT\s*<>\s*' +
        'mapRevision\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*4\]\^?\$UDINT\s*<>\s*' +
        'originalRequestId\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*5\]\^?\$UDINT\s*<>\s*intent0\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*6\]\^?\$UDINT\s*<>\s*intent1\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*7\]\^?\$UDINT\s*<>\s*intent2\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*8\]\^?\$UDINT\s*<>\s*intent3\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*9\]\s*<>\s*homingMethod\).*?' +
        '\(Ds402HomeState\[recordBase\s*\+\s*22\]\^?\$UDINT\s*<>\s*' +
        'recordGeneration\).*?detailCode\s*:=\s*28;') (
        "$Owner Retire must bind the exact identity and nonzero generation.")
    Assert-Match $blocks.Retire (
        '(?s)' + [regex]::Escape($retireRaw) + '\s*=\s*0.*?' +
        'detailCode\s*:=\s*25;.*?' + [regex]::Escape($retireRaw) +
        '\s*=\s*1.*?detailCode\s*:=\s*26;.*?' +
        [regex]::Escape($retireValidity.Groups['Valid'].Value) +
        '\s*=\s*FALSE.*?detailCode\s*:=\s*27;') (
        "$Owner Retire must reject missing, running, and corrupt states as " +
        'details 25, 26, and 27.')
    if ($blocks.Retire -match '(?i)detailCode\s*:=\s*32') {
        throw "$Owner Retire must never emit Start-only detail 32."
    }

    $outcomeCall = [regex]::Match(
        $blocks.Retire,
        ('(?is)if\s+detailCode\s*=\s*0\s+then\s*' +
         'ResponseSize\s*:=\s*HandleAxisDs402HomeOutcome\(\s*' +
         'Reference:=Reference,\s*pRequest:=pRequest,\s*' +
         'pResponse:=pResponse,\s*ResponseCapacity:=ResponseCapacity,\s*' +
         'CallerSessionEpoch:=CallerSessionEpoch,\s*RequestSize:=44\);'))
    $terminalResponseCheck = [regex]::Match(
        $blocks.Retire,
        '(?is)if\s+ResponseSize\s*<>\s*92\s+then\s*RETURN;\s*end_if;')
    $generationEchoCheck = [regex]::Match(
        $blocks.Retire,
        ('(?is)\(pResponse\s*\+\s*88\)\^\$UDINT\s*<>\s*' +
         'recordGeneration.*?detailCode\s*:=\s*28;\s*end_if;'))
    $markerWritePattern = (
        '(?is)if\s+detailCode\s*=\s*0\s+then\s*if\s+' +
        [regex]::Escape($retireRaw) + '\s*=\s*' +
        [regex]::Escape($retireBase) + '\s+then\s*' +
        'Ds402HomeState\[recordBase\]\s*:=\s*TO_DINT\(\s*' +
        [regex]::Escape($retireBase) + '\s+or\s+0x0*8000\s*\);\s*end_if;')
    $markerWrite = [regex]::Match($blocks.Retire, $markerWritePattern)
    if (-not $outcomeCall.Success -or -not $terminalResponseCheck.Success -or
        -not $generationEchoCheck.Success -or -not $markerWrite.Success -or
        $outcomeCall.Index -ge $terminalResponseCheck.Index -or
        $terminalResponseCheck.Index -ge $generationEchoCheck.Index -or
        $generationEchoCheck.Index -ge $markerWrite.Index) {
        throw (
            "$Owner Retire must reuse 0x7D16 with RequestSize 44, require a " +
            '92-byte exact-generation response, then mark only the first retire.')
    }
    $recordWrites = [regex]::Matches(
        $blocks.Retire,
        '(?i)Ds402HomeState\[[^\]]+\]\s*:=').Count
    if ($recordWrites -ne 1 -or
        $blocks.Retire -match
            '(?i)_(?:memset|memcpy)\s*\([^;]*Ds402HomeState') {
        throw (
            "$Owner Retire writes $recordWrites record fields; it may update " +
            'only +0 and must preserve the 92-byte tombstone snapshot.')
    }
    Assert-Match $blocks.Retire (
        '(?s)if\s+detailCode\s*<>\s*0\s+then.*?' +
        '\(pResponse\s*\+\s*4\)\^\$UINT\s*:=\s*1;.*?' +
        '\(pResponse\s*\+\s*6\)\^\$INT\s*:=\s*LMC_DIAG_ADMIN_ERROR_ID;.*?' +
        '\(pResponse\s*\+\s*12\)\^\$UDINT\s*:=\s*detailCode;.*?' +
        'ResponseSize\s*:=\s*16;') (
        "$Owner Retire domain failures must collapse to the 16-byte envelope.")
}

