    $negativeFixtures['SubmitCancelClearTarget'] = ([regex]::new(
        '(?is)(sigclib_atomic_setU32\s*\(\s*pValue\s*:=\s*#)' +
        'AxisZeroHomeCancelSequence(?=\s*,\s*value\s*:=\s*0\s*\))')).Replace(
