            $fixture,
            '${1}AxisZeroHomeAppliedSequence',
            1)
    $negativeFixtures['AppliedPublishTarget'] = ([regex]::new(
        '(?is)(sigclib_atomic_setU32\s*\(\s*pValue\s*:=\s*#)' +
