if ($AxisOwnershipReserveVerifierSelfTestOnly) {
    $reserveRoot = (Resolve-Path -LiteralPath $RepositoryRoot).Path
    $reserveControlPath = Join-Path $reserveRoot (
        'Lasal_PRG\Elmo_EtherCAT_Test_4Axis\Class\' +
        'LMCControlCommandService\LMCControlCommandService.st')
    $reserveControl = Get-Content -Raw -LiteralPath $reserveControlPath
    $reserveScan = Get-LasalLexicalScanText $reserveControl
    $reservePublishMatches = [regex]::Matches(
        $reserveScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::PublishAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    $reserveMatches = [regex]::Matches(
        $reserveScan,
        ('(?ims)^\s*FUNCTION\s+GLOBAL\s+' +
         'LMCControlCommandService::ReserveAxisOwnership\s*$' +
         '.*?^\s*END_FUNCTION\s*$'))
    if (($reservePublishMatches.Count -ne 1) -or
        ($reserveMatches.Count -ne 1)) {
        throw (
            'Current LMCControlCommandService reserve shared closure or ' +
            'implementation count drifted.')
    }
    $null = Assert-LasalAxisOwnershipPublishStateContract `
        -ControlServiceText $reserveControl `
        -Owner 'Current LMCControlCommandService reserve'
    Assert-LasalAxisOwnershipReserveMutationFences `
        -ReserveBlock $reserveMatches[0].Value `
        -ControlServiceText $reserveControl `
        -Owner 'Current LMCControlCommandService reserve' `
        -SharedControlClosureAlreadyChecked
    $reserveNegativeFixtureCount =
        Invoke-LasalAxisOwnershipReserveVerifierSelfTest `
            -ControlServiceText $reserveControl `
            -Owner 'Current LMCControlCommandService reserve'
    Write-Host (
        'PASS LASAL.AxisOwnershipReserveVerifier.SelfTest (' +
        "$reserveNegativeFixtureCount/" +
        "$reserveNegativeFixtureCount negative fixtures rejected; " +
        'comment-only fixture accepted)')
    return
}

