$controlServiceClassBlock = [regex]::Match(
    $controlCommandService,
    '(?s)LMCControlCommandService\s*:\s*CLASS.*?END_CLASS;').Value
if ([string]::IsNullOrWhiteSpace($controlServiceClassBlock)) {
    throw 'LMCControlCommandService generated class declaration was not found.'
}
$controlServiceMetadataBlock = [regex]::Match(
    $controlCommandService,
    '(?s)<Class\s+.*?Name\s*=\s*"LMCControlCommandService".*?</Class>').Value
if ([string]::IsNullOrWhiteSpace($controlServiceMetadataBlock)) {
    throw 'LMCControlCommandService generated class metadata was not found.'
}
$axisRebaseDeclarations = [regex]::Matches(
    $controlServiceClassBlock,
    '(?m)^\s*AxisRebaseRequiredState\s*:\s*SvrCh_UDINT\s*;\s*$')
$axisRebaseAnyDeclarations = [regex]::Matches(
    $controlServiceClassBlock,
    '(?m)^\s*AxisRebaseRequiredState\s*:\s*[^;]+;\s*$')
$axisRebaseMetadataEntries = [regex]::Matches(
    $controlServiceMetadataBlock,
    '<Server\s+Name="AxisRebaseRequiredState"[^>]*/>')
$axisRebaseDeclarationPresent = $axisRebaseDeclarations.Count -eq 1
if ($axisRebaseDeclarationPresent) {
    if ($axisRebaseAnyDeclarations.Count -ne 1 -or
        $axisRebaseMetadataEntries.Count -ne 1) {
        throw (
            'LMCControlCommandService.AxisRebaseRequiredState generated ' +
            'declaration/metadata count is not exactly one.')
    }
    $axisRebaseMetadata = $axisRebaseMetadataEntries[0].Value
    foreach ($attribute in @(
            'Visualized="false"',
            'Initialize="true"',
            'WriteProtected="false"',
            'Retentive="File"')) {
        Assert-Match $axisRebaseMetadata ([regex]::Escape($attribute)) (
            'LMCControlCommandService.AxisRebaseRequiredState metadata must ' +
            "contain exact $attribute.")
    }
    $axisRebaseDefValueAttributes = [regex]::Matches(
        $axisRebaseMetadata,
        '(?i)\bDefValue="(?<Value>[^"]*)"')
    if ($axisRebaseDefValueAttributes.Count -ne 1 -or
        $axisRebaseDefValueAttributes[0].Groups['Value'].Value -notmatch
            '(?i)^(?:0x|16#)5242530F$') {
        throw (
            'LMCControlCommandService.AxisRebaseRequiredState metadata must ' +
            'contain the exact UDINT DefValue 0x5242530F using the LASAL ' +
            '0x or 16# hexadecimal prefix.')
    }
}
else {
    if ($axisRebaseAnyDeclarations.Count -ne 0 -or
        $axisRebaseMetadataEntries.Count -ne 0) {
        throw (
            'LMCControlCommandService.AxisRebaseRequiredState generated ' +
            'declaration and metadata are inconsistent.')
    }
    if (-not $AllowPendingAxisRebaseRequiredStateDeclaration) {
        throw (
            'LMCControlCommandService hidden server ' +
            'AxisRebaseRequiredState:SvrCh_UDINT is missing. Add the exact ' +
            'retained IDE declaration or use ' +
            '-AllowPendingAxisRebaseRequiredStateDeclaration only for ' +
            'pre-IDE source staging.')
    }
}

foreach ($classProperty in @(
    @{ Name = 'RealtimeTask'; Value = 'false' },
    @{ Name = 'CyclicTask'; Value = 'false' },
    @{ Name = 'BackgroundTask'; Value = 'false' },
    @{ Name = 'Automatic'; Value = 'false' },
    @{ Name = 'SharedCommandTable'; Value = 'true' })) {
    Assert-Match $controlCommandService (
        [regex]::Escape($classProperty.Name) +
        '\s*=\s*"' + [regex]::Escape($classProperty.Value) + '"') (
        "LMCControlCommandService.$($classProperty.Name) must be $($classProperty.Value).")
}

Assert-Match $controlServiceClassBlock '(?m)^\s*ClassSvr\s*:\s*SvrChCmd_DINT\s*;\s*$' 'LMCControlCommandService.ClassSvr command server declaration is missing.'
foreach ($axisNumber in 1..9) {
    $axisClientName = "LMCAxis$axisNumber"
    Assert-Match $controlServiceClassBlock (
        '(?m)^\s*' + [regex]::Escape($axisClientName) +
        '\s*:\s*CltChCmd__LMCAxis\s*;\s*$') (
        "LMCControlCommandService.$axisClientName must be an _LMCAxis object command client.")
    Assert-Match $controlServiceMetadataBlock (
        '<Client\s+Name="' + [regex]::Escape($axisClientName) +
        '"\s+Required="true"\s+Internal="false"\s*/>') (
        "LMCControlCommandService.$axisClientName must be generated as a required external client.")
}
Assert-Match $controlServiceClassBlock '(?m)^\s*LMCRobot\s*:\s*CltChCmd__LMCRobotBase\s*;\s*$' 'LMCControlCommandService.LMCRobot must be an _LMCRobotBase object command client.'
Assert-Match $controlServiceMetadataBlock '<Client\s+Name="LMCRobot"\s+Required="true"\s+Internal="false"\s*/>' 'LMCControlCommandService.LMCRobot must be generated as a required external client.'
Assert-Match $controlServiceClassBlock '(?m)^\s*InputLatch\s*:\s*CltChCmd_LMCEcatInputLatch\s*;\s*$' 'LMCControlCommandService.InputLatch must be an LMCEcatInputLatch object command client.'
Assert-Match $controlServiceMetadataBlock '<Client\s+Name="InputLatch"\s+Required="true"\s+Internal="false"\s*/>' 'LMCControlCommandService.InputLatch must be generated as a required external client.'
$controlServiceMetadataClients = [regex]::Matches(
    $controlServiceMetadataBlock,
    '<Client\s+Name="[^"]+"[^>]*/>')
if ($controlServiceMetadataClients.Count -ne 11) {
    throw "LMCControlCommandService metadata client count is $($controlServiceMetadataClients.Count), expected eleven."
}

$controlServiceTableBlock = [regex]::Match(
    $controlCommandService,
    '(?s)FUNCTION GLOBAL TAB LMCControlCommandService::@CT_.*?END_FUNCTION').Value
if ([string]::IsNullOrWhiteSpace($controlServiceTableBlock)) {
    throw 'LMCControlCommandService generated command table was not found.'
}
$expectedControlServiceServerCount = if ($axisRebaseDeclarationPresent) { 2 } else { 1 }
Assert-Match $controlServiceTableBlock (
    '(?m)^\s*' + $expectedControlServiceServerCount +
    '\$UINT,\s*11\$UINT,\s*0\$UINT,\s*$') (
    'LMCControlCommandService generated server/client/data counts are not ' +
    "exactly $expectedControlServiceServerCount/11/0.")

$controlServiceServerEntries = [regex]::Matches(
    $controlServiceTableBlock,
    '\(::LMCControlCommandService\.[A-Za-z_][A-Za-z0-9_]*\.pMeth\)\$UINT')
if ($controlServiceServerEntries.Count -ne $expectedControlServiceServerCount) {
    throw (
        'LMCControlCommandService generated server entry count is ' +
        "$($controlServiceServerEntries.Count), expected " +
        "$expectedControlServiceServerCount.")
}
Assert-Match $controlServiceTableBlock '(?m)^\s*\(::LMCControlCommandService\.ClassSvr\.pMeth\)\$UINT,\s*_CH_CMD\$UINT,.*"ClassSvr"' 'LMCControlCommandService.ClassSvr generated metadata is missing.'
if ($axisRebaseDeclarationPresent) {
    Assert-Match $controlServiceTableBlock (
        '(?m)^\s*\(::LMCControlCommandService\.' +
        'AxisRebaseRequiredState\.pMeth\)\$UINT,\s*_CH_SVR\$UINT,\s*' +
        '2#0000000000011000\$UINT,.*"AxisRebaseRequiredState"') (
        'LMCControlCommandService.AxisRebaseRequiredState generated retained ' +
        'server entry is missing or has wrong flags.')
}
elseif ($controlServiceTableBlock -match
        '(?<![A-Za-z0-9_])AxisRebaseRequiredState(?![A-Za-z0-9_])') {
    throw (
        'LMCControlCommandService generated command table contains stale ' +
        'AxisRebaseRequiredState metadata without its declaration.')
}

$controlServiceClientLines = [regex]::Matches(
    $controlServiceTableBlock,
    '(?m)^\s*\(::LMCControlCommandService\.(?<Name>[A-Za-z_][A-Za-z0-9_]*)\.pCh\)\$UINT.*$')
if ($controlServiceClientLines.Count -ne 11) {
    throw "LMCControlCommandService generated client entry count is $($controlServiceClientLines.Count), expected eleven."
}
foreach ($clientLine in $controlServiceClientLines) {
    if ($clientLine.Value -notmatch
        '_CH_CLT_OBJ\$UINT,\s*2#0000000000000010\$UINT') {
        throw ("LMCControlCommandService.$($clientLine.Groups['Name'].Value) " +
            'is not generated as a required object client.')
    }
}
if ($controlServiceTableBlock -match '_CH_CLT\$UINT') {
    throw 'LMCControlCommandService contains a generated scalar client entry.'
}
foreach ($axisNumber in 1..9) {
    $axisClientName = "LMCAxis$axisNumber"
    Assert-Match $controlServiceTableBlock (
        '(?m)^\s*\(::LMCControlCommandService\.' +
        [regex]::Escape($axisClientName) +
        '\.pCh\)\$UINT,\s*_CH_CLT_OBJ\$UINT,\s*' +
        '2#0000000000000010\$UINT,.*"' +
        [regex]::Escape($axisClientName) + '".*"_LMCAxis"') (
        "LMCControlCommandService.$axisClientName generated object-client metadata is missing.")
}
Assert-Match $controlServiceTableBlock '(?m)^\s*\(::LMCControlCommandService\.LMCRobot\.pCh\)\$UINT,\s*_CH_CLT_OBJ\$UINT,\s*2#0000000000000010\$UINT,.*"LMCRobot".*"_LMCRobotBase"' 'LMCControlCommandService.LMCRobot required object-client metadata is missing.'
Assert-Match $controlServiceTableBlock '(?m)^\s*\(::LMCControlCommandService\.InputLatch\.pCh\)\$UINT,\s*_CH_CLT_OBJ\$UINT,\s*2#0000000000000010\$UINT,.*"InputLatch".*"LMCEcatInputLatch"' 'LMCControlCommandService.InputLatch required object-client metadata is missing.'

$controlServicePragmas = [regex]::Matches(
    $controlCommandService,
    '(?m)^\s*#pragma usingLtd\s+(?<Class>[A-Za-z_][A-Za-z0-9_]*)\s*$')
if ($controlServicePragmas.Count -ne 3 -or
    @($controlServicePragmas | Where-Object {
            $_.Groups['Class'].Value -eq '_LMCAxis' }).Count -ne 1 -or
    @($controlServicePragmas | Where-Object {
            $_.Groups['Class'].Value -eq '_LMCRobotBase' }).Count -ne 1 -or
    @($controlServicePragmas | Where-Object {
            $_.Groups['Class'].Value -eq 'LMCEcatInputLatch' }).Count -ne 1) {
    throw 'LMCControlCommandService must have exactly the _LMCAxis, _LMCRobotBase, and LMCEcatInputLatch limited-using pragmas.'
}
if ($controlCommandService -match '(?:#pragma usingLtd\s+_StdLib|\b_StdLib\b)') {
    throw 'LMCControlCommandService must not depend on an _StdLib client.'
}

$controlServiceRequestInputs = @(
    @{ Name = 'CommandId'; Type = 'UINT' },
    @{ Name = 'Reference'; Type = 'UINT' },
    @{ Name = 'pRequestFrame'; Type = '^USINT' },
    @{ Name = 'RequestFrameSize'; Type = 'UDINT' },
    @{ Name = 'pResponseFrame'; Type = '^USINT' },
    @{ Name = 'ResponseCapacity'; Type = 'UDINT' })
$controlServiceHandleRequestInputs = @(
    $controlServiceRequestInputs +
    @(
        @{ Name = 'CallerSessionEpoch'; Type = 'UDINT' },
        @{ Name = 'RequestSequence'; Type = 'UDINT' },
        @{ Name = 'AdmissionToken'; Type = 'UDINT' },
        @{ Name = 'OwnerGeneration'; Type = 'UDINT' }))
$controlServiceResponseOutput = @(
    @{ Name = 'ResponseSize'; Type = 'DINT' })

Assert-ExactLasalFunctionAbi `
    -ClassBlock $controlServiceClassBlock `
    -FunctionName 'HandleRequest' `
    -IsGlobal $true `
    -Inputs $controlServiceHandleRequestInputs `
    -Outputs $controlServiceResponseOutput

$ownershipResultOutput = @(@{ Name = 'Result'; Type = 'DINT' })
$controlServiceOwnershipAbiContracts = @(
    @{
        Name = 'ReserveAxisOwnership'
        Inputs = @(
            @{ Name = 'CommandId'; Type = 'UINT' },
            @{ Name = 'Reference'; Type = 'UINT' },
            @{ Name = 'RequestedAxisMask'; Type = 'UDINT' },
            @{ Name = 'OwnerKind'; Type = 'UINT' },
            @{ Name = 'ResourceKind'; Type = 'UINT' },
            @{ Name = 'AdmissionMode'; Type = 'UINT' },
            @{ Name = 'CallerSessionEpoch'; Type = 'UDINT' },
            @{ Name = 'RequestSequence'; Type = 'UDINT' },
            @{ Name = 'pIdentity'; Type = '^void' },
            @{ Name = 'IdentitySize'; Type = 'UDINT' },
            @{ Name = 'pEffectiveAxisMask'; Type = '^UDINT' },
            @{ Name = 'pAdmissionToken'; Type = '^UDINT' },
            @{ Name = 'pOwnerGeneration'; Type = '^UDINT' })
