            @{ Name = 'CommandId'; Type = 'UINT' },
            @{ Name = 'Reference'; Type = 'UINT' },
            @{ Name = 'ExpectedAxisMask'; Type = 'UDINT' },
            @{ Name = 'OwnerKind'; Type = 'UINT' },
            @{ Name = 'ResourceKind'; Type = 'UINT' },
            @{ Name = 'AdmissionMode'; Type = 'UINT' },
            @{ Name = 'CallerSessionEpoch'; Type = 'UDINT' },
            @{ Name = 'RequestSequence'; Type = 'UDINT' },
            @{ Name = 'AdmissionToken'; Type = 'UDINT' },
