    @{ Name = 'ProcessAxisOwnership'; Inputs = @(); Outputs = @() },
    @{ Name = 'ProcessAxisZeroHome'; Inputs = @(); Outputs = @() })
foreach ($ownershipAbi in $controlServiceOwnershipAbiContracts) {
    Assert-ExactLasalFunctionAbi `
        -ClassBlock $controlServiceClassBlock `
        -FunctionName $ownershipAbi.Name `
        -IsGlobal $true `
        -Inputs $ownershipAbi.Inputs `
