                [regex]::Matches(
                    $outputWriteCaseScanText,
                    $outputWriteParsedLocal.Pattern).Count -ne 1 -or
                [regex]::Matches(
                    $outputWriteParseGuardThenArmScanText,
                    $outputWriteParsedLocal.Pattern).Count -ne 1) {
