$ds402SafetyDrainRetryNegativeFixtureCount = 0
foreach ($fixtureName in $ds402SafetyDrainRetryNegativeFixtures.Keys) {
    $fixture = $ds402SafetyDrainRetryNegativeFixtures[$fixtureName]
    if (($fixture.Control -ceq $controlCommandService) -and
        ($fixture.Tcp -ceq $st)) {
        throw (
            "DS402 safety-drain retry negative fixture '$fixtureName' " +
            'did not mutate either source.')
    }
    $negativeRejected = $false
    try {
        Assert-LasalDs402SafetyDrainRetryContract -ControlServiceText $fixture.Control -TcpText $fixture.Tcp -Owner "DS402 safety-drain retry negative fixture '$fixtureName'"
    }
    catch {
        $negativeRejected = $true
    }
    if (-not $negativeRejected) {
        throw (
            "DS402 safety-drain retry verifier accepted negative fixture " +
            "'$fixtureName'.")
    }
    $ds402SafetyDrainRetryNegativeFixtureCount++
}
if ($ds402SafetyDrainRetryNegativeFixtureCount -ne 25) {
    throw (
        'DS402 safety-drain retry negative fixture count is ' +
        "$ds402SafetyDrainRetryNegativeFixtureCount, expected 25.")
