Assert-Match $st 'PendingClosedSessionEpoch\s*:\s*UDINT' 'TCPMotionInterface pending closed-session epoch storage is missing.'
Assert-Match $motionCyWorkBlock '(?s)PendingClosedSessionEpoch <> 0.*?IsClientConnected\(#Diagnostics\).*?Diagnostics\.NotifySessionClosed\(\s*SessionEpoch:=PendingClosedSessionEpoch\).*?PendingClosedSessionEpoch := 0.*?currentEpoch := SessionEpoch' 'TCPMotionInterface.CyWork does not flush the pending closed epoch to LMCDiagnosticsService before processing requests.'
$closedEpochCaptureCount = [regex]::Matches(
    $st,
    '(?s)if \(SessionEpoch <> 0\)\s*&\s*\(PendingClosedSessionEpoch = 0\) then\s*PendingClosedSessionEpoch := SessionEpoch;\s*end_if;\s*SessionEpoch \+= 1').Count
if ($closedEpochCaptureCount -ne 3) {
    throw "TCPMotionInterface first-wins closed-session capture count is $closedEpochCaptureCount, expected three disconnect/send/close paths."
}
Assert-Match $motionCyWorkBlock '(?s)RequestQueue\[QueueReadIndex\$DINT\]\.State\s*=\s*TCPMI_QUEUE_READY.*?State\s*:=\s*TCPMI_QUEUE_ACTIVE.*?MemCpy.*?State\s*:=\s*TCPMI_QUEUE_FREE' 'CyWork queue READY/ACTIVE/FREE transition is missing.'
Assert-Match $motionCyWorkBlock '(?s)CommandID\s*:=\s*TO_DINT\(ActiveRequest\.CommandId\);.*?AxisRef\s*:=\s*TO_DINT\(ActiveRequest\.Reference\);.*?Payload\s*:=\s*TO_DINT\(ActiveRequest\.PayloadLength\);.*?MsgPaser\(\);.*?ActiveRequestValid\s*:=\s*FALSE' 'CyWork does not numerically widen, execute, and release one active request.'
Assert-Match $motionCyWorkBlock '(?s)ControlCommands\.ProcessAxisOwnership\(\);.*?if IsClientConnected\(#Diagnostics\) then\s*Diagnostics\.ProcessOperations\(\);\s*end_if.*?if \(PendingClosedSessionEpoch = 0\) & \(ActiveRequestValid = FALSE\) then.*?MsgPaser\(\);' 'TCPMotionInterface.CyWork must finish retained diagnostics receipts before admitting and dispatching a new request.'
if ([regex]::Matches(
        $motionCyWorkBlock,
        '(?i)Diagnostics\.ProcessOperations\(\)').Count -ne 1) {
    throw 'TCPMotionInterface.CyWork must invoke Diagnostics.ProcessOperations exactly once per scan.'
}
if ($motionCyWorkBlock -match 'ActiveRequest\.(?:CommandId|Reference|PayloadLength)\$DINT') {
    throw 'CyWork reinterprets a 16-bit request field as a 32-bit DINT instead of using numeric conversion.'
}

$msgParserCallCount = [regex]::Matches($st, '(?m)^\s*MsgPaser\(\);\s*$').Count
if ($msgParserCallCount -ne 1) {
    throw "MsgPaser call count is $msgParserCallCount, expected one CyWork caller."
}

Assert-Match $responseBlock '(?s)State\s*=\s*TCPMI_QUEUE_FREE.*?State\s*:=\s*TCPMI_QUEUE_WRITING.*?State\s*:=\s*TCPMI_QUEUE_READY' 'Response queue FREE/WRITING/READY transition is missing.'

$sendDataBlock = [regex]::Match(
    $st,
    '(?s)FUNCTION VIRTUAL GLOBAL TCPMotionInterface::SendData.*?END_FUNCTION').Value
Assert-Match $sendDataBlock '_TCPIPServerInterface::SendData' 'TCPMotionInterface.SendData base call is missing.'
Assert-Match $sendDataBlock 'if dRetcode <> udSize\$DINT then' 'Partial/failed send check is missing.'
Assert-Match $sendDataBlock 'IngressFaultCloseRequired\s*:=\s*TRUE' 'Partial send quarantine is missing.'
Assert-Match $sendDataBlock 'SessionEpoch\s*\+=\s*1' 'Partial send does not invalidate the session epoch.'
Assert-Match $st 'vmt\.UserFcts\[2\]\s*:=\s*#SendData\(\)' 'TCPMotionInterface.SendData override is not registered.'

if ($st -match '(?m)^\s*0x208[1-4]\s*:') {
    throw 'Legacy 0x2081..0x2084 handler is active.'
}

$upperBitMappings = [regex]::Matches($st, 'AxisCommandState\$UDINT\s+and\s+0xFFFF0000').Count
if ($transportClean) {
    if ($upperBitMappings -ne 0 -or
        $st -match '(?<![A-Za-z0-9_])AxisObjectName[1-9](?![A-Za-z0-9_])' -or
        $st -match '(?<![A-Za-z0-9_])AxisCommandInputValid(?![A-Za-z0-9_])') {
        throw 'Phase5TransportClean TCPMotionInterface still contains legacy axis-domain implementation state.'
    }
}
else {
    if ($upperBitMappings -ne 4) {
        throw "32-bit axis error truncation guards=$upperBitMappings, expected 4."
    }
    Assert-Match $st 'AxisObjectName1\s*:\s*ARRAY \[0\.\.255\] OF CHAR' 'LASAL object-name buffer is not 256 bytes.'
    if ($st -match 'AxisObjectName[5-9]\s*:\s*ARRAY') {
        throw 'Axes 5..9 must reuse an IDE-registered object-name buffer instead of adding CodeGenerator-only class variables.'
    }
    Assert-Match $st '(?s)AxisCommandInputValid\s*:=.*?\(dir = 2\).*?\(bufMode = 1\).*?\(Exec = 1\)' 'Shortest-only axis direction validation is missing.'
    Assert-Match $st '(?s)\(dec = 0\).*?\(Exec = 1\)' 'MoveVelocity deceleration/execute validation is missing.'
}
Assert-Match $protocol 'WriteInt32\(buffer, HeaderSize, reference\);\s*WriteInt32\(buffer, HeaderSize \+ 4, 1\);' 'C# read-status descriptor payload is missing.'
Assert-Match $protocol 'WriteInt32\(buffer, HeaderSize \+ 64, velocity\);' 'C# group velocity offset is not 64 bytes into payload.'
Assert-Match $protocol 'WriteInt32\(\s*buffer,\s*HeaderSize \+ 92,\s*options\.Execute \? 1 : 0\s*\);' 'C# group execute option is not serialized at payload offset 92.'
Assert-Match $protocol '(?s)StartAxisHome\s*=\s*0x7D13.*?ReadAxisHomeOutcome\s*=\s*0x7D18.*?RetireAxisHomeOutcome\s*=\s*0x7D19' 'C# protocol does not reserve the complete LMC_Home triad.'
Assert-Match $protocol '(?s)StartEncoderMaintenance\s*=\s*0x7E53.*?ReadEncoderMaintenanceOutcome\s*=\s*0x7E54.*?RetireEncoderMaintenanceOutcome\s*=\s*0x7E55' 'C# protocol does not reserve the complete encoder-maintenance triad.'
Assert-Match $adminHomeProtocol '(?s)StartLmcHomeRequestPayloadLength\s*=\s*56.*?LmcHomeOutcomeRequestPayloadLength\s*=\s*56.*?LmcHomeRetirementRequestPayloadLength\s*=\s*60.*?LmcHomeOutcomeResponsePayloadLength\s*=\s*144' 'C# LMC_Home request/outcome sizes drifted.'
Assert-Match $adminHomeProtocol (
    '(?s)(?=.*?semanticOffset\s*=\s*isOutcomeRequest\s*\?\s*44\s*:\s*36)' +
    '(?=.*?payloadOffset \+ semanticOffset.*?SemanticMode)' +
    '(?=.*?payloadOffset \+ semanticOffset \+ 4.*?ExpectedActualPosition)' +
    '(?=.*?payloadOffset \+ semanticOffset \+ 8,\s*0\))' +
    '(?=.*?payloadOffset \+ 48.*?TimeoutMilliseconds)' +
    '(?=.*?payloadOffset \+ 52.*?LmcHomeExecuteTokenValue)') (
    'C# LMC_Home current-position-zero offsets drifted.')
Assert-Match $adminHomeProtocol '(?s)response\.DetailCode\s*==\s*LMCAdminDetailCode\.NativeCommandRejected.*?throw\s+new\s+InvalidDataException' 'C# LMC_Home parser does not explicitly reject forbidden detail 11.'
if ($adminHomeProtocol -match '(?i)MoveReference|ReferenceSwitch|SearchVelocity|BackoffVelocity') {
    throw 'C# LMC_Home protocol contains a retired switch-search field or backend name.'
}
$adminFailureDetailNumberPattern = (
    '(?s)InvalidState\s*=\s*10.*?' +
    'NativeCommandRejected\s*=\s*11.*?' +
    'ActiveAxisError\s*=\s*13.*?' +
    'CoordinatePreconditionFailed\s*=\s*15.*?' +
    'DiagnosticsBuildMismatch\s*=\s*16.*?' +
    'BootIdMismatch\s*=\s*17.*?' +
    'MapRevisionMismatch\s*=\s*18.*?' +
    'Ds402HomeOutcomeNotFound\s*=\s*25.*?' +
    'Ds402HomeOutcomeStorageUnavailable\s*=\s*29.*?' +
    'LmcHomeOutcomeNotFound\s*=\s*33.*?' +
    'LmcHomeOutcomeStorageUnavailable\s*=\s*37.*?' +
    'LmcHomeOutcomeSlotOccupied\s*=\s*40.*?' +
    'AxisOwnershipConflict\s*=\s*41.*?' +
    'AxisOwnershipQuarantined\s*=\s*42')
Assert-Match $adminModels $adminFailureDetailNumberPattern 'C# Admin Home failure detail numbers drifted.'

$lmcHomeStartFailureBlock = [regex]::Match(
    $adminProtocol,
    '(?s)if\s*\(\s*allowLmcHomeStartFailureDetails\b.*?return\s+errorId\s*==\s*AdminErrorId\s*;\s*\}').Value
$lmcHomeOutcomeFailureBlock = [regex]::Match(
    $adminProtocol,
    '(?s)if\s*\(\s*allowLmcHomeOutcomeFailureDetails\b.*?return\s+errorId\s*==\s*AdminErrorId\s*;\s*\}').Value
$ds402HomeOutcomeFailureBlock = [regex]::Match(
    $adminProtocol,
    '(?s)if\s*\(\s*allowDs402HomeOutcomeFailureDetails\b.*?return\s+errorId\s*==\s*AdminErrorId\s*;\s*\}').Value
if ([string]::IsNullOrWhiteSpace($lmcHomeStartFailureBlock) -or
    [string]::IsNullOrWhiteSpace($lmcHomeOutcomeFailureBlock) -or
    [string]::IsNullOrWhiteSpace($ds402HomeOutcomeFailureBlock)) {
    throw 'C# Home command-specific failure allow-list branch is missing.'
}

$expectedLmcHomeStartFailureNames = @(
    'ActiveAxisError',
    'AxisOwnershipConflict',
    'AxisOwnershipQuarantined',
    'CoordinatePreconditionFailed',
    'DiagnosticsBuildMismatch',
    'InvalidState',
    'LmcHomeOutcomeSlotOccupied',
    'MapRevisionMismatch')
$actualLmcHomeStartFailureNames = @(
    [regex]::Matches(
        $lmcHomeStartFailureBlock,
        'LMCAdminDetailCode\s*\.\s*(?<Name>[A-Za-z0-9_]+)') |
        ForEach-Object { $_.Groups['Name'].Value } |
        Sort-Object -Unique)
if (@(Compare-Object `
            -ReferenceObject $expectedLmcHomeStartFailureNames `
            -DifferenceObject $actualLmcHomeStartFailureNames).Count -ne 0 -or
    $lmcHomeStartFailureBlock -match 'NativeCommandRejected') {
    throw ('C# LMC_Home Start failure allow-list must be exact details ' +
        '10/13/15/16/17/18/40/41/42 and must reject detail 11.')
}

foreach ($homeOutcomeFailureContract in @(
        @{
            Name = 'LMC_Home Outcome/Retire'
            Block = $lmcHomeOutcomeFailureBlock
            Expected = @(
                'DiagnosticsBuildMismatch',
                'LmcHomeOutcomeNotFound',
                'LmcHomeOutcomeStorageUnavailable',
                'MapRevisionMismatch')
        },
        @{
            Name = 'DS402 Home Outcome/Retire'
            Block = $ds402HomeOutcomeFailureBlock
            Expected = @(
                'DiagnosticsBuildMismatch',
                'Ds402HomeOutcomeNotFound',
                'Ds402HomeOutcomeStorageUnavailable',
                'MapRevisionMismatch')
        })) {
    $actualOutcomeFailureNames = @(
        [regex]::Matches(
            $homeOutcomeFailureContract.Block,
            'LMCAdminDetailCode\s*\.\s*(?<Name>[A-Za-z0-9_]+)') |
            ForEach-Object { $_.Groups['Name'].Value } |
            Sort-Object -Unique)
    if (@(Compare-Object `
                -ReferenceObject $homeOutcomeFailureContract.Expected `
                -DifferenceObject $actualOutcomeFailureNames).Count -ne 0) {
        throw ($homeOutcomeFailureContract.Name +
            ' failure allow-list must include only identity 16/17/18 and its exact outcome range.')
    }
}
Assert-Match $adminDs402HomeProtocol '(?s)homingMethod.*?CurrentPositionZeroHomingMethod.*?position.*?CurrentPositionZeroHomeOffset.*?velocity\s*!=\s*0.*?acceleration\s*!=\s*0.*?distanceLimit\s*!=\s*0.*?torqueLimit\s*!=\s*0.*?bufferMode\s*!=\s*LMCDs402HomeBufferMode\.Aborting' 'C# DS402 Home does not fail closed outside method 37/offset zero/no-motion inputs.'
Assert-Match $encoderMaintenanceProtocol '(?s)StartEncoderMaintenanceCommandId\s*=\s*0x7E53.*?ReadEncoderMaintenanceOutcomeCommandId\s*=\s*0x7E54.*?RetireEncoderMaintenanceOutcomeCommandId\s*=\s*0x7E55.*?StartEncoderMaintenanceRequestPayloadLength\s*=\s*72.*?RetireEncoderMaintenanceOutcomeRequestPayloadLength\s*=\s*76.*?EncoderMaintenanceOutcomeResponsePayloadLength\s*=\s*156' 'C# encoder-maintenance IDs or sizes drifted.'
Assert-Match $encoderMaintenanceModels '(?s)ResetCommandValue\s*=\s*1.*?CommandValue.*?ResetCommandValue' 'C# maintenance model does not pin the reset command value to one.'
Assert-Match $encoderMaintenanceProtocol '(?s)payloadOffset \+ 42.*?FeedbackSocket.*?payloadOffset \+ 44.*?CommandValue.*?CommandValue\s*!=\s*LMCEncoderMaintenanceSdoContract\.ResetCommandValue' 'C# maintenance wire/recovery contract does not pin the write value to one.'
Assert-CSharpEncoderMaintenanceTimeoutContract `
    -ProtocolText $encoderMaintenanceProtocol `
    -ModelsText $encoderMaintenanceModels `
    -Owner 'C# encoder-maintenance timeout contract'
if (($encoderMaintenanceProtocol + "`n" + $encoderMaintenanceModels) -match '(?i)0x3204') {
    throw 'C# encoder-maintenance contract contains the forbidden TW[] LONG alias.'
}

$binaryMetadataResult = if ($transportClean -and
    $AllowStaleLasalBinaryMetadata) {
    '; LASAL binary metadata explicitly bypassed'
}
else {
    ''
}
if ($SourceOnly) {
    Write-Host (
        "PASS LASAL.StaticContract.SourceOnly ($ControlServiceCheckpoint; " +
        "TopologyIoCheckpoint=$TopologyIoCheckpoint; " +
        'common axis ownership, Admin reads, dormant 0x7D12, LMC_Home 0x7D13/18/19, ' +
        'DS402 method-37 0x7D15/16/17, encoder maintenance 0x7E53/54/55, CyWork queue, ' +
        'control-service checkpoint, diagnostics D1-D5, recorder bank, ' +
        'and session-close wiring' + $binaryMetadataResult + ')')
}
else {
    Write-Host (
        "PASS LASAL.StaticContract ($ControlServiceCheckpoint; " +
        "TopologyIoCheckpoint=$TopologyIoCheckpoint; " +
        'common axis ownership, Admin reads, dormant 0x7D12, LMC_Home 0x7D13/18/19, ' +
        'DS402 method-37 0x7D15/16/17, encoder maintenance 0x7E53/54/55, CyWork queue, ' +
        'control-service checkpoint, diagnostics D1-D5, nine-axis network, ' +
        'recorder wiring, and generated metadata/tables' +
        $binaryMetadataResult + ')')
}
